BRIDGE_SOURCE_LOADED_AT = time.time()


def _bridge_source_info():
    """Expose source freshness so a live IDE cannot hide a stale bridge copy."""
    path = _text(globals().get("__file__") or "") if "_text" in globals() else ""
    try:
        stat = os.stat(path)
        return {"path": path, "mtime": stat.st_mtime, "loadedAt": BRIDGE_SOURCE_LOADED_AT}
    except Exception:
        return {"path": path or None, "mtime": None, "loadedAt": BRIDGE_SOURCE_LOADED_AT}
