class OperationError(Exception):
    """A request error with a stable code and structured recovery data."""

    def __init__(self, message, code="handler_error", data=None):
        Exception.__init__(self, message)
        self.code = code
        self.data = data or {}


def _decode_bytes(value):
    """Decode IronPython byte strings without losing vendor UI text."""
    for encoding in ("utf-8", "cp1252", "latin-1"):
        try:
            return value.decode(encoding)
        except Exception:
            continue
    return repr(value)


def _python_unicode(value):
    """Copy a CLR-backed string into a real Python unicode value.

    IronPython maps ``System.String`` to ``unicode``, but its JSON encoder can
    still try the current Windows code page when the value retains its CLR
    backing.  Building a new value from code points removes that backing while
    preserving the characters. The bridge emits UTF-8 JSON so the vendor's
    ASCII encoder never coerces mixed Unicode and Latin-1 source into bytes.
    """
    try:
        return u"".join(unichr(ord(ch)) for ch in value)
    except Exception:
        try:
            return value.encode("utf-8").decode("utf-8")
        except Exception:
            return value


def _json_safe(value):
    if value is None or isinstance(value, bool):
        return value
    # IronPython 2 can return CLR strings as byte ``str`` values using the
    # system code page. Passing those bytes directly to json.dumps makes the
    # entire response fail with UnicodeDecodeError. Preserve genuine Unicode
    # before trying the byte decoder. Never rewrite units or program text.
    try:
        if isinstance(value, unicode):
            return _python_unicode(value)
    except NameError:
        if isinstance(value, bytes):
            return _decode_bytes(value)
        if isinstance(value, str):
            return value
    try:
        if isinstance(value, str):
            try:
                return _decode_bytes(value)
            except AttributeError:
                return value
    except NameError:
        pass
    if isinstance(value, (int, float)):
        return value
    try:
        if isinstance(value, long):
            return int(value)
    except NameError:
        pass
    if isinstance(value, dict):
        return dict((_text(k), _json_safe(v)) for k, v in value.items())
    if isinstance(value, (list, tuple)):
        return [_json_safe(v) for v in value]
    try:
        # A CLR value can stringify to an IronPython byte ``str`` that still
        # contains the vendor profile's single-byte text (for example the
        # micro sign in an EtherNet/IP timing unit).  Returning that byte
        # string directly lets json.dumps try an implicit ASCII decode and
        # abort the entire response.  Feed the rendered value through the
        # primitive branches once more so byte strings are decoded by
        # _decode_bytes before they reach the JSON encoder.
        return _json_safe(_text(value))
    except Exception:
        try:
            return _json_safe(repr(value))
        except Exception:
            return "<unserializable>"


def _write_json(path, payload):
    parent = os.path.dirname(path)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent)
    temp_path = path + ".tmp"
    # CODESYS' IronPython encoder treats CLR Unicode as str. Its ASCII mode
    # decodes the entire string when ANY Latin-1 glyph (e.g. squared units)
    # occurs, breaking Chinese text. UTF-8 output preserves every character.
    raw = json.dumps(_json_safe(payload), ensure_ascii=False).encode("utf-8")
    with open(temp_path, "wb") as output:
        output.write(raw)
    if os.path.exists(path):
        os.remove(path)
    os.rename(temp_path, path)


def _json_serialization_failure_path(value, path="$", depth=0):
    """Locate the first response value that the IronPython encoder rejects.

    The diagnostic deliberately contains only ASCII field names, indices and
    exception repr text so it remains writable from the serialization fallback
    that called it.
    """
    try:
        json.dumps(_json_safe(value), ensure_ascii=False).encode("utf-8")
        return None
    except Exception as exc:
        if depth < 32 and isinstance(value, dict):
            for key, child in value.items():
                child_path = path + "." + _text(key)
                failure = _json_serialization_failure_path(
                    child, child_path, depth + 1)
                if failure is not None:
                    return failure
        elif depth < 32 and isinstance(value, (list, tuple)):
            for index, child in enumerate(value):
                failure = _json_serialization_failure_path(
                    child, path + "[" + str(index) + "]", depth + 1)
                if failure is not None:
                    return failure
        try:
            type_name = type(value).__name__
        except Exception:
            type_name = "unknown"
        try:
            is_unicode = isinstance(value, unicode)
        except Exception:
            is_unicode = False
        try:
            is_str = isinstance(value, str)
        except Exception:
            is_str = False
        try:
            value_repr = repr(value)
        except Exception:
            value_repr = "<repr failed>"
        return {"path": path, "type": type_name, "error": repr(exc),
                "isUnicode": bool(is_unicode), "isStr": bool(is_str),
                "hasDecode": bool(hasattr(value, "decode")),
                "repr": value_repr}


def respond(req_id, payload):
    try:
        if globals().get("_BOUNDED_EXECUTOR_SCOPE", False):
            globals()["_BOUNDED_RESULT_JSON"] = json.dumps(
                _json_safe(payload), ensure_ascii=False)
        else:
            _write_json(os.path.join(RES_DIR, req_id + ".json"), payload)
    except Exception as exc:
        # Never leave the host waiting when a CLR value cannot be serialized.
        # Keep the fallback deliberately small so it cannot trigger the same
        # conversion failure a second time.
        failure_path = _json_serialization_failure_path(payload)
        fallback = {
            "protocolVersion": PROTOCOL_VERSION,
            "requestId": _text(req_id),
            "ok": False,
            "status": "error",
            "op": _text(payload.get("op") if isinstance(payload, dict) else ""),
            "cmd": _text(payload.get("cmd") if isinstance(payload, dict) else ""),
            "stage": "response",
            "data": {"serializationFailure": failure_path},
            "error": "response serialization failed: " + repr(exc),
            "errorCode": "response_serialization_failed",
            "issues": [],
        }
        try:
            if globals().get("_BOUNDED_EXECUTOR_SCOPE", False):
                globals()["_BOUNDED_RESULT_JSON"] = json.dumps(
                    _json_safe(fallback), ensure_ascii=False)
            else:
                path = os.path.join(RES_DIR, req_id + ".json")
                _write_json(path, fallback)
        except Exception:
            pass


def ok(req_id, cmd, data=None, issues=None):
    gate = globals().get("write_success_issues")
    gate_issues = gate(cmd, data) if gate is not None else []
    if gate_issues:
        # Fail closed (never claim success the contract cannot prove) but say
        # WHAT to do next: the mutation may already be in the project, so the
        # caller needs a readback instruction rather than a bare refusal.
        payload = data if isinstance(data, dict) else {"detail": data}
        if not payload.get("next"):
            codes = [issue.get("code") if isinstance(issue, dict) else _text(issue)
                     for issue in gate_issues]
            actuals = [issue.get("actual") if isinstance(issue, dict) else None
                       for issue in gate_issues]
            needs_reopen = any(value == "committed_pending_reopen_readback"
                               for value in actuals if value)
            step = ("save the project, close and REOPEN it, then read the "
                    "affected object back - the gate only failed because a "
                    "same-process readback cannot prove persistence"
                    if needs_reopen else
                    "re-read the affected object (project tree / device tree / "
                    "rack module count) before retrying")
            payload["next"] = {
                "then": "the write gate could not prove every success "
                        "condition; " + step + ", and report the unresolved "
                        "gate instead of claiming success",
                "readbackTools": ["inoproshop_project_tree",
                                  "inoproshop_device_tree",
                                  "codesys_project_tree"],
                "saveAndReopenRequired": bool(needs_reopen),
                "failedGates": codes[:10],
            }
        payload.setdefault("mutatedProject", True)
        return fail(
            req_id, cmd,
            "writer returned without proving every required success gate",
            stage="verify", issues=gate_issues,
            data=payload,
            error_code="write_success_unproven",
        )
    respond(req_id, {
        "protocolVersion": PROTOCOL_VERSION,
        "requestId": req_id,
        "ok": True,
        "status": "ok",
        "op": cmd,
        "cmd": cmd,
        "stage": "done",
        "data": data if data is not None else {},
        "issues": issues or [],
    })


def fail(req_id, cmd, error, stage="error", issues=None, data=None,
         error_code="handler_error"):
    respond(req_id, {
        "protocolVersion": PROTOCOL_VERSION,
        "requestId": req_id,
        "ok": False,
        "status": "error",
        "op": cmd,
        "cmd": cmd,
        "stage": stage,
        "data": data if data is not None else {},
        "error": error,
        "errorCode": error_code,
        "issues": issues or [],
    })


def _write_heartbeat(state, operation=None, started_at=None, force=False):
    global last_heartbeat_at, last_heartbeat_state, last_heartbeat_operation
    now = time.time()
    if (not force and state == last_heartbeat_state and
            operation == last_heartbeat_operation and
            now - last_heartbeat_at < 2.0):
        return
    try:
        payload = {
            "protocolVersion": PROTOCOL_VERSION,
            "mode": BRIDGE_MODE,
            "pid": os.getpid() if hasattr(os, "getpid") else None,
            "time": now,
            "state": state,
            "operation": operation,
            "operationStartedAt": started_at,
            # Effective runtime identity (2026-09-08 CODESYS probe: settles
            # which env values actually reached the resident bridge).
            "profile": PROFILE,
            "templatesDir": TEMPLATES_DIR,
        }
        if globals().get("_BOUNDED_EXECUTOR_SCOPE", False):
            # Executed fires before the vendor progress callback's Finish().
            # Only the outer host may publish after ExecuteSource returns.
            globals()["_BOUNDED_HEARTBEAT_JSON"] = json.dumps(
                _json_safe(payload), ensure_ascii=False)
        else:
            _write_json(HEARTBEAT_FILE, payload)
        last_heartbeat_at = now
        last_heartbeat_state = state
        last_heartbeat_operation = operation
    except Exception:
        # Keep the host from misreading a dead bridge: heartbeat write
        # failures must not be silently swallowed forever.  One missed
        # write is tolerated, but the next call will retry because the
        # in-memory debounce state was not advanced.
        pass


def _discover_primary_project():
    """Recover the IDE primary project when a one-shot bridge is restarted."""
    global project, native_core_project
    candidates = []
    primary = _get_member(projects, "primary", "get_primary")
    if primary is not None:
        candidates.append(primary)
    if not candidates:
        opened = _get_member(projects, "all", "get_all", [])
        try:
            opened = list(opened)
        except Exception:
            opened = []
        candidates = [item for item in opened if bool(
            _get_member(item, "primary", "get_primary", False)
        )]
    if candidates:
        project = candidates[0]
        native_core_project = _native_primary_project_for_current_path()
        pou_cache.clear()


def _text(value):
    if value is None:
        return ""
    try:
        return unicode(value)
    except NameError:
        if isinstance(value, bytes):
            return _decode_bytes(value)
        return str(value)
    except UnicodeDecodeError:
        return _decode_bytes(value)


def _is_callable(value):
    """Avoid IronPython's callable() deprecation diagnostic in the IDE."""
    return value is not None and hasattr(value, "__call__")


def _is_native_object_in_use_error(exc):
    """Recognize InoProShop's stale native-object lock exception.

    The vendor boundary is inconsistent about how it renders this error:
    IronPython may expose the Chinese text through ``str`` or ``args``, while
    a CLR exception's ``repr`` can contain the literal ``\\uXXXX`` escapes.
    Some wrappers put the original exception in ``Message`` or
    ``InnerException``.  Collect all of those representations defensively and
    classify only the known lock phrases.  This helper must never hide the
    original exception by raising while inspecting it.
    """
    pieces = []
    seen = set()

    def collect(value, depth=0):
        if value is None or depth > 4:
            return
        try:
            marker = id(value)
            if marker in seen:
                return
            seen.add(marker)
        except Exception:
            marker = None

        # _text() handles IronPython byte/unicode conversion; the explicit
        # str/repr calls cover objects whose __unicode__ is opaque but whose
        # repr carries the vendor message.
        for converter in (_text, str, repr):
            try:
                rendered = converter(value)
            except Exception:
                continue
            try:
                rendered = _text(rendered)
            except Exception:
                continue
            if rendered:
                try:
                    if len(rendered) > 4096:
                        rendered = rendered[:4096]
                except Exception:
                    pass
                if rendered not in pieces:
                    pieces.append(rendered)

        # Python exceptions expose args; CLR/IronPython wrappers commonly use
        # Message and InnerException.  Attribute access is deliberately
        # bounded and guarded because vendor proxy properties may throw.
        try:
            args = getattr(value, "args")
        except Exception:
            args = None
        if args is not None and args is not value:
            try:
                try:
                    is_string = isinstance(args, basestring)
                except NameError:
                    is_string = isinstance(args, (str, bytes))
                items = (args,) if is_string else tuple(args)
            except Exception:
                items = (args,)
            for item in items:
                collect(item, depth + 1)

        for attribute in (
                "Message", "message", "InnerException", "inner_exception",
                "__cause__", "__context__"):
            try:
                child = getattr(value, attribute)
            except Exception:
                continue
            if child is None or child is value:
                continue
            # Message is normally a property, but a few wrappers expose a
            # zero-argument getter.  Calling only these known names avoids
            # invoking arbitrary vendor methods while still reaching text.
            if attribute in ("Message", "message") and hasattr(child, "__call__"):
                try:
                    child = child()
                except Exception:
                    continue
            collect(child, depth + 1)

    collect(exc)
    text = "\n".join(pieces)
    lowered = text.lower()
    compact = re.sub(r"\s+", "", lowered)

    # The first two forms are the exact InoProShop message and its common
    # translated spelling.  Matching the escaped representation is necessary
    # when repr(StandardError(...)) crosses the JSON/IPC boundary unchanged.
    for token in (
            u"\u5bf9\u8c61\u5df2\u7ecf\u4f7f\u7528",
            u"\u5bf9\u8c61\u5df2\u88ab\u4f7f\u7528",
            u"\u5bf9\u8c61\u6b63\u5728\u4f7f\u7528",
            u"\u5bf9\u8c61\u5df2\u5728\u4f7f\u7528"):
        if token in text:
            return True
    for token in (
            r"\u5bf9\u8c61\u5df2\u7ecf\u4f7f\u7528",
            r"\u5bf9\u8c61\u5df2\u88ab\u4f7f\u7528",
            r"\u5bf9\u8c61\u6b63\u5728\u4f7f\u7528",
            r"\u5bf9\u8c61\u5df2\u5728\u4f7f\u7528"):
        if token in compact:
            return True

    # Keep English matching explicit enough not to turn every unrelated
    # vendor validation mentioning a resource into an object-lock retry.
    for phrase in (
            "already in use", "object is in use", "object in use",
            "resource is in use", "handle is in use",
            "object is being used"):
        if phrase in lowered:
            return True
    try:
        if re.search(
                r"\b(?:object|resource|device|handle)\b[^\r\n.]{0,80}"
                r"\b(?:already\s+|currently\s+|being\s+)?in\s+use\b",
                lowered):
            return True
    except Exception:
        pass
    return False


def _sha256(value):
    return hashlib.sha256(_text(value).encode("utf-8")).hexdigest()


def _get_member(obj, property_name, getter_name=None, default=None):
    try:
        value = getattr(obj, property_name)
        if hasattr(value, "__call__"):
            value = value()
        return value
    except Exception:
        pass
    if getter_name:
        try:
            return getattr(obj, getter_name)()
        except Exception:
            pass
    return default


def _native_primary_project_for_current_path():
    """Return the Core primary project that backs the current IDE project.

    ScriptEngine's ``ScriptProject`` wrapper does not expose its CoreProject
    reliably in InoProShop 1.10. Vendor plug-ins use the Core engine's
    ``Projects.PrimaryProject`` instead, so follow that same public route and
    reject a primary project whose path does not match the ScriptEngine view.
    """
    try:
        system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
        if system_instances is None:
            return None
        engine_property = system_instances.GetProperty("Engine")
        engine = engine_property.GetValue(None, None) if engine_property is not None else None
        core_projects = _get_member(engine, "Projects", "get_Projects")
        primary = _get_member(core_projects, "PrimaryProject", "get_PrimaryProject")
        if primary is None:
            return None
        handle = _get_member(primary, "Handle", "get_Handle")
        # Core project handles are zero-based in this InoProShop build.
        if handle is None:
            return None
        expected_path = _project_path()
        primary_path = _text(_get_member(primary, "Path", "get_Path", ""))
        if expected_path and primary_path:
            expected = os.path.normcase(os.path.abspath(expected_path))
            actual = os.path.normcase(os.path.abspath(primary_path))
            if expected != actual:
                return None
        return primary
    except Exception:
        return None


def _object_name(obj):
    return _text(_get_member(obj, "name", "get_name", ""))


def configure_prompt_handling():
    global prompt_handling_status
    try:
        # New engines (SP21 P5+/ScriptEngine 4.x) deprecated the old
        # PromptHandling enum; auto-forwarding silently stops working there
        # (2026-09-08 campaign: a native library dialog blocked the queue).
        # Gate on the new API shape; the legacy enum stays for InoProShop.
        if hasattr(system, "script_prompt_handling"):
            new_flags = (
                getattr(system, "ScriptPromptHandling", None) is not None
            )
            if new_flags:
                value = (system.ScriptPromptHandling.LogPrompts |
                         system.ScriptPromptHandling.ForwardUnknownPrompts)
                system.script_prompt_handling = value
                prompt_handling_status = {
                    "configured": True,
                    "api": "script_prompt_handling",
                    "value": _text(system.script_prompt_handling),
                    "error": None,
                }
                return
        value = (PromptHandling.ForwardSimplePrompts |
                 PromptHandling.LogSimplePrompts |
                 PromptHandling.LogMessageKeys)
        system.prompt_handling = value
        prompt_handling_status = {
            "configured": True,
            "api": "legacy_prompt_handling",
            "value": _text(system.prompt_handling),
            "error": None,
        }
    except Exception as exc:
        prompt_handling_status = {
            "configured": False,
            "value": None,
            "error": repr(exc),
        }


def configure_abort_handling():
    """Disable the session-level cancel link for the resident bridge."""
    global abort_handling_status
    try:
        system.abortable = False
        abort_handling_status = {
            "configured": True,
            "abortable": bool(system.abortable),
            "error": None,
        }
    except Exception as exc:
        abort_handling_status = {
            "configured": False,
            "abortable": None,
            "error": repr(exc),
        }


def open_project_silent(path, password=""):
    flags = VersionUpdateFlags.NoUpdates | VersionUpdateFlags.SilentMode
    opened = projects.open(path, password, "", "", True, flags, False)
    return opened, {
        "mode": "explicit-silent",
        "updateFlags": _text(flags),
        "allowReadonly": False,
        "promptHandling": prompt_handling_status,
    }


def _is_textual(obj):
    return (hasattr(obj, "textual_declaration") or
            hasattr(obj, "textual_implementation"))


def find_textual_object(name):
    cached = pou_cache.get(name)
    if cached is not None and _is_textual(cached):
        return cached
    try:
        matches = list(project.find(name, True))
    except Exception:
        matches = []
    textual = [item for item in matches
               if _is_textual(item) and _object_name(item) == name]
    if len(textual) > 1:
        raise RuntimeError(
            "ambiguous textual object '%s': %d exact matches" %
            (name, len(textual))
        )
    if textual:
        pou_cache[name] = textual[0]
        return textual[0]
    return None


def _pou_type(kind):
    normalized = (kind or "program").strip().lower()
    mapping = {
        "program": PouType.Program,
        "function_block": PouType.FunctionBlock,
        "function": PouType.Function,
    }
    if normalized not in mapping:
        raise RuntimeError("unsupported POU kind: " + normalized)
    return mapping[normalized]


def _implementation_language(language="st"):
    normalized = (language or "st").strip().lower()
    languages = globals().get("ImplementationLanguages")
    if languages is None:
        languages = globals().get("ScriptImplementationLanguage")
    if languages is None:
        raise RuntimeError("implementation language enum is unavailable")
    mapping = {
        "st": "st",
        "structured_text": "st",
        "ld": "ladder",
        "ladder": "ladder",
        "fbd": "fbd",
        "sfc": "sfc",
        "cfc": "cfc",
        "il": "instruction_list",
        "instruction_list": "instruction_list",
        "page_cfc": "page_oriented_cfc",
        "uml": "uml_statechart",
    }
    member = mapping.get(normalized)
    if member is None:
        raise RuntimeError(
            "unsupported implementation language: %s; use st, ld, fbd, sfc, cfc, il, page_cfc or uml" %
            normalized
        )
    value = getattr(languages, member, None)
    if value is None:
        raise RuntimeError("implementation language enum member unavailable: " + member)
    return value


def get_or_create_pou(name, kind="program", create_if_missing=True, language="st",
                      return_type=None, base_type=None, interfaces=None,
                      parent=None):
    pou = find_textual_object(name)
    if pou is not None:
        return pou, False
    if not create_if_missing:
        raise RuntimeError("textual object not found: " + name)
    pou_type = _pou_type(kind)
    lang = _implementation_language(language)
    # POU/FB/FN must be created inside the Application's POU container, not
    # through the bare project handle: project.create_pou lands objects in the
    # root-level POU pool where the compiler rejects them with error 464
    # ("object not supported in POU view").  GVL/DUT creation already used
    # _creation_parent for exactly this reason.
    if parent is not None:
        container = find_project_object(parent)[0]
    else:
        container = getattr(project, "active_application", None)
    creator = getattr(container, "create_pou", None)
    if creator is None:
        container = project
        creator = project.create_pou
    # The ScriptEngine overload is create_pou(name, type, language, return_type,
    # base_type, interfaces).  Programs and FBs accept the 3-arg form; functions
    # raise ValueError (return_type) unless the return type is supplied, and FB
    # EXTENDS/IMPLEMENTS clauses go through the remaining string parameters.
    try:
        pou = creator(name, pou_type, lang)
    except Exception as exc:
        extra = []
        if return_type:
            extra.append(return_type)
        elif pou_type == PouType.Function:
            raise RuntimeError(
                "function POU creation requires returnType: " + repr(exc))
        else:
            extra.append(None)
        if base_type:
            extra.append(base_type)
        if interfaces:
            extra.append(interfaces)
        pou = creator(name, pou_type, lang, *extra)
    pou_cache[name] = pou
    return pou, True


def _document_text(document):
    if document is None:
        return ""
    return _text(_get_member(document, "text", "get_text", ""))


def _validate_source_text(value, label):
    value = _text(value)
    # JSON decoders turn "\\n" into a real LF. Seeing the two literal
    # characters here means a caller escaped the payload twice.
    if has_literal_linebreak_escape(value):
        raise OperationError(
            "%s contains literal backslash-n sequences; provide real line breaks"
            % label,
            "invalid_text_encoding",
            {
                "path": label,
                "expected": "LF/CRLF line breaks",
                "actual": "literal backslash-n characters",
                "example": "FUNCTION_BLOCK Demo\\nVAR\\nEND_VAR\\n",
                "repair": "decode JSON escape sequences before calling the write tool",
            },
        )
    return value


def _canonical_source_text(value):
    """Compare source content independent of the IDE's line-ending policy.

    InoProShop stores textual objects with LF line endings even when a client
    supplies CRLF.  Line endings are transport formatting, not an IEC source
    change, but the raw form remains in every response so callers can record
    the actual native bytes.
    """
    return _text(value).replace("\r\n", "\n").replace("\r", "\n")


def _document_readback(document, expected, label):
    if document is None:
        raise RuntimeError(label + " document is unavailable")
    expected = _validate_source_text(expected, label)
    actual = _document_text(document)
    canonical_expected = _canonical_source_text(expected)
    canonical_actual = _canonical_source_text(actual)
    result = {
        "chars": len(actual),
        "sha256": _sha256(actual),
        "exactMatch": actual == expected,
        "canonicalMatch": canonical_actual == canonical_expected,
        "canonicalSha256": _sha256(canonical_actual),
    }
    if actual != expected:
        result["expectedChars"] = len(expected)
        result["expectedSha256"] = _sha256(expected)
        result["expectedCanonicalSha256"] = _sha256(canonical_expected)
        result["lineEndingNormalized"] = (
            canonical_actual == canonical_expected
        )
    if canonical_actual != canonical_expected:
        raise RuntimeError(
            "%s readback mismatch: expected %d chars/%s, got %d chars/%s" %
            (label, len(expected), _sha256(expected), len(actual), _sha256(actual))
        )
    return result


def _write_document(document, expected, label):
    if document is None:
        raise RuntimeError(label + " document is unavailable")
    expected = _validate_source_text(expected, label)
    document.replace(expected)
    return _document_readback(document, expected, label)


def read_st(pou):
    declaration = _document_text(
        _get_member(pou, "textual_declaration", "get_textual_declaration")
    )
    implementation = _document_text(
        _get_member(pou, "textual_implementation", "get_textual_implementation")
    )
    return {
        "name": _object_name(pou),
        "declaration": declaration,
        "implementation": implementation,
        "declarationChars": len(declaration),
        "implementationChars": len(implementation),
        "declarationSha256": _sha256(declaration),
        "implementationSha256": _sha256(implementation),
    }


def list_textual_objects():
    items = []
    reader = _program_reader_module()

    def visit(parent, path_parts):
        try:
            children = list(parent.get_children(False))
        except Exception:
            children = []
        for child in children:
            name = _object_name(child) or "<unnamed>"
            child_path = path_parts + [name]
            declaration_doc = _get_member(
                child, "textual_declaration", "get_textual_declaration"
            )
            implementation_doc = _get_member(
                child, "textual_implementation", "get_textual_implementation"
            )
            if declaration_doc is not None or implementation_doc is not None:
                declaration_text = _document_text(declaration_doc)
                implementation_text = _document_text(implementation_doc)
                language = _text(_get_member(child, "implementation_language", "get_implementation_language", ""))
                body = reader.describe_body(declaration_text, implementation_text,
                    declaration_doc is not None, implementation_doc is not None, language)
                items.append({
                    "name": name,
                    "path": "/".join(child_path),
                    "type": _text(getattr(child, "type", "")),
                    "hasDeclaration": declaration_doc is not None,
                    "hasImplementation": implementation_doc is not None,
                    "declarationChars": len(declaration_text),
                    "implementationChars": len(implementation_text),
                    "implementationLanguage": language,
                    "bodyState": body["bodyState"],
                })
            visit(child, child_path)

    visit(project, [])
    return items


def _severity_kind(value):
    raw = _text(value)
    lowered = raw.lower()
    if "fatal" in lowered or "error" in lowered or u"错误" in lowered:
        return "error"
    if "warn" in lowered or u"警告" in lowered:
        return "warning"
    if lowered == "text":
        return "status"
    if "info" in lowered or u"信息" in lowered:
        return "info"
    return "unknown"


def _message_entry(message, category):
    severity = _get_member(message, "severity", "get_severity")
    entry = {
        "category": _text(category),
        "severity": _severity_kind(severity),
        "severityRaw": _text(severity),
        "text": _text(_get_member(message, "text", "get_text", "")),
    }
    fields = (
        ("prefix", "prefix", "get_prefix"),
        ("position", "position_text", "get_position_text"),
        ("positionOffset", "position_offset", "get_position_offset"),
        ("length", "length", "get_length"),
        ("number", "number", "get_number"),
    )
    for output_name, property_name, getter_name in fields:
        value = _get_member(message, property_name, getter_name)
        if value is not None and _text(value) != "":
            entry[output_name] = _json_safe(value)
    return entry


def _classify_plain_message(raw, category):
    text_value = _text(raw)
    return {
        "category": _text(category),
        "severity": _severity_kind(text_value),
        "severityRaw": "plain-text-fallback",
        "text": text_value,
    }


def clear_messages(exclude_categories=None):
    excluded = set(_text(item).lower() for item in (exclude_categories or []))
    cleared = []
    errors = []
    # get_message_categories() returns Guid values on some InoProShop builds,
    # but category wrappers on others. Always clear the PLC categories by an
    # explicit System.Guid first; passing a wrapper can report success while
    # leaving editor/parser messages in the message store.
    try:
        import System
        for known in (BUILD_CATEGORY, PRECOMPILE_CATEGORY):
            if known.lower() in excluded:
                continue
            try:
                system.clear_messages(System.Guid(known))
                cleared.append(known)
            except Exception as exc:
                errors.append({"category": known, "error": repr(exc)})
    except Exception as exc:
        errors.append({"category": "known_categories", "error": repr(exc)})
    try:
        categories = list(system.get_message_categories(True))
    except Exception as exc:
        return {"cleared": cleared, "errors": [repr(exc)]}
    for category in categories:
        category_text = _text(category)
        if category_text.lower() in excluded:
            continue
        try:
            clear_target = category
            if category_text.lower() in (BUILD_CATEGORY.lower(), PRECOMPILE_CATEGORY.lower()):
                try:
                    import System
                    clear_target = System.Guid(category_text)
                except Exception:
                    clear_target = category
            system.clear_messages(clear_target)
            if category_text not in cleared:
                cleared.append(category_text)
        except Exception as exc:
            errors.append({"category": category_text, "error": repr(exc)})
    return {"cleared": cleared, "errors": errors}


def _diagnostic_category_inventory():
    """Return active categories plus installed build targets.

    ScriptEngine's ``get_message_categories(True)`` only returns categories
    that have received at least one message since this IDE process started.
    A clean precompile category is therefore absent from that list in a fresh
    process.  Enumerate the installation separately, but only query the active
    categories and our two build targets so diagnostic polling does not walk
    every installed plug-in category on every sample.
    """
    errors = []
    try:
        active = [item for item in list(system.get_message_categories(True))
                  if item is not None]
    except Exception as exc:
        return {
            "active": [], "installed": [], "query": [],
            "complete": False,
            "errors": [{"scope": "active", "error": repr(exc)}],
        }
    try:
        installed = [item for item in list(system.get_message_categories(False))
                     if item is not None]
    except Exception as exc:
        return {
            "active": active, "installed": [], "query": active,
            "complete": False,
            "errors": [{"scope": "installed", "error": repr(exc)}],
        }

    def category_key(value):
        return _text(value).strip().lower()

    active_keys = set(category_key(item) for item in active)
    installed_by_key = dict((category_key(item), item) for item in installed)
    query = list(active)
    query_keys = set(active_keys)
    for target in (BUILD_CATEGORY, PRECOMPILE_CATEGORY):
        key = target.lower()
        category = installed_by_key.get(key)
        if category is not None and key not in query_keys:
            query.append(category)
            query_keys.add(key)
    # A category object that resolved to None would reach the CLR
    # get_message_objects call and raise ArgumentNullException (parameter
    # 'category'), killing the whole diagnostics collection. Drop it here.
    query = [item for item in query if item is not None]
    return {
        "active": active,
        "activeKeys": active_keys,
        "installed": installed,
        "installedKeys": set(installed_by_key.keys()),
        "query": query,
        "complete": True,
        "errors": errors,
    }


def collect_messages(categories=None):
    """Read the live message store.  ``categories`` (optional) restricts the
    walk to the given category GUIDs — the CODESYS-line per-op snapshots use
    it to skip the vendor/editor categories and shorten primary-thread time
    on the SP22 engine (where the script IS the UI thread)."""
    messages = []
    category_results = []
    inventory = _diagnostic_category_inventory()
    if not inventory.get("complete"):
        return {
            "messages": [],
            "categories": [],
            "collectionComplete": False,
            "collectionErrors": inventory.get("errors", []),
            "activeCategoryCount": len(inventory.get("active", [])),
            "installedCategoryCount": len(inventory.get("installed", [])),
        }

    active_keys = inventory.get("activeKeys", set())
    installed_keys = inventory.get("installedKeys", set())
    for category in inventory.get("query", []):
        category_name = _text(category)
        if categories is not None and category_name not in categories:
            continue
        category_key = category_name.strip().lower()
        active = category_key in active_keys
        structured = None
        structured_error = None
        try:
            structured = list(system.get_message_objects(category, ALL_SEVERITIES))
        except Exception as exc:
            structured_error = repr(exc)
            try:
                structured = list(system.get_message_objects(category))
                structured_error = None
            except Exception as retry_exc:
                structured_error = repr(retry_exc)

        if structured is not None:
            for message in structured:
                messages.append(_message_entry(message, category))
            category_results.append({
                "category": category_name,
                "source": "structured",
                "count": len(structured),
                "active": active,
                "installed": category_key in installed_keys,
                "queryMode": "active" if active else "installed_target",
            })
            continue

        try:
            plain = list(system.get_messages(category))
            for message in plain:
                messages.append(_classify_plain_message(message, category))
            category_results.append({
                "category": category_name,
                "source": "plain-text",
                "count": len(plain),
                "structuredError": structured_error,
                "active": active,
                "installed": category_key in installed_keys,
                "queryMode": "active" if active else "installed_target",
            })
        except Exception as exc:
            category_results.append({
                "category": category_name,
                "source": "failed",
                "count": 0,
                "structuredError": structured_error,
                "plainTextError": repr(exc),
                "active": active,
                "installed": category_key in installed_keys,
                "queryMode": "active" if active else "installed_target",
            })

    collection_errors = [item for item in category_results
                         if item.get("source") == "failed"]
    return {
        "messages": messages,
        "categories": category_results,
        "collectionComplete": not collection_errors,
        "collectionErrors": collection_errors,
        "activeCategoryCount": len(inventory.get("active", [])),
        "installedCategoryCount": len(inventory.get("installed", [])),
        "categoryInventoryComplete": True,
    }


def diagnostics_categories(req=None):
    """Return the message categories actually published by this IDE session.

    The two category GUIDs used by compile_summary are deliberately only
    classification hints.  InoProShop/SP11 can expose parser diagnostics
    lazily, under a different category, or only after an editor operation.
    This probe records the live category objects and their current messages so
    callers can distinguish "no messages" from "category was never exposed".
    It is strictly read-only and never clears or creates diagnostics.
    """
    requested = req or {}
    include_messages = bool(requested.get("includeMessages", True))
    max_messages = requested.get("maxMessages", MAX_MESSAGES)
    try:
        max_messages = max(1, min(int(max_messages), MAX_MESSAGES))
    except Exception:
        max_messages = MAX_MESSAGES
    inventory = _diagnostic_category_inventory()
    if not inventory.get("complete"):
        return {
            "schema": "inoproshop.diagnostics-categories.v1",
            "readOnly": True,
            "collectionComplete": False,
            "categories": [],
            "collectionErrors": inventory.get("errors", []),
            "hints": {
                "buildCategoryHint": BUILD_CATEGORY,
                "precompileCategoryHint": PRECOMPILE_CATEGORY,
            },
        }

    def member_text(value, names):
        for name in names:
            try:
                value = getattr(value, name)
                if _is_callable(value):
                    value = value()
                if value is not None and _text(value):
                    return _text(value)
            except Exception:
                pass
        return None

    rows = []
    errors = []
    active_keys = inventory.get("activeKeys", set())
    installed_keys = inventory.get("installedKeys", set())
    for category in inventory.get("query", []):
        category_text = _text(category)
        category_key = category_text.strip().lower()
        active = category_key in active_keys
        row = {
            "id": category_text,
            "text": category_text,
            "runtimeType": None,
            "clrType": None,
            "name": member_text(category, ("name", "Name", "display_name", "DisplayName")),
            "description": member_text(category, ("description", "Description")),
            "isBuildHint": category_text.lower() == BUILD_CATEGORY.lower(),
            "isPrecompileHint": category_text.lower() == PRECOMPILE_CATEGORY.lower(),
            "active": active,
            "installed": category_key in installed_keys,
            "queryMode": "active" if active else "installed_target",
            "source": None,
            "messageCount": 0,
            "messages": [],
        }
        try:
            runtime_type = category.GetType()
            row["runtimeType"] = _text(runtime_type.FullName)
            row["clrType"] = _text(runtime_type.AssemblyQualifiedName)
        except Exception as exc:
            row["runtimeTypeError"] = repr(exc)
        structured = None
        structured_error = None
        try:
            structured = list(system.get_message_objects(category, ALL_SEVERITIES))
            row["source"] = "structured"
        except Exception as exc:
            structured_error = repr(exc)
            try:
                structured = list(system.get_message_objects(category))
                row["source"] = "structured-default-severity"
                structured_error = None
            except Exception as retry_exc:
                structured_error = repr(retry_exc)
        if structured is not None:
            row["messageCount"] = len(structured)
            if include_messages:
                row["messages"] = [_message_entry(item, category) for item in structured[:max_messages]]
        else:
            try:
                plain = list(system.get_messages(category))
                row["source"] = "plain-text"
                row["messageCount"] = len(plain)
                if include_messages:
                    row["messages"] = [_classify_plain_message(item, category) for item in plain[:max_messages]]
            except Exception as exc:
                row["source"] = "failed"
                row["plainTextError"] = repr(exc)
                errors.append({"category": category_text, "structuredError": structured_error,
                               "plainTextError": repr(exc)})
        if structured_error:
            row["structuredError"] = structured_error
        rows.append(row)
    return {
        "schema": "inoproshop.diagnostics-categories.v1",
        "readOnly": True,
        "collectionComplete": not errors,
        "categoryCount": len(rows),
        "activeCategoryCount": len(inventory.get("active", [])),
        "installedCategoryCount": len(inventory.get("installed", [])),
        "queryScope": "active_plus_installed_build_targets",
        "categories": rows,
        "collectionErrors": errors,
        "hints": {
            "buildCategoryHint": BUILD_CATEGORY,
            "precompileCategoryHint": PRECOMPILE_CATEGORY,
            "hintMeaning": "Hints are not evidence; use the live rows and runtime type.",
        },
        "mutatedProject": False,
    }


def _diagnostic_group(category):
    value = _text(category).lower()
    if value == BUILD_CATEGORY.lower():
        return "compile"
    if value == PRECOMPILE_CATEGORY.lower():
        return "precompile"
    return "other"


def _plc_diagnostic_message(message):
    """Separate PLC diagnostics from resident ScriptEngine/runtime messages."""
    if _diagnostic_group(message.get("category", "")) in (
            "compile", "precompile"):
        return True
    # Some SP11 builds publish IEC parser diagnostics under a third category,
    # but those records still carry a real source position. ScriptEngine
    # warnings produced by a bridge reload do not.
    return _positioned_diagnostic(message)


def _normalize_message_text(text):
    """Decode a message text that may arrive JSON/CLR-escaped.

    E2E V2 R089 (L84): on the InoProShop line the build messages came back as
    the literal backslash-u form of the Chinese completion line, so every
    marker comparison failed, completionSeen stayed false, compileStatus stayed
    "unknown" and the native LAD writers ROLLED BACK a clean 0/0 build (then
    refused the retry with retryable_diagnostic_gap_missing).
    """
    value = _text(text)
    if "\\u" not in value and "\\n" not in value and "\\t" not in value:
        return value
    for attempt in ("unicode_escape", "raw_unicode_escape"):
        try:
            import codecs as _codecs
            decoded = _codecs.decode(value, attempt)
            if decoded and ("\\u" not in decoded):
                return decoded
        except Exception:
            continue
    try:
        return value.encode("latin-1", "backslashreplace").decode("unicode_escape")
    except Exception:
        return value


def _is_compile_completion_text(text):
    """True when one build message announces a finished compilation."""
    normalized = _normalize_message_text(text)
    lowered = normalized.lower()
    return bool(
        u"\u7f16\u8bd1\u5b8c\u6210" in normalized or
        u"\u6784\u5efa\u5b8c\u6210" in normalized or
        "compile complete" in lowered or
        "build complete" in lowered or
        "compilation complete" in lowered or
        "compile finished" in lowered or
        "build finished" in lowered or
        "build succeeded" in lowered or
        "compile succeeded" in lowered
    )

def compile_summary(diagnostics, build_invoked=False):
    all_messages = diagnostics.get("messages", [])
    plc_messages = [message for message in all_messages
                    if _plc_diagnostic_message(message)]
    ignored_messages = [message for message in all_messages
                        if not _plc_diagnostic_message(message)]
    messages = [m for m in all_messages
                if m.get("category", "").lower() == BUILD_CATEGORY]
    other_messages = [m for m in all_messages
                      if m.get("category", "").lower() != BUILD_CATEGORY]
    # InoProShop emits POU/parser diagnostics in a separate category from the
    # build progress category.  Counting only BUILD_CATEGORY can therefore
    # report 0/0 while the editor contains red errors. ScriptEngine/runtime
    # categories can also publish unrelated bridge warnings during the same
    # operation, so only PLC categories or positioned IEC records gate it.
    error_count = len([m for m in plc_messages if m.get("severity") == "error"])
    warning_count = len([m for m in plc_messages if m.get("severity") == "warning"])
    unknown_count = len([m for m in plc_messages if m.get("severity") == "unknown"])
    build_categories = [c for c in diagnostics.get("categories", [])
                        if c.get("category", "").lower() == BUILD_CATEGORY]
    precompile_messages = [m for m in all_messages
                           if _diagnostic_group(m.get("category", "")) == "precompile"]
    precompile_categories = [c for c in diagnostics.get("categories", [])
                             if c.get("category", "").lower() == PRECOMPILE_CATEGORY.lower()]
    precompile_installed = any(
        category.get("installed", True)
        for category in precompile_categories
    )
    precompile_active = any(
        category.get("active", True)
        for category in precompile_categories
    )
    precompile_query_complete = any(
        category.get("source") in (
            "structured", "structured-default-severity", "plain-text")
        and not category.get("plainTextError")
        for category in precompile_categories
    )
    post_build_direct_query = bool(
        build_invoked and precompile_installed and precompile_query_complete
    )
    # A successful direct read of an installed precompile category with
    # count=0 is positive evidence of a clean parser pass after a real build.
    # SP11's structured API rejects an inactive category, while its
    # get_messages(Guid) overload still performs the exact installed-category
    # query.  The build_invoked guard above prevents an ordinary read-only
    # diagnostics snapshot from promoting that empty result to success.
    precompile_category_observed = bool(precompile_messages or precompile_active)
    precompile_errors = len([m for m in precompile_messages
                             if m.get("severity") == "error"])
    precompile_warnings = len([m for m in precompile_messages
                               if m.get("severity") == "warning"])
    precompile_unknown = len([m for m in precompile_messages
                              if m.get("severity") == "unknown"])
    inferred_precompile_messages = [m for m in messages
                                    if _positioned_diagnostic(m)]
    precompile_diagnostics_observed = bool(
        precompile_messages or inferred_precompile_messages or
        precompile_active or post_build_direct_query
    )
    precompile_evidence_source = (
        "category" if precompile_messages else
        "structured_position_inference" if inferred_precompile_messages else
        "active_category_empty" if precompile_active else
        "post_build_direct_category_query" if post_build_direct_query else
        "none"
    )
    if not precompile_messages and inferred_precompile_messages:
        # Some InoProShop builds publish IEC parser errors in the build
        # category while retaining source position/text. Keep that evidence
        # separate from the category GUID so callers cannot mistake an empty
        # precompile category for a real diagnostic result.
        precompile_messages = inferred_precompile_messages
        precompile_errors = len([m for m in precompile_messages
                                 if m.get("severity") == "error"])
        precompile_warnings = len([m for m in precompile_messages
                                   if m.get("severity") == "warning"])
        precompile_unknown = len([m for m in precompile_messages
                                  if m.get("severity") == "unknown"])
    structured_build = any(c.get("source") == "structured"
                           for c in build_categories)
    completion_seen = any(
        _is_compile_completion_text(m.get("text", ""))
        for m in messages
    )

    if error_count:
        status = "failed"
    elif (diagnostics.get("collectionComplete") and structured_build and
          completion_seen and unknown_count == 0):
        status = "success"
    else:
        status = "unknown"

    if not precompile_diagnostics_observed:
        # A missing category is not evidence of a clean precompiler.  Some
        # SP11 builds expose parser diagnostics only while the editor is
        # active, so callers must see this as an explicit verification gap.
        precompile_status = "unknown"
    elif precompile_errors:
        precompile_status = "failed"
    elif precompile_unknown:
        precompile_status = "unknown"
    else:
        precompile_status = "success"

    diagnostic_gaps = []
    if not diagnostics.get("collectionComplete", False):
        diagnostic_gaps.append("message_collection_incomplete")
    if not build_categories:
        diagnostic_gaps.append("compile_category_not_observed")
    if not (precompile_installed and precompile_query_complete and
            (precompile_active or precompile_messages or
             inferred_precompile_messages or post_build_direct_query)):
        diagnostic_gaps.append("precompile_category_not_observed")

    compile_ok = bool(
        status == "success" and
        precompile_status == "success" and
        error_count == 0 and
        unknown_count == 0 and
        precompile_errors == 0 and
        precompile_unknown == 0 and
        not diagnostic_gaps
    )

    return {
        "compileStatus": status,
        # compileStatus describes the compiler category. compileOk is the
        # stricter public gate and also requires complete precompile evidence.
        "compileOk": compile_ok,
        "errorCount": error_count,
        "warningCount": warning_count,
        "unknownSeverityCount": unknown_count,
        "completionSeen": completion_seen,
        "messageCount": len(all_messages),
        "plcDiagnosticMessageCount": len(plc_messages),
        "ignoredNonPlcMessageCount": len(ignored_messages),
        "ignoredNonPlcMessages": ignored_messages[:MAX_MESSAGES],
        "buildMessageCount": len(messages),
        "otherMessageCount": len(other_messages),
        "precompileStatus": precompile_status,
        "precompileOk": precompile_status == "success",
        "precompileCategoryObserved": precompile_category_observed,
        "precompileCategoryInstalled": precompile_installed,
        "precompileCategoryActive": precompile_active,
        "precompileCategoryQueried": precompile_query_complete,
        "precompileDiagnosticsObserved": precompile_diagnostics_observed,
        "precompileEvidenceSource": precompile_evidence_source,
        "precompileErrorCount": precompile_errors,
        "precompileWarningCount": precompile_warnings,
        "precompileUnknownSeverityCount": precompile_unknown,
        "precompileMessages": precompile_messages[:MAX_MESSAGES],
        # Library-manager failures are native host events, not ScriptEngine
        # message objects. route_cli fills this field from timestamp-filtered
        # native log evidence when available.
        "libraryManager": {
            "status": "not_observed",
            "source": "host_native_log",
        },
        "diagnosticsComplete": diagnostics.get("collectionComplete", False),
        "diagnosticGaps": diagnostic_gaps,
        "categories": diagnostics.get("categories", []),
        "messages": messages[:MAX_MESSAGES],
        "otherMessages": other_messages[:MAX_MESSAGES],
    }


def _diagnostic_fingerprint(diagnostics):
    """Return an order-independent identity for the live diagnostic store."""
    message_fields = (
        "category", "severity", "severityRaw", "prefix", "number", "text",
        "position", "positionOffset", "length",
    )
    category_fields = (
        "category", "source", "count", "structuredError", "plainTextError",
    )
    message_rows = [
        [_text(message.get(field)) for field in message_fields]
        for message in diagnostics.get("messages", [])
    ]
    category_rows = [
        [_text(category.get(field)) for field in category_fields]
        for category in diagnostics.get("categories", [])
    ]
    message_rows.sort(key=lambda row: u"\x1f".join(row))
    category_rows.sort(key=lambda row: u"\x1f".join(row))
    payload = {
        "collectionComplete": bool(diagnostics.get("collectionComplete", False)),
        "collectionErrors": sorted(
            [_text(item) for item in diagnostics.get("collectionErrors", [])]
        ),
        "categories": category_rows,
        "messages": message_rows,
    }
    return json.dumps(payload, ensure_ascii=True, sort_keys=True,
                      separators=(",", ":"))


def _diagnostic_message_key(message):
    """Return a stable identity for one diagnostic across repeated polls."""
    fields = (
        "category", "severity", "severityRaw", "prefix", "number", "text",
        "position", "positionOffset", "length",
    )
    return json.dumps(
        [_text(message.get(field)) for field in fields],
        ensure_ascii=True, separators=(",", ":"))


_KNOWN_PLACEHOLDER_LIBRARY_CATEGORY = "56a60174-4139-411b-86c7-df0da1cfc088"
_KNOWN_PLACEHOLDER_LIBRARY_NAMES = (
    "InoParamsConfigLib", "SoftMotion_AddRamps",
)
_KNOWN_PLACEHOLDER_LIBRARY_MARKERS = (
    "cannot open library", "placeholder library",
    # Real-Chinese wording, built from explicit code points so file-encoding
    # or escape-roundtripping can never turn these into literal \uXXXX text
    # (round-2026-09-02 live evidence: the tuple had silently become the
    # escaped form, so marker matching always failed and the LAD baseline
    # gate blocked every generation).
    u"".join([unichr(c) for c in (19981, 33021, 25171, 24320, 24211)]),
    u"".join([unichr(c) for c in (21344, 20301, 31526, 24211)]),
    # Some bridge responses have already JSON-escaped the vendor text before
    # this module sees it (the literal ``\\uXXXX`` sequence survives a second
    # serialization pass).  Accept those exact forms as well.
    "\\u4e0d\\u80fd\\u6253\\u5f00\\u5e93",
    "\\u5360\\u4f4d\\u7b26\\u5e93",
)


def _json_unescape_text(text):
    """Decode a message text that was stored in its JSON-escaped form.

    The vendor message store can hold the text with literal ``\\uXXXX``
    sequences (quotes included, e.g. ``\\u0027``).  Matching against that
    form breaks word-boundary checks — the digit ``7`` of ``\\u0027`` sits
    right before the library name.  Decode the escaped form when present so
    the predicate works on the real wording; keep the original on failure.
    """
    try:
        if "\\u" not in text:
            return text
        candidate = json.loads(u'"' + text.replace(u'"', u'\\"') + u'"')
        # ``basestring`` exists only on IronPython 2.7.  Keep this helper
        # usable from the CPython based offline contract tests as well as the
        # resident IronPython bridge.  ``json.loads`` returns a text value for
        # a quoted JSON string, so a non-None candidate is sufficient here.
        if candidate is not None:
            return candidate
    except Exception:
        pass
    return text


def _known_placeholder_library_diagnostic(message):
    """Recognize one known *baseline* placeholder-library diagnostic.

    InoProShop can leave an installation-level placeholder-library error in
    the message store before a native LAD write starts.  The error is not a
    compiler result and is removed by ``clear_messages``; treating every
    category-56a error as benign would hide real library/parser failures.
    Keep this predicate deliberately narrow (exact category, error severity,
    known library name and the native load-failure wording).  The caller only
    applies it to the ``before_build_clear`` snapshot and retains the raw
    message as audit evidence.
    """
    if not isinstance(message, dict):
        return False
    if _text(message.get("severity")).strip().lower() != "error":
        return False
    category = _text(message.get("category")).strip().lower()
    if category != _KNOWN_PLACEHOLDER_LIBRARY_CATEGORY.lower():
        return False
    text = _text(message.get("text")).strip().lower()
    if not text:
        return False
    # The store can hold the JSON-escaped form; decode it before matching so
    # \\u0027-style escaped quotes don't break the word-boundary checks.
    # Keep the predicate robust when this function is loaded in isolation by
    # contract tests or a diagnostic replay tool.  Those callers may extract
    # only ``_known_placeholder_library_diagnostic`` and therefore not define
    # the module-level helper above.  Falling back to the same tiny decoder
    # preserves matching instead of leaking a NameError and, in production,
    # still uses the canonical helper.
    unescape = globals().get("_json_unescape_text")
    if callable(unescape):
        text = unescape(text)
    elif "\\u" in text:
        try:
            decoded = json.loads(u'"' + text.replace(u'"', u'\\"') + u'"')
            if decoded is not None:
                text = decoded
        except Exception:
            pass
    # Remove the IEC library-name marker so both ``#Name`` and ``Name`` are
    # accepted, while still requiring the exact known name as a token.
    normalized = text.replace("#", "")
    if not any(re.search(
            r"(?<![A-Za-z0-9_])" + re.escape(name.lower()) +
            r"(?![A-Za-z0-9_])", normalized)
               for name in _KNOWN_PLACEHOLDER_LIBRARY_NAMES):
        return False
    return any(marker.lower() in text
               for marker in _KNOWN_PLACEHOLDER_LIBRARY_MARKERS)


def _noteworthy_diagnostic_messages(diagnostics):
    """Keep every diagnostic that can invalidate a write or strict LAD gate."""
    return [dict(message) for message in diagnostics.get("messages", [])
            if (message.get("severity") in ("error", "warning", "unknown") and
                _plc_diagnostic_message(message))]


def _apply_observed_diagnostic_history(summary, messages):
    """Make any diagnostic observed during the operation participate in gates.

    InoProShop can retract a precompile error after a later model commit.  The
    final snapshot remains available through the ``final*`` fields, while the
    public counts and statuses describe the whole observation window.
    """
    unique = {}
    order = []
    for raw in messages or []:
        message = dict(raw)
        key = _diagnostic_message_key(message)
        existing = unique.get(key)
        if existing is None:
            unique[key] = message
            order.append(key)
            continue
        for field in ("lastSeenAtMs", "lastSeenSample", "lastSeenStage"):
            if message.get(field) is not None:
                existing[field] = message.get(field)
        existing["seenCount"] = int(existing.get("seenCount", 1) or 1) + int(
            message.get("seenCount", 1) or 1)

    observed = [unique[key] for key in order]
    observed_errors = [item for item in observed
                       if item.get("severity") == "error"]
    observed_warnings = [item for item in observed
                         if item.get("severity") == "warning"]
    observed_unknown = [item for item in observed
                        if item.get("severity") == "unknown"]
    observed_precompile = [item for item in observed
                           if _diagnostic_group(item.get("category", "")) ==
                           "precompile"]
    observed_precompile_errors = [item for item in observed_precompile
                                  if item.get("severity") == "error"]
    observed_precompile_warnings = [item for item in observed_precompile
                                    if item.get("severity") == "warning"]
    observed_precompile_unknown = [item for item in observed_precompile
                                   if item.get("severity") == "unknown"]

    final_error_count = int(summary.get(
        "finalErrorCount", summary.get("errorCount", 0)) or 0)
    final_warning_count = int(summary.get(
        "finalWarningCount", summary.get("warningCount", 0)) or 0)
    final_unknown_count = int(summary.get(
        "finalUnknownSeverityCount",
        summary.get("unknownSeverityCount", 0)) or 0)
    final_precompile_error_count = int(summary.get(
        "finalPrecompileErrorCount",
        summary.get("precompileErrorCount", 0)) or 0)
    final_precompile_warning_count = int(summary.get(
        "finalPrecompileWarningCount",
        summary.get("precompileWarningCount", 0)) or 0)
    final_precompile_unknown_count = int(summary.get(
        "finalPrecompileUnknownSeverityCount",
        summary.get("precompileUnknownSeverityCount", 0)) or 0)
    summary.update({
        "finalErrorCount": final_error_count,
        "finalWarningCount": final_warning_count,
        "finalUnknownSeverityCount": final_unknown_count,
        "finalPrecompileErrorCount": final_precompile_error_count,
        "finalPrecompileWarningCount": final_precompile_warning_count,
        "finalPrecompileUnknownSeverityCount": final_precompile_unknown_count,
        "observedErrorCount": len(observed_errors),
        "observedWarningCount": len(observed_warnings),
        "observedUnknownSeverityCount": len(observed_unknown),
        "observedPrecompileErrorCount": len(observed_precompile_errors),
        "observedPrecompileWarningCount": len(observed_precompile_warnings),
        "observedPrecompileUnknownSeverityCount": len(observed_precompile_unknown),
        "errorCount": len(observed_errors),
        "warningCount": len(observed_warnings),
        "unknownSeverityCount": len(observed_unknown),
        "precompileErrorCount": len(observed_precompile_errors),
        "precompileWarningCount": len(observed_precompile_warnings),
        "precompileUnknownSeverityCount": len(observed_precompile_unknown),
        "precompileMessages": observed_precompile[:MAX_MESSAGES],
        "diagnosticHistoryClean": not (
            observed_errors or observed_unknown),
        "diagnosticHistory": {
            "messageCount": len(observed),
            "errorCount": len(observed_errors),
            "warningCount": len(observed_warnings),
            "unknownSeverityCount": len(observed_unknown),
            "precompileErrorCount": len(observed_precompile_errors),
            "precompileWarningCount": len(observed_precompile_warnings),
            "precompileUnknownSeverityCount": len(observed_precompile_unknown),
            "messages": observed[:MAX_MESSAGES],
        },
    })
    if observed_errors:
        summary["finalCompileStatus"] = summary.get("compileStatus")
        summary["compileStatus"] = "failed"
        summary["compileOk"] = False
    if observed_unknown:
        summary["compileOk"] = False
        if summary.get("compileStatus") == "success":
            summary["finalCompileStatus"] = "success"
            summary["compileStatus"] = "unknown"
    if observed_precompile_errors:
        summary["finalPrecompileStatus"] = summary.get("precompileStatus")
        summary["precompileStatus"] = "failed"
        summary["precompileOk"] = False
    if observed_precompile_unknown:
        summary["precompileOk"] = False
        if summary.get("precompileStatus") == "success":
            summary["finalPrecompileStatus"] = "success"
            summary["precompileStatus"] = "unknown"
    return summary


def _diagnostic_stage_snapshot(stage, categories=None):
    """Capture one named write-stage snapshot without clearing any evidence.

    ``categories`` (optional) limits the message-store walk; the CODESYS-line
    PLCopen routes pass the two PLC categories only."""
    diagnostics = collect_messages(categories=categories)
    summary = compile_summary(diagnostics)
    return {
        "stage": _text(stage),
        "collectionComplete": bool(diagnostics.get("collectionComplete")),
        "collectionErrors": diagnostics.get("collectionErrors", []),
        "errorCount": int(summary.get("errorCount", 0) or 0),
        "warningCount": int(summary.get("warningCount", 0) or 0),
        "unknownSeverityCount": int(
            summary.get("unknownSeverityCount", 0) or 0),
        "precompileErrorCount": int(
            summary.get("precompileErrorCount", 0) or 0),
        "precompileWarningCount": int(
            summary.get("precompileWarningCount", 0) or 0),
        "precompileUnknownSeverityCount": int(
            summary.get("precompileUnknownSeverityCount", 0) or 0),
        "messages": _noteworthy_diagnostic_messages(diagnostics)[:MAX_MESSAGES],
    }


def _diagnostic_stage_clean(snapshot, require_zero_warnings=False):
    if not isinstance(snapshot, dict) or not snapshot.get("collectionComplete"):
        return False
    clean = bool(
        int(snapshot.get("errorCount", 0) or 0) == 0 and
        int(snapshot.get("unknownSeverityCount", 0) or 0) == 0 and
        int(snapshot.get("precompileErrorCount", 0) or 0) == 0 and
        int(snapshot.get("precompileUnknownSeverityCount", 0) or 0) == 0
    )
    if require_zero_warnings:
        clean = bool(
            clean and int(snapshot.get("warningCount", 0) or 0) == 0 and
            int(snapshot.get("precompileWarningCount", 0) or 0) == 0)
    return clean


def _apply_precompile_timeline(summary, timeline):
    """Merge named write stages with the build polling history."""
    # Messages collected by _wait_for_stable_diagnostics are post-build
    # observations.  Keep them separate from the named write-stage messages
    # while deciding whether an installation-level placeholder error was only
    # a pre-clear baseline.  A baseline error that reappears post-build must
    # remain fatal.
    post_build_messages = list((summary.get("diagnosticHistory") or {}).get(
        "messages", []))
    timeline_messages = []
    baseline_diagnostics = []
    baseline_placeholder_candidates = []
    for snapshot in timeline or []:
        stage = _text(snapshot.get("stage"))
        for raw in snapshot.get("messages", []):
            message = dict(raw)
            message.setdefault("firstSeenStage", stage)
            message["lastSeenStage"] = stage
            message.setdefault("seenCount", 1)
            if stage == "before_build_clear":
                baseline_diagnostics.append(message)
                if _known_placeholder_library_diagnostic(message):
                    baseline_placeholder_candidates.append(message)
                    continue
            timeline_messages.append(message)

    def _count_is_zero(field):
        try:
            return int(summary.get(field, 0) or 0) == 0
        except Exception:
            return False

    def _placeholder_identity(message):
        """Return a conservative identity for a known library diagnostic."""
        text = _text(message.get("text")).lower().replace("#", "")
        names = tuple(sorted(
            name.lower() for name in _KNOWN_PLACEHOLDER_LIBRARY_NAMES
            if re.search(
                r"(?<![A-Za-z0-9_])" + re.escape(name.lower()) +
                r"(?![A-Za-z0-9_])", text)))
        if not names:
            return None
        return (
            _text(message.get("category")).strip().lower(),
            _text(message.get("severity")).strip().lower(),
            names,
        )

    # A clean final snapshot is necessary but not sufficient: stability and
    # complete collection are also required before any baseline message can
    # be excluded from the effective gate.  This prevents a timeout or an
    # incomplete category query from turning a real failure into success.
    final_snapshot_clean = bool(
        summary.get("diagnosticsStable") is True and
        summary.get("diagnosticsComplete") is True and
        summary.get("finalCompileStatus") == "success" and
        summary.get("precompileStatus") == "success" and
        summary.get("precompileOk") is True and
        _count_is_zero("finalErrorCount") and
        _count_is_zero("finalWarningCount") and
        _count_is_zero("finalUnknownSeverityCount") and
        _count_is_zero("finalPrecompileErrorCount") and
        _count_is_zero("finalPrecompileWarningCount") and
        _count_is_zero("finalPrecompileUnknownSeverityCount")
    )
    post_placeholder_ids = set(
        identity for identity in
        (_placeholder_identity(message) for message in post_build_messages)
        if identity is not None
    )
    ignored_baseline = []
    if final_snapshot_clean:
        for message in baseline_placeholder_candidates:
            identity = _placeholder_identity(message)
            if identity in post_placeholder_ids:
                # The same known placeholder was observed after clear/build;
                # it is no longer a stale baseline and must invalidate the
                # operation just like any other compiler diagnostic.
                timeline_messages.append(message)
            else:
                ignored_baseline.append(message)
    else:
        # Preserve every candidate when final diagnostics are not conclusively
        # clean; the strict gate will reject it and the raw timeline remains
        # available for diagnosis.
        timeline_messages.extend(baseline_placeholder_candidates)

    messages = post_build_messages + timeline_messages
    summary["baselineDiagnostics"] = baseline_diagnostics[:MAX_MESSAGES]
    summary["baselineDiagnosticCount"] = len(baseline_diagnostics)
    summary["ignoredBaselineDiagnostics"] = ignored_baseline[:MAX_MESSAGES]
    summary["ignoredBaselineDiagnosticCount"] = len(ignored_baseline)
    summary["precompileTimeline"] = list(timeline or [])
    summary["precompileTimelineComplete"] = bool(
        timeline and all(item.get("collectionComplete") for item in timeline))
    if not summary["precompileTimelineComplete"]:
        if "precompile_timeline_incomplete" not in summary["diagnosticGaps"]:
            summary["diagnosticGaps"].append("precompile_timeline_incomplete")
        summary["compileOk"] = False
    return _apply_observed_diagnostic_history(summary, messages)


def _wait_for_stable_diagnostics(
        poll_interval_ms=DIAGNOSTIC_POLL_INTERVAL_MS,
        minimum_observation_ms=DIAGNOSTIC_MIN_OBSERVATION_MS,
        quiet_period_ms=DIAGNOSTIC_QUIET_PERIOD_MS,
        timeout_ms=DIAGNOSTIC_TIMEOUT_MS):
    """Poll until diagnostics stay unchanged beyond the known publish delay.

    InoProShop can publish IEC precompile diagnostics two to three seconds
    after ``Application.build()`` returns. Repeated identical early snapshots
    are therefore insufficient: a clean result must also survive the minimum
    observation window. A timeout is a failed verification gate, never a
    clean compile.
    """
    poll_interval_ms = max(1, int(poll_interval_ms))
    minimum_observation_ms = max(0, int(minimum_observation_ms))
    quiet_period_ms = max(0, int(quiet_period_ms))
    timeout_ms = max(minimum_observation_ms, int(timeout_ms))

    elapsed_ms = 0
    sample_count = 0
    stable_sample_count = 0
    changes_observed = 0
    last_change_at_ms = 0
    previous_fingerprint = None
    latest = None
    stable = False
    timeline = []
    observed_messages = {}

    while True:
        latest = collect_messages()
        fingerprint = _diagnostic_fingerprint(latest)
        sample_count += 1
        noteworthy = _noteworthy_diagnostic_messages(latest)
        for raw in noteworthy:
            key = _diagnostic_message_key(raw)
            entry = observed_messages.get(key)
            if entry is None:
                entry = dict(raw)
                entry.update({
                    "firstSeenAtMs": elapsed_ms,
                    "lastSeenAtMs": elapsed_ms,
                    "firstSeenSample": sample_count,
                    "lastSeenSample": sample_count,
                    "seenCount": 1,
                })
                observed_messages[key] = entry
            else:
                entry["lastSeenAtMs"] = elapsed_ms
                entry["lastSeenSample"] = sample_count
                entry["seenCount"] = int(entry.get("seenCount", 1) or 1) + 1
        changed = previous_fingerprint is None or fingerprint != previous_fingerprint
        if previous_fingerprint is None:
            stable_sample_count = 1
            last_change_at_ms = elapsed_ms
        elif fingerprint == previous_fingerprint:
            stable_sample_count += 1
        else:
            changes_observed += 1
            stable_sample_count = 1
            last_change_at_ms = elapsed_ms
        if changed:
            snapshot_summary = compile_summary(latest, build_invoked=True)
            timeline.append({
                "sample": sample_count,
                "elapsedMs": elapsed_ms,
                "collectionComplete": bool(latest.get("collectionComplete")),
                "errorCount": int(snapshot_summary.get("errorCount", 0) or 0),
                "warningCount": int(snapshot_summary.get("warningCount", 0) or 0),
                "unknownSeverityCount": int(
                    snapshot_summary.get("unknownSeverityCount", 0) or 0),
                "precompileErrorCount": int(
                    snapshot_summary.get("precompileErrorCount", 0) or 0),
                "precompileWarningCount": int(
                    snapshot_summary.get("precompileWarningCount", 0) or 0),
                "precompileUnknownSeverityCount": int(
                    snapshot_summary.get("precompileUnknownSeverityCount", 0) or 0),
                "messages": noteworthy[:MAX_MESSAGES],
            })
        previous_fingerprint = fingerprint

        quiet_ms = elapsed_ms - last_change_at_ms
        if (elapsed_ms >= minimum_observation_ms and
                quiet_ms >= quiet_period_ms and
                stable_sample_count >= 3):
            stable = True
            break
        if elapsed_ms >= timeout_ms:
            break
        delay_ms = min(poll_interval_ms, timeout_ms - elapsed_ms)
        system.delay(delay_ms)
        elapsed_ms += delay_ms

    summary = compile_summary(latest or {
        "messages": [], "categories": [], "collectionComplete": False,
        "collectionErrors": ["no diagnostic snapshot was collected"],
    }, build_invoked=True)
    summary["diagnosticTimeline"] = timeline
    _apply_observed_diagnostic_history(
        summary, list(observed_messages.values()))
    summary["diagnosticsStable"] = stable
    summary["diagnosticStability"] = {
        "status": "stable" if stable else "timeout",
        "stable": stable,
        "sampleCount": sample_count,
        "stableSampleCount": stable_sample_count,
        "changesObserved": changes_observed,
        "elapsedMs": elapsed_ms,
        "lastChangeAtMs": last_change_at_ms,
        "quietForMs": elapsed_ms - last_change_at_ms,
        "pollIntervalMs": poll_interval_ms,
        "minimumObservationMs": minimum_observation_ms,
        "quietPeriodMs": quiet_period_ms,
        "timeoutMs": timeout_ms,
    }
    if not stable:
        if "diagnostics_not_stable" not in summary["diagnosticGaps"]:
            summary["diagnosticGaps"].append("diagnostics_not_stable")
        summary["compileOk"] = False
    return summary


def _merge_post_build_diagnostic_verification(summary, verification):
    """Merge an independent post-build diagnostic window into one hard gate."""
    if not isinstance(summary, dict) or not isinstance(verification, dict):
        return summary
    primary_messages = list((summary.get("diagnosticHistory") or {}).get("messages", []))
    secondary_messages = list((verification.get("diagnosticHistory") or {}).get("messages", []))
    _apply_observed_diagnostic_history(summary, primary_messages + secondary_messages)
    summary["postBuildVerification"] = verification
    secondary_complete = bool(verification.get("diagnosticsComplete"))
    secondary_stable = verification.get("diagnosticsStable") is True
    secondary_clean = (
        secondary_complete and secondary_stable and
        int(verification.get("errorCount", 0) or 0) == 0 and
        int(verification.get("warningCount", 0) or 0) == 0 and
        int(verification.get("unknownSeverityCount", 0) or 0) == 0 and
        int(verification.get("precompileErrorCount", 0) or 0) == 0 and
        int(verification.get("precompileWarningCount", 0) or 0) == 0 and
        int(verification.get("precompileUnknownSeverityCount", 0) or 0) == 0
    )
    summary["postBuildVerificationPassed"] = bool(secondary_clean)
    # The vendor sometimes reports the compiler result through the stable
    # post-build window while the structured precompile category itself is
    # inactive.  A clean, complete, stable post-build window is authoritative
    # evidence in that case; retain the evidence and clear only this known
    # observation gap so a successful compile is not rolled back as a false
    # negative.
    if secondary_clean and summary.get("diagnosticGaps"):
        summary["diagnosticGaps"] = [gap for gap in summary.get("diagnosticGaps", [])
                                      if gap != "precompile_category_not_observed"]
        summary["precompileStatus"] = "success"
        summary["precompileOk"] = True
        summary["precompileCategoryObserved"] = True
        summary["precompileCategoryActive"] = True
        summary["precompileEvidenceSource"] = "post_build_verification_window"
    if not secondary_stable and "post_build_diagnostics_not_stable" not in summary.get("diagnosticGaps", []):
        summary.setdefault("diagnosticGaps", []).append("post_build_diagnostics_not_stable")
    if not secondary_complete and "post_build_diagnostics_incomplete" not in summary.get("diagnosticGaps", []):
        summary.setdefault("diagnosticGaps", []).append("post_build_diagnostics_incomplete")
    if not secondary_clean and secondary_complete and secondary_stable and "post_build_diagnostics_failed" not in summary.get("diagnosticGaps", []):
        summary.setdefault("diagnosticGaps", []).append("post_build_diagnostics_failed")
    if not secondary_clean:
        summary["compileOk"] = False
    return summary


def _compile_message_hints(summary):
    """Actionable next steps for the compiler diagnostics the model sees.

    Measured 2026-09-19: an ST POU declaring ``pidTest : PID_FIXCYCLE`` made the
    compiler answer only "未知类型: 'PID_FIXCYCLE'" plus a downstream "needs a
    program/function/FB instance" error, with nothing saying that the FB must be
    namespace-qualified (UTIL.PID_FIXCYCLE compiles) or that the providing
    library has to be referenced. The receipt carries that next step now instead
    of leaving the model to guess.
    """
    hints = []
    for message in summary.get("messages") or []:
        text = _text(message.get("text") or message.get("message") or "")
        if not text:
            continue
        if "未知类型" not in text and "unknown type" not in text.lower():
            continue
        symbol = None
        # Vendors quote the qualified name too ("未知类型: 'UTIL.PID_FIXCYCLE'"),
        # so the symbol pattern has to accept dots.
        match = re.search(r"['\"]([A-Za-z_][A-Za-z0-9_.]*)['\"]", text)
        if match is not None:
            symbol = match.group(1)
        hints.append({
            "kind": "unknown_type",
            "symbol": symbol,
            "text": text,
            "next": [
                "call codesys_lad_instruction_signatures with names=[\"%s\"]: it "
                "resolves installed library function blocks and returns the "
                "exact pin table (measured 2026-09-19: PID_FIXCYCLE and PID, "
                "namespace UTIL)" % (symbol or "<symbol>"),
                "an unknown type means the library that provides it is NOT "
                "referenced by this project: add it with codesys_library_add "
                "and re-compile (measured 2026-09-19 in an AM600 project: "
                "PID_FIXCYCLE reported 未知类型 until "
                "\"Util, 3.5.11.0 (System)\" was referenced, then compiled with "
                "0 errors - both bare and UTIL-qualified spellings work once the "
                "library is referenced)",
            ],
        })
    return hints


def _compile_gate_failures(summary, require_zero_warnings=False):
    """Name every condition of the build gate that is not satisfied.

    Measured 2026-09-19 on the InoProShop line: a build with compileOk=true,
    errorCount=0 and diagnosticsComplete=true was reported as "offline build
    failed" with no acceptanceVerdict and no reason - the payload said the
    compile succeeded while the message said it failed. The gate is deliberately
    fail-closed (the precompile category must be OBSERVED, not inferred), so the
    fix is to say which observation is missing instead of only "failed".
    """
    failures = []
    if not isinstance(summary, dict):
        return ["not_a_summary"]
    history_clean = summary.get("diagnosticHistoryClean")
    if history_clean is None:
        history_clean = bool(
            int(summary.get("errorCount", 0) or 0) == 0 and
            int(summary.get("unknownSeverityCount", 0) or 0) == 0)
    if summary.get("diagnosticsStable") is not True:
        failures.append("diagnostics_not_stable")
    if summary.get("diagnosticsComplete") is not True:
        failures.append("diagnostics_incomplete")
    if history_clean is not True:
        failures.append("diagnostic_history_not_clean")
    if not bool(summary.get("precompileTimelineComplete", True)):
        failures.append("precompile_timeline_incomplete")
    if summary.get("compileStatus") != "success":
        failures.append("compile_status_not_success")
    if summary.get("compileOk") is not True:
        failures.append("compile_not_ok")
    if summary.get("precompileStatus") != "success":
        failures.append("precompile_status_not_success")
    if summary.get("precompileOk") is not True:
        failures.append("precompile_not_ok")
    if int(summary.get("errorCount", 0) or 0) != 0:
        failures.append("errors_present")
    if int(summary.get("unknownSeverityCount", 0) or 0) != 0:
        failures.append("unknown_severity_messages")
    if int(summary.get("precompileErrorCount", 0) or 0) != 0:
        failures.append("precompile_errors_present")
    if int(summary.get("precompileUnknownSeverityCount", 0) or 0) != 0:
        failures.append("precompile_unknown_severity_messages")
    if summary.get("diagnosticGaps"):
        failures.append("diagnostic_gaps")
    precompile_observed = summary.get("precompileCategoryObserved")
    precompile_active = summary.get("precompileCategoryActive")
    precompile_evidence = summary.get("precompileEvidenceSource")
    precompile_direct_query_clean = (
        precompile_evidence == "post_build_direct_category_query_clean" and
        summary.get("precompileCategoryQueried") is True and
        summary.get("precompileCategoryInstalled") is True
    )
    precompile_observation_gap = not precompile_direct_query_clean and (
        precompile_observed is False or
        precompile_active is False or
        precompile_evidence in ("none", "post_build_direct_category_query")
    )
    if precompile_observation_gap:
        failures.append("precompile_category_not_observed")
    if require_zero_warnings:
        if int(summary.get("observedWarningCount",
                           summary.get("warningCount", 0)) or 0) != 0:
            failures.append("warnings_present")
        if int(summary.get("observedPrecompileWarningCount",
                           summary.get("precompileWarningCount", 0)) or 0) != 0:
            failures.append("precompile_warnings_present")
    return failures


def _report_build_result(rid, operation, summary):
    """Use identical, fail-closed evidence semantics for every build entry point."""
    try:
        failures = list(_compile_gate_failures(summary))
    except BaseException as exc:
        raise OperationError(
            "the build result could not be evaluated: " + _text(exc),
            "build_gate_evaluation_failed",
            {"mutatedProject": True, "rawVendorMessage": _text(exc),
             "next": {"then": "re-run build.compile; if this repeats, report rawVendorMessage"}})
    if not failures:
        return ok(rid, operation, summary)
    error_kinds = ("errors_present", "compile_not_ok", "compile_status_not_success",
                   "precompile_errors_present", "precompile_status_not_success", "precompile_not_ok")
    has_errors = False
    for name in failures:
        if name in error_kinds:
            has_errors = True
            break
    summary = dict(summary)
    summary["acceptanceVerdict"] = "fail" if has_errors else "inconclusive"
    summary["gateFailures"] = failures
    summary["gatePolicy"] = (
        "fail-closed: certify only complete, stable compiler and precompile evidence; "
        "an unobserved category cannot be inferred clean from an empty query")
    summary["next"] = {"then": (
        "fix the reported errors and re-run build.compile" if has_errors else
        "re-run build.compile; if an observation gap persists, inspect its native category "
        "and report the missing evidence, not a passing build")}
    return fail(rid, operation,
                "offline build failed" if has_errors else
                "build acceptance is inconclusive: " + ", ".join(failures),
                stage="build", data=summary,
                error_code="build_failed" if has_errors else "build_inconclusive")


def _compile_gate_passed(summary, require_zero_warnings=False):
    return not _compile_gate_failures(summary, require_zero_warnings)


def _compile_gate_passed_legacy(summary, require_zero_warnings=False):
    """Apply the same hard diagnostic gate to build and LAD operations."""
    if not isinstance(summary, dict):
        return False
    history_clean = summary.get("diagnosticHistoryClean")
    if history_clean is None:
        history_clean = bool(
            int(summary.get("errorCount", 0) or 0) == 0 and
            int(summary.get("unknownSeverityCount", 0) or 0) == 0)
    timeline_complete = bool(
        summary.get("precompileTimelineComplete", True))
    # A direct category query is not proof that the precompiler ran.  InoProShop
    # can return an empty result for an inactive/unobserved category while the
    # editor still holds parser errors (the previous campaign was promoted on
    # exactly this false-green path).  Fail closed whenever the summary
    # explicitly says the category was not observed or is inactive.
    precompile_observed = summary.get("precompileCategoryObserved")
    precompile_active = summary.get("precompileCategoryActive")
    precompile_evidence = summary.get("precompileEvidenceSource")
    # R052b: the guarded post-build direct query is the only precompile channel
    # SP11 leaves open on the vendor line; when the build path certified it
    # clean (see _build_project) it is not an observation gap.  The unguarded
    # "post_build_direct_category_query" string deliberately stays in the gap
    # list, so a replayed/read-only empty result still fails closed.
    precompile_direct_query_clean = (
        precompile_evidence == "post_build_direct_category_query_clean" and
        summary.get("precompileCategoryQueried") is True and
        summary.get("precompileCategoryInstalled") is True
    )
    precompile_observation_gap = not precompile_direct_query_clean and (
        precompile_observed is False or
        precompile_active is False or
        precompile_evidence in ("none", "post_build_direct_category_query")
    )
    passed = bool(
        summary.get("diagnosticsStable") is True and
        summary.get("diagnosticsComplete") is True and
        history_clean is True and
        timeline_complete and
        summary.get("compileStatus") == "success" and
        summary.get("compileOk") is True and
        summary.get("precompileStatus") == "success" and
        summary.get("precompileOk") is True and
        int(summary.get("errorCount", 0) or 0) == 0 and
        int(summary.get("unknownSeverityCount", 0) or 0) == 0 and
        int(summary.get("precompileErrorCount", 0) or 0) == 0 and
        int(summary.get("precompileUnknownSeverityCount", 0) or 0) == 0 and
        not summary.get("diagnosticGaps") and
        not precompile_observation_gap
    )
    if require_zero_warnings:
        passed = bool(
            passed and int(summary.get(
                "observedWarningCount", summary.get("warningCount", 0)) or 0) == 0 and
            int(summary.get(
                "observedPrecompileWarningCount",
                summary.get("precompileWarningCount", 0)) or 0) == 0
        )
    return passed


def _require_project():
    # The IDE can open a project after the resident bridge starts. Recover the
    # current primary project before rejecting a valid write request.
    if project is None:
        _discover_primary_project()
    if project is None:
        raise OperationError(
            "no project open",
            "project_required",
            {"mutatedProject": False,
             "next": ("open the intended existing project with "
                      "codesys_project_open(path=<absolute project path>), then verify "
                      "projectPath with codesys_project_status before retrying this call. "
                      "If the user requested a new project, first inspect templates and "
                      "installed devices for the selected IDE line, then use that line's "
                      "project-creation tool. This error does not select a vendor or controller.")},
        )


def _children(obj):
    try:
        return list(obj.get_children(False))
    except Exception:
        return []


def _object_type(obj):
    return _text(getattr(obj, "type", ""))


def _object_guid(obj):
    return _text(getattr(obj, "guid", ""))


def _object_summary(obj, path=None):
    declaration = _get_member(
        obj, "textual_declaration", "get_textual_declaration"
    )
    implementation = _get_member(
        obj, "textual_implementation", "get_textual_implementation"
    )
    return {
        "name": _object_name(obj),
        "path": path,
        "type": _object_type(obj),
        "guid": _object_guid(obj),
        "implementationLanguage": _text(
            _get_member(obj, "implementation_language", "get_implementation_language", "")
        ),
        "isFolder": bool(getattr(obj, "is_folder", False)),
        "hasDeclaration": declaration is not None,
        "hasImplementation": implementation is not None,
        "childCount": len(_children(obj)),
    }


def _walk_objects(parent, prefix, depth, max_depth, flat):
    entries = []
    for child in _children(parent):
        name = _object_name(child) or "<unnamed>"
        path = "/".join(prefix + [name])
        summary = _object_summary(child, path)
        flat.append((path, child))
        if depth < max_depth:
            nested = _walk_objects(
                child, prefix + [name], depth + 1, max_depth, flat
            )
            if nested:
                summary["children"] = nested
        entries.append(summary)
    return entries


def _resolve_active_application():
    """Return a buildable Application even when ScriptEngine loses its cache.

    InoProShop can reopen a valid project with ``active_application`` unset
    while the Application remains present in the native/project tree. Calling
    ``build`` with that missing cache reaches the vendor command with an empty
    application name and raises a modal "No application found" dialog. Resolve
    the single buildable tree application before issuing any build command.
    """
    app = _get_member(project, "active_application", "get_active_application")
    try:
        if app is not None and _is_callable(getattr(app, "build", None)):
            return app, {"source": "project.active_application"}
    except Exception:
        pass
    flat = []
    try:
        _walk_objects(project, [], 1, 64, flat)
    except Exception as exc:
        return None, {"source": "project_tree_fallback", "error": repr(exc)}
    candidates = []
    for path, candidate in flat:
        try:
            if (_object_name(candidate).lower() == "application" and
                    _is_callable(getattr(candidate, "build", None))):
                candidates.append((path, candidate))
        except Exception:
            continue
    if len(candidates) == 1:
        return candidates[0][1], {
            "source": "project_tree_fallback",
            "path": candidates[0][0],
            "activeApplicationMissing": app is None,
        }
    return None, {
        "source": "project_tree_fallback",
        "activeApplicationMissing": app is None,
        "candidatePaths": [path for path, _candidate in candidates],
    }


def project_tree(max_depth=6):
    try:
        max_depth = int(max_depth)
    except Exception:
        max_depth = 6
    max_depth = max(1, min(max_depth, 32))
    flat = []
    tree = _walk_objects(project, [], 1, max_depth, flat)
    return {
        "maxDepth": max_depth,
        "count": len(flat),
        "tree": tree,
    }


def symbol_list(req=None):
    """List persisted Symbol Configuration objects without guessing bindings.

    InoProShop may expose no symbol configuration in a freshly-created
    project.  That is a valid empty result, distinct from an API failure.  We
    therefore inspect the live object tree and only classify objects whose
    native name/type identifies them as a symbol configuration.
    """
    _require_project()
    flat = []
    _walk_objects(project, [], 1, 64, flat)
    entries = []
    for path, obj in flat:
        name = _object_name(obj)
        object_type = _object_type(obj)
        runtime_type = ""
        try:
            runtime_type = _text(obj.GetType().FullName)
        except Exception:
            pass
        marker = (name + " " + object_type + " " + runtime_type).lower()
        # InoProShop labels the native object simply "Symbols".  Its stable
        # runtime identity is InoSymbolObject.SymbolConfigObject, so matching
        # only the display name used by stock CODESYS loses persisted configs.
        # The ScriptEngine tree wrapper exposes the native object category as
        # a GUID rather than its CLR type. This is the registered type for
        # Inovance.InoPro.InoSymbolObject.SymbolConfigObject.
        is_vendor_symbol_config = object_type.lower() == (
            "21d4fe94-4123-4e23-9091-ead220afbd1f")
        if ("symbol configuration" not in marker and
                "symbolconfiguration" not in marker and
                "symbolconfigobject" not in marker and
                not is_vendor_symbol_config):
            continue
        entries.append({
            "name": name,
            "path": path,
            "type": object_type,
            "runtimeType": runtime_type,
            "guid": _object_guid(obj),
        })
    return {
        "count": len(entries),
        "configurationPresent": bool(entries),
        "configurations": entries,
        "claims": {
            "treeReadback": True,
            "emptyProjectIsValid": True,
            "configurationBinding": False,
        },
        "status": "found" if entries else "not_present",
    }


SYMBOL_CONFIG_TYPE_GUID = "21d4fe94-4123-4e23-9091-ead220afbd1f"
SYMBOL_CONFIG_FACTORY_GUID = "bcd53c37-9588-42a6-9d92-7d9189ac9595"
SYMBOL_CONFIG_FIELDS = {
    "exportCommentsInXml": ("ExportCommentsInXML", "bool"),
    "supportOpcUa": ("SupportOPCUA", "bool"),
    "addLibrariesToDeviceApplication": ("AddLibrariesToDeviceApplication", "bool"),
    "enableDirectIoAccess": ("EnableDirectIoAccessSetting", "bool"),
}

# These fields exist on the native object, but only exportCommentsInXml has a
# clean InoProShop write/save/reopen/UI/diagnostic closure. Keep reflection
# readback broad and the public mutation contract narrow.
SYMBOL_CONFIG_WRITE_FIELDS = {
    "exportCommentsInXml": SYMBOL_CONFIG_FIELDS["exportCommentsInXml"],
}


def _symbol_config_member(value, name):
    return _get_member(value, name, "get_" + name)


def _symbol_config_target(req):
    req = req or {}
    target = _text(req.get("target") or req.get("symbol") or req.get("path")).strip()
    if target:
        candidate, candidate_path = find_project_object(target)
        if _object_type(candidate).lower() != SYMBOL_CONFIG_TYPE_GUID:
            raise OperationError("target is not an InoProShop Symbol Configuration",
                                 "symbol_configuration_target_invalid",
                                 {"target": target, "path": candidate_path,
                                  "type": _object_type(candidate)})
        return candidate, candidate_path
    entries = symbol_list(req).get("configurations", [])
    if not entries:
        raise OperationError("project has no Symbol Configuration",
                             "symbol_configuration_not_present")
    if len(entries) != 1:
        raise OperationError("multiple Symbol Configurations require exact target",
                             "symbol_configuration_target_ambiguous",
                             {"count": len(entries), "paths": [entry["path"] for entry in entries]})
    return find_project_object(entries[0]["path"])


def _native_symbol_config(req=None, access="read"):
    """Resolve the persisted vendor SymbolConfigObject through ObjectMgr.

    ScriptEngine is used only to resolve the tree object. The returned native
    object is the exact Inovance SymbolConfigObject whose settings the editor
    reads and writes. This deliberately excludes ScriptEngine's orphaning
    create_symbol_config extension.
    """
    import System

    script_object, path = _symbol_config_target(req)
    requested_guid = _object_guid(script_object)
    if not requested_guid:
        raise OperationError("Symbol Configuration has no tree GUID",
                             "symbol_configuration_guid_unavailable",
                             {"path": path})
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    getter = object_mgr.GetObjectToModify if access == "modify" else object_mgr.GetObjectToRead
    candidates = []

    def inspect(guid):
        try:
            meta = getter(handle, System.Guid(_text(guid)))
            native = _symbol_config_member(meta, "Object") if meta is not None else None
            runtime_type = _text(native.GetType().FullName) if native is not None else ""
            if (runtime_type.endswith(".SymbolConfigObject") or
                    runtime_type == "Inovance.InoPro.InoSymbolObject.SymbolConfigObject"):
                candidates.append((guid, meta, native, runtime_type))
        except Exception:
            pass

    inspect(requested_guid)
    if not candidates:
        # Recover only the unique native object with the same tree name and
        # registered SymbolConfig type. Never select a type-only candidate.
        wanted_name = _object_name(script_object).lower()
        try:
            for guid in list(object_mgr.GetAllObjects(handle)):
                stub = object_mgr.GetMetaObjectStub(handle, guid)
                if (stub is None or _text(_symbol_config_member(stub, "Name")).lower() != wanted_name or
                        _text(_symbol_config_member(stub, "ObjectType")).lower() != SYMBOL_CONFIG_TYPE_GUID):
                    continue
                inspect(guid)
        except Exception as exc:
            raise OperationError("could not enumerate native Symbol Configurations",
                                 "symbol_configuration_enumeration_failed",
                                 {"path": path, "cause": repr(exc)})
    unique = {}
    for item in candidates:
        unique[_text(item[0]).lower()] = item
    candidates = list(unique.values())
    if len(candidates) != 1:
        raise OperationError("tree target does not resolve to one native Symbol Configuration",
                             "symbol_configuration_native_binding_unavailable",
                             {"path": path, "requestedGuid": requested_guid,
                              "candidateCount": len(candidates), "access": access})
    guid, meta, native, runtime_type = candidates[0]
    return object_mgr, meta, native, {
        "path": path,
        "guid": requested_guid,
        "nativeGuid": _text(guid),
        "projectHandle": handle,
        "objectRuntimeType": runtime_type,
        "access": access,
        "binding": "ObjectMgr.GetObjectTo%s(SymbolConfigObject)" %
                   ("Modify" if access == "modify" else "Read"),
    }


def _symbol_config_snapshot(native, binding):
    settings = {}
    for public_name, (native_name, kind) in SYMBOL_CONFIG_FIELDS.items():
        value = _symbol_config_member(native, native_name)
        settings[public_name] = bool(value) if kind == "bool" else _json_safe(value)
    flags = _symbol_config_member(native, "ContentFeatureFlags")
    try:
        flags = int(flags)
    except Exception:
        flags = _json_safe(flags)
    calculators = []
    known = _symbol_config_member(native, "KnownClientSideLayoutCalculators")
    try:
        for calculator in known or []:
            calculators.append({
                "guid": _text(_symbol_config_member(calculator, "TypeGuid")),
                "name": _text(_symbol_config_member(calculator, "Name")),
            })
    except Exception as exc:
        calculators = [{"readError": repr(exc)}]
    return {
        "path": binding["path"],
        "guid": binding["guid"],
        "nativeGuid": binding["nativeGuid"],
        "projectHandle": binding["projectHandle"],
        "objectRuntimeType": binding["objectRuntimeType"],
        "settings": settings,
        "contentFeatureFlags": flags,
        "clientSideLayoutCalculator": _text(_symbol_config_member(native, "ClientSideLayoutCalculator")),
        "symbolConfigWithinApplication": bool(_symbol_config_member(native, "SymbolConfigWithinApplication")),
        "knownClientSideLayoutCalculators": calculators,
        "mutatedProject": False,
        "status": "observed",
    }


def symbol_config_probe(req=None):
    _object_mgr, _meta, native, binding = _native_symbol_config(req, "read")
    snapshot = _symbol_config_snapshot(native, binding)
    snapshot["claims"] = {
        "persistedNativeObject": True,
        "editorSettingReadback": True,
        "methodInvoked": False,
        "projectMutationVerified": False,
    }
    return snapshot


def symbol_configure(req):
    req = req or {}
    if req.get("confirm") != "configure_symbol_configuration":
        raise OperationError("confirm must exactly equal configure_symbol_configuration",
                             "confirmation_required")
    _require_current_disposable_project(req, "symbol.configure")
    supplied = req.get("settings")
    if not isinstance(supplied, dict) or not supplied:
        raise OperationError("symbol.configure requires non-empty settings object",
                             "invalid_argument", {"path": "settings"})
    unsupported = sorted(set(supplied.keys()) - set(SYMBOL_CONFIG_WRITE_FIELDS.keys()))
    if unsupported:
        raise OperationError("Symbol Configuration contains unsupported settings",
                             "invalid_argument", {"path": "settings", "unsupported": unsupported,
                              "supported": sorted(SYMBOL_CONFIG_WRITE_FIELDS.keys())})
    object_mgr, meta, native, binding = _native_symbol_config(req, "modify")
    before = _symbol_config_snapshot(native, binding)
    changes = []
    for public_name in sorted(supplied.keys()):
        native_name, kind = SYMBOL_CONFIG_WRITE_FIELDS[public_name]
        requested = supplied[public_name]
        if kind == "bool" and not isinstance(requested, bool):
            raise OperationError("Symbol Configuration setting must be boolean",
                                 "invalid_argument", {"path": "settings." + public_name,
                                                      "expected": "boolean"})
        previous = _symbol_config_member(native, native_name)
        try:
            setattr(native, native_name, requested)
        except Exception as exc:
            raise OperationError("could not set Symbol Configuration setting",
                                 "symbol_configuration_write_failed",
                                 {"path": "settings." + public_name, "cause": repr(exc)})
        after_set = _symbol_config_member(native, native_name)
        if bool(after_set) != requested:
            raise OperationError("Symbol Configuration rejected the requested value",
                                 "symbol_configuration_write_not_retained",
                                 {"path": "settings." + public_name,
                                  "requested": requested, "afterSet": _json_safe(after_set)})
        changes.append({"path": "settings." + public_name,
                        "before": bool(previous), "requested": requested,
                        "afterSet": bool(after_set)})
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed", "symbol_configuration_commit_failed",
                             {"before": before, "changes": changes, "cause": repr(exc)})
    _read_mgr, _read_meta, rebound_native, rebound_binding = _native_symbol_config(req, "read")
    after = _symbol_config_snapshot(rebound_native, rebound_binding)
    mismatches = [change for change in changes if after["settings"].get(
        change["path"].split(".", 1)[1]) != change["requested"]]
    if mismatches:
        raise OperationError("Symbol Configuration commit did not retain every value",
                             "symbol_configuration_commit_not_retained",
                             {"before": before, "after": after, "changes": changes,
                              "mismatches": mismatches, "commitReturn": _json_safe(commit_return)})
    readback_settings = dict(
        (name, after["settings"].get(name)) for name in sorted(supplied.keys()))
    return {
        "input": {"target": rebound_binding["path"],
                  "settings": dict(supplied)},
        "before": before,
        "after": after,
        "readbackSettings": readback_settings,
        "changes": changes,
        "commitReturn": _json_safe(commit_return),
        "binding": rebound_binding,
        "mutatedProject": True,
        "committed": True,
        "exactReadback": True,
        "status": "committed_same_process_requires_save_reopen_gate",
        "limits": [
            "does not create an orphan ScriptEngine configuration",
            "does not select individual export variables or invoke online download",
            "save, fresh-process reopen, compilation, diagnostics, and UI evidence are separate gates",
        ],
    }


def _legacy_scriptengine_symbol_create_config(req):
    """Fail closed until the native Symbol factory create route is closed.

    The previous ScriptEngine extension is retained below only as forensic
    evidence for the rejected route. It returned an orphan object that never
    reached the InoProShop project tree, so it must not be invoked again.
    """
    req = req or {}
    if not bool(req.get("disposable")):
        raise OperationError("symbol.create_config requires disposable=true",
                             "disposable_required")
    if _text(req.get("confirm")).strip() != "create_symbol_configuration":
        raise OperationError(
            "symbol.create_config requires confirm=create_symbol_configuration",
            "confirmation_required")
    raise OperationError(
        "Symbol Configuration creation is blocked until the native ObjectMgr factory path "
        "has a clean-project save/reopen/UI/compile closure; the rejected ScriptEngine "
        "route is never invoked",
        "symbol_configuration_creation_requires_runtime_validation",
        {
            "mutatedProject": False,
            "rejectedBinding": "IScriptApplicationSymbolConfigExtension.create_symbol_config",
            "rejectedReason": "returned object was absent from project tree and UI",
            "nativeFactory": {
                "guid": SYMBOL_CONFIG_FACTORY_GUID,
                "runtimeType": "Inovance.InoPro.InoSymbolObject.SymbolConfigObjectFactory",
                "requiredParent": "Application",
                "requiredPostCreate": "ObjectCreated(projectHandle, objectGuid, batchArguments)",
            },
            "requiredEvidence": [
                "clean disposable AM600 project",
                "ObjectMgr AddObject tree readback",
                "same-session UI tree screenshot",
                "save and fresh IDE process reopen",
                "compiler, precompile, and library diagnostics",
            ],
        })
    _require_project()
    app = _get_member(project, "active_application", "get_active_application")
    if app is None:
        raise OperationError("active application is unavailable",
                             "application_unavailable")
    try:
        create = getattr(app, "create_symbol_config")
    except Exception:
        create = None
    create_method = None
    binding = "IScriptApplicationSymbolConfigExtension.create_symbol_config"
    provider = None
    if create is None:
        # InoProShop loads the official SymbolConfig ScriptDriver but does not
        # register it in the profile extension table. Bind the concrete
        # driver to the live ScriptApplication object exactly as its one-arg
        # constructor requires, rather than fabricating a generic object.
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Static |
                 System.Reflection.BindingFlags.Public |
                 System.Reflection.BindingFlags.NonPublic)
        base_object = None
        try:
            import clr
            wrapper_clr = clr.GetClrType(type(app))
            base_prop = wrapper_clr.GetProperty("BaseObject", flags)
            base_object = base_prop.GetValue(app, None) if base_prop is not None else None
        except Exception:
            base_object = _get_member(app, "BaseObject", "get_BaseObject")
        constructor_candidates = [
            ("application", app),
            ("application.Extender", _get_member(app, "Extender", "get_Extender")),
            ("application.BaseObject", base_object),
        ]
        try:
            import clr
            script_object_type = System.Type.GetType(
                "_3S.CoDeSys.ScriptEngine.BasicFunctionality.IScriptObject, ScriptEngine")
            if script_object_type is not None:
                constructor_candidates.append(("application.clr.IScriptObject",
                                                clr.Convert(app, script_object_type)))
        except Exception:
            pass
        for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
            if "scriptdriversymbolconfigobject" not in _text(assembly.FullName).lower():
                continue
            try:
                extension_type = assembly.GetType(
                    "_3S.CoDeSys.ScriptDriverSymbolConfigObject.ScriptApplicationSymbolConfigExtension")
                if extension_type is not None:
                    constructors = extension_type.GetConstructors()
                    if not constructors:
                        raise RuntimeError("Symbol Configuration extension has no public constructor")
                    for candidate_label, candidate in constructor_candidates:
                        if candidate is None:
                            continue
                        try:
                            provider = constructors[0].Invoke(System.Array[System.Object]([candidate]))
                            try:
                                create = getattr(provider, "create_symbol_config")
                            except Exception:
                                create = None
                            if create is None:
                                for method in provider.GetType().GetMethods(flags):
                                    if _text(method.Name) == "create_symbol_config" and len(method.GetParameters()) == 3:
                                        create_method = method
                                        create = True
                                        break
                            binding = "ScriptDriverSymbolConfigObject.ScriptApplicationSymbolConfigExtension(" + candidate_label + ").create_symbol_config"
                            if create is not None:
                                break
                        except Exception:
                            provider = None
                            create = None
                    if create is not None:
                        break
            except Exception:
                continue
    if create is None:
        raise OperationError(
            "IScriptApplicationSymbolConfigExtension.create_symbol_config is unavailable",
            "symbol_configuration_binding_unavailable",
            {"mutatedProject": False, "existing": symbol_list(req),
             "concreteProviderConstructed": provider is not None})
    export_comments = bool(req.get("exportCommentsToXml", False))
    support_opc_ua = bool(req.get("supportOpcUa", False))
    client_guid = req.get("clientSideLayoutCalculator")
    import System
    try:
        client_guid = System.Guid(client_guid) if client_guid else System.Guid.Empty
    except Exception:
        raise OperationError("clientSideLayoutCalculator must be a GUID",
                             "invalid_argument")
    before = symbol_list(req)
    try:
        if create_method is not None:
            created = create_method.Invoke(provider, System.Array[System.Object]([
                export_comments, support_opc_ua, client_guid]))
        else:
            created = create(export_comments, support_opc_ua, client_guid)
    except Exception as exc:
        chain = []
        current = exc
        for _index in range(8):
            if current is None:
                break
            entry = {"type": _text(current.GetType().FullName)
                     if hasattr(current, "GetType") else _text(type(current)),
                     "message": _text(current)}
            try:
                entry["stackTrace"] = _text(current.StackTrace)
            except Exception:
                pass
            chain.append(entry)
            try:
                current = current.InnerException
            except Exception:
                current = None
        message = _text(exc)
        parent_unsupported = (u"不接受符号配置对象" in message or
                              "does not accept symbol configuration" in message.lower())
        raise OperationError(
            "create_symbol_config invocation failed: " + repr(exc),
            "symbol_configuration_parent_unsupported" if parent_unsupported
            else "symbol_configuration_create_failed",
            {"mutatedProject": False, "before": before,
             "binding": binding, "exceptionChain": chain,
             "parentSupportsSymbolConfiguration": False if parent_unsupported else None})
    created_summary = None
    if created is not None:
        try:
            created_summary = _object_summary(created)
        except Exception as exc:
            created_summary = {"summaryError": repr(exc),
                               "runtimeType": _text(created.GetType().FullName)
                               if hasattr(created, "GetType") else None}
    after = symbol_list(req)
    if not after.get("configurationPresent"):
        raise OperationError(
            "create_symbol_config returned but no Symbol Configuration is visible in the project tree",
            "symbol_configuration_tree_readback_mismatch",
            {"mutatedProject": True, "before": before, "returned": created_summary,
             "after": after})
    return {
        "created": True,
        "mutatedProject": True,
        "binding": binding,
        "arguments": {"exportCommentsToXml": export_comments,
                       "supportOpcUa": support_opc_ua,
                       "clientSideLayoutCalculator": _text(client_guid)},
        "returned": created_summary,
        "before": before,
        "after": after,
        "status": "created_same_process_requires_restart_gate",
        "claims": {"official_scriptengine_binding": True,
                    "treeReadback": True,
                    "saveReopenPersistence": False},
    }


def _symbol_config_factory_preflight():
    """Resolve the one supported native Symbol Configuration creation route."""
    import System

    parent, parent_path = find_project_object("Application")
    parent_guid = _object_guid(parent)
    if not parent_guid:
        raise OperationError("Application has no project-tree GUID",
                             "symbol_configuration_parent_guid_unavailable",
                             {"path": parent_path})
    existing = symbol_list().get("configurations", [])
    if existing:
        raise OperationError(
            "Application already has a Symbol Configuration; creation is single-instance only",
            "symbol_configuration_already_exists",
            {"existing": existing, "mutatedProject": False},
        )
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    manager = _get_member(object_mgr, "ObjectFactoryManager", "get_ObjectFactoryManager")
    if manager is None:
        raise OperationError("ObjectFactoryManager is unavailable",
                             "object_factory_manager_unavailable")
    try:
        factory = manager.GetFactory(System.Guid(SYMBOL_CONFIG_FACTORY_GUID))
    except Exception as exc:
        raise OperationError("native Symbol Configuration factory lookup failed",
                             "symbol_configuration_factory_lookup_failed",
                             {"factoryGuid": SYMBOL_CONFIG_FACTORY_GUID,
                              "cause": repr(exc)})
    runtime_type = _text(factory.GetType().FullName) if factory is not None else ""
    if runtime_type != "Inovance.InoPro.InoSymbolObject.SymbolConfigObjectFactory":
        raise OperationError("loaded Symbol Configuration factory is not the exact Inovance factory",
                             "symbol_configuration_factory_identity_mismatch",
                             {"factoryGuid": SYMBOL_CONFIG_FACTORY_GUID,
                              "runtimeType": runtime_type,
                              "mutatedProject": False})
    handle = _trace_project_handle()
    try:
        parent_meta = object_mgr.GetObjectToRead(handle, System.Guid(parent_guid))
        parent_native = _get_member(parent_meta, "Object", "get_Object")
    except Exception as exc:
        raise OperationError("could not read native Application parent",
                             "symbol_configuration_parent_read_failed",
                             {"path": parent_path, "guid": parent_guid,
                              "cause": repr(exc)})
    if parent_native is None:
        raise OperationError("native Application parent is unavailable",
                             "symbol_configuration_parent_unavailable",
                             {"path": parent_path, "guid": parent_guid})
    accept_method = None
    for method in factory.GetType().GetMethods():
        if _text(method.Name) == "AcceptsParentObject" and len(method.GetParameters()) == 1:
            accept_method = method
            break
    if accept_method is None:
        raise OperationError("Symbol Configuration factory has no parent acceptance binding",
                             "symbol_configuration_parent_check_unavailable",
                             {"path": parent_path, "guid": parent_guid,
                              "factoryRuntimeType": runtime_type})
    try:
        accepts_parent = bool(accept_method.Invoke(
            factory, System.Array[System.Object]([parent_native])))
    except Exception as exc:
        raise OperationError("Symbol Configuration parent acceptance check failed",
                             "symbol_configuration_parent_check_failed",
                             {"path": parent_path, "guid": parent_guid,
                              "factoryRuntimeType": runtime_type,
                              "binding": _text(accept_method.ToString()),
                              "cause": repr(exc)})
    if not accepts_parent:
        raise OperationError("native Symbol Configuration factory rejects Application parent",
                             "symbol_configuration_parent_unsupported",
                             {"path": parent_path, "guid": parent_guid,
                              "factoryRuntimeType": runtime_type,
                              "mutatedProject": False})
    return {
        "parent": parent_path,
        "parentGuid": parent_guid,
        "projectHandle": handle,
        "factoryGuid": SYMBOL_CONFIG_FACTORY_GUID,
        "factoryRuntimeType": runtime_type,
        "acceptsParentObject": True,
        "existingConfigurationCount": 0,
    }


def symbol_create_config(req):
    """Create the single native Application Symbols object through ObjectMgr.

    This deliberately does not invoke the ScriptEngine extension retained above:
    that route returned an unreachable orphan in the tested InoProShop profile.
    Empty batch arguments are required for the initial closure because they map
    to the documented default factory state and the matching post-create path.
    """
    req = req or {}
    if req.get("confirm") != "create_symbol_configuration":
        raise OperationError("symbol.create_config requires confirm=create_symbol_configuration",
                             "confirmation_required")
    _require_current_disposable_project(req, "symbol.create_config")
    supplied_name = _text(req.get("name") or "Symbols").strip()
    supplied_parent = _text(req.get("parent") or "Application").strip()
    if supplied_name != "Symbols":
        raise OperationError("native Symbol Configuration name must be Symbols",
                             "symbol_configuration_name_invalid",
                             {"actual": supplied_name, "expected": "Symbols"})
    if supplied_parent != "Application":
        raise OperationError("native Symbol Configuration parent must be Application",
                             "symbol_configuration_parent_invalid",
                             {"actual": supplied_parent, "expected": "Application"})
    settings = req.get("settings")
    if settings is not None:
        if not isinstance(settings, dict) or not settings:
            raise OperationError("settings must be a non-empty object when supplied",
                                 "invalid_argument", {"path": "settings"})
        unsupported = sorted(set(settings.keys()) - set(SYMBOL_CONFIG_WRITE_FIELDS.keys()))
        if unsupported:
            raise OperationError("Symbol Configuration contains unsupported settings",
                                 "invalid_argument", {"path": "settings",
                                                      "unsupported": unsupported,
                                                      "supported": sorted(SYMBOL_CONFIG_WRITE_FIELDS.keys())})
        if any(not isinstance(value, bool) for value in settings.values()):
            raise OperationError("Symbol Configuration settings must be booleans",
                                 "invalid_argument", {"path": "settings"})
    preflight = _symbol_config_factory_preflight()
    created = vendor_object_factory_create({
        "factoryGuid": SYMBOL_CONFIG_FACTORY_GUID,
        "name": "Symbols",
        "parent": "Application",
        "batchArguments": [],
        "postCreate": True,
        "disposable": True,
        "confirm": "vendor_object_factory_create",
    })
    created_path = created.get("treePath")
    if not created_path:
        raise OperationError("native Symbol Configuration creation has no tree path",
                             "symbol_configuration_tree_readback_mismatch",
                             {"created": created, "mutatedProject": True})
    native_snapshot = symbol_config_probe({"target": created_path})
    if native_snapshot.get("objectRuntimeType") != (
            "Inovance.InoPro.InoSymbolObject.SymbolConfigObject"):
        raise OperationError("created object is not the expected native Symbol Configuration",
                             "symbol_configuration_native_identity_mismatch",
                             {"created": created, "native": native_snapshot,
                              "mutatedProject": True})
    configure = None
    if settings:
        configure = symbol_configure({
            "target": created_path,
            "settings": settings,
            "confirm": "configure_symbol_configuration",
            "disposable": True,
        })
        native_snapshot = configure["after"]
    requested_settings = dict(settings or {})
    readback_settings = dict(
        (name, native_snapshot["settings"].get(name))
        for name in sorted(requested_settings.keys()))
    return {
        "input": {"name": "Symbols", "parent": "Application",
                  "settings": requested_settings},
        "created": True,
        "creation": created,
        "preflight": preflight,
        "nativeReadback": native_snapshot,
        "settingsCommit": configure,
        "batchArguments": [],
        "mutatedProject": True,
        "exactSettingsReadback": readback_settings == requested_settings,
        "readbackSettings": readback_settings,
        "status": "created_same_process_requires_ui_save_reopen_compile_gate",
        "nextRequired": [
            "refresh and reveal Symbols in the native navigator, then capture an immediate screenshot",
            "save, close, and reopen in a fresh IDE process before treating creation as persistent",
            "compile and inspect compiler, precompile, and library-manager diagnostics",
            "a symbol pragma can be written through pou.add_symbol_pragma, but generated export content and online symbol availability require separate evidence",
        ],
        "limits": [
            "only one Application-level Symbols object is supported",
            "only the empty string[] creation batch is used",
            "does not create variable export selections, OPC UA communication, or online downloads",
        ],
    }


def symbol_binding_probe(req=None):
    """Read the concrete Symbol Configuration extension binding topology."""
    _require_project()
    import System
    app = _get_member(project, "active_application", "get_active_application")
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    extension_type = None
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        if "scriptdriversymbolconfigobject" not in _text(assembly.FullName).lower():
            continue
        try:
            extension_type = assembly.GetType(
                "_3S.CoDeSys.ScriptDriverSymbolConfigObject.ScriptApplicationSymbolConfigExtension")
        except Exception:
            extension_type = None
        if extension_type is not None:
            break
    constructor_probe = []
    if extension_type is not None and app is not None:
        try:
            constructors = extension_type.GetConstructors()
            base_probe = None
            try:
                import clr
                base_prop = clr.GetClrType(type(app)).GetProperty("BaseObject", flags)
                base_probe = base_prop.GetValue(app, None) if base_prop is not None else None
            except Exception:
                base_probe = _get_member(app, "BaseObject", "get_BaseObject")
            probe_candidates = [("application", app),
                               ("application.Extender", _get_member(app, "Extender", "get_Extender")),
                               ("application.BaseObject", base_probe)]
            try:
                import clr
                script_object_type = System.Type.GetType(
                    "_3S.CoDeSys.ScriptEngine.BasicFunctionality.IScriptObject, ScriptEngine")
                probe_candidates.append(("application.clr.IScriptObject",
                                         clr.Convert(app, script_object_type)))
            except Exception:
                pass
            for label, candidate in probe_candidates:
                try:
                    provider_probe = constructors[0].Invoke(System.Array[System.Object]([candidate]))
                    constructor_probe.append({"binding": "constructor(" + label + ")", "ok": True,
                                              "runtimeType": _text(provider_probe.GetType().FullName)})
                except Exception as exc:
                    constructor_probe.append({"binding": "constructor(" + label + ")", "ok": False,
                                              "error": repr(exc)})
        except Exception as exc:
            constructor_probe.append({"binding": "constructor_metadata", "ok": False,
                                      "error": repr(exc)})

    wrapper_members = []
    wrapper_values = []
    wrapper_clr = None
    wrapper_fields = []
    try:
        wrapper_members = sorted(_text(item) for item in dir(app))[:500]
        for name in wrapper_members:
            lowered = name.lower()
            if not any(token in lowered for token in
                       ("base", "object", "inner", "value", "extend", "script", "raw")):
                continue
            try:
                value = getattr(app, name)
                wrapper_values.append({
                    "name": name,
                    "runtimeType": _text(value.GetType().FullName)
                    if value is not None and hasattr(value, "GetType") else _text(type(value)),
                    "callable": bool(hasattr(value, "__call__")),
                })
            except Exception as exc:
                wrapper_values.append({"name": name, "readError": repr(exc)})
    except Exception as exc:
        wrapper_members = ["<dir-error> " + repr(exc)]
    try:
        import clr
        wrapper_clr = clr.GetClrType(type(app))
    except Exception:
        try:
            wrapper_clr = app.__class__.__clrtype__()
        except Exception as exc:
            wrapper_fields.append({"binding": "wrapper_clr_type", "error": repr(exc)})
    if wrapper_clr is not None:
        try:
            for field in wrapper_clr.GetFields(flags):
                entry = {"name": _text(field.Name), "type": _text(field.FieldType.FullName),
                         "public": bool(field.IsPublic), "private": bool(field.IsPrivate)}
                try:
                    value = field.GetValue(app)
                    entry["valueRuntimeType"] = _text(value.GetType().FullName) if value is not None else None
                except Exception as exc:
                    entry["readError"] = repr(exc)
                wrapper_fields.append(entry)
            for prop in wrapper_clr.GetProperties(flags):
                entry = {"name": _text(prop.Name), "type": _text(prop.PropertyType.FullName),
                         "property": True}
                try:
                    value = prop.GetValue(app, None)
                    entry["valueRuntimeType"] = _text(value.GetType().FullName) if value is not None else None
                except Exception as exc:
                    entry["readError"] = repr(exc)
                wrapper_fields.append(entry)
        except Exception as exc:
                wrapper_fields.append({"binding": "wrapper_reflection", "error": repr(exc)})

    def describe_type(value):
        if value is None:
            return None
        result = {"runtimeType": _text(value.FullName), "interfaces": [],
                  "constructors": [], "members": []}
        try:
            result["interfaces"] = sorted(_text(item.FullName)
                                          for item in value.GetInterfaces())
        except Exception as exc:
            result["interfacesError"] = repr(exc)
        try:
            for ctor in value.GetConstructors(flags):
                result["constructors"].append(_text(ctor.ToString()))
        except Exception as exc:
            result["constructorsError"] = repr(exc)
        try:
            for method in value.GetMethods(flags):
                name = _text(method.Name)
                if name.lower() in ("create_symbol_config", "get_extender", "get_object"):
                    result["members"].append(_text(method.ToString()))
        except Exception as exc:
            result["membersError"] = repr(exc)
        try:
            result["properties"] = [_text(item.ToString()) for item in value.GetProperties(flags)
                                    if any(token in _text(item.Name).lower()
                                           for token in ("object", "inner", "base", "value", "script", "extend"))][:100]
            result["fields"] = [_text(item.ToString()) for item in value.GetFields(flags)
                                if any(token in _text(item.Name).lower()
                                       for token in ("object", "inner", "base", "value", "script", "extend"))][:100]
        except Exception as exc:
            result["propertiesError"] = repr(exc)
        return result

    return {
        "readOnly": True,
        "mutatedProject": False,
        "application": describe_type(app.GetType()) if app is not None else None,
        "wrapperPythonType": _text(type(app)),
        "wrapperClrType": _text(wrapper_clr.FullName) if wrapper_clr is not None else None,
        "wrapperMembers": wrapper_members,
        "wrapperCandidateValues": wrapper_values,
        "wrapperFields": wrapper_fields,
        "extension": describe_type(extension_type),
        "constructorProbe": constructor_probe,
        "directApplicationMethod": bool(app is not None and
                                          _get_member(app, "create_symbol_config") is not None),
        "status": "observed" if extension_type is not None else "unavailable",
    }


def installation_binding_unavailable(req, operation):
    """Common fail-closed response for system/repository mutation operations."""
    req = req or {}
    name = req.get("name") or req.get("library") or req.get("package")
    data = {
        "operation": operation,
        "mutatedProject": False,
        "installationAttempted": False,
        "binding": "unavailable",
        "requested": name,
        "next": "call __host.library.installation_sources before selecting an official package",
    }
    raise OperationError(
        operation + " has no verified InoProShop installation binding; nothing was changed",
        "installation_binding_unavailable", data)


def _hmi_resource_kind(obj):
    """Duck-type the marker interfaces the official dump documents.

    IScriptTextListObject / IScriptImagePoolObject are marker-based interfaces
    whose concrete objects never appear in the dump's type list, so the object
    in the project tree is classified by the members it actually carries.
    """
    text_list = (hasattr(obj, "addlanguage") or hasattr(obj, "add_language")) and (
        hasattr(obj, "rows") or hasattr(obj, "get_rows"))
    image_pool = hasattr(obj, "images") and (
        hasattr(obj, "download_only_used_images")
        or hasattr(obj, "get_download_only_used_images"))
    if text_list:
        return "textList"
    if image_pool:
        return "imagePool"
    return None


def project_hmi_resources(normalized):
    """Read-only: which objects in this project carry text lists / image pools."""
    _require_project()
    flat = []
    _walk_objects(project, [], 1, 64, flat)
    found = []
    for path, obj in flat:
        kind = _hmi_resource_kind(obj)
        if kind is None:
            continue
        found.append({
            "path": _text(path),
            "name": _text(_object_name(obj)),
            "kind": kind,
            "type": _text(type(obj)),
        })
    return {
        "count": len(found),
        "objects": found,
        "boundary": "Read-only scan of the project tree for the documented "
                    "text-list / image-pool surfaces. A project with no "
                    "visualization may legitimately report zero objects - that "
                    "is not an error, it means there is nothing to read yet.",
    }


def debug_textlist_container_probe(normalized=None):
    """Read the documented TextList container extension on Project/Application.

    ``system.dump_scripting_api()`` declares IScriptTextListObjectContainer as
    an extension for every Project and Application object.  The CLR wrapper's
    concrete type does not list those members, so test the live ScriptEngine
    extension binding directly without creating or changing a text list.
    """
    _require_project()
    application = _get_member(project, "active_application",
                              "get_active_application", None)
    application_path = None
    if application is None:
        try:
            application, application_path = find_project_object("Application")
        except Exception:
            application = None

    def describe(label, value, path=None):
        if value is None:
            return {
                "label": label,
                "available": False,
                "path": path,
            }
        members = {}
        for name in ("create_textlist", "get_global_textlist",
                     "has_global_textlist"):
            try:
                member = getattr(value, name)
                members[name] = {
                    "available": True,
                    "callable": bool(hasattr(member, "__call__")),
                    "runtimeType": _text(type(member)),
                }
            except Exception as exc:
                members[name] = {
                    "available": False,
                    "error": repr(exc),
                }
        has_global = None
        if members["has_global_textlist"]["available"]:
            try:
                has_global = bool(_get_member(
                    value, "has_global_textlist", "get_has_global_textlist", False))
            except Exception:
                has_global = None
        return {
            "label": label,
            "available": True,
            "path": path,
            "name": _object_name(value),
            "runtimeType": _text(type(value)),
            "members": members,
            "reflectedTextMembers": _member_names(
                value, ["textlist", "text_list", "language"]),
            "hasGlobalTextList": has_global,
        }

    return {
        "project": describe("project", project, _project_path()),
        "application": describe("application", application, application_path),
        "readOnly": True,
        "mutatedProject": False,
        "officialContract": "IScriptTextListObjectContainer",
    }


def _collection_rows(collection, row_reader, limit=500):
    """Read a vendor collection that exposes Item/__len__ but may not iterate."""
    count = None
    try:
        count = int(len(collection))
    except Exception:
        try:
            count = int(collection.__len__())
        except Exception:
            count = None
    rows = []
    if count is not None:
        for index in range(min(count, limit)):
            try:
                item = collection[index]
            except Exception:
                try:
                    item = collection.Item[index]
                except Exception:
                    break
            rows.append(row_reader(item))
        return rows, count
    try:
        for item in collection:
            if len(rows) >= limit:
                break
            rows.append(row_reader(item))
    except Exception:
        pass
    return rows, len(rows)


def _text_list_object(normalized):
    target = _text(normalized.get("target") or "").strip()
    if not target:
        raise OperationError(
            "target is required", "invalid_argument",
            {"next": {"tool": "codesys_project_hmi_resources",
                      "then": "call it first to list the objects that carry a "
                              "text list, then pass one exact path"}})
    obj, path = find_project_object(target)
    kind = _hmi_resource_kind(obj)
    if kind != "textList":
        raise OperationError(
            "'%s' is not a text list object" % target,
            "not_a_text_list",
            {"target": target, "resolvedPath": _text(path),
             "resolvedKind": kind, "objectType": _text(type(obj)),
             "members": _member_names(obj, ["text", "language", "row", "id"]),
             "next": {"tool": "codesys_project_hmi_resources",
                      "then": "pass the path of an object whose kind is textList"}})
    return obj, _text(path)


def _textlist_languages(obj):
    languages = []
    try:
        count = int(_get_member(obj, "languagecount", "languagecount", 0))
        for index in range(min(count, 50)):
            languages.append(_text(_call_with_args(obj, "getlanguage", [index])))
    except Exception as exc:
        languages = ["<language read failed: " + _text(exc) + ">"]
    return languages


def _textlist_rows_collection(obj):
    collection = _get_member(obj, "rows", "get_rows", None)
    if collection is None:
        raise OperationError(
            "text list rows collection is unavailable",
            "textlist_rows_unavailable",
            {"objectType": _text(type(obj)),
             "members": _member_names(obj, ["row", "text", "language"])})
    return collection


def _textlist_row_by_id(obj, row_id):
    collection = _textlist_rows_collection(obj)
    try:
        row = collection[row_id]
        if row is not None:
            return row
    except Exception:
        pass
    try:
        row = collection.Item[row_id]
        if row is not None:
            return row
    except Exception:
        pass
    rows, _total = _collection_rows(collection, lambda row: row)
    for row in rows:
        if _text(_get_member(row, "id", "get_id", "")) == row_id:
            return row
    raise OperationError(
        "text list row does not exist: " + row_id,
        "textlist_row_not_found",
        {"id": row_id,
         "availableIds": [_text(_get_member(row, "id", "get_id", ""))
                          for row in rows]})


def _textlist_snapshot(obj, path):
    languages = _textlist_languages(obj)

    def read_row(row):
        raw_texts = []
        try:
            row_count = int(_get_member(row, "languagetextcount",
                                        "languagetextcount", 0))
            for index in range(min(row_count, 50)):
                raw_texts.append(_call_with_args(row, "languagetext", [index]))
        except Exception:
            raw_texts = []
        raw_texts = [_text(value) for value in raw_texts]
        # The live getter returns genuine Unicode. A previous bridge version
        # converted it to a literal escaped string in _json_safe and then
        # escaped that string a second time. Do not decode escape-looking user
        # text here: a literal backslash-u value is valid data.
        texts = list(raw_texts)
        raw_default = _text(_get_member(row, "defaulttext",
                                        "defaulttext", ""))
        return {
            "id": _text(_get_member(row, "id", "id", "")),
            "defaultText": raw_default,
            "rawDefaultText": raw_default,
            "texts": texts,
            "rawTexts": raw_texts,
            "translations": [
                {"language": languages[index], "text": _text(value),
                 "rawText": raw_texts[index]}
                for index, value in enumerate(texts)
                if index < len(languages)
            ],
        }

    collection = _textlist_rows_collection(obj)
    rows, total = _collection_rows(collection, read_row) if collection is not None \
        else ([], 0)
    return {
        "path": path,
        "name": _object_name(obj),
        "guid": _object_guid(obj),
        "languages": languages,
        "rowCount": total,
        "rows": rows,
    }


def project_textlist_read(normalized):
    """Read-only: languages and rows of one text list object."""
    _require_project()
    obj, path = _text_list_object(normalized)
    result = _textlist_snapshot(obj, path)
    result["readOnly"] = True
    return result


def _textlist_created_path(created):
    guid = _object_guid(created).lower()
    flat = []
    _walk_objects(project, [], 1, 64, flat)
    matches = []
    for path, item in flat:
        if guid and _object_guid(item).lower() == guid:
            matches.append((path, item))
        elif not guid and item is created:
            matches.append((path, item))
    if len(matches) == 1:
        return _text(matches[0][0]), matches[0][1]
    name = _object_name(created)
    name_matches = [(path, item) for path, item in flat
                    if _hmi_resource_kind(item) == "textList"
                    and _object_name(item) == name]
    if len(name_matches) == 1:
        return _text(name_matches[0][0]), name_matches[0][1]
    raise OperationError(
        "created text list did not resolve to exactly one project-tree object",
        "textlist_create_readback_mismatch",
        {"name": name, "guid": guid or None,
         "guidMatchCount": len(matches),
         "nameMatchCount": len(name_matches),
         "mutatedProject": True,
         "recovery": "close the disposable project without saving"})


def _textlist_file_path(req, key, must_exist=False):
    path = _require_disposable_destination_path(req.get(key),
                                                "project.textlist.write")
    if must_exist and not os.path.isfile(path):
        raise OperationError(
            key + " does not exist", "textlist_file_not_found",
            {"path": key, "resolvedPath": path, "mutatedProject": False})
    return path


def _textlist_csv_shape(path):
    """Read just enough of a CODESYS text-list CSV to validate its purpose."""
    import codecs
    with open(path, "rb") as stream:
        prefix = stream.read(4)
    prefix_bytes = []
    for item in prefix[:2]:
        prefix_bytes.append(item if isinstance(item, int) else ord(item))
    encoding = "utf-16" if prefix_bytes in ([255, 254], [254, 255]) \
        else "utf-8-sig"
    with codecs.open(path, "r", encoding) as stream:
        content = stream.read()
    lines = [line for line in content.splitlines() if line.strip()]
    if not lines:
        raise OperationError(
            "text-list import file is empty", "textlist_import_file_empty",
            {"importPath": path, "mutatedProject": False})
    header = lines[0]
    candidates = [("tab", "\t"), ("semicolon", ";"), ("comma", ",")]
    delimiter_name, delimiter = max(candidates,
                                    key=lambda item: header.count(item[1]))
    if header.count(delimiter) == 0:
        raise OperationError(
            "text-list import header has no supported delimiter",
            "textlist_import_header_invalid",
            {"importPath": path, "header": header,
             "allowedDelimiters": ["tab", "semicolon", "comma"],
             "mutatedProject": False})
    headings = [part.strip() for part in header.split(delimiter)]
    rows = []
    for line in lines[1:]:
        fields = [part.strip() for part in line.split(delimiter)]
        rows.append(fields)
    return {
        "encoding": encoding,
        "delimiter": delimiter_name,
        "headings": headings,
        "rows": rows,
    }


def _textlist_validate_regular_import(path, obj, object_path):
    shape = _textlist_csv_shape(path)
    headings = [item.lower() for item in shape["headings"]]
    if len(headings) < 3 or headings[:3] != ["textlist", "id", "default"]:
        raise OperationError(
            "import file is not a CODESYS text-list export",
            "textlist_import_header_invalid",
            {"importPath": path, "headings": shape["headings"],
             "expectedPrefix": ["TextList", "Id", "Default"],
             "mutatedProject": False})
    name = _object_name(obj)
    path_dotted = _text(object_path).replace("/", ".")
    selectors = []
    matching_rows = 0
    for fields in shape["rows"]:
        if not fields:
            continue
        selector = fields[0]
        if selector:
            selectors.append(selector)
        if (selector == name or selector == path_dotted or
                selector.endswith("." + name)):
            matching_rows += 1
    if matching_rows == 0:
        raise OperationError(
            "import file contains no rows for the target text list",
            "textlist_import_target_not_found",
            {"target": object_path, "targetName": name,
             "importPath": path,
             "fileTextLists": sorted(set(selectors))[:100],
             "mutatedProject": False,
             "next": {"then": "use an export whose TextList column names "
                              "the target list, or edit that column first"}})
    shape["matchingRows"] = matching_rows
    shape["fileTextLists"] = sorted(set(selectors))[:100]
    return shape


def _textlist_validate_replacement_import(path, obj, object_path):
    if _object_name(obj).lower() != "globaltextlist":
        raise OperationError(
            "replacement files apply only to GlobalTextList static source text",
            "textlist_replacement_requires_global_text_list",
            {"target": object_path, "targetName": _object_name(obj),
             "mutatedProject": False,
             "next": {"then": "use action=import for an ordinary TextList"}})
    shape = _textlist_csv_shape(path)
    headings = [item.lower() for item in shape["headings"]]
    if len(headings) < 3 or headings[:3] != [
            "defaultold", "defaultnew", "replace"]:
        raise OperationError(
            "file is not a GlobalTextList replacement file",
            "textlist_replacement_header_invalid",
            {"importPath": path, "headings": shape["headings"],
             "expected": ["defaultold", "defaultnew", "REPLACE"],
             "mutatedProject": False})
    invalid_rows = [index + 2 for index, fields in enumerate(shape["rows"])
                    if len(fields) < 3 or fields[2].upper() != "REPLACE"]
    if invalid_rows:
        raise OperationError(
            "replacement file has rows without the REPLACE command",
            "textlist_replacement_row_invalid",
            {"importPath": path, "lineNumbers": invalid_rows[:100],
             "mutatedProject": False})
    shape["replacementRows"] = len(shape["rows"])
    return shape


def _require_textlist_container_member(container, member_name, container_name):
    """Resolve one documented TextList container member or name the profile gap."""
    try:
        member = getattr(container, member_name)
    except Exception:
        member = None
    if hasattr(member, "__call__"):
        return member
    raise OperationError(
        "the current IDE profile does not expose the documented TextList "
        "container member '%s'" % member_name,
        "textlist_container_api_unavailable",
        {
            "container": container_name,
            "member": member_name,
            "profile": _text(PROFILE),
            "runtimeType": _text(type(container)),
            "officialContract": "IScriptTextListObjectContainer",
            "platformSupport": "documented",
            "installationSupport": "extension_not_loaded",
            "mutatedProject": False,
            "next": {
                "then": "install or enable the IDE-profile component that "
                        "provides IScriptTextListObjectContainer (normally "
                        "CODESYS Visualization Support), restart that profile, "
                        "and retry; do not report the CODESYS platform itself "
                        "as unsupported"
            },
        })


def project_textlist_write(req):
    """Create and edit one project text list through the documented API."""
    _require_current_disposable_project(req, "project.textlist.write")
    action = _text(req.get("action") or "").strip().lower().replace("_", "-")
    actions = (
        "create", "create-global", "delete", "add-language", "remove-language", "add-row",
        "remove-row", "set-default-text", "set-language-text",
        "update-text-ids", "check-ids", "remove-unused-ids", "import",
        "import-replacement", "export", "export-difference",
    )
    if action not in actions:
        raise OperationError(
            "project.textlist.write action is invalid", "invalid_argument",
            {"path": "action", "actual": action, "allowed": list(actions),
             "mutatedProject": False})

    if action == "create-global":
        if not _is_vanilla_codesys_profile():
            raise OperationError(
                "InoProShop's project GlobalTextList is rejected by its compiler",
                "textlist_global_compile_unsupported",
                {"compilerCode": "C0464", "mutatedProject": False,
                 "next": {"then": "use action=create with container=application "
                                  "for a dynamic text list"}})
        get_global_textlist = _require_textlist_container_member(
            project, "get_global_textlist", "project")
        had_global = bool(_get_member(project, "has_global_textlist",
                                      "get_has_global_textlist", False))
        try:
            global_list = get_global_textlist()
        except Exception as exc:
            raise OperationError(
                "global text-list creation failed",
                "textlist_global_create_failed",
                {"cause": repr(exc), "mutatedProject": False})
        if global_list is None or _hmi_resource_kind(global_list) != "textList":
            raise OperationError(
                "get_global_textlist returned no text-list object",
                "textlist_global_create_readback_mismatch",
                {"mutatedProject": not had_global})
        path, global_list = _textlist_created_path(global_list)
        return {
            "action": action,
            "created": not had_global,
            "globalTextList": _textlist_snapshot(global_list, path),
            "saveRequired": not had_global,
            "mutatedProject": not had_global,
            "nextRequired": (["project.save", "fresh-process reopen",
                              "project.textlist_read", "build.compile"]
                             if not had_global else []),
        }

    if action == "create":
        name = _text(req.get("name") or "").strip()
        if not name:
            raise OperationError("name is required", "invalid_argument",
                                 {"path": "name", "mutatedProject": False})
        container_name = _text(req.get("container") or "application").strip().lower()
        if container_name not in ("application", "project"):
            raise OperationError(
                "container must be application or project", "invalid_argument",
                {"path": "container", "actual": container_name,
                 "allowed": ["application", "project"],
                 "mutatedProject": False})
        if container_name == "project" and not _is_vanilla_codesys_profile():
            raise OperationError(
                "InoProShop rejects project-root text lists during compilation",
                "textlist_project_container_compile_unsupported",
                {"container": "project", "compilerCode": "C0464",
                 "next": {"then": "create the text list in container=application"},
                 "mutatedProject": False})
        if container_name == "application":
            container = _get_member(project, "active_application",
                                    "get_active_application", None)
            if container is None:
                raise OperationError(
                    "the project has no active Application text-list container",
                    "textlist_application_container_unavailable",
                    {"mutatedProject": False})
        else:
            container = project
        create_textlist = _require_textlist_container_member(
            container, "create_textlist", container_name)
        before = []
        _walk_objects(project, [], 1, 64, before)
        duplicates = [path for path, item in before
                      if _hmi_resource_kind(item) == "textList"
                      and _object_name(item).lower() == name.lower()]
        if duplicates:
            raise OperationError(
                "a text list with this name already exists",
                "textlist_name_exists",
                {"name": name, "paths": duplicates, "mutatedProject": False})
        try:
            created = create_textlist(name)
        except Exception as exc:
            raise OperationError(
                "project text-list creation failed", "textlist_create_failed",
                {"name": name, "cause": repr(exc), "mutatedProject": False})
        if created is None or _hmi_resource_kind(created) != "textList":
            raise OperationError(
                "project create_textlist returned no text-list object",
                "textlist_create_readback_mismatch",
                {"name": name, "runtimeType": _text(type(created)),
                 "mutatedProject": True,
                 "recovery": "close the disposable project without saving"})
        path, created = _textlist_created_path(created)
        return {
            "action": action,
            "created": _textlist_snapshot(created, path),
            "container": container_name,
            "saveRequired": True,
            "mutatedProject": True,
            "nextRequired": ["project.save", "fresh-process reopen",
                             "project.textlist_read", "build.compile"],
        }

    obj, path = _text_list_object(req)
    before = _textlist_snapshot(obj, path)
    result = None

    if action in ("update-text-ids", "check-ids", "remove-unused-ids",
                  "import-replacement") and _object_name(obj).lower() != "globaltextlist":
        raise OperationError(
            action + " applies only to GlobalTextList",
            "textlist_action_requires_global_text_list",
            {"action": action, "target": path,
             "targetName": _object_name(obj), "mutatedProject": False,
             "next": {"then": "use ordinary row/language actions or action=import "
                              "for this dynamic TextList"}})

    if action == "delete":
        guid = _object_guid(obj).lower()
        obj.remove()
        flat = []
        _walk_objects(project, [], 1, 64, flat)
        remaining = [item_path for item_path, item in flat
                     if guid and _object_guid(item).lower() == guid]
        if remaining:
            raise OperationError(
                "text list deletion did not disappear from the project tree",
                "textlist_delete_readback_mismatch",
                {"target": path, "guid": guid, "remaining": remaining,
                 "mutatedProject": True})
        return {"action": action, "target": path, "guid": guid,
                "deleted": True, "saveRequired": True,
                "mutatedProject": True}

    if action in ("add-language", "remove-language", "set-language-text"):
        language = _text(req.get("language") or "").strip()
        if not language:
            raise OperationError("language is required", "invalid_argument",
                                 {"path": "language", "mutatedProject": False})
        languages = before.get("languages") or []
        if action == "add-language":
            if language in languages:
                raise OperationError(
                    "text list language already exists", "textlist_language_exists",
                    {"language": language, "languages": languages,
                     "mutatedProject": False})
            _call_with_args(obj, "addlanguage", [language])
        elif action == "remove-language":
            if language not in languages:
                raise OperationError(
                    "text list language does not exist",
                    "textlist_language_not_found",
                    {"language": language, "languages": languages,
                     "mutatedProject": False})
            _call_with_args(obj, "removelanguage", [language])
        else:
            if language not in languages:
                raise OperationError(
                    "add the language before setting its text",
                    "textlist_language_not_found",
                    {"language": language, "languages": languages,
                     "mutatedProject": False})
            row_id = _text(req.get("id") or "").strip()
            if not row_id:
                raise OperationError("id is required", "invalid_argument",
                                     {"path": "id", "mutatedProject": False})
            text_value = _text(req.get("text"))
            row = _textlist_row_by_id(obj, row_id)
            accepted = bool(_call_with_args(
                row, "setlanguagetext", [language, text_value]))
            if not accepted:
                raise OperationError(
                    "the vendor rejected the language text",
                    "textlist_language_text_rejected",
                    {"id": row_id, "language": language,
                     "mutatedProject": False})

    elif action == "add-row":
        row_id = _text(req.get("id") or "").strip()
        if not row_id:
            raise OperationError("id is required", "invalid_argument",
                                 {"path": "id", "mutatedProject": False})
        existing_ids = [row.get("id") for row in before.get("rows") or []]
        if row_id in existing_ids:
            raise OperationError("text list row already exists",
                                 "textlist_row_exists",
                                 {"id": row_id, "mutatedProject": False})
        default_text = _text(req.get("defaultText"))
        added_row = _call_with_args(_textlist_rows_collection(obj), "add",
                                    [row_id, default_text])
        if added_row is None or _text(_get_member(
                added_row, "id", "get_id", "")) != row_id:
            raise OperationError(
                "text list row creation readback failed",
                "textlist_row_create_readback_mismatch",
                {"id": row_id, "mutatedProject": True})
        result = {"addedRow": row_id}
    elif action == "remove-row":
        row_id = _text(req.get("id") or "").strip()
        if not row_id:
            raise OperationError("id is required", "invalid_argument",
                                 {"path": "id", "mutatedProject": False})
        _textlist_row_by_id(obj, row_id)
        _call_with_args(_textlist_rows_collection(obj), "remove", [row_id])
    elif action == "set-default-text":
        row_id = _text(req.get("id") or "").strip()
        if not row_id:
            raise OperationError("id is required", "invalid_argument",
                                 {"path": "id", "mutatedProject": False})
        text_value = _text(req.get("text"))
        accepted = bool(_call_with_args(
            _textlist_row_by_id(obj, row_id), "setdefaulttext", [text_value]))
        if not accepted:
            raise OperationError(
                "the vendor rejected the default text",
                "textlist_default_text_rejected",
                {"id": row_id, "mutatedProject": False})
    elif action == "update-text-ids":
        _call_with_args(obj, "updatetextids", [])
    elif action == "check-ids":
        _call_with_args(obj, "checkids", [])
    elif action == "remove-unused-ids":
        _call_with_args(obj, "removeunusedids", [])
    elif action in ("import", "import-replacement"):
        import_path = _textlist_file_path(req, "importPath", True)
        if action == "import":
            import_shape = _textlist_validate_regular_import(
                import_path, obj, path)
        else:
            import_shape = _textlist_validate_replacement_import(
                import_path, obj, path)
        method = "importfile" if action == "import" else "importreplacementfile"
        _call_with_args(obj, method, [import_path])
        result = {"importPath": import_path,
                  "format": import_shape}
    elif action == "export":
        export_path = _textlist_file_path(req, "exportPath", False)
        if os.path.exists(export_path) and not bool(req.get("overwrite")):
            raise OperationError(
                "export destination exists; set overwrite=true to replace it",
                "destination_exists",
                {"exportPath": export_path, "mutatedProject": False})
        parent = os.path.dirname(export_path)
        if parent and not os.path.isdir(parent):
            os.makedirs(parent)
        _call_with_args(obj, "export", [export_path])
        if not os.path.isfile(export_path):
            raise OperationError("text list export file was not created",
                                 "textlist_export_readback_mismatch",
                                 {"exportPath": export_path,
                                  "mutatedProject": False})
        result = {"exportPath": export_path,
                  "bytes": int(os.path.getsize(export_path))}
    elif action == "export-difference":
        import_path = _textlist_file_path(req, "importPath", True)
        export_path = _textlist_file_path(req, "exportPath", False)
        if os.path.exists(export_path) and not bool(req.get("overwrite")):
            raise OperationError(
                "export destination exists; set overwrite=true to replace it",
                "destination_exists",
                {"exportPath": export_path, "mutatedProject": False})
        parent = os.path.dirname(export_path)
        if parent and not os.path.isdir(parent):
            os.makedirs(parent)
        _call_with_args(obj, "exportonlydifference",
                        [import_path, export_path])
        if not os.path.isfile(export_path):
            raise OperationError("text-list difference export file was not created",
                                 "textlist_export_readback_mismatch",
                                 {"exportPath": export_path,
                                  "mutatedProject": False})
        result = {"importPath": import_path, "exportPath": export_path,
                  "bytes": int(os.path.getsize(export_path))}

    after = _textlist_snapshot(obj, path)
    if action == "add-language" and language not in after.get("languages", []):
        raise OperationError("added language was not retained",
                             "textlist_language_readback_mismatch",
                             {"language": language, "mutatedProject": True})
    if action == "remove-language" and language in after.get("languages", []):
        raise OperationError("removed language is still present",
                             "textlist_language_readback_mismatch",
                             {"language": language, "mutatedProject": True})
    if action == "add-row" and not any(
            row.get("id") == row_id for row in after.get("rows") or []):
        raise OperationError("added row is not present",
                             "textlist_row_readback_mismatch",
                             {"id": row_id, "mutatedProject": True})
    if action == "remove-row" and any(
            row.get("id") == row_id for row in after.get("rows") or []):
        raise OperationError("removed row is still present",
                             "textlist_row_readback_mismatch",
                             {"id": row_id, "mutatedProject": True})
    if action == "set-default-text":
        actual = next((row.get("defaultText") for row in after.get("rows") or []
                      if row.get("id") == row_id), None)
        if actual != text_value:
            raise OperationError("default text readback differs",
                                 "textlist_default_text_readback_mismatch",
                                 {"id": row_id, "expected": text_value,
                                  "actual": actual, "mutatedProject": True})
    if action == "set-language-text":
        actual = None
        for row in after.get("rows") or []:
            if row.get("id") != row_id:
                continue
            for translation in row.get("translations") or []:
                if translation.get("language") == language:
                    actual = translation.get("text")
                    break
        if actual != text_value:
            raise OperationError("language text readback differs",
                                 "textlist_language_text_readback_mismatch",
                                 {"id": row_id, "language": language,
                                  "expected": text_value, "actual": actual,
                                  "mutatedProject": True})
    return {
        "action": action,
        "target": path,
        "before": before,
        "after": after,
        "file": result,
        "saveRequired": action not in ("check-ids", "export", "export-difference"),
        "mutatedProject": action not in ("check-ids", "export", "export-difference"),
        "nextRequired": ["project.save", "fresh-process reopen",
                         "project.textlist_read", "build.compile"]
                        if action not in ("check-ids", "export", "export-difference")
                        else [],
    }


def project_imagepool_read(normalized):
    """Read-only: settings and images of one image pool object."""
    _require_project()
    target = _text(normalized.get("target") or "").strip()
    if not target:
        raise OperationError(
            "target is required", "invalid_argument",
            {"next": {"tool": "codesys_project_hmi_resources",
                      "then": "call it first to list image pool objects"}})
    obj, path = find_project_object(target)
    kind = _hmi_resource_kind(obj)
    if kind != "imagePool":
        raise OperationError(
            "'%s' is not an image pool object" % target,
            "not_an_image_pool",
            {"target": target, "resolvedPath": _text(path),
             "resolvedKind": kind, "objectType": _text(type(obj)),
             "members": _member_names(obj, ["image", "symbol", "internal"]),
             "next": {"tool": "codesys_project_hmi_resources",
                      "then": "pass the path of an object whose kind is imagePool"}})

    def read_item(item):
        return {
            "id": _text(_get_member(item, "id", "id", "")),
            "filePath": _text(_get_member(item, "filepath", "filepath", "")),
            "linkType": _text(_get_member(item, "linktype", "linktype", "")),
            "updateMode": _text(_get_member(item, "updatemode", "updatemode", "")),
        }

    collection = _get_member(obj, "images", "get_images", None)
    items, total = _collection_rows(collection, read_item) if collection is not None \
        else ([], 0)
    return {
        "path": path,
        "downloadOnlyUsedImages": _get_member(
            obj, "download_only_used_images",
            "get_download_only_used_images", None),
        "isInternal": _get_member(obj, "imagepool_is_internal",
                                  "get_imagepool_is_internal", None),
        "symbolTextList": _text(_get_member(obj, "symboltextlist",
                                            "get_symboltextlist", "")),
        "imageCount": total,
        "images": items,
        "boundary": "Read-only. Adding/removing images or changing the pool "
                    "settings is not implemented.",
    }


def _call_with_args(obj, name, args):
    """Call a vendor method with explicit arguments (never via _get_member)."""
    method = getattr(obj, name, None)
    if not hasattr(method, "__call__"):
        raise OperationError(
            "this object has no %s method" % name,
            "object_member_unavailable",
            {"member": name, "objectType": _text(type(obj)),
             "candidates": _member_names(obj, [name[:4]])})
    return method(*args)


def _user_or_group_row(item):
    """IScriptUser / IScriptGroup share the IScriptUserOrGroup naming surface."""
    groups = []
    for nested in _get_member(item, "groups", "get_groups", None) or []:
        groups.append(_text(_get_member(nested, "name", "get_name", "")))
    userlist = []
    for nested in _get_member(item, "userlist", "get_userlist", None) or []:
        userlist.append(_text(_get_member(nested, "name", "get_name", "")))
    grouplist = []
    for nested in _get_member(item, "grouplist", "get_grouplist", None) or []:
        grouplist.append(_text(_get_member(nested, "name", "get_name", "")))
    return {
        "name": _text(_get_member(item, "name", "get_name", "")),
        "id": _text(_get_member(item, "id", "get_id", "")),
        "description": _text(_get_member(item, "description", "get_description", "")),
        "isUser": bool(_get_member(item, "is_user", "get_is_user", False)),
        "isGroup": bool(_get_member(item, "is_group", "get_is_group", False)),
        "active": _get_member(item, "active", "get_active", None),
        "fullname": _text(_get_member(item, "fullname", "get_fullname", "")),
        "isEveryoneGroup": _get_member(item, "is_everyone_group",
                                       "get_is_everyone_group", None),
        "isOwnerGroup": _get_member(item, "is_owner_group",
                                    "get_is_owner_group", None),
        "groups": groups,
        "users": userlist,
        "nestedGroups": grouplist,
    }


def project_users(normalized):
    """Read-only: the PROJECT's user/group management (IScriptProject4)."""
    _require_project()
    management = _get_member(project, "user_management", "get_user_management", None)
    if management is None:
        raise OperationError(
            "this project exposes no user_management object",
            "project_user_management_unavailable",
            {"projectPath": _project_path(),
             "projectMembers": _member_names(project, ["user", "management"])})
    # MEASURED 2026-09-19: IScriptUserManagement.check_available takes the
    # permission-type GUID; the old zero-argument call always answered False and
    # made every project look as if user management were unavailable. Ask it for
    # the user-management type this op actually needs.
    _types = _get_member(management, "types", "get_types", None)
    _um_guid = _get_member(_types, "usermanagement", "get_usermanagement", None) \
        if _types is not None else None
    try:
        available = bool(_call_with_args(management, "check_available",
                                         [_um_guid])) if _um_guid is not None \
            else bool(_get_member(management, "check_available",
                                  "check_available", False))
    except Exception:
        available = False
    users = []
    for user in _get_member(management, "users", "get_users", None) or []:
        users.append(_user_or_group_row(user))
    groups = []
    for group in _get_member(management, "groups", "get_groups", None) or []:
        groups.append(_user_or_group_row(group))
    logged_on = _text(_get_member(management, "logged_on_user",
                                  "get_logged_on_user", ""))
    return {
        "projectPath": _project_path(),
        "available": available,
        "loggedOnUser": logged_on,
        "userCount": len(users),
        "groupCount": len(groups),
        "users": users,
        "groups": groups,
        "boundary": "This is the PROJECT's user/group management - who may do "
                    "what on this project. It is unrelated to the DEVICE user "
                    "management (online.device_users), and no password or "
                    "password hash is ever returned here.",
    }


PERMISSION_STATE_NAMES = {0: "granted", 1: "denied", 2: "default"}
PERMISSION_STATE_VALUES = {"granted": "Granted", "denied": "Denied",
                           "default": "Default"}
PERMISSION_TYPE_KEYS = ("usermanagement", "objectaccess", "objectfactory",
                        "commandexecution")
PERMISSION_ENUM_TYPE = \
    "_3S.CoDeSys.UserManagement.PermissionState, UserManagement"


def _project_user_management():
    """The project's IScriptUserManagement, or a typed refusal."""
    _require_project()
    management = _get_member(project, "user_management", "get_user_management",
                             None)
    if management is None:
        raise OperationError(
            "this project exposes no user_management object",
            "project_user_management_unavailable",
            {"projectPath": _project_path(),
             "projectMembers": _member_names(project, ["user", "management"]),
             "next": {"then": "this build's project object has no "
                              "user_management member; report the boundary "
                              "instead of retrying"}})
    return management


def _permission_type_guids(management):
    """The four documented permission-type GUIDs (IScriptPermissionTypes)."""
    types = _get_member(management, "types", "get_types", None)
    guids = {}
    for key in PERMISSION_TYPE_KEYS:
        value = None
        if types is not None:
            value = _get_member(types, key, "get_" + key, None)
        guids[key] = _text(value)
    return guids


def _permission_state_name(value):
    """PermissionState -> stable lower-case name (never a raw number alone)."""
    text = _text(value)
    name = text.rsplit(".", 1)[-1].strip().lower()
    if name in PERMISSION_STATE_VALUES:
        return name
    try:
        return PERMISSION_STATE_NAMES.get(int(value), text)
    except Exception:
        return text


def _permission_enum_value(state_name):
    """Build the vendor PermissionState value from its documented name."""
    import System
    enum_type = System.Type.GetType(PERMISSION_ENUM_TYPE)
    if enum_type is None:
        raise OperationError(
            "the vendor PermissionState enum is not loaded",
            "permission_enum_unavailable",
            {"enumType": PERMISSION_ENUM_TYPE,
             "next": {"then": "report the boundary; the script session cannot "
                              "address permission states on this build"}})
    return System.Enum.Parse(enum_type, PERMISSION_STATE_VALUES[state_name])


def _permission_group_rows(management):
    """Every project group with its state for the DIRECT permission handles."""
    groups = list(_get_member(management, "groups", "get_groups", None) or [])
    permission = _call_with_args(management, "get_user_management_permission",
                                 [])
    rows = []
    for group in groups:
        name = _text(_get_member(group, "name", "get_name", ""))
        row = {
            "group": name,
            "isEveryoneGroup": _get_member(group, "is_everyone_group",
                                           "get_is_everyone_group", None),
            "isOwnerGroup": _get_member(group, "is_owner_group",
                                        "get_is_owner_group", None),
        }
        try:
            row["userManagementState"] = _permission_state_name(
                _call_with_args(permission, "get_permission_state",
                                [group, False, False]))
        except Exception as exc:
            row["userManagementState"] = None
            row["userManagementStateError"] = _text(exc)
        try:
            row["userManagementEffective"] = _permission_state_name(
                _call_with_args(permission, "get_permission_state",
                                [group, True, True]))
        except Exception as exc:
            row["userManagementEffective"] = None
            row["userManagementEffectiveError"] = _text(exc)
        rows.append(row)
    return rows, permission


def project_permission_read(normalized):
    """Read-only: PROJECT permission states (IScriptPermission).

    MEASURED 2026-09-19 (official dump + live probe): IScriptPermission is
    reachable through IScriptUserManagement.get_user_management_permission(),
    which covers the `usermanagement` permission type.  The other three types
    (objectaccess / objectfactory / commandexecution) have no direct getter -
    their handles come from get_object_permission(obj, kind),
    get_factory_permission(guid) and get_command_permission(guid), i.e. they
    need a target object/factory/command - so they are reported here with their
    GUIDs and the exact provider, not as silently missing rows.
    """
    management = _project_user_management()
    rows, permission = _permission_group_rows(management)
    return {
        "projectPath": _project_path(),
        "permissionTypeGuids": _permission_type_guids(management),
        "permissionHandleType": _text(type(permission)),
        "groupCount": len(rows),
        "groups": rows,
        "stateVocabulary": sorted(PERMISSION_STATE_VALUES),
        "otherTypesBoundary": {
            "types": ["objectaccess", "objectfactory", "commandexecution"],
            "providers": ["get_object_permission(obj, kind)",
                          "get_factory_permission(factory_guid)",
                          "get_command_permission(command_guid)"],
            "note": "These permission types need a concrete target; this "
                    "operation reports their GUIDs so a target-specific call "
                    "can be added without guessing.",
        },
        "boundary": "Read-only. A state of 'default' means the group inherits "
                    "the project default; 'effective' resolves inheritance.",
    }


def _set_project_permission(normalized):
    """Set ONE project group's permission state for the usermanagement type.

    The vendor exposes a permission-checked setter (check_set_permission_state)
    next to the writer, so the guard is asked FIRST and a refusal is reported as
    its own code instead of being discovered by a failed mutation.  The receipt
    carries before/after readbacks and the save/reopen gate.

    MEASURED 2026-09-19 (fresh-process gate): a state change made while a
    privileged project user is logged on SURVIVES project.save + reopen
    (Everyone default -> denied persisted), while the login itself is held per
    process. The vendor demands that login: without one, the IDE raises its
    native 登录 dialog and check_set_permission_state answers False.
    """
    operation = "project.user.write"
    management = _project_user_management()
    group_name = _text(normalized.get("group") or normalized.get("groupName") or "").strip()
    if not group_name:
        raise OperationError(
            "group is required", "invalid_argument",
            {"groups": [_text(_get_member(g, "name", "get_name", ""))
                        for g in _get_member(management, "groups",
                                             "get_groups", None) or []],
             "next": {"then": "pass the exact project group name"}})
    requested = _text(normalized.get("state") or "").strip().lower()
    if requested not in PERMISSION_STATE_VALUES:
        raise OperationError(
            "state must be one of " + ", ".join(sorted(PERMISSION_STATE_VALUES)),
            "invalid_argument",
            {"state": _text(normalized.get("state")),
             "next": {"then": "granted | denied | default"}})
    permission_type = _text(normalized.get("permissionType")
                            or "usermanagement").strip().lower()
    if permission_type != "usermanagement":
        raise OperationError(
            permission_type + " permission states need a concrete target on "
            "this build",
            "permission_type_needs_target",
            {"permissionType": permission_type,
             "supported": ["usermanagement"],
             "providers": {"objectaccess": "get_object_permission(obj, kind)",
                           "objectfactory": "get_factory_permission(guid)",
                           "commandexecution": "get_command_permission(guid)"},
             "next": {"then": "only usermanagement is addressable without a "
                              "target; report the boundary for the others"}})

    groups = list(_get_member(management, "groups", "get_groups", None) or [])
    exact = [g for g in groups
             if _text(_get_member(g, "name", "get_name", "")) == group_name]
    if len(exact) != 1:
        raise OperationError(
            "project group not resolved to exactly one group",
            "permission_group_not_found" if not exact
            else "permission_group_ambiguous",
            {"group": group_name,
             "candidateCount": len(exact),
             "groups": [_text(_get_member(g, "name", "get_name", ""))
                        for g in groups],
             "mutatedProject": False,
             "next": {"then": "pass the exact name from this receipt's groups "
                              "list"}})
    group = exact[0]
    permission = _call_with_args(management, "get_user_management_permission",
                                 [])
    state_value = _permission_enum_value(requested)
    before = _permission_state_name(
        _call_with_args(permission, "get_permission_state", [group, False, False]))
    allowed = _call_with_args(permission, "check_set_permission_state",
                              [group, state_value, False])
    if allowed is not True:
        raise OperationError(
            "the vendor permission guard refused this state change",
            "permission_set_not_allowed",
            {"group": group_name, "requestedState": requested,
             "before": before, "guardReturned": _text(allowed),
             "mutatedProject": False,
             "next": {"then": "the logged-on user may not change this group's "
                              "state; report the refusal, do not retry"}})
    _call_with_args(permission, "set_permission_state", [group, state_value])
    after = _permission_state_name(
        _call_with_args(permission, "get_permission_state", [group, False, False]))
    effective = _permission_state_name(
        _call_with_args(permission, "get_permission_state", [group, True, True]))
    return {
        "operation": operation,
        "action": "set-permission",
        "projectPath": _project_path(),
        "group": group_name,
        "permissionType": permission_type,
        "before": before,
        "requested": requested,
        "after": after,
        "effective": effective,
        "guardChecked": True,
        "mutatedProject": True,
        "status": "committed_same_process_requires_save_reopen_gate",
        "persistenceVerified": False,
        "nextRequired": "project.save (confirm=save_project, disposable=true), "
                        "close, reopen in a fresh process and re-read with "
                        "project.permission.read - the same-process value is "
                        "not persistence",
    }


PROJECT_USER_ACTIONS = ("create", "remove", "login", "logout",
                        "join-group", "leave-group", "set-permission")


def _project_users_list(management):
    return list(_get_member(management, "users", "get_users", None) or [])


def _assign_member(obj, name, value):
    """Set a vendor member that the dump declares as set_<name>.

    MEASURED 2026-09-19: IScriptUser declares set_fullname/set_active, but the
    runtime user object answers with "this object has no set_fullname method" -
    IronPython binds the .NET property directly instead. Try the documented
    setter first, then fall back to attribute assignment so both shapes work.
    """
    setter = getattr(obj, "set_" + name, None)
    if setter is not None:
        try:
            setter(value)
            return "method"
        except Exception as method_exc:
            try:
                setattr(obj, name, value)
                return "property"
            except Exception:
                raise method_exc
    setattr(obj, name, value)
    return "property"


def _project_user_rows(user):
    groups = []
    for group in _get_member(user, "groups", "get_groups", None) or []:
        groups.append(_text(_get_member(group, "name", "get_name", group)))
    return {
        "name": _text(_get_member(user, "name", "get_name", "")),
        "id": _text(_get_member(user, "id", "get_id", "")),
        "fullname": _text(_get_member(user, "fullname", "get_fullname", "")),
        "active": _get_member(user, "active", "get_active", None),
        "groups": groups,
    }


def _project_logged_on(management):
    value = _get_member(management, "logged_on_user", "get_logged_on_user", None)
    if value is None:
        return ""
    return _text(_get_member(value, "name", "get_name", value))


def project_user_write(normalized):
    """Create/remove a PROJECT user and log in/out of the project.

    MEASURED 2026-09-19: changing a project permission state (or any other
    user-management action) makes the IDE demand a logged-on member of a
    privileged group ("为了执行此动作，必须以下列组的用户成员登录").  The vendor
    exposes the whole path to a script - IScriptUserList.create(name),
    IScriptUser.change_password(old, new), IScriptUserOrGroup.add_to(group) and
    IScriptUserManagement.login/logout - so the capability exists; only the
    login state has to be established first.  One operation covers the four
    actions to keep the tool surface small.

    The receipt NEVER echoes a password (only `passwordSet`).
    """
    operation = "project.user.write"
    management = _project_user_management()
    action = _text(normalized.get("action") or "").strip().lower()
    if action not in PROJECT_USER_ACTIONS:
        raise OperationError(
            "action must be one of " + ", ".join(PROJECT_USER_ACTIONS),
            "invalid_argument",
            {"action": _text(normalized.get("action")),
             "next": {"then": " | ".join(PROJECT_USER_ACTIONS)}})

    if action == "set-permission":
        return _set_project_permission(normalized)

    if action == "logout":
        before = _project_logged_on(management)
        _call_with_args(management, "logout", [])
        return {
            "operation": operation, "action": action,
            "loggedOnBefore": before,
            "loggedOnAfter": _project_logged_on(management),
            "mutatedProject": False,
            "status": "session_changed",
            "nextRequired": "no project save is needed for a session change",
        }

    name = _text(normalized.get("name") or normalized.get("username") or "").strip()
    if not name:
        raise OperationError("name (the project user) is required",
                             "invalid_argument", {"action": action})

    if action == "login":
        password = _text(normalized.get("password") or "")
        try:
            _call_with_args(management, "login", [name, password])
        except Exception as exc:
            raise OperationError(
                "the project refused this login: " + _text(exc),
                "project_login_failed",
                {"user": name, "loggedOnUser": _project_logged_on(management),
                 "mutatedProject": False,
                 "next": {"then": "check the exact project user name and its "
                                  "password; a passwordless project user is "
                                  "logged in with an empty password"}})
        return {
            "operation": operation, "action": action, "user": name,
            "loggedOnUser": _project_logged_on(management),
            "mutatedProject": False,
            "status": "logged_in_same_process",
            "nextRequired": "permission/user-management writes are now allowed "
                            "while this login is held; log out when finished",
        }

    users = _project_users_list(management)
    matches = [u for u in users
               if _text(_get_member(u, "name", "get_name", "")) == name]

    if action == "create":
        if matches:
            raise OperationError(
                "a project user with this name already exists",
                "project_user_exists",
                {"user": name, "existing": [_project_user_rows(u) for u in matches],
                 "mutatedProject": False})
        created = _call_with_args(
            (_get_member(management, "users", "get_users", None)), "create",
            [name])
        steps = {}
        fullname = _text(normalized.get("fullName") or "").strip()
        if fullname:
            try:
                steps["fullname"] = _assign_member(created, "fullname", fullname)
            except Exception as exc:
                steps["fullname"] = _text(exc)
        active = normalized.get("active")
        if active is not None:
            try:
                steps["active"] = _assign_member(created, "active", bool(active))
            except Exception as exc:
                steps["active"] = _text(exc)
        password = normalized.get("password")
        password_set = False
        if password is not None:
            old_password = _text(normalized.get("oldPassword") or "")
            try:
                _call_with_args(created, "change_password",
                                [old_password, _text(password)])
                password_set = True
                steps["password"] = True
            except Exception as exc:
                steps["password"] = _text(exc)
        joined = []
        for group_name in normalized.get("groups") or []:
            wanted = _text(group_name).strip()
            group = [g for g in _get_member(management, "groups", "get_groups", None) or []
                     if _text(_get_member(g, "name", "get_name", "")) == wanted]
            if len(group) != 1:
                steps.setdefault("groupsFailed", []).append(wanted)
                continue
            try:
                _call_with_args(created, "add_to", [group[0]])
                joined.append(wanted)
            except Exception as exc:
                steps.setdefault("groupsFailed", []).append(
                    {"group": wanted, "error": _text(exc)})
        readback = [u for u in _project_users_list(management)
                    if _text(_get_member(u, "name", "get_name", "")) == name]
        return {
            "operation": operation, "action": action, "user": name,
            "passwordSet": password_set,
            "joinedGroups": joined,
            "steps": steps,
            "created": bool(readback),
            "user": _project_user_rows(readback[0]) if readback else None,
            "mutatedProject": True,
            "status": "created_same_process_requires_save_reopen_gate",
            "nextRequired": "project.save, close, reopen in a fresh process and "
                            "re-read with project.users - a same-process row is "
                            "not persistence",
        }

    if len(matches) != 1:
        raise OperationError(
            "project user not resolved to exactly one user",
            "project_user_not_found" if not matches else "project_user_ambiguous",
            {"user": name, "matchCount": len(matches),
             "users": [_text(_get_member(u, "name", "get_name", "")) for u in users],
             "mutatedProject": False})

    if action in ("join-group", "leave-group"):
        group_name = _text(normalized.get("group") or normalized.get("groupName")
                           or "").strip()
        groups = list(_get_member(management, "groups", "get_groups", None) or [])
        exact = [g for g in groups
                 if _text(_get_member(g, "name", "get_name", "")) == group_name]
        if len(exact) != 1:
            raise OperationError(
                "project group not resolved to exactly one group",
                "permission_group_not_found" if not exact
                else "permission_group_ambiguous",
                {"group": group_name,
                 "groups": [_text(_get_member(g, "name", "get_name", ""))
                            for g in groups],
                 "mutatedProject": False})
        user_obj = matches[0]
        before = _project_user_rows(user_obj)
        method = "add_to" if action == "join-group" else "remove_from"
        _call_with_args(user_obj, method, [exact[0]])
        after = _project_user_rows(user_obj)
        return {
            "operation": operation, "action": action, "user": name,
            "group": group_name,
            "groupsBefore": before.get("groups"),
            "groupsAfter": after.get("groups"),
            "mutatedProject": True,
            "status": "committed_same_process_requires_save_reopen_gate",
            "persistenceVerified": False,
            # MEASURED 2026-09-19 (twice): a group-membership change made here
            # reverts after project.save + a fresh-process reopen - the user is
            # back in BOTH groups.  The saved .project carries no user-management
            # data at all (it contains PLC_PRG but neither the group names nor the
            # user), so Project.Save cannot deliver the change.
            "measuredPersistence": "NOT_PERSISTED_BY_SAVE",
            "boundary": "Do NOT report the membership change as durable: after "
                        "project.save and a fresh reopen the user is back in its "
                        "original groups. Re-read with project.users after "
                        "reopening, and change membership in the IDE's "
                        "user-management dialog when it must stick.",
            "nextRequired": "project.save, close, reopen in a fresh process and "
                            "re-read with project.users - a same-process group "
                            "change is not persistence",
        }

    before = _project_user_rows(matches[0])
    _call_with_args(matches[0], "remove", [])
    remaining = [u for u in _project_users_list(management)
                 if _text(_get_member(u, "name", "get_name", "")) == name]
    return {
        "operation": operation, "action": action,
        "removed": not remaining,
        "before": before,
        "mutatedProject": not remaining,
        "status": "removed_same_process_requires_save_reopen_gate"
                  if not remaining else "remove_not_effective",
        # MEASURED 2026-09-19 (twice, with and without leave-group first):
        # IScriptUser.remove() takes the user out of the RUNNING session, but
        # after project.save + a fresh-process reopen the user is back WITH its
        # password and groups (the same user could even log in again).  Creation
        # and permission-state writes DO persist; the delete path does not.  The
        # saved .project carries no user-management data at all, so Project.Save
        # cannot be the mechanism that removes them.
        "measuredPersistence": "NOT_PERSISTED_BY_SAVE",
        "boundary": "Do NOT report the account as deleted: after project.save and "
                    "a fresh reopen the user is back with its password and group "
                    "memberships. Re-read with project.users after reopening, and "
                    "perform the removal in the IDE's user-management dialog when "
                    "it must stick.",
        "nextRequired": "project.save, close, reopen in a fresh process and "
                        "re-read with project.users",
    }


def debug_device_extension_probe(normalized):
    """Read-only: is IScriptProjectDeviceExtension reachable at runtime?

    MEASURED 2026-09-19 (offline): the official surface (821 types, 12,602
    members, 20 assemblies) declares that interface with two `add` overloads but
    contains NO member returning it and NO type listing it as implemented - so
    the documented composition API has no documented provider.  A provider can
    still exist in a plugin assembly the dump does not cover, so this probe asks
    the LIVE process instead of trusting the dump: it scans every loaded type
    for implementors and every device object of the open project for the
    interface.  Internal diagnostic (deliberately uncarded) - it never mutates.
    """
    import System
    result = {"operation": "debug.device_extension.probe", "mutatedProject": False}
    iface = System.Type.GetType(
        "_3S.CoDeSys.ScriptEngine.BasicFunctionality.IScriptProjectDeviceExtension, "
        "ScriptEngine")
    result["interfaceType"] = _text(iface)
    if iface is None:
        result["status"] = "interface_type_not_loadable"
        return result
    try:
        result["declaredMembers"] = sorted({_text(m.Name)
                                            for m in iface.GetMembers()})
    except Exception as exc:
        result["memberError"] = _text(exc)
    implementors = []
    scanned_types = 0
    try:
        for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
            try:
                types = assembly.GetTypes()
            except Exception:
                continue
            for candidate in types:
                scanned_types += 1
                try:
                    if iface.IsAssignableFrom(candidate):
                        implementors.append(_text(candidate.FullName))
                except Exception:
                    continue
    except Exception as exc:
        result["scanError"] = _text(exc)
    result["scannedTypeCount"] = scanned_types
    result["implementorTypes"] = implementors[:40]
    result["implementorCount"] = len(implementors)

    devices = []
    if project is not None:
        def visit(parent, prefix):
            for child in _children(parent):
                name = _object_name(child)
                if _is_device_node(child):
                    row = {"path": "/".join(prefix + [name]),
                           "runtimeType": _text(type(child))}
                    try:
                        row["implementsExtension"] = bool(
                            iface.IsAssignableFrom(child.GetType()))
                    except Exception as exc:
                        row["implementsExtension"] = _text(exc)
                    try:
                        row["addMember"] = bool(hasattr(child, "add"))
                    except Exception:
                        row["addMember"] = None
                    devices.append(row)
                visit(child, prefix + [name])
        try:
            visit(project, [])
        except Exception as exc:
            result["treeError"] = _text(exc)
    result["deviceObjects"] = devices
    result["deviceImplementors"] = [d for d in devices
                                   if d.get("implementsExtension") is True]
    # The interface's own add overloads are IDENTICAL to
    # IScriptDeviceObject.add(name, type, id, version, module), so the question
    # that decides the classification is which object provides it.  Test the
    # project itself and its direct children, not only device nodes.
    probes = []
    if project is not None:
        candidates = [("project", project)]
        try:
            for child in _children(project):
                candidates.append(("project/" + _object_name(child), child))
        except Exception as exc:
            result["childError"] = _text(exc)
        for label, obj in candidates:
            row = {"label": label, "runtimeType": _text(type(obj))}
            try:
                row["implementsExtension"] = bool(
                    iface.IsAssignableFrom(obj.GetType()))
            except Exception as exc:
                row["implementsExtension"] = _text(exc)
            probes.append(row)
    result["projectCandidates"] = probes
    result["projectImplementors"] = [p for p in probes
                                     if p.get("implementsExtension") is True]
    result["status"] = "observed"
    result["truth"] = ("A provider/implementor found here means the composition "
                       "API is reachable by reflection even though the dump has "
                       "no documented path to it; an empty result means the "
                       "documented interface is unreachable in this build.")
    return result


def _online_file_root():
    """Where device-side files may be written on this machine."""
    override = os.environ.get("CODESYS_ROUTE_ONLINE_FILE_ROOT")
    if override:
        return os.path.abspath(override)
    local = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~")
    return os.path.abspath(os.path.join(local, "PLC Engineering Suite", "codesys-bridge",
                                        "online-files"))


def _require_local_file_path(normalized):
    raw = _text(normalized.get("localPath") or "").strip()
    if not raw:
        raise OperationError(
            "localPath is required", "invalid_argument",
            {"allowedRoot": _online_file_root(),
             "next": {"then": "pass an absolute path under allowedRoot"}})
    target = os.path.abspath(raw)
    root = _online_file_root()
    if not (target == root or target.startswith(root + os.sep)):
        raise OperationError(
            "localPath must stay under the online file root",
            "unsafe_local_path",
            {"requested": target, "allowedRoot": root,
             "mutatedTarget": False,
             "next": {"then": "write under allowedRoot; the directory is created "
                              "on demand and the receipt reports the resolved path"}})
    return target


def _require_remote_path(normalized, key="remotePath"):
    raw = _text(normalized.get(key) or "").strip()
    if not raw:
        raise OperationError(
            key + " is required", "invalid_argument",
            {"next": {"then": "pass the device-side path, e.g. /PlcLogic or "
                              "/myfile.txt"}})
    return raw


def _require_connected(online_device, device_path, action):
    if bool(_get_member(online_device, "connected", "get_connected", False)):
        return
    raise OperationError(
        "%s needs a connected runtime" % action,
        "online_device_not_connected",
        {"devicePath": device_path, "connected": False, "mutatedTarget": False,
         "next": {"tool": "codesys_online_connect",
                  "arguments": {"confirm": "connect_online_device"},
                  "then": "connect first, then re-run; codesys_online_scan tells "
                          "you whether any device answers at all"}})


def _directory_entry_row(entry):
    return {
        "name": _text(_get_member(entry, "name", "get_name", "")),
        "isDirectory": bool(_get_member(entry, "is_directory",
                                        "get_is_directory", False)),
        "isFile": bool(_get_member(entry, "is_file", "get_is_file", False)),
        "size": _text(_get_member(entry, "size", "get_size", "")),
        "lastModification": _text(_get_member(
            entry, "last_modification_time", "get_last_modification_time", "")),
    }


def online_files_list(normalized):
    """Read-only: list a directory on the connected PLC."""
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    _require_connected(online_device, device_path, "listing device files")
    remote = _require_remote_path(normalized, "remoteDirectory")
    lister = getattr(online_device, "get_file_list_of_directory", None)
    if not hasattr(lister, "__call__"):
        raise OperationError(
            "this build has no get_file_list_of_directory on the online device",
            "online_file_api_unavailable",
            {"devicePath": device_path,
             "members": _member_names(online_device, ["file", "director"])})
    try:
        entries = lister(remote)
    except Exception as exc:
        raise OperationError(
            "the runtime refused the directory listing: " + _text(exc),
            "online_files_list_failed",
            {"devicePath": device_path, "remoteDirectory": remote})
    rows = []
    for entry in entries or []:
        rows.append(_directory_entry_row(entry))
    return {
        "devicePath": device_path,
        "remoteDirectory": remote,
        "count": len(rows),
        "entries": rows,
        "boundary": "Read-only listing of the connected runtime's file system.",
    }


def _online_file_root_mkdir(target):
    parent = os.path.dirname(target)
    if parent and not os.path.isdir(parent):
        try:
            os.makedirs(parent)
        except Exception:
            pass
    return target


def online_file_download(normalized):
    """Copy one file from the connected runtime to the local machine."""
    _require_confirmation(normalized, "download_online_file")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    # Validate the request BEFORE the device state: an unsafe or missing
    # argument must surface even while nothing is connected, otherwise the
    # caller cannot tell a bad request from an offline device.
    remote = _require_remote_path(normalized)
    local = _online_file_root_mkdir(_require_local_file_path(normalized))
    _require_connected(online_device, device_path, "downloading a device file")
    force = bool(normalized.get("forceOverwrite"))
    caller = getattr(online_device, "download_file", None)
    if not hasattr(caller, "__call__"):
        raise OperationError(
            "this build has no download_file on the online device",
            "online_file_api_unavailable",
            {"members": _member_names(online_device, ["file", "director"])})
    try:
        caller(local, remote, force)
    except Exception as exc:
        raise OperationError(
            "the runtime refused the download: " + _text(exc),
            "online_file_download_failed",
            {"devicePath": device_path, "remotePath": remote, "localPath": local})
    return {
        "devicePath": device_path,
        "remotePath": remote,
        "localPath": local,
        "exists": os.path.exists(local),
        "bytes": os.path.getsize(local) if os.path.exists(local) else None,
        "mutatedTarget": False,
        "boundary": "The file lands under the online file root on THIS machine; "
                    "the runtime was not modified.",
    }


def online_file_upload(normalized):
    """Copy one local file to the connected runtime (mutating)."""
    _require_confirmation(normalized, "upload_online_file")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    remote = _require_remote_path(normalized)
    local = _require_local_file_path(normalized)
    if not os.path.isfile(local):
        raise OperationError(
            "localPath does not exist", "local_file_missing",
            {"localPath": local,
             "next": {"then": "download it first or place it under the online "
                              "file root"}})
    _require_connected(online_device, device_path, "uploading a device file")
    force = bool(normalized.get("forceOverwrite"))
    caller = getattr(online_device, "upload_file", None)
    if not hasattr(caller, "__call__"):
        raise OperationError(
            "this build has no upload_file on the online device",
            "online_file_api_unavailable",
            {"members": _member_names(online_device, ["file", "director"])})
    try:
        # NOTE: the vendor argument order differs from download_file - remote first.
        caller(remote, local, force)
    except Exception as exc:
        raise OperationError(
            "the runtime refused the upload: " + _text(exc),
            "online_file_upload_failed",
            {"devicePath": device_path, "remotePath": remote, "localPath": local})
    return {
        "devicePath": device_path,
        "remotePath": remote,
        "localPath": local,
        "bytes": os.path.getsize(local),
        "mutatedTarget": True,
    }


def online_file_delete(normalized):
    """Delete one file on the connected runtime (destructive)."""
    _require_confirmation(normalized, "delete_online_file")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    _require_connected(online_device, device_path, "deleting a device file")
    remote = _require_remote_path(normalized)
    caller = getattr(online_device, "delete_file", None)
    if not hasattr(caller, "__call__"):
        raise OperationError(
            "this build has no delete_file on the online device",
            "online_file_api_unavailable",
            {"members": _member_names(online_device, ["file", "director"])})
    try:
        caller(remote)
    except Exception as exc:
        raise OperationError(
            "the runtime refused the delete: " + _text(exc),
            "online_file_delete_failed",
            {"devicePath": device_path, "remotePath": remote})
    return {"devicePath": device_path, "remotePath": remote,
            "mutatedTarget": True}


def online_source_upload(normalized):
    """Read the source archive back OFF the connected runtime."""
    _require_confirmation(normalized, "upload_online_source")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    local = _online_file_root_mkdir(_require_local_file_path(normalized))
    _require_connected(online_device, device_path, "uploading source from the device")
    caller = getattr(online_device, "upload_source", None)
    if not hasattr(caller, "__call__"):
        raise OperationError(
            "this build has no upload_source on the online device",
            "online_source_api_unavailable",
            {"members": _member_names(online_device, ["source", "archive"])})
    try:
        caller(local)
    except Exception as exc:
        raise OperationError(
            "the runtime refused the source upload: " + _text(exc),
            "online_source_upload_failed",
            {"devicePath": device_path, "localPath": local})
    return {
        "devicePath": device_path,
        "localPath": local,
        "exists": os.path.exists(local),
        "bytes": os.path.getsize(local) if os.path.exists(local) else None,
        "mutatedTarget": False,
        "boundary": "This is the compile-time SOURCE the runtime holds, not a "
                    "live memory image; it proves what was downloaded, not what "
                    "the running task is doing right now.",
    }


def online_source_download(normalized):
    """Write the project's source archive TO the connected runtime."""
    _require_confirmation(normalized, "download_online_source")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    _require_connected(online_device, device_path, "downloading source to the device")
    caller = getattr(online_device, "download_source", None)
    if not hasattr(caller, "__call__"):
        raise OperationError(
            "this build has no download_source on the online device",
            "online_source_api_unavailable",
            {"members": _member_names(online_device, ["source", "archive"])})
    compact = bool(normalized.get("compact"))
    try:
        caller(compact, None)
    except Exception as exc:
        raise OperationError(
            "the runtime refused the source download: " + _text(exc),
            "online_source_download_failed",
            {"devicePath": device_path, "compact": compact,
             "mutatedTarget": True})
    return {
        "devicePath": device_path,
        "compact": compact,
        "mutatedTarget": True,
        "boundary": "This writes the project source onto the device so it can be "
                    "read back later; it does not change the running program.",
    }


def _online_device_for_current_project(se):
    """The IScriptOnlineDevice wrapper for the open project's device."""
    try:
        device, device_path = _sim_device_object()
    except OperationError:
        raise OperationError(
            "no open project with a device, so there is nothing to connect to",
            "online_project_required",
            {"next": {"tool": "codesys_project_open",
                      "then": "open or create a disposable project first"}})
    creator = getattr(se.online, "create_online_device", None)
    if not hasattr(creator, "__call__"):
        raise OperationError(
            "this IDE has no create_online_device entry point",
            "online_device_unavailable",
            {"onlineMembers": _member_names(se.online, ["device", "online"])})
    return creator(device), _text(device_path)


def _confirm_error_next(code, message, data):
    """Give every confirmation-class failure an executable next step.

    Measured 2026-09-19 by auditing the delivered package: 58 raise sites
    answered `confirmation_required` / `disposable_confirmation_required`
    WITHOUT any next step, so a caller had to scrape the token out of the
    message text. Normalizing here fixes every site at once (and keeps the
    per-site messages untouched).
    """
    if not isinstance(data, dict):
        data = {"detail": data}
    if code not in ("confirmation_required", "disposable_confirmation_required"):
        return data
    if data.get("next"):
        return data
    if code == "disposable_confirmation_required":
        data.setdefault("next", {
            "arguments": {"disposable": True},
            "then": "re-send this tool with disposable=true (it only ever "
                    "touches projects under the disposable experiment root)",
        })
        return data
    token = _text(data.get("expected") or data.get("confirm") or "").strip()
    if not token:
        match = (re.search(r"confirm=([A-Za-z0-9_]+)", message)
                 or re.search(r"exactly equal ([A-Za-z0-9_]+)", message))
        if match:
            token = match.group(1)
    if token:
        data["expected"] = token
        data["next"] = {
            "arguments": {"confirm": token},
            "then": "re-send this same tool with that confirm token; nothing "
                    "was changed by this call",
        }
    else:
        data["next"] = {
            "then": "re-send with the confirm token named in error; nothing was "
                    "changed by this call",
        }
    return data


def _require_confirmation(normalized, expected):
    """Accept the published token (or any alias) for this gate.

    Measured 2026-09-19: the published cards use tokens like `online_write`
    while the bridge-side gates were written with `write_online_values`; both
    are accepted so the model never has to know which layer named it.
    """
    accepted = expected if isinstance(expected, (tuple, list)) else (expected,)
    actual = _text(normalized.get("confirm"))
    if actual not in accepted:
        raise OperationError(
            "confirm must exactly equal one of " + ", ".join(accepted),
            "confirmation_required",
            {"expected": accepted[0], "accepted": list(accepted),
             "next": {"arguments": {"confirm": accepted[0]},
                      "then": "re-send this same tool with that confirm token; "
                              "nothing was changed by this call"}})


def _online_connection_state(online_device, device_path):
    return {
        "devicePath": device_path,
        "connected": bool(_get_member(online_device, "connected",
                                      "get_connected", False)),
        "sharedConnected": bool(_get_member(online_device, "shared_connected",
                                            "get_shared_connected", False)),
        "currentUser": _text(_get_member(online_device,
                                         "current_logged_on_username",
                                         "get_current_logged_on_username", "")),
    }


def _online_target_key(value):
    """Normalize a project-device path for an exact, case-insensitive match."""
    text = _text(value).strip().replace("\\", "/")
    parts = [part.strip() for part in text.split("/") if part.strip()]
    return "/".join(parts).lower()


def _require_online_target_match(normalized, device_path):
    """Bind a credential write to the one device resolved from the project."""
    requested = normalized.get("target")
    if not isinstance(requested, _STRING_TYPES) or not requested.strip():
        raise OperationError(
            "target is required and must equal the current project's devicePath",
            "online_target_required",
            {"expectedTarget": device_path, "mutatedTarget": False,
             "next": {"tool": "codesys_online_device_state",
                      "then": "copy data.devicePath exactly into target and retry"}})
    requested_text = _text(requested).strip()
    if _online_target_key(requested_text) != _online_target_key(device_path):
        raise OperationError(
            "target does not match the current project's devicePath",
            "online_target_mismatch",
            {"requestedTarget": requested_text, "expectedTarget": device_path,
             "mutatedTarget": False,
             "next": {"tool": "codesys_online_device_state",
                      "then": "verify the open project, then copy data.devicePath "
                              "exactly into target; no credential was staged"}})
    return requested_text


def _credential_flag(credentials, name, default):
    value = credentials.get(name, default)
    if not isinstance(value, bool):
        raise OperationError(
            "credentials.%s must be a boolean" % name,
            "invalid_argument",
            {"path": "credentials.%s" % name, "expected": "boolean",
             "mutatedTarget": False})
    return value


def _clear_default_online_credentials(default_setter):
    """Best-effort rollback without ever returning credential values."""
    try:
        default_setter(None)
        return True, None
    except Exception as exc:
        return False, type(exc).__name__


def online_set_credentials(normalized):
    """Stage login and optional initial-user credentials for this bridge run.

    CODESYS exposes this through IScriptOnline.set_default_credentials and
    IScriptOnlineDevice.set_credentials_for_initial_user.  Both settings are
    consumed by a later connect/login; this call itself does not contact or
    mutate the PLC.  Passwords are intentionally absent from every result and
    error payload.
    """
    _require_confirmation(normalized, "set_online_credentials")
    credentials = normalized.get("credentials")
    if not isinstance(credentials, dict):
        raise OperationError(
            "credentials must be an object containing username and password",
            "invalid_argument",
            {"path": "credentials", "expected": "object",
             "mutatedTarget": False})
    username_value = credentials.get("username")
    password = credentials.get("password")
    if (not isinstance(username_value, _STRING_TYPES)
            or not _text(username_value).strip()):
        raise OperationError(
            "credentials.username must be a non-empty string",
            "invalid_argument",
            {"path": "credentials.username", "expected": "non-empty string",
             "mutatedTarget": False})
    if not isinstance(password, _STRING_TYPES) or len(password) == 0:
        raise OperationError(
            "credentials.password must be a non-empty string",
            "invalid_argument",
            {"path": "credentials.password", "expected": "non-empty string",
             "mutatedTarget": False})
    username = _text(username_value).strip()
    setup_initial = _credential_flag(credentials, "setupInitialUser", True)
    can_change = _credential_flag(credentials, "canChangePassword", True)
    must_change = _credential_flag(credentials, "mustChangePassword", False)

    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    _require_online_target_match(normalized, device_path)
    default_setter = getattr(se.online, "set_default_credentials", None)
    if not hasattr(default_setter, "__call__"):
        raise OperationError(
            "this IDE exposes no set_default_credentials entry point",
            "online_credentials_api_unavailable",
            {"method": "IScriptOnline.set_default_credentials",
             "onlineMembers": _member_names(se.online, ["credential"]),
             "devicePath": device_path, "mutatedTarget": False})
    initial_setter = getattr(
        online_device, "set_credentials_for_initial_user", None)
    if setup_initial and not hasattr(initial_setter, "__call__"):
        raise OperationError(
            "this IDE exposes no initial-user credential entry point",
            "online_initial_credentials_api_unavailable",
            {"method": "IScriptOnlineDevice.set_credentials_for_initial_user",
             "onlineDeviceMembers": _member_names(
                 online_device, ["credential", "initial", "user"]),
             "devicePath": device_path, "mutatedTarget": False,
             "next": {"arguments": {
                         "credentials": {"setupInitialUser": False}},
                      "then": "only use setupInitialUser=false when the runtime "
                              "already has this user"}})

    try:
        default_setter(username, password)
    except Exception as exc:
        cleared, clear_error_type = _clear_default_online_credentials(default_setter)
        raise OperationError(
            "the IDE rejected staging the default online credentials",
            "online_default_credentials_failed",
            {"method": "IScriptOnline.set_default_credentials",
             "exceptionType": type(exc).__name__,
             "defaultCredentialsCleared": cleared,
             "clearExceptionType": clear_error_type,
             "devicePath": device_path, "mutatedTarget": False,
             "passwordReturned": False})

    initial_staged = False
    if setup_initial:
        try:
            initial_setter(username, password, can_change, must_change)
            initial_staged = True
        except Exception as exc:
            cleared, clear_error_type = _clear_default_online_credentials(default_setter)
            raise OperationError(
                "the IDE rejected staging credentials for the initial runtime user",
                "online_initial_credentials_failed",
                {"method": (
                    "IScriptOnlineDevice.set_credentials_for_initial_user"),
                 "exceptionType": type(exc).__name__,
                 "defaultCredentialsCleared": cleared,
                 "clearExceptionType": clear_error_type,
                 "devicePath": device_path, "mutatedTarget": False,
                 "passwordReturned": False,
                 "next": {"arguments": {
                             "credentials": {"setupInitialUser": False}},
                          "then": "retry with setupInitialUser=false only if "
                                  "the runtime is already provisioned"}})

    return {
        "devicePath": device_path,
        "username": username,
        "defaultCredentialsSet": True,
        "initialUserCredentialsStaged": initial_staged,
        "setupInitialUser": setup_initial,
        "canChangePassword": can_change,
        "mustChangePassword": must_change,
        "passwordReturned": False,
        "mutatedTarget": False,
        "credentialsLifetime": "until_the_resident_bridge_script_ends",
        "next": {"tool": "codesys_online_connect",
                 "arguments": {"confirm": "connect_online_device"},
                 "verify": "read connected/currentUser from the connection result"},
        "boundary": (
            "Credentials are staged in the resident CODESYS scripting session "
            "for a later connect/download. This call does not contact the PLC "
            "and does not prove that authentication or initial-user creation "
            "succeeded on the runtime; verify the later connection result. "
            "Re-send after the bridge script restarts."),
    }


def online_connect(normalized):
    """Log in to the project's configured runtime target."""
    _require_confirmation(normalized, "connect_online_device")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    try:
        getattr(online_device, "connect")()
    except Exception as exc:
        raise OperationError(
            "the runtime refused the login: " + _text(exc),
            "online_connect_failed",
            {"devicePath": device_path, "mutatedTarget": False,
             "next": {"tool": "codesys_online_scan",
                      "then": "confirm a device answers on the network; the "
                              "target address itself is configured in the IDE "
                              "device communication settings, not by this API"}})
    state = _online_connection_state(online_device, device_path)
    state["mutatedTarget"] = True
    state["boundary"] = ("connect() logs in to whatever target the project is "
                         "configured for; it does not choose the target.")
    return state


def online_disconnect(normalized):
    """Release the login held by this IDE (mutating, confirm-gated)."""
    _require_confirmation(normalized, "disconnect_online_device")
    se = _sim_scriptengine()
    online_device, device_path = _online_device_for_current_project(se)
    try:
        getattr(online_device, "disconnect")()
    except Exception as exc:
        raise OperationError(
            "disconnect failed: " + _text(exc),
            "online_disconnect_failed",
            {"devicePath": device_path, "mutatedTarget": False})
    state = _online_connection_state(online_device, device_path)
    state["mutatedTarget"] = True
    return state


def _device_user_row(user):
    return {
        "name": _text(_get_member(user, "name", "get_name", "")),
        "flags": _text(_get_member(user, "flags", "get_flags", "")),
        # Deliberately never return the hash itself: presence is the useful
        # signal, the value is a credential.
        "hasPasswordHash": bool(_text(_get_member(
            user, "password_hash", "get_password_hash", ""))),
    }


def _device_group_row(group):
    def string_list(value):
        out = []
        try:
            for item in value or []:
                out.append(_text(item))
        except Exception:
            return []
        return out[:200]
    return {
        "name": _text(_get_member(group, "name", "get_name", "")),
        "flags": _text(_get_member(group, "flags", "get_flags", "")),
        "userMembers": string_list(_get_member(
            group, "user_members", "get_user_members", None)),
        "groupMembers": string_list(_get_member(
            group, "group_members", "get_group_members", None)),
    }


def _device_user_management(se, normalized):
    online_device, device_path = _online_device_for_current_project(se)
    plain = getattr(online_device, "create_user_management", None)
    live = getattr(online_device, "create_live_user_management", None)
    requested = _text(normalized.get("mode") or "auto").strip().lower()
    if requested not in ("auto", "live", "project"):
        raise OperationError(
            "mode must be one of auto, live, project",
            "invalid_argument",
            {"field": "mode", "actual": requested,
             "allowed": ["auto", "live", "project"],
             "next": {"arguments": {"mode": "auto"},
                      "then": "omit mode (auto tries the live interface first) "
                              "or pass one of the allowed values"}})
    if requested == "project":
        order = [("project", plain)]
    elif requested == "live":
        order = [("live", live)]
    else:
        # Measured 2026-09-19: PLCWinNT answers create_user_management with
        # "设备不支持指定的用户管理.请使用方法'create_live_user_management'获取另一个."
        # so the live interface is tried first and the project one kept as the
        # fallback rather than making the caller guess.
        order = [("live", live), ("project", plain)]
    attempts = []
    management = None
    chosen = None
    for label, creator in order:
        if not hasattr(creator, "__call__"):
            attempts.append({"mode": label, "ok": False,
                             "error": "this build exposes no %s"
                                      % ("create_live_user_management"
                                         if label == "live"
                                         else "create_user_management")})
            continue
        try:
            # Measured 2026-09-19: create_live_user_management() takes no
            # arguments while create_user_management(bool) does.
            management = creator() if label == "live" else creator(False)
            chosen = label
            attempts.append({"mode": label, "ok": True})
            break
        except Exception as exc:
            attempts.append({"mode": label, "ok": False, "error": _text(exc)})
    if management is None:
        vendor = attempts[-1].get("error") if attempts else None
        raise OperationError(
            "the device refused device user management in every mode this "
            "build exposes: " + _text(vendor),
            "device_user_management_unavailable",
            {"devicePath": device_path,
             "attempts": attempts,
             "rawVendorMessage": _text(vendor),
             "members": _member_names(online_device, ["user", "management"]),
             "next": {"tool": "codesys_online_connect",
                      "arguments": {"confirm": "connect_online_device"},
                      "then": "login to this device, then retry with "
                              "mode=\"live\" (the vendor message names the live "
                              "interface as the supported one)"}})
    return management, device_path, chosen, attempts


def online_device_users(normalized):
    """Read the project's device user/group picture (no runtime needed)."""
    se = _sim_scriptengine()
    management, device_path, mode, attempts = _device_user_management(se, normalized)
    users = []
    for user in _get_member(management, "users", "get_users", None) or []:
        users.append(_device_user_row(user))
    groups = []
    for group in _get_member(management, "groups", "get_groups", None) or []:
        groups.append(_device_group_row(group))
    return {
        "devicePath": device_path,
        "mode": mode,
        "attempts": attempts,
        "userCount": len(users),
        "groupCount": len(groups),
        "users": users,
        "groups": groups,
        "boundary": "This is the PROJECT-side device user management. The "
                    "runtime's own list is only known after "
                    "online.device_users_upload runs against a connected "
                    "device. Password hashes are reported as present/absent, "
                    "never as values.",
    }


def online_device_users_transfer(normalized, direction):
    """Move device user management between the project and the runtime."""
    expected = ("upload_device_users" if direction == "upload"
                else "download_device_users")
    _require_confirmation(normalized, expected)
    se = _sim_scriptengine()
    # Check the connection BEFORE building the user-management wrapper: with no
    # runtime the wrapper itself fails for an unrelated reason ("设备不支持指定的
    # 用户管理"), which would hide the real next step from the caller.
    online_device, device_path = _online_device_for_current_project(se)
    connected = bool(_get_member(online_device, "connected",
                                 "get_connected", False))
    if not connected:
        raise OperationError(
            "the device user list cannot be transferred while no runtime is "
            "connected",
            "device_user_management_requires_connection",
            {"devicePath": device_path, "direction": direction,
             "connected": False,
             "mutatedTarget": False,
             "next": {"tool": "codesys_online_connect",
                      "arguments": {"confirm": "connect_online_device"},
                      "then": "connect first, then re-run this transfer; use "
                              "codesys_online_scan when no device answers"}})
    management, device_path, mode, attempts = _device_user_management(se, normalized)
    try:
        getattr(management, direction)()
    except Exception as exc:
        raise OperationError(
            "the runtime refused the device user %s: %s" % (direction, _text(exc)),
            "device_user_management_" + direction + "_failed",
            {"devicePath": device_path, "direction": direction,
             "mutatedTarget": True})
    return {
        "devicePath": device_path,
        "direction": direction,
        "done": True,
        "mutatedTarget": True,
        "boundary": "upload = read the runtime's user list into the project; "
                    "download = write the project's user list to the runtime.",
    }


def _scan_target_row(target):
    return {
        "deviceName": _text(_get_member(target, "device_name", "get_device_name", "")),
        "typeName": _text(_get_member(target, "type_name", "get_type_name", "")),
        "vendorName": _text(_get_member(target, "vendor_name", "get_vendor_name", "")),
        "address": _text(_get_member(target, "address", "get_address", "")),
        "parentAddress": _text(_get_member(
            target, "parent_address", "get_parent_address", "")),
        "deviceId": _text(_get_member(target, "device_id", "get_device_id", "")),
        "blockDriver": _text(_get_member(
            target, "block_driver", "get_block_driver", "")),
        "blockDriverAddress": _text(_get_member(
            target, "block_driver_address", "get_block_driver_address", "")),
        "lockedInCache": bool(_get_member(
            target, "locked_in_cache", "get_locked_in_cache", False)),
    }


def online_scan(normalized):
    """Read-only: ask a gateway which devices answer on the network.

    The official surface is IScriptGateway.perform_network_scan() /
    get_cached_network_scan_result(), both returning
    IEnumerable<IScriptScanTargetDescription>. Measured 2026-09-19 on the vanilla
    line: this IDE exposes exactly one gateway (Gateway-1 / TCP/IP).
    """
    se = _sim_scriptengine()
    gateway, gateway_row, _all = _resolve_gateway(se, normalized)
    cached = bool(normalized.get("cached"))
    started = time.time()
    found = _get_member(
        gateway,
        "get_cached_network_scan_result" if cached else "perform_network_scan",
        "get_cached_network_scan_result" if cached else "perform_network_scan",
        None)
    if found is None:
        raise OperationError(
            "the gateway returned no scan result collection",
            "online_scan_unavailable",
            {"gateway": gateway_row,
             "method": "cached" if cached else "perform_network_scan"})
    rows = []
    for target in found:
        rows.append(_scan_target_row(target))
    elapsed = int(round((time.time() - started) * 1000))
    return {
        "gateway": gateway_row,
        "cached": cached,
        "count": len(rows),
        "targets": rows,
        "elapsedMs": elapsed,
        "boundary": "A scan reports what answered on the network. Whether the "
                    "project's target address matches a scanned device, and "
                    "whether the runtime accepts a login, are separate checks "
                    "(online.device_state / online.connect).",
    }


def _communication_settings_snapshot(online_device):
    """Read the online target picture without claiming a write capability.

    IScriptCommunicationSettings (official dump) declares only getters -
    device_address, device_name, gateway_guid, monitoring_interval, scanned_* -
    and No member in the dump returns the interface, so it is located by
    reflection on the live object instead of by a guessed property path.
    """
    keys = ("address", "gateway", "device_name", "monitoring", "secure",
            "tracking", "scanned", "prompt")
    snapshot = {
        "located": False,
        "source": None,
        "values": {},
        "reflectedMembers": _member_names(online_device, keys),
    }
    for holder_name, holder in (("online_device", online_device),):
        for candidate in ("communication_settings", "get_communication_settings"):
            try:
                value = getattr(holder, candidate)
            except Exception:
                continue
            if hasattr(value, "__call__"):
                try:
                    value = value()
                except Exception as exc:
                    snapshot["values"]["_call_error"] = _text(exc)
                    continue
            if value is None:
                continue
            snapshot["located"] = True
            snapshot["source"] = holder_name + "." + candidate
            for key in keys:
                for prefix in ("", "get_"):
                    try:
                        raw = getattr(value, prefix + key)
                    except Exception:
                        continue
                    if hasattr(raw, "__call__"):
                        try:
                            raw = raw()
                        except Exception:
                            continue
                    snapshot["values"][prefix + key] = _text(raw)
            break
        if snapshot["located"]:
            break
    return snapshot


def online_device_state(normalized):
    """Read-only: is a PLC connected through the configured target?"""
    se = _sim_scriptengine()
    device, device_path = _sim_device_object()
    creator = getattr(se.online, "create_online_device", None)
    if not hasattr(creator, "__call__"):
        raise OperationError(
            "this IDE has no create_online_device entry point",
            "online_device_unavailable",
            {"onlineMembers": _member_names(se.online, ["device", "online"])})
    online_device = creator(device)
    return {
        "devicePath": _text(device_path),
        "onlineDeviceType": _text(type(online_device)),
        "connected": bool(_get_member(online_device, "connected",
                                      "get_connected", False)),
        "sharedConnected": bool(_get_member(online_device, "shared_connected",
                                            "get_shared_connected", False)),
        "currentUser": _text(_get_member(online_device,
                                         "current_logged_on_username",
                                         "get_current_logged_on_username", "")),
        "members": _member_names(online_device,
                                 ["connect", "disconnect", "user", "file",
                                  "download", "upload", "license", "source"]),
        "communicationSettings": _communication_settings_snapshot(online_device),
        "boundary": "Read-only. A false connected value means this IDE is not "
                    "logged in to a runtime; it is not evidence that no device "
                    "is reachable (run online.scan for that).",
    }


def _text_map(value, limit=40):
    """Best-effort snapshot of a .NET dictionary or collection as text pairs.

    Gateway driver parameters arrive as IDictionary<object, object>; the values
    are vendor objects, so every entry is stringified defensively and the walk
    is bounded (a gateway can expose an open-ended parameter set).
    """
    if value is None:
        return {}
    out = {}
    try:
        items = getattr(value, "items", None)
        if items is not None:
            for index, pair in enumerate(items()):
                if index >= limit:
                    break
                out[_text(pair[0])] = _text(pair[1])
            return out
        for index, item in enumerate(value):
            if index >= limit:
                break
            out[str(index)] = _text(item)
        return out
    except Exception:
        return {"_unavailable": _text(value)}


def _gateway_row(gateway):
    driver = _get_member(gateway, "gateway_driver", "get_gateway_driver", None)
    driver_row = None
    if driver is not None:
        driver_row = {
            "name": _text(_get_member(driver, "name", "get_name", "")),
            "guid": _text(_get_member(driver, "guid", "get_guid", "")),
            "parameters": _text_map(_get_member(
                driver, "gateway_parameters", "get_gateway_parameters", None)),
        }
    return {
        "name": _text(_get_member(gateway, "name", "get_name", "")),
        "guid": _text(_get_member(gateway, "guid", "get_guid", "")),
        "driver": driver_row,
        "configParams": _text_map(_get_member(
            gateway, "config_params", "get_config_params", None)),
    }


def _online_gateways(se):
    """The IScriptGateways collection, or None when this IDE has none."""
    collection = _get_member(se.online, "gateways", "get_gateways", None)
    if collection is None:
        return None
    rows = []
    for gateway in collection:
        rows.append(_gateway_row(gateway))
    return rows


def _resolve_gateway(se, normalized):
    collection = _get_member(se.online, "gateways", "get_gateways", None)
    if collection is None:
        raise OperationError(
            "this IDE exposes no gateway collection on the online object",
            "online_gateways_unavailable",
            {"onlineType": _text(type(se.online))})
    wanted_guid = _text(normalized.get("gatewayGuid") or "").strip().lower()
    wanted_name = _text(normalized.get("gatewayName") or "").strip().lower()
    rows = []
    for gateway in collection:
        row = _gateway_row(gateway)
        rows.append((gateway, row))
    if wanted_guid or wanted_name:
        for gateway, row in rows:
            if wanted_guid and _text(row.get("guid")).lower() == wanted_guid:
                return gateway, row, rows
            if wanted_name and _text(row.get("name")).lower() == wanted_name:
                return gateway, row, rows
        raise OperationError(
            "no gateway matches gatewayGuid/gatewayName",
            "gateway_not_found",
            {"requested": {"guid": wanted_guid or None, "name": wanted_name or None},
             "available": [row for _gateway, row in rows],
             "next": "call online.gateways for the exact name/guid of this IDE"})
    if not rows:
        raise OperationError(
            "this IDE reports no gateways, so no network scan target exists",
            "gateway_not_found",
            {"available": [],
             "next": "add a gateway in the IDE, then call online.gateways again"})
    return rows[0][0], rows[0][1], rows


def _member_names(value, keywords, limit=120):
    """Reflect a live vendor object's members; evidence for capability probes."""
    if value is None:
        return []
    try:
        names = set(member.Name for member in value.GetType().GetMembers())
    except Exception as exc:
        return ["<reflection failed: " + _text(exc) + ">"]
    lowered = [str(name).lower() for name in keywords]
    selected = sorted(name for name in names
                      if any(key in str(name).lower() for key in lowered))
    return selected[:limit]


def online_gateways(normalized):
    """Read-only: every gateway this IDE can scan or connect through."""
    se = _sim_scriptengine()
    rows = _online_gateways(se)
    if rows is None:
        raise OperationError(
            "the online object exposes no gateways collection",
            "online_gateways_unavailable",
            {"onlineMembers": _member_names(se.online, ["gateway"])})
    return {
        "count": len(rows),
        "gateways": rows,
        "boundary": "Listing gateways is read-only. Scanning the network and "
                    "connecting to a target are separate operations.",
    }


def _online_target_report(normalized=None):
    """Which runtime the online.* family is talking to, told honestly."""
    report = {"target": _text((normalized or {}).get("target") or "").strip() or None,
              "devicePath": None, "deviceSimulationMode": None,
              "runtimeKind": None}
    try:
        device, device_path = _sim_device_object()
        report["devicePath"] = _text(device_path)
        report["deviceSimulationMode"] = bool(device.get_simulation_mode())
        report["runtimeKind"] = ("simulated-runtime"
                                 if report["deviceSimulationMode"]
                                 else "real-device")
    except OperationError as exc:
        report["targetResolution"] = _text(exc)
    return report


_ONLINE_FAMILY_BOUNDARY = (
    "The online.* family drives the SAME resident online session machinery as "
    "sim.* (Measured 2026-09-19: the platform surface is "
    "IScriptOnlineApplication.login/logout/start/stop/reset + "
    "read_value(s) + set_prepared_value -> write_prepared_values / "
    "force_prepared_values / unforce_all_values + create_boot_application + "
    "source_download). When the open project's device has simulation mode ON "
    "the session talks to the simulated runtime; with it OFF the same calls "
    "target a real PLC through the configured communication settings and fail "
    "closed when nothing is reachable. Always read data.targetReport.runtimeKind and repeat "
    "it in your answer."
    " UNLIKE sim.*, the online family NEVER switches the project's device into "
    "simulation mode (simulationModeUntouched=true): it reports the mode the "
    "project already has, so a real-device session is never silently retargeted "
    "onto the simulator. This bridge's application-delivery path uses "
    "IScriptOnlineApplication.login(OnlineChangeOption, deleteForeignApps) - "
    "the IDE's Download/Online-Change flow. OperatingState reports sampled "
    "current/transient status, not an event log or a program identity; missing "
    "download/online_change bits do not prove no transfer occurred. Use "
    "codesys_online_download for explicit delivery, and distinguish "
    "downloadEvidence from behavioral verification. A readable variable or "
    "positive value alone does not prove that the edited source was delivered."
)


def _online_items(normalized):
    """Accept both card shapes: expressions[] + values, or items[]."""
    args = normalized if isinstance(normalized, dict) else {}
    items = args.get("items")
    if isinstance(items, list) and items:
        return items
    expressions = args.get("expressions")
    if isinstance(expressions, list) and expressions:
        values = args.get("values")
        if isinstance(values, list) and len(values) == len(expressions):
            return [{"expression": _text(expr), "value": value}
                    for expr, value in zip(expressions, values)]
        return [{"expression": _text(expr)} for expr in expressions]
    expression = args.get("expression")
    if expression:
        item = {"expression": _text(expression)}
        if "value" in args:
            item["value"] = args.get("value")
        return [item]
    return []


def online_session_action(normalized, action):
    """login/logout/start/stop/state on the resident online session."""
    if action == "state":
        _se, _session, report = _online_observe_session()
        payload = _sim_session_report(report)
    else:
        payload = sim_online_native({"action": action,
                                     "changeOption": normalized.get("changeOption")},
                                    manage_simulation=False)
    payload["action"] = action
    payload["targetReport"] = _online_target_report(normalized)
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_read(normalized):
    """Read live values by expression (single or batch)."""
    items = _online_items(normalized)
    if not items or any("expression" not in item for item in items):
        raise OperationError(
            "read needs expressions[] or items[].expression",
            "invalid_argument",
            {"field": "expressions",
             "next": {"arguments": {"expressions": ["PLC_PRG.xOut"]},
                      "then": "pass the exact qualified names to read"}})
    _se, session, report = _online_observe_session(require_login=True)
    payload = {"values": _sim_read_items(session, items)}
    payload.update(_sim_session_report(report))
    payload["targetReport"] = _online_target_report(normalized)
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_write(normalized, force_mode=False):
    """Write (or force) values through the prepared-value API."""
    expected = (("force_online_values", "online_force") if force_mode
                else ("write_online_values", "online_write"))
    _require_confirmation(normalized, expected)
    items = _online_items(normalized)
    if not items or any("value" not in item for item in items):
        raise OperationError(
            "write needs values: pass items[{expression,value}] or "
            "expressions[] plus values[] of equal length",
            "invalid_argument",
            {"field": "items",
             "next": {"arguments": {"items": [{"expression": "PLC_PRG.xStart",
                                               "value": True}]},
                      "then": "re-send with one value per expression"}})
    # Writing values is not an instruction to log in, download, or start a PLC.
    # In particular, post-reset inputs must be writable before the first scan.
    se, session, report = _online_observe_session(require_login=True)
    payload = _sim_write_items(session, items, force=bool(force_mode))
    report["readOnly"] = False
    report["online"] = _sim_state(se, session)
    report["forcedExpressions"] = _sim_forced_list(session)
    payload.update(_sim_session_report(report))
    payload["boundary"] = _SIM_BOUNDARY
    payload["mode"] = "force" if force_mode else "write"
    payload["platformCalls"] = (["set_prepared_value"] * len(items)
                               + (["force_prepared_values"] if force_mode
                                  else ["write_prepared_values"]))
    payload["targetReport"] = _online_target_report(normalized)
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_forced(normalized):
    _se, _session, report = _online_observe_session()
    payload = _sim_session_report(report)
    payload["targetReport"] = _online_target_report(normalized)
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_unforce_all(normalized):
    _require_confirmation(normalized, ("unforce_online_values", "online_unforce_all"))
    se, session, report = _online_observe_session(require_login=True)
    before = _sim_forced_list(session)
    session.unforce_all_values()
    report["readOnly"] = False
    report["online"] = _sim_state(se, session)
    report["forcedExpressions"] = _sim_forced_list(session)
    payload = _sim_session_report(report)
    payload.update({"forcedBefore": before, "forcedAfter": report["forcedExpressions"],
                    "boundary": _SIM_BOUNDARY})
    payload["targetReport"] = _online_target_report(normalized)
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_reset(normalized):
    """Reset the application (IScriptOnlineApplication2.reset)."""
    _require_confirmation(normalized, ("reset_online_application", "online_reset"))
    se = _sim_scriptengine()
    option_name = _text(normalized.get("mode") or "Warm").strip()
    available_modes = [name for name in ("Warm", "Cold", "Original")
                       if getattr(se.ResetOption, name, None) is not None]
    option = (getattr(se.ResetOption, option_name, None)
              if option_name in available_modes else None)
    if option is None:
        raise OperationError(
            "unknown reset mode " + option_name,
            "invalid_argument",
            {"field": "mode", "actual": option_name,
             "availableModes": available_modes, "defaultMode": "Warm",
             "onlineSessionTouched": False,
             "next": {"then": "use an availableModes member; omit mode "
                              "for Warm (keep RETAIN; initialize ordinary variables)"}})
    session, report = _sim_ensure_online(manage_simulation=False, start_if_stopped=False)[1:]
    reset = getattr(session, "reset", None)
    if not hasattr(reset, "__call__"):
        raise OperationError(
            "this online session has no reset (IScriptOnlineApplication2)",
            "online_reset_unavailable",
            {"sessionType": _text(type(session))})
    online_before = report.get("online")
    reset(option, bool(normalized.get("forceKill")))
    # Reset returns with the application normally stopped. Never reuse the
    # RUN observation made while establishing the session before this call.
    report["online"] = _sim_state(se, session)
    report["forcedExpressions"] = _sim_forced_list(session)
    stopped = _text(report["online"].get("applicationState")).lower() == "stop"
    payload = {"reset": stopped, "resetRequested": True,
               "resetCompleted": stopped, "mode": option_name,
               "forceKill": bool(normalized.get("forceKill")),
               "onlineBefore": online_before}
    payload.update(_sim_session_report(report))
    payload["targetReport"] = _online_target_report(normalized)
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_create_boot(normalized):
    """Create a boot application on the target (persists what is downloaded)."""
    _require_confirmation(normalized, ("create_boot_application", "online_create_boot"))
    _se, session, report = _sim_ensure_online(manage_simulation=False)
    creator = getattr(session, "create_boot_application", None)
    if not hasattr(creator, "__call__"):
        raise OperationError(
            "this online session has no create_boot_application",
            "online_boot_unavailable",
            {"sessionType": _text(type(session))})
    creator()
    payload = {"bootApplicationCreated": True}
    payload.update(_sim_session_report(report))
    payload["targetReport"] = _online_target_report(normalized)
    payload["boundary"] = ("A boot application makes the target start the "
                           "downloaded program after a reboot; it does not "
                           "change the running program by itself.")
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


_DOWNLOAD_CHANGE_OPTIONS = {"never": "Never", "try": "Try", "force": "Force"}
_DOWNLOAD_INTENTS = {
    "full_download": "never",
    "download_or_online_change": "try",
    "online_change_only": "force",
}


def _online_change_option(se, option_name, error_code="online_change_option_unavailable"):
    """Resolve only the requested vendor enum; never weaken Force to Try.

    Some ScriptEngine versions return None for dynamic getattr on this enum
    while direct attribute access works. Each branch deliberately names the
    same member, so a missing Force cannot authorize a full download.
    """
    if option_name not in ("Never", "Try", "Force"):
        raise OperationError(
            "unknown OnlineChangeOption " + _text(option_name),
            "invalid_argument",
            {"field": "changeOption", "actual": _text(option_name),
             "supported": ["Never", "Try", "Force"],
             "loginIssued": False, "mutatedTarget": False})
    try:
        if option_name == "Never":
            option = se.OnlineChangeOption.Never
        elif option_name == "Force":
            option = se.OnlineChangeOption.Force
        else:
            option = se.OnlineChangeOption.Try
        if option is not None:
            return option
    except BaseException as exc:
        raw = _text(exc)
    else:
        raw = "the requested enum member is unavailable"
    raise OperationError(
        "this IDE exposes no usable OnlineChangeOption." + option_name,
        error_code,
        {"changeOption": option_name, "rawVendorMessage": raw,
         "loginIssued": False, "mutatedTarget": False,
         "fallbackApplied": False})


def _online_download_contract(normalized):
    """Validate delivery policy before build/save or native session changes."""
    intent = normalized.get("deliveryIntent")
    if "deliveryIntent" in normalized and intent not in tuple(_DOWNLOAD_INTENTS):
        raise OperationError(
            "deliveryIntent must be full_download, download_or_online_change "
            "or online_change_only", "invalid_argument",
            {"field": "deliveryIntent", "actual": intent,
             "supported": sorted(_DOWNLOAD_INTENTS),
             "mutatedProject": False, "mutatedTarget": False})
    option_name = _text(normalized.get("changeOption") or
                        _DOWNLOAD_INTENTS.get(intent, "try")).strip().lower()
    if option_name not in _DOWNLOAD_CHANGE_OPTIONS:
        raise OperationError(
            "changeOption must be one of never, try, force", "invalid_argument",
            {"field": "changeOption", "actual": option_name,
             "supported": sorted(_DOWNLOAD_CHANGE_OPTIONS),
             "mutatedProject": False, "mutatedTarget": False,
             "next": {"then": "never requires a full download; try permits "
                      "an online change or a full download; force permits "
                      "only an online change and must refuse if impossible"}})
    if intent is not None and option_name != _DOWNLOAD_INTENTS[intent]:
        raise OperationError(
            "deliveryIntent and changeOption authorize different actions",
            "invalid_argument",
            {"field": "deliveryIntent", "deliveryIntent": intent,
             "changeOption": option_name,
             "requiredChangeOption": _DOWNLOAD_INTENTS[intent],
             "mutatedProject": False, "mutatedTarget": False})
    if intent is None:
        intent = next(name for name, option in _DOWNLOAD_INTENTS.items()
                      if option == option_name)
    report = {"changeOption": option_name, "deliveryIntent": intent,
              "allowFullDownload": option_name != "force",
              "loginIssued": False, "startIssued": False,
              "stopIssued": False, "unforceIssued": False,
              "logoutIssued": False}
    for name, default in (("compileFirst", True), ("deleteForeignApps", False),
                          ("startAfterDownload", False),
                          ("createBootAfterDownload", False)):
        value = normalized.get(name, default)
        if not isinstance(value, bool):
            raise OperationError(
                name + " must be a boolean", "invalid_argument",
                {"field": name, "actual": value,
                 "mutatedProject": False, "mutatedTarget": False})
        report[name] = value
    return report


def online_download(normalized):
    """Deliver the edited program to the runtime (the platform's download path).

    This bridge uses the CODESYS Download / Online-Change flow through
    ``IScriptOnlineApplication.login(OnlineChangeOption, delete_foreign_apps)``,
    and samples the target's current/transient ``operation_state``
    (OperatingState.download / online_change / run_after_download /
    store_bootproject). This tool compiles what is in the editor, saves it, logs
    in with the requested OnlineChangeOption and returns the platform's own
    before/after evidence - it never claims a download the target did not
    report, and it never switches the project's device into simulation mode.
    """
    _require_project()
    _require_confirmation(normalized,
                          ("download_online_application", "online_download"))
    report = _online_download_contract(normalized)
    option_name = report["changeOption"]
    se = _sim_scriptengine()
    option = _online_change_option(se, _DOWNLOAD_CHANGE_OPTIONS[option_name],
                                   "online_download_unavailable")
    app_obj, app_path = _sim_application_object()
    app_guid = _text(getattr(app_obj, "guid", ""))
    report["applicationPath"] = app_path
    report["applicationGuid"] = app_guid or None
    if report["compileFirst"]:
        try:
            summary = _build_project()
            failures = list(_compile_gate_failures(summary))
        except OperationError:
            raise
        except BaseException as exc:
            raise OperationError(
                "the IDE build raised a vendor exception: " + _text(exc),
                "build_vendor_exception",
                {"mutatedProject": True, "mutatedTarget": False,
                 "rawVendorMessage": _text(exc),
                 "next": {"tool": "codesys_project_save",
                          "then": "save the project, then re-run "
                                  "codesys_online_download"}})
        report["compile"] = {
            "acceptanceVerdict": summary.get("acceptanceVerdict"),
            "compileOk": summary.get("compileOk"),
            "observedErrorCount": summary.get("observedErrorCount"),
            "observedWarningCount": summary.get("observedWarningCount"),
            "compileStatus": summary.get("compileStatus"),
        }
        if failures:
            raise OperationError(
                "the program does not compile, so NOTHING was downloaded",
                "download_blocked_by_compile",
                {"compile": report["compile"],
                 "compileGateFailures": failures,
                 "mutatedProject": False, "mutatedTarget": False,
                 "next": {"tool": "codesys_build_diagnostics",
                          "then": "fix the reported diagnostics and repeat "
                                  "codesys_online_download"}})
        report["compiled"] = True
    try:
        project.save()
        report["saved"] = True
    except BaseException as exc:
        report["saved"] = False
        report["saveError"] = _text(exc)
        report["mutatedTarget"] = False
        raise OperationError(
            "the project could not be saved; no login or download was issued",
            "download_blocked_by_save", report)
    try:
        device, device_path = _sim_device_object()
        report["devicePath"] = device_path
        report["simulationModeBefore"] = bool(device.get_simulation_mode())
        report["simulationModeAfter"] = report["simulationModeBefore"]
    except BaseException as exc:
        report["deviceResolutionError"] = _text(exc)
    session = _SIM_SESSION.get("online")
    if session is not None and _SIM_SESSION.get("appGuid") not in (None, app_guid):
        # A different target does not authorize STOP/unforce/logout on the
        # previously attached application. Bind only the requested target.
        _SIM_SESSION.update({"online": None, "key": None, "appGuid": None})
        session = None
    if session is None:
        try:
            session = se.online.create_online_application(app_obj)
        except BaseException as exc:
            raise OperationError(
                "could not create an online application for the open project: %s"
                % _text(exc), "online_download_unavailable",
                {"applicationPath": app_path, "mutatedProject": False,
                 "mutatedTarget": False})
        _SIM_SESSION.update({"online": session, "key": _sim_session_key(app_obj),
                             "appGuid": app_guid, "appPath": app_path})
        report["sessionCreated"] = True
    before = _sim_state(se, session)
    report["before"] = {
        "loggedIn": before.get("loggedIn"),
        "applicationState": before.get("applicationState"),
        "operationState": before.get("operationState"),
        "operationStateFlags": before.get("operationStateFlags"),
    }
    if option_name == "force":
        flags = (before.get("operationStateFlags") or {}).get("flags") or {}
        loaded = flags.get("program_loaded")
        report["forcePrecondition"] = {
            "programLoaded": loaded,
            "flagsSource": (before.get("operationStateFlags") or {}).get("source"),
            "checkedBeforeLogin": True,
        }
        if loaded is not True:
            # Measured SP22 simulation: Force still performs the initial
            # transfer when no program exists. Do not entrust that case to
            # the enum alone, or mistake unknown state for a loaded program.
            report["mutatedTarget"] = False
            raise OperationError(
                "online_change_only requires an already loaded program with "
                "known target state; no login was issued",
                "online_change_requires_loaded_program", report)
    # ScriptOnline.login explicitly performs a fresh login when already
    # logged in. No bridge STOP/unforce/logout is needed before online change.
    report["reloginByVendor"] = bool(before.get("loggedIn"))
    report["loginIssued"] = True
    try:
        session.login(option, report["deleteForeignApps"])
    except BaseException as exc:
        report.update({"rawVendorMessage": _text(exc),
                       "fallbackApplied": False, "mutatedTarget": None})
        raise OperationError(
            "the IDE rejected the requested delivery; no fallback or start was issued",
            "online_delivery_rejected", report)
    after = _sim_state(se, session)
    report["after"] = {
        "loggedIn": after.get("loggedIn"),
        "applicationState": after.get("applicationState"),
        "operationState": after.get("operationState"),
        "operationStateFlags": after.get("operationStateFlags"),
    }
    if after.get("loggedIn") is not True:
        report.update({"fallbackApplied": False, "mutatedTarget": None})
        raise OperationError(
            "delivery login was not confirmed; no start or boot creation was issued",
            "online_delivery_login_unconfirmed", report)
    _SIM_SESSION.update({"key": _sim_session_key(app_obj),
                         "appGuid": app_guid, "appPath": app_path})
    evidence = _download_evidence(before, after)
    report["downloadEvidence"] = evidence
    report["downloadVerdict"] = _download_verdict(evidence)
    if option_name == "force" and evidence.get("downloadBit"):
        report.update({"mutatedTarget": True, "fallbackApplied": False})
        raise OperationError(
            "the IDE reported a download despite online_change_only; no start "
            "or boot creation was issued, and no automatic rollback was attempted",
            "online_change_policy_violated", report)
    if report["startAfterDownload"]:
        state = _sim_state(se, session)
        if _text(state.get("applicationState")).strip().lower() != "run":
            session.start()
            report["startIssued"] = True
    if report["createBootAfterDownload"]:
        creator = getattr(session, "create_boot_application", None)
        if not hasattr(creator, "__call__"):
            report["bootApplicationCreated"] = False
            report["bootError"] = "this online session has no create_boot_application"
        else:
            creator()
            report["bootApplicationCreated"] = True
    final = _sim_state(se, session)
    report["online"] = final
    report["forcedExpressions"] = _sim_forced_list(session)
    # These reads are observations, not a program fingerprint. A caller may
    # supply a new-program marker and compare it with an expected behavior;
    # complete=True only says every requested expression could be read.
    verify = [_text(item).strip()
              for item in (normalized.get("verifyExpressions") or [])
              if _text(item).strip()][:8]
    if verify:
        rows = []
        complete = True
        for expression in verify:
            try:
                raw = _sim_read_batch(session, [expression])[0]
                rows.append({"expression": expression, "read": True,
                             "raw": _text(raw), "value": _sim_norm(raw),
                             "readMethod": "read_values", "atomicSnapshot": False})
            except BaseException as exc:
                complete = False
                rows.append({"expression": expression, "read": False,
                             "error": _text(exc)})
        report["verification"] = {"expressions": verify, "results": rows,
                                  "complete": complete}
    payload = {"action": "download"}
    payload.update(_sim_session_report(report))
    payload["deliveryIntent"] = report["deliveryIntent"]
    payload["allowFullDownload"] = report["allowFullDownload"]
    payload["downloadEvidence"] = report["downloadEvidence"]
    payload["downloadVerdict"] = report["downloadVerdict"]
    payload["programLoadedByLogin"] = bool(
        report["downloadEvidence"].get("transferInferred"))
    payload["downloadBitObserved"] = bool(
        report["downloadEvidence"].get("downloadBit"))
    payload["onlineChangeBitObserved"] = bool(
        report["downloadEvidence"].get("onlineChangeBit"))
    payload["verification"] = report.get("verification")
    payload["simulationModeUntouched"] = True
    payload["platformCalls"] = (
        (["Application.build"] if report["compileFirst"] else []) + ["Project.save"] +
        (["IScriptOnline.create_online_application"]
         if report.get("sessionCreated") else []) + [
        "IScriptOnlineApplication.login(OnlineChangeOption.%s, deleteForeignApps=%s)"
        % (_DOWNLOAD_CHANGE_OPTIONS[option_name],
           report["deleteForeignApps"]),
    ])
    payload["targetReport"] = _online_target_report(normalized)
    payload["boundary"] = (
        "downloadVerdict summarizes sampled OperatingState. operation_state "
        "is a STATE bitmask, not an event log or source fingerprint; transient "
        "download/online_change bits may clear before sampling. The verdicts are: "
        "download_bit_observed / online_change_bit_observed (the transient bit "
        "was still set), program_loaded_by_login (nothing was loaded before and "
        "the program is loaded now, a transfer inferred from the state transition), "
        "already_loaded_no_transfer_evidence (a program was already loaded; "
        "no transfer outcome can be concluded), unproven_no_operation_state, "
        "no_program_on_target. verification.complete means requested reads "
        "succeeded, not that their values prove delivery. Compare a known "
        "program marker or behavior with explicit expectations. "
        "allowFullDownload is the requested policy, not independent proof of "
        "the vendor's internal action. This tool never switches the device into "
        "simulation mode, so a real-device project stays a real-device project."
    )
    payload["familyBoundary"] = _ONLINE_FAMILY_BOUNDARY
    return payload


def online_gateway_drivers(normalized):
    """Read-only: which gateway drivers (protocols) this IDE can use."""
    se = _sim_scriptengine()
    collection = _get_member(se.online, "gateway_drivers",
                             "get_gateway_drivers", None)
    if collection is None:
        raise OperationError(
            "the online object exposes no gateway_drivers collection",
            "online_gateway_drivers_unavailable",
            {"onlineMembers": _member_names(se.online, ["gateway", "driver"])})
    rows = []
    for driver in collection:
        parameters = []
        raw_parameters = _get_member(driver, "gateway_parameters",
                                     "get_gateway_parameters", None)
        # Measured 2026-09-19: this is an enumerable collection of
        # IScriptGatewayParameterDescription, not a dictionary, so iterate it
        # directly and keep the stringify path only as a fallback.
        entries = []
        if raw_parameters is not None:
            try:
                entries = list(raw_parameters)
            except Exception:
                entries = []
        if entries:
            for value in entries[:60]:
                row = {}
                # The vendor hands back IScriptGatewayParameterDescription
                # objects here, so the parameter metadata (name/description/
                # default/type) is readable instead of being stringified.
                for field in ("id", "name", "description", "default_value",
                              "parameter_type"):
                    found = _get_member(value, field, "get_" + field, None)
                    if found is not None:
                        row[field] = _text(found)
                parameters.append(row)
        else:
            parameters = [{"key": k, "value": v}
                          for k, v in _text_map(raw_parameters).items()]
        rows.append({
            "name": _text(_get_member(driver, "name", "get_name", "")),
            "guid": _text(_get_member(driver, "guid", "get_guid", "")),
            "parameterCount": len(parameters),
            "parameters": parameters,
        })
    return {
        "count": len(rows),
        "drivers": rows,
        "boundary": "Read-only list of installed gateway drivers. Adding or "
                    "removing a gateway is not implemented.",
    }


def online_probe(normalized):
    """Read-only: measure the online surface this IDE really exposes.

    The official dump documents IScriptGateways / IScriptGateway /
    IScriptCommunicationSettings, but the object graph that hands them to a
    script is not in that dump. This probe reflects the live objects so the
    mapping is measured on this machine instead of guessed.
    """
    se = _sim_scriptengine()
    report = {
        "onlineType": _text(type(se.online)),
        "onlineMembers": _member_names(
            se.online, ["gateway", "device", "online", "scan", "communication"]),
        "gateways": [],
        "gatewayMembers": [],
        "deviceBinding": None,
    }
    rows = _online_gateways(se)
    report["gateways"] = rows if rows is not None else []
    if report["gateways"]:
        collection = _get_member(se.online, "gateways", "get_gateways", None)
        for gateway in collection:
            report["gatewayMembers"] = _member_names(
                gateway, ["scan", "address", "driver", "config", "name", "guid"])
            break
    if normalized.get("probeDevice", True):
        try:
            device, device_path = _sim_device_object()
            # NOTE: _get_member *invokes* a callable member, so it must not be
            # used to obtain a method for a later call. Bind the method here.
            creator = getattr(se.online, "create_online_device", None)
            report["creatorInfo"] = {
                "type": _text(type(creator)),
                "repr": _text(repr(creator))[:200],
                "callable": bool(hasattr(creator, "__call__")),
            }
            report["onlineMethodSignatures"] = []
            try:
                for method in se.online.GetType().GetMethods():
                    name = str(method.Name)
                    if "device" not in name.lower():
                        continue
                    report["onlineMethodSignatures"].append(
                        name + "(" + ", ".join(
                            _text(parameter.ParameterType) for parameter
                            in method.GetParameters()) + ")")
            except Exception as exc:
                report["onlineMethodSignatures"] = ["<reflection failed: "
                                                    + _text(exc) + ">"]
            if not hasattr(creator, "__call__"):
                raise RuntimeError(
                    "create_online_device is not callable (got %s)"
                    % _text(type(creator)))
            online_device = creator(device)
            report["deviceBinding"] = {
                "devicePath": _text(device_path),
                "onlineDeviceType": _text(type(online_device)),
                "members": _member_names(online_device,
                                         ["connect", "address", "gateway",
                                          "communication", "user", "file",
                                          "download", "license", "disconnect"]),
                "connected": bool(_get_member(online_device, "connected",
                                              "get_connected", False)),
                "sharedConnected": bool(_get_member(online_device, "shared_connected",
                                                    "get_shared_connected", False)),
                "currentUser": _text(_get_member(
                    online_device, "current_logged_on_username",
                    "get_current_logged_on_username", "")),
            }
        except Exception as exc:
            report["deviceBinding"] = {"error": _text(exc)}
    return report


def online_operation_unavailable(req, operation):
    """Expose online contracts without pretending a PLC connection exists."""
    req = req or {}
    target = req.get("target") or req.get("connection") or req.get("url")
    return_data = {
        "operation": operation,
        "target": target,
        "connected": False,
        "mutatedTarget": False,
        "onlineActionAttempted": False,
        "requires": [
            "exact Inovance CPU/runtime and firmware",
            "verified communication route",
            "explicit target safety policy",
        ],
        "next": "provide a real disposable/test PLC target before probing online bindings",
    }
    raise OperationError(
        operation + " is exposed but no real PLC target is connected; no online action was attempted",
        "online_target_unavailable", return_data)


def _project_object_target_forms(target):
    """Return path spellings accepted by the project-object resolver.

    Some InoProShop device descriptions contain a *literal* ``\\uXXXX``
    sequence in their display name (the profile XML was escaped twice).  A
    blanket backslash-to-slash replacement turns that name into a different
    path and makes the object impossible to address.  Keep the conventional
    Windows-normalized spelling for ordinary callers, and add a second
    spelling that preserves literal Unicode escape sequences.  Both forms are
    read-only normalization; the resolver still returns the canonical live
    object path.
    """
    raw = _text(target).strip()
    if not raw:
        return []
    forms = []
    standard = raw.replace("\\", "/").strip("/")
    if standard:
        forms.append(standard)
    # Preserve a backslash only when it starts a four-digit Unicode escape.
    # The standard form above remains available for a real path separator
    # followed by a directory named ``u1234``.
    escaped = re.sub(r"\\(?!u[0-9a-fA-F]{4})", "/", raw).strip("/")
    if escaped and escaped not in forms:
        forms.append(escaped)
    # The opposite transport boundary is also common: JSON has already
    # decoded the profile's literal sequence once, while the native object
    # name is a real Unicode string.  Add that spelling without interpreting
    # arbitrary backslash escapes in the rest of the target.
    def _unicode_escape(match):
        codepoint = int(match.group(1), 16)
        try:
            return unichr(codepoint)
        except NameError:
            return chr(codepoint)
    decoded = re.sub(r"\\u([0-9a-fA-F]{4})", _unicode_escape, raw)
    decoded = decoded.replace("\\", "/").strip("/")
    if decoded and decoded not in forms:
        forms.append(decoded)
    return forms


def find_project_object(target):
    _require_project()
    raw_target = _text(target).strip()
    target_forms = _project_object_target_forms(raw_target)
    if not target_forms:
        raise OperationError("object target is required", "invalid_argument",
                             {"path": "target"})
    flat = []
    _walk_objects(project, [], 1, 64, flat)
    path_matches = []
    for path, obj in flat:
        if any(_text(path).lower() == _text(form).lower()
               for form in target_forms):
            path_matches.append((path, obj))
    if len(path_matches) == 1:
        return path_matches[0][1], path_matches[0][0]
    if len(path_matches) > 1:
        raise OperationError(
            "ambiguous project object path: " + raw_target,
            "ambiguous_object_target",
            {"target": raw_target, "candidates": [item[0] for item in path_matches]},
        )
    name_matches = []
    for path, obj in flat:
        if any(_text(_object_name(obj)) == _text(form)
               for form in target_forms):
            name_matches.append((path, obj))
    if len(name_matches) == 1:
        return name_matches[0][1], name_matches[0][0]
    if len(name_matches) > 1:
        raise OperationError(
            "ambiguous object name '%s'; pass one exact path" % raw_target,
            "ambiguous_object_target",
            {"target": raw_target, "candidates": [item[0] for item in name_matches]},
        )
    # Partial paths ("Application/Alarm Configuration") resolve by suffix so
    # callers don't need the full "Device/Plc Logic/..." prefix.
    suffix_matches = []
    for path, obj in flat:
        if any(_text(path).lower().endswith("/" + _text(form).lower())
               for form in target_forms):
            suffix_matches.append((path, obj))
    if len(suffix_matches) == 1:
        return suffix_matches[0][1], suffix_matches[0][0]
    if len(suffix_matches) > 1:
        raise OperationError(
            "ambiguous project object path suffix: " + raw_target,
            "ambiguous_object_target",
            {"target": raw_target, "candidates": [item[0] for item in suffix_matches]},
        )
    # Keep a small bounded hint for profile-generated names that are hard to
    # spell (notably literal ``\\uXXXX`` device labels).  This is diagnostic
    # only; it never broadens target matching or performs a write.
    observed_hint = [path for path, _obj in flat
                     if "GL20" in _text(path).upper()][:20]
    target_debug = [{"value": _text(form), "length": len(_text(form)),
                     "codepoints": [ord(ch) for ch in _text(form)[:128]]}
                    for form in target_forms]
    observed_debug = [{"value": _text(path), "length": len(_text(path)),
                      "codepoints": [ord(ch) for ch in _text(path)[:128]]}
                     for path in observed_hint]
    raise OperationError(
        "project object not found: " + raw_target,
        "object_not_found",
        {"target": raw_target, "targetForms": target_forms,
         "targetDebug": target_debug,
         "observedCandidatePaths": observed_hint,
         "observedCandidateDebug": observed_debug,
         "next": {
             "tool": "codesys_project_tree",
             "then": "read the tree and pass an exact path (the tree prints the "
                     "device-qualified form, e.g. PLCWinNT/Plc Logic/Application/"
                     "PRG_X); observedCandidatePaths lists what this project "
                     "actually contains",
         }},
    )


def vendor_pou_create(req):
    """Create a PROGRAM POU through the vendor channel the wizard itself uses.

    ScriptEngine-created objects never register in the vendor structured view
    that backs the visible project tree (proven 2026-08-22: TEST_UI_POU is
    absent from the tree in the live creation session).  The wizard creates
    its objects via APEnvironment.CreatePOUObject + vendor ObjectMgr.AddObject
    and those are visible.  This tool replicates that exact recipe, attaching
    the vendor ST implementation object before AddObject, and keeps the
    ScriptEngine only for the text writes that follow.
    """
    _require_project()
    name = _text(req.get("name")).strip()
    declaration = req.get("declaration")
    implementation = req.get("implementation")
    language = _text(req.get("language") or "st").strip().lower()
    if language in ("lad", "ladder", "ld"):
        language = "ld"
    else:
        language = "st"
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
        raise OperationError("vendor.pou.create requires name", "invalid_argument",
                             {"path": "name", "expected": "IEC identifier",
                              "actual": name})
    if declaration is None or (implementation is None and language != "ld"):
        raise OperationError(
            "vendor.pou.create requires declaration and implementation",
            "invalid_argument",
            {"path": "declaration/implementation"})
    declared_kind = _vendor_st_declaration_kind(name, declaration)
    requested_kind = _text(req.get("kind") or declared_kind).strip().lower()
    if requested_kind != declared_kind:
        raise OperationError(
            "POU kind does not match its ST declaration header",
            "pou_kind_declaration_mismatch",
            {"path": "kind", "expected": declared_kind,
             "actual": requested_kind,
             "correctFormat": _vendor_st_header_example(name, requested_kind)},
        )
    import System
    flags_static = (System.Reflection.BindingFlags.Static |
                    System.Reflection.BindingFlags.Public |
                    System.Reflection.BindingFlags.NonPublic)
    trace = []

    # 1. The Application GUID is the AddObject parent, exactly like the wizard.
    app = getattr(project, "active_application", None)
    if app is None:
        raise OperationError("no active application", "no_active_application")
    app_guid = _text(_get_member(app, "guid", "get_guid"))
    if not app_guid:
        raise OperationError("application guid is unavailable", "binding_failed")
    trace.append({"step": "application", "guid": app_guid})

    # 2. Vendor POU object from the wizard's own factory.
    # Resolve APEnvironment from the loaded wizard assembly.  The physical
    # plugin is named InoProjectWizards.plugin.dll, but its CLR assembly name
    # is profile-dependent; a Type.GetType lookup using the file name is not
    # reliable even though the wizard itself is already bound.
    wizard, wizard_binding = _reflection_generic_create(
        INOVANCE_WIZARD_INTERFACE, INOVANCE_WIZARD_TYPE_GUID
    )
    if wizard is None:
        raise OperationError("vendor project wizard is unavailable",
                             "vendor_wizard_binding_failed",
                             {"binding": wizard_binding})
    ap_type = wizard.GetType().Assembly.GetType(
        "Inovance.InoPro.InoProjectWizards.APEnvironment", False
    )
    if ap_type is None:
        raise OperationError("vendor APEnvironment type is unavailable",
                             "vendor_wizard_binding_failed",
                             {"wizardRuntimeType": _text(wizard.GetType().FullName),
                              "wizardAssembly": _text(wizard.GetType().Assembly.FullName)})
    create_pou_method = ap_type.GetMethod("CreatePOUObject", flags_static)
    if create_pou_method is None:
        raise OperationError("CreatePOUObject binding is unavailable",
                             "vendor_wizard_binding_failed")
    pou = create_pou_method.Invoke(None, System.Array[System.Object]([]))
    trace.append({"step": "CreatePOUObject",
                  "runtimeType": _text(pou.GetType().FullName)})

    # 3. Attach the vendor ST implementation object before AddObject.
    implementation_guid = (
        INOVANCE_LD_IMPLEMENTATION_FACTORY_GUID
        if language == "ld" else INOVANCE_ST_IMPLEMENTATION_FACTORY_GUID
    )
    st_factory, st_binding = _reflection_generic_create(
        INOVANCE_IMPLEMENTATION_FACTORY_INTERFACE,
        implementation_guid,
    )
    if st_factory is None:
        raise OperationError("vendor ST implementation factory is unavailable",
                             "implementation_factory_unavailable", st_binding)
    impl = st_factory.Create()
    impl_prop = pou.GetType().GetProperty("Implementation")
    if impl_prop is None:
        raise OperationError("POU Implementation property is unavailable",
                             "vendor_pou_binding_failed")
    impl_prop.SetValue(pou, impl, System.Array[System.Object]([]))
    trace.append({"step": "Implementation",
                  "runtimeType": _text(impl.GetType().FullName)})

    # 4. Vendor ObjectMgr.AddObject(handle, appGuid, newGuid, obj, name, -1).
    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("SystemInstances type is unavailable",
                             "system_instances_unavailable")
    object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            handle = None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable",
                             "project_handle_unavailable")
    add_method = None
    for method in object_mgr.GetType().GetMethods():
        if method.Name != "AddObject":
            continue
        parameters = method.GetParameters()
        if len(parameters) != 6:
            continue
        add_method = method
        break
    if add_method is None:
        raise OperationError("vendor AddObject binding is unavailable",
                             "vendor_addobject_unavailable")
    new_guid = System.Guid.NewGuid()
    args = System.Array[System.Object]([
        int(handle), System.Guid(app_guid), new_guid, pou, name, -1,
    ])
    added = add_method.Invoke(object_mgr, args)
    trace.append({"step": "AddObject", "requestedGuid": _text(new_guid),
                  "returnedGuid": _text(added)})

    # 5. Text writes stay on the proven ScriptEngine path.
    pou_cache.clear()
    script_pou = find_textual_object(name)
    if script_pou is None:
        raise OperationError(
            "vendor-created POU not found in the object model after AddObject",
            "vendor_pou_not_found", {"trace": trace})
    try:
        text_result = {
            "declaration": _write_document(
                _get_member(script_pou, "textual_declaration", "get_textual_declaration"),
                declaration, "declaration"),
        }
        if language != "ld":
            text_result["implementation"] = _write_document(
                _get_member(script_pou, "textual_implementation", "get_textual_implementation"),
                implementation, "implementation")
    except Exception as exc:
        # AddObject has already registered the POU.  A text write failure is
        # therefore a recoverable partial operation, not permission to create
        # the same name again and leave duplicate objects behind.
        raise OperationError(
            "vendor POU was created but source text did not complete",
            "vendor_pou_create_partial_write",
            {"name": name, "createdGuid": _text(added), "trace": trace,
             "cause": repr(exc),
             "recovery": ["pou.get", "project.tree", "screenshot",
                          "pou.set_text with createIfMissing=false"]},
        )
    created_path = None
    try:
        _created_obj, created_path = find_project_object(name)
    except Exception:
        pass
    return {
        "name": name,
        "kind": declared_kind,
        "language": language,
        "createdGuid": _text(added),
        "parent": "Application",
        "treePath": created_path,
        "creationRoute": "vendor_object_mgr_add_object",
        "trace": trace,
        "text": text_result,
        "readback": read_st(script_pou),
        "object": _object_summary(script_pou),
        "uiVisibilityGate": "required: screenshot the tree in this session",
        "graphicalImplementationFactory": implementation_guid,
    }


def _open_project_object_editor(obj, object_path, factory_guid=None,
                                include_detail=False):
    """Open one generic project object view when an exact factory is supplied.

    InoProShop's ``OpenEditorView`` needs a *factory* GUID in addition to the
    project-object GUID.  Device-editor factories are not valid for POUs, and
    no generic POU factory is hard-coded.  This helper therefore asks the
    official ``ViewFactoryManager.GetDefaultEditorViewFactory`` for the
    object's actual type when no caller-supplied factory is given; a supplied
    factory is invoked through the same native ObjectMgr/Engine route.
    """
    result = {
        "requested": bool(factory_guid),
        "editorOpened": False,
        "status": "default_factory_lookup" if not factory_guid else "not_attempted",
        "objectPath": object_path,
    }
    import System
    factory = None
    if factory_guid:
        try:
            factory = System.Guid(_text(factory_guid))
        except Exception as exc:
            result.update({"status": "invalid_factory_guid", "error": repr(exc)})
            return result
    object_guid = _object_guid(obj)
    if not object_guid:
        result.update({"status": "object_guid_unavailable"})
        return result
    native_project = native_core_project or _native_primary_project_for_current_path()
    handle = None
    if native_project is not None:
        try:
            handle = int(native_project.Handle)
        except Exception:
            handle = None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        result.update({"status": "project_handle_unavailable"})
        return result
    object_mgr, object_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        result.update({"status": "object_manager_unavailable", "probe": object_probe})
        return result
    try:
        stub = object_mgr.GetMetaObjectStub(int(handle), System.Guid(object_guid))
        if stub is None:
            result.update({"status": "meta_object_stub_unavailable"})
            return result
        engine, engine_probe = _system_instances_property("Engine")
        root_frame = _get_member(engine, "Frame", "get_Frame") if engine is not None else None
        if root_frame is None:
            result.update({"status": "frame_unavailable", "probe": engine_probe})
            return result
        if factory is None:
            # This is the official route used by the vendor NWL diagnostics
            # and navigator code: ask ViewFactoryManager for the default
            # editor for the object's actual type and embedded types.  It is
            # not a hard-coded device/editor GUID guess.
            object_type = _get_member(stub, "ObjectType", "get_ObjectType")
            embedded = _get_member(stub, "EmbeddedObjectTypes", "get_EmbeddedObjectTypes")
            manager = _get_member(root_frame, "ViewFactoryManager", "get_ViewFactoryManager")
            if manager is None or object_type is None:
                result.update({"status": "default_editor_factory_unavailable"})
                return result
            attempts = []
            for args in ((object_type, embedded), (object_type, None), (object_type,)):
                try:
                    factory = manager.GetDefaultEditorViewFactory(*args)
                    if factory is not None:
                        break
                except Exception as exc:
                    attempts.append(repr(exc))
            if factory is None:
                result.update({"status": "default_editor_factory_unavailable",
                               "factoryLookupAttempts": attempts})
                return result
            result["factoryResolution"] = "ViewFactoryManager.GetDefaultEditorViewFactory"
            result["factoryGuid"] = _text(factory)
        view = root_frame.OpenEditorView(stub, factory, None)
        if view is None:
            result.update({"status": "editor_view_unavailable"})
            return result
        result.update({
            "editorOpened": True,
            "status": "editor_opened",
            # The default response is intentionally compact.  Full CLR
            # reflection is expensive and can make a one-object write look
            # like a hung tool; callers can opt into it for diagnostics.
            "view": (_native_editor_frame_snapshot(view, object_path)
                     if include_detail else {
                         "target": object_path,
                         "runtimeType": _text(view.GetType().FullName),
                         "editor": {
                             "runtimeType": _text(_get_member(
                                 view, "Editor", "get_Editor").GetType().FullName)
                             if _get_member(view, "Editor", "get_Editor") is not None else None,
                         },
                     }),
        })
        return result
    except Exception as exc:
        result.update({"status": "editor_open_failed", "error": repr(exc),
                       "factoryGuid": _text(factory_guid)})
        return result


def _existing_editor_for_object(obj, object_path, include_detail=False):
    """Detect an already-open view for a POU without opening a new view."""
    object_guid = _object_guid(obj).lower()
    result = {"editorOpened": False, "status": "not_open"}
    if not object_guid:
        result["status"] = "object_guid_unavailable"
        return result
    try:
        engine, _probe = _system_instances_property("Engine")
        root_frame = _get_member(engine, "Frame", "get_Frame") if engine is not None else None
        views = list(root_frame.GetViews()) if root_frame is not None else []
        for view in views:
            editor_obj = _get_member(view, "Editor", "get_Editor")
            view_guid = _get_member(editor_obj, "ObjectGuid", "get_ObjectGuid") if editor_obj is not None else None
            if _text(view_guid).lower() == object_guid:
                detail = (_native_editor_frame_snapshot(view, object_path)
                          if include_detail else {
                              "target": object_path,
                              "runtimeType": _text(view.GetType().FullName),
                              "editor": {"objectGuid": _text(view_guid)},
                          })
                return {"editorOpened": True, "status": "already_open",
                        "view": detail}
    except Exception as exc:
        result.update({"status": "editor_probe_failed", "error": repr(exc)})
    return result


def lad_create_atomic(req):
    """Create one LAD root POU and complete the cheap, deterministic gates.

    The operation intentionally does not synthesize graphical XML.  It creates
    the POU through the existing ScriptEngine route, verifies that the object
    is present in the live tree, optionally opens a caller-supplied editor
    factory, and saves once.  Every gate is returned independently so a
    caller can distinguish creation from UI/editor success.
    """
    _require_project()
    name = _text(req.get("name") or "").strip()
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
        raise OperationError("lad.create requires an IEC identifier name",
                             "invalid_argument", {"path": "name", "actual": name})
    kind = _text(req.get("kind") or "program").strip().lower()
    if kind not in ("program", "function_block", "function"):
        raise OperationError("lad.create supports program, function_block or function",
                             "invalid_argument", {"path": "kind", "actual": kind})
    language = _text(req.get("language") or "ld").strip().lower()
    if language not in ("ld", "ladder"):
        raise OperationError("lad.create language must be ld/ladder", "invalid_argument",
                             {"path": "language", "actual": language})
    if req.get("declaration") is not None or req.get("implementation") is not None:
        raise OperationError(
            "LD graphical body cannot be supplied as textual declaration/implementation",
            "lad_graphical_source_required",
            {"path": "declaration" if req.get("declaration") is not None else "implementation",
             "expected": "PLCopen XML via lad.generate_add or native graphical network/XML",
             "mutatedProject": False},
        )
    if req.get("parent") not in (None, "", "Application"):
        raise OperationError("vendor LD creation is verified only under Application",
                             "ui_visible_pou_parent_unverified",
                             {"path": "parent", "actual": req.get("parent"),
                              "expected": "Application"})
    existing = find_textual_object(name)
    created = False
    creation_route = "existing_object"
    if existing is None:
        # The vendor wizard does not use ScriptEngine.create_pou for a
        # graphical POU.  It creates the POU shell, attaches the real LD
        # implementation object, and registers both through ObjectMgr.AddObject.
        # Reproduce that route so the body is an actual NWL network rather than
        # a textual object with an empty implementation pane.
        import System
        app = getattr(project, "active_application", None)
        if app is None:
            raise OperationError("no active application", "no_active_application")
        app_guid = _text(_get_member(app, "guid", "get_guid"))
        wizard, wizard_binding = _reflection_generic_create(
            INOVANCE_WIZARD_INTERFACE, INOVANCE_WIZARD_TYPE_GUID
        )
        if wizard is None:
            raise OperationError("vendor project wizard is unavailable",
                                 "vendor_wizard_binding_failed",
                                 {"binding": wizard_binding})
        ap_type = wizard.GetType().Assembly.GetType(
            "Inovance.InoPro.InoProjectWizards.APEnvironment", False
        )
        create_pou_method = (ap_type.GetMethod(
            "CreatePOUObject",
            System.Reflection.BindingFlags.Static |
            System.Reflection.BindingFlags.Public |
            System.Reflection.BindingFlags.NonPublic,
        ) if ap_type is not None else None)
        if create_pou_method is None:
            raise OperationError("CreatePOUObject binding is unavailable",
                                 "vendor_wizard_binding_failed")
        vendor_pou = create_pou_method.Invoke(None, System.Array[System.Object]([]))
        ld_factory, ld_binding = _reflection_generic_create(
            INOVANCE_IMPLEMENTATION_FACTORY_INTERFACE,
            INOVANCE_LD_IMPLEMENTATION_FACTORY_GUID,
        )
        if ld_factory is None:
            raise OperationError("LD implementation factory is unavailable",
                                 "ld_implementation_factory_unavailable",
                                 {"binding": ld_binding,
                                  "factoryGuid": INOVANCE_LD_IMPLEMENTATION_FACTORY_GUID})
        implementation = ld_factory.Create()
        _NWL_IMPLEMENTATION_CACHE[name] = implementation
        impl_prop = vendor_pou.GetType().GetProperty("Implementation")
        if impl_prop is None:
            raise OperationError("POU Implementation property is unavailable",
                                 "vendor_pou_binding_failed")
        impl_prop.SetValue(vendor_pou, implementation,
                           System.Array[System.Object]([]))
        object_mgr, object_probe = _system_instances_property("ObjectMgr")
        if object_mgr is None:
            raise OperationError("SystemInstances.ObjectMgr is unavailable",
                                 "object_manager_unavailable", {"probe": object_probe})
        native_project = native_core_project or _native_primary_project_for_current_path()
        handle = None
        if native_project is not None:
            try:
                handle = int(native_project.Handle)
            except Exception:
                handle = None
        if handle is None:
            handle = _get_member(project, "handle", "get_handle")
        if handle is None:
            raise OperationError("project handle is unavailable",
                                 "project_handle_unavailable")
        add_method = None
        for method in object_mgr.GetType().GetMethods():
            if method.Name == "AddObject" and len(method.GetParameters()) == 6:
                add_method = method
                break
        if add_method is None:
            raise OperationError("vendor AddObject binding is unavailable",
                                 "vendor_addobject_unavailable")
        requested_guid = System.Guid.NewGuid()
        added_guid = add_method.Invoke(object_mgr, System.Array[System.Object]([
            int(handle), System.Guid(app_guid), requested_guid, vendor_pou, name, -1,
        ]))
        pou_cache.clear()
        existing = find_textual_object(name)
        if existing is None:
            # Graphical POUs may not expose textual panes.  Resolve the object
            # from the live tree instead of treating that as a creation failure.
            try:
                existing, _unused_path = find_project_object(name)
            except Exception:
                existing = vendor_pou
        created = True
        creation_route = "vendor_object_mgr_add_object_ld_factory"
    pou = existing
    pou_cache[name] = pou
    created_path = None
    try:
        _found, created_path = find_project_object(name)
    except Exception:
        pass
    tree_visible = bool(created_path)
    source = read_st(pou)
    text_writes = {}
    if req.get("declaration") is not None:
        if _get_member(pou, "textual_declaration", "get_textual_declaration") is None:
            raise OperationError(
                "graphical LD POU has no textual declaration pane; provide graphical XML/network data",
                "lad_graphical_source_required",
                {"path": "declaration", "creationRoute": creation_route,
                 "mutatedProject": created, "correctFormat": "omit declaration/implementation for empty LD shell"},
            )
        text_writes["declaration"] = _write_document(
            _get_member(pou, "textual_declaration", "get_textual_declaration"),
            req.get("declaration"), "declaration")
    if req.get("implementation") is not None:
        if _get_member(pou, "textual_implementation", "get_textual_implementation") is None:
            raise OperationError(
                "graphical LD POU has no textual implementation pane; provide graphical XML/network data",
                "lad_graphical_source_required",
                {"path": "implementation", "creationRoute": creation_route,
                 "mutatedProject": created, "correctFormat": "omit declaration/implementation for empty LD shell"},
            )
        text_writes["implementation"] = _write_document(
            _get_member(pou, "textual_implementation", "get_textual_implementation"),
            req.get("implementation"), "implementation")
    if text_writes:
        source = read_st(pou)
    editor_detail = bool(req.get("editorDetail", False))
    open_editor = bool(req.get("openEditor", False))
    editor = {"editorOpened": False, "status": "not_requested",
              "objectPath": created_path or name}
    if open_editor:
        editor = _existing_editor_for_object(pou, created_path or name, editor_detail)
        if not editor.get("editorOpened"):
            editor = _open_project_object_editor(
                pou, created_path or name, req.get("editorFactoryGuid"),
                editor_detail)
    defer_save = bool(req.get("deferSave"))
    saved = False
    save_error = None
    if not defer_save:
        try:
            project.save()
            saved = True
        except Exception as exc:
            save_error = repr(exc)
    return {
        "name": name,
        "kind": kind,
        "language": "ld",
        "created": created,
        "reused": not created,
        "creationRoute": creation_route,
        "pou": _object_summary(pou, created_path),
        "treePath": created_path,
        "treeVisible": tree_visible,
        "editorOpened": bool(editor.get("editorOpened")),
        "editor": editor,
        "saved": saved,
        "saveError": save_error,
        "text": text_writes,
        "readback": source,
        "status": ("ready" if tree_visible and (saved or defer_save) and
                   (not open_editor or editor.get("editorOpened"))
                   else ("saved_editor_not_open" if tree_visible and saved else "partial")),
        "claims": {
            "objectCreatedOrReused": True,
            "treeReadback": tree_visible,
            "editorOpenAttempted": open_editor,
            "saved": saved,
            "saveDeferred": defer_save,
            "graphicalBodyWritten": False,
            "compilePerformed": False,
        },
    }


def _vendor_st_header_example(name, kind):
    kind = _text(kind).strip().lower()
    if kind == "function_block":
        return "FUNCTION_BLOCK %s\nVAR\nEND_VAR" % name
    if kind == "function":
        return "FUNCTION %s : DINT\nVAR_INPUT\nEND_VAR" % name
    return "PROGRAM %s\nVAR\nEND_VAR" % name


def _vendor_st_declaration_kind(name, declaration):
    """Validate a new vendor-visible POU before ObjectMgr creates it."""
    source = _validate_source_text(declaration, "declaration")
    pattern = (r"^\s*(PROGRAM|FUNCTION_BLOCK|FUNCTION)\s+" +
               re.escape(name) + r"\b")
    match = re.match(pattern, source, re.IGNORECASE)
    if match is None:
        raise OperationError(
            "ST declaration must start with the exact POU kind and requested name",
            "invalid_pou_declaration_header",
            {"path": "declaration", "expected": [
                 _vendor_st_header_example(name, "program"),
                 _vendor_st_header_example(name, "function_block"),
                 _vendor_st_header_example(name, "function"),
             ], "actual": source.split("\n", 1)[0] if source else ""},
        )
    token = match.group(1).upper()
    return {"PROGRAM": "program", "FUNCTION_BLOCK": "function_block",
            "FUNCTION": "function"}[token]


def _vendor_st_create_if_needed(req):
    """Use the proven ObjectMgr route for a new root ST POU only."""
    language = _text(req.get("language") or "st").strip().lower()
    if language not in ("st", "structured_text"):
        return None
    name = _text(req.get("name") or req.get("pou")).strip()
    if not name or find_textual_object(name) is not None:
        return None
    if req.get("parent"):
        raise OperationError(
            "vendor-visible ST POU creation is verified only directly under Application",
            "ui_visible_pou_parent_unverified",
            {"path": "parent", "actual": req.get("parent"),
             "expected": "omit parent for Application root",
             "next": "verify vendor ObjectMgr insertion for this exact parent"},
        )
    if req.get("declaration") is None or req.get("implementation") is None:
        raise OperationError(
            "new vendor-visible ST POU requires complete declaration and implementation",
            "vendor_pou_create_requires_full_source",
            {"required": ["name", "declaration", "implementation"],
             "correctFormat": {
                 "name": "PumpControl", "kind": "function_block",
                 "language": "st",
                 "declaration": "FUNCTION_BLOCK PumpControl\nVAR\nEND_VAR",
                 "implementation": ""
             }},
        )
    try:
        result = vendor_pou_create(req)
    except (OperationError, RuntimeError) as exc:
        # Plain CODESYS has no Inovance project wizard / ST implementation
        # factory. Degrade to the generic ScriptEngine creation path
        # (get_or_create_pou) instead of failing the write — the vendor
        # route stays primary on InoProShop where its bindings exist
        # (2026-09-08 vanilla-CODESYS probe).
        message = repr(exc)
        if ("interface type is unavailable" in message
                or "vendor project wizard is unavailable" in message
                or "vendor ST implementation factory is unavailable" in message
                or "implementation factory" in message.lower()
                or "wizard" in message.lower()):
            return None
        raise
    result["created"] = True
    return result


def project_parent_map(req):
    """Read-only parent-reference map of every object in the open project.

    Enumerates all object GUIDs through SystemInstances.ObjectMgr and reports
    each object's name, type, parent GUID, and any parent reference that does
    not resolve to an existing object.  This locates dangling-parent defects
    (e.g. the recurring 6dd19da5 InvalidObjectGuidException at reload) without
    touching the project.
    """
    _require_project()
    import System
    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("SystemInstances type is unavailable",
                             "system_instances_unavailable")
    object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is null",
                             "system_instances_unavailable")
    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            handle = None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable",
                             "project_handle_unavailable")
    all_guids = list(object_mgr.GetAllObjects(int(handle)))
    existing = set()
    for guid in all_guids:
        existing.add(_text(guid).lower())
    entries = []
    for guid in all_guids:
        stub = object_mgr.GetMetaObjectStub(int(handle), guid)
        if stub is None:
            continue
        parent = stub.ParentObjectGuid
        entry = {
            "objectGuid": _text(guid),
            "name": _text(stub.Name),
            "parentObjectGuid": _text(parent),
        }
        try:
            entry["objectType"] = _text(stub.ObjectType.FullName)
        except Exception:
            entry["objectType"] = None
        entries.append(entry)
    empty_guid = "00000000-0000-0000-0000-000000000000"
    dangling = []
    for entry in entries:
        parent = entry.get("parentObjectGuid") or ""
        if parent and parent != empty_guid and parent.lower() not in existing:
            dangling.append(entry)
    # The structured view builds the visible tree from SVFoldersProperty
    # references, not only from ParentObjectGuid.  Vendor assemblies are
    # obfuscated, so the property type is matched by runtime type name on
    # each stub's Properties collection instead of by a fixed type handle.
    svfolders_refs = []
    svf_diag = []
    try:
        import System
        flags_inst = (System.Reflection.BindingFlags.Instance |
                      System.Reflection.BindingFlags.Public |
                      System.Reflection.BindingFlags.NonPublic)
        stub_type = None
        for guid in all_guids[:1]:
            stub = object_mgr.GetMetaObjectStub(int(handle), guid)
            if stub is not None:
                stub_type = stub.GetType()
                break
        if stub_type is not None:
            for member in list(stub_type.GetProperties(flags_inst)) + list(stub_type.GetFields(flags_inst)):
                svf_diag.append({"stubMember": member.Name})
        for guid in all_guids:
            stub = object_mgr.GetMetaObjectStub(int(handle), guid)
            if stub is None:
                continue
            props = None
            for name in ("Properties", "properties", "get_Properties"):
                try:
                    props = getattr(stub, name)
                    if _is_callable(props) and name.startswith("get_"):
                        props = props()
                    break
                except Exception:
                    props = None
            if props is None:
                continue
            try:
                props = list(props)
            except Exception:
                continue
            for prop in props:
                prop_type_name = _text(prop.GetType().Name)
                if "svfolders" not in prop_type_name.lower():
                    continue
                # Dump members of the first match, then bind the dictionary.
                if not svfolders_refs:
                    dump = []
                    for field in prop.GetType().GetFields(flags_inst):
                        try:
                            value = field.GetValue(prop)
                            dump.append({"field": field.Name, "value": _text(value)[:300]})
                        except Exception as exc:
                            dump.append({"field": field.Name, "error": repr(exc)})
                    for p in prop.GetType().GetProperties(flags_inst):
                        try:
                            value = p.GetValue(prop, None)
                            dump.append({"property": p.Name, "value": _text(value)[:300]})
                        except Exception as exc:
                            dump.append({"property": p.Name, "error": repr(exc)})
                    svfolders_refs.append({
                        "objectName": _text(stub.Name), "objectGuid": _text(guid),
                        "propertyRuntimeType": prop_type_name, "memberDump": dump,
                    })
                    continue
                # Read the internal view->parent dictionary directly.
                parents = {}
                try:
                    raw_dict = None
                    for field in prop.GetType().GetFields(flags_inst):
                        if field.Name == "_parentObjects":
                            raw_dict = field.GetValue(prop)
                            break
                    if raw_dict is None:
                        for p in prop.GetType().GetProperties(flags_inst):
                            if p.Name == "ParentObjects":
                                raw_dict = p.GetValue(prop, None)
                                break
                    if raw_dict is not None:
                        for key in list(getattr(raw_dict, "Keys", []) or []):
                            value = raw_dict[key]
                            parents[_text(key)] = {
                                "parent": _text(value),
                                "parentExists": _text(value).lower() in existing,
                            }
                except Exception as exc:
                    parents = {"error": repr(exc)}
                views = []
                try:
                    raw_views = getattr(prop, "StructuredViews", None)
                    if raw_views is not None:
                        views = [_text(item) for item in list(raw_views)]
                except Exception:
                    views = []
                svfolders_refs.append({
                    "objectName": _text(stub.Name), "objectGuid": _text(guid),
                    "propertyRuntimeType": prop_type_name,
                    "views": views, "parents": parents,
                })
                if len(svfolders_refs) > 400:
                    break
    except Exception as exc:
        svf_diag.append({"error": repr(exc)})
    dangling_parents_from_folders = [
        item for item in svfolders_refs if not item.get("parentExists")
    ]
    known = _text(req.get("guid") or req.get("target") or "").strip().lower()
    requested_entry = None
    if known:
        for entry in entries:
            if entry.get("objectGuid", "").lower() == known:
                requested_entry = entry
                break
    referenced_missing = {}
    if known:
        for entry in entries:
            if entry.get("parentObjectGuid", "").lower() == known:
                referenced_missing.setdefault(known, []).append(
                    {"name": entry.get("name"), "objectGuid": entry.get("objectGuid"),
                     "objectType": entry.get("objectType")})
    return {
        "projectPath": _project_path(),
        "handle": int(handle),
        "objectCount": len(entries),
        "danglingParentCount": len(dangling),
        "danglingParents": dangling[:200],
        "svFoldersReferences": svfolders_refs[:400],
        "svFoldersTypeDiagnostics": svf_diag if 'svf_diag' in dir() else [],
        "svFoldersDangling": dangling_parents_from_folders[:200],
        "referencesToRequestedGuid": referenced_missing.get(known, []) if known else None,
        "requestedGuid": known or None,
        "requestedGuidExists": bool(requested_entry) if known else None,
        "requestedGuidEntry": requested_entry,
        "mutated": False,
    }


def _creation_parent(req):
    parent_target = req.get("parent")
    if parent_target:
        return find_project_object(parent_target)[0]
    app = getattr(project, "active_application", None)
    if app is not None:
        return app
    return project


def _find_created_child(parent, name):
    for child in _children(parent):
        if _object_name(child) == name:
            return child
    return None


def _require_child_destination_absent(parent, parent_path, name, operation):
    """Reject duplicate child creation before invoking a native factory."""
    matches = [child for child in _children(parent)
               if _object_name(child).lower() == name.lower()]
    if matches:
        raise OperationError(
            "child destination already exists: " + parent_path + "/" + name,
            "child_destination_exists",
            {
                "operation": operation,
                "parent": parent_path,
                "name": name,
                "matches": [_object_summary(item) for item in matches],
                "mutatedProject": False,
            },
        )


def _created_child_model_readback(parent, parent_path, name, created,
                                  operation):
    """Re-resolve a newly created child and prove its exact native identity."""
    expected_path = parent_path.rstrip("/") + "/" + name
    matches = [child for child in _children(parent)
               if _object_name(child).lower() == name.lower()]
    if len(matches) != 1:
        raise OperationError(
            "native child readback did not contain exactly one requested object",
            "child_creation_readback_mismatch",
            {
                "operation": operation,
                "parent": parent_path,
                "name": name,
                "expectedPath": expected_path,
                "matchCount": len(matches),
                "matches": [_object_summary(item) for item in matches],
                "mutatedProject": True,
            },
        )
    rebound, actual_path = find_project_object(expected_path)
    created_guid = _object_guid(created)
    rebound_guid = _object_guid(rebound)
    exact_name = _object_name(rebound) == name
    exact_path = actual_path.lower() == expected_path.lower()
    guid_readback = bool(
        created_guid and rebound_guid and
        created_guid.lower() == rebound_guid.lower()
    )
    if not exact_name or not exact_path or not guid_readback:
        raise OperationError(
            "native child identity did not match the created object",
            "child_creation_readback_mismatch",
            {
                "operation": operation,
                "parent": parent_path,
                "name": name,
                "expectedPath": expected_path,
                "actualPath": actual_path,
                "createdGuid": created_guid,
                "readbackGuid": rebound_guid,
                "actualName": _object_name(rebound),
                "mutatedProject": True,
            },
        )
    result = _object_summary(rebound, actual_path)
    result.update({
        "created": True,
        "createdGuid": created_guid,
        "modelReadback": True,
        "exactNameReadback": True,
        "exactPathReadback": True,
        "guidReadback": True,
    })
    return rebound, result


def _device_repository():
    """Return the ScriptEngine device repository injected by InoProShop."""
    repository = globals().get("device_repository")
    if repository is None:
        repository = _get_member(
            system, "device_repository", "get_device_repository"
        )
    if repository is None:
        raise OperationError(
            "InoProShop did not expose the ScriptEngine device repository in "
            "this session. Reconnect through the InoProShop V1.10 bridge.",
            "device_repository_unavailable",
        )
    return repository


def _device_identity(value):
    """Serialize a ScriptEngine IDeviceId without leaking CLR objects."""
    if value is None:
        return None
    raw_type = _get_member(value, "type", "get_type")
    if raw_type is None:
        raw_type = _get_member(value, "Type", "get_Type")
    try:
        device_type = int(raw_type)
    except Exception:
        device_type = _text(raw_type)
    return {
        "type": device_type,
        "id": _text(_get_member(value, "id", "get_id") or
                    _get_member(value, "Id", "get_Id")),
        "version": _text(_get_member(value, "version", "get_version") or
                          _get_member(value, "Version", "get_Version")),
    }


def _normalize_device_id(value):
    """Compare repository IDs independent of display casing/whitespace.

    InoProShop returns hexadecimal device IDs with inconsistent casing across
    repository enumeration and the wizard/API surface (for example
    ``10f4 0819`` versus ``10F4 0819``).  The ID remains verbatim in receipts;
    this seam is only for selector matching and ambiguity grouping.
    """
    return " ".join(_text(value).strip().split()).lower()


def _device_info_value(info, name):
    return _text(_get_member(info, name, "get_" + name, ""))


def _device_repository_entry(value):
    info = _get_member(value, "device_info", "get_device_info")
    identity = _device_identity(_get_member(value, "device_id", "get_device_id"))
    categories = []
    families = []
    if info is not None:
        try:
            categories = [int(item) for item in list(
                _get_member(info, "categories", "get_categories", [])
            )]
        except Exception:
            categories = []
        try:
            families = [_text(item) for item in list(
                _get_member(info, "families", "get_families", [])
            )]
        except Exception:
            families = []
    return {
        "name": _device_info_value(info, "name") if info is not None else "",
        "vendor": _device_info_value(info, "vendor") if info is not None else "",
        "description": (
            _device_info_value(info, "description") if info is not None else ""
        ),
        "orderNumber": (
            _device_info_value(info, "order_number") if info is not None else ""
        ),
        "categories": categories,
        "families": families,
        "deviceId": identity,
    }


def _repository_source_summary(value):
    result = {}
    for name in ("name", "location_url", "location", "editable", "internal"):
        item = _get_member(value, name, "get_" + name)
        if item is not None and _text(item) != "":
            result[name] = _json_safe(item)
    if not result:
        result["display"] = _text(value)
    return result


def _device_repository_sources(repository):
    values = _get_member(repository, "sources", "get_sources", [])
    try:
        return list(values)
    except Exception:
        return []


def _device_enumeration_attempts():
    """Run explicit API overloads because SP11 binds the no-arg call poorly."""
    repository = _device_repository()
    attempts = []
    calls = [
        ("get_all_devices()", lambda: repository.get_all_devices()),
        ("get_all_devices(name='')", lambda: repository.get_all_devices("")),
        ("get_all_devices(name='', source=None)", lambda: repository.get_all_devices("", None)),
    ]
    sources = _device_repository_sources(repository)
    for index, source in enumerate(sources):
        label = "source[%d]" % index
        calls.extend([
            ("get_all_devices(%s)" % label,
             lambda source=source: repository.get_all_devices(source)),
            ("get_all_devices(name='', %s)" % label,
             lambda source=source: repository.get_all_devices("", source)),
        ])
    for binding, call in calls:
        try:
            collection = call()
            try:
                values = list(collection)
            except Exception as exc:
                attempts.append({"binding": binding, "error": repr(exc)})
                continue
            attempts.append({"binding": binding, "count": len(values), "values": values})
        except Exception as exc:
            attempts.append({"binding": binding, "error": repr(exc)})
    return repository, sources, attempts


def device_repository_status():
    repository, sources, attempts = _device_enumeration_attempts()
    del repository
    return {
        "sources": [_repository_source_summary(source) for source in sources],
        "attempts": [dict((key, value) for key, value in attempt.items()
                          if key != "values") for attempt in attempts],
        "anyDevicesFound": any(bool(attempt.get("values")) for attempt in attempts),
    }


def device_categories(req=None):
    """Enumerate numeric categories from the installed device repository.

    The SP11 repository binding exposes category IDs on ``DeviceInfo`` but
    does not reliably expose human-readable category names.  Returning the
    IDs and counts is still useful for selecting a device, while the explicit
    ``namesUnavailable`` flag prevents callers from inventing labels.
    """
    del req
    entries = _installed_device_entries()
    counts = {}
    examples = {}
    for _raw, entry in entries:
        for category in entry.get("categories", []):
            key = _text(category)
            counts[key] = counts.get(key, 0) + 1
            examples.setdefault(key, [])
            identity = entry.get("deviceId") or {}
            example = {
                "name": entry.get("name", ""),
                "deviceId": identity,
            }
            if len(examples[key]) < 5 and example not in examples[key]:
                examples[key].append(example)
    categories = []
    for key in sorted(counts.keys(), key=lambda value: _version_key(value)):
        categories.append({
            "id": int(key) if key.isdigit() else key,
            "deviceCount": counts[key],
            "examples": examples.get(key, []),
            "name": None,
        })
    return {
        "count": len(categories),
        "categories": categories,
        "source": "installed_device_repository.device_info.categories",
        "namesUnavailable": True,
        "claims": {
            "readOnly": True,
            "installedRepositoryOnly": True,
            "projectTreeCategories": False,
        },
    }


def _installed_device_entries():
    _repository, _sources, attempts = _device_enumeration_attempts()
    successful = [attempt for attempt in attempts if "values" in attempt]
    if not successful:
        raise OperationError(
            "InoProShop could not enumerate installed devices through any "
            "ScriptEngine repository binding",
            "device_enumeration_failed",
            {"attempts": [dict((key, value) for key, value in attempt.items()
                                if key != "values") for attempt in attempts]},
        )
    chosen = max(successful, key=lambda attempt: len(attempt.get("values", [])))
    return [(value, _device_repository_entry(value))
            for value in chosen.get("values", [])]


def _version_key(value):
    result = []
    for part in _text(value).replace(",", ".").split("."):
        part = part.strip()
        try:
            result.append(int(part))
        except Exception:
            try:
                result.append(int(part, 16))
            except Exception:
                result.append(0)
    return tuple(result)


def _device_explicit_selector_name(req):
    """Return the catalog/display selector, never an instance name.

    ``device.add`` historically overloaded ``name`` for both the destination
    instance and the repository display name.  The two values are unrelated:
    an instance such as ``R54_DI16`` is not expected to occur in the installed
    catalog row ``AM600 DI16 module``.  Keep the explicit selector aliases in
    one place so every repository consumer applies the same precedence.

    ``selectorName``/``catalogName`` are accepted as unambiguous aliases for
    callers that cannot use the older ``deviceName`` spelling.  ``name`` is a
    legacy selector only when none of those explicit fields is supplied.
    """
    if not isinstance(req, dict):
        return ""
    for key in ("selectorName", "catalogName", "deviceName", "device_name"):
        value = req.get(key)
        if value is not None and _text(value).strip():
            return _text(value).strip()
    return _text(req.get("name")).strip()


def _device_selector_request(req, instance_name=False):
    """Separate a destination instance name from repository selectors.

    The public generic device route requires ``name`` because it is the new
    node's instance name, while the installed repository is selected by
    ``deviceName`` (or an exact type/id/version triple).  Older callers that
    supplied only ``name`` continue to resolve by that name.  For the explicit
    ``device.add`` path, any identity field makes ``name`` non-selecting unless
    an explicit catalog selector is present.

    This helper is deliberately pure: it only copies/normalizes the request;
    no repository or native API is touched, which lets the caller resolve once
    and prevents a failed selector from triggering duplicate native attempts.
    """
    if not isinstance(req, dict):
        return req
    normalized = dict(req)
    explicit_name = None
    for key in ("selectorName", "catalogName", "deviceName", "device_name"):
        value = req.get(key)
        if value is not None and _text(value).strip():
            explicit_name = _text(value).strip()
            break
    has_identity = any(req.get(key) is not None
                      for key in ("type", "id", "version"))
    if explicit_name:
        # Canonicalize the selector into the field consumed by the legacy
        # filter while retaining the original aliases for diagnostics.
        normalized["name"] = explicit_name
    elif instance_name and has_identity:
        # ``name`` is the destination instance in device.add/device.add_cpu;
        # do not let it filter the catalog when an identity was supplied.
        normalized.pop("name", None)
    return normalized


def _device_selector_summary(req, instance_name=False):
    """Return an auditable selector/instance split for operation receipts."""
    selector = _device_explicit_selector_name(req)
    has_explicit = any(
        req.get(key) is not None and _text(req.get(key)).strip()
        for key in ("selectorName", "catalogName", "deviceName", "device_name")
    ) if isinstance(req, dict) else False
    # ``name`` is still both selector and destination for legacy name-only
    # calls.  Preserve that fact in the receipt instead of dropping the
    # instance label simply because no explicit alias was supplied.
    instance = (_text(req.get("name")).strip() or None
                if instance_name and isinstance(req, dict) else None)
    return {
        "catalogName": selector or None,
        "instanceName": instance,
        "identity": {
            "type": req.get("type") if isinstance(req, dict) else None,
            "id": req.get("id") if isinstance(req, dict) else None,
            "version": req.get("version") if isinstance(req, dict) else None,
        },
        "mode": ("instance_plus_explicit_selector" if instance_name and has_explicit
                 else "instance_plus_explicit_identity" if instance_name and isinstance(req, dict)
                 and any(req.get(key) is not None for key in ("type", "id", "version"))
                 else "legacy_name_selector"),
    }


def _filter_installed_devices(req):
    # Explicit repository selectors always win over the legacy ``name`` key.
    # This is what makes ``name=<instance>, deviceName=<catalog row>`` safe.
    name = _device_explicit_selector_name(req).lower()
    vendor = _text(req.get("vendor")).strip().lower()
    description = _text(req.get("description")).strip().lower()
    raw_keywords = req.get("keywords") or []
    if not isinstance(raw_keywords, (list, tuple)):
        raise OperationError("device keywords must be an array", "invalid_argument")
    keywords = [_text(value).strip().lower() for value in raw_keywords]
    keywords = [value for value in keywords if value]
    requested_type = req.get("type")
    requested_id = req.get("id")
    if requested_id is not None:
        requested_id = _normalize_device_id(requested_id)
    requested_version = req.get("version")
    if requested_type is not None:
        try:
            requested_type = int(requested_type)
        except Exception:
            raise OperationError("device type must be an integer", "invalid_argument")
    matches = []
    for raw, item in _installed_device_entries():
        identity = item.get("deviceId") or {}
        searchable = " ".join([
            item.get("name", ""), item.get("vendor", ""),
            item.get("description", ""), " ".join(item.get("families", [])),
        ]).lower()
        if name and name not in item.get("name", "").lower():
            continue
        if vendor and vendor not in item.get("vendor", "").lower():
            continue
        if description and description not in item.get("description", "").lower():
            continue
        if keywords and not all(value in searchable for value in keywords):
            continue
        if requested_type is not None and identity.get("type") != requested_type:
            continue
        if (requested_id is not None and
                _normalize_device_id(identity.get("id")) != requested_id):
            continue
        if (requested_version is not None and
                identity.get("version") != _text(requested_version)):
            continue
        matches.append((raw, item))
    return matches


def _device_candidate_names(needle, limit=8):
    """Top installed-catalog names relevant to a failed module selector, so a
    rejection can carry the valid options instead of forcing a re-probe."""
    needle = _text(needle).strip().lower()
    if not needle:
        return []
    found = []
    for _raw, item in _installed_device_entries():
        identity = item.get("deviceId") or {}
        searchable = " ".join([
            item.get("name", ""), item.get("description", ""),
            item.get("orderNumber", ""), _text(identity.get("id", "")),
        ]).lower()
        if needle in searchable:
            entry = {
                "name": item.get("name", ""),
                "type": identity.get("type"),
                "id": identity.get("id"),
                "version": identity.get("version"),
            }
            if entry not in found:
                found.append(entry)
        if len(found) >= limit:
            break
    return found


def _resolve_installed_device(req, instance_name=False):
    """Resolve one installed repository row using a normalized selector.

    ``instance_name`` is true only for the generic insertion operations.  It
    tells the resolver that ``name`` identifies the destination node, not the
    repository row; the old name-only selector behavior remains unchanged for
    probes and the vendor project wizard.
    """
    selector_req = _device_selector_request(req, instance_name)
    selector_present = any(selector_req.get(key) is not None for key in (
        "name", "selectorName", "catalogName", "deviceName", "device_name",
        "type", "id", "version",
    ))
    if not selector_present:
        raise OperationError(
            "device selector is required: provide deviceName or type/id "
            "from device.list_installed",
            "invalid_argument",
        )
    matches = _filter_installed_devices(selector_req)
    if not matches:
        explicit_identity = (selector_req.get("type") is not None and
                             selector_req.get("id") is not None and
                             selector_req.get("version") is not None)
        if explicit_identity:
            try:
                device_type = int(selector_req.get("type"))
            except Exception:
                raise OperationError("device type must be an integer", "invalid_argument")
            return None, {
                "name": _text(_device_explicit_selector_name(req) or
                              req.get("name")),
                "vendor": "",
                "description": "",
                "orderNumber": "",
                "categories": [],
                "families": [],
                "deviceId": {
                    "type": device_type,
                    "id": _text(selector_req.get("id")),
                    "version": _text(selector_req.get("version")),
                },
                "selection": "explicit_identity_not_enumerated",
                "selector": _device_selector_summary(req, instance_name),
            }
        raise OperationError(
            "no installed InoProShop device matches the selector",
            "device_not_installed",
            {"selector": {
                "name": _device_explicit_selector_name(req),
                "selectorName": req.get("selectorName") or req.get("catalogName"),
                "deviceName": req.get("deviceName") or req.get("device_name"),
                "type": selector_req.get("type"), "id": selector_req.get("id"),
                "version": selector_req.get("version"),
            }, "instanceName": (_text(req.get("name")).strip() or None)
            if instance_name else None},
        )
    groups = {}
    for raw, item in matches:
        identity = item.get("deviceId") or {}
        key = (_text(identity.get("type")),
               _normalize_device_id(identity.get("id", "")))
        groups.setdefault(key, []).append((raw, item))
    if len(groups) != 1:
        candidates = []
        for entries in groups.values():
            candidates.append(entries[-1][1])
        raise OperationError(
            "device selector is ambiguous; pass the exact type and id from "
            "device.list_installed",
            "ambiguous_device_selector",
            {"candidates": candidates[:50]},
        )
    versions = list(groups.values())[0]
    versions.sort(key=lambda entry: _version_key(
        (entry[1].get("deviceId") or {}).get("version", "")
    ))
    return versions[-1]


def device_add_probe(req):
    """Resolve an installed device without mutating the open project."""
    raw, selected = _resolve_installed_device(req)
    identity = selected.get("deviceId") or {}
    return {
        "probeOnly": True,
        "mutated": False,
        "selection": selected,
        "repositoryEntryResolved": raw is not None,
        "candidateBindings": [value for value in [
            "type_id_version",
            "repository_device_id" if raw is not None else None,
            "factory_device_id",
        ] if value],
        "deviceIdentity": identity,
        "claims": {
            "repositoryResolution": True,
            "projectInsertion": False,
            "projectCreation": False,
            "versionSwitchBehavior": False,
        },
    }


