def _reflection_type(type_name):
    """Resolve a loaded CLR type without requiring static IronPython imports."""
    try:
        import System
        value = System.Type.GetType(type_name, False)
        if value is not None:
            return value
        # Core/vendor assemblies are normally already loaded in an
        # InoProShop profile.  Use the supported Assembly.Load overload for
        # a simple identity; LoadWithPartialName writes a deprecation warning
        # into the IDE message pane and makes bridge diagnostics look like PLC
        # failures.
        assembly_name = type_name.rsplit(",", 1)[-1].strip()
        loaded = None
        try:
            loaded = System.Reflection.Assembly.Load(assembly_name)
        except Exception:
            # InoProShop plug-ins use a physical ``*.plugin.dll`` file name
            # but are not always resolvable by simple identity until another
            # feature has loaded them. Resolve only an exact file name below
            # the configured installation PlugIns root. This replaces the
            # obsolete LoadWithPartialName call without guessing a DLL.
            candidate_name = assembly_name + ".dll"
            candidate_path = plugin_assembly_path_cache.get(candidate_name)
            if candidate_path is None and re.match(r"^[A-Za-z0-9_.-]+\.dll$", candidate_name):
                try:
                    for root, _dirs, files in os.walk(PLUGIN_ROOT):
                        if candidate_name in files:
                            candidate_path = os.path.join(root, candidate_name)
                            plugin_assembly_path_cache[candidate_name] = candidate_path
                            break
                except Exception:
                    candidate_path = None
            if candidate_path and os.path.isfile(candidate_path):
                try:
                    loaded = System.Reflection.Assembly.LoadFrom(candidate_path)
                except Exception:
                    loaded = None
        if loaded is not None:
            return loaded.GetType(type_name.split(",", 1)[0].strip(), False)
        # Vendor plugin assemblies use the physical *.plugin.dll name while
        # their assembly identity can differ. Search already-loaded assemblies
        # before declaring a type unavailable.
        full_name = type_name.split(",", 1)[0].strip()
        for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
            try:
                value = assembly.GetType(full_name, False)
                if value is not None:
                    return value
            except Exception:
                pass
    except Exception:
        pass
    return None


def _reflection_generic_create(interface_name, type_guid, try_create=True):
    """Call ComponentManager.CreateInstance<T> through reflection.

    The ScriptEngine exposes no direct binding for the vendor's managed
    component interfaces. Reflection keeps this probe read-only and records
    the exact binding instead of guessing at Python imports.
    """
    import System
    manager_type = _reflection_type(
        "_3S.CoDeSys.Core.Components.ComponentManager, Core"
    )
    interface_type = _reflection_type(interface_name)
    if manager_type is None:
        raise RuntimeError("Core.ComponentManager type is unavailable")
    if interface_type is None:
        raise RuntimeError("interface type is unavailable: " + interface_name)
    singleton = manager_type.GetProperty("Singleton").GetValue(None, None)
    if singleton is None:
        raise RuntimeError("ComponentManager.Singleton is null")
    method_name = "TryCreateInstance" if try_create else "CreateInstance"
    methods = [method for method in manager_type.GetMethods()
               if method.Name == method_name and method.IsGenericMethodDefinition
               and len(method.GetGenericArguments()) == 1
               and len(method.GetParameters()) == 1]
    if not methods:
        raise RuntimeError("generic %s<T>(Guid) binding is unavailable" % method_name)
    method = methods[0].MakeGenericMethod(interface_type)
    guid = System.Guid(type_guid)
    args = System.Array[System.Object]([guid])
    value = method.Invoke(singleton, args)
    return value, {
        "interface": interface_name,
        "typeGuid": type_guid,
        "binding": "ComponentManager.Singleton.%s<T>(Guid)" % method_name,
        "runtimeType": _text(value.GetType().FullName) if value is not None else None,
    }


def _description_summary(description):
    if description is None:
        return None
    identity = _get_member(description, "device_identification", "get_device_identification")
    if identity is None:
        identity = _get_member(description, "DeviceIdentification", "get_DeviceIdentification")
    info = _get_member(description, "device_info", "get_device_info")
    if info is None:
        info = _get_member(description, "DeviceInfo", "get_DeviceInfo")
    return {
        "runtimeType": _text(description.GetType().FullName),
        "deviceId": _device_identity(identity),
        "name": (_device_info_value(info, "name") or
                 _device_info_value(info, "Name")) if info is not None else "",
        "vendor": (_device_info_value(info, "vendor") or
                   _device_info_value(info, "Vendor")) if info is not None else "",
        "description": (_device_info_value(info, "description") or
                        _device_info_value(info, "Description")) if info is not None else "",
        "allowTopLevel": bool(
            _get_member(description, "allow_top_level", "get_allow_top_level", False) or
            _get_member(description, "AllowTopLevel", "get_AllowTopLevel", False)
        ),
        "hideInCatalogue": bool(
            _get_member(description, "hide_in_catalogue", "get_hide_in_catalogue", False) or
            _get_member(description, "HideInCatalogue", "get_HideInCatalogue", False)
        ),
    }


def vendor_wizard_probe(req):
    """Read-only vendor binding probe; never creates or mutates a project."""
    import System
    raw, selected = _resolve_installed_device(req)
    identity = selected.get("deviceId") or {}
    result = {
        "probeOnly": True,
        "mutated": False,
        "selector": {
            "type": identity.get("type"),
            "id": identity.get("id"),
            "version": identity.get("version"),
        },
        "repositoryEntryResolved": raw is not None,
        "attempts": [],
        "claims": {
            "repositoryResolution": True,
            "coreDeviceDescription": False,
            "stFactory": False,
            "wizardFactory": False,
            "configurationFactory": False,
            "projectCreation": False,
        },
    }

    def attempt(name, call):
        try:
            value, binding = call()
            result["attempts"].append({
                "name": name,
                "ok": value is not None,
                "binding": binding,
                "value": _json_safe(value) if value is None else None,
            })
            return value
        except Exception as exc:
            result["attempts"].append({
                "name": name,
                "ok": False,
                "error": repr(exc),
            })
            return None

    wizard = attempt(
        "inovance_project_wizard",
        lambda: _reflection_generic_create(
            INOVANCE_WIZARD_INTERFACE, INOVANCE_WIZARD_TYPE_GUID
        ),
    )
    result["claims"]["wizardFactory"] = wizard is not None
    if wizard is not None:
        result["wizard"] = {
            "runtimeType": _text(wizard.GetType().FullName),
            "interfaces": [_text(item.FullName) for item in wizard.GetType().GetInterfaces()],
            "methods": [
                {
                    "name": _text(method.Name),
                    "parameters": [_text(param.ParameterType.FullName)
                                   for param in method.GetParameters()],
                    "returnType": _text(method.ReturnType.FullName),
                }
                for method in wizard.GetType().GetMethods()
                if method.Name == "Execute"
            ],
        }

    repository = None
    try:
        if wizard is None:
            raise RuntimeError("wizard instance is unavailable for assembly lookup")
        ap_type = wizard.GetType().Assembly.GetType(
            "Inovance.InoPro.InoProjectWizards.APEnvironment", False
        )
        if ap_type is None:
            raise RuntimeError("InovanceProjectWizards.APEnvironment type is unavailable")
        property_info = ap_type.GetProperty(
            "DeviceRepository",
            System.Reflection.BindingFlags.Static |
            System.Reflection.BindingFlags.Public |
            System.Reflection.BindingFlags.NonPublic,
        )
        if property_info is None:
            raise RuntimeError("APEnvironment.DeviceRepository property is unavailable")
        repository = property_info.GetValue(None, None)
        result["attempts"].append({
            "name": "device_repository",
            "ok": repository is not None,
            "binding": "InovanceProjectWizards.APEnvironment.DeviceRepository",
            "runtimeType": _text(repository.GetType().FullName)
                            if repository is not None else None,
        })
    except Exception as exc:
        result["attempts"].append({
            "name": "device_repository",
            "ok": False,
            "error": repr(exc),
        })
    if repository is not None:
        try:
            device_id = repository.CreateDeviceIdentification(
                int(identity.get("type")), identity.get("id"), identity.get("version")
            )
            description = repository.GetDevice(device_id)
            result["coreDeviceDescription"] = _description_summary(description)
            result["claims"]["coreDeviceDescription"] = description is not None
        except Exception as exc:
            result["attempts"].append({
                "name": "repository.get_device",
                "ok": False,
                "error": repr(exc),
            })

    st_factory = attempt(
        "st_implementation_factory",
        lambda: _reflection_generic_create(
            INOVANCE_IMPLEMENTATION_FACTORY_INTERFACE,
            INOVANCE_ST_IMPLEMENTATION_FACTORY_GUID,
        ),
    )
    result["claims"]["stFactory"] = st_factory is not None
    if st_factory is not None:
        result["stFactory"] = {
            "runtimeType": _text(st_factory.GetType().FullName),
            "name": _object_name(st_factory),
            "description": _text(_get_member(st_factory, "description", "get_description", "")),
        }

    config_factory = attempt(
        "configuration_sync_factory",
        lambda: _reflection_generic_create(
            INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID
        ),
    )
    result["claims"]["configurationFactory"] = config_factory is not None
    if config_factory is not None:
        result["configurationFactory"] = {
            "runtimeType": _text(config_factory.GetType().FullName),
            "interfaces": [_text(item.FullName)
                           for item in config_factory.GetType().GetInterfaces()],
            "createConfigSyncProjAvailable": any(
                method.Name == "CreateConfigSyncProj"
                for method in config_factory.GetType().GetMethods()
            ),
        }

    result["status"] = "bound" if all(result["claims"].get(key) for key in (
        "coreDeviceDescription", "stFactory", "wizardFactory", "configurationFactory"
    )) else "binding_incomplete"
    result["issues"] = [
        "This probe never calls IInovanceProjectWizard.Execute.",
        "A successful binding is not project-creation or CPU compatibility evidence.",
    ]
    return result


def _disposable_project_path(req):
    path = _text(req.get("path") or req.get("projectPath")).strip()
    if not path:
        raise OperationError(
            "project.create_with_cpu requires path", "invalid_argument"
        )
    if req.get("disposable") is not True:
        raise OperationError(
            "project.create_with_cpu requires disposable=true",
            "disposable_confirmation_required",
            {"path": path, "disposableRoot": DISPOSABLE_ROOT},
        )
    target = os.path.normcase(os.path.abspath(path))
    root = os.path.normcase(os.path.abspath(DISPOSABLE_ROOT))
    if not target.endswith(".project"):
        raise OperationError(
            "disposable project path must end with .project", "invalid_argument"
        )
    if target == root or not target.startswith(root.rstrip("\\/") + os.sep):
        raise OperationError(
            "project path is outside the disposable experiment root",
            "unsafe_project_path",
            {"path": path, "resolvedPath": target, "disposableRoot": root},
        )
    if os.path.exists(target):
        raise OperationError(
            "disposable project destination already exists",
            "destination_exists",
            {"path": target},
        )
    return target


def _require_current_disposable_project(req, operation):
    """Refuse provider upgrades outside the dedicated experiment root."""
    _require_project()
    if req.get("disposable") is not True:
        raise OperationError(
            operation + " requires disposable=true",
            "disposable_confirmation_required",
            {"projectPath": _project_path(), "disposableRoot": DISPOSABLE_ROOT},
        )
    project_path = _project_path()
    if not project_path:
        raise OperationError(
            "open project path is unavailable", "project_path_unavailable"
        )
    target = os.path.normcase(os.path.abspath(project_path))
    root = os.path.normcase(os.path.abspath(DISPOSABLE_ROOT))
    if target == root or not target.startswith(root.rstrip("\\/") + os.sep):
        raise OperationError(
            "open project is outside the disposable experiment root",
            "unsafe_project_path",
            {"projectPath": project_path, "resolvedPath": target,
             "disposableRoot": root},
        )
    return target


# These operations can change project contents. Keep the protection at the
# dispatch boundary as well as in vendor-specific writers: new aliases must
# not accidentally gain a path to the real PLC Engineering Suite project.
# Creation ops are exempt from the open-project requirement: they must run
# with NO project open (their handlers enforce project_already_open), so
# asking for an open project first would make them impossible.
