def _require_disposable_mutation_request(req, operation):
    """Require an explicit disposable confirmation for every project write."""
    if req.get("disposable") is not True:
        raise OperationError(
            operation + " requires disposable=true",
            "disposable_confirmation_required",
            {
                "operation": operation,
                "projectPath": _project_path(),
                "disposableRoot": DISPOSABLE_ROOT,
                "mutatedProject": False,
                "errors": [{
                    "code": "DISPOSABLE_CONFIRMATION_REQUIRED",
                    "path": "disposable", "expected": True,
                    "actual": req.get("disposable"), "example": True,
                    "message": "project writes require explicit disposable scope",
                    "remediation": "Set disposable=true and keep the project under the disposable root.",
                }],
                "next": "repeat the operation with disposable=true",
            },
        )


def _require_public_write_confirmation(req, operation):
    """Reject an unacknowledged generic public write before mutation."""
    expected = PUBLIC_PROJECT_WRITE_CONFIRMATIONS.get(operation)
    if expected and _text(req.get("confirm")).strip() != expected:
        raise OperationError(
            operation + " requires confirm=" + expected,
            "confirmation_required",
            {
                "operation": operation,
                "expectedConfirm": expected,
                "mutatedProject": False,
                "errors": [{
                    "code": "CONFIRMATION_REQUIRED", "path": "confirm",
                    "expected": expected, "actual": req.get("confirm"),
                    "example": expected,
                    "message": "the write confirmation token is missing or incorrect",
                    "remediation": "Set confirm to the exact value shown in expected.",
                }],
                "next": "repeat the operation with the exact confirmation token",
            },
        )


def _require_mutable_project_scope(operation, req=None):
    """Allow project mutation only inside the disposable experiment root."""
    if operation in _PROJECT_CREATION_OPERATIONS:
        # Creation ops bring their own project into existence; they must run
        # with NO project open and their handlers enforce that. Requiring an
        # open project here made project.create impossible: the guard said
        # project_required with no project open while the handler said
        # project_already_open with one open.
        return
    if operation == "roundtrip.verify" and project is None:
        requested = _text((req or {}).get("projectPath") or
                          (req or {}).get("path")).strip()
        if not requested:
            raise OperationError(
                "roundtrip.verify requires projectPath when no project is open",
                "project_required",
                {"operation": operation, "mutatedProject": False},
            )
        target = os.path.normcase(os.path.abspath(requested))
        root = os.path.normcase(os.path.abspath(DISPOSABLE_ROOT))
        if (target == root or
                not target.startswith(root.rstrip("\\/") + os.sep)):
            raise OperationError(
                "roundtrip.verify project is outside the disposable experiment root",
                "unsafe_project_write_blocked",
                {"operation": operation, "projectPath": requested,
                 "resolvedPath": target, "disposableRoot": root,
                 "mutatedProject": False},
            )
        return target
    if project is None:
        raise OperationError(
            "project mutation requires an open project",
            "project_required",
            {"operation": operation, "mutatedProject": False},
        )
    project_path = _project_path()
    root = os.path.normcase(os.path.abspath(DISPOSABLE_ROOT))
    target = os.path.normcase(os.path.abspath(project_path)) if project_path else ""
    if not target or target == root or not target.startswith(root.rstrip("\\/") + os.sep):
        raise OperationError(
            "project mutation is blocked outside the disposable experiment root",
            "unsafe_project_write_blocked",
            {
                "operation": operation,
                "projectPath": project_path,
                "resolvedPath": target or None,
                "disposableRoot": root,
                "mutatedProject": False,
                "next": "open or create a disposable project under the experiment root",
            },
        )
    return target


def _require_disposable_destination_path(path, operation):
    """Keep project copies and archives out of the protected project area."""
    requested = _text(path).strip()
    if not requested:
        raise OperationError(operation + " requires path", "invalid_argument")
    target = os.path.normcase(os.path.abspath(requested))
    root = os.path.normcase(os.path.abspath(DISPOSABLE_ROOT))
    if target == root or not target.startswith(root.rstrip("\\/") + os.sep):
        raise OperationError(
            operation + " destination is outside the disposable experiment root",
            "unsafe_project_path",
            {
                "operation": operation,
                "path": requested,
                "resolvedPath": target,
                "disposableRoot": root,
                "fileWriteAttempted": False,
            },
        )
    return target


def _version_update_item_summary(item):
    fields = (
        "stVersionName", "stCurVersion", "stNewestVersion", "stUpdateInfo",
        "stDetails", "VersionClass",
    )
    summary = {"runtimeType": _text(item.GetType().FullName)}
    for field in fields:
        value = _get_member(item, field, "get_" + field)
        if value is not None:
            summary[field] = _text(value)
    return summary


def lad_version_update(req):
    """Use InoProShop's registered LD/FBD version provider, never XML edits."""
    operation = _text(req.get("op") or "lad.version_update.probe")
    _require_current_disposable_project(req, operation)
    provider, binding = _reflection_generic_create(
        INOVANCE_LD_FBD_VERSION_PROVIDER_INTERFACE,
        INOVANCE_LD_FBD_VERSION_PROVIDER_GUID,
    )
    if provider is None:
        raise OperationError(
            "InoProShop did not provide the registered LD/FBD version updater",
            "ld_fbd_provider_unavailable", binding,
        )

    # These calls are the vendor provider behind Project Version Information
    # -> LD/FBD.  No migration state is assigned by this bridge.
    provider.Initialize()
    update_available = bool(provider.NewVersionAvailable(False))
    raw_items = list(provider.GetNewestVersion())
    result = {
        "projectPath": _project_path(),
        "provider": binding,
        "providerRuntimeType": _text(provider.GetType().FullName),
        "officialRoute": "Project Version Information -> LD/FBD -> Update",
        "updateAvailable": update_available,
        "items": [_version_update_item_summary(item) for item in raw_items],
        "mutated": False,
    }


def project_structured_view_probe(req):
    """Inspect live vendor StructuredView caches without editing the project.

    ``project.parent_map`` can prove that a GUID is absent from normal object
    parents and SVFoldersProperty dictionaries, but the vendor UI also keeps
    an in-memory ``Project._structuredViews`` cache.  This probe reflects that
    cache and the private ``StructuredView._nodes``/``SVNodeContainer`` lists.
    It never calls AddObject, Remove, SetParent, or any persistence API.
    ``GetStructuredView`` may lazily allocate an in-memory view for a known
    persisted view GUID; that cache-only side effect is reported explicitly.
    """
    _require_project()
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    target = _text((req or {}).get("guid") or (req or {}).get("target") or "").strip().lower()
    max_nodes = (req or {}).get("maxNodes", 2000)
    try:
        max_nodes = max(1, min(int(max_nodes), 10000))
    except Exception:
        max_nodes = 2000

    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            pass
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable", "project_handle_unavailable")

    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("SystemInstances type is unavailable", "system_instances_unavailable")
    object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is null", "system_instances_unavailable")

    def safe_value(value):
        if value is None or isinstance(value, (bool, int, float, str)):
            return value
        try:
            return _text(value)
        except Exception:
            return repr(value)

    def field_value(obj, name):
        try:
            field = obj.GetType().GetField(name, flags)
            return field.GetValue(obj) if field is not None else None
        except Exception:
            return None

    def key_texts(value, limit=max_nodes):
        if value is None:
            return []
        try:
            keys = list(value.Keys)
        except Exception:
            try:
                keys = list(value)
            except Exception:
                return []
        return [_text(item) for item in keys[:limit]]

    def describe_view(view, view_guid, source):
        result = {
            "structuredViewGuid": _text(view_guid),
            "source": source,
            "runtimeType": None,
            "projectHandle": None,
            "nodeCache": [],
            "nodeCacheCount": 0,
            "childGuids": [],
            "targetMatches": [],
        }
        try:
            result["runtimeType"] = _text(view.GetType().FullName)
        except Exception:
            pass
        try:
            result["projectHandle"] = int(view.ProjectHandle)
        except Exception:
            value = field_value(view, "_nProjectHandle")
            if value is not None:
                result["projectHandle"] = safe_value(value)
        child_value = field_value(view, "_children")
        result["childGuids"] = key_texts(child_value)
        node_dict = field_value(view, "_nodes")
        node_keys = key_texts(node_dict)
        result["nodeCacheCount"] = len(node_keys)
        for guid in node_keys[:max_nodes]:
            node = None
            try:
                node = node_dict[System.Guid(guid)]
            except Exception:
                try:
                    node = node_dict[guid]
                except Exception:
                    pass
            entry = {"objectGuid": guid}
            if node is not None:
                try:
                    entry["runtimeType"] = _text(node.GetType().FullName)
                except Exception:
                    pass
                entry["objectGuidField"] = safe_value(field_value(node, "_objectGuid"))
                parent_node = field_value(node, "_parent")
                if parent_node is not None:
                    entry["parentObjectGuid"] = safe_value(field_value(parent_node, "_objectGuid"))
                entry["childGuids"] = key_texts(field_value(node, "_children"))
            result["nodeCache"].append(entry)
            if target and (target == guid.lower() or target == _text(entry.get("objectGuidField")).lower()):
                result["targetMatches"].append(entry)
        if target and target in [item.lower() for item in result["childGuids"]]:
            result["targetMatches"].append({"location": "rootChildren", "objectGuid": target})
        return result

    view_guids = []
    discovery = []
    # Prefer the vendor Project's persisted StructuredViews list.  GetProject
    # is internal in this build, so use a reflected invocation when needed.
    vendor_project = None
    try:
        vendor_project = object_mgr.GetProject(int(handle))
    except Exception:
        try:
            method = object_mgr.GetType().GetMethod("GetProject", flags)
            if method is not None:
                vendor_project = method.Invoke(object_mgr, (int(handle),))
        except Exception as exc:
            discovery.append({"source": "ObjectMgr.GetProject", "error": repr(exc)})
    if vendor_project is not None:
        try:
            view_guids = [_text(item) for item in list(vendor_project.StructuredViews)]
            discovery.append({"source": "Project.StructuredViews", "count": len(view_guids)})
        except Exception as exc:
            discovery.append({"source": "Project.StructuredViews", "error": repr(exc)})
        # Existing cached views are available without creating new ones.
        cached = field_value(vendor_project, "_structuredViews")
        cached_keys = key_texts(cached)
        discovery.append({"source": "Project._structuredViews", "count": len(cached_keys),
                          "guids": cached_keys[:max_nodes]})
        for item in cached_keys:
            if item not in view_guids:
                view_guids.append(item)
    view_guids = list(dict((item.lower(), item) for item in view_guids).values())
    views = []
    for view_guid in view_guids:
        view = None
        source = "cached_or_persisted"
        try:
            if vendor_project is not None:
                cached = field_value(vendor_project, "_structuredViews")
                if cached is not None:
                    try:
                        view = cached[System.Guid(view_guid)]
                    except Exception:
                        try:
                            view = cached[view_guid]
                        except Exception:
                            view = None
            if view is None:
                view = object_mgr.GetStructuredView(int(handle), System.Guid(view_guid))
                source = "ObjectMgr.GetStructuredView_cache_only"
            if view is not None:
                views.append(describe_view(view, view_guid, source))
        except Exception as exc:
            views.append({"structuredViewGuid": view_guid, "source": source,
                          "error": repr(exc), "targetMatches": []})
    target_matches = []
    for view in views:
        for match in view.get("targetMatches", []):
            target_matches.append(dict(match, structuredViewGuid=view.get("structuredViewGuid")))
    return {
        "schema": "inoproshop.structured-view-probe.v1",
        "readOnly": True,
        "projectPath": _project_path(),
        "projectHandle": int(handle),
        "requestedGuid": target or None,
        "structuredViewCount": len(views),
        "views": views,
        "targetMatchCount": len(target_matches),
        "targetMatches": target_matches,
        "discovery": discovery,
        "mutatedProject": False,
        "cacheOnlyAllocationPossible": any(
            item.get("source") == "ObjectMgr.GetStructuredView_cache_only" for item in views
        ),
    }
    if operation == "lad.version_update.probe":
        return result

    if operation != "lad.version_update.apply":
        raise OperationError("unsupported LD/FBD version update operation", "invalid_argument")
    if req.get("confirm") != "apply_ld_fbd_update":
        raise OperationError(
            "confirm must exactly equal apply_ld_fbd_update",
            "confirmation_required", result,
        )
    update_result = provider.SetAllItemsToNewestVersion()
    provider.Save()
    result["mutated"] = True
    provider_result = {}
    if update_result is not None:
        for key in update_result.Keys:
            provider_result[_text(key)] = _text(update_result[key])
    result["providerResult"] = provider_result
    result["postUpdateAvailable"] = bool(provider.NewVersionAvailable(False))
    result["postUpdateItems"] = [
        _version_update_item_summary(item)
        for item in list(provider.GetNewestVersion())
    ]
    return result


def _system_instances_property(name):
    """Read one static property from _3S.CoDeSys.Core.SystemInstances."""
    import System
    probes = {"property": name}
    instance_type = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if instance_type is None:
        probes["error"] = "SystemInstances type is unavailable"
        return None, probes
    prop = instance_type.GetProperty(name)
    if prop is None:
        probes["error"] = "property is unavailable"
        return None, probes
    value = prop.GetValue(None, None)
    if value is not None:
        probes["runtimeType"] = _text(value.GetType().FullName)
    return value, probes


def _option_root_zero_key(probes):
    """Open OptionRoot(0); its data is embedded in the project WorkspaceObject."""
    import System
    storage, storage_probe = _system_instances_property("OptionStorage")
    probes.append(dict([("kind", "option_storage")] + storage_probe.items()))
    if storage is None:
        return None
    try:
        root_key = storage.GetRootKey(0)
        probes.append({"kind": "option_root", "root": 0,
                       "binding": "GetRootKey(int)"})
        return root_key
    except Exception as exc:
        probes.append({"kind": "option_root", "root": 0,
                       "binding": "GetRootKey(int)", "error": repr(exc)})
    enum_type = _reflection_type("_3S.CoDeSys.Core.Options.OptionRoot, Core")
    if enum_type is None:
        probes.append({"kind": "option_root", "root": 0,
                       "error": "OptionRoot enum type is unavailable"})
        return None
    try:
        root_value = System.Enum.ToObject(enum_type, 0)
        root_key = storage.GetRootKey(root_value)
        probes.append({"kind": "option_root", "root": 0,
                       "binding": "GetRootKey(OptionRoot)"})
        return root_key
    except Exception as exc:
        probes.append({"kind": "option_root", "root": 0,
                       "binding": "GetRootKey(OptionRoot)", "error": repr(exc)})
    return None


def _read_option_values(key, value_names):
    """Read named values from one IOptionKey without creating anything."""
    import System
    values = {}
    for value_name in value_names:
        entry = {}
        try:
            entry["present"] = bool(key.HasValue(value_name, System.String))
        except Exception as exc:
            entry["hasValueError"] = repr(exc)
        if entry.get("present"):
            raw = None
            try:
                raw = key[value_name]
            except Exception:
                try:
                    raw = key.Item[value_name]
                except Exception as exc:
                    entry["readError"] = repr(exc)
            if raw is not None:
                text = _text(raw)
                entry["length"] = len(text)
                entry["value"] = text[:4000]
        values[value_name] = entry
    return values


def _read_option_subkey(root_key, subkey_name, value_names):
    entry = {"name": subkey_name, "exists": False}
    try:
        if not root_key.HasSubKey(subkey_name):
            return entry
        entry["exists"] = True
        key = root_key.OpenSubKey(subkey_name)
        entry["values"] = _read_option_values(key, value_names)
    except Exception as exc:
        entry["error"] = repr(exc)
    return entry


def _workspace_object_presence(probes):
    """Report whether the option-carrying WorkspaceObject exists in the project."""
    import System
    object_mgr, om_probe = _system_instances_property("ObjectMgr")
    probes.append(dict([("kind", "object_mgr")] + om_probe.items()))
    if object_mgr is None:
        return None
    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            handle = None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        probes.append({"kind": "workspace_object",
                       "error": "project handle is unavailable"})
        return None
    try:
        exists = bool(object_mgr.ExistsObject(
            int(handle), System.Guid(INOVANCE_WORKSPACE_OBJECT_GUID)
        ))
        probes.append({"kind": "workspace_object",
                       "handle": int(handle),
                       "objectGuid": INOVANCE_WORKSPACE_OBJECT_GUID,
                       "exists": exists})
        return exists
    except Exception as exc:
        probes.append({"kind": "workspace_object", "error": repr(exc)})
    return None


def _libversion_option_snapshot():
    """Minimal ListLib + placeholder-redirection snapshot for update experiments."""
    probes = []
    root_key = _option_root_zero_key(probes)
    subkeys = []
    if root_key is not None:
        subkeys.append(_read_option_subkey(
            root_key, OPTION_SUBKEY_LIBS_MANAGER, [OPTION_VALUE_LIB_LIST]
        ))
    else:
        subkeys.append({"name": OPTION_SUBKEY_LIBS_MANAGER,
                        "error": "OptionRoot(0) is unavailable"})
    manager = None
    manager_error = None
    redirections = {}
    placeholder_count = 0
    redirection_api_kind = "none"
    redirection_api_probes = []
    placeholder_read_errors = []
    try:
        manager = _find_project_library_manager()
    except Exception as exc:
        manager_error = repr(exc)
    if manager is not None:
        try:
            entries = _placeholder_state_entries(manager)
            placeholder_count = len(entries)
            api, redirection_api_kind, redirection_api_probes = (
                _placeholder_redirection_api(manager, False)
            )
            for entry in entries:
                placeholder_name = _text(
                    entry.get("placeholder_name") or entry.get("name")
                ).strip().lstrip("#")
                if not placeholder_name:
                    placeholder_read_errors.append({
                        "placeholder": None,
                        "error": "placeholder identity is unavailable",
                    })
                    continue
                if api is None:
                    placeholder_read_errors.append({
                        "placeholder": placeholder_name,
                        "error": "placeholder redirection API is unavailable",
                    })
                    continue
                try:
                    redirections[_text(placeholder_name)] = _text(
                        api.get_redirected_placeholder_resolution(
                            _text(placeholder_name)
                        )
                    )
                except Exception as exc:
                    error = {"error": repr(exc)}
                    redirections[_text(placeholder_name)] = error
                    placeholder_read_errors.append({
                        "placeholder": placeholder_name,
                        "error": repr(exc),
                    })
        except Exception as exc:
            manager_error = repr(exc)
    return {
        "libListOption": subkeys[0] if subkeys else None,
        "placeholderCount": placeholder_count,
        "redirections": redirections,
        "redirectionApi": redirection_api_kind,
        "redirectionBindingProbes": redirection_api_probes,
        "placeholderReadErrors": placeholder_read_errors,
        "libraryManagerError": manager_error,
        "probes": probes,
    }


def _libversion_snapshot_complete(snapshot):
    """Require readable option storage and placeholder-manager state."""
    if not isinstance(snapshot, dict):
        return False
    option = snapshot.get("libListOption")
    return bool(
        isinstance(option, dict) and not option.get("error") and
        not snapshot.get("libraryManagerError") and
        not snapshot.get("placeholderReadErrors") and
        (not snapshot.get("placeholderCount") or
         (snapshot.get("redirectionApi") not in (None, "", "none") and
          len(snapshot.get("redirections") or {}) ==
          int(snapshot.get("placeholderCount") or 0)))
    )


def liboptions_probe(req):
    """Read-only inspection of the option data carried by the open project.

    The vendor version-update flow persists its library-category selections
    (LibLDictionary) under OptionRoot(0), which the engine embeds into the
    project's WorkspaceObject.  This probe never creates a subkey and never
    writes a value; it only reports what the current project carries.
    """
    _require_project()
    probes = []
    subkeys = []
    root_key = _option_root_zero_key(probes)
    if root_key is not None:
        subkeys.append(_read_option_subkey(
            root_key, OPTION_SUBKEY_LIBS_MANAGER, [OPTION_VALUE_LIB_LIST]
        ))
        subkeys.append(_read_option_subkey(
            root_key, OPTION_SUBKEY_PROJECT_LIB_UPDATE,
            ["OmronUtilsUpdate", "IoDrvEtherNetIPAdapter"],
        ))
        subkeys.append(_read_option_subkey(
            root_key, OPTION_SUBKEY_LAST_SOFTVERSION,
            ["SoftwareVersion", "PatchVersion"],
        ))
        subkeys.append(_read_option_subkey(
            root_key, OPTION_SUBKEY_SAVED_LIB_CONFIG, [],
        ))
        subkeys.append(_read_option_subkey(
            root_key, OPTION_SUBKEY_WIZARD,
            ["DeviceId", "DeviceType", "ImplementationObjectFactory"],
        ))
    workspace_exists = _workspace_object_presence(probes)
    lib_list = None
    for entry in subkeys:
        if entry.get("name") == OPTION_SUBKEY_LIBS_MANAGER:
            lib_list = entry
    return {
        "projectPath": _project_path(),
        "optionRoot": 0,
        "libListPresent": bool(
            lib_list and lib_list.get("values", {}).get(
                OPTION_VALUE_LIB_LIST, {}
            ).get("present")
        ),
        "subkeys": subkeys,
        "workspaceObject": {
            "guid": INOVANCE_WORKSPACE_OBJECT_GUID,
            "exists": workspace_exists,
        },
        "probes": probes,
        "mutated": False,
    }


def vendor_libversion_update(req):
    """Drive the official silent library-version update for a disposable project.

    This reproduces exactly what the vendor manager does for its silent mode
    (VersionUpdateFlags bit 1): construct the registered
    VersionCompatibilityDialog, Initialize(bAutomaticCheck=True), then
    SaveControls(bStartProgressBar=False).  SaveControls is the handler behind
    the dialog's Update button; it runs every registered provider (including
    the library one that writes ListLib and the placeholder redirections),
    calls ProjectLibManagerHelper.SaveOptions and raises VersionChangedDone so
    LibraryLoader.OnVersionChangedDone re-links InoParamsConfigLib.  The bridge
    assigns no migration state itself and never edits placeholders directly.
    """
    operation = _text(req.get("op") or "vendor.libversion.update")
    _require_current_disposable_project(req, operation)
    import System
    dialog_type = _reflection_type(INOVANCE_VERSION_DIALOG_TYPE)
    binding = {
        "type": INOVANCE_VERSION_DIALOG_TYPE,
        "resolved": dialog_type is not None,
    }
    if dialog_type is None:
        raise OperationError(
            "vendor VersionCompatibilityDialog type is unavailable",
            "vendor_dialog_unavailable", binding,
        )
    if req.get("confirm") != "apply_lib_version_update":
        raise OperationError(
            "confirm must exactly equal apply_lib_version_update",
            "confirmation_required",
            {"projectPath": _project_path(), "binding": binding},
        )
    dialog = System.Activator.CreateInstance(dialog_type)
    binding["runtimeType"] = _text(dialog.GetType().FullName)
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    initialize_method = dialog_type.GetMethod("Initialize", flags)
    save_method = dialog_type.GetMethod("SaveControls", flags)
    binding["initializeMethodFound"] = initialize_method is not None
    binding["saveControlsMethodFound"] = save_method is not None
    if initialize_method is None or save_method is None:
        raise OperationError(
            "VersionCompatibilityDialog methods are unavailable",
            "vendor_dialog_unavailable", binding,
        )
    args = System.Array[System.Object]([True])
    initialized = bool(initialize_method.Invoke(dialog, args))
    before = _libversion_option_snapshot()
    result = {
        "projectPath": _project_path(),
        "binding": binding,
        "officialRoute": "Project Version Information -> Update "
                         "(silent path: Initialize(auto) + SaveControls)",
        "initialize": initialized,
        "initializeCalled": True,
        "saveControlsCalled": False,
        "before": before,
        "mutated": False,
    }
    if not initialized:
        after = _libversion_option_snapshot()
        result["after"] = after
        result["status"] = "already_current"
        result["note"] = ("Initialize reported no providers with available "
                          "updates; SaveControls was not executed, matching "
                          "the silent flags=2 semantics")
        result["claims"] = {
            "officialRouteCompleted": True,
            "initializeCalled": True,
            "beforeSnapshotReadback": _libversion_snapshot_complete(before),
            "afterSnapshotReadback": _libversion_snapshot_complete(after),
        }
        return result
    save_args = System.Array[System.Object]([False])
    save_method.Invoke(dialog, save_args)
    result["saveControlsCalled"] = True
    result["mutated"] = True
    result["status"] = "update_applied"
    after = _libversion_option_snapshot()
    result["after"] = after
    result["claims"] = {
        "officialRouteCompleted": True,
        "initializeCalled": True,
        "beforeSnapshotReadback": _libversion_snapshot_complete(before),
        "afterSnapshotReadback": _libversion_snapshot_complete(after),
    }
    return result


def _vendor_creation_bindings(req):
    """Resolve the exact managed values required by the no-UI wizard call."""
    import System
    raw, selected = _resolve_installed_device(req)
    identity = selected.get("deviceId") or {}
    wizard, wizard_binding = _reflection_generic_create(
        INOVANCE_WIZARD_INTERFACE, INOVANCE_WIZARD_TYPE_GUID
    )
    if wizard is None:
        raise OperationError(
            "Inovance project wizard factory is unavailable",
            "vendor_wizard_unavailable",
            {"binding": wizard_binding},
        )
    ap_type = wizard.GetType().Assembly.GetType(
        "Inovance.InoPro.InoProjectWizards.APEnvironment", False
    )
    if ap_type is None:
        raise OperationError(
            "vendor APEnvironment type is unavailable",
            "vendor_wizard_binding_failed",
        )
    repository_property = ap_type.GetProperty(
        "DeviceRepository",
        System.Reflection.BindingFlags.Static |
        System.Reflection.BindingFlags.Public |
        System.Reflection.BindingFlags.NonPublic,
    )
    if repository_property is None:
        raise OperationError(
            "vendor DeviceRepository property is unavailable",
            "vendor_repository_unavailable",
        )
    repository = repository_property.GetValue(None, None)
    device_id = repository.CreateDeviceIdentification(
        int(identity.get("type")), identity.get("id"), identity.get("version")
    )
    description = repository.GetDevice(device_id)
    if description is None:
        raise OperationError(
            "core device description was not found for the exact identity",
            "device_not_installed",
            {"device": selected},
        )
    st_factory, st_binding = _reflection_generic_create(
        INOVANCE_IMPLEMENTATION_FACTORY_INTERFACE,
        INOVANCE_ST_IMPLEMENTATION_FACTORY_GUID,
    )
    if st_factory is None:
        raise OperationError(
            "ST implementation factory is unavailable",
            "implementation_factory_unavailable",
            {"binding": st_binding},
        )
    config_factory, config_binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID
    )
    return {
        "wizard": wizard,
        "description": description,
        "stFactory": st_factory,
        "configurationFactory": config_factory,
        "selected": selected,
        "repositoryEntryResolved": raw is not None,
        "bindings": {
            "wizard": wizard_binding,
            "repository": "InovanceProjectWizards.APEnvironment.DeviceRepository",
            "stFactory": st_binding,
            "configurationFactory": config_binding,
        },
    }


def _find_script_project(path):
    global project
    _discover_primary_project()
    if project is not None:
        return project
    try:
        candidate = projects.get_by_path(path)
    except Exception:
        candidate = None
    if candidate is not None:
        project = candidate
        pou_cache.clear()
    return project


def _tree_required_objects():
    flat = []
    _walk_objects(project, [], 1, 32, flat)
    names = [_object_name(obj) for _path, obj in flat]
    lowered = [name.lower() for name in names]
    devices = device_tree()
    exact_cpu = [item for item in devices.get("devices", [])
                 if (item.get("deviceId") or {}).get("type") == 4102]
    checks = {
        "cpu": len(exact_cpu) == 1,
        "application": "application" in lowered,
        "plcPrg": "plc_prg" in lowered,
        "taskConfiguration": "task configuration" in lowered,
        "mainTask": "maintask" in lowered,
    }
    return {
        "checks": checks,
        "allRequiredPresent": all(checks.values()),
        "cpuDevices": exact_cpu,
        "objectNames": names,
        "tree": project_tree(10),
    }


def prepare_vendor_project(req):
    """Create and prepare a vendor project as one guarded disposable operation."""
    if req.get("disposable") is not True:
        raise OperationError(
            "project.prepare_vendor_project requires disposable=true",
            "disposable_confirmation_required",
            {"disposableRoot": DISPOSABLE_ROOT},
        )
    if _text(req.get("confirm")).strip() != "prepare_vendor_project":
        raise OperationError(
            "project.prepare_vendor_project requires confirm=prepare_vendor_project",
            "confirmation_required",
            {"mutatedProject": False, "expectedConfirm": "prepare_vendor_project"},
        )
    # Accept the natural directory/base-name form as well as the final file
    # form.  The wizard always materializes `<base>/<base>.project`; rejecting
    # the directory first only forced the caller into an avoidable error/retry.
    original_path = _text(req.get("path") or req.get("projectPath")).strip()
    normalized_path = original_path
    if original_path and not original_path.lower().endswith(".project"):
        base_path = os.path.normpath(original_path)
        if not os.path.isabs(base_path):
            base_path = os.path.join(DISPOSABLE_ROOT, base_path)
        normalized_path = os.path.join(base_path, os.path.basename(base_path) + ".project")
        req = dict(req)
        req["path"] = normalized_path
    elif original_path and not os.path.isabs(original_path):
        req = dict(req)
        req["path"] = os.path.join(DISPOSABLE_ROOT, original_path)
        normalized_path = req["path"]
    created = create_project_with_cpu(req)
    update_request = dict(req)
    update_request.update({
        "op": "vendor.libversion.update",
        "confirm": "apply_lib_version_update",
    })
    updated = vendor_libversion_update(update_request)
    automatic_redirections = []
    # The AM600 vendor baseline can publish this SoftMotion placeholder only
    # after the first compiler pass.  Its installed concrete library and
    # resolution were verified in the lib-version closure experiment.
    manager = _find_project_library_manager()
    api, api_kind, api_probes = _placeholder_redirection_api(manager, True)
    if api is not None:
        softmotion_resolution = (
            "SM3_AddRampsDefault, 4.1.0.0 "
            "(3S - Smart Software Solutions GmbH)"
        )
        try:
            before = _text(api.get_redirected_placeholder_resolution("SoftMotion_AddRamps"))
        except Exception:
            before = ""
        if not before:
            try:
                api.set_redirected_placeholder_resolution(
                    "SoftMotion_AddRamps", softmotion_resolution
                )
                committed = False
                commit_fn = getattr(api, "commit", None)
                if commit_fn is not None:
                    commit_fn()
                    committed = True
                after = _text(api.get_redirected_placeholder_resolution("SoftMotion_AddRamps"))
                automatic_redirections.append({
                    "placeholder": "SoftMotion_AddRamps",
                    "before": before,
                    "after": after,
                    "resolution": softmotion_resolution,
                    "committed": committed,
                    "api": api_kind,
                    "bindingProbes": api_probes,
                })
            except Exception as exc:
                raise OperationError(
                    "known SoftMotion placeholder could not be redirected",
                    "placeholder_redirection_failed",
                    {"placeholder": "SoftMotion_AddRamps",
                     "resolution": softmotion_resolution,
                     "error": repr(exc), "api": api_kind,
                     "bindingProbes": api_probes},
                )
    options = liboptions_probe({})
    placeholders = _placeholder_state_entries(
        _find_project_library_manager()
    )
    unresolved = []
    for item in placeholders:
        name = _text(item.get("placeholder_name") or item.get("name"))
        effective = item.get("effective_resolution")
        redirected = item.get("redirected_resolution")
        if not effective and not redirected:
            unresolved.append({"name": name, "reason": "no_effective_resolution"})
    tree = project_tree(10)
    devices = device_tree()
    if not options.get("libListPresent") or unresolved:
        raise OperationError(
            "vendor project preparation did not resolve all library placeholders",
            "vendor_project_preparation_blocked",
            {
                "created": created,
                "libraryUpdate": updated,
                "libOptions": options,
                "unresolvedPlaceholders": unresolved,
                "tree": tree,
                "devices": devices,
            },
        )
    # The version manager mutates the WorkspaceObject and placeholder table in
    # memory.  Returning ready before saving leaves a project that appears
    # prepared to this process but reopens with the vendor library dialog.
    # Persist exactly once after all official update writes have completed.
    persisted_path = _project_path()
    try:
        project.save()
    except Exception as exc:
        raise OperationError(
            "vendor project preparation could not persist its version update",
            "vendor_project_preparation_save_failed",
            {
                "projectPath": persisted_path,
                "libraryUpdate": updated,
                "libOptions": options,
                "error": repr(exc),
            },
        )
    if not persisted_path or not os.path.isfile(persisted_path):
        raise OperationError(
            "vendor project preparation save did not produce a project file",
            "vendor_project_preparation_save_failed",
            {"projectPath": persisted_path},
        )
    return {
        "status": "ready",
        "created": created,
        "libraryUpdate": updated,
        "automaticRedirections": automatic_redirections,
        "libOptions": options,
        "placeholders": placeholders,
        "tree": tree,
        "devices": devices,
        "preparedProjectSaved": True,
        "pathNormalization": {
            "requested": original_path,
            "used": normalized_path,
            "changed": original_path != normalized_path,
        },
        "savedProject": {
            "path": persisted_path,
            "bytes": os.path.getsize(persisted_path),
        },
        "claims": {
            "vendorWizardExecuted": True,
            "libraryVersionUpdateExecuted": True,
            "listLibVerified": True,
            "placeholderResolutionVerified": True,
            "projectSaved": True,
            "saveReopenVerified": False,
            "buildVerified": False,
        },
    }


def create_project_with_cpu(req):
    """Create one disposable CPU project through the vendor's no-UI wizard."""
    global project, native_core_project
    if project is not None:
        raise OperationError(
            "a project is already open; close it before the CPU experiment",
            "project_already_open",
            {"projectPath": _project_path()},
        )
    path = _disposable_project_path(req)
    parent = os.path.dirname(path)
    if not os.path.isdir(parent):
        os.makedirs(parent)
    values = _vendor_creation_bindings(req)
    wizard = values["wizard"]
    methods = [method for method in wizard.GetType().GetMethods()
               if method.Name == "Execute" and len(method.GetParameters()) == 5]
    if len(methods) != 1:
        raise OperationError(
            "vendor no-UI Execute overload could not be resolved uniquely",
            "vendor_wizard_binding_failed",
            {"overloadCount": len(methods)},
        )
    import System
    project_name = os.path.splitext(os.path.basename(path))[0]
    args = System.Array[System.Object]([
        project_name,
        parent,
        values["description"],
        System.Guid(INOVANCE_ST_IMPLEMENTATION_FACTORY_GUID),
        values["stFactory"],
    ])
    started_at = time.time()
    core_project = methods[0].Invoke(wizard, args)
    if core_project is None:
        raise OperationError(
            "vendor wizard returned no project",
            "cpu_project_creation_unconfirmed",
            {"path": path, "bindings": values["bindings"]},
        )
    native_core_project = core_project
    actual_path = _text(_get_member(core_project, "Path", "get_Path", ""))
    if not actual_path:
        actual_path = path
    try:
        system.delay(200)
    except Exception:
        pass
    if _find_script_project(actual_path) is None:
        raise OperationError(
            "vendor wizard created a core project but ScriptEngine could not bind it",
            "cpu_project_handle_unavailable",
            {"requestedPath": path, "actualPath": actual_path},
        )
    verification = _tree_required_objects()
    if not verification["allRequiredPresent"]:
        raise OperationError(
            "vendor wizard returned but required CPU project objects are missing",
            "cpu_project_structure_incomplete",
            {
                "requestedPath": path,
                "actualPath": _project_path() or actual_path,
                "verification": verification,
                "bindings": values["bindings"],
            },
        )
    project.save()
    persisted_path = _project_path() or actual_path
    # Auto-apply the official library version-compat update right after
    # creation (verified closure, 2026-09-01 round 16): every fresh AM600
    # project on this installation reports an unresolved #InoParamsConfigLib
    # placeholder, and the vendor's silent update re-links it to the
    # installed InoParamsConfigLib (1.0.2.0). Doing it HERE means callers
    # never see the known defect and never pay the extra round-trip.
    library_update = None
    try:
        library_update = vendor_libversion_update({
            "op": "project.create_with_cpu.library_update",
            "confirm": "apply_lib_version_update",
            "disposable": True,
        })
    except Exception as exc:
        library_update = {"applied": False, "error": repr(exc)}
    # The redirection only fully settles after a reopen (the first compile in
    # the same session still sees the stale create-time library log entry).
    # Save → close → reopen here so a freshly created project compiles clean
    # on its FIRST build, and close the saveReopenVerified claim gap.
    reopen_info = None
    try:
        project.save()
        close_info = None
        for _attempt in range(4):
            try:
                close_info = _close_project_after_vendor_load()
                break
            except OperationError as exc:
                if exc.code == "project_close_deferred":
                    time.sleep(0.5)
                    continue
                raise
        project, open_info = open_project_silent(persisted_path, "")
        # open_project_silent does not rebind the native core project the way
        # the project.open dispatch does; rebind here so every later op that
        # reads native_core_project.Handle sees the reopened project.
        native_core_project = _native_primary_project_for_current_path()
        reopen_info = {
            "reopened": project is not None,
            "closeInfo": close_info,
            "openInfo": open_info,
        }
    except Exception as exc:
        reopen_info = {"reopened": False, "error": repr(exc)}
    return {
        "created": True,
        "disposable": True,
        "requestedPath": path,
        "projectPath": _project_path() or persisted_path,
        "elapsedSeconds": time.time() - started_at,
        "device": values["selected"],
        "coreDeviceDescription": _description_summary(values["description"]),
        "bindings": values["bindings"],
        "configurationFactoryBound": values["configurationFactory"] is not None,
        "verification": verification,
        "saved": os.path.isfile(_project_path() or persisted_path),
        "libraryUpdate": library_update,
        "reopenAfterLibraryUpdate": reopen_info,
        "claims": {
            "vendorWizardExecuted": True,
            "treeIdentityVerified": True,
            "saveReopenVerified": bool(
                reopen_info is not None and reopen_info.get("reopened")),
            "buildVerified": False,
            "configurationStorageVerified": False,
            "placeholderLibraryRelinked": bool(
                library_update is not None
                and library_update.get("status") in (
                    "update_applied", "already_current")),
        },
    }


def _project_device_identity(value):
    return _device_identity(_get_member(
        value, "device_identification", "get_device_identification"
    ))


def _is_device_node(value):
    marked = _get_member(value, "is_device", "get_is_device", False)
    return bool(marked) or _project_device_identity(value) is not None


def device_tree():
    _require_project()
    devices = []

    def visit(parent, prefix):
        for child in _children(parent):
            name = _object_name(child) or "<unnamed>"
            path = "/".join(prefix + [name])
            identity = _project_device_identity(child)
            if _is_device_node(child):
                devices.append({
                    "name": name,
                    "path": path,
                    "deviceId": identity,
                    "childCount": len(_children(child)),
                })
            visit(child, prefix + [name])

    visit(project, [])
    return {"count": len(devices), "devices": devices}


def device_update(req):
    """Update one device through the native ScriptDeviceObject.update API."""
    operation = "device.update"
    _require_current_disposable_project(req, operation)
    target = _text(req.get("target") or req.get("path") or req.get("device")).strip()
    if not target:
        raise OperationError("device.update requires target", "invalid_argument")
    if _text(req.get("confirm")).strip() != "update_device":
        raise OperationError("device.update requires confirm=update_device",
                             "confirmation_required")
    type_value = req.get("type")
    device_id = _text(req.get("id")).strip()
    version = _text(req.get("version")).strip()
    if type_value is None or not device_id or not version:
        raise OperationError("device.update requires exact type, id, and version",
                             "invalid_argument")
    try:
        type_value = int(type_value)
    except Exception:
        raise OperationError("device type must be an integer", "invalid_argument")
    obj, object_path = find_project_object(target)
    if not _is_device_node(obj):
        raise OperationError("target is not a device node: " + object_path,
                             "not_a_device")
    before = _project_device_identity(obj)
    update = None
    adapter = None
    binding = None
    for method_name in ("update", "Update"):
        try:
            update = getattr(obj, method_name)
            binding = "project_device_wrapper." + method_name
            break
        except Exception:
            continue
    if update is None:
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Static |
                 System.Reflection.BindingFlags.Public |
                 System.Reflection.BindingFlags.NonPublic)
        base_object = None
        try:
            import clr
            wrapper_type = clr.GetClrType(type(obj))
            prop = wrapper_type.GetProperty("BaseObject", flags)
            base_object = prop.GetValue(obj, None) if prop is not None else None
        except Exception:
            base_object = None
        if base_object is not None:
            for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
                if "scriptdriverdeviceobject" not in _text(assembly.FullName).lower():
                    continue
                try:
                    adapter_type = assembly.GetType(
                        "_3S.CoDeSys.ScriptDriverDeviceObject.ScriptDeviceObject")
                    if adapter_type is None:
                        continue
                    constructors = adapter_type.GetConstructors()
                    adapter = constructors[0].Invoke(System.Array[System.Object]([base_object]))
                    update = getattr(adapter, "update")
                    binding = "ScriptDriverDeviceObject.ScriptDeviceObject(device.BaseObject).update"
                    break
                except Exception:
                    adapter = None
                    update = None
    if update is None:
        raise OperationError("native device update binding is unavailable",
                             "device_update_unavailable")
    attempts = []
    try:
        result = update(type_value, device_id, version, req.get("module"))
        attempts.append({"binding": binding, "ok": True})
    except Exception as exc:
        raise OperationError("native device update failed", "device_update_failed",
                             {"target": object_path, "error": repr(exc)})
    after = _project_device_identity(obj)
    tree_after = device_tree()
    expected = {"type": type_value, "id": device_id, "version": version}
    exact = after == expected
    if not exact:
        raise OperationError("device identity readback mismatch after update",
                             "device_update_readback_mismatch",
                             {"target": object_path, "before": before,
                              "requested": expected, "after": after})
    return {"updated": True, "target": object_path, "before": before,
            "requested": expected, "after": after, "nativeResult": _json_safe(result),
            "tree": tree_after, "attempts": attempts, "saveRequired": True,
            "claims": {"nativeUpdate": True, "exactIdentityReadback": True,
                       "saved": False, "freshProcessPersistence": False}}


def device_update_binding_probe(req):
    """Read the exact wrapper/native constructor path for ScriptDeviceObject."""
    _require_project()
    target = _text(req.get("target") or req.get("path") or req.get("device")).strip()
    if not target:
        raise OperationError("device.update.binding.probe requires target", "invalid_argument")
    obj, object_path = find_project_object(target)
    if not _is_device_node(obj):
        raise OperationError("target is not a device node: " + object_path, "not_a_device")
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    wrapper_type = None
    base_object = None
    wrapper_fields = []
    try:
        import clr
        wrapper_type = clr.GetClrType(type(obj))
        for field in wrapper_type.GetFields(flags):
            entry = {"name": _text(field.Name), "type": _text(field.FieldType.FullName)}
            try:
                value = field.GetValue(obj)
                entry["valueRuntimeType"] = _text(value.GetType().FullName) if value is not None else None
                if _text(field.Name).upper() == "BASE_OBJECT":
                    base_object = value
            except Exception as exc:
                entry["readError"] = repr(exc)
            wrapper_fields.append(entry)
        if base_object is None:
            prop = wrapper_type.GetProperty("BaseObject", flags)
            base_object = prop.GetValue(obj, None) if prop is not None else None
    except Exception as exc:
        wrapper_fields.append({"binding": "wrapper_reflection", "error": repr(exc)})
    script_device_type = None
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        if "scriptdriverdeviceobject" not in _text(assembly.FullName).lower():
            continue
        try:
            script_device_type = assembly.GetType(
                "_3S.CoDeSys.ScriptDriverDeviceObject.ScriptDeviceObject")
        except Exception:
            script_device_type = None
        if script_device_type is not None:
            break
    constructors = []
    methods = []
    if script_device_type is not None:
        try:
            constructors = [_text(item.ToString()) for item in script_device_type.GetConstructors(flags)]
            methods = [_text(item.ToString()) for item in script_device_type.GetMethods(flags)
                       if _text(item.Name) == "update"]
        except Exception as exc:
            constructors.append("<reflection-error> " + repr(exc))
    return {
        "readOnly": True,
        "mutatedProject": False,
        "target": object_path,
        "identity": _project_device_identity(obj),
        "wrapperPythonType": _text(type(obj)),
        "wrapperClrType": _text(wrapper_type.FullName) if wrapper_type is not None else None,
        "wrapperFields": wrapper_fields,
        "baseObjectRuntimeType": _text(base_object.GetType().FullName) if base_object is not None else None,
        "scriptDeviceObject": {"present": script_device_type is not None,
                               "constructors": constructors, "updateMethods": methods},
        "status": "observed" if script_device_type is not None else "unavailable",
    }


def vendor_softmotion_axis_pool_preflight(req):
    """Read-only gate for SoftMotion axis writes.

    The pool node is present in every vendor CPU template, but it is not an
    axis editor by itself.  A concrete axis connector must be visible below
    it before page controls such as HomingVelocity can be resolved.

    Measured 2026-09-19 (AM600 + AM600_EtherCAT_Slave, InoProShop V1.10.0.3):
    after a successful vendor.softmotion.axis.add the axis exists as
    ``Device/ETHERCAT/<slave>/Axis`` (type 1027, id FFFF 0001) while the pool
    node's own children stay EMPTY - the pool is a view placeholder, so a
    children-only gate told callers "axis_pool_empty" and invited them to add
    the same axis again.  The authoritative inventory is the type-1027 device
    scan below.
    """
    _require_project()
    target = _text(req.get("target") or "Device/SoftMotion General Axis Pool")
    tree = project_tree(12).get("tree", [])

    def find(nodes):
        for node in nodes or []:
            if _text(node.get("path")) == target:
                return node
            found = find(node.get("children", []))
            if found is not None:
                return found
        return None

    # project.tree carries the object-type GUID, not the device identity, so the
    # authoritative axis scan has to use device.tree (which resolves
    # device_identification for every device node).
    axes = []
    axes_error = None
    try:
        for item in device_tree().get("devices") or []:
            identity = item.get("deviceId") or {}
            try:
                if int(identity.get("type")) == 1027:
                    axes.append({"name": item.get("name"),
                                 "path": item.get("path"),
                                 "deviceId": identity})
            except Exception:
                continue
    except Exception as exc:
        axes_error = repr(exc)
    node = find(tree)
    if node is None and not axes:
        return {
            "target": target,
            "status": "axis_pool_missing",
            "errorCode": "axis_pool_missing",
            "axisWriteAuthorized": False,
            "axes": [],
            "mutatedProject": False,
        }
    if axes:
        for axis in axes:
            try:
                axis["nativeBinding"] = _softmotion_axis_binding(axis["path"])
            except Exception as exc:
                axis["nativeBinding"] = {"status": "unavailable", "error": repr(exc),
                                         "engineeringBindingVerified": False}
        return {
            "target": target,
            "guid": node.get("guid") if node is not None else None,
            "poolNodePresent": node is not None,
            "poolChildCount": len((node or {}).get("children") or []),
            "axes": axes,
            "axisCount": len(axes),
            "axisScanError": axes_error,
            "status": "axis_present",
            "errorCode": None,
            "axisWriteAuthorized": True,
            "mutatedProject": False,
            "boundary": ("The SoftMotion pool node is a view placeholder: the "
                         "axes hang off their EtherCAT slaves (type 1027), so "
                         "an empty pool child list is NOT evidence that no "
                         "axis exists. Address an axis by the exact path "
                         "reported in axes[]."),
            "next": ("inspect axes[].nativeBinding first. For status=missing, preserve the existing "
                     "axis and use inoproshop_softmotion_axis_repair_binding with its exact path "
                     "and an unused parent connectorId; do not create a duplicate axis. Then "
                     "match each requested axis to the actual slave/connector "
                     "in axes[] and reuse an existing matching axis. A non-empty "
                     "project inventory does not mean all requested axes exist; "
                     "add missing axes on compatible slaves with unused "
                     "connectors via vendor.softmotion.axis.add. Avoid creating "
                     "a duplicate of an already matching axis. Verify IEC "
                     "binding and feedback separately from device presence"),
        }
    if node is None:
        return {
            "target": target,
            "status": "axis_pool_missing",
            "errorCode": "axis_pool_missing",
            "axisWriteAuthorized": False,
            "axes": [],
            "mutatedProject": False,
        }
    children = node.get("children") or []
    return {
        "target": target,
        "guid": node.get("guid"),
        "childCount": len(children),
        "children": [{"name": item.get("name"), "path": item.get("path"),
                       "type": item.get("type")} for item in children],
        "axes": [],
        "axisCount": 0,
        "status": "axis_pool_empty_no_axis_connector",
        "errorCode": "axis_pool_empty_no_axis_connector",
        "axisWriteAuthorized": False,
        "mutatedProject": False,
        "next": ("probe the concrete axis editor and its controls" if children
                  else "add a real vendor axis connector, then repeat this preflight"),
    }


def _softmotion_connector_xml(connector_id, device_id="FFFF 0001"):
    """Build the exact generic CiA402 connector used by InoProShop.

    This mirrors AddInoCiA402Connector/ClassHelper.CreateConnector from the
    installed plugin.  Keeping it as a pure helper makes the contract
    testable without starting the IDE and prevents callers from hand-writing
    subtly different connector XML.
    """
    if build_cia402_connector_xml is None:
        raise OperationError("SoftMotion contract module is unavailable",
                             "softmotion_contract_unavailable")
    try:
        return build_cia402_connector_xml(connector_id, device_id)
    except (TypeError, ValueError) as exc:
        raise OperationError(_text(exc), "invalid_argument")


def _native_connector_summary(connector):
    if connector is None:
        return None
    result = {"runtimeType": _text(connector.GetType().FullName)}
    for key, names in (
        ("connectorId", ("connector_id", "get_ConnectorId", "ConnectorId")),
        ("connectorRole", ("connector_role", "get_ConnectorRole", "ConnectorRole")),
        ("moduleType", ("module_type", "get_ModuleType", "ModuleType")),
        ("interface", ("interface", "get_Interface", "Interface")),
    ):
        value = _get_member(connector, names[0], names[1])
        if value is None and len(names) > 2:
            value = _get_member(connector, names[2])
        if value is not None:
            result[key] = _json_safe(value)
    return result


def _native_connector_list(device_object):
    connectors = _get_member(device_object, "connectors", "get_Connectors")
    if connectors is None:
        connectors = _get_member(device_object, "Connectors")
    try:
        return list(connectors) if connectors is not None else []
    except Exception:
        return []


def _native_connector_id(connector):
    value = _get_member(connector, "connector_id", "get_ConnectorId")
    if value is None:
        value = _get_member(connector, "ConnectorId")
    try:
        return int(value)
    except Exception:
        return None


def _new_softmotion_axis_tree_matches(before_tree, after_tree, target_path,
                                      axis_device_id):
    """Return exact newly materialized generic Axis children."""
    before_paths = set(
        _text(item.get("path"))
        for item in (before_tree.get("devices") or [])
    )
    target_prefix = _text(target_path).rstrip("/") + "/"
    result = []
    for item in after_tree.get("devices") or []:
        item_path = _text(item.get("path"))
        identity = item.get("deviceId") or {}
        try:
            item_type = int(identity.get("type"))
        except Exception:
            item_type = None
        if (
            item_path.startswith(target_prefix)
            and item_path not in before_paths
            and item_type == 1027
            and _text(identity.get("id")).lower() ==
                _text(axis_device_id).lower()
            and _text(identity.get("version")) == "4.0.0.0"
        ):
            result.append(item)
    return result


def _softmotion_axis_binding(target):
    """Read the parent slot's exact module GUID, not just the visible axis row."""
    target = _text(target).strip()
    if "/" not in target:
        raise OperationError("an exact axis device-tree path is required", "invalid_argument")
    parent = target.rsplit("/", 1)[0]
    mgr, axis_meta, axis, axis_binding = _native_device_object(target, "read")
    mgr, parent_meta, slave, parent_binding = _native_device_object(parent, "read")
    if axis_binding.get("path") != target or parent_binding.get("path") != parent:
        raise OperationError("axis and parent paths must resolve exactly", "softmotion_axis_path_mismatch")
    if int(axis.DeviceIdentification.Type) != 1027 or int(slave.DeviceIdentification.Type) != 65:
        raise OperationError("expected a native SoftMotion axis beneath an EtherCAT slave",
                             "softmotion_axis_binding_scope_unverified")
    if axis_meta.ParentObjectGuid != parent_meta.ObjectGuid:
        raise OperationError("axis native parent differs from its device-tree parent",
                             "softmotion_axis_parent_mismatch")
    # Do not turn an unreadable collection into evidence of a missing link.
    connectors = list(slave.Connectors)
    axis_guid = _text(axis_meta.ObjectGuid).lower()
    links = []
    used = []
    for connector in connectors:
        cid = int(connector.ConnectorId)
        used.append(cid)
        for index, adapter in enumerate(list(connector.Adapters)):
            modules = [_text(guid).lower() for guid in list(adapter.Modules)]
            if axis_guid in modules:
                links.append({"connectorId": cid, "adapterIndex": index,
                              "interface": _text(connector.Interface),
                              "moduleGuids": modules})
    next_id = 1000
    while next_id in used:
        next_id += 1
    return {"target": target, "parent": parent, "axisGuid": axis_guid,
            "status": "linked" if len(links) == 1 else "missing" if not links else "ambiguous",
            "links": links, "usedConnectorIds": sorted(used),
            "nextUnusedConnectorId": next_id if next_id <= 2147483647 else None,
            "engineeringBindingVerified": len(links) == 1,
            "iecSymbolVerified": False, "motionVerified": False}


def vendor_softmotion_axis_repair_binding(req):
    """Attach an existing orphan axis to one empty native parent slot."""
    _require_current_disposable_project(req, "vendor.softmotion.axis.repair_binding")
    if req.get("confirm") != "repair_axis_binding":
        raise OperationError("confirm=repair_axis_binding is required", "confirmation_required")
    target = _text(req.get("target")).strip()
    cid = req.get("connectorId")
    try:
        integer_types = (int, long)
    except NameError:
        integer_types = (int,)
    if isinstance(cid, bool) or not isinstance(cid, integer_types) or not 1000 <= cid <= 2147483647:
        raise OperationError("connectorId must be an unused integer >=1000", "invalid_argument",
                             {"mutatedProject": False, "field": "connectorId"})
    before = _softmotion_axis_binding(target)
    result = {"target": target, "parent": before["parent"], "connectorId": cid,
              "axisGuid": before["axisGuid"], "before": before, "mutatedProject": False,
              "newObjectCreated": False, "persistenceVerified": False,
              "iecSymbolVerified": False, "motionVerified": False}
    if before["status"] == "linked":
        result.update(status="already_bound", engineeringBindingVerified=True, after=before)
        return result
    if before["status"] != "missing":
        raise OperationError("axis has ambiguous parent module links; no repair attempted",
                             "softmotion_axis_binding_ambiguous", result)
    if cid in before["usedConnectorIds"]:
        raise OperationError("connectorId is already in use; choose the reported unused id",
                             "softmotion_axis_connector_exists", result)
    import System
    import System.Xml
    from System.Reflection import BindingFlags
    mgr, axis_meta, axis, axis_binding = _native_device_object(target, "read")
    mgr, parent_meta, slave, parent_binding = _native_device_object(before["parent"], "read")
    identity = axis.DeviceIdentification
    if (_text(identity.Id).upper() not in ("0000 0001", "FFFF 0001") or
            _text(identity.Version) != "4.0.0.0"):
        raise OperationError("this native axis identity has not been verified for binding repair",
                             "softmotion_axis_binding_scope_unverified", result)
    matching_children = [c for c in list(axis.Connectors)
                         if _text(c.Interface) == "Common.SoftMotion.EtherCAT.DSP402"
                         and int(c.ConnectorRole) == 1]
    if len(matching_children) != 1:
        raise OperationError("axis has no unique native CiA402 child connector",
                             "softmotion_axis_child_connector_unverified", result)
    connectors = list(slave.Connectors)
    if not connectors:
        raise OperationError("parent has no native connector type to construct a slot",
                             "softmotion_axis_binding_api_unavailable", result)
    xml = System.Xml.XmlDocument()
    # Empty slot: NO DefaultModule, so no duplicate axis or default parameters.
    xml.LoadXml('<Connector connectorId="%s" explicit="false" hostpath="1" '
                'interface="Common.SoftMotion.EtherCAT.DSP402" moduleType="1279" '
                'role="parent"><Slot allowEmpty="true" count="1" /></Connector>' % cid)
    flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic
    constructors = [c for c in connectors[0].GetType().GetConstructors(flags)
                    if len(c.GetParameters()) == 4 and
                    _text(c.GetParameters()[0].ParameterType.FullName) == "System.Xml.XmlNode"]
    if len(constructors) != 1:
        raise OperationError("native Connector constructor differs from the verified signature",
                             "softmotion_axis_binding_api_unavailable", result)
    connector = constructors[0].Invoke(System.Array[System.Object](
        [xml.DocumentElement, slave.TypeDefinitions, slave.DeviceIdentification, System.Boolean(False)]))
    adapters = list(connector.Adapters)
    if len(adapters) != 1:
        raise OperationError("new connector does not expose one empty slot adapter",
                             "softmotion_axis_binding_api_unavailable", result)
    stub = mgr.GetMetaObjectStub(int(parent_binding["projectHandle"]), axis_meta.ObjectGuid)
    adapters[0].AddModule(0, stub)
    if [_text(g).lower() for g in list(adapters[0].Modules)] != [before["axisGuid"]]:
        raise OperationError("native slot did not accept the existing axis GUID",
                             "softmotion_axis_binding_slot_rejected", result)
    # Re-read just before crossing the mutation boundary. Existing topology
    # must still match the snapshot used to construct this detached connector.
    current = _softmotion_axis_binding(target)
    if current != before:
        raise OperationError("axis topology changed during repair; inspect again",
                             "softmotion_axis_binding_changed", result)
    mgr, modify_meta, modify_native, modify_binding = _native_device_object(before["parent"], "modify")
    result.update(mutationAttempted=True, mutatedProject=True, processDiscardRequired=True)
    try:
        connector.Device = modify_native
        # Connectors returns a filtered temporary list. This owns storage.
        modify_native.ConnectorsWithGroups.Add(connector)
        mgr.SetObject(modify_meta, True, None)
        after = _softmotion_axis_binding(target)
        result["after"] = after
        if (after["status"] != "linked" or after["axisGuid"] != before["axisGuid"] or
                after["links"][0]["connectorId"] != cid):
            raise OperationError("committed parent slot does not retain the exact axis GUID",
                                 "softmotion_axis_binding_readback_mismatch", result)
    except OperationError:
        raise
    except Exception as exc:
        raise OperationError("native binding repair failed: " + repr(exc),
                             "softmotion_axis_binding_commit_failed", result)
    result.update(status="committed_same_process", engineeringBindingVerified=True,
                  processDiscardRequired=False)
    result["nextRequired"] = ["save, close and reopen in a fresh process; repeat axis preflight",
                              "compile and read the real axis IEC members online",
                              "verify drive configuration and physical motion separately"]
    return result


def vendor_softmotion_axis_add(req):
    """Add one vendor CiA402 connector to a real EtherCAT slave.

    This is deliberately a disposable-project experiment.  It follows the
    vendor command's CallFunction("AddConnector", XmlDocument) path and the
    subsequent ObjectMgr/editor-helper commit; generic ``device.add`` is not
    interchangeable with this operation.
    """
    _require_project()
    _require_current_disposable_project(req, "vendor.softmotion.axis.add")
    if _text(req.get("confirm")) != "add_softmotion_axis":
        raise OperationError(
            "vendor.softmotion.axis.add requires confirm=add_softmotion_axis",
            "confirmation_required",
        )
    target = req.get("target") or req.get("path") or req.get("device")
    if not target:
        raise OperationError("target EtherCAT slave is required", "invalid_argument")

    import System
    import System.Xml

    script_obj, object_path = find_project_object(target)
    object_mgr, meta_read, native_read, binding = _native_device_object(target, "read")
    identity = _get_member(native_read, "device_identification", "get_DeviceIdentification")
    if identity is None:
        identity = _get_member(native_read, "DeviceIdentification")
    identity_type = _json_safe(_get_member(identity, "type", "get_Type")) if identity is not None else None
    if identity_type is None and identity is not None:
        identity_type = _json_safe(_get_member(identity, "Type"))
    if int(identity_type or 0) != 65:
        raise OperationError(
            "SoftMotion CiA402 axis requires an EtherCAT slave target",
            "softmotion_axis_target_not_ethercat_slave",
            {"target": object_path, "deviceType": identity_type,
             "binding": binding},
        )

    existing = _native_connector_list(native_read)
    generic = []
    for connector in existing:
        module_type = _get_member(connector, "module_type", "get_ModuleType")
        if module_type is None:
            module_type = _get_member(connector, "ModuleType")
        role = _get_member(connector, "connector_role", "get_ConnectorRole")
        if role is None:
            role = _get_member(connector, "ConnectorRole")
        try:
            if int(role) == 0 and int(module_type) == 1279:
                generic.append(connector)
        except Exception:
            pass
    connector_id = req.get("connectorId")
    if connector_id is None:
        raise OperationError(
            "connectorId is required; automatic allocation is not part of the "
            "verified public contract",
            "invalid_argument",
            {"path": "connectorId", "expected": "unused integer >= 1000"},
        )
    try:
        connector_id = int(connector_id)
    except Exception:
        raise OperationError("connectorId must be an integer", "invalid_argument")
    if connector_id < 1000:
        raise OperationError("connectorId must be >= 1000", "invalid_argument")
    if any(_native_connector_id(item) == connector_id for item in generic):
        raise OperationError(
            "connectorId is already used by a generic CiA402 connector",
            "softmotion_axis_connector_exists",
            {"target": object_path, "connectorId": connector_id},
        )

    # The only fresh-process-verified creation identity is the generic
    # CiA402 Axis FFFF 0001. Keep other vendor-specific identities out of the
    # public route until they have their own closure evidence.
    slave_id = _text(_get_member(identity, "id", "get_Id") if identity is not None else "")
    if not slave_id and identity is not None:
        slave_id = _text(_get_member(identity, "Id"))
    device_id = _text(req.get("axisDeviceId")).strip()
    if device_id != "FFFF 0001":
        raise OperationError(
            "axisDeviceId must equal the verified generic CiA402 identity "
            "FFFF 0001",
            "softmotion_axis_identity_unverified",
            {"path": "axisDeviceId", "expected": "FFFF 0001",
             "actual": device_id},
        )
    connector_xml = _softmotion_connector_xml(connector_id, device_id)
    result = {
        "target": object_path,
        "binding": binding,
        "before": [_native_connector_summary(item) for item in existing],
        "inputs": {
            "connectorId": connector_id,
            "axisDeviceId": device_id,
            "sourceSlaveIdentity": {"type": identity_type, "id": slave_id},
            "moduleType": 1279,
            "deviceType": 1027,
            "interface": "Common.SoftMotion.EtherCAT.DSP402",
            "version": "4.0.0.0",
        },
        "connectorXml": connector_xml,
        "mutatedProject": False,
    }
    # Some InoProShop builds apply AddConnector to the native project model,
    # but do not refresh the connector collection exposed by the current
    # DeviceObject wrapper.  Capture the device tree before the call so a
    # new type=1027 child and its parent module GUID can both be verified.
    # A tree row alone must never be accepted as a complete binding.
    try:
        tree_before_call = device_tree()
        result["treeBeforeCall"] = tree_before_call
    except Exception as exc:
        tree_before_call = {"devices": []}
        result["treeBeforeCallError"] = repr(exc)

    # The vendor command calls AddConnector on the read object, then obtains
    # the modify lock from that native object's MetaObject.  The ScriptEngine
    # wrapper GUID is not interchangeable with this native MetaObject.
    provider = native_read
    native_meta = _get_member(native_read, "meta_object", "get_MetaObject")
    if native_meta is None:
        native_meta = _get_member(native_read, "MetaObject")
    if native_meta is None:
        raise OperationError("native EtherCAT slave MetaObject is unavailable",
                             "softmotion_native_meta_unavailable", result)
    try:
        available = bool(provider.IsFunctionAvailable("AddConnector"))
    except Exception as exc:
        available = False
        result["isFunctionAvailableError"] = repr(exc)
    if not available:
        raise OperationError(
            "selected EtherCAT slave does not expose AddConnector",
            "softmotion_add_connector_unavailable", result,
        )
    xml_document = System.Xml.XmlDocument()
    xml_document.LoadXml(connector_xml)
    result["mutationAttempted"] = True
    result["mutatedProject"] = True
    result["mutationBoundaryCrossed"] = True
    result["processDiscardRequired"] = True
    try:
        provider.CallFunction("AddConnector", xml_document)
        result["callFunction"] = {"name": "AddConnector", "ok": True}
        # The provider can materialize a project child before the wrapper or
        # ObjectMgr readback refreshes. From this point, any failure must
        # discard the disposable process/fixture instead of claiming no write.
        provider_connectors = _native_connector_list(provider)
        result["providerConnectorsAfterCall"] = [
            _native_connector_summary(item) for item in provider_connectors
        ]
    except Exception as exc:
        result["callFunction"] = {"name": "AddConnector", "ok": False, "error": repr(exc)}
        raise OperationError("vendor AddConnector failed: " + repr(exc),
                             "softmotion_add_connector_failed", result)

    try:
        # CallFunction commits through ObjectMgr and can replace the parent.
        # Locking its pre-call MetaObject can restore the old connector list
        # and leave a visible axis disconnected from the compiler's topology.
        object_mgr, fresh_meta, fresh_native, fresh_binding = _native_device_object(target, "read")
        meta_modify = object_mgr.GetObjectToModify(fresh_meta)
        result["postCallBinding"] = fresh_binding
    except Exception as exc:
        raise OperationError(
            "ObjectMgr.GetObjectToModify(native MetaObject) failed",
            "softmotion_modify_binding_failed",
            dict(result, error=repr(exc)),
        )
    try:
        native_modify = meta_modify.Object if meta_modify is not None else None
    except Exception:
        native_modify = _get_member(meta_modify, "object", "get_Object") if meta_modify is not None else None
    if native_modify is None:
        raise OperationError("modified EtherCAT slave object is unavailable",
                             "softmotion_modify_object_unavailable", result)
    result["modifyBinding"] = dict(binding, access="modify", nativeMetaObject=True)
    modified_connectors = _native_connector_list(native_modify)
    result["modifiedConnectors"] = [
        _native_connector_summary(item) for item in modified_connectors
    ]
    # Some InoProShop builds materialize the child object immediately but
    # expose the refreshed connector collection only through a fresh native
    # read.  The vendor AxisAdderHelper follows the same native MetaObject
    # route, so reacquire the object before declaring AddConnector unusable.
    if not modified_connectors and provider_connectors:
        modified_connectors = provider_connectors
        result["connectorRefresh"] = {
            "ok": True,
            "binding": "same_provider_after_CallFunction",
            "count": len(provider_connectors),
        }
    if not modified_connectors:
        try:
            rebound_mgr, rebound_meta, rebound_native, rebound_binding = (
                _native_device_object(target, "read")
            )
            refreshed = _native_connector_list(rebound_native)
            if refreshed:
                modified_connectors = refreshed
                result["modifiedConnectors"] = [
                    _native_connector_summary(item) for item in refreshed
                ]
                result["connectorRefresh"] = {
                    "ok": True,
                    "binding": rebound_binding,
                    "count": len(refreshed),
                }
        except Exception as exc:
            result["connectorRefresh"] = {"ok": False, "error": repr(exc)}
    selected = None
    for connector in modified_connectors:
        if _native_connector_id(connector) == connector_id:
            selected = connector
            break
    if selected is None:
        try:
            tree_after_call = device_tree()
        except Exception as exc:
            tree_after_call = {"devices": []}
            result["treeAfterCallError"] = repr(exc)
        tree_candidates = _new_softmotion_axis_tree_matches(
            tree_before_call, tree_after_call, object_path, device_id
        )
        # A tree row is not a native module binding. Keep this failure
        # explicit even if the vendor already created the child object.
        result["treeAfterCall"] = tree_after_call
        result["connectorPresentAfterCall"] = False
        result["nextRequired"] = [
            "save diagnostic evidence and discard this disposable attempt",
            "inspect the parent connector and exact axis module GUID before retrying",
        ]
        raise OperationError(
            "AddConnector returned but the new connector was not readable",
            "softmotion_connector_not_readable",
            dict(result, treeCandidates=tree_candidates),
        )

    helper_state = {"attempted": False, "saved": False}
    try:
        iterator = selected.CreateModuleIterator()
        helper_state["attempted"] = True
        if not iterator.MoveToFirstChild():
            raise RuntimeError("new connector has no child module")
        current = iterator.Current
        helper = current.CreateEditorHelper()
        if helper is None:
            raise RuntimeError("child module CreateEditorHelper returned null")
        try:
            connector_for_modify = helper.GetConnector(True)
            if connector_for_modify is None:
                raise RuntimeError("CreateEditorHelper.GetConnector(true) returned null")
            parameter_set = _get_member(connector_for_modify, "host_parameter_set", "get_HostParameterSet")
            if parameter_set is None:
                parameter_set = _get_member(connector_for_modify, "HostParameterSet")
            parameter = parameter_set.GetParameter(6000) if parameter_set is not None else None
            if parameter is None:
                raise RuntimeError("verified CiA402 connector must expose logical-device parameter 6000")
            parameter.Value = str(connector_id - 1000)
            if _text(_native_element_value(parameter)) != str(connector_id - 1000):
                raise RuntimeError("logical-device parameter 6000 did not retain the channel index")
            helper.Save(True, None)
            helper_state["saved"] = True
            helper_state["channelParameter6000"] = _native_element_value(parameter) if parameter is not None else None
        finally:
            try:
                helper.Dispose()
            except Exception:
                pass
    except Exception as exc:
        helper_state["error"] = repr(exc)
        result["editorHelper"] = helper_state
        raise OperationError("vendor connector editor-helper commit failed: " + repr(exc),
                             "softmotion_connector_helper_commit_failed", result)
    result["editorHelper"] = helper_state
    try:
        commit_return = object_mgr.SetObject(meta_modify, True, None)
        result["objectManagerCommit"] = {"ok": True, "return": _json_safe(commit_return)}
    except Exception as exc:
        result["objectManagerCommit"] = {"ok": False, "error": repr(exc)}
        raise OperationError("ObjectMgr.SetObject failed: " + repr(exc),
                             "softmotion_connector_commit_failed", result)
    rebound_mgr, _rebound_meta, rebound_native, rebound_binding = _native_device_object(target, "read")
    after = _native_connector_list(rebound_native)
    result["after"] = [_native_connector_summary(item) for item in after]
    result["reboundBinding"] = rebound_binding
    result["connectorPresentAfterCommit"] = any(
        _native_connector_id(item) == connector_id for item in after
    )
    if not result["connectorPresentAfterCommit"]:
        raise OperationError(
            "connector id was not retained after ObjectMgr commit",
            "softmotion_connector_readback_mismatch", result,
        )
    try:
        tree_after_commit = device_tree()
    except Exception as exc:
        raise OperationError(
            "SoftMotion axis tree after-read failed",
            "softmotion_axis_tree_readback_failed",
            dict(result, error=repr(exc)),
        )
    tree_candidates = _new_softmotion_axis_tree_matches(
        tree_before_call, tree_after_commit, object_path, device_id
    )
    if len(tree_candidates) != 1:
        raise OperationError(
            "ObjectMgr commit did not produce exactly one requested Axis child",
            "softmotion_axis_tree_readback_mismatch",
            dict(result, treeAfterCommit=tree_after_commit,
                 treeCandidates=tree_candidates),
        )
    axis_binding = _softmotion_axis_binding(tree_candidates[0].get("path"))
    result["axisNativeBinding"] = axis_binding
    if (axis_binding["status"] != "linked" or
            axis_binding["links"][0]["connectorId"] != connector_id):
        raise OperationError("new axis is visible but is not linked to the requested native slot",
                             "softmotion_axis_binding_readback_mismatch", result)
    _, _, committed_axis, _ = _native_device_object(tree_candidates[0].get("path"), "read")
    child_connectors = [c for c in list(committed_axis.Connectors)
                        if int(c.ConnectorRole) == 1 and
                        _text(c.Interface) == "Common.SoftMotion.EtherCAT.DSP402"]
    channel_value = None
    if len(child_connectors) == 1:
        channel_parameter = child_connectors[0].HostParameterSet.GetParameter(6000)
        if channel_parameter is not None:
            channel_value = _text(_native_element_value(channel_parameter))
    result["channelParameter6000AfterCommit"] = channel_value
    if channel_value != str(connector_id - 1000):
        raise OperationError("committed axis logical-device parameter does not match the requested connector",
                             "softmotion_axis_channel_readback_mismatch", result)
    result["treeAfterCommit"] = tree_after_commit
    result["treeIdentityAfterCommit"] = tree_candidates[0]
    result["readback"] = {
        "path": tree_candidates[0].get("path"),
        "axisDeviceType": 1027,
        "axisDeviceId": device_id,
        "version": "4.0.0.0",
        "newTreeObject": True,
        "connectorId": connector_id,
    }
    result["exactReadback"] = True
    result["mutatedProject"] = True
    result["processDiscardRequired"] = False
    result["status"] = "committed_same_process"
    result["persistenceVerified"] = False
    result["claims"] = {
        "targetEthercatSlave": True,
        "axisIdentityReadback": True,
        "newTreeObject": True,
        "connectorIdentityReadback": True,
    }
    result["nextRequired"] = [
        "device.tree and UI screenshot must show the new axis",
        "project.save, close, fresh-process reopen and connector readback",
        "open concrete AxisEditor/ParameterSettingsPage and verify controls",
        "second compile with precompile/compiler/library diagnostics",
    ]
    return result


def _parameter_value(value, name, default=None):
    return _json_safe(_get_member(value, name, "get_" + name, default))


def _parameter_summary(value, depth=0, max_depth=3):
    """Return UI/device parameter metadata without changing the value."""
    try:
        available_names = set(_text(name) for name in dir(value))
    except Exception:
        available_names = set()
    value_fields = set(("value", "default_value", "min_value", "max_value"))
    result = {
        "id": _parameter_value(value, "id"),
        "name": _parameter_value(value, "name", ""),
        "identifier": _parameter_value(value, "identifier", ""),
        "visibleName": _parameter_value(value, "visible_name", ""),
        "description": _parameter_value(value, "description", ""),
        "unit": _parameter_value(value, "unit", ""),
        "value": _parameter_value(value, "value", ""),
        "defaultValue": _parameter_value(value, "default_value", ""),
        "minValue": _parameter_value(value, "min_value", ""),
        "maxValue": _parameter_value(value, "max_value", ""),
        "baseType": _parameter_value(value, "base_type", ""),
        "type": _parameter_value(value, "type_string", ""),
        "section": _parameter_value(value, "section", ""),
        "iecType": _parameter_value(value, "iec_type", ""),
        "paramType": _parameter_value(value, "param_type", ""),
        "downloadedWithIoConfig": _parameter_value(value, "downloaded_with_ioconfig", None),
        "channelType": _parameter_value(value, "channel_type", ""),
        "diagnosticType": _parameter_value(value, "diagnostic_type", ""),
        "isRangeType": bool(_get_member(value, "is_range_type", "get_is_range_type", False)),
        "isEnumeration": bool(_get_member(value, "is_enumeration", "get_is_enumeration", False)),
        "hasSubElements": bool(_get_member(value, "has_sub_elements", "get_has_sub_elements", False)),
        "valueReadbackSupported": bool(value_fields.intersection(available_names)),
        "availableFields": sorted(available_names.intersection(set((
            "id", "name", "identifier", "visible_name", "description", "unit",
            "value", "default_value", "min_value", "max_value", "type_string",
            "section", "iec_type", "param_type", "online_access_rights",
            "offline_access_rights", "downloaded_with_ioconfig", "channel_type",
            "diagnostic_type", "sub_elements")))) ,
    }
    # ScriptEngine's IScriptDeviceParameter exposes these rights directly;
    # older DeviceObject adapters expose get_access_right(bool).
    for label, member in (("online", "online_access_rights"),
                          ("offline", "offline_access_rights")):
        access = _get_member(value, member, "get_" + member)
        if access is not None:
            result["access" + label.capitalize()] = _json_safe(access)
    if not any(key in result for key in ("accessOnline", "accessOffline")):
        for online, label in ((True, "online"), (False, "offline")):
            try:
                result["access" + label.capitalize()] = _json_safe(value.get_access_right(online))
            except Exception as exc:
                result.setdefault("accessErrors", []).append({"mode": label, "error": repr(exc)})
    if depth < max_depth:
        subelements = _get_member(value, "sub_elements", "get_sub_elements")
        if subelements is not None:
            try:
                result["subElements"] = [
                    _parameter_summary(item, depth + 1, max_depth)
                    for item in list(subelements)
                ]
            except Exception as exc:
                result["subElementsError"] = repr(exc)
    return result


def device_parameters_probe(req):
    """Inspect the parameter model behind a device editor page.

    Different CODESYS generations expose the same model under slightly
    different ScriptEngine member names. Report every binding attempt so a
    missing UI adapter is an explicit result rather than an empty success.
    """
    _require_project()
    target = req.get("target") or req.get("path") or req.get("device")
    if not target:
        raise OperationError("device.parameters.probe requires target", "invalid_argument")
    obj, object_path = find_project_object(target)
    attempts = []
    try:
        member_candidates = [
            _text(name) for name in dir(obj)
            if any(token in _text(name).lower() for token in
                   ("param", "config", "property", "editor", "device"))
        ][:200]
    except Exception as exc:
        member_candidates = ["<reflection failed: %s>" % repr(exc)]
    runtime_type = None
    runtime_properties = []
    runtime_methods = []
    try:
        clr_type = obj.GetType()
        runtime_type = _text(clr_type.FullName)
        runtime_properties = [
            _text(item.Name) for item in clr_type.GetProperties()
            if any(token in _text(item.Name).lower() for token in
                   ("param", "config", "property", "editor", "device"))
        ][:200]
        runtime_methods = [
            _text(item.Name) for item in clr_type.GetMethods()
            if any(token in _text(item.Name).lower() for token in
                   ("param", "config", "property", "editor", "device"))
        ][:200]
    except Exception as exc:
        runtime_type = "<reflection failed: %s>" % repr(exc)
    parameter_set = None
    for name, getter in (
        ("device_parameters", "get_device_parameters"),
        ("device_parameter_set", "get_device_parameter_set"),
        ("parameter_set", "get_parameter_set"),
        ("parameters", "get_parameters"),
    ):
        try:
            value = _get_member(obj, name, getter)
            attempts.append({"binding": name, "available": value is not None})
            if value is not None:
                parameter_set = value
                break
        except Exception as exc:
            attempts.append({"binding": name, "available": False, "error": repr(exc)})
    if parameter_set is None:
        return {
            "target": object_path,
            "parameterModel": "unavailable",
            "parameterCount": 0,
            "parameters": [],
            "attempts": attempts,
            "memberCandidates": member_candidates,
            "runtimeType": runtime_type,
            "runtimeProperties": runtime_properties,
            "runtimeMethods": runtime_methods,
            "mutatedProject": False,
        }
    try:
        values = list(parameter_set)
    except Exception as exc:
        raise OperationError(
            "device parameter set is not enumerable: " + repr(exc),
            "parameter_enumeration_failed",
            {"target": object_path, "attempts": attempts},
        )
    return {
        "target": object_path,
        "parameterModel": _text(type(parameter_set)),
        "parameterCount": len(values),
        "parameters": [_parameter_summary(value) for value in values],
        "attempts": attempts,
        "memberCandidates": member_candidates,
        "runtimeType": runtime_type,
        "runtimeProperties": runtime_properties,
        "runtimeMethods": runtime_methods,
        "mutatedProject": False,
        "writeSupport": "not_attempted",
    }


def device_io_probe(req):
    """Read-only discovery of IO/mapping members exposed by a project object.

    InoProShop exposes different device editors through different managed
    types. This probe deliberately does not guess a mapping API or mutate a
    project; it reports object children and reflection candidates so a later
    writer can be implemented against observed bindings.
    """
    _require_project()
    target = req.get("target") or req.get("path") or req.get("device") or "Device"
    obj, object_path = find_project_object(target)
    token_text = ("io", "channel", "mapping", "address", "input", "output",
                  "variable", "parameter", "slot", "bit", "byte")

    def names_from(value, clr=False):
        result = []
        try:
            if clr:
                typ = value.GetType()
                properties = [item.Name for item in typ.GetProperties()]
                methods = [item.Name for item in typ.GetMethods()]
                result = properties + methods
            else:
                result = list(dir(value))
        except Exception:
            return []
        return sorted(set(_text(name) for name in result
                          if any(token in _text(name).lower() for token in token_text)))[:300]

    def interfaces_from(value):
        result = []
        try:
            for interface in value.GetType().GetInterfaces():
                full_name = _text(interface.FullName)
                lowered = full_name.lower()
                if any(token in lowered for token in ("io", "address", "mapping", "logical", "variable", "provider", "device")):
                    result.append({
                        "name": full_name,
                        "methods": sorted(set(_text(method.Name) for method in interface.GetMethods())),
                    })
        except Exception as exc:
            return [{"name": "<interface reflection failed>", "error": repr(exc)}]
        return result

    candidates = {
        "pythonMembers": names_from(obj),
        "runtimeMembers": names_from(obj, True),
        "interfaces": interfaces_from(obj),
    }
    extender = _get_member(obj, "Extender", "get_Extender")
    extender_info = None
    if extender is not None:
        try:
            extender_info = {
                "runtimeType": _text(extender.GetType().FullName),
                "pythonMembers": names_from(extender),
                "runtimeMembers": names_from(extender, True),
                "interfaces": interfaces_from(extender),
            }
        except Exception as exc:
            extender_info = {"error": repr(exc)}
    values = {}
    for name in candidates["pythonMembers"]:
        try:
            value = getattr(obj, name)
            if not _is_callable(value):
                values[name] = _json_safe(value)
        except Exception as exc:
            values[name] = {"readError": repr(exc)}

    children = []
    for child in _children(obj):
        child_name = _object_name(child)
        child_path = object_path + "/" + child_name if child_name else object_path
        entry = _object_summary(child, child_path)
        entry["ioCandidates"] = {
            "pythonMembers": names_from(child),
            "runtimeMembers": names_from(child, True),
            "interfaces": interfaces_from(child),
        }
        children.append(entry)

    return {
        "target": object_path,
        "runtimeType": _text(obj.GetType().FullName) if hasattr(obj, "GetType") else _text(type(obj)),
        "readOnly": True,
        "mutatedProject": False,
        "mappingWriteSupport": "not_attempted",
        "parameterModel": "reflection_candidates",
        "candidates": candidates,
        "extender": extender_info,
        "values": values,
        "children": children,
        "childCount": len(children),
        "status": "observed" if (values or children or candidates["runtimeMembers"]) else "unavailable",
        "nextRequired": "implement a vendor-specific mapping adapter only after a concrete writable binding is observed",
    }


def _native_device_object(target, access="read"):
    """Resolve a vendor device through the ObjectMgr used by its editor."""
    import System
    script_object, path = find_project_object(target)
    guid = _get_member(script_object, "guid", "get_guid")
    if not guid:
        raise OperationError("device tree object has no GUID", "device_guid_unavailable", {"target": target})
    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            pass
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable", "project_handle_unavailable")
    object_mgr, probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable", "object_manager_unavailable", {"probe": probe})
    getter = object_mgr.GetObjectToModify if access == "modify" else object_mgr.GetObjectToRead
    meta = getter(int(handle), System.Guid(_text(guid)))
    try:
        native = meta.Object if meta is not None else None
    except Exception:
        native = _get_member(meta, "object", "get_Object") if meta is not None else None
    # ScriptEngine wraps vendor device nodes and assigns a different GUID.  The
    # UI editor resolves the actual IDeviceObject from ObjectMgr; recover that
    # object by its unique native name and connector-bearing runtime shape.
    native_guid = _text(guid)
    try:
        native_connectors = native.Connectors if native is not None else None
    except Exception:
        native_connectors = _get_member(native, "connectors", "get_Connectors") if native is not None else None
    if native is None or native_connectors is None:
        wanted_name = _object_name(script_object).lower()
        candidates = []
        try:
            for candidate_guid in list(object_mgr.GetAllObjects(int(handle))):
                stub = object_mgr.GetMetaObjectStub(int(handle), candidate_guid)
                stub_name = _text(stub.Name) if stub is not None else ""
                if stub is None or stub_name.lower() != wanted_name:
                    continue
                candidate_meta = getter(int(handle), candidate_guid)
                try:
                    candidate_native = candidate_meta.Object if candidate_meta is not None else None
                except Exception:
                    candidate_native = _get_member(candidate_meta, "object", "get_Object") if candidate_meta is not None else None
                try:
                    candidate_connectors = candidate_native.Connectors if candidate_native is not None else None
                except Exception:
                    candidate_connectors = _get_member(candidate_native, "connectors", "get_Connectors") if candidate_native is not None else None
                if candidate_native is not None and candidate_connectors is not None:
                    candidates.append((candidate_guid, candidate_meta, candidate_native))
        except Exception:
            candidates = []
        if len(candidates) == 1:
            native_guid, meta, native = candidates[0]
    if native is None:
        raise OperationError("native device object is unavailable", "native_device_object_unavailable", {"target": target, "path": path, "guid": _text(guid)})
    return object_mgr, meta, native, {"target": target, "path": path, "guid": _text(guid), "nativeGuid": _text(native_guid), "projectHandle": int(handle), "access": access, "objectRuntimeType": _text(native.GetType().FullName)}


def _native_element_children(element):
    children = _get_member(element, "sub_elements", "get_SubElements") or _get_member(element, "SubElements")
    try:
        return list(children) if children is not None else []
    except Exception:
        return []


def _native_element_snapshot(element, depth=0, max_depth=2):
    if element is None:
        return None
    result = {"runtimeType": _text(element.GetType().FullName), "childCount": 0}
    for key, names in (("name", ("name", "get_Name", "Name")), ("visibleName", ("visible_name", "get_VisibleName", "VisibleName")), ("identifier", ("identifier", "get_Identifier", "Identifier")), ("id", ("id", "get_Id", "Id")), ("paramType", ("param_type", "get_ParamType", "ParamType")), ("baseType", ("base_type", "get_BaseType", "BaseType")), ("channelType", ("channel_type", "get_ChannelType", "ChannelType")), ("value", ("value", "get_Value", "Value")), ("description", ("description", "get_Description", "Description")),
                       ("defaultValue", ("default_value", "get_DefaultValue", "DefaultValue")),
                       ("minimum", ("minimum", "get_Minimum", "Minimum", "min_value", "get_MinValue")),
                       ("maximum", ("maximum", "get_Maximum", "Maximum", "max_value", "get_MaxValue")),
                       ("access", ("access", "get_Access", "Access", "access_right", "get_AccessRight")),
                       ("readOnly", ("read_only", "get_ReadOnly", "ReadOnly"))):
        for name in names:
            value = _get_member(element, name)
            if value is not None:
                result[key] = _json_safe(value)
                break
    for name in ("GetBitSize", "get_bit_size"):
        try:
            getter = getattr(element, name)
            result["bitSize"] = int(getter())
            break
        except Exception:
            pass
    children = _native_element_children(element)
    result["childCount"] = len(children)
    if depth < max_depth and children:
        result["children"] = [_native_element_snapshot(item, depth + 1, max_depth) for item in children[:500]]
    return result


def _parameter_set_ids(parameter_set):
    """Best-effort enumeration of a connector host parameter set's parameter
    ids, so a parameter_not_found error can tell the caller the valid ids in
    the SAME response instead of forcing a probe round trip."""
    ids = []
    try:
        members = parameter_set.Parameters
    except Exception:
        members = _get_member(parameter_set, "parameters", "get_Parameters")
    try:
        for index, item in enumerate(list(members or [])[:64]):
            try:
                ids.append(int(_get_member(item, "id", "get_Id")))
            except Exception:
                ids.append(index)
    except Exception:
        pass
    return ids


def _native_connector_for_id(device_object, connector_id):
    """Resolve a connector by the vendor's OWN ConnectorId, never by index.

    Measured 2026-09-19 on the InoProShop line: the collection index and the
    vendor ConnectorId do NOT share a base -

        AM600 CPU            index 0 -> ConnectorId 0, index 1 -> ConnectorId 1
        ModbusTCP Slave      index 0 -> ConnectorId 1, index 1 -> ConnectorId 2

    - so reading ``connectors[connector_id]`` silently picked the WRONG
    connector on the slave (and returned a null entry for id 2), which surfaced
    as ``parameter_set_unavailable``.  Match the reported ConnectorId first and
    keep the historical index lookup only as a fallback for a device whose
    collection exposes no ConnectorId at all.
    """
    try:
        connectors = device_object.Connectors
    except Exception:
        connectors = _get_member(device_object, "connectors", "get_Connectors")
    if connectors is None:
        raise OperationError("device has no connectors", "connector_unavailable",
                             {"connectorId": int(connector_id)})
    try:
        rows = list(connectors)
    except Exception:
        rows = []
    wanted = int(connector_id)
    available = []
    for row in rows:
        if row is None:
            continue
        raw_id = _get_member(row, "ConnectorId", "get_ConnectorId")
        try:
            row_id = int(raw_id)
        except Exception:
            row_id = None
        available.append({"connectorId": row_id,
                          "visibleInterfaceName": _text(_get_member(
                              row, "VisibleInterfaceName",
                              "get_VisibleInterfaceName", ""))})
        if row_id is not None and row_id == wanted:
            return row
    if 0 <= wanted < len(rows) and rows[wanted] is not None:
        return rows[wanted]
    raise OperationError(
        "device has no requested connector",
        "connector_unavailable",
        {"connectorId": wanted, "availableConnectors": available,
         "hint": "connectorId is the vendor ConnectorId reported by "
                 "vendor.device.parameter.probe, not a list index"})


def _native_parameter_from_device(device_object, parameter_id, connector_id=1):
    connector = _native_connector_for_id(device_object, connector_id)
    try:
        parameter_set = connector.HostParameterSet
    except Exception:
        parameter_set = _get_member(connector, "host_parameter_set", "get_HostParameterSet")
    if parameter_set is None:
        raise OperationError(
            "connector has no host parameter set",
            "parameter_set_unavailable",
            {"connectorId": int(connector_id),
             "visibleInterfaceName": _text(_get_member(
                 connector, "VisibleInterfaceName", "get_VisibleInterfaceName", "")),
             "hint": "this connector exposes no host parameter set; enumerate "
                     "the device with vendor.device.parameter.probe and pick a "
                     "connector whose parameterCount is not 0"})
    try:
        parameter = parameter_set.GetParameter(int(parameter_id))
    except Exception:
        parameter = parameter_set.GetParameter(long(parameter_id))
    if parameter is None:
        raise OperationError(
            "parameter id was not found",
            "parameter_not_found",
            {"parameterId": int(parameter_id),
             "availableParameterIds": _parameter_set_ids(parameter_set),
             "hint": "pick one of availableParameterIds for parameterId; "
                     "modules with no I/O channels return an empty list — "
                     "choose a DI/DO module instead of an END terminal"})
    return parameter


def _native_element_at_path(element, element_path):
    parts = element_path if isinstance(element_path, list) else [item for item in _text(element_path).replace("\\", "/").split("/") if item]
    for part in parts:
        current = element
        try:
            # IDataElement.SubElements is commonly indexed by an integer;
            # named children use the string indexer. Try the typed index first
            # so a request for child "0" cannot silently return None.
            if _text(part).isdigit():
                try:
                    element = element[int(part)]
                except Exception:
                    element = element[part]
            else:
                element = element[part]
        except Exception:
            try:
                element = getattr(element, part)
            except Exception:
                children = _native_element_children(current)
                index = None
                try:
                    index = int(part)
                except Exception:
                    pass
                if index is not None and 0 <= index < len(children):
                    element = children[index]
                else:
                    raise OperationError("element path was not found", "element_not_found", {"elementPath": parts, "at": part})
        if element is None:
            raise OperationError("element path resolved to null", "element_not_found",
                                 {"elementPath": parts, "at": part,
                                  "parentRuntimeType": _text(current.GetType().FullName)
                                  if current is not None and hasattr(current, "GetType") else None})
    return element, parts


def _native_element_value(element):
    try:
        return _json_safe(element.Value)
    except Exception:
        return _json_safe(_get_member(element, "value", "get_Value"))


def _native_io_mapping_snapshot(element):
    """Read the actual CODESYS IIoMapping shape for one IDataElement.

    The vendor editors use this model for variable bindings and manual IEC
    addresses. This helper is deliberately read-only and does not infer a
    writable mapping contract from the presence of ``AddMapping``.
    """
    mapping = _get_member(element, "IoMapping", "get_IoMapping")
    if mapping is None:
        mapping = _get_member(element, "io_mapping", "get_io_mapping")
    result = {"available": mapping is not None, "variableMappings": []}
    if mapping is None:
        return result
    try:
        result["runtimeType"] = _text(mapping.GetType().FullName)
    except Exception:
        pass
    for key, prop, getter in (
            ("automaticIecAddress", "AutomaticIecAddress", "get_AutomaticIecAddress"),
            ("iecAddress", "IecAddress", "get_IecAddress"),
            ("mappingType", "MappingType", "get_MappingType")):
        value = _get_member(mapping, prop, getter)
        if value is not None:
            result[key] = _json_safe(value)
    mappings = _get_member(mapping, "VariableMappings", "get_VariableMappings")
    if mappings is None:
        mappings = _get_member(mapping, "variable_mappings", "get_variable_mappings")
    if mappings is None:
        return result
    try:
        result["variableMappingsRuntimeType"] = _text(mappings.GetType().FullName)
    except Exception:
        pass
    try:
        values = list(mappings)
    except Exception as exc:
        result["variableMappingsReadError"] = repr(exc)
        return result
    for item in values[:100]:
        entry = {}
        try:
            entry["runtimeType"] = _text(item.GetType().FullName)
        except Exception:
            pass
        for key, prop, getter in (
                ("variable", "Variable", "get_Variable"),
                ("createVariable", "CreateVariable", "get_CreateVariable"),
                ("description", "Description", "get_Description")):
            value = _get_member(item, prop, getter)
            if value is not None:
                entry[key] = _json_safe(value)
        result["variableMappings"].append(entry)
    result["variableMappingCount"] = len(values)
    return result


def vendor_device_config_module_probe(req):
    """Read-only: resolve a device-tree node inside the VENDOR CONFIG GRAPH.

    Measured 2026-09-19: the ScriptEngine DeviceObject reachable through
    ObjectMgr exposes a communication slave's parameters on its connector host
    set, but that set's IoMapping carries no IoProvider (its IecAddress resolves
    to ""), so a mapping written there only lands in a memory copy. The vendor
    editors work on the config-graph object instead, which this probe resolves
    by GUID through IHardwareConfigProj.FindSpecialDevice(Guid) and reports:
    the runtime type, the parameter/mapping members it exposes, and - when
    parameterId is given - the parameter id and IoMapping state per candidate
    parameter set. It never mutates the project.
    """
    _require_project()
    target = req.get("target") or req.get("path") or req.get("device")
    guid_text = _text(req.get("guid") or "").strip()
    if not guid_text and target:
        _mgr, meta, _native, _binding = _native_device_object(target, "read")
        guid_text = _text(_get_member(meta, "ObjectGuid", "get_ObjectGuid"))
        if not guid_text:
            guid_text = _text(_get_member(meta, "Guid", "get_Guid"))
    if not guid_text:
        raise OperationError("guid or target is required", "invalid_argument")
    import System
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable",
                             {"binding": binding})
    sync_project = factory.CreateConfigSyncProj()
    sync_project.StartSyncToConfigrationDataObject()
    hardware = _get_member(sync_project, "HardwareConfigProject",
                           "get_HardwareConfigProject")
    if hardware is None:
        raise OperationError("vendor hardware configuration object is unavailable",
                             "hardware_configuration_unavailable",
                             {"mutatedProject": False})
    result = {"target": target, "guid": guid_text,
              "configurationFactory": binding, "mutatedProject": False,
              "resolved": False}
    module = None
    try:
        module = hardware.FindSpecialDevice(System.Guid(guid_text))
    except Exception as exc:
        result["resolveError"] = repr(exc)
    if module is None:
        result["status"] = "config_module_not_found"
        result["nextRequired"] = ("the guid must be a device-tree object guid of "
                                  "a node that exists in the vendor config graph")
        return result
    result["resolved"] = True
    result["status"] = "observed"
    result["runtimeType"] = _text(module.GetType().FullName)
    result["members"] = _member_names(
        module, ["parameter", "iomapping", "mapping", "devobject", "provider",
                 "address", "channel"])
    parameter_id = req.get("parameterId")
    if parameter_id is None:
        return result
    try:
        parameter_id = int(parameter_id)
    except Exception:
        raise OperationError("parameterId must be an integer", "invalid_argument")
    rows = []
    for label, accessor, getter in (
            ("HostParameterSet", "HostParameterSet", "get_HostParameterSet"),
            ("ParameterSet", "ParameterSet", "get_ParameterSet"),
            ("DeviceParameterSet", "DeviceParameterSet", "get_DeviceParameterSet")):
        parameter_set = _get_member(module, accessor, getter)
        if parameter_set is None:
            continue
        row = {"parameterSet": label}
        try:
            item = parameter_set.GetParameter(parameter_id)
        except Exception as exc:
            item = None
            row["getParameterError"] = repr(exc)
        row["parameterFound"] = item is not None
        if item is not None:
            row["ioMapping"] = _native_io_mapping_snapshot(item)
        rows.append(row)
    result["parameterSets"] = rows
    if not rows:
        result["nextRequired"] = ("this config module exposes no parameter set; "
                                  "use the device-tree parameter route instead")
    # The config module exposes the LIVE device object the vendor editors use
    # (members: DevObject / get_DevObject). Its connector host sets are the ones
    # that carry a wired IoProvider - the ObjectMgr-side DeviceObject we reach
    # from the ScriptEngine tree does not. Report the mapping state here so the
    # difference is visible before any write is attempted.
    dev_object = _get_member(module, "DevObject", "get_DevObject")
    if dev_object is None:
        dev_object = _get_member(module, "dev_object", "get_dev_object")
    if dev_object is not None:
        result["devObjectRuntimeType"] = _text(dev_object.GetType().FullName)
        connector_id = req.get("connectorId")
        connector_id = 2 if connector_id is None else connector_id
        dev_rows = []
        try:
            dev_candidates = _varmapping_candidate_sets(
                dev_object, parameter_id, connector_id)
        except Exception as exc:
            dev_candidates = []
            result["devObjectCandidatesError"] = repr(exc)
        for label, element in dev_candidates:
            row = {"parameterSet": label}
            row["ioMapping"] = _native_io_mapping_snapshot(element)
            dev_rows.append(row)
        result["devObjectParameterSets"] = dev_rows
        if dev_rows:
            result["nextRequired"] = (
                "compare ioMapping.iecAddress between parameterSets and "
                "devObjectParameterSets: a resolvable address means the IoProvider "
                "is attached and a variable mapping written there can land")
    return result


def _varmapping_candidate_sets(native, parameter_id, connector_id):
    """Parameter-set candidates for one parameter id, in vendor-preference order.

    Measured/decompiled 2026-09-19 (InoDeviceObject): DeviceObject.cs wires its
    OWN _deviceParameterSet with SetIoProvider(this) during load
    (DeviceObject.cs:1939/2048/2108), and ConnectorBase wires each connector's
    _hostParameterSet the same way (ConnectorBase.cs:1182).  The element we
    reached through a connector's host set carried an IoMapping whose provider
    was NOT attached (its IecAddress resolved to ""), so AddMapping only ever
    mutated a memory copy.  Prefer the wired DeviceObject set and keep the
    connector set as a fallback, reporting which one was used.
    """
    rows = []
    seen = []
    for label, accessor, getter in (
            ("device_parameter_set", "DeviceParameterSet", "get_DeviceParameterSet"),
            ("parameter_set", "ParameterSet", "get_ParameterSet"),
            ("device_parameter_set_alt", "device_parameter_set",
             "get_device_parameter_set")):
        parameter_set = _get_member(native, accessor, getter)
        if parameter_set is None:
            continue
        duplicate = False
        for previous in seen:
            try:
                if previous is parameter_set:
                    duplicate = True
                    break
            except Exception:
                continue
        if duplicate:
            continue
        seen.append(parameter_set)
        try:
            item = parameter_set.GetParameter(int(parameter_id))
        except Exception:
            try:
                item = parameter_set.GetParameter(long(parameter_id))
            except Exception:
                item = None
        if item is not None:
            rows.append((label, item))
            break
    try:
        rows.append(("connector_%d_host_parameter_set" % int(connector_id),
                     _native_parameter_from_device(native, parameter_id,
                                                   connector_id)))
    except OperationError:
        pass
    return rows


def vendor_io_variable_mapping(req):
    """Add or remove one IEC variable binding on a device parameter element.

    Vendor primitive (decompiled InoDeviceObject, measured 2026-09-19):

        IoMapping.VariableMappings -> IVariableMappingCollection
            AddMapping(string variable, bool createVariable) -> IVariableMapping
            Remove(IVariableMapping) / Remove(long id) / RemoveAt(int index)

    The element must come from a parameter set whose IoMapping carries the
    connector/DeviceObject IoProvider, otherwise the change only lands in a
    memory copy.  This op therefore tries the vendor-wired candidate sets in
    order (DeviceObject.DeviceParameterSet first - see
    _varmapping_candidate_sets), verifies EVERY attempt with a fresh-handle
    readback, and reports the per-candidate outcome plus an explicit boundary.
    """
    operation = "vendor.io.variable_mapping"
    _require_current_disposable_project(req, operation)
    _require_confirmation(req, ("map_variable", "variable_mapping"))
    target = req.get("target") or req.get("path") or req.get("device")
    parameter_id = req.get("parameterId")
    if not target or parameter_id is None:
        raise OperationError("target and parameterId are required", "invalid_argument")
    if isinstance(parameter_id, bool) or not isinstance(
            parameter_id, _INTEGER_TYPES):
        raise OperationError("parameterId must be an integer", "invalid_argument")
    parameter_id = int(parameter_id)
    connector_id = req.get("connectorId")
    connector_id = 1 if connector_id is None else connector_id
    if isinstance(connector_id, bool) or not isinstance(
            connector_id, _INTEGER_TYPES):
        raise OperationError("connectorId must be an integer", "invalid_argument")
    connector_id = int(connector_id)
    if "elementPath" in req:
        element_path = req.get("elementPath")
    elif "field" in req:
        element_path = req.get("field")
    else:
        element_path = []
    if element_path is None:
        element_path = []
    action = _text(req.get("action") or "add").strip().lower()
    if action not in ("add", "remove"):
        raise OperationError("action must be add or remove", "invalid_argument",
                             {"path": "action", "actual": action})
    variable = _text(req.get("variable") or "").strip()
    if not variable:
        raise OperationError(
            "variable is required (the exact IEC name as the vendor mapping "
            "page shows it, e.g. Application.GVL_MAP.xMapped)",
            "invalid_argument", {"path": "variable"})
    create_variable = req.get("createVariable", False)
    if not isinstance(create_variable, bool):
        raise OperationError(
            "createVariable must be a JSON boolean", "invalid_argument",
            {"path": "createVariable", "actual": create_variable,
             "mutatedProject": False})
    object_mgr, meta, native, binding = _native_device_object_with_retry(
        target, "modify")
    candidates = _varmapping_candidate_sets(native, parameter_id, connector_id)
    result = {
        "operation": operation,
        "action": action,
        "target": target,
        "parameterId": parameter_id,
        "connectorId": connector_id,
        "elementPath": element_path if isinstance(element_path, list)
                       else [element_path],
        "variable": variable,
        "createVariable": create_variable,
        "binding": binding,
        "candidateSets": [label for label, _item in candidates],
        "candidateAttempts": [],
        "mutatedProject": False,
        "attempts": [],
    }
    if not candidates:
        raise OperationError(
            "parameter id was not found in the device parameter sets",
            "parameter_not_found",
            {"target": target, "parameterId": parameter_id,
             "connectorId": connector_id, "mutatedProject": False})
    landed = None
    mutation_attempted = False
    absent_sets = []
    for label, root in candidates:
        attempt = {"parameterSet": label}
        element, parts = _native_element_at_path(root, element_path)
        attempt["elementPath"] = parts
        mapping = _get_member(element, "IoMapping", "get_IoMapping")
        if mapping is None:
            mapping = _get_member(element, "io_mapping", "get_io_mapping")
        if mapping is None:
            attempt["status"] = "no_io_mapping"
            result["candidateAttempts"].append(attempt)
            continue
        collection = _get_member(mapping, "VariableMappings",
                                 "get_VariableMappings")
        if collection is None:
            attempt["status"] = "no_variable_mappings"
            result["candidateAttempts"].append(attempt)
            continue
        attempt["iecAddressBefore"] = _text(_get_member(
            mapping, "IecAddress", "get_IecAddress"))
        before = _native_io_mapping_snapshot(element)
        existing = [_text(row.get("variable"))
                    for row in (before.get("variableMappings") or [])
                    if _text(row.get("variable"))]
        attempt["beforeVariables"] = existing
        if action == "add":
            if variable in existing:
                attempt["status"] = "already_present"
                attempt["readbackVariables"] = existing
                result["candidateAttempts"].append(attempt)
                landed = label
                result["alreadyPresent"] = True
                break
            try:
                mutation_attempted = True
                collection.AddMapping(variable, create_variable)
            except Exception as exc:
                attempt["status"] = "add_failed"
                attempt["error"] = repr(exc)
                result["candidateAttempts"].append(attempt)
                continue
        else:
            if variable not in existing:
                attempt["status"] = "not_mapped_on_this_set"
                result["candidateAttempts"].append(attempt)
                absent_sets.append(label)
                continue
            removed = False
            try:
                values = list(collection)
            except Exception as exc:
                attempt["status"] = "enumeration_failed"
                attempt["error"] = repr(exc)
                result["candidateAttempts"].append(attempt)
                continue
            for item in values:
                if _text(_get_member(item, "Variable", "get_Variable")) != variable:
                    continue
                try:
                    mutation_attempted = True
                    collection.Remove(item)
                    removed = True
                except Exception as exc:
                    attempt["error"] = repr(exc)
                break
            if not removed:
                attempt["status"] = "remove_failed"
                result["candidateAttempts"].append(attempt)
                continue
        committed = False
        commit_error = None
        try:
            object_mgr.SetObject(meta, True, None)
            committed = True
        except Exception as exc:
            commit_error = repr(exc)
        attempt["committed"] = committed
        if commit_error:
            attempt["commitError"] = commit_error
        expected_present = action == "add"
        observed = None
        try:
            _read_mgr, _read_meta, read_native, read_binding = _native_device_object(
                target, "read")
            read_candidates = _varmapping_candidate_sets(
                read_native, parameter_id, connector_id)
            read_element = None
            for read_label, read_root in read_candidates:
                if read_label != label:
                    continue
                read_element, _read_parts = _native_element_at_path(
                    read_root, element_path)
                break
            if read_element is None and read_candidates:
                read_element, _read_parts = _native_element_at_path(
                    read_candidates[0][1], element_path)
            after = _native_io_mapping_snapshot(read_element)
            attempt["afterVariables"] = [
                _text(row.get("variable"))
                for row in (after.get("variableMappings") or [])
                if _text(row.get("variable"))]
            observed = variable in attempt["afterVariables"]
            attempt["readbackBinding"] = read_binding
        except Exception as exc:
            attempt["readbackError"] = repr(exc)
        if observed == expected_present:
            attempt["status"] = "landed"
            attempt["exactReadback"] = True
            result["candidateAttempts"].append(attempt)
            landed = label
            break
        attempt["status"] = "write_not_visible_on_fresh_handle"
        attempt["exactReadback"] = False
        result["candidateAttempts"].append(attempt)
    if (action == "remove" and not mutation_attempted and absent_sets and
            landed is None):
        landed = absent_sets[0]
        result["alreadyAbsent"] = True
    result["mutationAttempted"] = mutation_attempted
    result["mutatedProject"] = mutation_attempted
    result["parameterSetUsed"] = landed
    result["landed"] = landed is not None
    if result.get("alreadyPresent"):
        result["status"] = "already_present"
    elif result.get("alreadyAbsent"):
        result["status"] = "already_absent"
    else:
        result["status"] = ("committed" if landed is not None
                            else "commit_unverified")
    result["exactReadback"] = landed is not None
    result["persistenceVerified"] = False
    if landed is None:
        result["boundary"] = (
            "No candidate parameter set exposed a writable IoMapping: every "
            "AddMapping/Remove committed through ObjectMgr but was invisible to a "
            "fresh handle, so the binding did NOT land. Treat commit_unverified "
            "as a boundary - do not report the mapping as done. The verified "
            "channel-mapping surface remains local rack modules "
            "(codesys_io_mapping_add).")
        result["nextRequired"] = (
            "wire the binding through the vendor data-model route (the device "
            "editor's data-model page / connector IIoProvider) instead of the "
            "parameter set; that route is not implemented yet")
    else:
        result["nextRequired"] = (
            "save the project (codesys_project_save, confirm=save_project, "
            "disposable=true), reopen it in a fresh process and read the mapping "
            "again with codesys_io_mapping_read - an in-session mapping is not "
            "persistence")
    return result

def vendor_io_mapping_read(req):
    """Read an exact vendor channel mapping without enumerating or changing it."""
    target = req.get("target") or req.get("path") or req.get("device")
    parameter_id = req.get("parameterId")
    element_path = req.get("elementPath") or req.get("field") or []
    connector_id = req.get("connectorId", 1)
    if not target or parameter_id is None:
        raise OperationError("target and parameterId are required", "invalid_argument")
    try:
        parameter_id = int(parameter_id)
        connector_id = int(connector_id)
    except Exception:
        raise OperationError("parameterId and connectorId must be integers", "invalid_argument")
    _object_mgr, _meta, native, binding = _native_device_object(target, "read")
    element = _native_parameter_from_device(native, parameter_id, connector_id)
    element, parts = _native_element_at_path(element, element_path)
    return {
        "binding": binding,
        "target": target,
        "connectorId": connector_id,
        "parameterId": parameter_id,
        "elementPath": parts,
        "element": _native_element_snapshot(element, 0, int(req.get("depth", 1))),
        "ioMapping": _native_io_mapping_snapshot(element),
        "mutatedProject": False,
        "status": "observed",
        "writeSupport": "not_attempted",
        "nextRequired": "use this readback to identify an exact writable channel before enabling a mapping writer",
    }


def _mapping_variables(mapping):
    values = _get_member(mapping, "VariableMappings", "get_VariableMappings")
    if values is None:
        values = _get_member(mapping, "variable_mappings", "get_variable_mappings")
    try:
        return list(values) if values is not None else []
    except Exception:
        return []


def _ethercat_pdo_bounded_sequence(value, limit):
    """Read a CLR/Python sequence without allowing an unbounded enumeration.

    EtherCAT pages use ``ArrayList``/``List<T>`` in the installed plug-in, but
    test doubles and older builds may expose only an iterator.  The helper is
    deliberately read-only and returns the observed count/truncation state so
    callers cannot mistake a bounded inventory for a complete one.
    """
    result = {
        "available": value is not None,
        "count": None,
        "items": [],
        "truncated": False,
        "error": None,
    }
    if value is None:
        return result
    try:
        result["runtimeType"] = _text(value.GetType().FullName)
    except Exception:
        result["runtimeType"] = _text(type(value))
    for name in ("Count", "Length"):
        try:
            candidate = _get_member(value, name, "get_" + name)
            if candidate is not None:
                result["count"] = max(0, int(candidate))
                break
        except Exception as exc:
            result["error"] = repr(exc)
    try:
        hard_limit = max(0, int(limit))
    except Exception:
        hard_limit = 0
    # Prefer the indexer.  This avoids materialising a vendor collection whose
    # Count is unexpectedly large and keeps the probe deterministic.
    indexable = True
    if result["count"] is not None:
        upper = min(result["count"], hard_limit)
    else:
        upper = hard_limit
    for index in range(upper):
        try:
            item = value[index]
        except Exception:
            indexable = False
            break
        result["items"].append((index, item))
    if indexable and result["count"] is not None:
        result["truncated"] = result["count"] > hard_limit
        return result
    if indexable and result["count"] == 0:
        return result
    # Unknown-count iterables (or non-indexable wrappers) are read one item at
    # a time and stop after ``hard_limit + 1`` so truncation is explicit.
    result["items"] = []
    try:
        iterator = iter(value)
        for index in range(hard_limit + 1):
            try:
                item = next(iterator)
            except StopIteration:
                break
            result["items"].append((index, item))
        if len(result["items"]) > hard_limit:
            result["items"] = result["items"][:hard_limit]
            result["truncated"] = True
    except Exception as exc:
        result["error"] = repr(exc)
    return result


def _ethercat_pdo_mapping_inventory(entry, mapping_visible=None,
                                    include_variables=True, variable_limit=32):
    """Snapshot one PDO entry's mapping dictionary without invoking writers.

    ``bIsMappingVisable`` is a field on the parent ``PDOITEM`` rather than on
    ``PDOITEMENTRY`` in the InoProShop plug-in.  Callers should pass the
    parent value explicitly; retaining the entry fallback keeps this helper
    compatible with older/test-double models that put the flag on entries.
    """
    mapping = _get_member(entry, "_dictMappingVariable")
    if mapping is None:
        mapping = _get_member(entry, "dictMappingVariable",
                              "get_dictMappingVariable")
    result = {
        "mappingStatus": "unavailable",
        "mappingVisible": None,
        "mappingCount": 0,
        "mappedVariables": [],
        "mappingTruncated": False,
        "mappingError": None,
    }
    visible = (mapping_visible if mapping_visible is not None else
               _get_member(entry, "bIsMappingVisable",
                           "get_bIsMappingVisable"))
    if visible is not None:
        result["mappingVisible"] = _json_safe(visible)
    if mapping is None:
        # A missing dictionary is different from an empty dictionary: the
        # former means this runtime does not expose mapping state safely.
        result["mappingError"] = "_dictMappingVariable is unavailable"
        return result
    keys = _get_member(mapping, "Keys", "get_Keys")
    if keys is None:
        # Do not report an empty mapping when the dictionary exists but its
        # key collection cannot be read.  That distinction is important for
        # callers deciding whether a subsequent mapping write is safe.
        result["mappingError"] = "_dictMappingVariable.Keys is unavailable"
        return result
    sequence = _ethercat_pdo_bounded_sequence(keys, variable_limit)
    result["mappingCount"] = sequence.get("count")
    if result["mappingCount"] is None:
        result["mappingCount"] = len(sequence.get("items", []))
    result["mappingTruncated"] = bool(sequence.get("truncated"))
    if sequence.get("error"):
        result["mappingError"] = sequence.get("error")
    if include_variables:
        for _index, key in sequence.get("items", []):
            try:
                value = mapping[key]
            except Exception as exc:
                try:
                    value = _get_member(mapping, _text(key))
                except Exception:
                    value = None
                if value is None:
                    result["mappingError"] = repr(exc)
            result["mappedVariables"].append({
                "key": _text(key),
                "variable": _text(value),
            })
    count = int(result.get("mappingCount") or 0)
    if count > 0:
        result["mappingStatus"] = (
            "mapped_hidden" if result.get("mappingVisible") is False
            else "mapped")
    elif result.get("mappingVisible") is False:
        result["mappingStatus"] = "hidden"
    elif result.get("mappingError"):
        result["mappingStatus"] = "unavailable"
    else:
        result["mappingStatus"] = "empty"
    return result


def vendor_ethercat_pdo_probe(req):
    """Inventory the live EtherCATProcessDataPage PDO model, read-only.

    The native page keeps PDOITEM/PDOITEMENTRY records in the private
    ``_PDOItems`` field.  Reading that field is the same source used by the
    vendor mapping writer, but this operation never asks for a writable
    connector, changes ``bIsMappingVisable``/mapping dictionaries, calls
    ``Save``/``Reload``, or commits through ObjectMgr.
    """
    _require_project()
    target = _text(req.get("target") or req.get("path") or "").strip()
    if not target:
        raise OperationError("vendor.ethercat.pdo.probe requires target",
                             "invalid_argument", {"path": "target"})

    direction = _text(req.get("direction") or "").strip().upper()
    if direction and direction not in ("RX", "TX"):
        raise OperationError("direction must be RX or TX", "invalid_argument",
                             {"path": "direction", "expected": ["RX", "TX"]})
    module_guid = _text(req.get("moduleGuid") or "").strip()
    if module_guid:
        module_guid = module_guid.strip("{}").lower()

    def optional_int(name):
        value = req.get(name)
        if value is None or value == "":
            return None
        try:
            return int(value)
        except Exception:
            raise OperationError(name + " must be an integer", "invalid_argument",
                                 {"path": name})

    sync_manager = optional_int("syncManager")
    entry_index = optional_int("index")
    entry_subindex = optional_int("subIndex")
    try:
        limit = int(req.get("limit", 200))
    except Exception:
        raise OperationError("limit must be an integer", "invalid_argument",
                             {"path": "limit"})
    if limit < 1 or limit > 1000:
        raise OperationError("limit must be between 1 and 1000",
                             "invalid_argument", {"path": "limit",
                                                   "minimum": 1,
                                                   "maximum": 1000})
    try:
        offset = int(req.get("offset", 0))
    except Exception:
        raise OperationError("offset must be an integer", "invalid_argument",
                             {"path": "offset"})
    if offset < 0 or offset > 1000000:
        raise OperationError("offset must be between 0 and 1000000",
                             "invalid_argument", {"path": "offset",
                                                   "minimum": 0,
                                                   "maximum": 1000000})
    include_variables = req.get("includeMappingVariables", True)
    if not isinstance(include_variables, bool):
        raise OperationError(
            "includeMappingVariables must be a boolean", "invalid_argument",
            {"path": "includeMappingVariables", "expected": "boolean"})

    page_request = dict(req)
    page_request["target"] = target
    page_request["pageType"] = "EthercatProcessDataPage"
    page, _frame, editor_detail, _pages = _vendor_editor_page(page_request)
    page_runtime = _text(page.GetType().FullName)
    if not page_runtime.endswith(".EthercatProcessDataPage"):
        raise OperationError("live page is not EthercatProcessDataPage",
                             "ethercat_pdo_page_mismatch",
                             {"pageType": page_runtime, "target": target,
                              "mutatedProject": False})

    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    pdo_field = page.GetType().GetField("_PDOItems", flags)
    loadsave_field = page.GetType().GetField("_loadsave", flags)
    connector_field = page.GetType().GetField("_ConnectorId", flags)
    state = {
        "pageType": page_runtime,
        "pdoItemsField": pdo_field is not None,
        "loadSaveField": loadsave_field is not None,
        "connectorIdField": connector_field is not None,
    }
    if pdo_field is None:
        raise OperationError("vendor EtherCAT page has no _PDOItems field",
                             "ethercat_pdo_page_state_unavailable", state)
    try:
        pdo_items = pdo_field.GetValue(page)
    except Exception as exc:
        raise OperationError("reading vendor EtherCAT _PDOItems failed",
                             "ethercat_pdo_page_state_unavailable",
                             dict(state, readError=repr(exc)))
    if pdo_items is None:
        raise OperationError(
            "vendor EtherCAT PDO state has not been loaded; open the process-data page and retry",
            "ethercat_pdo_page_not_loaded",
            dict(state, target=target, mutatedProject=False,
                 reloadAttempted=False,
                 next="allow the native page idle load to finish, then call the probe again"),
        )

    # The page's lists are small in normal projects.  These hard caps protect
    # the resident bridge from a corrupt/hostile project while preserving an
    # explicit ``collectionTruncated`` signal for callers.
    groups = _ethercat_pdo_bounded_sequence(pdo_items, 512)
    rows = []
    item_errors = []
    item_error_limit = 256
    item_errors_truncated = [False]

    def record_item_error(value):
        # A malformed project can expose thousands of null/invalid entries;
        # bound diagnostics as well as data so an error response remains
        # cheap to serialize.
        if len(item_errors) < item_error_limit:
            item_errors.append(value)
        else:
            item_errors_truncated[0] = True

    observed_entry_count = 0
    entry_collection_truncated = False
    entry_collection_errors = []
    total_row_cap = 20000
    for item_index, item in groups.get("items", []):
        if item is None:
            record_item_error({"pdoIndex": item_index,
                               "error": "null PDO item"})
            continue
        item_direction = _text(_get_member(item, "Type", "get_Type")).upper()
        item_guid = _text(_get_member(item, "moduleGuid", "get_moduleGuid"))
        item_guid = item_guid.strip("{}").lower()
        item_sm = _json_safe(_get_member(item, "iSm", "get_iSm"))
        item_visible = _json_safe(_get_member(item, "bIsMappingVisable",
                                              "get_bIsMappingVisable"))
        item_name = _text(_get_member(item, "sName", "get_sName"))
        entries = _get_member(item, "Entry", "get_Entry")
        entry_sequence = _ethercat_pdo_bounded_sequence(entries, 4096)
        if entry_sequence.get("truncated"):
            entry_collection_truncated = True
        if entry_sequence.get("error"):
            entry_collection_errors.append({
                "pdoIndex": item_index,
                "moduleGuid": item_guid,
                "error": entry_sequence.get("error"),
            })
        if not entry_sequence.get("available"):
            record_item_error({"pdoIndex": item_index,
                               "moduleGuid": item_guid,
                               "error": "PDO Entry collection unavailable"})
            continue
        for entry_index_in_item, entry in entry_sequence.get("items", []):
            observed_entry_count += 1
            if len(rows) >= total_row_cap:
                break
            if entry is None:
                record_item_error({"pdoIndex": item_index,
                                   "entryIndex": entry_index_in_item,
                                   "error": "null PDO entry"})
                continue
            mapping = _ethercat_pdo_mapping_inventory(
                entry, mapping_visible=item_visible,
                include_variables=include_variables)
            row = {
                "pdoIndex": item_index,
                "entryIndex": entry_index_in_item,
                "pdoName": item_name,
                "direction": item_direction,
                "moduleGuid": item_guid,
                "syncManager": item_sm,
                "mappingVisible": item_visible,
                "index": _json_safe(_get_member(entry, "uiIndex",
                                                   "get_uiIndex")),
                "subIndex": _json_safe(_get_member(entry, "usSubIndex",
                                                       "get_usSubIndex")),
                "bitSize": _json_safe(_get_member(entry, "uiSize",
                                                    "get_uiSize")),
                "dataType": _text(_get_member(entry, "sDataType",
                                                "get_sDataType")).upper(),
                "name": _text(_get_member(entry, "sName", "get_sName")),
            }
            row.update(mapping)
            if direction and row["direction"] != direction:
                continue
            if module_guid and row["moduleGuid"] != module_guid:
                continue
            if sync_manager is not None:
                try:
                    if int(row["syncManager"]) != sync_manager:
                        continue
                except Exception:
                    continue
            if entry_index is not None:
                try:
                    if int(row["index"]) != entry_index:
                        continue
                except Exception:
                    continue
            if entry_subindex is not None:
                try:
                    if int(row["subIndex"]) != entry_subindex:
                        continue
                except Exception:
                    continue
            rows.append(row)
        if len(rows) >= total_row_cap:
            break

    collection_truncated = bool(
        groups.get("truncated") or entry_collection_truncated)
    if len(rows) >= total_row_cap:
        collection_truncated = True
    collection_errors = list(entry_collection_errors)
    if groups.get("error"):
        collection_errors.insert(0, {"scope": "pdoItems",
                                     "error": groups.get("error")})
    total_matched = len(rows)
    page_rows = rows[offset:offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total_matched or collection_truncated
    try:
        # ``_ConnectorId`` is private in the vendor page; use the reflected
        # field when available instead of relying on IronPython name mangling
        # or a public getter that differs between plug-in builds.
        connector_value = (connector_field.GetValue(page)
                           if connector_field is not None else None)
    except Exception:
        connector_value = None
    result = {
        "target": target,
        "pageType": page_runtime,
        "connectorId": _json_safe(connector_value),
        "state": state,
        "groupsObserved": len(groups.get("items", [])),
        "groupsReported": groups.get("count"),
        "entryCountObserved": observed_entry_count,
        "totalMatched": total_matched,
        "offset": offset,
        "limit": limit,
        "returned": len(page_rows),
        "nextOffset": next_offset if has_more else None,
        "hasMore": has_more,
        "truncated": has_more,
        "collectionTruncated": collection_truncated,
        "collectionError": groups.get("error"),
        "collectionErrors": collection_errors,
        "bounds": {
            "pdoGroups": 512,
            "entriesPerGroup": 4096,
            "rows": total_row_cap,
            "mappingVariablesPerEntry": 32,
            "itemErrors": item_error_limit,
        },
        "itemErrors": item_errors,
        "itemErrorsTruncated": item_errors_truncated[0],
        "items": page_rows,
        "readOnly": True,
        "mutatedProject": False,
        "status": "observed",
        "editor": editor_detail,
    }
    return result


def _ethercat_pdo_mapping_add(req, variable, pdo_contract):
    """Commit one modular EtherCAT PDO mapping through the live vendor page."""
    parent_target = _text(pdo_contract.get("parentTarget") or "").strip()
    if not parent_target:
        raise OperationError("ethercatPdo.parentTarget is required",
                             "invalid_argument",
                             {"path": "ethercatPdo.parentTarget"})
    required = ("direction", "index", "subIndex", "bitSize", "dataType",
                "expectedModuleGuid")
    missing = [name for name in required if pdo_contract.get(name) is None]
    if missing:
        raise OperationError("ethercatPdo requires an exact PDO entry identity",
                             "invalid_argument",
                             {"missing": ["ethercatPdo." + name for name in missing]})
    direction = _text(pdo_contract.get("direction")).upper()
    if direction not in ("RX", "TX"):
        raise OperationError("ethercatPdo.direction must be RX or TX",
                             "invalid_argument", {"path": "ethercatPdo.direction"})
    try:
        entry_index = int(pdo_contract.get("index"))
        entry_subindex = int(pdo_contract.get("subIndex"))
        entry_bits = int(pdo_contract.get("bitSize"))
    except Exception:
        raise OperationError("EtherCAT PDO index, subIndex and bitSize must be integers",
                             "invalid_argument")
    entry_type = _text(pdo_contract.get("dataType")).upper()
    expected_guid = _text(pdo_contract.get("expectedModuleGuid")).strip("{}").lower()

    page_request = dict(req)
    page_request["target"] = parent_target
    page_request["pageType"] = "EthercatProcessDataPage"
    page, frame, _editor_detail, _pages = _vendor_editor_page(page_request)
    page_runtime = _text(page.GetType().FullName)
    if not page_runtime.endswith(".EthercatProcessDataPage"):
        raise OperationError("live page is not EthercatProcessDataPage",
                             "ethercat_pdo_page_mismatch",
                             {"pageType": page_runtime})

    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)

    pdo_field = page.GetType().GetField("_PDOItems", flags)
    loadsave_field = page.GetType().GetField("_loadsave", flags)
    connector_field = page.GetType().GetField("_ConnectorId", flags)
    change_field = page.GetType().GetField("_bChange", flags)
    if (pdo_field is None or loadsave_field is None or connector_field is None or
            change_field is None):
        raise OperationError("vendor EtherCAT page state is incomplete",
                             "ethercat_pdo_page_state_unavailable",
                             {"pageType": page_runtime})
    pdo_items = pdo_field.GetValue(page)
    loadsave = loadsave_field.GetValue(page)
    connector_id = int(connector_field.GetValue(page))
    if pdo_items is None or loadsave is None:
        raise OperationError("vendor EtherCAT PDO state has not been loaded",
                             "ethercat_pdo_page_not_loaded",
                             {"parentTarget": parent_target})

    matches = []
    inventory = []
    for item in list(pdo_items):
        item_direction = _text(_get_member(item, "Type", "get_Type")).upper()
        item_guid = _text(_get_member(item, "moduleGuid", "get_moduleGuid")).strip("{}").lower()
        item_sm = _get_member(item, "iSm", "get_iSm")
        item_visible = _get_member(item, "bIsMappingVisable", "get_bIsMappingVisable")
        entries = _get_member(item, "Entry", "get_Entry")
        for entry in list(entries or []):
            row = {
                "direction": item_direction,
                "moduleGuid": item_guid,
                "syncManager": _json_safe(item_sm),
                "mappingVisible": _json_safe(item_visible),
                "index": _json_safe(_get_member(entry, "uiIndex", "get_uiIndex")),
                "subIndex": _json_safe(_get_member(entry, "usSubIndex", "get_usSubIndex")),
                "bitSize": _json_safe(_get_member(entry, "uiSize", "get_uiSize")),
                "dataType": _text(_get_member(entry, "sDataType", "get_sDataType")).upper(),
                "name": _text(_get_member(entry, "sName", "get_sName")),
            }
            inventory.append(row)
            try:
                exact = (item_direction == direction and item_guid == expected_guid and
                         int(row["index"]) == entry_index and
                         int(row["subIndex"]) == entry_subindex and
                         int(row["bitSize"]) == entry_bits and
                         row["dataType"] == entry_type)
            except Exception:
                exact = False
            if exact:
                matches.append((item, entry, row))
    if len(matches) != 1:
        raise OperationError("expected exactly one live vendor PDO entry",
                             "ethercat_pdo_entry_ambiguous",
                             {"matchCount": len(matches), "expected": _json_safe(pdo_contract),
                              "inventory": inventory, "mutatedProject": False})
    selected_item, selected_entry, selected_snapshot = matches[0]
    try:
        if int(selected_snapshot["syncManager"]) < 0:
            raise OperationError("selected PDO is disabled",
                                 "ethercat_pdo_disabled", selected_snapshot)
    except OperationError:
        raise
    except Exception:
        raise OperationError("selected PDO sync manager is invalid",
                             "ethercat_pdo_sync_manager_invalid", selected_snapshot)
    mapping_dict = _get_member(selected_entry, "_dictMappingVariable")
    if mapping_dict is None:
        raise OperationError("PDO entry mapping dictionary is unavailable",
                             "ethercat_pdo_mapping_dictionary_unavailable")
    existing = []
    try:
        existing = [{"key": _text(key), "variable": _text(mapping_dict[key])}
                    for key in list(mapping_dict.Keys)]
    except Exception:
        pass
    conflicting = [row for row in existing if row.get("variable") != variable]
    if conflicting:
        raise OperationError("refusing to overwrite an existing PDO mapping",
                             "io_mapping_not_empty",
                             {"existing": existing, "variable": variable,
                              "mutatedProject": False})

    # Repeating an already-satisfied mapping request is a read-only success.
    # In particular, do not call Save(true): that would dirty the project and
    # falsely report a mutation even though the PDO dictionary is unchanged.
    if existing:
        return {
            "binding": "EthercatProcessDataPage.PDOITEM._dictMappingVariable",
            "target": req.get("target") or req.get("path") or req.get("device"),
            "mappingLocation": parent_target,
            "parameterId": int(req.get("parameterId")),
            "elementPath": [],
            "variable": variable,
            "pdoEntry": selected_snapshot,
            "existingPdoMappings": existing,
            "retained": True,
            "committed": False,
            "mutatedProject": False,
            "status": "unchanged",
            "nextRequired": "none; the exact PDO mapping already exists",
        }

    try:
        parent_connector = frame.GetConnector(connector_id, True)
    except Exception as exc:
        raise OperationError("vendor EtherCAT parent connector is unavailable: " + repr(exc),
                             "ethercat_parent_connector_unavailable",
                             {"connectorId": connector_id})
    if parent_connector is None:
        raise OperationError("vendor EtherCAT parent connector resolved to null",
                             "ethercat_parent_connector_unavailable",
                             {"connectorId": connector_id})

    # All fallible identity and conflict checks above intentionally precede
    # the first mutation. Keep the vendor page transaction reversible until
    # Save succeeds so a failed request cannot poison the live IDE process.
    visibility_before = selected_snapshot["mappingVisible"]
    visibility_repaired = False
    mapping_added = False
    try:
        if visibility_before is not True:
            if pdo_contract.get("allowModuleMappingVisibility") is not True:
                raise OperationError(
                    "selected modular PDO needs the vendor mapping-visible state restored",
                    "ethercat_pdo_mapping_hidden",
                    {"entry": selected_snapshot,
                     "correctParameter": "ethercatPdo.allowModuleMappingVisibility=true",
                     "why": "UpdateModularDeviceData marks real nonzero module PDO entries mapping-visible",
                     "mutatedProject": False})
            selected_item.bIsMappingVisable = True
            visibility_repaired = True
        if not existing:
            mapping_dict[""] = variable
            mapping_added = True
    except OperationError:
        raise
    except Exception as exc:
        try:
            if mapping_added:
                mapping_dict.Remove("")
            if visibility_repaired:
                selected_item.bIsMappingVisable = visibility_before
        except Exception:
            pass
        raise OperationError("failed to stage the vendor PDO mapping: " + repr(exc),
                             "ethercat_pdo_mapping_stage_failed",
                             {"entry": selected_snapshot,
                              "mutatedProject": False})
    try:
        change_field.SetValue(page, True)
        save_return = page.Save(True)
        committed_object = frame.GetDeviceObject(True)
    except Exception as exc:
        rollback = {"mappingRemoved": False, "visibilityRestored": False,
                    "pageReloaded": False, "errors": []}
        try:
            if mapping_added:
                rollback["mappingRemoved"] = bool(mapping_dict.Remove(""))
        except Exception as rollback_exc:
            rollback["errors"].append("mapping: " + repr(rollback_exc))
        try:
            if visibility_repaired:
                selected_item.bIsMappingVisable = visibility_before
                rollback["visibilityRestored"] = True
        except Exception as rollback_exc:
            rollback["errors"].append("visibility: " + repr(rollback_exc))
        try:
            change_field.SetValue(page, False)
            page.Reload()
            rollback["pageReloaded"] = True
        except Exception as rollback_exc:
            rollback["errors"].append("reload: " + repr(rollback_exc))
        raise OperationError("vendor EtherCAT PDO save failed: " + repr(exc),
                             "ethercat_pdo_save_failed",
                             {"entry": selected_snapshot, "existing": existing,
                              "rollback": rollback,
                              "mutatedProject": True,
                              "processDiscardRequired": True})

    generated_id = int(req.get("parameterId"))
    generated = None
    try:
        parameter_set = parent_connector.HostParameterSet
        generated = parameter_set.GetParameter(generated_id)
    except Exception:
        generated = None
    if generated is None:
        raise OperationError("vendor save did not generate the requested I/O channel",
                             "ethercat_io_channel_not_generated",
                             {"parameterId": generated_id, "entry": selected_snapshot,
                              "parentTarget": parent_target, "mutatedProject": True})
    generated_snapshot = _native_element_snapshot(generated, 0, 1)
    generated_mapping = _native_io_mapping_snapshot(generated)
    retained = variable in [row.get("variable")
                            for row in generated_mapping.get("variableMappings", [])]
    if not retained:
        raise OperationError("generated EtherCAT channel did not retain the requested mapping",
                             "ethercat_io_mapping_not_retained",
                             {"parameterId": generated_id,
                              "channel": generated_snapshot,
                              "ioMapping": generated_mapping,
                              "mutatedProject": True})
    return {
        "binding": "EthercatProcessDataPage.PDOITEM._dictMappingVariable + Save(true)",
        "target": req.get("target") or req.get("path") or req.get("device"),
        "mappingLocation": parent_target,
        "connectorId": connector_id,
        "parameterId": generated_id,
        "elementPath": [],
        "variable": variable,
        "pdoEntry": selected_snapshot,
        "existingPdoMappings": existing,
        "mappingVisibilityBefore": visibility_before,
        "mappingVisibilityRepaired": visibility_repaired,
        "generatedChannel": generated_snapshot,
        "afterObjectManagerCommit": generated_mapping,
        "saveReturn": _json_safe(save_return),
        "committedObjectType": (_text(committed_object.GetType().FullName)
                                if committed_object is not None else None),
        "retained": True,
        "committed": True,
        "mutatedProject": True,
        "status": "same_process_retained",
        "nextRequired": "project.save, fresh-process reopen, exact mapping readback, and second compile",
    }


def vendor_io_mapping_add(req):
    """Append one variable binding to an otherwise empty native I/O channel.

    This is intentionally an append-only experimental operation. Vendor pages
    use ``IDataElement.IoMapping.VariableMappings.AddMapping``; overwriting or
    deleting an existing binding is not exposed until it has its own audited
    vendor transaction and persistence evidence.
    """
    target = req.get("target") or req.get("path") or req.get("device")
    parameter_id = req.get("parameterId")
    element_path_present = "elementPath" in req or "field" in req
    element_path = req.get("elementPath") if "elementPath" in req else req.get("field")
    if element_path is None:
        element_path = []
    connector_id = req.get("connectorId", 1)
    variable = _text(req.get("variable") or "").strip()
    if not target or parameter_id is None or not element_path_present or not variable:
        raise OperationError("target, parameterId, elementPath, and variable are required",
                             "invalid_argument")
    # InoProShop's VariableMapping parser resolves the first segment as the
    # application name.  Bare variables and GVL-only paths are accepted by
    # AddMapping but fail later with "Invalid application" during build.  Fail
    # before mutating the project and return the exact format the compiler
    # accepts for this vendor profile.
    if not re.match(r"^Application\.[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$", variable):
        raise OperationError(
            "InoProShop mapping variables must use the full application-qualified format",
            "mapping_variable_format_invalid",
            {
                "path": "variable",
                "actual": variable,
                "correctFormat": "Application.<GVL_or_POU>.<IEC_variable>",
                "examples": [
                    "Application.MappingGVL.gInput",
                    "Application.PLC_PRG.gInput",
                ],
                "why": "the first segment is resolved as the application; shorter paths compile as Invalid application",
            },
        )
    if req.get("confirm") != "add_vendor_io_mapping":
        raise OperationError("confirm must exactly equal add_vendor_io_mapping",
                             "confirmation_required")
    _require_current_disposable_project(req, "vendor.io.mapping.add")
    try:
        parameter_id = int(parameter_id)
        connector_id = int(connector_id)
    except Exception:
        raise OperationError("parameterId and connectorId must be integers", "invalid_argument")
    pdo_contract = req.get("ethercatPdo")
    if pdo_contract is not None:
        if not isinstance(pdo_contract, dict):
            raise OperationError("ethercatPdo must be an object", "invalid_argument",
                                 {"path": "ethercatPdo"})
        return _ethercat_pdo_mapping_add(req, variable, pdo_contract)
    object_mgr, meta, native, binding = _native_device_object_with_retry(target, "modify")
    try:
        return _vendor_io_mapping_add_locked(req, object_mgr, meta, native,
                                             binding, parameter_id,
                                             connector_id, element_path,
                                             variable)
    except OperationError as exc:
        # ``_native_device_object_with_retry`` already performs the single
        # bounded GC/reacquire attempt.  When that attempt is exhausted it
        # returns the structured ``vendor_object_in_use`` error below; do not
        # classify that diagnostic as a fresh retry trigger here or one stale
        # handle would fan out into a third native acquisition attempt.  Raw
        # in-use failures raised by the mapping transaction itself still get
        # one outer recovery attempt.
        if (getattr(exc, "code", None) != "vendor_object_in_use" and
                _is_native_object_in_use_error(exc)):
            # A prior modify never released the object. Force a GC sweep and
            # retry once — without this, every retry fails the same way and
            # the caller loops pointlessly.
            _release_native_modify()
            object_mgr, meta, native, binding = _native_device_object_with_retry(target, "modify")
            return _vendor_io_mapping_add_locked(req, object_mgr, meta, native,
                                                 binding, parameter_id,
                                                 connector_id, element_path,
                                                 variable)
        raise


def _release_native_modify():
    """Drop pending 'modify' handles so a retried GetObjectToModify does not
    fail with the vendor's '对象已经使用' (object already in use)."""
    try:
        import System
        System.GC.Collect()
        System.GC.WaitForPendingFinalizers()
    except Exception:
        pass
    return None


def _native_device_object_with_retry(target, mode="modify"):
    """_native_device_object with a GC sweep and ONE retry on the vendor's
    '对象已经使用' (object already in use) — a previously failed transaction
    (a rejected io_add, a killed editor write) can leave the modify handle
    held, and every op that acquires a modify handle hits the same wall."""
    try:
        return _native_device_object(target, mode)
    except Exception as exc:
        if _is_native_object_in_use_error(exc):
            _release_native_modify()
            try:
                return _native_device_object(target, mode)
            except Exception as retry_exc:
                # The GC sweep released nothing (round-27 HSIO evidence): the
                # stale handle is held by the vendor object manager per
                # project handle and only a fresh process releases it. Fail
                # with the recovery step instead of an opaque handler_error.
                raise OperationError(
                    "vendor object is still in use after a GC sweep and retry; "
                    "the stale modify handle is held per project handle",
                    "vendor_object_in_use",
                    {"target": target, "mode": mode,
                     "cause": repr(retry_exc),
                     "recovery": "save, close, and reopen the project in a "
                                 "fresh IDE process, then retry the write",
                     "mutatedProject": False})
        raise


def _vendor_io_mapping_add_locked(req, object_mgr, meta, native, binding,
                                  parameter_id, connector_id, element_path,
                                  variable):
    """The actual mapping write, once a fresh modify handle is held."""
    target = req.get("target") or req.get("path") or req.get("device")
    element = _native_parameter_from_device(native, parameter_id, connector_id)
    element, parts = _native_element_at_path(element, element_path)
    mapping = _get_member(element, "IoMapping", "get_IoMapping")
    if mapping is None:
        mapping = _get_member(element, "io_mapping", "get_io_mapping")
    if mapping is None:
        raise OperationError("element has no native IoMapping", "io_mapping_unavailable",
                             {"target": target, "parameterId": parameter_id,
                              "elementPath": parts})
    mappings = _get_member(mapping, "VariableMappings", "get_VariableMappings")
    if mappings is None:
        mappings = _get_member(mapping, "variable_mappings", "get_variable_mappings")
    if mappings is None:
        raise OperationError("native IoMapping has no VariableMappings", "variable_mappings_unavailable")
    before = _native_io_mapping_snapshot(element)
    existing = _mapping_variables(mapping)
    if existing:
        raise OperationError(
            "refusing to overwrite an existing I/O mapping; read and use a dedicated replacement workflow",
            "io_mapping_not_empty",
            {"before": before, "existingCount": len(existing), "variable": variable})
    # _get_member invokes callables with zero arguments, which is correct for
    # property getters but would hide this two-argument method. Resolve the
    # callable directly before invoking it with the vendor contract.
    add_mapping = None
    try:
        add_mapping = getattr(mappings, "AddMapping")
    except Exception:
        try:
            add_mapping = getattr(mappings, "add_mapping")
        except Exception:
            add_mapping = None
    if add_mapping is None:
        raise OperationError("VariableMappings.AddMapping is unavailable", "mapping_add_unavailable",
                             {"runtimeType": _text(mappings.GetType().FullName)})
    create_variable = bool(req.get("createVariable", False))
    try:
        add_result = add_mapping(variable, create_variable)
    except Exception as exc:
        raise OperationError("VariableMappings.AddMapping failed: " + repr(exc),
                             "mapping_add_failed", {"variable": variable,
                                                    "createVariable": create_variable,
                                                    "before": before})
    after_add = _native_io_mapping_snapshot(element)
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed after AddMapping: " + repr(exc),
                             "mapping_commit_failed", {"before": before,
                                                       "afterAdd": after_add})
    read_mgr, read_meta, read_native, read_binding = _native_device_object(target, "read")
    read_element = _native_parameter_from_device(read_native, parameter_id, connector_id)
    read_element, read_parts = _native_element_at_path(read_element, parts)
    after_commit = _native_io_mapping_snapshot(read_element)
    read_variables = [item.get("variable") for item in after_commit.get("variableMappings", [])]
    retained = variable in read_variables
    return {
        "binding": binding,
        "readbackBinding": read_binding,
        "target": target,
        "connectorId": connector_id,
        "parameterId": parameter_id,
        "elementPath": read_parts,
        "variable": variable,
        "createVariable": create_variable,
        "before": before,
        "afterAdd": after_add,
        "afterObjectManagerCommit": after_commit,
        "addReturn": _json_safe(add_result),
        "commitReturn": _json_safe(commit_return),
        "retained": retained,
        "committed": True,
        "mutatedProject": True,
        "status": "same_process_retained" if retained else "same_process_not_retained",
        "nextRequired": "project.save, fresh-process reopen, exact mapping readback, and second compile are required before promotion",
    }


def vendor_device_parameter_read(req):
    target = req.get("target") or req.get("path") or req.get("device")
    parameter_id = req.get("parameterId")
    element_path = req.get("elementPath") or req.get("field") or []
    if not target or parameter_id is None:
        raise OperationError("target and parameterId are required", "invalid_argument")
    try:
        parameter_id = int(parameter_id)
    except Exception:
        raise OperationError("parameterId must be an integer", "invalid_argument")
    connector_id = req.get("connectorId", 1)
    try:
        connector_id = int(connector_id)
    except Exception:
        raise OperationError("connectorId must be an integer", "invalid_argument")
    _object_mgr, _meta, native, binding = _native_device_object(target, "read")
    element = _native_parameter_from_device(native, parameter_id, connector_id)
    element, parts = _native_element_at_path(element, element_path)
    return {"binding": binding, "target": target, "connectorId": connector_id,
            "parameterId": parameter_id, "elementPath": parts,
            "value": _native_element_value(element),
            "snapshot": _native_element_snapshot(element, 0, 1),
            "mutatedProject": False, "status": "observed"}


def vendor_device_parameter_probe(req):
    """Read the native IDataElement tree behind a vendor editor."""
    target = req.get("target") or req.get("path") or req.get("device")
    if not target:
        raise OperationError("vendor.device.parameter.probe requires target", "invalid_argument")
    _object_mgr, _meta, native, binding = _native_device_object(target, "read")
    try:
        connectors = native.Connectors
    except Exception:
        connectors = _get_member(native, "connectors", "get_Connectors")
    values = []
    all_parameter_locations = {}
    requested_ids = req.get("parameterIds") or []
    if not isinstance(requested_ids, list):
        raise OperationError("parameterIds must be an array", "invalid_argument",
                             {"path": "parameterIds"})
    try:
        requested_ids = sorted(set(int(value) for value in requested_ids))
    except Exception:
        raise OperationError("parameterIds must contain integers", "invalid_argument",
                             {"path": "parameterIds"})
    for index, connector in enumerate(list(connectors) if connectors is not None else []):
        native_connector_id = _get_member(
            connector, "ConnectorId", "get_ConnectorId")
        entry = {"connectorIndex": index,
                 "connectorId": _json_safe(native_connector_id),
                 "runtimeType": _text(connector.GetType().FullName)}
        for key, names in (
                ("interfaceName", ("InterfaceName", "get_InterfaceName", "interface_name")),
                ("visibleInterfaceName", ("VisibleInterfaceName", "get_VisibleInterfaceName", "visible_interface_name")),
                ("connectorType", ("ConnectorType", "get_ConnectorType", "connector_type")),
                ("role", ("Role", "get_Role", "role"))):
            for name in names:
                value = _get_member(connector, name)
                if value is not None and _text(value) != "":
                    entry[key] = _json_safe(value)
                    break
        try:
            parameter_set = connector.HostParameterSet
        except Exception:
            parameter_set = _get_member(connector, "host_parameter_set", "get_HostParameterSet")
        if parameter_set is not None:
            entry["parameterSetType"] = _text(parameter_set.GetType().FullName)
            params = []
            seen_ids = set()
            enumeration_error = None
            enumeration_succeeded = False
            try:
                enumerated = list(parameter_set)
                enumeration_succeeded = True
            except Exception as exc:
                enumerated = []
                enumeration_error = repr(exc)
            for item in enumerated:
                parameter_id = _get_member(item, "Id", "get_Id")
                try:
                    parameter_id = int(parameter_id)
                except Exception:
                    parameter_id = None
                if parameter_id is None or parameter_id in seen_ids:
                    continue
                seen_ids.add(parameter_id)
                all_parameter_locations.setdefault(parameter_id, []).append(index)
                params.append({"id": parameter_id,
                               "element": _native_element_snapshot(
                                   item, 0, int(req.get("depth", 2))),
                               "ioMapping": _native_io_mapping_snapshot(item)})
            # Exact supplemental IDs cover older parameter-set wrappers that
            # enumerate only their legacy section while still supporting
            # GetParameter for generated protocol IDs.
            supplement = requested_ids
            if not enumeration_succeeded and not requested_ids:
                supplement = list(range(0, 16384))
            for parameter_id in supplement:
                if parameter_id in seen_ids:
                    continue
                try:
                    item = parameter_set.GetParameter(parameter_id)
                except Exception:
                    try:
                        item = parameter_set.GetParameter(long(parameter_id))
                    except Exception:
                        item = None
                if item is None:
                    continue
                seen_ids.add(parameter_id)
                all_parameter_locations.setdefault(parameter_id, []).append(index)
                params.append({"id": parameter_id,
                               "element": _native_element_snapshot(
                                   item, 0, int(req.get("depth", 2))),
                               "ioMapping": _native_io_mapping_snapshot(item)})
            params.sort(key=lambda row: row["id"])
            entry["parameters"] = params
            entry["parameterCount"] = len(params)
            entry["parameterIdMinimum"] = params[0]["id"] if params else None
            entry["parameterIdMaximum"] = params[-1]["id"] if params else None
            entry["parameterEnumeration"] = {
                "mode": "native_collection" if enumeration_succeeded else "legacy_scan_fallback",
                "complete": bool(enumeration_succeeded),
                "nativeCount": len(enumerated),
                "supplementalIds": requested_ids,
                "error": enumeration_error,
            }
        else:
            entry["parameters"] = []
            entry["parameterCount"] = 0
            entry["parameterIdMinimum"] = None
            entry["parameterIdMaximum"] = None
            entry["parameterEnumeration"] = {
                "mode": "no_host_parameter_set",
                "complete": True,
                "nativeCount": 0,
                "supplementalIds": requested_ids,
                "error": None,
            }
        values.append(entry)
    all_parameter_ids = sorted(all_parameter_locations)
    duplicate_ids = [
        {"id": parameter_id,
         "connectorIndexes": all_parameter_locations[parameter_id]}
        for parameter_id in all_parameter_ids
        if len(all_parameter_locations[parameter_id]) > 1
    ]
    identity = _get_member(native, "DeviceIdentification", "get_DeviceIdentification")
    if identity is None:
        identity = _get_member(native, "device_identification", "get_DeviceIdentification")
    mapping_parameter_count = 0
    addressed_parameter_count = 0
    for connector_entry in values:
        for parameter_entry in connector_entry.get("parameters", []):
            mapping = parameter_entry.get("ioMapping") or {}
            if mapping.get("available"):
                mapping_parameter_count += 1
            if _text(mapping.get("iecAddress")):
                addressed_parameter_count += 1
    return {
        "projectPath": _project_path(),
        "scenario": _text(req.get("scenario")),
        "target": target,
        "objectName": _text(_get_member(native, "Name", "get_Name") or
                            _get_member(native, "name", "get_Name")),
        "deviceId": _device_identity(identity),
        "binding": binding,
        "connectorCount": len(values),
        "connectors": values,
        "parameterInventory": {
            "complete": all(
                item.get("parameterEnumeration", {}).get("complete", False)
                for item in values
            ),
            "uniqueParameterCount": len(all_parameter_ids),
            "allParameterIds": all_parameter_ids,
            "duplicateParameterIds": duplicate_ids,
            "ioMappingParameterCount": mapping_parameter_count,
            "addressedParameterCount": addressed_parameter_count,
        },
        "mutatedProject": False,
        "status": "observed",
    }


def vendor_object_list(req):
    """List native ObjectMgr stubs to correlate ScriptEngine and vendor GUIDs."""
    _require_project()
    object_mgr, probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable", "object_manager_unavailable", {"probe": probe})
    handle = 0
    try:
        values = list(object_mgr.GetAllObjects(int(handle)))
    except Exception as exc:
        raise OperationError("ObjectMgr.GetAllObjects failed: " + repr(exc), "object_enumeration_failed")
    result = []
    wanted = _text(req.get("name") or req.get("target") or "").lower()
    for guid in values:
        try:
            stub = object_mgr.GetMetaObjectStub(int(handle), guid)
            name = _text(stub.Name) if stub is not None else ""
            typ = _text(stub.ObjectType.FullName) if stub is not None else ""
            if wanted and wanted not in name.lower() and wanted not in typ.lower():
                continue
            result.append({"guid": _text(guid), "name": name, "objectType": typ})
        except Exception as exc:
            result.append({"guid": _text(guid), "error": repr(exc)})
    return {"handle": handle, "count": len(result), "objects": result, "mutatedProject": False, "status": "observed"}


