PID_PAGE_TYPES = set(item["pageType"] for item in PID_DEVICE_CONTRACTS.values())
PID_CONTROL_FIELDS = set(field for item in PID_DEVICE_CONTRACTS.values()
                         for field in item["fields"])


def _pid_contract(module_type):
    try:
        return PID_DEVICE_CONTRACTS.get(int(module_type))
    except Exception:
        return None


def _pid_identity_value(value, names):
    for name in names:
        result = _get_member(value, name, "get_" + name)
        if result is not None:
            return result
    return None


def _pid_runtime_identity(script_object, native, binding, frame=None):
    """Read identity facts without falling back to display names."""
    identity = _pid_identity_value(native, ("device_identification", "DeviceIdentification"))
    if identity is None:
        identity = _pid_identity_value(script_object, ("device_identification", "DeviceIdentification"))
    observed = {
        "type": _json_safe(_pid_identity_value(identity, ("type", "Type"))) if identity is not None else None,
        "id": _text(_pid_identity_value(identity, ("id", "Id"))) if identity is not None else "",
        "version": _text(_pid_identity_value(identity, ("version", "Version"))) if identity is not None else "",
    }
    interface = _pid_identity_value(native, ("interface", "Interface", "device_interface", "DeviceInterface"))
    if interface is None:
        interface = _pid_identity_value(script_object, ("interface", "Interface", "device_interface", "DeviceInterface"))
    observed["interface"] = _text(interface) if interface is not None else ""
    connector_ids = []
    connector_interfaces = {}
    live_connectors = list(_native_connector_list(native))
    if frame is not None:
        try:
            editor_device = frame.GetDeviceObject(False)
            live_connectors.extend(_native_connector_list(editor_device))
        except Exception:
            pass
        # Vendor-created local modules can expose no connectors through the
        # ObjectMgr wrapper while the live DeviceEditor frame exposes both.
        # Read the two required identities from that frame; do not substitute
        # values from PID_DEVICE_CONTRACTS.
        for connector_id in (1, 2):
            try:
                connector = frame.GetConnector(connector_id, False)
                if connector is not None:
                    live_connectors.append(connector)
            except Exception:
                pass
    for connector in live_connectors:
        connector_id = _pid_identity_value(connector, ("connector_id", "ConnectorId"))
        try:
            connector_ids.append(int(connector_id))
        except Exception:
            pass
        interface = _pid_identity_value(connector, ("interface", "Interface"))
        if connector_id is not None and interface is not None and _text(interface):
            try:
                connector_interfaces[int(connector_id)] = _text(interface)
            except Exception:
                pass
    observed["connectorIds"] = sorted(set(connector_ids))
    observed["parentConnectorId"] = (2 if 2 in observed["connectorIds"] else None)
    observed["localBusConnectorId"] = (1 if 1 in observed["connectorIds"] else None)
    return {
        "deviceId": {"type": observed["type"], "id": observed["id"], "version": observed["version"]},
        "interface": connector_interfaces.get(2, observed["interface"]),
        "parentConnectorId": observed["parentConnectorId"],
        "localBusConnectorId": observed["localBusConnectorId"],
        "localBusInterface": connector_interfaces.get(1, ""),
        "connectorIds": observed["connectorIds"],
        "binding": binding,
    }


def _pid_validate_identity(observed):
    """Return (contract, checks) and never accept partial identity evidence."""
    device_id = observed.get("deviceId") or {}
    module_type = device_id.get("type")
    contract = _pid_contract(module_type)
    checks = {"accepted": False, "missing": [], "mismatches": [], "moduleType": module_type}
    if contract is None:
        checks["mismatches"].append({"field": "deviceId.type", "expected": sorted(PID_DEVICE_CONTRACTS), "actual": module_type})
        return None, checks
    expected_id = contract["deviceId"]
    for field in ("type", "id", "version"):
        actual = device_id.get(field)
        if actual in (None, ""):
            checks["missing"].append("deviceId." + field)
        else:
            try:
                matches = (int(actual) == int(expected_id[field])) if field == "type" else (_text(actual).upper() == expected_id[field].upper())
            except Exception:
                matches = False
            if not matches:
                checks["mismatches"].append({"field": "deviceId." + field, "expected": expected_id[field], "actual": actual})
    for field in ("interface", "parentConnectorId", "localBusConnectorId", "localBusInterface"):
        actual = observed.get(field)
        expected = contract[field]
        if actual in (None, ""):
            checks["missing"].append(field)
        else:
            try:
                matches = (_text(actual).lower() == _text(expected).lower()) if field in ("interface", "localBusInterface") else (int(actual) == int(expected))
            except Exception:
                matches = False
            if not matches:
                checks["mismatches"].append({"field": field, "expected": expected, "actual": actual})
    checks["accepted"] = not checks["missing"] and not checks["mismatches"]
    return (contract if checks["accepted"] else None), checks


def _pid_identity_error(target, observed, checks):
    return OperationError(
        "target is not an exact installed Inovance PID module identity",
        "pid_module_identity_unsupported",
        {"target": target, "resolvedIdentity": observed, "validation": checks,
         "mutatedProject": False, "next": "use a disposable vendor-wizard project and pass the exact 41053/41054 device path"},
    )


def _runtime_type_detail(value, include_members=True):
    """Return bounded CLR type metadata without invoking arbitrary methods."""
    if value is None:
        return None
    result = {"runtimeType": _text(value.GetType().FullName)}
    if not include_members:
        return result
    try:
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Public)
        typ = value.GetType()
        result["interfaces"] = sorted(set(_text(item.FullName)
            for item in typ.GetInterfaces()))
        result["properties"] = sorted(set(_text(item.Name)
            for item in typ.GetProperties(flags)))[:200]
        result["methods"] = sorted(set(_text(item.Name)
            for item in typ.GetMethods(flags)))[:300]
    except Exception as exc:
        result["reflectionError"] = repr(exc)
    return result


def _native_editor_frame_snapshot(view, target_name):
    """Describe an already-open editor view and its frame without mutation."""
    entry = {"target": target_name, "view": _runtime_type_detail(view)}
    frame = view
    # Most vendor views implement IDeviceEditorFrame directly.  Some wrappers
    # expose the frame as a property, so inspect both forms without constructing
    # a new editor.
    for name in ("DeviceEditorFrame", "device_editor_frame", "ConnectorEditorFrame",
                 "connector_editor_frame"):
        candidate = _get_member(view, name, "get_" + name)
        if candidate is not None:
            frame = candidate
            entry["frameBinding"] = name
            break
    entry["frame"] = _runtime_type_detail(frame)
    for method_name in ("GetDeviceObject", "GetAssociatedDeviceObject"):
        method = getattr(frame, method_name, None)
        if method is None:
            continue
        entry.setdefault("frameMethods", []).append(method_name)
        try:
            device = method(False)
            entry.setdefault("readBindings", []).append({
                "method": method_name,
                "runtimeType": _text(device.GetType().FullName) if device is not None else None,
                "name": _object_name(device) if device is not None else None,
            })
        except Exception as exc:
            entry.setdefault("readBindings", []).append({
                "method": method_name, "error": repr(exc),
            })
    editor = _get_member(view, "Editor", "get_Editor")
    if editor is not None:
        entry["editor"] = _runtime_type_detail(editor)
        for key, names in (
            ("objectGuid", ("ObjectGuid", "object_guid", "get_ObjectGuid")),
            ("projectHandle", ("ProjectHandle", "project_handle", "get_ProjectHandle")),
            ("caption", ("Caption", "caption", "get_Caption")),
            ("description", ("Description", "description", "get_Description")),
        ):
            for name in names:
                value = _get_member(editor, name)
                if value is not None:
                    entry["editor"][key] = _json_safe(value)
                    break
    base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
    if base_editors is not None:
        try:
            entry["baseEditors"] = []
            for base_editor in list(base_editors):
                item = {
                    "runtimeType": _text(base_editor.GetType().FullName),
                    "type": _runtime_type_detail(base_editor, False),
                }
                for key, names in (
                    ("connectorId", ("ConnectorId", "connector_id", "get_ConnectorId")),
                    ("hideGenericEditor", ("HideGenericEditor", "hide_generic_editor", "get_HideGenericEditor")),
                ):
                    for name in names:
                        value = _get_member(base_editor, name)
                        if value is not None:
                            item[key] = _json_safe(value)
                            break
                pages = _get_member(base_editor, "Pages", "get_Pages")
                if pages is not None:
                    try:
                        item["pages"] = []
                        for page in list(pages):
                            page_item = {"runtimeType": _text(page.GetType().FullName)}
                            for key, names in (
                                ("pageIdentifier", ("PageIdentifier", "page_identifier", "get_PageIdentifier")),
                                ("pageName", ("PageName", "page_name", "get_PageName")),
                            ):
                                for name in names:
                                    value = _get_member(page, name)
                                    if value is not None:
                                        page_item[key] = _json_safe(value)
                                        break
                            item["pages"].append(page_item)
                    except Exception as exc:
                        item["pagesError"] = repr(exc)
                entry["baseEditors"].append(item)
        except Exception as exc:
            entry["baseEditorsError"] = repr(exc)
    return entry


def _positioned_diagnostic(message):
    """Return whether a structured message identifies source code location."""
    if message.get("severity") not in ("error", "warning"):
        return False
    return bool(message.get("position") or
                message.get("positionOffset") not in (None, "", "-1"))


def vendor_editor_probe(req):
    """Inspect live vendor editor views; never opens a view or mutates a project."""
    _require_project()
    frame, frame_probe = _system_instances_property("Engine")
    if frame is None:
        raise OperationError("SystemInstances.Engine is unavailable",
                             "engine_unavailable", {"probe": frame_probe})
    root_frame = _get_member(frame, "Frame", "get_Frame")
    if root_frame is None:
        raise OperationError("SystemInstances.Engine.Frame is unavailable",
                             "frame_unavailable", {"engine": frame_probe})
    try:
        views = list(root_frame.GetViews())
    except Exception as exc:
        raise OperationError("Engine.Frame.GetViews failed: " + repr(exc),
                             "view_enumeration_failed")
    wanted = _text(req.get("target") or req.get("name") or "").lower()
    entries = []
    for view in views:
        detail = _native_editor_frame_snapshot(view, _object_name(view))
        if wanted and wanted not in _text(detail).lower():
            continue
        entries.append(detail)
    active = _get_member(root_frame, "ActiveView", "get_ActiveView")
    return {
        "viewCount": len(views),
        "activeView": _runtime_type_detail(active),
        "views": entries,
        "factoryGuids": VENDOR_EDITOR_FACTORIES,
        "mutatedProject": False,
        "status": "observed",
        "next": "open an editor explicitly, then rerun this probe to obtain its frame",
    }


def vendor_editor_open(req):
    """Open a vendor editor through Engine.Frame.OpenEditorView.

    Opening is intentionally separate from save: it may initialize a vendor
    page and may surface a native popup, but it does not change project data by
    itself.  The factory GUID must be supplied explicitly or selected from the
    checked-in reverse-engineering table.
    """
    _require_project()
    target = req.get("target") or req.get("device") or req.get("path")
    if not target:
        raise OperationError("target is required", "invalid_argument")
    factory_guid = req.get("factoryGuid") or req.get("factory")
    if not factory_guid:
        factory_key = _text(req.get("factoryKey") or "").lower()
        factory_guid = VENDOR_EDITOR_FACTORIES.get(factory_key)
    if not factory_guid:
        raise OperationError("factoryGuid or known factoryKey is required",
                             "invalid_argument", {
                                 "factoryGuids": VENDOR_EDITOR_FACTORIES,
                             })
    import System
    _object_mgr, _meta, _native, binding = _native_device_object(target, "read")
    handle = int(binding.get("projectHandle"))
    object_mgr, object_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": object_probe})
    try:
        native_guid = System.Guid(_text(binding.get("nativeGuid")))
        stub = object_mgr.GetMetaObjectStub(handle, native_guid)
    except Exception as exc:
        raise OperationError("GetMetaObjectStub failed: " + repr(exc),
                             "meta_object_stub_unavailable", {
                                 "target": target, "binding": binding,
                             })
    if stub is None:
        raise OperationError("native meta object stub is null",
                             "meta_object_stub_unavailable", {
                                 "target": target, "binding": binding,
                             })
    stub_detail = _runtime_type_detail(stub, False)
    # MetaObjectStub implementations expose these as properties in different
    # SP11 builds.  Capture them so a failed OpenEditorView is diagnosable.
    for key, names in (
        ("guid", ("ObjectGuid", "Guid", "guid", "get_ObjectGuid")),
        ("parentGuid", ("ParentObjectGuid", "parent_object_guid", "get_ParentObjectGuid")),
        ("name", ("Name", "name", "get_Name")),
        ("objectType", ("ObjectType", "object_type", "get_ObjectType")),
    ):
        for name in names:
            value = _get_member(stub, name)
            if value is not None:
                if key == "objectType":
                    value = _get_member(value, "FullName", "get_FullName", value)
                stub_detail[key] = _json_safe(value)
                break
    engine, engine_probe = _system_instances_property("Engine")
    root_frame = _get_member(engine, "Frame", "get_Frame") if engine is not None else None
    if root_frame is None:
        raise OperationError("SystemInstances.Engine.Frame is unavailable",
                             "frame_unavailable", {"probe": engine_probe})
    try:
        view = root_frame.OpenEditorView(
            stub, System.Guid(_text(factory_guid)), None)
    except Exception as exc:
        raise OperationError("Engine.Frame.OpenEditorView failed: " + repr(exc),
                             "editor_open_failed", {
                                 "target": target,
                                 "factoryGuid": _text(factory_guid),
                                 "binding": binding,
                                 "stub": stub_detail,
                             })
    if view is None:
        raise OperationError("OpenEditorView returned null",
                             "editor_view_unavailable", {
                                 "target": target,
                                 "factoryGuid": _text(factory_guid),
                                 "binding": binding,
                                 "stub": stub_detail,
                             })
    return {
        "target": target,
        "factoryGuid": _text(factory_guid),
        "nativeBinding": binding,
        "stub": stub_detail,
        "view": _native_editor_frame_snapshot(view, _object_name(view)),
        "mutatedProject": False,
        "status": "editor_opened",
        "note": "未处理任何弹窗；如有弹窗，调用方必须先读取 dialogs.detect",
    }


def vendor_editor_manager_probe(req):
    """Inspect Engine.EditorManager editors and overloads used by vendor code."""
    _require_project()
    engine, probe = _system_instances_property("Engine")
    manager = _get_member(engine, "EditorManager", "get_EditorManager") if engine is not None else None
    if manager is None:
        raise OperationError("Engine.EditorManager is unavailable",
                             "editor_manager_unavailable", {"probe": probe})
    result = {"manager": _runtime_type_detail(manager), "editors": [],
              "methodSignatures": [], "mutatedProject": False}
    try:
        for method in manager.GetType().GetMethods():
            if _text(method.Name) not in ("AddEditor", "CloseEditor",
                                          "GetEditors", "SaveEditor",
                                          "SaveAllEditors", "Initialize"):
                continue
            result["methodSignatures"].append({
                "name": _text(method.Name),
                "returnType": _text(method.ReturnType.FullName),
                "parameters": [{
                    "name": _text(parameter.Name),
                    "type": _text(parameter.ParameterType.FullName),
                } for parameter in method.GetParameters()],
            })
    except Exception as exc:
        result["methodSignatureError"] = repr(exc)
    try:
        editors = list(manager.GetEditors())
    except Exception as exc:
        result["getEditorsError"] = repr(exc)
        editors = []
    for editor in editors:
        detail = _runtime_type_detail(editor)
        for key, names in (
            ("objectGuid", ("ObjectGuid", "object_guid", "get_ObjectGuid")),
            ("projectHandle", ("ProjectHandle", "project_handle", "get_ProjectHandle")),
        ):
            for name in names:
                value = _get_member(editor, name)
                if value is not None:
                    detail[key] = _json_safe(value)
                    break
        result["editors"].append(detail)
    result["editorCount"] = len(result["editors"])
    result["status"] = "observed"
    return result


def _vendor_editor_normalized_guid(value):
    value = _text(value).strip().lower()
    if value.startswith("{") and value.endswith("}"):
        value = value[1:-1]
    if value == "00000000-0000-0000-0000-000000000000":
        return ""
    return value


def _vendor_editor_frame(view):
    """Return the DeviceEditor frame carried by a view or editor wrapper."""
    frame = view
    for name in ("DeviceEditorFrame", "device_editor_frame",
                 "ConnectorEditorFrame", "connector_editor_frame"):
        candidate = _get_member(view, name, "get_" + name)
        if candidate is not None:
            frame = candidate
            break
    return frame


def _vendor_editor_object_guids(view, frame=None):
    """Read every exact object GUID exposed by an editor/view wrapper."""
    if frame is None:
        frame = _vendor_editor_frame(view)
    owners = []
    for owner in (view, frame):
        if owner is not None and owner not in owners:
            owners.append(owner)
        editor = _get_member(owner, "Editor", "get_Editor")
        if editor is not None and editor not in owners:
            owners.append(editor)
    guids = []
    for owner in owners:
        for property_name, getter_name in (
                ("ObjectGuid", "get_ObjectGuid"),
                ("object_guid", "get_object_guid")):
            value = _get_member(owner, property_name, getter_name)
            guid = _vendor_editor_normalized_guid(value)
            if guid and guid not in guids:
                guids.append(guid)
    return guids


def _vendor_editor_same_instance(left, right):
    """Compare CLR editor references without depending on wrapper identity."""
    if left is right:
        return True
    for first, second in ((left, right), (right, left)):
        equals = getattr(first, "Equals", None)
        if equals is None:
            continue
        try:
            if bool(equals(second)):
                return True
        except Exception:
            pass
    return False


def _vendor_editor_pages(frame):
    """Return bounded page identity data used to select the right factory view."""
    pages = []
    base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
    try:
        editors = list(base_editors or [])
    except Exception:
        return pages
    for base_editor in editors:
        native_pages = _get_member(base_editor, "Pages", "get_Pages")
        try:
            native_pages = list(native_pages or [])
        except Exception:
            continue
        for page in native_pages:
            try:
                runtime_type = _text(page.GetType().FullName)
            except Exception:
                runtime_type = ""
            page_name = _text(_get_member(page, "PageName", "get_PageName"))
            pages.append({"runtimeType": runtime_type, "pageName": page_name})
    return pages


def _vendor_editor_has_page(pages, requested_page):
    wanted = _text(requested_page).strip().lower()
    if not wanted:
        return False
    for page in pages:
        if (wanted in _text(page.get("runtimeType")).lower() or
                wanted == _text(page.get("pageName")).lower()):
            return True
    return False


def _open_vendor_editor_match(req):
    """Return the authoritative open DeviceEditor for one exact object GUID."""
    engine, probe = _system_instances_property("Engine")
    root_frame = _get_member(engine, "Frame", "get_Frame") if engine is not None else None
    if root_frame is None:
        raise OperationError("SystemInstances.Engine.Frame is unavailable",
                             "frame_unavailable", {"probe": probe})
    target_raw = req.get("target") or req.get("name") or ""
    if not _text(target_raw).strip():
        raise OperationError("target is required", "invalid_argument",
                             {"path": "target"})
    target_obj, target_path = find_project_object(target_raw)
    target_guid = _vendor_editor_normalized_guid(_object_guid(target_obj))
    if not target_guid:
        raise OperationError("target object has no stable GUID",
                             "editor_target_guid_unavailable", {
                                 "target": target_path,
                             })

    raw_candidates = []
    manager_error = None
    manager = _get_member(engine, "EditorManager", "get_EditorManager")
    if manager is not None:
        try:
            raw_candidates.extend(("editor_manager", item)
                                  for item in list(manager.GetEditors()))
        except Exception as exc:
            manager_error = repr(exc)
    active_view = _get_member(root_frame, "ActiveView", "get_ActiveView")
    if active_view is not None:
        raw_candidates.append(("active_view", active_view))
    view_error = None
    try:
        raw_candidates.extend(("frame_view", item)
                              for item in list(root_frame.GetViews()))
    except Exception as exc:
        view_error = repr(exc)

    requested_page = req.get("pageType")

    def scan_candidates(candidates, wanted_guid):
        exact_raw_count = 0
        observed_guids = []
        matches = []
        for source, view in candidates:
            frame = _vendor_editor_frame(view)
            editor = _get_member(frame, "Editor", "get_Editor")
            identity = editor if editor is not None else frame
            guids = _vendor_editor_object_guids(view, frame)
            for guid in guids:
                if guid not in observed_guids:
                    observed_guids.append(guid)
            if wanted_guid not in guids:
                continue
            exact_raw_count += 1
            duplicate = None
            for item in matches:
                if _vendor_editor_same_instance(identity, item["identity"]):
                    duplicate = item
                    break
            if duplicate is not None:
                if source not in duplicate["sources"]:
                    duplicate["sources"].append(source)
                continue
            detail = _native_editor_frame_snapshot(view, _object_name(view))
            # Only DeviceEditor views expose the frame methods used by vendor
            # connector editors. Avoid navigator/toolbox views with the same
            # object GUID.
            if "_3S.CoDeSys.DeviceEditor.IDeviceEditorFrame" not in _text(detail):
                continue
            is_disposed = _get_member(frame, "IsDisposed", "get_IsDisposed")
            disposing = _get_member(frame, "Disposing", "get_Disposing")
            if bool(is_disposed) or bool(disposing):
                continue
            matches.append({
                "view": view,
                "frame": frame,
                "identity": identity,
                "detail": detail,
                "sources": [source],
                "pages": _vendor_editor_pages(frame),
            })
        return matches, exact_raw_count, observed_guids

    matches, exact_raw_count, observed_guids = scan_candidates(
        raw_candidates, target_guid)
    opened_exact_target = False
    script_target_guid = target_guid
    native_binding = None
    if not matches:
        # A read operation must not depend on the operator having opened or
        # cleaned up a particular editor tab. Resolve the native object that
        # owns the editor, prefer its exact GUID if ScriptEngine wraps it, and
        # create the verified generic DeviceEditor view only when no matching
        # cached view exists.
        object_mgr, _meta, _native, native_binding = _native_device_object(
            target_raw, "read")
        native_target_guid = _vendor_editor_normalized_guid(
            native_binding.get("nativeGuid"))
        if not native_target_guid:
            raise OperationError("native target object has no stable GUID",
                                 "editor_target_guid_unavailable", {
                                     "target": target_path,
                                     "scriptTargetGuid": script_target_guid,
                                     "binding": native_binding,
                                 })
        target_guid = native_target_guid
        matches, exact_raw_count, observed_guids = scan_candidates(
            raw_candidates, target_guid)
        if not matches:
            import System
            handle = int(native_binding.get("projectHandle"))
            try:
                native_guid = System.Guid(_text(native_binding.get("nativeGuid")))
                stub = object_mgr.GetMetaObjectStub(handle, native_guid)
            except Exception as exc:
                raise OperationError("GetMetaObjectStub failed: " + repr(exc),
                                     "meta_object_stub_unavailable", {
                                         "target": target_path,
                                         "targetGuid": target_guid,
                                         "binding": native_binding,
                                     })
            if stub is None:
                raise OperationError("native meta object stub is null",
                                     "meta_object_stub_unavailable", {
                                         "target": target_path,
                                         "targetGuid": target_guid,
                                         "binding": native_binding,
                                     })
            factory_guid = VENDOR_EDITOR_FACTORIES["device_editor"]
            try:
                opened_view = root_frame.OpenEditorView(
                    stub, System.Guid(factory_guid), None)
            except Exception as exc:
                raise OperationError(
                    "Engine.Frame.OpenEditorView failed: " + repr(exc),
                    "editor_open_failed", {
                        "target": target_path,
                        "targetGuid": target_guid,
                        "factoryGuid": factory_guid,
                        "binding": native_binding,
                    })
            if opened_view is None:
                raise OperationError("OpenEditorView returned null",
                                     "editor_view_unavailable", {
                                         "target": target_path,
                                         "targetGuid": target_guid,
                                         "factoryGuid": factory_guid,
                                         "binding": native_binding,
                                     })
            opened_exact_target = True
            raw_candidates.append(("opened_exact_target", opened_view))
            matches, exact_raw_count, observed_guids = scan_candidates(
                raw_candidates, target_guid)
    if not matches:
        raise OperationError(
            "device editor did not bind to the exact target GUID",
            "editor_view_target_mismatch", {
                "target": target_path,
                "targetGuid": target_guid,
                "scriptTargetGuid": script_target_guid,
                "exactCandidateCount": exact_raw_count,
                "observedEditorGuids": sorted(observed_guids),
                "managerError": manager_error,
                "viewEnumerationError": view_error,
                "openedExactTarget": opened_exact_target,
                "binding": native_binding,
            })

    def selection_rank(item):
        sources = item["sources"]
        visible = _get_member(item["frame"], "Visible", "get_Visible")
        return (
            1 if _vendor_editor_has_page(item["pages"], requested_page) else 0,
            1 if "editor_manager" in sources else 0,
            1 if "active_view" in sources else 0,
            1 if visible is True else 0,
            len(item["pages"]),
        )

    selected = max(matches, key=selection_rank)
    detail = selected["detail"]
    if isinstance(detail, dict):
        detail["selection"] = {
            "target": target_path,
            "targetGuid": target_guid,
            "scriptTargetGuid": script_target_guid,
            "exactGuidMatch": True,
            "openedExactTarget": opened_exact_target,
            "requestedPage": _text(requested_page) or None,
            "requestedPageMatched": _vendor_editor_has_page(
                selected["pages"], requested_page),
            "rawExactCandidateCount": exact_raw_count,
            "deduplicatedCandidateCount": len(matches),
            "sources": selected["sources"],
        }
    return selected["view"], selected["frame"], detail


def vendor_editor_parameter_probe(req):
    """Read connector/parameter trees from a live generic DeviceEditor frame."""
    _require_project()
    _view, frame, detail = _open_vendor_editor_match(req)
    connector_ids = []
    try:
        device = frame.GetDeviceObject(False)
        for connector in list(device.Connectors):
            value = _get_member(connector, "ConnectorId", "get_ConnectorId")
            if value is not None and int(value) not in connector_ids:
                connector_ids.append(int(value))
    except Exception:
        device = None
    base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
    try:
        for base_editor in list(base_editors or []):
            value = _get_member(base_editor, "ConnectorId", "get_ConnectorId")
            if value is not None and int(value) not in connector_ids:
                connector_ids.append(int(value))
    except Exception:
        pass
    connector_entries = []
    for connector_id in sorted(connector_ids):
        connector = None
        try:
            connector = frame.GetConnector(connector_id, False)
        except Exception as exc:
            connector_entries.append({"connectorId": connector_id,
                                       "error": repr(exc)})
            continue
        if connector is None:
            connector_entries.append({"connectorId": connector_id,
                                       "status": "null"})
            continue
        entry = {
            "connectorId": connector_id,
            "runtimeType": _text(connector.GetType().FullName),
            "moduleType": _json_safe(_get_member(connector, "ModuleType", "get_ModuleType")),
            "connectorRole": _json_safe(_get_member(connector, "ConnectorRole", "get_ConnectorRole")),
            "parameterSet": [],
        }
        parameter_set = _get_member(connector, "HostParameterSet", "get_HostParameterSet")
        if parameter_set is not None:
            for parameter_id in range(0, 16384):
                try:
                    parameter = parameter_set.GetParameter(parameter_id)
                except Exception:
                    parameter = None
                if parameter is not None:
                    entry["parameterSet"].append({
                        "id": parameter_id,
                        "element": _native_element_snapshot(parameter, 0, int(req.get("depth", 2))),
                    })
        connector_entries.append(entry)
    return {
        "target": req.get("target") or req.get("name"),
        "editor": detail,
        "connectorCount": len(connector_entries),
        "connectors": connector_entries,
        "mutatedProject": False,
        "status": "observed",
    }


def _editor_connector_parameter(frame, req, writable=False):
    """Resolve a parameter through the same connector frame the UI uses."""
    parameter_id = req.get("parameterId")
    if parameter_id is None:
        raise OperationError("parameterId is required", "invalid_argument")
    try:
        parameter_id = int(parameter_id)
    except Exception:
        raise OperationError("parameterId must be an integer", "invalid_argument")
    requested_connector = req.get("connectorId")
    connector_ids = []
    if requested_connector is not None:
        try:
            connector_ids = [int(requested_connector)]
        except Exception:
            raise OperationError("connectorId must be an integer", "invalid_argument")
    else:
        device = frame.GetDeviceObject(False)
        if device is None:
            raise OperationError(
                "editor frame returned no device object for connector "
                "enumeration",
                "editor_device_object_unavailable",
                {"frameRuntimeType": _text(frame.GetType().FullName)
                 if frame is not None else None,
                 "recovery": "pass an explicit connectorId, or target the "
                             "parent config device instead of a child "
                             "specialized object"})
        for connector in list(device.Connectors):
            value = _get_member(connector, "ConnectorId", "get_ConnectorId")
            if value is not None:
                connector_ids.append(int(value))
    attempts = []
    for connector_id in connector_ids:
        try:
            connector = frame.GetConnector(connector_id, bool(writable))
            if connector is None:
                attempts.append({"connectorId": connector_id, "status": "null"})
                continue
            parameter_set = _get_member(connector, "HostParameterSet", "get_HostParameterSet")
            parameter = parameter_set.GetParameter(parameter_id) if parameter_set is not None else None
            if parameter is None:
                attempts.append({"connectorId": connector_id, "status": "parameter_not_found"})
                continue
            requested_path = ([] if req.get("parameterRoot") is True else
                              (req.get("elementPath") or req.get("field") or []))
            element, parts = _native_element_at_path(parameter, requested_path)
            return connector_id, parameter, element, parts, attempts
        except OperationError:
            raise
        except Exception as exc:
            attempts.append({"connectorId": connector_id, "error": repr(exc)})
    raise OperationError("parameter was not found through editor connector frame",
                         "parameter_not_found", {"parameterId": parameter_id,
                         "attempts": attempts})


def vendor_editor_parameter_read(req):
    _require_project()
    _view, frame, editor_detail = _open_vendor_editor_match(req)
    connector_id, _parameter, element, parts, attempts = _editor_connector_parameter(frame, req, False)
    return {
        "target": req.get("target") or req.get("name"),
        "connectorId": connector_id,
        "parameterId": int(req.get("parameterId")),
        "elementPath": parts,
        "value": _native_element_value(element),
        "snapshot": _native_element_snapshot(element, 0, 2),
        "attempts": attempts,
        "editor": editor_detail,
        "mutatedProject": False,
        "status": "observed",
    }


def vendor_editor_parameter_write(req):
    _require_project()
    if req.get("confirm") != "write_vendor_editor_parameter":
        raise OperationError("confirm must exactly equal write_vendor_editor_parameter",
                             "confirmation_required")
    _require_current_disposable_project(req, "vendor.editor.parameter.write")
    if req.get("value") is None:
        raise OperationError("value is required", "invalid_argument")
    _view, frame, editor_detail = _open_vendor_editor_match(req)
    connector_id, _parameter, element, parts, attempts = _editor_connector_parameter(frame, req, True)
    before = _native_element_value(element)
    stages = [{
        "stage": "before",
        "value": before,
        "snapshot": _native_element_snapshot(element, 0, 1),
    }]
    try:
        element.Value = _text(req.get("value"))
    except Exception:
        element.value = _text(req.get("value"))
    after = _native_element_value(element)
    stages.append({
        "stage": "after_set",
        "value": after,
        "exactRequestedValue": after == _text(req.get("value")),
        "snapshot": _native_element_snapshot(element, 0, 1),
    })
    editor = _get_member(frame, "Editor", "get_Editor")
    if editor is None or getattr(editor, "Save", None) is None:
        raise OperationError("live device editor has no Save(bool)",
                             "editor_save_unavailable", {"editor": editor_detail})
    try:
        save_return = editor.Save(True)
    except Exception as exc:
        raise OperationError("live device editor Save(true) failed: " + repr(exc),
                             "editor_save_failed", {"before": before, "after": after,
                             "editor": editor_detail})
    # Re-resolve through the live frame after the vendor Save call.  Save may
    # replace the native object or normalize the value, so reading the old
    # IDataElement is not sufficient evidence.
    try:
        _saved_view, saved_frame, _saved_detail = _open_vendor_editor_match(req)
        _saved_connector, _saved_parameter, saved_element, _saved_parts, _saved_attempts = _editor_connector_parameter(
            saved_frame, req, False
        )
        saved_value = _native_element_value(saved_element)
        stages.append({
            "stage": "after_editor_save",
            "value": saved_value,
            "snapshot": _native_element_snapshot(saved_element, 0, 1),
            "rebound": True,
            "connectorId": _saved_connector,
            "attempts": _saved_attempts,
        })
        requested_value = _text(req.get("value"))
        if _text(saved_value) != requested_value:
            raise OperationError(
                "vendor editor Save(true) did not retain requested value",
                "editor_parameter_not_retained",
                {
                    "target": req.get("target") or req.get("name"),
                    "parameterId": int(req.get("parameterId")),
                    "elementPath": parts,
                    "requested": requested_value,
                    "afterSet": after,
                    "afterEditorSave": saved_value,
                    "stages": stages,
                },
            )
    except Exception as exc:
        if isinstance(exc, OperationError):
            raise
        stages.append({
            "stage": "after_editor_save",
            "readbackError": repr(exc),
            "rebound": False,
        })
    manager_stage = None
    if bool(req.get("managerSave", False)):
        engine, manager_probe = _system_instances_property("Engine")
        manager = _get_member(engine, "EditorManager", "get_EditorManager") if engine is not None else None
        if manager is None:
            manager_stage = {"called": False, "error": "editor_manager_unavailable", "probe": manager_probe}
        else:
            try:
                manager.SaveEditor(editor, True)
                manager_stage = {"called": True, "method": "SaveEditor", "ok": True}
            except Exception as exc:
                manager_stage = {"called": True, "method": "SaveEditor", "ok": False, "error": repr(exc)}
            try:
                _manager_view, manager_frame, _manager_detail = _open_vendor_editor_match(req)
                _manager_connector, _manager_parameter, manager_element, _manager_parts, _manager_attempts = _editor_connector_parameter(
                    manager_frame, req, False
                )
                manager_stage["readback"] = {
                    "value": _native_element_value(manager_element),
                    "snapshot": _native_element_snapshot(manager_element, 0, 1),
                    "connectorId": _manager_connector,
                    "attempts": _manager_attempts,
                }
            except Exception as exc:
                manager_stage["readbackError"] = repr(exc)
    return {
        "target": req.get("target") or req.get("name"),
        "connectorId": connector_id,
        "parameterId": int(req.get("parameterId")),
        "elementPath": parts,
        "before": before,
        "after": after,
        "stages": stages,
        "managerSave": manager_stage,
        "attempts": attempts,
        "saveReturn": _json_safe(save_return),
        "editor": editor_detail,
        "mutatedProject": True,
        "committed": True,
        "status": "editor_parameter_saved",
        "note": "工程仍需调用 project.save，并完成关闭/全新进程重开回读",
    }


def _vendor_editor_page(req):
    """Resolve one live vendor page from the open device editor."""
    requested_page = req.get("pageType") or "TcpSlavePage"
    editor_request = dict(req)
    editor_request["pageType"] = requested_page
    _view, frame, editor_detail = _open_vendor_editor_match(editor_request)
    base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
    pages = []
    try:
        for base_editor in list(base_editors or []):
            value = _get_member(base_editor, "Pages", "get_Pages")
            pages.extend(list(value or []))
    except Exception as exc:
        raise OperationError("vendor editor pages are unavailable: " + repr(exc),
                             "editor_pages_unavailable")
    wanted_page = _text(requested_page).lower()
    for candidate in pages:
        runtime = _text(candidate.GetType().FullName)
        page_name = _text(_get_member(candidate, "PageName", "get_PageName"))
        if wanted_page in runtime.lower() or wanted_page == page_name.lower():
            return candidate, frame, editor_detail, pages
    raise OperationError("vendor page was not found", "editor_page_not_found",
                         {"pageType": wanted_page,
                          "pages": [_text(item.GetType().FullName) for item in pages]})


def _vendor_page_control_snapshot(control, field, runtime_type=None):
    """Return the editable WinForms state exposed by one nested control."""
    if runtime_type is None:
        runtime_type = _text(control.GetType().FullName)
    entry = {"field": field, "runtimeType": runtime_type}
    for prop, getter in (("value", ("Value", "get_Value")),
                         ("checked", ("Checked", "get_Checked")),
                         ("text", ("Text", "get_Text")),
                         ("selectedIndex", ("SelectedIndex", "get_SelectedIndex")),
                         ("minimum", ("Minimum", "get_Minimum")),
                         ("maximum", ("Maximum", "get_Maximum"))):
        try:
            value = _get_member(control, getter[0], getter[1])
            if value is not None:
                entry[prop] = _json_safe(value)
        except Exception as exc:
            entry[prop + "ReadError"] = repr(exc)
    return entry


def _vendor_page_control_fields(root, flags, prefix="", depth=0, seen=None):
    """Recursively inventory page-owned controls and nested user controls.

    Inovance HSIO pages compose UserControls (for example
    ``_counter1._edtPulsePerCycle``), while Modbus pages expose controls
    directly.  Reflection is deliberately limited to page-owned fields and a
    small depth so framework parent/component graphs cannot be traversed.
    """
    if seen is None:
        seen = set()
    if root is None or depth > 4:
        return []
    try:
        identity = root.GetHashCode()
        if identity in seen:
            return []
        seen.add(identity)
    except Exception:
        pass
    controls = []
    try:
        import System.Windows.Forms as _Forms
        control_base = _Forms.Control
    except Exception:
        control_base = None
    for native_field in root.GetType().GetFields(flags):
        try:
            child = native_field.GetValue(root)
            if child is None:
                continue
            name = _text(native_field.Name)
            path = (prefix + "." + name) if prefix else name
            runtime_type = _text(child.GetType().FullName)
            if control_base is not None and not control_base.IsAssignableFrom(child.GetType()):
                continue
            snapshot = _vendor_page_control_snapshot(child, path, runtime_type)
            if any(key in snapshot for key in ("value", "checked", "text", "selectedIndex")):
                controls.append(snapshot)
            # Only recurse into vendor/user controls.  Standard WinForms
            # controls may contain large framework graphs and are already
            # represented by their editable value above.
            if (runtime_type.startswith(
                    "Inovance.InoPro.InoDeviceEditorHighSpeedIO.") and
                    ("Control" in runtime_type or "UserControl" in runtime_type or
                     "Page" in runtime_type)):
                controls.extend(_vendor_page_control_fields(child, flags, path,
                                                             depth + 1, seen))
        except Exception as exc:
            controls.append({"field": path if "path" in locals() else prefix,
                             "readError": repr(exc)})
    return controls


def _resolve_vendor_page_control(page, control_field, flags):
    """Resolve a dotted page-owned field such as ``_counter1._edtPulsePerCycle``."""
    current = page
    parts = [part for part in _text(control_field).split(".") if part]
    if not parts:
        return None, [], None
    for part in parts:
        native_field = current.GetType().GetField(part, flags)
        if native_field is None:
            return None, parts, current
        current = native_field.GetValue(current)
        if current is None:
            return None, parts, current
    return current, parts, current


def vendor_editor_page_probe(req):
    """Read vendor page controls, including nested user-control fields."""
    _require_project()
    if req.get("hsioAxis") is not None:
        return _vendor_editor_hsio_axis_read(req)
    if req.get("hsioHardware") is not None:
        return _vendor_editor_hsio_hardware_read(req)
    page, frame, editor_detail, _pages = _vendor_editor_page(req)
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    if bool(req.get("summaryOnly", False)) and _text(page.GetType().FullName).endswith("AxisParamPage"):
        # AxisParamControl contains several image/help and designer-owned
        # fields that are expensive to reflect in InoProShop's IronPython
        # host.  A summary probe intentionally returns only the page's direct
        # child controls; explicit nested paths can still be resolved by the
        # writer after a known contract has been supplied.
        controls = []
        for native_field in page.GetType().GetFields(flags):
            try:
                child = native_field.GetValue(page)
                if child is None:
                    continue
                runtime_type = _text(child.GetType().FullName)
                snapshot = _vendor_page_control_snapshot(child, _text(native_field.Name), runtime_type)
                if any(key in snapshot for key in ("value", "checked", "text", "selectedIndex")):
                    controls.append(snapshot)
            except Exception as exc:
                controls.append({"field": _text(native_field.Name), "readError": repr(exc)})
    else:
        controls = _vendor_page_control_fields(page, flags)
    result = {"target": req.get("target") or req.get("name"),
              "pageType": _text(page.GetType().FullName),
              "controls": controls,
              "mutatedProject": False, "status": "observed"}
    if not bool(req.get("summaryOnly", False)):
        result["editor"] = editor_detail
    else:
        result["editor"] = {
            "runtimeType": editor_detail.get("editor", {}).get("runtimeType")
            if isinstance(editor_detail, dict) else None,
            "summaryOnly": True,
        }
    return result


def vendor_editor_page_fields(req):
    """List direct private/public fields of one vendor page without recursion.

    Some EtherCAT pages contain WinForms designer graphs that make the generic
    recursive control probe unsafe or excessively slow.  This bounded probe
    only reports field names and CLR types; it never reads values or mutates
    the project.
    """
    _require_project()
    page, _frame, editor_detail, _pages = _vendor_editor_page(req)
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.DeclaredOnly)
    fields = []
    for native_field in page.GetType().GetFields(flags):
        try:
            value = native_field.GetValue(page)
            fields.append({
                "field": _text(native_field.Name),
                "fieldType": _text(native_field.FieldType.FullName),
                "valueRuntimeType": _text(value.GetType().FullName) if value is not None else None,
                "hasValue": value is not None,
            })
        except Exception as exc:
            fields.append({"field": _text(native_field.Name), "fieldType": _text(native_field.FieldType.FullName),
                           "readError": repr(exc)})
    return {"target": req.get("target") or req.get("name"),
            "pageType": _text(page.GetType().FullName),
            "fields": fields, "mutatedProject": False,
            "editor": {"runtimeType": editor_detail.get("editor", {}).get("runtimeType")
                        if isinstance(editor_detail, dict) else None},
            "status": "observed"}


HSIO_AXIS_CONTRACT = {
    "deviceId": {"type": 40600, "id": "10F4 0600", "version": "00.00.00.20"},
    "editorType": "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIOEditor",
    "parameter": {"connectorIndex": 1, "repositoryConnectorId": 2,
                  "firstId": 9, "type": "local:HSOUTPUT"},
    "fields": {
        "name": {"kind": "identifier"},
        "enabled": {"kind": "boolean"},
        "pulseSource": {"kind": "enum", "values": ["cw_ccw", "pulse_sign", "a_b_phase"]},
        "softwareLimitEnabled": {"kind": "boolean"},
        "upperLimit": {"kind": "integer", "minimum": -2147483648, "maximum": 2147483647},
        "lowerLimit": {"kind": "integer", "minimum": -2147483648, "maximum": 2147483647},
        "velocityLimit": {"kind": "integer", "minimum": 1, "maximum": 200000},
        "startVelocity": {"kind": "integer", "minimum": 1, "maximum": 200000},
        "rotationDirection": {"kind": "enum", "values": ["positive", "negative"]},
        "accelerationMode": {"kind": "enum", "values": ["trapezoid", "s_curve"]},
        "homingMethod": {"kind": "integer", "minimum": -1, "maximum": 3},
        "homingSpeed": {"kind": "integer", "minimum": 1, "maximum": 200000},
        "creepSpeed": {"kind": "integer", "minimum": 1, "maximum": 200000},
        "acceleration": {"kind": "integer", "minimum": 1, "maximum": 20000000},
        "deceleration": {"kind": "integer", "minimum": 1, "maximum": 20000000},
    },
}


def _hsio_axis_correct_format():
    return {"hsioAxis": {
        "axis": 0, "name": "HS_Axis0", "enabled": True,
        "pulseSource": "pulse_sign", "softwareLimitEnabled": True,
        "upperLimit": 100000, "lowerLimit": -100000,
        "velocityLimit": 10000, "startVelocity": 500,
        "rotationDirection": "positive", "accelerationMode": "trapezoid",
        "homingMethod": 0, "homingSpeed": 5000, "creepSpeed": 800,
        "acceleration": 1000, "deceleration": 1000,
    }}


def _hsio_axis_error(message, code, data=None):
    detail = dict(data or {})
    detail.setdefault("correctFormat", _hsio_axis_correct_format())
    detail.setdefault("mutatedProject", False)
    return OperationError(message, code, detail)


def _hsio_axis_normalize(req):
    requested = req.get("hsioAxis")
    if not isinstance(requested, dict):
        raise _hsio_axis_error("hsioAxis must be a JSON object",
                               "hsio_axis_input_invalid")
    supported = set(HSIO_AXIS_CONTRACT["fields"])
    supported.add("axis")
    unknown = sorted(set(requested).difference(supported))
    if unknown:
        raise _hsio_axis_error("hsioAxis contains unsupported fields",
                               "hsio_axis_field_unsupported", {
                                   "unsupportedFields": unknown,
                                   "supportedFields": sorted(supported),
                               })
    axis = requested.get("axis")
    if isinstance(axis, bool) or not isinstance(axis, _INTEGER_TYPES) or not 0 <= int(axis) <= 3:
        raise _hsio_axis_error("hsioAxis.axis must be an integer from 0 through 3",
                               "hsio_axis_index_invalid", {
                                   "field": "axis", "minimum": 0, "maximum": 3,
                                   "requested": axis,
                               })
    if len(requested) == 1:
        raise _hsio_axis_error("hsioAxis must include at least one writable field",
                               "hsio_axis_empty_update", {
                                   "supportedFields": sorted(
                                       set(HSIO_AXIS_CONTRACT["fields"])),
                               })
    normalized = {"axis": int(axis)}
    for name, contract in HSIO_AXIS_CONTRACT["fields"].items():
        if name not in requested:
            continue
        value = requested[name]
        kind = contract["kind"]
        if kind == "boolean":
            if not isinstance(value, bool):
                raise _hsio_axis_error("HSIO boolean field requires a JSON boolean",
                                       "hsio_axis_value_invalid", {
                                           "field": name, "requested": value,
                                           "expectedType": "boolean",
                                       })
        elif kind == "integer":
            if isinstance(value, bool) or not isinstance(value, _INTEGER_TYPES):
                raise _hsio_axis_error("HSIO numeric field requires a JSON integer",
                                       "hsio_axis_value_invalid", {
                                           "field": name, "requested": value,
                                           "expectedType": "integer",
                                           "minimum": contract["minimum"],
                                           "maximum": contract["maximum"],
                                       })
            value = int(value)
            if value < contract["minimum"] or value > contract["maximum"]:
                raise _hsio_axis_error("HSIO numeric field is outside the vendor range",
                                       "hsio_axis_value_out_of_range", {
                                           "field": name, "requested": value,
                                           "minimum": contract["minimum"],
                                           "maximum": contract["maximum"],
                                       })
        elif kind == "enum":
            value = _text(value).strip().lower()
            if value not in contract["values"]:
                raise _hsio_axis_error("HSIO enum field has an unsupported value",
                                       "hsio_axis_value_invalid", {
                                           "field": name, "requested": requested[name],
                                           "allowedValues": contract["values"],
                                       })
        elif kind == "identifier":
            if not isinstance(value, _STRING_TYPES) or not _text(value).strip():
                raise _hsio_axis_error("HSIO axis name must be a non-empty string",
                                       "hsio_axis_name_invalid", {
                                           "field": name, "requested": value,
                                       })
            value = _text(value).strip()
        normalized[name] = value
    return normalized


def _hsio_declared_field(value, name):
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.DeclaredOnly)
    runtime = value.GetType()
    while runtime is not None:
        field = runtime.GetField(name, flags)
        if field is not None:
            return field
        runtime = runtime.BaseType
    return None


def _hsio_axis_context(req):
    target = req.get("target") or req.get("name") or req.get("device")
    if not target:
        raise _hsio_axis_error("target is required for hsioAxis",
                               "invalid_argument")
    _view, frame, editor_detail = _open_vendor_editor_match(req)
    base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
    matches = []
    try:
        matches = [item for item in list(base_editors or [])
                   if _text(item.GetType().FullName) == HSIO_AXIS_CONTRACT["editorType"]]
    except Exception as exc:
        raise _hsio_axis_error("HSIO base editor inventory is unavailable",
                               "hsio_editor_unavailable", {"cause": repr(exc)})
    if len(matches) != 1:
        raise _hsio_axis_error("expected exactly one classic NewHSIOEditor",
                               "hsio_editor_identity_mismatch", {
                                   "expectedEditorType": HSIO_AXIS_CONTRACT["editorType"],
                                   "matchCount": len(matches),
                               })
    editor = matches[0]
    data_field = _hsio_declared_field(editor, "_ioData")
    live_data = data_field.GetValue(editor) if data_field is not None else None
    if live_data is None or _text(live_data.GetType().FullName) != (
            "Inovance.InoPro.InoDeviceEditorHighSpeedIO.HiSpeedIoData"):
        raise _hsio_axis_error("NewHSIOEditor shared data binding is unavailable",
                               "hsio_data_binding_unavailable", {
                                   "fieldFound": data_field is not None,
                                   "runtimeType": (_text(live_data.GetType().FullName)
                                                   if live_data is not None else None),
                               })
    device_object = frame.GetDeviceObject(False)
    object_mgr, meta, native_device, native_binding = _native_device_object(
        target, "read")
    identity_value = _get_member(native_device, "DeviceIdentification",
                                 "get_DeviceIdentification")
    if identity_value is None:
        identity_value = _get_member(native_device, "device_identification",
                                     "get_device_identification")
    observed_identity = _device_identity(identity_value)
    expected_identity = HSIO_AXIS_CONTRACT["deviceId"]
    identity_matches = bool(
        observed_identity and
        int(observed_identity.get("type") or 0) == expected_identity["type"] and
        _text(observed_identity.get("id")).upper() == expected_identity["id"].upper() and
        _text(observed_identity.get("version")).upper() == expected_identity["version"].upper())
    if not identity_matches:
        raise _hsio_axis_error("target is not the exact classic HIGH_SPEED_IO identity",
                               "hsio_device_identity_mismatch", {
                                   "expectedIdentity": expected_identity,
                                   "resolvedIdentity": observed_identity,
                               })
    return {"target": target, "frame": frame, "editor": editor,
            "editorDetail": editor_detail, "liveData": live_data,
            "deviceObject": device_object, "nativeDeviceObject": native_device,
            "objectMgr": object_mgr, "meta": meta,
            "nativeBinding": native_binding, "identity": observed_identity}


def _hsio_int32_minus_one(value):
    return 2147483647 if int(value) == -2147483648 else int(value) - 1


def _hsio_int32_plus_one(value):
    return -2147483648 if int(value) == 2147483647 else int(value) + 1


def _hsio_axis_data_snapshot(data, axis):
    output = data.OutputChs[int(axis)]
    pos = output.PosParamData
    zero = output.ZeroParamData
    acceleration = (((int(zero[7]) + 1) & 0xFFFF) << 16) | ((int(zero[5]) + 1) & 0xFFFF)
    deceleration = (((int(zero[8]) + 1) & 0xFFFF) << 16) | ((int(zero[6]) + 1) & 0xFFFF)
    pulse_values = HSIO_AXIS_CONTRACT["fields"]["pulseSource"]["values"]
    return {
        "axis": int(axis), "name": _text(output.AxisName),
        "enabled": bool(output.InUse),
        "pulseSource": pulse_values[int(pos[0])],
        "softwareLimitEnabled": int(pos[2]) == 1,
        "upperLimit": _hsio_int32_plus_one(pos[3]),
        "lowerLimit": _hsio_int32_plus_one(pos[4]),
        "velocityLimit": int(pos[5]) + 1,
        "startVelocity": int(pos[6]) + 1,
        "rotationDirection": "negative" if int(pos[1]) == 1 else "positive",
        "accelerationMode": "s_curve" if int(pos[7]) == 1 else "trapezoid",
        "homingMethod": int(zero[0]),
        "homingSpeed": int(zero[3]) + 1,
        "creepSpeed": int(zero[4]) + 1,
        "acceleration": acceleration, "deceleration": deceleration,
        "outputFunctions": {"y0": int(output.Y0Func), "y1": int(output.Y1Func)},
    }


def _hsio_axis_apply(data, normalized):
    axis = normalized["axis"]
    output = data.OutputChs[axis]
    pulse_values = HSIO_AXIS_CONTRACT["fields"]["pulseSource"]["values"]
    if "name" in normalized:
        output.AxisName = normalized["name"]
    if "enabled" in normalized:
        output.InUse = normalized["enabled"]
    if "pulseSource" in normalized:
        output.PosParamData[0] = pulse_values.index(normalized["pulseSource"])
    if "rotationDirection" in normalized:
        output.PosParamData[1] = 1 if normalized["rotationDirection"] == "negative" else 0
    if "softwareLimitEnabled" in normalized:
        output.PosParamData[2] = 1 if normalized["softwareLimitEnabled"] else 0
    if "upperLimit" in normalized:
        output.PosParamData[3] = _hsio_int32_minus_one(normalized["upperLimit"])
    if "lowerLimit" in normalized:
        output.PosParamData[4] = _hsio_int32_minus_one(normalized["lowerLimit"])
    if "velocityLimit" in normalized:
        output.PosParamData[5] = normalized["velocityLimit"] - 1
    if "startVelocity" in normalized:
        output.PosParamData[6] = normalized["startVelocity"] - 1
    if "accelerationMode" in normalized:
        output.PosParamData[7] = 1 if normalized["accelerationMode"] == "s_curve" else 0
    if "homingMethod" in normalized:
        output.ZeroParamData[0] = normalized["homingMethod"]
    if "homingSpeed" in normalized:
        output.ZeroParamData[3] = normalized["homingSpeed"] - 1
    if "creepSpeed" in normalized:
        output.ZeroParamData[4] = normalized["creepSpeed"] - 1
    if "acceleration" in normalized:
        value = normalized["acceleration"]
        output.ZeroParamData[5] = (value & 0xFFFF) - 1
        output.ZeroParamData[7] = ((value >> 16) & 0xFFFF) - 1
    if "deceleration" in normalized:
        value = normalized["deceleration"]
        output.ZeroParamData[6] = (value & 0xFFFF) - 1
        output.ZeroParamData[8] = ((value >> 16) & 0xFFFF) - 1


def _hsio_axis_validate_relations(snapshot):
    failures = []
    if snapshot["upperLimit"] <= snapshot["lowerLimit"]:
        failures.append({"relation": "upperLimit > lowerLimit",
                         "fields": ["upperLimit", "lowerLimit"]})
    if not (snapshot["startVelocity"] <= snapshot["creepSpeed"] <=
            snapshot["homingSpeed"] <= snapshot["velocityLimit"]):
        failures.append({
            "relation": "startVelocity <= creepSpeed <= homingSpeed <= velocityLimit",
            "fields": ["startVelocity", "creepSpeed", "homingSpeed", "velocityLimit"],
        })
    if failures:
        raise _hsio_axis_error("HSIO axis parameters violate vendor relations",
                               "hsio_axis_relation_invalid", {
                                   "violations": failures, "resolvedValues": snapshot,
                               })


def _hsio_axis_type(editor, full_name):
    value = editor.GetType().Assembly.GetType(full_name)
    if value is None:
        raise _hsio_axis_error("HSIO vendor validation type is unavailable",
                               "hsio_validation_binding_unavailable", {
                                   "runtimeType": full_name,
                               })
    return value


def _hsio_static_method(runtime_type, name, argument_count, non_public=False):
    import System
    flags = (System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public)
    if non_public:
        flags |= System.Reflection.BindingFlags.NonPublic
    methods = [method for method in runtime_type.GetMethods(flags)
               if _text(method.Name) == name and
               len(method.GetParameters()) == int(argument_count)]
    if len(methods) != 1:
        raise _hsio_axis_error("HSIO vendor method binding is ambiguous",
                               "hsio_validation_binding_unavailable", {
                                   "runtimeType": _text(runtime_type.FullName),
                                   "method": name, "matchCount": len(methods),
                               })
    return methods[0]


def _hsio_axis_validate_name(context, before, normalized):
    if "name" not in normalized or normalized["name"] == before["name"]:
        return {"called": False, "accepted": True, "reason": "unchanged_or_omitted"}
    import System
    counter_type = _hsio_axis_type(
        context["editor"],
        "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.CounterParamControl")
    method = _hsio_static_method(counter_type, "CheckIdentifier", 4)
    meta = context["meta"]
    handle = int(_get_member(meta, "ProjectHandle", "get_ProjectHandle"))
    parent_guid = _get_member(meta, "ParentObjectGuid", "get_ParentObjectGuid")
    args = System.Array[System.Object]([
        normalized["name"], handle, parent_guid, None])
    accepted = bool(method.Invoke(None, args))
    error = _text(args[3])
    if not accepted:
        raise _hsio_axis_error("HSIO vendor identifier validation rejected the axis name",
                               "hsio_axis_name_invalid", {
                                   "field": "name", "requested": normalized["name"],
                                   "vendorError": error,
                               })
    return {"called": True, "accepted": True, "vendorError": error}


def _hsio_axis_validate_ports(context, clone):
    import System
    editor = context["editor"]
    input_type = _hsio_axis_type(
        editor, "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.InputPortControl")
    output_type = _hsio_axis_type(
        editor, "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.OutputPortControl")
    axis_type = _hsio_axis_type(
        editor, "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.AxisPortControl")
    get_conflict = _hsio_static_method(input_type, "GetConflictPort", 1, True)
    input_port = int(get_conflict.Invoke(
        None, System.Array[System.Object]([clone])))
    if input_port >= 0:
        raise _hsio_axis_error("HSIO physical input port is already in use",
                               "hsio_input_port_conflict", {
                                   "physicalPort": input_port,
                               })
    counter_output = _hsio_static_method(
        output_type, "CounterSupportCoincidentOutput", 3)
    pwm_output = _hsio_static_method(output_type, "PortisPWMOutput", 2)
    output_conflicts = []
    for port in range(8):
        owners = 1 if bool(clone.OutputChs[port // 2].InUse) else 0
        for counter in range(8):
            if bool(counter_output.Invoke(None, System.Array[System.Object]([
                    clone, counter, port]))):
                owners += 1
        if bool(pwm_output.Invoke(None, System.Array[System.Object]([clone, port]))):
            owners += 1
        if owners > 1:
            output_conflicts.append({"physicalPort": port, "ownerCount": owners})
    if output_conflicts:
        raise _hsio_axis_error("HSIO physical output port is already in use",
                               "hsio_output_port_conflict", {
                                   "conflicts": output_conflicts,
                               })
    update_input = _hsio_static_method(input_type, "UpdateInputPortData", 2)
    update_output = _hsio_static_method(axis_type, "UpdateOutputPortFunction", 1)
    update_input.Invoke(None, System.Array[System.Object]([
        clone, context["liveData"]]))
    update_output.Invoke(None, System.Array[System.Object]([clone]))
    return {"inputConflictPort": None, "outputConflicts": [],
            "inputNormalized": True, "outputNormalized": True}


def _hsio_native_value(element, path):
    value, _parts = _native_element_at_path(element, path)
    return _native_element_value(value)


def _hsio_axis_native_decode(raw, axis_object):
    """Decode persisted HSOUTPUT values into the public atomic contract."""
    try:
        pulse_index = int(raw["OutputMode"]) - 1
        pulse_values = HSIO_AXIS_CONTRACT["fields"]["pulseSource"]["values"]
        if pulse_index < 0 or pulse_index >= len(pulse_values):
            raise ValueError("OutputMode index is outside the vendor enum")
        for field in ("StrokeLimitEnabled", "RetationDir", "LugDownMode"):
            if int(raw[field]) not in (1, 2):
                raise ValueError(field + " is outside the vendor enum")
        if int(raw["ReturnMode"]) not in (0, 1, 2, 3, 4):
            raise ValueError("ReturnMode is outside the vendor enum")
        if axis_object.get("available") and int(axis_object.get("enabled")) not in (0, 1):
            raise ValueError("HSIOObject.AxisEnabled is outside the vendor enum")
        acceleration = (((int(raw["AccelerationHigh"]) & 0xFFFF) << 16) |
                        (int(raw["AccelerationLow"]) & 0xFFFF))
        deceleration = (((int(raw["DecelerationHigh"]) & 0xFFFF) << 16) |
                        (int(raw["DecelerationLow"]) & 0xFFFF))
        return {
            "name": axis_object.get("name") if axis_object.get("available") else None,
            "enabled": (bool(axis_object.get("enabled"))
                        if axis_object.get("available") else None),
            "pulseSource": pulse_values[pulse_index],
            "softwareLimitEnabled": int(raw["StrokeLimitEnabled"]) == 2,
            "upperLimit": int(raw["PositiveLimit"]),
            "lowerLimit": int(raw["NegativeLimit"]),
            "velocityLimit": int(raw["VelocityLimit"]),
            "startVelocity": int(raw["StartVelocity"]),
            "rotationDirection": ("negative" if int(raw["RetationDir"]) == 2
                                  else "positive"),
            "accelerationMode": ("s_curve" if int(raw["LugDownMode"]) == 2
                                 else "trapezoid"),
            "homingMethod": int(raw["ReturnMode"]) - 1,
            "homingSpeed": int(raw["ReturnVelocity"]),
            "creepSpeed": int(raw["SlowDownVelocity"]),
            "acceleration": acceleration,
            "deceleration": deceleration,
        }
    except Exception as exc:
        raise _hsio_axis_error(
            "HSIO native readback could not be decoded",
            "hsio_native_readback_invalid",
            {"raw": raw, "axisObject": axis_object, "cause": repr(exc),
             "mutatedProject": True, "processDiscardRequired": True},
        )


def _hsio_axis_native_snapshot(context, axis, persisted=False):
    # The editor frame owns the current unsaved IDeviceObject. ObjectMgr is
    # intentionally still the source for HSIOObject metadata, but its device
    # parameter object remains the previous persisted snapshot until the
    # project itself is saved.
    device_object = (context["nativeDeviceObject"] if persisted else
                     context["frame"].GetDeviceObject(False))
    meta = context["meta"]
    native_binding = dict(context["nativeBinding"])
    native_binding["parameterSource"] = (
        "object_manager_persisted" if persisted else "device_editor_frame")
    native_binding["persistenceState"] = (
        "persisted_object_mgr" if persisted else "same_process_unsaved")
    parameter_id = HSIO_AXIS_CONTRACT["parameter"]["firstId"] + int(axis)
    parameter = _native_parameter_from_device(
        device_object, parameter_id,
        HSIO_AXIS_CONTRACT["parameter"]["connectorIndex"])
    parameter_type = _text(_get_member(parameter, "ParamType", "get_ParamType"))
    if parameter_type != HSIO_AXIS_CONTRACT["parameter"]["type"]:
        raise _hsio_axis_error("HSIO axis parameter type does not match the verified binding",
                               "hsio_parameter_identity_mismatch", {
                                   "parameterId": parameter_id,
                                   "expectedType": HSIO_AXIS_CONTRACT["parameter"]["type"],
                                   "actualType": parameter_type,
                               })
    raw = {
        "OutputMode": _hsio_native_value(parameter, ["PosPara", "OutputMode"]),
        "RetationDir": _hsio_native_value(parameter, ["PosPara", "RetationDir"]),
        "StrokeLimitEnabled": _hsio_native_value(parameter, ["PosPara", "StrokeLimitEnabled"]),
        "PositiveLimit": _hsio_native_value(parameter, ["PosPara", "PositiveLimit"]),
        "NegativeLimit": _hsio_native_value(parameter, ["PosPara", "NegativeLimit"]),
        "VelocityLimit": _hsio_native_value(parameter, ["PosPara", "VelocityLimit"]),
        "StartVelocity": _hsio_native_value(parameter, ["PosPara", "StartVelocity"]),
        "LugDownMode": _hsio_native_value(parameter, ["PosPara", "LugDownMode"]),
        "ReturnMode": _hsio_native_value(parameter, ["ReturnPara", "ReturnMode"]),
        "ReturnVelocity": _hsio_native_value(parameter, ["ReturnPara", "ReturnVelocity"]),
        "SlowDownVelocity": _hsio_native_value(parameter, ["ReturnPara", "SlowDownVelocity"]),
        "AccelerationLow": _hsio_native_value(parameter, ["ReturnPara", "LugDownTm"]),
        "DecelerationLow": _hsio_native_value(parameter, ["ReturnPara", "SlowToStopTm"]),
        "AccelerationHigh": _hsio_native_value(parameter, ["ReturnPara", "MoveLenAfterDog"]),
        "DecelerationHigh": _hsio_native_value(parameter, ["ReturnPara", "StayTm"]),
        "UsePosFuc": _hsio_native_value(parameter, ["UsePosFuc"]),
        "Yn0Func": _hsio_native_value(parameter, ["OutPortFunc", "Yn0Func"]),
        "Yn1Func": _hsio_native_value(parameter, ["OutPortFunc", "Yn1Func"]),
    }
    child_guids = list(_get_member(meta, "SubObjectGuids", "get_SubObjectGuids") or [])
    axis_object = {"available": False}
    if child_guids:
        object_mgr, probe = _system_instances_property("ObjectMgr")
        if object_mgr is None:
            raise _hsio_axis_error("HSIO axis-name ObjectMgr binding is unavailable",
                                   "object_manager_unavailable", {"probe": probe})
        handle = int(_get_member(meta, "ProjectHandle", "get_ProjectHandle"))
        child_meta = object_mgr.GetObjectToRead(handle, child_guids[0])
        child = _get_member(child_meta, "Object", "get_Object")
        if child is not None:
            names = _get_member(child, "AxisName", "get_AxisName")
            enabled = _get_member(child, "AxisEnabled", "get_AxisEnabled")
            axis_object = {
                "available": True, "guid": _text(child_guids[0]),
                "runtimeType": _text(child.GetType().FullName),
                "name": _text(names[int(axis)]),
                "enabled": int(enabled[int(axis)]),
            }
    decoded = _hsio_axis_native_decode(raw, axis_object)
    return {"connectorIndex": 1, "repositoryConnectorId": 2,
            "parameterId": parameter_id, "parameterType": parameter_type,
            "raw": raw, "decoded": decoded, "axisObject": axis_object,
            "binding": native_binding}


def _vendor_editor_hsio_axis_read(req):
    selector = req.get("hsioAxis")
    if not isinstance(selector, dict):
        raise _hsio_axis_error("hsioAxis must be a JSON object",
                               "hsio_axis_input_invalid")
    unknown = sorted(set(selector).difference(["axis"]))
    if unknown:
        raise _hsio_axis_error("read-only hsioAxis accepts only axis",
                               "hsio_axis_field_unsupported", {
                                   "unsupportedFields": unknown,
                                   "supportedFields": ["axis"],
                               })
    axis = selector.get("axis")
    if isinstance(axis, bool) or not isinstance(axis, _INTEGER_TYPES) or not 0 <= int(axis) <= 3:
        raise _hsio_axis_error("hsioAxis.axis must be an integer from 0 through 3",
                               "hsio_axis_index_invalid", {
                                   "field": "axis", "minimum": 0, "maximum": 3,
                                   "requested": axis,
                               })
    axis = int(axis)
    context = _hsio_axis_context(req)
    model = _hsio_axis_data_snapshot(context["liveData"], axis)
    frame = _hsio_axis_native_snapshot(context, axis, False)
    persisted = _hsio_axis_native_snapshot(context, axis, True)
    comparisons = []
    for field in HSIO_AXIS_CONTRACT["fields"]:
        model_value = model.get(field)
        frame_value = frame["decoded"].get(field)
        persisted_value = persisted["decoded"].get(field)
        comparisons.append({
            "field": field, "model": model_value,
            "frameNative": frame_value, "persistedNative": persisted_value,
            "modelMatchesFrame": model_value == frame_value,
            "frameMatchesPersisted": frame_value == persisted_value,
        })
    return {
        "target": context["target"], "axis": axis,
        "resolvedIdentity": context["identity"],
        "model": model, "frameNative": frame,
        "persistedNative": persisted, "comparisons": comparisons,
        "allModelMatchesFrame": all(item["modelMatchesFrame"] for item in comparisons),
        "allFrameMatchesPersisted": all(item["frameMatchesPersisted"] for item in comparisons),
        "mutatedProject": False, "status": "hsio_axis_observed",
    }


def _vendor_editor_hsio_axis_write(req):
    normalized = _hsio_axis_normalize(req)
    context = _hsio_axis_context(req)
    axis = normalized["axis"]
    before = _hsio_axis_data_snapshot(context["liveData"], axis)
    clone = context["liveData"].Clone()
    _hsio_axis_apply(clone, normalized)
    resolved = _hsio_axis_data_snapshot(clone, axis)
    _hsio_axis_validate_relations(resolved)
    name_validation = _hsio_axis_validate_name(context, before, normalized)
    port_validation = _hsio_axis_validate_ports(context, clone)
    resolved = _hsio_axis_data_snapshot(clone, axis)
    receipt = {
        "operation": "vendor.editor.page.parameter.write",
        "mode": "hsio_axis_atomic", "target": context["target"],
        "resolvedIdentity": context["identity"],
        "input": normalized, "before": before, "resolvedBeforeCommit": resolved,
        "validation": {"relations": "accepted", "name": name_validation,
                       "ports": port_validation},
        "mutatedProject": False, "committed": False,
    }
    try:
        context["liveData"].InputChs = clone.InputChs
        context["liveData"].OutputChs = clone.OutputChs
        context["liveData"].StopCpuWhenError = clone.StopCpuWhenError
        receipt["mutatedProject"] = True
        save_return = context["editor"].Save(True)
        receipt["save"] = {"called": True, "ownerType": HSIO_AXIS_CONTRACT["editorType"],
                           "return": _json_safe(save_return)}
        native_after_save = _hsio_axis_native_snapshot(context, axis)
        context["editor"].Reload()
        after = _hsio_axis_data_snapshot(context["liveData"], axis)
        mismatches = []
        for field, expected in normalized.items():
            if field == "axis":
                continue
            if after.get(field) != expected:
                mismatches.append({"field": field, "expected": expected,
                                   "actual": after.get(field)})
            native_actual = native_after_save["decoded"].get(field)
            if native_actual != expected:
                mismatches.append({"field": field, "source": "native_HSOUTPUT",
                                   "expected": expected, "actual": native_actual})
        axis_object = native_after_save.get("axisObject") or {}
        if axis_object.get("available"):
            if axis_object.get("name") != after["name"]:
                mismatches.append({"field": "name", "source": "HSIOObject",
                                   "expected": after["name"],
                                   "actual": axis_object.get("name")})
            if bool(axis_object.get("enabled")) != after["enabled"]:
                mismatches.append({"field": "enabled", "source": "HSIOObject",
                                   "expected": after["enabled"],
                                   "actual": axis_object.get("enabled")})
        else:
            mismatches.append({"field": "HSIOObject", "expected": "available",
                               "actual": axis_object})
        receipt["after"] = {"data": after, "native": native_after_save}
        if mismatches:
            raise OperationError("HSIO editor save did not retain the atomic axis update",
                                 "hsio_axis_save_not_retained", {
                                     "receipt": receipt, "mismatches": mismatches,
                                     "mutatedProject": True,
                                     "processDiscardRequired": True,
                                 })
        receipt["committed"] = True
        receipt["status"] = "hsio_axis_saved_same_process"
        receipt["processDiscardRequired"] = False
        receipt["nextRequired"] = [
            "project.save", "close and open in a fresh InoProShop process",
            "repeat HSIO data/native/HSIOObject readback", "offline compile diagnostics",
        ]
        return receipt
    except Exception as exc:
        if isinstance(exc, OperationError):
            exc.data.setdefault("mutatedProject", receipt["mutatedProject"])
            if receipt["mutatedProject"]:
                exc.data["processDiscardRequired"] = True
            raise
        raise OperationError("HSIO atomic axis commit failed: " + repr(exc),
                             "hsio_axis_commit_failed", {
                                 "receipt": receipt,
                                 "mutatedProject": receipt["mutatedProject"],
                                 "processDiscardRequired": receipt["mutatedProject"],
                             })


HSIO_HARDWARE_CONTRACT = {
    "deviceId": {"type": 40600, "id": "10F4 0600", "version": "00.00.00.20"},
    "editorType": "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIOEditor",
    "inputParameters": {"connectorIndex": 1, "repositoryConnectorId": 2,
                        "firstId": 1, "count": 8, "type": "local:HSINPUT"},
    "outputParameters": {"connectorIndex": 1, "repositoryConnectorId": 2,
                         "firstId": 9, "count": 4, "type": "local:HSOUTPUT"},
    "counterModes": {
        "single_phase": (0, 0), "ab_1x": (0, 1), "ab_4x": (0, 3),
        "cw_ccw": (0, 4), "internal_1us": (1, 0),
        "internal_10us": (2, 0), "internal_100us": (3, 0),
        "internal_1ms": (4, 0),
    },
    "externalFunctions": {
        "none": -1, "disable_counting": 0, "disable_and_preset": 3,
        "latch_and_preset": 4,
    },
    "interruptTriggers": {"rising": 0, "falling": 1, "both": 2},
    "rotationWindowsMs": {10: 0, 100: 1, 1000: 2},
}


def _hsio_hardware_correct_format():
    return {"hsioHardware": {
        "counters": [{
            "counter": 0, "name": "HS_Counter0", "enabled": True,
            "mode": "single_phase", "counting": "linear",
            "signalLogic": "positive", "externalFunction": "none",
            "rotationWindowMs": 10, "pulsesPerCycle": 1000,
            "externalTrigger": False, "coincidentOutput": None,
        }],
        "pwm": [{"port": 6, "enabled": True}],
        "interrupts": [{"port": 0, "enabled": True,
                        "trigger": "rising", "filterTimeMs": 2.0}],
    }}


def _hsio_hardware_error(message, code, data=None):
    detail = dict(data or {})
    detail.setdefault("correctFormat", _hsio_hardware_correct_format())
    detail.setdefault("mutatedProject", False)
    return OperationError(message, code, detail)


def _hsio_hardware_integer(value, field, minimum, maximum):
    if isinstance(value, bool) or not isinstance(value, _INTEGER_TYPES):
        raise _hsio_hardware_error("HSIO hardware field must be an integer",
                                   "hsio_hardware_value_invalid", {
                                       "field": field, "requested": value,
                                       "expectedType": "integer",
                                       "minimum": minimum, "maximum": maximum,
                                   })
    value = int(value)
    if value < minimum or value > maximum:
        raise _hsio_hardware_error("HSIO hardware field is outside the vendor range",
                                   "hsio_hardware_value_out_of_range", {
                                       "field": field, "requested": value,
                                       "minimum": minimum, "maximum": maximum,
                                   })
    return value


def _hsio_hardware_normalize(req):
    requested = req.get("hsioHardware")
    if not isinstance(requested, dict):
        raise _hsio_hardware_error("hsioHardware must be a JSON object",
                                   "hsio_hardware_input_invalid")
    groups = set(["counters", "pwm", "interrupts"])
    unknown = sorted(set(requested).difference(groups))
    if unknown:
        raise _hsio_hardware_error("hsioHardware contains unsupported groups",
                                   "hsio_hardware_group_unsupported", {
                                       "unsupportedGroups": unknown,
                                       "supportedGroups": sorted(groups),
                                   })
    if not requested or not any(requested.get(name) for name in groups):
        raise _hsio_hardware_error("hsioHardware requires at least one update",
                                   "hsio_hardware_empty_update")
    result = {"counters": [], "pwm": [], "interrupts": []}
    fields = {
        "counters": set(["counter", "name", "enabled", "mode", "counting",
                         "signalLogic", "externalFunction", "rotationWindowMs",
                         "pulsesPerCycle", "externalTrigger", "coincidentOutput"]),
        "pwm": set(["port", "enabled"]),
        "interrupts": set(["port", "enabled", "trigger", "filterTimeMs"]),
    }
    for group in ("counters", "pwm", "interrupts"):
        entries = requested.get(group, [])
        if not isinstance(entries, list):
            raise _hsio_hardware_error("HSIO hardware group must be an array",
                                       "hsio_hardware_input_invalid", {
                                           "group": group, "expectedType": "array"})
        identity_name = "counter" if group == "counters" else "port"
        seen = set()
        for entry in entries:
            if not isinstance(entry, dict):
                raise _hsio_hardware_error("HSIO hardware entry must be an object",
                                           "hsio_hardware_input_invalid", {"group": group})
            unsupported = sorted(set(entry).difference(fields[group]))
            if unsupported:
                raise _hsio_hardware_error("HSIO hardware entry contains unsupported fields",
                                           "hsio_hardware_field_unsupported", {
                                               "group": group,
                                               "unsupportedFields": unsupported,
                                               "supportedFields": sorted(fields[group]),
                                           })
            identity = _hsio_hardware_integer(entry.get(identity_name),
                                              group + "." + identity_name, 0, 7)
            if identity in seen:
                raise _hsio_hardware_error("HSIO hardware batch contains a duplicate target",
                                           "hsio_hardware_duplicate_target", {
                                               "group": group, identity_name: identity})
            seen.add(identity)
            if len(entry) == 1:
                raise _hsio_hardware_error("HSIO hardware entry has no writable fields",
                                           "hsio_hardware_empty_entry", {
                                               "group": group, identity_name: identity})
            item = {identity_name: identity}
            for name, original in entry.items():
                if name == identity_name:
                    continue
                value = original
                if name in ("enabled", "externalTrigger"):
                    if not isinstance(value, bool):
                        raise _hsio_hardware_error("HSIO hardware flag must be boolean",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": value,
                                                       "expectedType": "boolean"})
                elif name == "name":
                    if not isinstance(value, _STRING_TYPES) or not _text(value).strip():
                        raise _hsio_hardware_error("HSIO counter name must be non-empty",
                                                   "hsio_counter_name_invalid", {
                                                       "counter": identity, "requested": value})
                    value = _text(value).strip()
                elif name == "mode":
                    value = _text(value).strip().lower()
                    allowed = HSIO_HARDWARE_CONTRACT["counterModes"]
                    if value not in allowed:
                        raise _hsio_hardware_error("HSIO counter mode is unsupported",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": original,
                                                       "allowedValues": sorted(allowed)})
                elif name == "counting":
                    value = _text(value).strip().lower()
                    if value not in ("linear", "cyclic"):
                        raise _hsio_hardware_error("HSIO counting mode is unsupported",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": original,
                                                       "allowedValues": ["linear", "cyclic"]})
                elif name == "signalLogic":
                    value = _text(value).strip().lower()
                    if value not in ("positive", "negative"):
                        raise _hsio_hardware_error("HSIO signal logic is unsupported",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": original,
                                                       "allowedValues": ["positive", "negative"]})
                elif name == "externalFunction":
                    value = _text(value).strip().lower()
                    allowed = HSIO_HARDWARE_CONTRACT["externalFunctions"]
                    if value not in allowed:
                        raise _hsio_hardware_error("HSIO external function is unsupported",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": original,
                                                       "allowedValues": sorted(allowed)})
                elif name == "rotationWindowMs":
                    value = _hsio_hardware_integer(value, name, 10, 1000)
                    allowed = HSIO_HARDWARE_CONTRACT["rotationWindowsMs"]
                    if value not in allowed:
                        raise _hsio_hardware_error("HSIO rotation window is unsupported",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": value,
                                                       "allowedValues": [10, 100, 1000]})
                elif name == "pulsesPerCycle":
                    value = _hsio_hardware_integer(value, name, 1, 200000)
                elif name == "coincidentOutput" and value is not None:
                    value = _hsio_hardware_integer(value, name, 0, 7)
                elif name == "trigger":
                    value = _text(value).strip().lower()
                    allowed = HSIO_HARDWARE_CONTRACT["interruptTriggers"]
                    if value not in allowed:
                        raise _hsio_hardware_error("HSIO interrupt trigger is unsupported",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": original,
                                                       "allowedValues": sorted(allowed)})
                elif name == "filterTimeMs":
                    numeric_types = _INTEGER_TYPES + (float,)
                    if isinstance(value, bool) or not isinstance(value, numeric_types):
                        raise _hsio_hardware_error("HSIO filter time must be numeric",
                                                   "hsio_hardware_value_invalid", {
                                                       "field": name, "requested": value,
                                                       "expectedType": "number"})
                    value = float(value)
                item[name] = value
            if group == "counters":
                unavailable = set(["externalTrigger", "signalLogic",
                                   "externalFunction"]).intersection(item)
                if identity >= 4 and unavailable:
                    raise _hsio_hardware_error("Counter 4 through 7 do not expose external-trigger settings",
                                               "hsio_counter_external_trigger_unavailable", {
                                                   "counter": identity,
                                                   "unsupportedFields": sorted(unavailable),
                                                   "allowedCounters": [0, 1, 2, 3]})
                if identity >= 4 and item.get("counting") == "cyclic":
                    raise _hsio_hardware_error("Counter 4 through 7 do not expose cyclic counting",
                                               "hsio_counter_cyclic_unavailable", {
                                                   "counter": identity,
                                                   "allowedCounters": [0, 1, 2, 3]})
                external_fields = set(["signalLogic", "externalFunction"]).intersection(item)
                if external_fields and item.get("externalTrigger") is not True:
                    raise _hsio_hardware_error("External-trigger parameters require externalTrigger=true in the same batch entry",
                                               "hsio_counter_external_trigger_required", {
                                                   "counter": identity,
                                                   "dependentFields": sorted(external_fields)})
                if item.get("externalTrigger") is True and item.get("enabled") is not True:
                    raise _hsio_hardware_error("External trigger requires enabled=true in the same counter entry",
                                               "hsio_counter_enable_required", {
                                                   "counter": identity,
                                                   "dependentField": "externalTrigger"})
                if item.get("coincidentOutput") is not None and item.get("enabled") is not True:
                    raise _hsio_hardware_error("Coincident output requires enabled=true in the same counter entry",
                                               "hsio_counter_enable_required", {
                                                   "counter": identity,
                                                   "dependentField": "coincidentOutput"})
            if group == "interrupts":
                if "enabled" not in item:
                    raise _hsio_hardware_error("Interrupt entries require an explicit enabled state",
                                               "hsio_interrupt_enable_required", {
                                                   "port": identity,
                                                   "requiredField": "enabled"})
                if "trigger" in item and item["enabled"] is not True:
                    raise _hsio_hardware_error("Interrupt trigger selection requires enabled=true",
                                               "hsio_interrupt_enable_required", {
                                                   "port": identity,
                                                   "dependentField": "trigger"})
                if "filterTimeMs" in item:
                    value = item["filterTimeMs"]
                    if item["enabled"]:
                        valid = (0.5 <= value <= 10000.0 and
                                 abs(value * 4.0 - round(value * 4.0)) <= 0.000001)
                        bounds = {"minimum": 0.5, "maximum": 10000.0,
                                  "step": 0.25, "portMode": "interrupt"}
                    else:
                        valid = 10000.0 <= value <= 60000.0
                        bounds = {"minimum": 10000.0, "maximum": 60000.0,
                                  "portMode": "general_input"}
                    if not valid:
                        bounds.update({"field": "filterTimeMs", "requested": value})
                        raise _hsio_hardware_error("HSIO input filter violates the vendor range for its selected port mode",
                                                   "hsio_hardware_value_out_of_range",
                                                   bounds)
            result[group].append(item)
    return result


def _hsio_hardware_mode_name(values):
    pair = (int(values[1]), int(values[2]))
    for name, expected in HSIO_HARDWARE_CONTRACT["counterModes"].items():
        if tuple(expected) == pair:
            return name
    return None


def _hsio_hardware_external_name(value):
    for name, expected in HSIO_HARDWARE_CONTRACT["externalFunctions"].items():
        if int(expected) == int(value):
            return name
    return None


def _hsio_hardware_data_snapshot(data):
    counters = []
    for index in range(8):
        channel = data.InputChs[index]
        trigger_channel = data.InputChs[4 + index // 2]
        trigger_func = int(trigger_channel.X0Func if index % 2 == 0 else
                           trigger_channel.X1Func)
        counters.append({
            "counter": index, "name": _text(channel.CounterName),
            "enabled": bool(channel.InUse),
            "mode": _hsio_hardware_mode_name(channel.CounterData),
            "counting": "cyclic" if int(channel.CounterData[3]) == 1 else "linear",
            "signalLogic": "negative" if int(channel.CounterData[4]) == 1 else "positive",
            "externalFunction": _hsio_hardware_external_name(channel.CounterData[5]),
            "rotationWindowMs": (10, 100, 1000)[int(channel.CounterData[12])],
            "pulsesPerCycle": int(channel.CounterData[13]) + 1,
            "externalTrigger": bool(index < 4 and channel.InUse and trigger_func == 2),
            "coincidentOutput": (int(channel.CounterData[19]) - 1
                                  if int(channel.CounterData[19]) > 0 else None),
        })
    pwm = []
    for port in range(8):
        channel = data.OutputChs[port // 2]
        function = int(channel.Y0Func if port % 2 == 0 else channel.Y1Func)
        pwm.append({"port": port, "enabled": function == 4})
    trigger_names = dict((value, name) for name, value in
                         HSIO_HARDWARE_CONTRACT["interruptTriggers"].items())
    interrupts = []
    for port in range(8):
        channel = data.InputChs[port // 2]
        function = int(channel.X0Func if port % 2 == 0 else channel.X1Func)
        treat = int(channel.X0IntTreat if port % 2 == 0 else channel.X1IntTreat)
        filter_time = float(channel.X0IntTime if port % 2 == 0 else channel.X1IntTime)
        interrupts.append({"port": port, "enabled": function == 1,
                           "trigger": trigger_names.get(treat),
                           "filterTimeMs": filter_time})
    input_ports = []
    for port in range(16):
        channel = data.InputChs[port // 2]
        function = int(channel.X0Func if port % 2 == 0 else channel.X1Func)
        input_ports.append({"port": port, "function": function})
    output_ports = []
    for port in range(8):
        channel = data.OutputChs[port // 2]
        function = int(channel.Y0Func if port % 2 == 0 else channel.Y1Func)
        output_ports.append({"port": port, "function": function})
    return {"counters": counters, "pwm": pwm, "interrupts": interrupts,
            "physicalPorts": {"inputs": input_ports, "outputs": output_ports}}


def _hsio_hardware_apply(data, normalized):
    for item in normalized["counters"]:
        index = item["counter"]
        channel = data.InputChs[index]
        if "name" in item:
            channel.CounterName = item["name"]
        if "enabled" in item:
            channel.InUse = item["enabled"]
        if "mode" in item:
            mode = HSIO_HARDWARE_CONTRACT["counterModes"][item["mode"]]
            channel.CounterData[1], channel.CounterData[2] = mode[0], mode[1]
        if "counting" in item:
            channel.CounterData[3] = 1 if item["counting"] == "cyclic" else 0
        if "signalLogic" in item:
            channel.CounterData[4] = 1 if item["signalLogic"] == "negative" else 0
        if "externalFunction" in item:
            channel.CounterData[5] = HSIO_HARDWARE_CONTRACT["externalFunctions"][item["externalFunction"]]
        if "rotationWindowMs" in item:
            window = HSIO_HARDWARE_CONTRACT["rotationWindowsMs"][item["rotationWindowMs"]]
            channel.CounterData[10], channel.CounterData[12] = window, window
        if "pulsesPerCycle" in item:
            channel.CounterData[13] = item["pulsesPerCycle"] - 1
        if "coincidentOutput" in item:
            channel.CounterData[19] = (item["coincidentOutput"] + 1
                                       if item["coincidentOutput"] is not None else 0)
        if "externalTrigger" in item:
            target = data.InputChs[4 + index // 2]
            value = 2 if item["externalTrigger"] else 0
            if index % 2 == 0:
                target.X0Func = value
            else:
                target.X1Func = value
    for item in normalized["interrupts"]:
        port, even = item["port"], item["port"] % 2 == 0
        channel = data.InputChs[port // 2]
        if "enabled" in item:
            if even:
                channel.X0Func = 1 if item["enabled"] else 0
            else:
                channel.X1Func = 1 if item["enabled"] else 0
        if "trigger" in item:
            value = HSIO_HARDWARE_CONTRACT["interruptTriggers"][item["trigger"]]
            if even:
                channel.X0IntTreat = value
            else:
                channel.X1IntTreat = value
        if "filterTimeMs" in item:
            if even:
                channel.X0IntTime = item["filterTimeMs"]
            else:
                channel.X1IntTime = item["filterTimeMs"]
    for item in normalized["pwm"]:
        port = item["port"]
        channel = data.OutputChs[port // 2]
        value = 4 if item["enabled"] else 0
        if port % 2 == 0:
            channel.Y0Func = value
        else:
            channel.Y1Func = value


def _hsio_hardware_reapply_filter_times(data, normalized):
    # UpdateInputPortData applies the default transition used by the vendor
    # enable checkbox. An explicit filter value is the later UI action.
    for item in normalized["interrupts"]:
        if "filterTimeMs" not in item:
            continue
        channel = data.InputChs[item["port"] // 2]
        if item["port"] % 2 == 0:
            channel.X0IntTime = item["filterTimeMs"]
        else:
            channel.X1IntTime = item["filterTimeMs"]


def _hsio_hardware_validate_names(context, before, clone, normalized):
    names = [_text(clone.InputChs[index].CounterName).strip() for index in range(8)]
    folded = [name.lower() for name in names]
    duplicates = sorted(set(name for name in folded if folded.count(name) > 1))
    if duplicates:
        raise _hsio_hardware_error("HSIO counter names must be unique",
                                   "hsio_counter_name_duplicate", {
                                       "duplicateNames": duplicates})
    import System
    counter_type = _hsio_axis_type(
        context["editor"],
        "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.CounterParamControl")
    method = _hsio_static_method(counter_type, "CheckIdentifier", 4)
    meta = context["meta"]
    handle = int(_get_member(meta, "ProjectHandle", "get_ProjectHandle"))
    parent_guid = _get_member(meta, "ParentObjectGuid", "get_ParentObjectGuid")
    checks = []
    for item in normalized["counters"]:
        index = item["counter"]
        if "name" not in item or item["name"] == before["counters"][index]["name"]:
            continue
        args = System.Array[System.Object]([item["name"], handle, parent_guid, None])
        accepted = bool(method.Invoke(None, args))
        if not accepted:
            raise _hsio_hardware_error("Vendor rejected the HSIO counter name",
                                       "hsio_counter_name_invalid", {
                                           "counter": index, "requested": item["name"],
                                           "vendorError": _text(args[3])})
        checks.append({"counter": index, "accepted": True,
                       "vendorError": _text(args[3])})
    return checks


def _hsio_hardware_validate_ports(context, clone):
    import System
    input_type = _hsio_axis_type(
        context["editor"],
        "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.InputPortControl")
    output_type = _hsio_axis_type(
        context["editor"],
        "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.OutputPortControl")
    axis_type = _hsio_axis_type(
        context["editor"],
        "Inovance.InoPro.InoDeviceEditorHighSpeedIO.NewHSIO.AxisPortControl")
    get_conflict = _hsio_static_method(input_type, "GetConflictPort", 1, True)
    conflict = int(get_conflict.Invoke(None, System.Array[System.Object]([clone])))
    if conflict >= 0:
        raise _hsio_hardware_error("HSIO physical input port is already in use",
                                   "hsio_input_port_conflict", {"physicalPort": conflict})
    counter_output = _hsio_static_method(output_type, "CounterSupportCoincidentOutput", 3)
    pwm_output = _hsio_static_method(output_type, "PortisPWMOutput", 2)
    conflicts = []
    for port in range(8):
        owners = 1 if bool(clone.OutputChs[port // 2].InUse) else 0
        for counter in range(8):
            if bool(counter_output.Invoke(None, System.Array[System.Object]([
                    clone, counter, port]))):
                owners += 1
        if bool(pwm_output.Invoke(None, System.Array[System.Object]([clone, port]))):
            owners += 1
        if owners > 1:
            conflicts.append({"physicalPort": port, "ownerCount": owners})
    if conflicts:
        raise _hsio_hardware_error("HSIO physical output port is already in use",
                                   "hsio_output_port_conflict", {"conflicts": conflicts})
    _hsio_static_method(input_type, "UpdateInputPortData", 2).Invoke(
        None, System.Array[System.Object]([clone, context["liveData"]]))
    _hsio_static_method(axis_type, "UpdateOutputPortFunction", 1).Invoke(
        None, System.Array[System.Object]([clone]))
    return {"inputConflictPort": None, "outputConflicts": [],
            "inputNormalized": True, "outputNormalized": True}


def _hsio_hardware_mismatches(snapshot, normalized, source):
    mismatches = []
    for group in ("counters", "pwm", "interrupts"):
        identity = "counter" if group == "counters" else "port"
        actual = dict((item[identity], item) for item in snapshot[group])
        for requested in normalized[group]:
            for field, expected in requested.items():
                if field == identity:
                    continue
                observed = actual[requested[identity]].get(field)
                equal = (abs(float(observed) - float(expected)) < 0.000001
                         if field == "filterTimeMs" else observed == expected)
                if not equal:
                    mismatches.append({"group": group, identity: requested[identity],
                                       "field": field, "expected": expected,
                                       "actual": observed, "source": source})
    return mismatches


def _vendor_editor_hsio_hardware_read(req):
    if req.get("hsioHardware") not in ({}, None):
        raise _hsio_hardware_error("read-only hsioHardware accepts an empty object",
                                   "hsio_hardware_field_unsupported", {
                                       "supportedFormat": {"hsioHardware": {}}})
    context = _hsio_axis_context(req)
    return {"target": context["target"], "resolvedIdentity": context["identity"],
            "model": _hsio_hardware_data_snapshot(context["liveData"]),
            "mutatedProject": False, "status": "hsio_hardware_observed"}


def _vendor_editor_hsio_hardware_write(req):
    normalized = _hsio_hardware_normalize(req)
    context = _hsio_axis_context(req)
    before = _hsio_hardware_data_snapshot(context["liveData"])
    clone = context["liveData"].Clone()
    _hsio_hardware_apply(clone, normalized)
    name_validation = _hsio_hardware_validate_names(context, before, clone, normalized)
    port_validation = _hsio_hardware_validate_ports(context, clone)
    _hsio_hardware_reapply_filter_times(clone, normalized)
    resolved = _hsio_hardware_data_snapshot(clone)
    mismatches = _hsio_hardware_mismatches(resolved, normalized, "normalized_clone")
    if mismatches:
        raise _hsio_hardware_error("Vendor normalization did not retain HSIO assignments",
                                   "hsio_hardware_assignment_not_retained", {
                                       "mismatches": mismatches,
                                       "resolvedValues": resolved})
    receipt = {"operation": "vendor.editor.page.parameter.write",
               "mode": "hsio_hardware_atomic", "target": context["target"],
               "resolvedIdentity": context["identity"], "input": normalized,
               "before": before, "resolvedBeforeCommit": resolved,
               "validation": {"names": name_validation, "ports": port_validation},
               "mutatedProject": False, "committed": False}
    try:
        context["liveData"].InputChs = clone.InputChs
        context["liveData"].OutputChs = clone.OutputChs
        context["liveData"].StopCpuWhenError = clone.StopCpuWhenError
        receipt["mutatedProject"] = True
        save_return = context["editor"].Save(True)
        receipt["save"] = {"called": True,
                           "ownerType": HSIO_HARDWARE_CONTRACT["editorType"],
                           "return": _json_safe(save_return)}
        context["editor"].Reload()
        after = _hsio_hardware_data_snapshot(context["liveData"])
        mismatches = _hsio_hardware_mismatches(after, normalized,
                                               "reloaded_editor_model")
        receipt["after"] = after
        if mismatches:
            raise OperationError("HSIO editor save did not retain hardware update",
                                 "hsio_hardware_save_not_retained", {
                                     "receipt": receipt, "mismatches": mismatches,
                                     "mutatedProject": True,
                                     "processDiscardRequired": True})
        receipt["committed"] = True
        receipt["status"] = "hsio_hardware_saved_same_process"
        receipt["processDiscardRequired"] = False
        receipt["nextRequired"] = [
            "project.save", "close and open in a fresh InoProShop process",
            "vendor.editor.page.probe with hsioHardware={}",
            "offline compile diagnostics"]
        return receipt
    except Exception as exc:
        if isinstance(exc, OperationError):
            exc.data.setdefault("mutatedProject", receipt["mutatedProject"])
            if receipt["mutatedProject"]:
                exc.data["processDiscardRequired"] = True
            raise
        raise OperationError("HSIO atomic hardware commit failed: " + repr(exc),
                             "hsio_hardware_commit_failed", {
                                 "receipt": receipt,
                                 "mutatedProject": receipt["mutatedProject"],
                                 "processDiscardRequired": receipt["mutatedProject"]})


SOFTMOTION_AXIS_PARAMETER_CONTRACT = {
    "deviceId": {
        "type": 1027,
        "ids": ["FFFF 0001", "0000 0001"],
        "version": "4.0.0.0",
    },
    "pageType": "Inovance.InoPro.InoDeviceEditorSoftMotion.BasicPage",
    "editorType": "Inovance.InoPro.InoDeviceEditorSoftMotion.AxisEditor",
    "connectorId": 0,
    "softwareLimits": {
        "enabled": {"controlField": "_chkEnableSoftwareLimit",
                    "parameterId": 1205, "kind": "boolean"},
        "lower": {"controlField": "_txtSoftwareLimitLower",
                  "parameterId": 1201, "kind": "decimal"},
        "upper": {"controlField": "_txtSoftwareLimitUpper",
                  "parameterId": 1200, "kind": "decimal"},
        "deceleration": {"controlField": "_txtSoftwareLimitDec",
                         "parameterId": 1203, "kind": "nonnegative_decimal"},
        "maxDistance": {"controlField": "_txtSoftwareLimitMaxDist",
                        "parameterId": 1250, "kind": "nonnegative_decimal"},
    },
}


def _softmotion_axis_parameters_correct_format():
    return {"softmotionAxisParameters": {"softwareLimits": {
        "enabled": True, "lower": "-100000", "upper": "100000",
        "deceleration": "1000", "maxDistance": "1000",
    }}}


def _softmotion_axis_parameters_error(message, code, data=None):
    detail = dict(data or {})
    detail.setdefault("correctFormat", _softmotion_axis_parameters_correct_format())
    detail.setdefault("mutatedProject", False)
    return OperationError(message, code, detail)


def _softmotion_axis_parameters_normalize(req):
    requested = req.get("softmotionAxisParameters")
    if not isinstance(requested, dict):
        raise _softmotion_axis_parameters_error(
            "softmotionAxisParameters must be a JSON object",
            "softmotion_axis_parameters_input_invalid")
    unknown_groups = sorted(set(requested).difference(["softwareLimits"]))
    if unknown_groups:
        raise _softmotion_axis_parameters_error(
            "softmotionAxisParameters contains unsupported groups",
            "softmotion_axis_parameter_group_unsupported", {
                "unsupportedGroups": unknown_groups,
                "supportedGroups": ["softwareLimits"],
            })
    limits = requested.get("softwareLimits")
    if not isinstance(limits, dict):
        raise _softmotion_axis_parameters_error(
            "softwareLimits must be a JSON object",
            "softmotion_axis_software_limits_invalid")
    contract = SOFTMOTION_AXIS_PARAMETER_CONTRACT["softwareLimits"]
    unknown = sorted(set(limits).difference(contract))
    if unknown:
        raise _softmotion_axis_parameters_error(
            "softwareLimits contains unsupported fields",
            "softmotion_axis_parameter_field_unsupported", {
                "unsupportedFields": unknown,
                "supportedFields": sorted(contract),
            })
    required = ["enabled", "lower", "upper"]
    missing = [name for name in required if name not in limits]
    if missing:
        raise _softmotion_axis_parameters_error(
            "softwareLimits requires enabled, lower, and upper",
            "softmotion_axis_parameter_required", {
                "missingFields": missing, "requiredFields": required,
            })
    if not isinstance(limits["enabled"], bool):
        raise _softmotion_axis_parameters_error(
            "softwareLimits.enabled must be a JSON boolean",
            "softmotion_axis_parameter_value_invalid", {
                "field": "enabled", "expectedType": "boolean",
                "requested": limits["enabled"],
            })
    from decimal import Decimal, InvalidOperation
    normalized = {"enabled": limits["enabled"]}
    decimal_values = {}
    for name in ("lower", "upper", "deceleration", "maxDistance"):
        if name not in limits:
            continue
        value = limits[name]
        if isinstance(value, bool) or not isinstance(
                value, _STRING_TYPES + _INTEGER_TYPES + (float,)):
            raise _softmotion_axis_parameters_error(
                "SoftMotion numeric fields require a JSON number or decimal string",
                "softmotion_axis_parameter_value_invalid", {
                    "field": name, "expectedType": "decimal",
                    "requested": value,
                })
        text_value = _text(value).strip()
        try:
            decimal_value = Decimal(text_value)
            if not decimal_value.is_finite():
                raise InvalidOperation()
        except Exception:
            raise _softmotion_axis_parameters_error(
                "SoftMotion numeric field is not a finite decimal",
                "softmotion_axis_parameter_value_invalid", {
                    "field": name, "expectedType": "finite decimal",
                    "requested": value,
                })
        if name in ("deceleration", "maxDistance") and decimal_value < 0:
            raise _softmotion_axis_parameters_error(
                "SoftMotion nonnegative field is below zero",
                "softmotion_axis_parameter_value_out_of_range", {
                    "field": name, "minimum": "0", "requested": text_value,
                })
        normalized[name] = text_value
        decimal_values[name] = decimal_value
    if decimal_values["lower"] >= decimal_values["upper"]:
        raise _softmotion_axis_parameters_error(
            "softwareLimits.lower must be less than softwareLimits.upper",
            "softmotion_axis_parameter_relation_invalid", {
                "relation": "lower < upper",
                "lower": normalized["lower"], "upper": normalized["upper"],
            })
    return {"softwareLimits": normalized}


def _softmotion_axis_parameter_matches(kind, expected, actual):
    if kind == "boolean":
        expected_bool = bool(expected)
        actual_text = _text(actual).strip().lower()
        if actual_text in ("true", "1"):
            return expected_bool
        if actual_text in ("false", "0"):
            return not expected_bool
        return False
    try:
        from decimal import Decimal
        return Decimal(_text(expected).strip()) == Decimal(_text(actual).strip())
    except Exception:
        return False


def _vendor_editor_softmotion_axis_parameters_write(req):
    normalized = _softmotion_axis_parameters_normalize(req)
    target = req.get("target") or req.get("name")
    if not target:
        raise _softmotion_axis_parameters_error(
            "target SoftMotion axis is required", "invalid_argument")
    axis_object, object_path = find_project_object(target)
    identity = _project_device_identity(axis_object)
    expected_identity = SOFTMOTION_AXIS_PARAMETER_CONTRACT["deviceId"]
    try:
        identity_matches = (
            int(identity.get("type")) == expected_identity["type"] and
            _text(identity.get("id")).upper() in expected_identity["ids"] and
            _text(identity.get("version")) == expected_identity["version"]
        )
    except Exception:
        identity_matches = False
    if not identity_matches:
        raise _softmotion_axis_parameters_error(
            "target is not a supported generic CiA402 SoftMotion axis",
            "softmotion_axis_identity_mismatch", {
                "target": object_path, "expectedIdentity": expected_identity,
                "observedIdentity": identity,
            })

    page_req = dict(req)
    page_req["target"] = object_path
    page_req["pageType"] = SOFTMOTION_AXIS_PARAMETER_CONTRACT["pageType"]
    page, frame, editor_detail, _pages = _vendor_editor_page(page_req)
    page_runtime = _text(page.GetType().FullName)
    if page_runtime != SOFTMOTION_AXIS_PARAMETER_CONTRACT["pageType"]:
        raise _softmotion_axis_parameters_error(
            "resolved SoftMotion page does not match the exact contract",
            "softmotion_axis_page_mismatch", {
                "expectedPageType": SOFTMOTION_AXIS_PARAMETER_CONTRACT["pageType"],
                "observedPageType": page_runtime,
            })
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    contracts = SOFTMOTION_AXIS_PARAMETER_CONTRACT["softwareLimits"]
    controls = {}
    before_controls = {}
    before_native = {}
    for name in ("lower", "upper", "deceleration", "maxDistance", "enabled"):
        if name not in normalized["softwareLimits"]:
            continue
        field_contract = contracts[name]
        control, parts, owner = _resolve_vendor_page_control(
            page, field_contract["controlField"], flags)
        if control is None:
            raise _softmotion_axis_parameters_error(
                "SoftMotion page control was not found",
                "softmotion_axis_control_not_found", {
                    "field": name, "controlField": field_contract["controlField"],
                    "controlPath": parts,
                    "ownerType": (_text(owner.GetType().FullName)
                                  if owner is not None else None),
                })
        controls[name] = control
        before_controls[name] = _vendor_page_control_snapshot(
            control, field_contract["controlField"])
        parameter_req = dict(page_req)
        parameter_req.update({
            "connectorId": SOFTMOTION_AXIS_PARAMETER_CONTRACT["connectorId"],
            "parameterId": field_contract["parameterId"],
            "parameterRoot": True,
        })
        _connector, _parameter, element, _parts, _attempts = (
            _editor_connector_parameter(frame, parameter_req, False))
        before_native[name] = _native_element_value(element)

    base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
    try:
        axis_editors = [candidate for candidate in list(base_editors or [])
                        if _text(candidate.GetType().FullName) ==
                        SOFTMOTION_AXIS_PARAMETER_CONTRACT["editorType"]]
    except Exception:
        axis_editors = []
    if len(axis_editors) != 1:
        raise _softmotion_axis_parameters_error(
            "expected exactly one SoftMotion AxisEditor",
            "softmotion_axis_editor_ambiguous", {
                "expectedEditorType": SOFTMOTION_AXIS_PARAMETER_CONTRACT["editorType"],
                "matchCount": len(axis_editors),
            })
    axis_editor = axis_editors[0]
    receipt = {
        "operation": "vendor.editor.page.parameter.write",
        "mode": "softmotion_axis_parameters_atomic",
        "target": object_path, "resolvedIdentity": identity,
        "input": normalized, "before": {
            "controls": before_controls, "native": before_native,
        },
        "editor": {
            "runtimeType": editor_detail.get("editor", {}).get("runtimeType")
            if isinstance(editor_detail, dict) else None,
            "objectGuid": editor_detail.get("editor", {}).get("objectGuid")
            if isinstance(editor_detail, dict) else None,
            "pageType": page_runtime,
            "saveOwnerType": SOFTMOTION_AXIS_PARAMETER_CONTRACT["editorType"],
            "summaryOnly": True,
        }, "mutatedProject": False,
        "committed": False,
    }
    try:
        for name in ("lower", "upper", "deceleration", "maxDistance", "enabled"):
            if name not in normalized["softwareLimits"]:
                continue
            if contracts[name]["kind"] == "boolean":
                controls[name].Checked = normalized["softwareLimits"][name]
            else:
                controls[name].Text = normalized["softwareLimits"][name]
            receipt["mutatedProject"] = True
        after_controls = dict((name, _vendor_page_control_snapshot(
            control, contracts[name]["controlField"]))
                              for name, control in controls.items())
        receipt["afterControlAssignment"] = after_controls
        save_return = axis_editor.Save(True)
        receipt["save"] = {
            "called": True, "callCount": 1,
            "ownerType": SOFTMOTION_AXIS_PARAMETER_CONTRACT["editorType"],
            "return": _json_safe(save_return),
        }

        _saved_view, saved_frame, _saved_detail = _open_vendor_editor_match(page_req)
        saved_page, _unused_frame, _unused_detail, _unused_pages = (
            _vendor_editor_page(page_req))
        native_after = {}
        controls_after = {}
        mismatches = []
        for name, expected in normalized["softwareLimits"].items():
            field_contract = contracts[name]
            parameter_req = dict(page_req)
            parameter_req.update({
                "connectorId": SOFTMOTION_AXIS_PARAMETER_CONTRACT["connectorId"],
                "parameterId": field_contract["parameterId"],
                "parameterRoot": True,
            })
            _connector, _parameter, element, _parts, _attempts = (
                _editor_connector_parameter(saved_frame, parameter_req, False))
            native_value = _native_element_value(element)
            native_after[name] = native_value
            saved_control, _control_parts, _control_owner = (
                _resolve_vendor_page_control(
                    saved_page, field_contract["controlField"], flags))
            if saved_control is None:
                mismatches.append({"field": name, "source": "control",
                                   "expected": expected, "actual": None})
            else:
                controls_after[name] = _vendor_page_control_snapshot(
                    saved_control, field_contract["controlField"])
                control_value = (_get_member(saved_control, "Checked", "get_Checked")
                                 if field_contract["kind"] == "boolean" else
                                 _get_member(saved_control, "Text", "get_Text"))
                if not _softmotion_axis_parameter_matches(
                        field_contract["kind"], expected, control_value):
                    mismatches.append({"field": name, "source": "control",
                                       "expected": expected,
                                       "actual": _json_safe(control_value)})
            if not _softmotion_axis_parameter_matches(
                    field_contract["kind"], expected, native_value):
                mismatches.append({"field": name, "source": "native_parameter",
                                   "parameterId": field_contract["parameterId"],
                                   "expected": expected, "actual": native_value})
        receipt["after"] = {"controls": controls_after, "native": native_after}
        if mismatches:
            raise OperationError(
                "SoftMotion AxisEditor save did not retain all requested values",
                "softmotion_axis_parameters_save_not_retained", {
                    "receipt": receipt, "mismatches": mismatches,
                    "mutatedProject": True, "processDiscardRequired": True,
                })
        receipt["committed"] = True
        receipt["status"] = "softmotion_axis_parameters_saved_same_process"
        receipt["processDiscardRequired"] = False
        receipt["nextRequired"] = [
            "project.save", "close and open in a fresh InoProShop process",
            "open the Axis editor and repeat exact control/native readback",
            "offline compile diagnostics",
        ]
        return receipt
    except Exception as exc:
        if isinstance(exc, OperationError):
            exc.data.setdefault("mutatedProject", receipt["mutatedProject"])
            if receipt["mutatedProject"]:
                exc.data["processDiscardRequired"] = True
            raise
        raise OperationError(
            "SoftMotion atomic parameter commit failed: " + repr(exc),
            "softmotion_axis_parameters_commit_failed", {
                "receipt": receipt,
                "mutatedProject": receipt["mutatedProject"],
                "processDiscardRequired": receipt["mutatedProject"],
            })


def vendor_editor_page_parameter_write(req):
    """Drive a vendor page's real WinForms control before calling page.Save.

    The generic frame IDataElement is not the page's source of truth for some
    Inovance editors.  TcpSlavePage, for example, copies numericPort and
    numericFrameDelay into the parameter only from its own controls.
    """
    _require_project()
    if req.get("confirm") != "write_vendor_editor_page_parameter":
        raise OperationError("confirm must exactly equal write_vendor_editor_page_parameter",
                             "confirmation_required")
    _require_current_disposable_project(req, "vendor.editor.page.parameter.write")
    if req.get("hsioAxis") is not None:
        return _vendor_editor_hsio_axis_write(req)
    if req.get("hsioHardware") is not None:
        return _vendor_editor_hsio_hardware_write(req)
    if req.get("softmotionAxisParameters") is not None:
        return _vendor_editor_softmotion_axis_parameters_write(req)
    if req.get("value") is None:
        raise OperationError("value is required", "invalid_argument")
    field = _text(req.get("field") or "")
    field_map = {"Port": "numericPort", "FrameDelay": "numericFrameDelay"}
    control_field = field_map.get(field, field)
    if not control_field:
        raise OperationError("field is required", "invalid_argument")
    page, frame, editor_detail, _pages = _vendor_editor_page(req)
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    control, control_parts, owner = _resolve_vendor_page_control(page, control_field, flags)
    if control is None:
        raise OperationError("vendor page control field was not found",
                             "editor_control_not_found", {"field": control_field,
                             "path": control_parts,
                             "ownerType": _text(owner.GetType().FullName) if owner is not None else None,
                             "pageType": _text(page.GetType().FullName)})
    if control is None:
        raise OperationError("vendor page control is null", "editor_control_unavailable",
                             {"field": control_field})
    runtime_type = _text(control.GetType().FullName)
    requested = req.get("value")
    page_runtime = _text(page.GetType().FullName)
    if (".NewHSIO." in page_runtime and
            runtime_type.endswith("System.Windows.Forms.TextBox") and
            not bool(req.get("allowFocusCommit", False))):
        raise OperationError(
            "HSIO text control commits on LostFocus and cannot be safely set by direct assignment",
            "editor_control_event_unavailable",
            {"field": control_field, "pageType": page_runtime,
             "runtimeType": runtime_type,
             "required": "explicit focus transition contract"},
        )
    # Page controls are the source of truth.  Select the setter from the
    # actual WinForms control type, and enforce NumericUpDown bounds before
    # touching the project.
    control_kind = None
    before = None
    after_control = None
    if _get_member(control, "Value", "get_Value") is not None:
        control_kind = "numeric"
        before = _json_safe(_get_member(control, "Value", "get_Value"))
        minimum_raw = _get_member(control, "Minimum", "get_Minimum")
        maximum_raw = _get_member(control, "Maximum", "get_Maximum")
        minimum = _json_safe(minimum_raw)
        maximum = _json_safe(maximum_raw)
        try:
            decimal_value = System.Decimal.Parse(_text(requested),
                                                 System.Globalization.CultureInfo.InvariantCulture)
            from decimal import Decimal as _PyDecimal
            requested_decimal = _PyDecimal(_text(requested))
            minimum_decimal = (_PyDecimal(_text(minimum_raw))
                               if minimum_raw is not None else None)
            maximum_decimal = (_PyDecimal(_text(maximum_raw))
                               if maximum_raw is not None else None)
            if minimum_decimal is not None and requested_decimal < minimum_decimal:
                raise OperationError("value is below vendor control minimum",
                                     "editor_value_out_of_range", {"field": field,
                                     "minimum": _json_safe(minimum), "requested": _text(requested),
                                     "minimumText": _text(minimum_raw), "requestedText": _text(requested),
                                     "comparison": _text(requested_decimal < minimum_decimal)})
            if maximum_decimal is not None and requested_decimal > maximum_decimal:
                raise OperationError("value exceeds vendor control maximum",
                                     "editor_value_out_of_range", {"field": field,
                                     "maximum": _json_safe(maximum), "requested": _text(requested)})
            control.Value = decimal_value
        except OperationError:
            raise
        except Exception as exc:
            raise OperationError("vendor numeric control value assignment failed: " + repr(exc),
                                 "editor_control_set_failed", {"field": control_field,
                                 "before": before, "runtimeType": runtime_type})
        after_control = _json_safe(_get_member(control, "Value", "get_Value"))
    elif _get_member(control, "Checked", "get_Checked") is not None:
        control_kind = "checkbox"
        before = _json_safe(_get_member(control, "Checked", "get_Checked"))
        normalized = _text(requested).strip().lower()
        if normalized not in ("true", "false", "1", "0"):
            raise OperationError("checkbox value must be true/false/1/0",
                                 "editor_value_invalid", {"field": field,
                                 "requested": _text(requested)})
        control.Checked = normalized in ("true", "1")
        after_control = _json_safe(_get_member(control, "Checked", "get_Checked"))
    elif _get_member(control, "Text", "get_Text") is not None:
        control_kind = "text"
        before = _json_safe(_get_member(control, "Text", "get_Text"))
        control.Text = _text(requested)
        after_control = _json_safe(_get_member(control, "Text", "get_Text"))
    elif _get_member(control, "SelectedIndex", "get_SelectedIndex") is not None:
        control_kind = "selection"
        before = _json_safe(_get_member(control, "SelectedIndex", "get_SelectedIndex"))
        try:
            control.SelectedIndex = int(requested)
        except Exception as exc:
            raise OperationError("selection control value assignment failed: " + repr(exc),
                                 "editor_control_set_failed", {"field": control_field,
                                 "before": before, "runtimeType": runtime_type})
        after_control = _json_safe(_get_member(control, "SelectedIndex", "get_SelectedIndex"))
    else:
        raise OperationError("unsupported vendor page control type",
                             "editor_control_type_unsupported", {"field": control_field,
                             "runtimeType": runtime_type})
    if req.get("controlKind") and _text(req.get("controlKind")) != control_kind:
        raise OperationError("control kind does not match request",
                             "editor_control_kind_mismatch", {"expected": req.get("controlKind"),
                             "observed": control_kind, "runtimeType": runtime_type})
    save = getattr(page, "Save", None)
    save_owner = page
    # SoftMotion subpages are coordinated by AxisEditor.  For example,
    # HomingPageSwitch.Save expects (bool, IConnector), while the public
    # AxisEditor.Save(bool) obtains the connector and commits every bound
    # page exactly as the IDE does.
    if ".InoDeviceEditorSoftMotion." in page_runtime:
        base_editors = _get_member(frame, "BaseDeviceEditors", "get_BaseDeviceEditors")
        try:
            candidates = list(base_editors) if base_editors is not None else []
        except Exception:
            candidates = []
        for candidate in candidates:
            if _text(candidate.GetType().FullName).endswith(".AxisEditor"):
                save_owner = candidate
                save = getattr(candidate, "Save", None)
                break
    if save is None:
        raise OperationError("vendor page has no compatible Save(bool)",
                             "editor_page_save_unavailable")
    try:
        save_return = save(True)
    except Exception as exc:
        raise OperationError("vendor page Save(true) failed: " + repr(exc),
                             "editor_page_save_failed", {"before": before,
                             "afterControl": after_control,
                             "saveOwner": _text(save_owner.GetType().FullName)})
    # EtherCAT master pages keep NIC selection in vendor page state rather
    # than exposing an IDataElement parameter.  Allow an explicit, scoped
    # direct commit through the live frame, but do not claim persistence or
    # bypass the normal confirmation/disposable gates.
    if req.get("directPageCommit"):
        if not page_runtime.endswith("EthercatMasterEditorPage"):
            raise OperationError("direct page commit is restricted to EtherCAT master page",
                                 "editor_direct_commit_scope")
        try:
            device_object = frame.GetDeviceObject(True)
            direct_commit = {"called": True,
                             "runtimeType": _text(device_object.GetType().FullName)
                             if device_object is not None else None}
        except Exception as exc:
            raise OperationError("vendor direct page commit failed: " + repr(exc),
                                 "editor_page_commit_failed", {
                                     "field": field, "afterControl": after_control,
                                     "pageType": page_runtime})
        return {"target": req.get("target") or req.get("name"), "field": field,
                "controlField": control_field, "controlPath": control_parts,
                "pageType": page_runtime, "controlKind": control_kind,
                "controlRuntimeType": runtime_type, "beforeControl": before,
                "afterControl": after_control, "afterPageSave": after_control,
                "saveReturn": _json_safe(save_return), "directCommit": direct_commit,
                "connectorId": req.get("connectorId"),
                "parameterId": req.get("parameterId"), "mutatedProject": True,
                "committed": True, "status": "editor_page_direct_commit",
                "note": "EtherCAT page state committed through GetDeviceObject(true); project.save, restart and compile gates remain required"}
    # HSIO NewHSIO pages mutate their HiSpeedIoData from control change events;
    # CounterParamPage.Save(bool) is intentionally empty.  The event handler's
    # GetDeviceObject(true) is the vendor commit path, so do it explicitly and
    # verify the control state rather than pretending the generic IDataElement
    # connector path represents this page.
    if page_runtime.endswith("CounterParamPage") or ".NewHSIO." in page_runtime:
        try:
            device_object = frame.GetDeviceObject(True)
            event_commit = {"called": True,
                            "runtimeType": _text(device_object.GetType().FullName)
                            if device_object is not None else None}
        except Exception as exc:
            raise OperationError("vendor HSIO device-object commit failed: " + repr(exc),
                                 "editor_page_commit_failed", {
                                     "field": field, "afterControl": after_control,
                                     "pageType": page_runtime})
        return {"target": req.get("target") or req.get("name"), "field": field,
                "controlField": control_field, "controlPath": control_parts,
                "pageType": page_runtime, "controlKind": control_kind,
                "controlRuntimeType": runtime_type, "beforeControl": before,
                "afterControl": after_control, "afterPageSave": after_control,
                "saveReturn": _json_safe(save_return), "eventCommit": event_commit,
                "connectorId": req.get("connectorId"),
                "parameterId": req.get("parameterId"), "mutatedProject": True,
                "committed": True, "status": "editor_page_parameter_saved",
                "note": "HSIO nested page control committed through GetDeviceObject(true); project.save and fresh-process reopen remain required"}

    # Callers that perform their own fallback-aware retention verification
    # (e.g. the Modbus TCP slave write, whose fresh-project parameter exposes
    # its children by numeric index) can skip THIS rebind — the rebind below
    # navigates [parameterField] by name and fails on those projects.
    if req.get("skipRetentionCheck") is True:
        return {"target": req.get("target") or req.get("name"), "field": field,
                "controlField": control_field, "pageType": _text(page.GetType().FullName),
                "controlKind": control_kind, "controlRuntimeType": runtime_type,
                "beforeControl": before, "afterControl": after_control,
                "saveReturn": _json_safe(save_return),
                "connectorId": req.get("connectorId"),
                "parameterId": req.get("parameterId"),
                "mutatedProject": True, "committed": True,
                "status": "editor_page_parameter_saved_retention_skipped",
                "note": "retention verification is the caller's responsibility"}

    # Rebind through the live connector after the page's own Save call.
    # Newer vendor pages frequently expose a UI field whose name differs from
    # the persisted IDataElement name (for example
    # socketTimeoutNumericUpDown -> SocketTimeout).  Keep both sides explicit
    # in the request rather than guessing from the control name.
    parameter_req = dict(req)
    parameter_field = _text(req.get("parameterField") or field)
    parameter_req["elementPath"] = ([] if req.get("parameterRoot") is True
                                    else [parameter_field])
    _saved_view, saved_frame, _saved_detail = _open_vendor_editor_match(req)
    _saved_connector, _saved_parameter, saved_element, saved_parts, _saved_attempts = _editor_connector_parameter(
        saved_frame, parameter_req, False
    )
    after_save = _native_element_value(saved_element)
    requested = _text(req.get("value"))
    if _text(after_save) != requested:
        raise OperationError("vendor page Save(true) did not retain requested value",
                             "editor_page_parameter_not_retained", {
                                 "field": field, "beforeControl": before,
                                 "afterControl": after_control,
                                 "afterPageSave": after_save,
                                 "elementPath": saved_parts,
                                 "parameterField": parameter_field})
    return {"target": req.get("target") or req.get("name"), "field": field,
            "controlField": control_field, "pageType": _text(page.GetType().FullName),
            "controlKind": control_kind, "controlRuntimeType": runtime_type,
            "beforeControl": before, "afterControl": after_control,
            "afterPageSave": after_save, "saveReturn": _json_safe(save_return),
            "connectorId": _saved_connector, "parameterId": int(req.get("parameterId") or 393217),
            "parameterField": parameter_field,
            "mutatedProject": True, "committed": True,
            "status": "editor_page_parameter_saved",
            "note": "工程仍需调用 project.save 并通过全新进程重开门禁"}


def vendor_editor_page_control_read(req):
    """Read one explicit page-owned control without scanning the page graph."""
    _require_project()
    field = _text(req.get("field") or req.get("controlField"))
    if not field:
        raise OperationError("field is required", "invalid_argument")
    page, _frame, editor_detail, _pages = _vendor_editor_page(req)
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    control, parts, owner = _resolve_vendor_page_control(page, field, flags)
    if control is None:
        raise OperationError("vendor page control field was not found",
                             "editor_control_not_found", {
                                 "field": field, "path": parts,
                                 "pageType": _text(page.GetType().FullName),
                                 "ownerType": _text(owner.GetType().FullName)
                                 if owner is not None else None})
    return {"target": req.get("target") or req.get("name"),
            "pageType": _text(page.GetType().FullName),
            "field": field, "controlPath": parts,
            "control": _vendor_page_control_snapshot(
                control, field, _text(control.GetType().FullName)),
            "mutatedProject": False, "status": "observed",
            "editor": {"runtimeType": editor_detail.get("editor", {}).get("runtimeType")
                        if isinstance(editor_detail, dict) else None,
                        "summaryOnly": True}}


MODBUS_TCP_SLAVE_PAGE_TYPE = (
    "Inovance.InoPro.InoDeviceEditorModbus.TcpSlavePage")

# ObjectMgr indexes connector collections from one, while the live device
# editor exposes this parameter through connector ID two.  They are distinct
# vendor APIs and must remain explicit.
MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS = {
    "Port": {
        "controlField": "numericPort", "parameterField": "Port",
        "nativeConnectorIndex": 1, "editorConnectorId": 2,
        "parameterId": 393217,
        "parameterType": "localTypes:MODBUSTCPSLAVEDEVICE",
        "minimum": 1, "maximum": 65535,
        # Fresh projects expose the parameter's children by numeric index
        # until the TcpSlavePage editor has been opened once; index 2 is the
        # Port element (round-11 live evidence, native write 1502 retained).
        "fallbackPath": ["2"],
    },
    "FrameDelay": {
        "controlField": "numericFrameDelay", "parameterField": "FrameDelay",
        "nativeConnectorIndex": 1, "editorConnectorId": 2,
        "parameterId": 393217,
        "parameterType": "localTypes:MODBUSTCPSLAVEDEVICE",
        "minimum": 1, "maximum": 1000, "unit": "ms",
    },
}


def _modbus_tcp_slave_element(parameter, contract):
    """Resolve the contract's parameter element, tolerating the fresh-project
    numeric-index layout (see fallbackPath). Returns (element, parts,
    fallback_used)."""
    try:
        element, parts = _native_element_at_path(
            parameter, [contract["parameterField"]])
        return element, parts, False
    except OperationError as exc:
        fallback = contract.get("fallbackPath")
        if exc.code == "element_not_found" and fallback:
            element, parts = _native_element_at_path(parameter, fallback)
            return element, parts, True
        raise


def _modbus_tcp_slave_native_snapshot(target, contract):
    """Read one exact Modbus TCP slave value through ObjectMgr."""
    _object_mgr, _meta, native, identity = _native_device_object(target, "read")
    parameter = _native_parameter_from_device(
        native, contract["parameterId"], contract["nativeConnectorIndex"])
    parameter_type = _text(_get_member(parameter, "ParamType", "get_ParamType"))
    if parameter_type != contract["parameterType"]:
        raise OperationError(
            "Modbus TCP slave parameter type does not match the installed binding",
            "modbus_tcp_slave_parameter_type_mismatch",
            {"expected": contract["parameterType"], "observed": parameter_type,
             "identity": identity, "mutatedProject": False},
        )
    element, parts, fallback_used = _modbus_tcp_slave_element(parameter, contract)
    return {
        "binding": "SystemInstances.ObjectMgr.GetObjectToRead",
        "identity": identity,
        "nativeConnectorIndex": contract["nativeConnectorIndex"],
        "parameterId": contract["parameterId"],
        "parameterType": parameter_type,
        "elementPath": parts,
        "pathFallbackUsed": fallback_used,
        "value": _native_element_value(element),
        "snapshot": _native_element_snapshot(element, 0, 1),
    }


def _modbus_tcp_slave_native_write(target, contract, value):
    """Write the native parameter element directly (ObjectMgr modify +
    SetObject). Used when the TcpSlavePage editor was never opened in this
    project — the dedicated page path then cannot resolve its controls, but
    the native write is the same value the page would commit."""
    object_mgr, meta, native, binding = _native_device_object_with_retry(target, "modify")
    parameter = _native_parameter_from_device(
        native, contract["parameterId"], contract["nativeConnectorIndex"])
    element, parts, fallback_used = _modbus_tcp_slave_element(parameter, contract)
    before = _native_element_value(element)
    try:
        element.Value = _text(value)
    except Exception:
        element.value = _text(value)
    after_set = _native_element_value(element)
    commit_return = object_mgr.SetObject(meta, True, None)
    read_mgr, read_meta, read_native, read_binding = _native_device_object(target, "read")
    read_parameter = _native_parameter_from_device(
        read_native, contract["parameterId"], contract["nativeConnectorIndex"])
    read_element, read_parts, _read_fallback = _modbus_tcp_slave_element(
        read_parameter, contract)
    after = _native_element_value(read_element)
    return {
        "binding": binding,
        "readbackBinding": read_binding,
        "elementPath": parts,
        "pathFallbackUsed": fallback_used,
        "before": before,
        "afterSet": after_set,
        "afterCommit": after,
        "commitReturn": _json_safe(commit_return),
        "committed": _text(after) == _text(value),
        "mutatedProject": True,
    }


def _modbus_tcp_slave_page_snapshot(req, contract):
    """Read the exact live TcpSlavePage numeric control."""
    page_request = dict(req)
    page_request["pageType"] = MODBUS_TCP_SLAVE_PAGE_TYPE
    page, _frame, editor_detail, _pages = _vendor_editor_page(page_request)
    page_runtime = _text(page.GetType().FullName)
    if page_runtime != MODBUS_TCP_SLAVE_PAGE_TYPE:
        raise OperationError(
            "live page is not the installed Modbus TCP slave page",
            "modbus_tcp_slave_page_mismatch",
            {"expected": MODBUS_TCP_SLAVE_PAGE_TYPE, "observed": page_runtime,
             "mutatedProject": False},
        )
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    control_field = contract["controlField"]
    control, parts, owner = _resolve_vendor_page_control(
        page, control_field, flags)
    if control is None or parts != [control_field]:
        raise OperationError(
            "exact Modbus TCP slave page control was not found",
            "modbus_tcp_slave_control_mismatch",
            {"controlField": control_field, "controlPath": parts,
             "ownerType": (_text(owner.GetType().FullName)
                           if owner is not None else None),
             "mutatedProject": False},
        )
    return {
        "pageType": page_runtime,
        "editorConnectorId": contract["editorConnectorId"],
        "control": _vendor_page_control_snapshot(control, control_field),
        "editor": {"runtimeType": editor_detail.get("editor", {}).get(
            "runtimeType") if isinstance(editor_detail, dict) else None},
    }


def vendor_protocol_modbus_tcp_slave_parameter_read(req):
    """Read an allow-listed Modbus TCP slave field from native and UI state."""
    _require_project()
    target = _text(req.get("target") or req.get("name") or "").strip()
    field = _text(req.get("field") or "").strip()
    if not target or not field:
        raise OperationError(
            "target and field are required", "invalid_argument",
            {"supportedFields": sorted(MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS)})
    contract = MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS.get(field)
    if contract is None:
        raise OperationError(
            "field is not an allow-listed Modbus TCP slave parameter",
            "modbus_tcp_slave_field_unsupported",
            {"field": field,
             "supportedFields": sorted(MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS),
             "mutatedProject": False},
        )
    native = _modbus_tcp_slave_native_snapshot(target, contract)
    try:
        page = _modbus_tcp_slave_page_snapshot(req, contract)
    except OperationError as exc:
        if exc.code in ("modbus_tcp_slave_page_mismatch",
                        "modbus_tcp_slave_control_mismatch"):
            # The TcpSlavePage editor was never opened in this project, so
            # its controls do not exist yet. The native read is still exact —
            # report it instead of failing the read.
            page = {"available": False, "errorCode": exc.code,
                    "reason": "TcpSlavePage editor not opened in this project yet"}
        else:
            raise
    control_value = page.get("control", {}).get("value") if isinstance(page, dict) else None
    return {
        "target": target, "field": field, "contract": dict(contract),
        "native": native, "page": page,
        "valuesMatch": _text(native.get("value")) == _text(control_value),
        "mutatedProject": False, "status": "observed",
    }


def _modbus_tcp_slave_integer_value(req, contract):
    raw = _text(req.get("value")).strip()
    try:
        value = int(raw)
    except Exception:
        raise OperationError(
            "Modbus TCP slave parameter requires a canonical integer",
            "modbus_tcp_slave_value_invalid",
            {"requested": req.get("value"), "correctFormat": {"value": 502},
             "mutatedProject": False},
        )
    if raw != _text(value):
        raise OperationError(
            "Modbus TCP slave parameter requires canonical integer text",
            "modbus_tcp_slave_value_invalid",
            {"requested": req.get("value"), "canonical": value,
             "mutatedProject": False},
        )
    if value < contract["minimum"] or value > contract["maximum"]:
        raise OperationError(
            "Modbus TCP slave parameter is outside the vendor range",
            "modbus_tcp_slave_value_out_of_range",
            {"requested": value, "minimum": contract["minimum"],
             "maximum": contract["maximum"], "mutatedProject": False},
        )
    return value


def vendor_protocol_modbus_tcp_slave_parameter_write(req):
    """Write one verified TcpSlavePage parameter through the vendor editor."""
    _require_project()
    operation = "vendor.protocol.modbus.tcp_slave.parameter.write"
    if req.get("confirm") != "write_modbus_tcp_slave_parameter":
        raise OperationError(
            "confirm must exactly equal write_modbus_tcp_slave_parameter",
            "confirmation_required")
    _require_current_disposable_project(req, operation)
    if req.get("runtimeValidation") is not True:
        raise OperationError(
            "runtimeValidation=true is required for a Modbus TCP slave write",
            "runtime_validation_required",
            {"correctFormat": {"runtimeValidation": True,
             "disposable": True,
             "confirm": "write_modbus_tcp_slave_parameter"}},
        )
    target = _text(req.get("target") or req.get("name") or "").strip()
    field = _text(req.get("field") or "").strip()
    if not target or not field or req.get("value") is None:
        raise OperationError(
            "target, field and value are required", "invalid_argument",
            {"supportedFields": sorted(MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS)})
    contract = MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS.get(field)
    if contract is None:
        raise OperationError(
            "field is not an allow-listed Modbus TCP slave parameter",
            "modbus_tcp_slave_field_unsupported",
            {"field": field,
             "supportedFields": sorted(MODBUS_TCP_SLAVE_PARAMETER_CONTRACTS),
             "mutatedProject": False},
        )
    requested = _modbus_tcp_slave_integer_value(req, contract)
    native_before = _modbus_tcp_slave_native_snapshot(target, contract)
    try:
        page_before = _modbus_tcp_slave_page_snapshot(req, contract)
        page_available = True
    except OperationError as exc:
        if exc.code in ("modbus_tcp_slave_page_mismatch",
                        "modbus_tcp_slave_control_mismatch"):
            page_before = {"available": False, "errorCode": exc.code}
            page_available = False
        else:
            raise
    expected = _text(requested)
    if _text(native_before.get("value")) == expected:
        raise OperationError(
            "requested Modbus TCP slave value equals the current native value",
            "modbus_tcp_slave_validation_value_unchanged",
            {"field": field, "requested": requested,
             "nativeBefore": native_before, "mutatedProject": False},
        )
    receipt = {
        "operation": operation, "target": target, "field": field,
        "contract": dict(contract), "input": requested,
        "before": {"native": native_before, "page": page_before},
        "after": None, "genericWrite": None,
        "mutatedProject": False, "committed": False,
    }
    if not page_available:
        # Fresh project: the TcpSlavePage editor was never opened, so its
        # controls do not exist. The native parameter write is the same value
        # the page would commit — verified live in round 11 (Port 1502).
        native_write = _modbus_tcp_slave_native_write(target, contract, expected)
        receipt["nativeFallbackWrite"] = native_write
        receipt["mutatedProject"] = bool(native_write.get("mutatedProject"))
        receipt["committed"] = bool(native_write.get("committed"))
        receipt["after"] = {"nativeAfter": native_write,
                            "valuesMatch": native_write.get("committed")}
        if not receipt["committed"]:
            raise OperationError(
                "Modbus TCP slave native fallback write did not retain",
                "modbus_tcp_slave_native_fallback_not_retained",
                receipt)
        receipt["status"] = "modbus_tcp_slave_parameter_native_fallback"
        receipt["projectSaveRequired"] = True
        return receipt

    normalized = dict(req)
    normalized.update({
        "confirm": "write_vendor_editor_page_parameter",
        "target": target, "field": contract["parameterField"],
        "controlField": contract["controlField"],
        "controlKind": "numeric", "value": requested,
        "pageType": MODBUS_TCP_SLAVE_PAGE_TYPE,
        "connectorId": contract["editorConnectorId"],
        "parameterId": contract["parameterId"],
        "parameterField": contract["parameterField"],
        # The generic page write's own retention rebind navigates
        # [parameterField] by name; fresh projects expose the Port element by
        # numeric index only. This caller verifies retention itself through
        # the fallback-aware native snapshot below.
        "skipRetentionCheck": True,
    })
    generic_invoked = False
    try:
        generic_invoked = True
        generic_write = vendor_editor_page_parameter_write(normalized)
        receipt["genericWrite"] = generic_write
        receipt["mutatedProject"] = bool(generic_write.get("mutatedProject"))
        # TcpSlavePage.Save only copies its controls into DeviceEditor's
        # writable meta-object.  The parent editor owns the ObjectMgr.SetObject
        # commit, exactly as InoDeviceEditor.DeviceEditor.Save implements it.
        _commit_view, commit_frame, commit_detail = (
            _open_vendor_editor_match(normalized))
        parent_editor = _get_member(commit_frame, "Editor", "get_Editor")
        if parent_editor is None:
            raise OperationError(
                "Modbus TCP slave parent device editor is unavailable",
                "modbus_tcp_slave_parent_editor_unavailable",
                {"processDiscardRequired": True},
            )
        parent_save_return = parent_editor.Save(True)
        receipt["parentCommit"] = {
            "binding": "Inovance.InoPro.InoDeviceEditor.DeviceEditor.Save",
            "runtimeType": _text(parent_editor.GetType().FullName),
            "saveReturn": _json_safe(parent_save_return),
            "editor": commit_detail,
        }
        native_after_save = _modbus_tcp_slave_native_snapshot(target, contract)
        page_after_save = _modbus_tcp_slave_page_snapshot(req, contract)
        control_after = page_after_save["control"].get("value")
        if (_text(native_after_save.get("value")) != expected or
                _text(control_after) != expected):
            raise OperationError(
                "Modbus TCP slave write did not retain native and UI values",
                "modbus_tcp_slave_save_not_retained",
                {"expected": expected, "nativeAfterSave": native_after_save,
                 "pageAfterSave": page_after_save,
                 "processDiscardRequired": True},
            )
        receipt["after"] = {
            "nativeAfterSave": native_after_save,
            "pageAfterSave": page_after_save,
            "valuesMatch": True,
        }
        receipt["committed"] = True
    except OperationError as exc:
        if generic_invoked:
            exc.data["processDiscardRequired"] = True
            exc.data.setdefault("receipt", receipt)
        raise
    except Exception as exc:
        receipt["error"] = repr(exc)
        receipt["processDiscardRequired"] = generic_invoked
        raise OperationError(
            "Modbus TCP slave vendor write failed: " + repr(exc),
            "modbus_tcp_slave_write_failed", receipt)
    receipt["status"] = "modbus_tcp_slave_parameter_editor_saved"
    receipt["projectSaveRequired"] = True
    receipt["freshProcessReadback"] = {
        "operation": "vendor.protocol.modbus.tcp_slave.parameter.read",
        "target": target, "field": field, "expected": expected,
    }
    return receipt


