def _canopen_master_native_snapshot(target, contract):
    """Read one exact CANopen master value from ObjectMgr."""
    _object_mgr, _meta, native, identity = _native_device_object(target, "read")
    parameter = _native_parameter_from_device(
        native, contract["parameterId"], contract["connectorId"])
    parameter_type = _text(_get_member(parameter, "ParamType", "get_ParamType"))
    if parameter_type != contract["parameterType"]:
        raise OperationError(
            "CANopen master parameter type does not match the installed binding",
            "canopen_master_parameter_type_mismatch",
            {"expected": contract["parameterType"], "observed": parameter_type,
             "identity": identity, "mutatedProject": False},
        )
    if contract.get("parameterRoot"):
        element, parts = parameter, []
    else:
        element, parts = _native_element_at_path(
            parameter, [contract["parameterField"]])
    return {
        "binding": "SystemInstances.ObjectMgr.GetObjectToRead",
        "identity": identity,
        "connectorId": contract["connectorId"],
        "parameterId": contract["parameterId"],
        "parameterType": parameter_type,
        "elementPath": parts,
        "value": _native_element_value(element),
        "snapshot": _native_element_snapshot(element, 0, 1),
    }


def vendor_protocol_canopen_master_parameter_read(req):
    """Read one allow-listed CANopen master field from ObjectMgr and its page."""
    _require_project()
    target = _text(req.get("target") or req.get("name") or "").strip()
    field = _text(req.get("field") or "").strip()
    if not target or not field:
        raise OperationError(
            "target and field are required", "invalid_argument",
            {"supportedFields": sorted(CANOPEN_MASTER_PARAMETER_CONTRACTS)})
    contract = CANOPEN_MASTER_PARAMETER_CONTRACTS.get(field)
    if contract is None:
        raise OperationError(
            "field is not an allow-listed CANopen master parameter",
            "canopen_master_field_unsupported",
            {"field": field,
             "supportedFields": sorted(CANOPEN_MASTER_PARAMETER_CONTRACTS),
             "mutatedProject": False})
    native = _canopen_master_native_snapshot(target, contract)
    page_request = dict(req)
    page_request["pageType"] = CANOPEN_MASTER_PAGE_TYPE
    page, _frame, editor_detail, _pages = _vendor_editor_page(page_request)
    page_runtime = _text(page.GetType().FullName)
    if page_runtime != CANOPEN_MASTER_PAGE_TYPE:
        raise OperationError(
            "live page is not the installed CANopen master page",
            "canopen_master_page_mismatch",
            {"expected": CANOPEN_MASTER_PAGE_TYPE, "observed": page_runtime,
             "mutatedProject": False})
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    controls = {}
    for control_field in contract.get(
            "controlFields", [contract.get("controlField")]):
        control, parts, owner = _resolve_vendor_page_control(
            page, control_field, flags)
        if control is None or parts != [control_field]:
            raise OperationError(
                "exact CANopen page control was not found",
                "canopen_master_control_mismatch",
                {"field": field, "controlField": control_field,
                 "controlPath": parts,
                 "ownerType": (_text(owner.GetType().FullName)
                               if owner is not None else None),
                 "mutatedProject": False})
        controls[control_field] = _vendor_page_control_snapshot(
            control, control_field)
    result = {
        "target": target, "field": field, "contract": dict(contract),
        "native": native, "controls": controls,
        "pageType": page_runtime,
        "editor": {"runtimeType": editor_detail.get("editor", {}).get(
            "runtimeType") if isinstance(editor_detail, dict) else None},
        "mutatedProject": False, "status": "observed",
    }
    if field == "sync_period_us":
        result["semanticValidation"] = _canopen_sync_task_cycle()
        result["taskCycleMultiple"] = (
            int(_text(native["value"])) %
            result["semanticValidation"]["cycleUs"] == 0)
    return result


def _canopen_master_integer_value(req, contract, control):
    raw = _text(req.get("value")).strip()
    try:
        value = int(raw)
    except Exception:
        raise OperationError(
            "CANopen integer parameter requires a canonical integer",
            "canopen_master_value_invalid",
            {"requested": req.get("value"), "correctFormat": {"value": 100}},
        )
    if raw != _text(value):
        raise OperationError(
            "CANopen integer parameter requires canonical integer text",
            "canopen_master_value_invalid",
            {"requested": req.get("value"), "canonical": value},
        )
    live_minimum = int(_text(_get_member(control, "Minimum", "get_Minimum")))
    live_maximum = int(_text(_get_member(control, "Maximum", "get_Maximum")))
    minimum = max(live_minimum, int(contract.get("minimum", live_minimum)))
    maximum = min(live_maximum, int(contract.get("maximum", live_maximum)))
    if value < minimum or value > maximum:
        raise OperationError(
            "CANopen integer parameter is outside the live vendor range",
            "canopen_master_value_out_of_range",
            {"requested": value, "minimum": minimum, "maximum": maximum,
             "liveMinimum": live_minimum, "liveMaximum": live_maximum},
        )
    multiple = contract.get("multipleOf")
    if multiple and value % int(multiple) != 0:
        raise OperationError(
            "CANopen integer parameter does not match the vendor step",
            "canopen_master_value_step_mismatch",
            {"requested": value, "multipleOf": int(multiple)},
        )
    return value, _text(value)


def _canopen_sync_task_cycle():
    """Resolve the generated CANOPEN cyclic task and return its period in us."""
    matches = []
    for path, task in _find_tasks():
        if _object_name(task).strip().lower() == "canopen":
            matches.append((path, task))
    if len(matches) != 1:
        raise OperationError(
            "exactly one CANOPEN task is required for SYNC period validation",
            "canopen_sync_task_unavailable",
            {"matches": [path for path, _task in matches],
             "mutatedProject": False})
    path, task = matches[0]
    interval = _text(_get_member(task, "interval", "get_interval")).strip()
    match = re.match(r"^t#([0-9]+)(us|ms|s)$", interval.lower())
    if match is None:
        raise OperationError(
            "CANOPEN task interval format cannot be converted to microseconds",
            "canopen_sync_task_interval_unsupported",
            {"task": path, "interval": interval, "mutatedProject": False})
    scale = {"us": 1, "ms": 1000, "s": 1000000}[match.group(2)]
    cycle_us = int(match.group(1)) * scale
    if cycle_us <= 0:
        raise OperationError(
            "CANOPEN task cycle must be positive",
            "canopen_sync_task_interval_invalid",
            {"task": path, "interval": interval, "mutatedProject": False})
    return {"task": path, "interval": interval, "cycleUs": cycle_us}


def vendor_protocol_canopen_master_parameter_write(req):
    """Write one allow-listed CANopen master parameter through its real page."""
    _require_project()
    operation = "vendor.protocol.canopen.master.parameter.write"
    if req.get("confirm") != "write_canopen_master_parameter":
        raise OperationError(
            "confirm must exactly equal write_canopen_master_parameter",
            "confirmation_required")
    _require_current_disposable_project(req, operation)
    if req.get("runtimeValidation") is not True:
        raise OperationError(
            "runtimeValidation=true is required for a CANopen master write",
            "runtime_validation_required",
            {"correctFormat": {"runtimeValidation": True,
             "disposable": True,
             "confirm": "write_canopen_master_parameter"}},
        )
    target = _text(req.get("target") or req.get("name") or "").strip()
    field = _text(req.get("field") or "").strip()
    if not target or not field or req.get("value") is None:
        raise OperationError(
            "target, field and value are required", "invalid_argument",
            {"supportedFields": sorted(CANOPEN_MASTER_PARAMETER_CONTRACTS)})
    contract = CANOPEN_MASTER_PARAMETER_CONTRACTS.get(field)
    if contract is None:
        raise OperationError(
            "field is not an allow-listed CANopen master parameter",
            "canopen_master_field_unsupported",
            {"field": field,
             "supportedFields": sorted(CANOPEN_MASTER_PARAMETER_CONTRACTS),
             "mutatedProject": False},
        )

    page_request = dict(req)
    page_request["pageType"] = CANOPEN_MASTER_PAGE_TYPE
    page, frame, editor_detail, _pages = _vendor_editor_page(page_request)
    page_runtime = _text(page.GetType().FullName)
    if page_runtime != CANOPEN_MASTER_PAGE_TYPE:
        raise OperationError(
            "live page is not the installed CANopen master page",
            "canopen_master_page_mismatch",
            {"expected": CANOPEN_MASTER_PAGE_TYPE, "observed": page_runtime,
             "mutatedProject": False},
        )
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    controls = {}
    for control_field in contract.get(
            "controlFields", [contract.get("controlField")]):
        control, parts, owner = _resolve_vendor_page_control(
            page, control_field, flags)
        if control is None or parts != [control_field]:
            raise OperationError(
                "exact CANopen page control was not found",
                "canopen_master_control_mismatch",
                {"field": field, "controlField": control_field,
                 "controlPath": parts,
                 "ownerType": (_text(owner.GetType().FullName)
                               if owner is not None else None),
                 "mutatedProject": False},
            )
        controls[control_field] = control

    before_controls = {}
    for name, control in controls.items():
        before_controls[name] = _vendor_page_control_snapshot(control, name)
    native_before = _canopen_master_native_snapshot(target, contract)
    kind = contract["kind"]
    expected = None
    normalized_input = None
    semantic_validation = None

    if kind == "integer":
        control = controls[contract["controlField"]]
        if bool(_get_member(control, "ReadOnly", "get_ReadOnly", False)):
            raise OperationError(
                "CANopen page control is read-only in this target profile",
                "canopen_master_control_read_only",
                {"field": field, "control": before_controls,
                 "mutatedProject": False})
        if not bool(_get_member(control, "Enabled", "get_Enabled", True)):
            raise OperationError(
                "CANopen page control is disabled by the current configuration",
                "canopen_master_control_disabled",
                {"field": field, "control": before_controls,
                 "requiredState": ("enable the owning CANopen feature first"
                                   if field.startswith("heartbeat_") else None),
                 "mutatedProject": False})
        normalized_input, expected = _canopen_master_integer_value(
            req, contract, control)
        if field == "sync_period_us":
            semantic_validation = _canopen_sync_task_cycle()
            cycle_us = semantic_validation["cycleUs"]
            if normalized_input % cycle_us != 0:
                raise OperationError(
                    "CANopen SYNC period must be an integer multiple of the CANOPEN task cycle",
                    "canopen_sync_period_task_cycle_mismatch",
                    {"requested": normalized_input,
                     "taskCycleUs": cycle_us,
                     "nearestLower": (normalized_input // cycle_us) * cycle_us,
                     "nearestHigher": ((normalized_input + cycle_us - 1) // cycle_us) * cycle_us,
                     "task": semantic_validation,
                     "correctFormat": {"value": cycle_us * 10},
                     "mutatedProject": False},
                )
    elif kind == "boolean":
        if not isinstance(req.get("value"), bool):
            raise OperationError(
                "CANopen boolean parameter requires a JSON boolean",
                "canopen_master_value_invalid",
                {"requested": req.get("value"), "correctFormat": {"value": True},
                 "mutatedProject": False})
        normalized_input = bool(req.get("value"))
        expected = "1" if normalized_input else "0"
    elif kind == "selection_text":
        control = controls[contract["controlField"]]
        items = [_text(item) for item in list(control.Items)]
        normalized_input = _text(req.get("value")).strip()
        if normalized_input not in items:
            raise OperationError(
                "CANopen selection is not present in the live vendor control",
                "canopen_master_value_invalid",
                {"requested": normalized_input, "allowedValues": items,
                 "mutatedProject": False})
        expected = normalized_input
    elif kind == "sync_role":
        normalized_input = _text(req.get("value")).strip().lower()
        expected = contract["values"].get(normalized_input)
        if expected is None:
            raise OperationError(
                "CANopen sync role is invalid", "canopen_master_value_invalid",
                {"requested": req.get("value"),
                 "allowedValues": sorted(contract["values"]),
                 "mutatedProject": False})

    if _text(native_before.get("value")) == expected:
        raise OperationError(
            "requested CANopen value equals the current native value",
            "canopen_master_validation_value_unchanged",
            {"field": field, "requested": normalized_input,
             "nativeBefore": native_before, "mutatedProject": False})
    receipt = {
        "operation": operation, "target": target, "field": field,
        "contract": dict(contract), "input": normalized_input,
        "expectedNativeValue": expected,
        "semanticValidation": semantic_validation,
        "before": {"controls": before_controls, "native": native_before},
        "after": None, "editor": {
            "runtimeType": editor_detail.get("editor", {}).get("runtimeType")
            if isinstance(editor_detail, dict) else None,
            "pageType": page_runtime,
            "summaryOnly": True,
        },
        "mutatedProject": False, "committed": False,
    }
    try:
        if kind == "integer":
            controls[contract["controlField"]].Value = System.Decimal(
                normalized_input)
        elif kind == "boolean":
            controls[contract["controlField"]].Checked = normalized_input
        elif kind == "selection_text":
            control = controls[contract["controlField"]]
            control.SelectedIndex = [_text(item) for item in list(
                control.Items)].index(normalized_input)
        elif kind == "sync_role":
            consumer = controls["_chkEnableConsumer"]
            producer = controls["_chkEnableProducer"]
            if normalized_input == "producer":
                consumer.Checked = False
                producer.Checked = True
            elif normalized_input == "optional_consumer":
                producer.Checked = False
                consumer.Checked = True
            else:
                consumer.Checked = False
                producer.Checked = False
        receipt["mutatedProject"] = True
        save_return = frame.Editor.Save(True)
        native_after_save = _canopen_master_native_snapshot(target, contract)
        if _text(native_after_save.get("value")) != expected:
            raise OperationError(
                "CANopen editor did not retain the exact native value",
                "canopen_master_save_not_retained",
                {"receipt": receipt, "afterSave": native_after_save,
                 "processDiscardRequired": True})
        page.Reload()
        after_controls = {}
        for name, control in controls.items():
            after_controls[name] = _vendor_page_control_snapshot(control, name)
        receipt["after"] = {
            "controlsAfterReload": after_controls,
            "nativeAfterSave": native_after_save,
            "editorSaveReturn": _json_safe(save_return),
        }
        receipt["committed"] = True
    except OperationError as exc:
        if receipt["mutatedProject"]:
            exc.data["processDiscardRequired"] = True
            exc.data.setdefault("receipt", receipt)
        raise
    except Exception as exc:
        receipt["error"] = repr(exc)
        receipt["processDiscardRequired"] = receipt["mutatedProject"]
        raise OperationError(
            "CANopen master vendor write failed: " + repr(exc),
            "canopen_master_write_failed", receipt)
    receipt["status"] = "canopen_master_parameter_editor_saved"
    receipt["projectSaveRequired"] = True
    receipt["freshProcessReadback"] = {
        "operation": "vendor.editor.parameter.read", "target": target,
        "connectorId": contract["connectorId"],
        "parameterId": contract["parameterId"],
        "elementPath": ([] if contract.get("parameterRoot") else
                        [contract["parameterField"]]),
        "expected": expected,
    }
    return receipt


def _canopen_heartbeat_native_snapshot(target):
    """Read producer time from ObjectMgr's native DeviceObject."""
    contract = CANOPEN_HEARTBEAT_PRODUCER_CONTRACT
    _object_mgr, _meta, native, identity = _native_device_object(target, "read")
    parameter = _native_parameter_from_device(
        native, contract["parameterId"], contract["connectorId"])
    parameter_type = _text(_get_member(parameter, "ParamType", "get_ParamType"))
    if parameter_type != contract["parameterType"]:
        raise OperationError(
            "CANopen heartbeat parameter type does not match the verified binding",
            "canopen_heartbeat_parameter_type_mismatch",
            {"expected": contract["parameterType"], "observed": parameter_type,
             "identity": identity, "mutatedProject": False},
        )
    element, parts = _native_element_at_path(
        parameter, [contract["parameterField"]])
    return {
        "binding": "SystemInstances.ObjectMgr.GetObjectToRead",
        "identity": identity,
        "connectorId": contract["connectorId"],
        "parameterId": contract["parameterId"],
        "parameterType": parameter_type,
        "elementPath": parts,
        "value": _native_element_value(element),
        "snapshot": _native_element_snapshot(element, 0, 1),
    }


def vendor_protocol_canopen_heartbeat_write(req):
    """Write only CANopen master heartbeat producer time through its vendor page."""
    _require_project()
    operation = "vendor.protocol.canopen.heartbeat.write"
    if req.get("confirm") != "write_canopen_heartbeat_producer_time":
        raise OperationError(
            "confirm must exactly equal write_canopen_heartbeat_producer_time",
            "confirmation_required",
        )
    _require_current_disposable_project(req, operation)
    if req.get("runtimeValidation") is not True:
        raise OperationError(
            "runtimeValidation=true is required for a CANopen heartbeat write",
            "runtime_validation_required",
            {"correctFormat": {"runtimeValidation": True, "disposable": True,
             "confirm": "write_canopen_heartbeat_producer_time"}},
        )
    target = _text(req.get("target") or req.get("name") or "").strip()
    if not target:
        raise OperationError("target is required", "invalid_argument")
    if req.get("value") is None:
        raise OperationError("value is required", "invalid_argument")

    contract = CANOPEN_HEARTBEAT_PRODUCER_CONTRACT
    exact_inputs = (
        ("pageType", contract["pageType"]),
        ("field", contract["controlField"]),
        ("controlField", contract["controlField"]),
        ("parameterField", contract["parameterField"]),
    )
    for key, expected in exact_inputs:
        if key in req and _text(req.get(key)) != expected:
            raise OperationError(
                "CANopen heartbeat request does not match the verified binding",
                "canopen_heartbeat_binding_mismatch",
                {"field": key, "expected": expected, "observed": req.get(key),
                 "mutatedProject": False},
            )
    for key in ("connectorId", "parameterId"):
        if key not in req:
            continue
        try:
            observed = int(req.get(key))
        except Exception:
            observed = None
        if observed != contract[key]:
            raise OperationError(
                "CANopen heartbeat request does not match the verified binding",
                "canopen_heartbeat_binding_mismatch",
                {"field": key, "expected": contract[key],
                 "observed": req.get(key), "mutatedProject": False},
            )

    raw_value = _text(req.get("value")).strip()
    try:
        requested_value = int(raw_value)
    except Exception:
        raise OperationError(
            "CANopen heartbeat producer time must be an integer",
            "editor_value_invalid",
            {"requested": req.get("value"), "mutatedProject": False},
        )
    if raw_value != _text(requested_value):
        raise OperationError(
            "CANopen heartbeat producer time must use canonical integer format",
            "editor_value_invalid",
            {"requested": req.get("value"), "canonical": _text(requested_value),
             "mutatedProject": False},
        )
    if (requested_value < contract["minimum"] or
            requested_value > contract["maximum"]):
        raise OperationError(
            "CANopen heartbeat producer time is outside the vendor range",
            "editor_value_out_of_range",
            {"minimum": contract["minimum"], "maximum": contract["maximum"],
             "requested": requested_value, "mutatedProject": False},
        )

    page_request = dict(req)
    page_request["pageType"] = contract["pageType"]
    page, frame, editor_detail, _pages = _vendor_editor_page(page_request)
    page_runtime = _text(page.GetType().FullName)
    if page_runtime != contract["pageType"]:
        raise OperationError(
            "the live vendor page is not the verified CANopen master page",
            "canopen_heartbeat_page_mismatch",
            {"expected": contract["pageType"], "observed": page_runtime,
             "mutatedProject": False},
        )
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    control, parts, resolved = _resolve_vendor_page_control(
        page, contract["controlField"], flags)
    control_runtime = (_text(control.GetType().FullName)
                       if control is not None else None)
    if (control is None or parts != [contract["controlField"]] or
            control_runtime != contract["controlType"]):
        raise OperationError(
            "the exact CANopen heartbeat control was not found on the vendor page",
            "canopen_heartbeat_control_mismatch",
            {"controlField": contract["controlField"], "controlPath": parts,
             "expectedControlType": contract["controlType"],
             "observedControlType": control_runtime,
             "resolvedType": (_text(resolved.GetType().FullName)
                              if resolved is not None else None),
             "mutatedProject": False},
        )
    before_control = _vendor_page_control_snapshot(
        control, contract["controlField"])
    try:
        observed_minimum = int(_text(_get_member(control, "Minimum", "get_Minimum")))
        observed_maximum = int(_text(_get_member(control, "Maximum", "get_Maximum")))
    except Exception:
        raise OperationError(
            "CANopen heartbeat control does not expose integer bounds",
            "canopen_heartbeat_control_contract_mismatch",
            {"control": before_control, "mutatedProject": False},
        )
    if (observed_minimum != contract["minimum"] or
            observed_maximum != contract["maximum"]):
        raise OperationError(
            "CANopen heartbeat control bounds differ from the verified contract",
            "canopen_heartbeat_control_contract_mismatch",
            {"expectedMinimum": contract["minimum"],
             "expectedMaximum": contract["maximum"],
             "observedMinimum": observed_minimum,
             "observedMaximum": observed_maximum, "mutatedProject": False},
        )
    editor = _get_member(frame, "Editor", "get_Editor")
    if editor is None or getattr(editor, "Save", None) is None:
        raise OperationError(
            "CANopen device editor has no Save(bool)",
            "editor_save_unavailable",
            {"editor": {
                "runtimeType": editor_detail.get("editor", {}).get("runtimeType")
                if isinstance(editor_detail, dict) else None,
                "pageType": page_runtime,
                "summaryOnly": True,
            }, "mutatedProject": False},
        )
    native_before = _canopen_heartbeat_native_snapshot(target)
    if _text(native_before["value"]) == raw_value:
        raise OperationError(
            "requested heartbeat time equals the current native value",
            "canopen_heartbeat_validation_value_unchanged",
            {"requested": requested_value, "nativeBefore": native_before,
             "mutatedProject": False},
        )

    receipt = {
        "operation": operation, "target": target, "contract": dict(contract),
        "input": {"value": requested_value, "canonicalText": raw_value},
        "before": {"control": before_control, "native": native_before},
        "after": None, "editor": {
            "runtimeType": editor_detail.get("editor", {}).get("runtimeType")
            if isinstance(editor_detail, dict) else None,
            "pageType": page_runtime,
            "summaryOnly": True,
        },
        "mutatedProject": False, "committed": False,
    }
    try:
        decimal_value = System.Decimal.Parse(
            raw_value, System.Globalization.CultureInfo.InvariantCulture)
        control.Value = decimal_value
        receipt["mutatedProject"] = True
        after_event_control = _vendor_page_control_snapshot(
            control, contract["controlField"])
        if _text(after_event_control.get("value")) != raw_value:
            raise OperationError(
                "vendor heartbeat control did not retain the assigned value",
                "canopen_heartbeat_control_set_not_retained",
                {"receipt": receipt, "afterEventControl": after_event_control,
                 "processDiscardRequired": True},
            )
        save_return = frame.Editor.Save(True)
        after_save = _canopen_heartbeat_native_snapshot(target)
        if _text(after_save["value"]) != raw_value:
            raise OperationError(
                "CANopen editor Save(true) did not retain the native heartbeat value",
                "canopen_heartbeat_save_not_retained",
                {"receipt": receipt, "afterSave": after_save,
                 "processDiscardRequired": True},
            )
        page.Reload()
        after_control = _vendor_page_control_snapshot(
            control, contract["controlField"])
        if _text(after_control.get("value")) != raw_value:
            raise OperationError(
                "CANopen page reload does not match the native heartbeat value",
                "canopen_heartbeat_ui_readback_mismatch",
                {"receipt": receipt, "afterControl": after_control,
                 "afterSave": after_save, "processDiscardRequired": True},
            )
        receipt["after"] = {
            "eventControl": after_event_control, "editorSaveNative": after_save,
            "controlAfterReload": after_control,
            "editorSaveReturn": _json_safe(save_return),
        }
        receipt["committed"] = True
    except OperationError as exc:
        if receipt["mutatedProject"]:
            exc.data["processDiscardRequired"] = True
            exc.data.setdefault("receipt", receipt)
        raise
    except Exception as exc:
        receipt["error"] = repr(exc)
        receipt["processDiscardRequired"] = receipt["mutatedProject"]
        raise OperationError(
            "CANopen heartbeat vendor write failed: " + repr(exc),
            "canopen_heartbeat_write_failed", receipt,
        )
    receipt["status"] = "canopen_heartbeat_editor_saved"
    receipt["projectSaveRequired"] = True
    receipt["freshProcessReadback"] = {
        "operation": "vendor.editor.parameter.read", "target": target,
        "connectorId": contract["connectorId"],
        "parameterId": contract["parameterId"],
        "elementPath": [contract["parameterField"]], "expected": raw_value,
    }
    return receipt


def _pid_page_context(req, require_parent=False):
    """Resolve and validate a PID page without invoking any mutating member."""
    target = req.get("target") or req.get("path") or req.get("device")
    if not target:
        raise OperationError("vendor.pid.parameter operation requires target", "invalid_argument")
    script_object, object_path = find_project_object(target)
    _object_mgr, _meta, native, binding = _native_device_object(object_path, "read")
    observed = _pid_runtime_identity(script_object, native, binding)
    provisional_contract = _pid_contract(
        (observed.get("deviceId") or {}).get("type"))
    if provisional_contract is None:
        _contract, checks = _pid_validate_identity(observed)
        raise _pid_identity_error(object_path, observed, checks)
    page_request = dict(req)
    page_request["target"] = object_path
    page_request["pageType"] = provisional_contract["pageType"]
    page, frame, editor_detail, pages = _vendor_editor_page(page_request)
    observed = _pid_runtime_identity(script_object, native, binding, frame)
    contract, checks = _pid_validate_identity(observed)
    if contract is None:
        raise _pid_identity_error(object_path, observed, checks)
    page_runtime = _text(page.GetType().FullName)
    if page_runtime != contract["pageType"]:
        raise OperationError(
            "PID page runtime type does not match the exact module identity",
            "pid_page_identity_mismatch",
            {"target": object_path, "resolvedIdentity": observed,
             "expectedPageType": contract["pageType"], "actualPageType": page_runtime,
             "mutatedProject": False},
        )
    parent_types = []
    for item in (editor_detail.get("baseEditors", []) if isinstance(editor_detail, dict) else []):
        runtime = _text(item.get("runtimeType"))
        if runtime:
            parent_types.append(runtime)
    parent_found = contract["parentEditorType"] in parent_types
    if require_parent and not parent_found:
        raise OperationError(
            "PID parent editor binding is not confirmed; no write was attempted",
            "pid_runtime_binding_unverified",
            {"target": object_path, "resolvedIdentity": observed,
             "pageType": page_runtime, "parentEditorType": contract["parentEditorType"],
             "observedParentEditors": parent_types, "mutatedProject": False,
             "next": "capture a disposable runtime page and verify parent Save(bool) before enabling writes"},
        )
    return {
        "target": object_path, "scriptObject": script_object, "native": native,
        "binding": binding, "identity": observed, "contract": contract,
        "page": page, "frame": frame, "editor": editor_detail,
        "pageType": page_runtime, "parentTypes": parent_types,
        "parentFound": parent_found, "pages": pages,
    }


def _pid_parse_channel(value):
    """Parse a channel without silently truncating fractional values."""
    if isinstance(value, bool):
        raise OperationError("channel must be an integer", "invalid_argument",
                             {"channel": value})
    try:
        channel = int(value)
    except Exception:
        raise OperationError("channel must be an integer", "invalid_argument",
                             {"channel": value})
    # ``int(1.5)`` (and the equivalent CLR conversion) truncates.  Compare a
    # numeric projection as well so a malformed direct route call cannot land
    # on a neighbouring PID channel.  Strings such as "01" remain valid.
    try:
        if float(value) != float(channel):
            raise OperationError("channel must be an integer", "invalid_argument",
                                 {"channel": value})
    except OperationError:
        raise
    except Exception:
        pass
    return channel


def _pid_channel_context(context, req):
    """Resolve one exact channel control from StdModuleGenericPropPage."""
    channel_raw = req.get("channel")
    if channel_raw is None:
        raise OperationError(
            "channel is required for a PID parameter operation",
            "invalid_argument",
            {"correctFormat": {"channel": 0},
             "range": [0, int(context["contract"]["channelCount"]) - 1]},
        )
    channel = _pid_parse_channel(channel_raw)
    contract = context["contract"]
    if channel < 0 or channel >= int(contract["channelCount"]):
        raise OperationError(
            "channel is outside the installed PID module range",
            "pid_channel_out_of_range",
            {"channel": channel, "minimum": 0,
             "maximum": int(contract["channelCount"]) - 1,
             "mutatedProject": False},
        )
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.Public)
    list_field = context["page"].GetType().GetField(
        contract["controlListField"], flags)
    if list_field is None:
        raise OperationError(
            "PID channel control list field is unavailable",
            "pid_channel_controls_unavailable",
            {"pageType": context["pageType"],
             "controlListField": contract["controlListField"],
             "mutatedProject": False},
        )
    raw_controls = list_field.GetValue(context["page"])
    try:
        controls = list(raw_controls or [])
    except Exception as exc:
        raise OperationError(
            "PID channel control list cannot be enumerated: " + repr(exc),
            "pid_channel_controls_unavailable",
            {"pageType": context["pageType"], "mutatedProject": False},
        )
    observed = []
    matches = []
    for candidate in controls:
        runtime_type = _text(candidate.GetType().FullName)
        candidate_channel = _get_member(candidate, "Channel", "get_Channel")
        entry = {"runtimeType": runtime_type,
                 "channel": _json_safe(candidate_channel)}
        observed.append(entry)
        try:
            exact_channel = int(candidate_channel) == channel
        except Exception:
            exact_channel = False
        if runtime_type == contract["controlType"] and exact_channel:
            matches.append(candidate)
    if len(matches) != 1:
        raise OperationError(
            "expected exactly one PID channel control",
            "pid_channel_control_ambiguous",
            {"channel": channel, "expectedControlType": contract["controlType"],
             "matchCount": len(matches), "observedControls": observed,
             "mutatedProject": False},
        )
    return {"channel": channel, "control": matches[0],
            "controlType": contract["controlType"],
            "controlCount": len(controls), "observedControls": observed,
            "flags": flags}


def _pid_control_snapshot(control, field):
    result = _vendor_page_control_snapshot(
        control, field, _text(control.GetType().FullName))
    for key, prop in (("minVal", "MinVal"), ("maxVal", "MaxVal"),
                      ("decimalNum", "DecimalNum"),
                      ("isSupportDecimal", "IsSupportDecimal"),
                      ("isSupportSigned", "IsSupportSigned"),
                      ("validValue", "ValidValue")):
        value = _get_member(control, prop, "get_" + prop)
        if value is not None:
            result[key] = _json_safe(value)
    return result


def _pid_channel_runtime_state(channel_context):
    control = channel_context["control"]
    flags = channel_context["flags"]
    result = {}
    for key, field_name in (("isEditing", "_isEditing"),
                            ("moduleEditor", "_moduleDevEditor"),
                            ("cpuModule", "bCpuModule")):
        native_field = control.GetType().GetField(field_name, flags)
        if native_field is None:
            result[key] = {"available": False}
            continue
        value = native_field.GetValue(control)
        result[key] = {
            "available": True,
            "value": _json_safe(value) if key != "moduleEditor" else None,
            "runtimeType": (_text(value.GetType().FullName)
                            if value is not None and hasattr(value, "GetType")
                            else None),
            "nonNull": value is not None,
        }
    return result


def _pid_native_byte(value):
    """Parse one vendor byte while preserving IEC hexadecimal semantics."""
    text = _text(value).strip()
    try:
        number = int(text[3:], 16) if text.lower().startswith("16#") else int(text)
    except Exception:
        return None
    return number if 0 <= number <= 255 else None


def _pid_byte_array(value):
    """Normalize a native CfgParam byte array from Python or CLR shapes.

    InoProShop versions do not expose the parameter consistently: some return
    a normal list/tuple (or an enumerable ``System.Byte[]``), while the
    IronPython wrapper used by the resident bridge stringifies the same value
    as ``{16#A2, 16#0, ...}``.  Treat the textual representation as a strict
    IEC byte array and fail closed on any malformed/partial value so a PID
    write can never be reported as verified from an accidental string match.
    """
    # A mapping/set is not an ordered byte sequence.  ``list(value)`` would
    # otherwise turn a dict into its (possibly numeric) keys or a set into an
    # arbitrary order, allowing a metadata object to masquerade as CfgParam
    # bytes.  Keep this local (rather than adding module globals) so the
    # helper remains usable in the small AST-isolated regression tests too.
    try:
        try:
            from collections.abc import Mapping as _PidMapping
            from collections.abc import Set as _PidSet
        except ImportError:
            from collections import Mapping as _PidMapping
            from collections import Set as _PidSet
        if isinstance(value, (_PidMapping, _PidSet)):
            return None
    except Exception:
        # Python/CLR builds without ``collections.abc`` still get the explicit
        # built-in guard below; do not make parsing fail merely because the
        # optional type metadata is unavailable.
        pass
    if isinstance(value, (dict, set, frozenset)):
        return None
    items = None
    if isinstance(value, (list, tuple)):
        items = list(value)
    elif not isinstance(value, _STRING_TYPES):
        # CLR arrays generally implement IEnumerable, but do not turn an
        # arbitrary vendor object into a false-positive byte dump.
        try:
            candidate = list(value)
            if candidate:
                items = candidate
        except Exception:
            items = None
    if items is None:
        text = _text(value).strip()
        # Prefer an explicit ``value={...}`` member when a wrapper includes
        # metadata; otherwise use the first brace-delimited array.
        match = re.search(r"(?i)value\s*=\s*\{([^{}]*)\}", text)
        if match is None:
            match = re.search(r"\{([^{}]*)\}", text)
        if match is None:
            return None
        body = match.group(1)
        items = [item.strip() for item in body.split(",")]
        if not items or any(item == "" for item in items):
            return None
    result = []
    for item in items:
        parsed = _pid_native_byte(item)
        if parsed is None:
            return None
        result.append(parsed)
    return result or None


def _pid_connector_resolution(device_object, requested_connector_id):
    """Describe the connector interpretation used by the native PID path.

    The InoProShop editor and the device-object wrapper use two different
    conventions in the installed build: ``GetConnector(1, ...)`` takes the
    physical connector id, while ``device.Connectors[1]`` is an array index
    whose object has physical ``ConnectorId=2``.  Keep the old index behavior
    for compatibility, but expose both values so a receipt cannot silently
    conflate them.
    """
    try:
        requested = int(requested_connector_id)
    except Exception:
        requested = None
    result = {
        "requestedConnectorId": requested,
        "connectorIndex": requested,
        "resolvedPhysicalConnectorId": None,
        "resolution": "array_index",
    }
    if device_object is None or requested is None:
        result["resolution"] = "unresolved"
        return result
    try:
        connectors = device_object.Connectors
    except Exception:
        connectors = _get_member(device_object, "connectors", "get_Connectors")
    connector = None
    try:
        connector = connectors[requested]
    except Exception:
        try:
            connector = list(connectors)[requested]
        except Exception:
            connector = None
    if connector is None:
        result["resolution"] = "unresolved"
        return result
    physical = _get_member(connector, "ConnectorId", "get_ConnectorId")
    try:
        result["resolvedPhysicalConnectorId"] = int(physical)
    except Exception:
        result["resolvedPhysicalConnectorId"] = None
    try:
        result["connectorRuntimeType"] = _text(connector.GetType().FullName)
    except Exception:
        pass
    return result


def _pid_native_snapshot(context, binding, channel, writable=False):
    """Read the exact native fields affected by one PID control event.

    Fresh projects expose CfgParam's 178 children position-indexed with NO
    names (round-25 evidence: every child is an unnamed
    DataElementSimpleType), while the evidence layout has named
    Ch{channel}_DeadBand_L/H children. When *all* named children are absent
    this returns namedChildrenAbsent instead of raising, so the caller can
    fall back to a full byte-diff verification. A partial miss is reported
    separately and is never treated as an unnamed layout.
    """
    native_contract = context["contract"]["nativeParameter"]
    fields = [item.format(channel=channel)
              for item in binding["nativeFields"]]
    values = []
    attempts = []
    missing = []
    connector_resolution = {
        "requestedConnectorId": int(native_contract["connectorId"]),
        "connectorIndex": None,
        "resolvedPhysicalConnectorId": None,
        "resolution": "editor_connector_id",
    }
    for field in fields:
        resolved_via_index = False
        request = {
            "connectorId": native_contract["connectorId"],
            "parameterId": native_contract["parameterId"],
            "elementPath": [field],
        }
        try:
            connector_id, _parameter, element, parts, field_attempts = (
                _editor_connector_parameter(context["frame"], request, writable))
        except OperationError as frame_error:
            # The installed PID control uses this exact path in Reload() and
            # TextChanged: DeviceEditorFrame.GetDeviceObject(read/write), then
            # CommonProc accesses deviceObject.Connectors[1].  GetConnector(1)
            # exposes a different wrapper whose HostParameterSet omits the
            # large vendor configuration parameter.
            device_object = context["frame"].GetDeviceObject(bool(writable))
            try:
                resolved_via_index = True
                parameter = _native_parameter_from_device(
                    device_object, native_contract["parameterId"],
                    native_contract["connectorId"])
                connector_resolution = _pid_connector_resolution(
                    device_object, native_contract["connectorId"])
                element, parts = _native_element_at_path(parameter, [field])
                connector_id = int(native_contract["connectorId"])
                field_attempts = [{
                    "binding": "DeviceEditorFrame.GetDeviceObject(%s).Connectors[%s]" %
                               (_text(bool(writable)).lower(), connector_id),
                    "fallbackFrom": getattr(frame_error, "code", "parameter_not_found"),
                    "status": "resolved",
                    "requestedConnectorId": connector_resolution.get(
                        "requestedConnectorId"),
                    "connectorIndex": connector_resolution.get("connectorIndex"),
                    "resolvedPhysicalConnectorId": connector_resolution.get(
                        "resolvedPhysicalConnectorId"),
                }]
            except OperationError as path_error:
                if path_error.code == "element_not_found":
                    missing.append({"field": field, "code": "element_not_found"})
                    continue
                raise
        raw = _native_element_value(element)
        if connector_id is not None and not resolved_via_index:
            connector_resolution["resolvedPhysicalConnectorId"] = int(connector_id)
        values.append({"field": field, "elementPath": parts, "value": raw,
                       "snapshot": _native_element_snapshot(element, 0, 1)})
        attempts.extend(field_attempts)
    decoded = None
    if binding.get("encoding") == "uint16_le_x10" and len(values) == 2:
        low = _pid_native_byte(values[0]["value"])
        high = _pid_native_byte(values[1]["value"])
        if low is not None and high is not None:
            decoded = ((high << 8) | low) / 10.0
    result = {
        "connectorId": int(native_contract["connectorId"]),
        "requestedConnectorId": connector_resolution.get(
            "requestedConnectorId"),
        "connectorIndex": connector_resolution.get("connectorIndex"),
        "resolvedPhysicalConnectorId": connector_resolution.get(
            "resolvedPhysicalConnectorId"),
        "connectorResolution": connector_resolution,
        "parameterId": int(native_contract["parameterId"]),
        "parameterType": native_contract["parameterType"],
        "encoding": binding.get("encoding"), "fields": values,
        "decodedValue": decoded, "attempts": attempts,
    }
    if missing:
        missing_fields = [item["field"] for item in missing]
        if len(missing) == len(fields) and not values:
            result["namedChildrenAbsent"] = missing_fields
            result["layout"] = "unnamed"
        else:
            result["namedChildrenPartial"] = missing_fields
            result["layout"] = "partial"
    else:
        result["layout"] = "named"
    return result


def _pid_cfg_bytes(context, writable=False, diagnostics=None):
    """Full byte dump of the PID module's CfgParam parameter.

    Fresh projects index CfgParam's children by position with no names; the
    parameter's own element value is the complete byte array, so a before/
    after diff of those bytes locates the changed uint16 region exactly.
    """
    contract = context["contract"]["nativeParameter"]
    detail = {
        "requestedConnectorId": int(contract["connectorId"]),
        "parameterId": int(contract["parameterId"]),
        "writable": bool(writable),
    }
    device = context["frame"].GetDeviceObject(bool(writable))
    if device is None:
        detail["error"] = "device_object_unavailable"
        if isinstance(diagnostics, dict):
            diagnostics.update(detail)
        return None
    connector_resolution = _pid_connector_resolution(
        device, contract["connectorId"])
    detail["connectorResolution"] = connector_resolution
    detail["connectorIndex"] = connector_resolution.get("connectorIndex")
    detail["resolvedPhysicalConnectorId"] = connector_resolution.get(
        "resolvedPhysicalConnectorId")
    raw_from_element_value = False
    try:
        parameter = _native_parameter_from_device(
            device, contract["parameterId"], contract["connectorId"])
        # Read the underlying value before _json_safe converts CLR arrays to
        # their textual ``{16#..}`` form.  The textual fallback below is still
        # needed for wrappers that only expose a string representation.
        try:
            raw = parameter.Value
        except Exception:
            raw = _get_member(parameter, "value", "get_Value")
        if raw is None:
            raw = _native_element_value(parameter)
            raw_from_element_value = True
    except Exception as exc:
        detail["error"] = repr(exc)
        if isinstance(diagnostics, dict):
            diagnostics.update(detail)
        return None
    try:
        detail["rawRuntimeType"] = _text(raw.GetType().FullName)
    except Exception:
        try:
            detail["rawRuntimeType"] = _text(type(raw).__name__)
        except Exception:
            pass
    parsed = _pid_byte_array(raw)
    detail["parseSource"] = (
        "native_element_value_initial" if raw_from_element_value
        else "parameter.Value")
    if parsed is None:
        # Some IronPython wrappers expose a non-enumerable CLR value object;
        # _native_element_value applies the bridge's safe string conversion,
        # which can reveal the real ``{16#..}`` representation.  Retry parsing
        # that representation before declaring the layout unavailable.
        try:
            fallback = _native_element_value(parameter)
        except Exception:
            fallback = None
        parsed = _pid_byte_array(fallback)
        if parsed is not None:
            detail["parseSource"] = "native_element_value_text"
    expected_length = None
    for getter_name in ("GetBitSize", "get_bit_size"):
        try:
            bit_size = int(getattr(parameter, getter_name)())
            if bit_size > 0:
                detail["bitSize"] = bit_size
                expected_length = (bit_size + 7) // 8
            break
        except Exception:
            pass
    child_count = len(_native_element_children(parameter))
    detail["childCount"] = child_count
    if expected_length is not None:
        detail["expectedByteLength"] = expected_length
    detail["byteLength"] = len(parsed) if parsed is not None else None
    if (parsed is not None and expected_length is not None and
            len(parsed) != expected_length):
        detail["lengthMatches"] = False
        detail["error"] = "byte_length_mismatch"
        parsed = None
    elif parsed is not None:
        detail["lengthMatches"] = True
    else:
        detail["error"] = "byte_array_unavailable"
    if isinstance(diagnostics, dict):
        diagnostics.update(detail)
    return parsed


def _pid_decode_bytes_diff(before_bytes, after_bytes, expected_value):
    """Decode one changed uint16_le_x10 region from two full byte dumps.

    Vendor versions differ in both layout and write granularity: a small
    value can change only the low byte, while a save can also touch unrelated
    bytes in the same structure.  Do not assume that the first changed byte
    is the field or that exactly two bytes changed.  Instead scan every
    adjacent little-endian pair and accept a *unique* pair whose after value
    is the requested value and whose before value was different.  Ambiguous
    or incomplete evidence remains a failure (fail closed).
    """
    if (before_bytes is None or after_bytes is None or
            len(before_bytes) != len(after_bytes) or len(before_bytes) < 2):
        return None
    changed = [index for index in range(len(before_bytes))
               if before_bytes[index] != after_bytes[index]]
    if not changed:
        return None
    candidates = []
    for start in range(len(before_bytes) - 1):
        before_low = before_bytes[start]
        before_high = before_bytes[start + 1]
        after_low = after_bytes[start]
        after_high = after_bytes[start + 1]
        if (None in (before_low, before_high, after_low, after_high) or
                (before_low == after_low and before_high == after_high)):
            continue
        before_decoded = ((before_high << 8) | before_low) / 10.0
        decoded = ((after_high << 8) | after_low) / 10.0
        if (abs(decoded - expected_value) <= 1e-6 and
                abs(before_decoded - expected_value) > 1e-6):
            candidates.append({
                "startIndex": start,
                "changedCount": sum(1 for index in (start, start + 1)
                                     if before_bytes[index] != after_bytes[index]),
                "totalChangedCount": len(changed),
                "beforeDecodedValue": before_decoded,
                "decodedValue": decoded,
            })
    if len(candidates) != 1:
        return None
    return candidates[0]


def _pid_parent_editor(context):
    base_editors = _get_member(
        context["frame"], "BaseDeviceEditors", "get_BaseDeviceEditors")
    try:
        candidates = list(base_editors or [])
    except Exception:
        candidates = []
    matches = [candidate for candidate in candidates
               if _text(candidate.GetType().FullName) ==
               context["contract"]["parentEditorType"]]
    if len(matches) != 1:
        raise OperationError(
            "expected exactly one PID parent editor",
            "pid_runtime_binding_unverified",
            {"expectedParentEditorType": context["contract"]["parentEditorType"],
             "observedParentEditors": [
                 _text(item.GetType().FullName) for item in candidates],
             "matchCount": len(matches), "mutatedProject": False},
        )
    return matches[0]


def vendor_pid_parameter_probe(req):
    """Read one exact PID channel and its statically confirmed controls."""
    context = _pid_page_context(req, require_parent=False)
    contract = context["contract"]
    channel_context = _pid_channel_context(context, req)
    channel_control = channel_context["control"]
    flags = channel_context["flags"]
    controls = []
    for field in contract["fields"]:
        control, parts, owner = _resolve_vendor_page_control(channel_control, field, flags)
        if control is None:
            controls.append({"field": field, "available": False, "controlPath": parts,
                             "ownerType": _text(owner.GetType().FullName) if owner is not None else None})
            continue
        controls.append({"field": field, "available": True,
                         "control": _pid_control_snapshot(control, field),
                         "nativeBinding": contract["writeBindings"].get(field)})
    native = {}
    for field, binding in contract["writeBindings"].items():
        try:
            native[field] = _pid_native_snapshot(
                context, binding, channel_context["channel"], False)
        except Exception as exc:
            native[field] = {"readError": repr(exc)}
    return {
        "operation": "vendor.pid.parameter.probe",
        "target": context["target"],
        "channel": channel_context["channel"],
        "resolvedIdentity": context["identity"],
        "binding": context["binding"],
        "pageType": context["pageType"],
        "controlListField": contract["controlListField"],
        "channelControlType": channel_context["controlType"],
        "channelControlCount": channel_context["controlCount"],
        "channelRuntimeState": _pid_channel_runtime_state(channel_context),
        "parentEditorType": context["contract"]["parentEditorType"],
        "parentEditorObserved": context["parentFound"],
        "allowedFields": list(contract["fields"]),
        "runtimeWriteFields": sorted(contract["writeBindings"]),
        "controls": controls,
        "nativeParameters": native,
        "diagnostics": {"staticContract": True, "runtimeBindingObserved": True,
                         "runtimeWriteVerified": False,
                         "saveReopenVerified": False, "compileSemanticsVerified": False},
        "valueReadbackSupported": True,
        "mutatedProject": False,
        "status": "pid_channel_controls_observed",
        "next": "perform an approved disposable write using a field listed in runtimeWriteFields",
    }


def vendor_pid_parameter_write(req):
    """Write one exact PID channel control through its vendor change event."""
    _require_project()
    operation = "vendor.pid.parameter.write"
    if req.get("confirm") != "write_pid_parameter":
        raise OperationError("confirm must exactly equal write_pid_parameter",
                             "confirmation_required")
    _require_current_disposable_project(req, operation)
    if req.get("runtimeValidation") is not True:
        raise OperationError(
            "runtimeValidation=true is required for a PID parameter write",
            "runtime_validation_required",
            {"correctFormat": {"runtimeValidation": True,
             "disposable": True, "confirm": "write_pid_parameter"}},
        )
    if req.get("value") is None:
        raise OperationError("value is required", "invalid_argument")
    field = _text(req.get("field") or req.get("controlField") or "")
    if not field:
        raise OperationError("field is required", "invalid_argument")
    try:
        requested_channel = _pid_parse_channel(req.get("channel"))
    except OperationError:
        requested_channel = None
    # Keep the public mutation surface narrow while allowing the exact same
    # proven binding on every 4LC channel.  The module identity and the upper
    # channel bound are checked again below from the live page; this early
    # guard only rejects malformed/unsupported requests before any editor
    # resolution can occur.
    if requested_channel is None or requested_channel < 0 or field != "_deadBandLntb":
        raise OperationError(
            "public PID write is limited to the verified 41053 _deadBandLntb binding on channels 0..3",
            "pid_scope_not_promoted",
            {"channel": req.get("channel"), "field": field,
             "expected": {"moduleType": 41053, "channelRange": [0, 3],
                          "field": "_deadBandLntb"},
             "mutatedProject": False},
        )
    context = _pid_page_context(req, require_parent=False)
    contract = context["contract"]
    try:
        resolved_type = int((context["identity"].get("deviceId") or {}).get("type"))
    except Exception:
        resolved_type = None
    if resolved_type != 41053:
        raise OperationError(
            "public PID write is limited to the verified GL20-4LC-PID 41053 identity",
            "pid_scope_not_promoted",
            {"resolvedIdentity": context["identity"], "expectedModuleType": 41053,
             "mutatedProject": False},
        )
    if field not in contract["fields"]:
        raise OperationError(
            "PID field is not in the statically verified control contract",
            "pid_field_unsupported",
            {"target": context["target"], "field": field,
             "allowedFields": list(contract["fields"]), "mutatedProject": False},
        )
    write_binding = contract["writeBindings"].get(field)
    if write_binding is None:
        raise OperationError(
            "PID field has no exact native write/readback binding",
            "pid_field_runtime_binding_unavailable",
            {"target": context["target"], "field": field,
             "runtimeWriteFields": sorted(contract["writeBindings"]),
             "mutatedProject": False},
        )
    channel_context = _pid_channel_context(context, req)
    runtime_state = _pid_channel_runtime_state(channel_context)
    is_editing = (runtime_state.get("isEditing") or {}).get("value")
    module_editor_ready = (runtime_state.get("moduleEditor") or {}).get("nonNull")
    cpu_module = (runtime_state.get("cpuModule") or {}).get("value")
    if is_editing is not False or not module_editor_ready or cpu_module is not True:
        raise OperationError(
            "PID channel control is not initialized for local CPU event writes",
            "pid_runtime_binding_unverified",
            {"channel": channel_context["channel"],
             "channelRuntimeState": runtime_state, "mutatedProject": False},
        )
    flags = channel_context["flags"]
    control, parts, owner = _resolve_vendor_page_control(
        channel_context["control"], field, flags)
    if control is None:
        raise OperationError("PID control was not found on the live page",
                             "pid_control_not_found",
                             {"target": context["target"], "field": field,
                              "controlPath": parts, "mutatedProject": False})
    before = _pid_control_snapshot(control, field)
    observed_kind = ("numeric" if "value" in before else
                     "checkbox" if "checked" in before else
                     "text" if "text" in before else
                     "selection" if "selectedIndex" in before else None)
    requested_kind = _text(req.get("controlKind") or "")
    if requested_kind and requested_kind != observed_kind:
        raise OperationError("control kind does not match PID page control",
                             "editor_control_kind_mismatch",
                             {"field": field, "expected": requested_kind,
                              "observed": observed_kind, "before": before,
                              "mutatedProject": False})
    if observed_kind not in ("numeric", "text"):
        raise OperationError(
            "the exact PID runtime binding requires a numeric text control",
            "editor_control_kind_mismatch",
            {"field": field, "observed": observed_kind, "before": before,
             "mutatedProject": False},
        )
    try:
        requested_value = float(_text(req.get("value")))
    except Exception:
        raise OperationError("PID value must be numeric", "editor_value_invalid",
                             {"field": field, "requested": req.get("value"),
                              "mutatedProject": False})
    import math
    import System
    if math.isnan(requested_value) or math.isinf(requested_value):
        raise OperationError("PID value must be finite", "editor_value_invalid",
                             {"field": field, "requested": req.get("value"),
                              "mutatedProject": False})
    minimum = before.get("minVal")
    maximum = before.get("maxVal")
    if minimum is not None and requested_value < float(_text(minimum)):
        raise OperationError("PID value is below the vendor control minimum",
                             "editor_value_out_of_range",
                             {"field": field, "minimum": minimum,
                              "requested": requested_value, "mutatedProject": False})
    if maximum is not None and requested_value > float(_text(maximum)):
        raise OperationError("PID value exceeds the vendor control maximum",
                             "editor_value_out_of_range",
                             {"field": field, "maximum": maximum,
                              "requested": requested_value, "mutatedProject": False})
    scaled = int(round(requested_value * 10.0))
    if abs((scaled / 10.0) - requested_value) > 0.000001:
        raise OperationError("PID value exceeds the control's 0.1 resolution",
                             "editor_value_resolution_invalid",
                             {"field": field, "resolution": 0.1,
                              "requested": requested_value, "mutatedProject": False})
    if scaled < 0 or scaled > 65535:
        raise OperationError("PID encoded value is outside uint16 range",
                             "editor_value_out_of_range",
                             {"field": field, "scaled": scaled,
                              "mutatedProject": False})
    native_before = _pid_native_snapshot(
        context, write_binding, channel_context["channel"], False)
    if native_before.get("namedChildrenPartial"):
        raise OperationError(
            "PID native named layout is partial; no write was attempted",
            "pid_native_layout_unverified",
            {"field": field, "channel": channel_context["channel"],
             "nativeBefore": native_before,
             "connectorResolution": native_before.get(
                 "connectorResolution"),
             "mutatedProject": False},
        )
    unnamed_layout = bool(native_before.get("namedChildrenAbsent"))
    position_bytes_before = None
    position_byte_reads = {}
    if unnamed_layout:
        # A fresh project may expose the vendor struct only as an unnamed
        # byte array.  Capture the immutable baseline *before* invoking the
        # control setter; reading the array twice after the setter cannot
        # prove that this operation changed anything.
        position_byte_reads["before"] = {}
        position_bytes_before = _pid_cfg_bytes(
            context, False, position_byte_reads["before"])
        if (position_bytes_before is None or
                len(position_bytes_before) < 2):
            raise OperationError(
                "PID native byte baseline is unavailable for the unnamed layout",
                "pid_native_layout_unverified",
                {"field": field, "channel": channel_context["channel"],
                 "nativeBefore": native_before,
                 "positionByteRead": position_byte_reads["before"],
                 "mutatedProject": False},
            )
    if native_before.get("decodedValue") == requested_value:
        raise OperationError(
            "requested PID value equals the current native value; choose a different validation value",
            "pid_validation_value_unchanged",
            {"field": field, "channel": channel_context["channel"],
             "nativeBefore": native_before, "mutatedProject": False},
        )
    canonical = System.Single(requested_value).ToString()
    parent_editor = _pid_parent_editor(context)
    receipt = {
        "operation": operation, "target": context["target"], "field": field,
        "channel": channel_context["channel"],
        "resolvedIdentity": context["identity"], "binding": context["binding"],
        "connectorResolution": native_before.get("connectorResolution"),
        "pageType": context["pageType"],
        "channelControlType": channel_context["controlType"],
        "before": {"control": before, "native": native_before},
        "input": {"field": field, "channel": channel_context["channel"],
                  "value": requested_value, "canonicalText": canonical,
                  "controlKind": observed_kind},
        "after": None,
        "validation": {"identity": True, "field": True, "controlKind": observed_kind,
                        "parentEditorType": contract["parentEditorType"],
                        "parentEditorObserved": True,
                        "nativeLayout": native_before.get("layout"),
                        "channelRuntimeState": runtime_state,
                        "setterCalled": False, "eventCommitObserved": False,
                        "saveCommitObserved": False,
                        "parentSaveCalled": False,
                        "runtimeWriteVerified": False},
        "mutatedProject": False,
        "committed": False,
        "projectSaveCalled": False,
        # A native setter can dirty the resident IDE even if a later save or
        # readback fails.  Keep this explicit so callers discard the process
        # instead of retrying on stale vendor handles.
        "processDiscardRequired": False,
    }
    if unnamed_layout:
        # Keep the diagnostics object live in the receipt even if a later
        # native read/save raises; the exception path then exposes the exact
        # byte-read stage that was reached.
        receipt["validation"]["positionByteReads"] = position_byte_reads
    try:
        position_diff_event = None
        position_diff_save = None
        position_bytes_event = None
        position_bytes_save = None
        control.Value = System.Single(requested_value)
        receipt["validation"]["setterCalled"] = True
        receipt["mutatedProject"] = True
        after_event = _pid_native_snapshot(
            context, write_binding, channel_context["channel"], False)
        if unnamed_layout:
            # Position-indexed fresh-project layout: locate the changed
            # uint16 region by byte diff instead of named children.
            position_byte_reads["event"] = {}
            position_bytes_event = _pid_cfg_bytes(
                context, False, position_byte_reads["event"])
            position_diff_event = _pid_decode_bytes_diff(
                position_bytes_before, position_bytes_event, requested_value)
            receipt["validation"]["positionByteReads"] = position_byte_reads
            receipt["validation"]["positionDiffEvent"] = position_diff_event
            receipt["validation"]["eventCommitObserved"] = (
                position_diff_event is not None)
        else:
            receipt["validation"]["eventCommitObserved"] = (
                after_event.get("decodedValue") == requested_value)
        committed_object = context["frame"].GetDeviceObject(True)
        parent_return = parent_editor.Save(True)
        receipt["validation"]["parentSaveCalled"] = True
        after_parent = _pid_native_snapshot(
            context, write_binding, channel_context["channel"], False)
        if unnamed_layout:
            position_byte_reads["afterSave"] = {}
            position_bytes_save = _pid_cfg_bytes(
                context, False, position_byte_reads["afterSave"])
            position_diff_save = _pid_decode_bytes_diff(
                position_bytes_before, position_bytes_save, requested_value)
            receipt["validation"]["positionByteReads"] = position_byte_reads
            receipt["validation"]["positionDiffAfterSave"] = position_diff_save
            receipt["validation"]["saveCommitObserved"] = (
                position_diff_save is not None)
        channel_context["control"].Reload()
        after_reload = _pid_control_snapshot(control, field)
        receipt["after"] = {
            "event": after_event, "parentSave": after_parent,
            "controlAfterReload": after_reload,
            "deviceCommitRuntimeType": (
                _text(committed_object.GetType().FullName)
                if committed_object is not None else None),
            "parentSaveReturn": _json_safe(parent_return),
        }
    except Exception as exc:
        if isinstance(exc, OperationError):
            exc.data.setdefault("receipt", receipt)
            exc.data.setdefault("mutatedProject", receipt["mutatedProject"])
            if receipt["mutatedProject"]:
                receipt["processDiscardRequired"] = True
                exc.data["processDiscardRequired"] = True
            raise
        receipt["error"] = repr(exc)
        receipt["processDiscardRequired"] = bool(receipt["mutatedProject"])
        raise OperationError("PID vendor event write failed: " + repr(exc),
                             "pid_event_write_failed", receipt)
    final_native = receipt["after"]["parentSave"]
    control_after = receipt["after"]["controlAfterReload"]
    control_text_matches = (
        _text(control_after.get("text")) == _text(canonical) and
        _text(control_after.get("validValue")) == _text(canonical))
    receipt["validation"]["controlTextMatched"] = control_text_matches
    if unnamed_layout:
        final_native_check = position_diff_save is not None
    else:
        final_native_check = (
            final_native.get("decodedValue") == requested_value)
    # Some vendor builds defer serialization until the parent Save.  For the
    # unnamed layout either an event-time diff or a save-time diff is useful,
    # but the final save-time diff remains mandatory for persistence proof.
    exact = ((receipt["validation"]["eventCommitObserved"] or
              receipt["validation"].get("saveCommitObserved", False)) and
             final_native_check and
             control_text_matches)
    if not exact:
        receipt["processDiscardRequired"] = bool(receipt["mutatedProject"])
        raise OperationError(
            "PID native parameter or reloaded control did not retain the requested value",
            "pid_native_parameter_not_retained", receipt)
    receipt["validation"]["runtimeWriteVerified"] = True
    receipt["committed"] = True
    receipt["status"] = "pid_parameter_written_runtime_verified"
    receipt["next"] = (
        "call project.save, close the IDE, reopen in a fresh process, read the same native fields and control, then compile")
    return receipt


def vendor_editor_save(req):
    """Save an already-open vendor editor view, with explicit confirmation."""
    _require_project()
    if req.get("confirm") != "save_vendor_editor":
        raise OperationError("confirm must exactly equal save_vendor_editor",
                             "confirmation_required")
    _require_current_disposable_project(req, "vendor.editor.save")
    target = req.get("target") or req.get("name") or ""
    view, frame, before = _open_vendor_editor_match(req)
    selected_tab = None
    wanted_editor_type = _text(req.get("baseEditorType") or "").strip()
    wanted_page_type = _text(req.get("pageType") or "").strip()
    if wanted_editor_type and wanted_page_type:
        raise OperationError("baseEditorType and pageType are mutually exclusive",
                             "invalid_argument",
                             {"paths": ["baseEditorType", "pageType"]})
    if wanted_page_type:
        base_editors = list(_get_member(
            frame, "BaseDeviceEditors", "get_BaseDeviceEditors") or [])
        page_matches = []
        page_inventory = []
        for base_editor in base_editors:
            pages = list(_get_member(base_editor, "Pages", "get_Pages") or [])
            for candidate in pages:
                runtime_type = _text(candidate.GetType().FullName)
                page_name = _text(_get_member(
                    candidate, "PageName", "get_PageName") or "")
                page_inventory.append({"runtimeType": runtime_type,
                                       "pageName": page_name})
                if (runtime_type == wanted_page_type or
                        runtime_type.endswith("." + wanted_page_type) or
                        runtime_type.endswith(wanted_page_type)):
                    page_matches.append((candidate, runtime_type, page_name))
        if len(page_matches) != 1:
            raise OperationError(
                "expected exactly one matching vendor editor page",
                "editor_page_ambiguous",
                {"pageType": wanted_page_type,
                 "matchCount": len(page_matches), "pages": page_inventory,
                 "mutatedProject": False},
            )
        page, runtime_type, page_name = page_matches[0]
        if not page_name:
            raise OperationError("matching vendor page has no page name",
                                 "editor_tab_page_name_unavailable",
                                 {"pageType": wanted_page_type,
                                  "runtimeType": runtime_type,
                                  "mutatedProject": False})
        try:
            select_return = frame.SelectEditorTab(page_name)
        except Exception as exc:
            raise OperationError(
                "vendor editor page selection failed: " + repr(exc),
                "editor_tab_selection_failed",
                {"pageType": wanted_page_type, "runtimeType": runtime_type,
                 "pageName": page_name, "mutatedProject": False},
            )
        active_page = None
        try:
            active_page = frame.GetActiveEditorPage()
        except Exception:
            pass
        selected_tab = {
            "requestedPageType": wanted_page_type,
            "runtimeType": runtime_type,
            "pageName": page_name,
            "selectReturn": _json_safe(select_return),
            "activePageRuntimeType": (
                _text(active_page.GetType().FullName)
                if active_page is not None else None),
        }
    elif wanted_editor_type:
        base_editors = list(_get_member(
            frame, "BaseDeviceEditors", "get_BaseDeviceEditors") or [])
        matches = []
        inventory = []
        for base_editor in base_editors:
            runtime_type = _text(base_editor.GetType().FullName)
            inventory.append(runtime_type)
            if (runtime_type == wanted_editor_type or
                    runtime_type.endswith("." + wanted_editor_type) or
                    runtime_type.endswith(wanted_editor_type)):
                matches.append(base_editor)
        if len(matches) != 1:
            raise OperationError(
                "expected exactly one matching vendor base editor",
                "editor_tab_ambiguous",
                {"baseEditorType": wanted_editor_type,
                 "matchCount": len(matches), "baseEditors": inventory,
                 "mutatedProject": False},
            )
        page_name = _text(_get_member(
            matches[0], "PageName", "get_PageName") or "").strip()
        if not page_name:
            try:
                import System
                page_flags = (System.Reflection.BindingFlags.Instance |
                              System.Reflection.BindingFlags.NonPublic |
                              System.Reflection.BindingFlags.Public |
                              System.Reflection.BindingFlags.FlattenHierarchy)
                page_getter = matches[0].GetType().GetMethod(
                    "get_PageName", page_flags)
                if page_getter is not None:
                    page_name = _text(page_getter.Invoke(
                        matches[0], System.Array[System.Object]([]))).strip()
            except Exception:
                page_name = ""
        if not page_name:
            raise OperationError(
                "matching vendor base editor has no page name",
                "editor_tab_page_name_unavailable",
                {"baseEditorType": wanted_editor_type,
                 "runtimeType": _text(matches[0].GetType().FullName),
                 "mutatedProject": False},
            )
        try:
            select_return = frame.SelectEditorTab(page_name)
        except Exception as exc:
            raise OperationError(
                "vendor editor tab selection failed: " + repr(exc),
                "editor_tab_selection_failed",
                {"baseEditorType": wanted_editor_type,
                 "runtimeType": _text(matches[0].GetType().FullName),
                 "pageName": page_name,
                 "mutatedProject": False},
            )
        active_page = None
        try:
            active_page = frame.GetActiveEditorPage()
        except Exception:
            pass
        selected_tab = {
            "requested": wanted_editor_type,
            "runtimeType": _text(matches[0].GetType().FullName),
            "pageName": page_name,
            "selectReturn": _json_safe(select_return),
            "activePageRuntimeType": (
                _text(active_page.GetType().FullName)
                if active_page is not None else None),
        }
    editor = _get_member(view, "Editor", "get_Editor")
    if editor is None:
        raise OperationError("open view has no Editor property",
                             "editor_unavailable", before)
    save = getattr(editor, "Save", None)
    if save is None:
        raise OperationError("editor has no Save(bool) method",
                             "editor_save_unavailable", before)
    try:
        returned = save(True)
    except Exception as exc:
        raise OperationError("vendor editor Save(true) failed: " + repr(exc),
                             "editor_save_failed", before)
    parameter_readback = []
    requested_parameters = req.get("readParameters") or []
    if requested_parameters and not isinstance(requested_parameters, list):
        raise OperationError("readParameters must be an array", "invalid_argument",
                             {"path": "readParameters"})
    if requested_parameters:
        for requested in requested_parameters:
            row = {"request": _json_safe(requested)}
            try:
                if not isinstance(requested, dict):
                    raise OperationError("readParameters entries must be objects",
                                         "invalid_argument")
                parameter_id = int(requested.get("parameterId"))
                connector_index = int(requested.get(
                    "connectorIndex", requested.get("connectorId", 0)))
                element_path = requested.get("elementPath") or []
                read_target = requested.get("target") or target
                _mgr, _meta, native, binding = _native_device_object(
                    read_target, "read")
                element = _native_parameter_from_device(
                    native, parameter_id, connector_index)
                element, parts = _native_element_at_path(element, element_path)
                row.update({
                    "ok": True,
                    "target": read_target,
                    "binding": binding,
                    "connectorIndex": connector_index,
                    "parameterId": parameter_id,
                    "elementPath": parts,
                    "element": _native_element_snapshot(element, 0, 2),
                    "ioMapping": _native_io_mapping_snapshot(element),
                })
            except Exception as exc:
                row.update({"ok": False, "error": repr(exc)})
            parameter_readback.append(row)
    return {
        "target": target,
        "before": before,
        "selectedTab": selected_tab,
        "saveReturn": _json_safe(returned),
        "parameterReadback": parameter_readback,
        "mutatedProject": True,
        "committed": True,
        "status": "editor_saved",
        "note": "工程仍需另行调用 project.save 并通过关闭/重开门禁",
    }


def vendor_device_parameter_write(req):
    """Write one native IDataElement.Value and commit it through ObjectMgr."""
    target = req.get("target") or req.get("path") or req.get("device")
    parameter_id = req.get("parameterId")
    # elementPath may be EMPTY: measured 2026-09-19 on the SoftMotion axis, most
    # engineer-facing parameters (gear ratio 1051/1052, limits 1113/1200/1201,
    # movement type 1060, homing options 7100+) are scalar LEAVES whose own
    # value is the parameter value, and vendor.device.parameter.read reports
    # elementPath=[] for them. Requiring a non-empty path made every one of
    # those parameters unwritable. The key must still be PRESENT so a typo can
    # never silently retarget the write to the parameter root.
    if "elementPath" in req:
        element_path = req.get("elementPath")
    elif "field" in req:
        element_path = req.get("field")
    else:
        raise OperationError(
            "elementPath is required: pass [] to write the parameter element "
            "itself (that is what vendor.device.parameter.read reports for a "
            "scalar parameter), or the child names for a structured one",
            "invalid_argument",
            {"path": "elementPath",
             "example": {"elementPath": ["SlaveAddr"]},
             "scalarExample": {"elementPath": []}})
    if element_path is None:
        element_path = []
    if not target or parameter_id is None:
        raise OperationError("target and parameterId are required", "invalid_argument")
    if req.get("confirm") != "write_vendor_parameter":
        raise OperationError("write requires confirm=write_vendor_parameter", "confirmation_required")
    _require_current_disposable_project(req, "vendor.device.parameter.write")
    try:
        parameter_id = int(parameter_id)
    except Exception:
        raise OperationError("parameterId must be an integer", "invalid_argument")
    # Measured defect 2026-09-19: this writer ignored connectorId and always
    # used connector 1, so a parameter that lives on the device's SECOND
    # connector (the Modbus slave's Internal connector, id 2) answered
    # parameter_not_found even though vendor.device.parameter.read found it.
    connector_id = req.get("connectorId")
    if connector_id is None:
        connector_id = 1
    try:
        connector_id = int(connector_id)
    except Exception:
        raise OperationError("connectorId must be an integer", "invalid_argument",
                             {"path": "connectorId", "actual": req.get("connectorId")})
    object_mgr, meta, native, binding = _native_device_object_with_retry(target, "modify")
    element = _native_parameter_from_device(native, parameter_id, connector_id)
    element, parts = _native_element_at_path(element, element_path)
    before = _native_element_value(element)
    if req.get("value") is None:
        raise OperationError("value is required", "invalid_argument")
    try:
        element.Value = _text(req.get("value"))
    except Exception:
        element.value = _text(req.get("value"))
    after = _native_element_value(element)
    committed = False
    commit_return = None
    error = None
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
        # SP11's SetObject is effectively void and returns None on success.
        committed = True
    except Exception as exc:
        error = repr(exc)
    stages = [{
        "stage": "before",
        "value": before,
        "snapshot": _native_element_snapshot(element, 0, 1),
    }, {
        "stage": "after_set",
        "value": after,
        "exactRequestedValue": after == _text(req.get("value")),
        "snapshot": _native_element_snapshot(element, 0, 1),
    }]
    if committed:
        try:
            _read_mgr, _read_meta, read_native, read_binding = _native_device_object(target, "read")
            read_element = _native_parameter_from_device(read_native, parameter_id,
                                                         connector_id)
            read_element, _read_parts = _native_element_at_path(read_element, parts)
            stages.append({
                "stage": "after_object_manager_commit",
                "value": _native_element_value(read_element),
                "snapshot": _native_element_snapshot(read_element, 0, 1),
                "rebound": True,
                "binding": read_binding,
            })
        except Exception as exc:
            stages.append({
                "stage": "after_object_manager_commit",
                "readbackError": repr(exc),
                "rebound": False,
            })
    result = {"binding": binding, "target": target, "parameterId": parameter_id, "connectorId": connector_id, "elementPath": parts, "before": before, "after": after, "stages": stages, "committed": committed, "commitReturn": _json_safe(commit_return), "mutatedProject": True, "status": "committed" if committed else "commit_failed"}
    if error:
        result["commitError"] = error
    return result


def device_set_parameter(req):
    """Generic contract adapter over the verified vendor IDataElement path.

    It intentionally remains fail-closed until the caller runs the separate
    save/reopen gate; the response retains the vendor binding evidence.
    """
    if _text(req.get("confirm")).strip() != "set_device_parameter":
        raise OperationError("device.set_parameter requires confirm=set_device_parameter",
                             "confirmation_required")
    adapted = dict(req)
    adapted["confirm"] = "write_vendor_parameter"
    result = vendor_device_parameter_write(adapted)
    result["operation"] = "device.set_parameter"
    result["status"] = "committed_same_process_requires_restart_gate"
    result["claims"] = {"vendorSetter": True, "objectManagerCommit": bool(result.get("committed")),
                         "sameProcessReadback": bool(result.get("stages")),
                         "saveReopenPersistence": False}
    return result


def project_core_probe(req):
    """Read ScriptEngine project wrappers to locate the vendor Core IProject."""
    _require_project()
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)

    def describe(value):
        if value is None:
            return None
        result = {"runtimeType": _text(value.GetType().FullName), "properties": [], "fields": []}
        try:
            for prop in value.GetType().GetProperties(flags):
                entry = {"name": _text(prop.Name), "type": _text(prop.PropertyType.FullName),
                         "declaringType": _text(prop.DeclaringType.FullName)}
                if any(token in entry["name"].lower() for token in
                       ("project", "core", "object", "target", "inner", "meta", "extend")):
                    try:
                        child = prop.GetValue(value, None)
                        entry["valueRuntimeType"] = _text(child.GetType().FullName) if child is not None else None
                    except Exception as exc:
                        entry["readError"] = repr(exc)
                    result["properties"].append(entry)
            for field in value.GetType().GetFields(flags):
                entry = {"name": _text(field.Name), "type": _text(field.FieldType.FullName),
                         "declaringType": _text(field.DeclaringType.FullName)}
                if any(token in entry["name"].lower() for token in
                       ("project", "core", "object", "target", "inner", "meta", "extend")):
                    try:
                        child = field.GetValue(value)
                        entry["valueRuntimeType"] = _text(child.GetType().FullName) if child is not None else None
                    except Exception as exc:
                        entry["readError"] = repr(exc)
                    result["fields"].append(entry)
        except Exception as exc:
            result["reflectionError"] = repr(exc)
        return result

    extender = _get_member(project, "Extender", "get_Extender")
    return {
        "project": describe(project),
        "extender": describe(extender),
        "mutatedProject": False,
        "status": "observed",
    }


def project_core_binding_probe(req):
    """Locate the concrete Core IProject behind the ScriptEngine wrapper.

    InoProShop exposes ``projects.primary`` to IronPython as an extended
    ScriptEngine object.  Its reflected CLR type advertises ``CoreProject``,
    but calling a property getter on that Python wrapper can fail with
    ``TargetException``.  This read-only probe tests the actual interface and
    reflection routes independently so a later archive commit uses only a
    binding observed in this exact IDE build.
    """
    _require_project()
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)

    def type_name(value):
        try:
            return _text(value.GetType().AssemblyQualifiedName)
        except Exception:
            return None

    def value_summary(value):
        if value is None:
            return {"present": False}
        summary = {
            "present": True,
            "runtimeType": _text(value.GetType().FullName),
            "assemblyQualifiedType": type_name(value),
        }
        try:
            summary["interfaces"] = sorted(set(
                _text(item.AssemblyQualifiedName)
                for item in value.GetType().GetInterfaces()))[:200]
        except Exception as exc:
            summary["interfacesError"] = repr(exc)
        return summary

    def record(label, callback):
        try:
            value = callback()
            entry = value_summary(value)
            entry["ok"] = True
            return entry, value
        except Exception as exc:
            return {"ok": False, "error": repr(exc)}, None

    result = {
        "readOnly": True,
        "mutatedProject": False,
        "project": value_summary(project),
        "attempts": [],
        "status": "observed",
    }
    engine = None
    core_projects = None
    primary = None
    entry, engine = record(
        "system_instances_engine",
        lambda: _system_instances_property("Engine")[0])
    entry["binding"] = "SystemInstances.Engine"
    result["attempts"].append(entry)
    if engine is not None:
        entry, core_projects = record(
            "core_engine_projects",
            lambda: _get_member(engine, "Projects", "get_Projects"))
        entry["binding"] = "SystemInstances.Engine.Projects"
        result["attempts"].append(entry)
    if core_projects is not None:
        entry, primary = record(
            "core_primary_project",
            lambda: _get_member(core_projects, "PrimaryProject", "get_PrimaryProject"))
        entry["binding"] = "SystemInstances.Engine.Projects.PrimaryProject"
        result["attempts"].append(entry)
    if primary is not None:
        entry, primary_handle = record(
            "core_primary_handle",
            lambda: _get_member(primary, "Handle", "get_Handle"))
        entry["binding"] = "Core PrimaryProject.Handle"
        entry["value"] = _json_safe(primary_handle)
        result["attempts"].append(entry)
        entry, primary_path = record(
            "core_primary_path",
            lambda: _get_member(primary, "Path", "get_Path"))
        entry["binding"] = "Core PrimaryProject.Path"
        entry["value"] = _text(primary_path)
        result["attempts"].append(entry)
        result["corePrimaryProject"] = value_summary(primary)
        result["coreProject"] = value_summary(primary)
        result["coreProjectBindingAvailable"] = True
    if native_core_project is not None:
        result["wizardCoreProject"] = value_summary(native_core_project)
        result["wizardCoreProjectBinding"] = "retained from IInovanceProjectWizard.Execute"
        result["coreProject"] = value_summary(native_core_project)
        result["coreProjectBindingAvailable"] = True
    project_type = project.GetType()
    result["projectClrType"] = {
        "fullName": _text(project_type.FullName),
        "assemblyQualifiedName": _text(project_type.AssemblyQualifiedName),
        "assembly": _text(project_type.Assembly.FullName),
        "baseType": _text(project_type.BaseType.AssemblyQualifiedName)
                    if project_type.BaseType is not None else None,
    }

    # First try direct IronPython member dispatch.  This is distinct from
    # PropertyInfo.GetValue and may be the only valid route for a proxy.
    entry, candidate = record("python_get_CoreProject", lambda: project.CoreProject)
    entry["binding"] = "project.CoreProject"
    result["attempts"].append(entry)
    if candidate is not None:
        result["coreProject"] = value_summary(candidate)

    entry, candidate = record("python_get_project", lambda: project.project)
    entry["binding"] = "project.project"
    result["attempts"].append(entry)
    if candidate is not None:
        result["projectWrapper"] = value_summary(candidate)

    # Record every matching concrete property including assembly identity.
    for prop_name in ("CoreProject", "project", "Extender", "ProjectStructure"):
        properties = [item for item in project_type.GetProperties(flags)
                      if _text(item.Name) == prop_name]
        if not properties:
            result["attempts"].append({
                "label": "concrete_property_" + prop_name,
                "binding": "not_found", "ok": False,
            })
            continue
        for index, prop in enumerate(properties):
            entry, candidate = record(
                "concrete_property_%s_%d" % (prop_name, index),
                lambda prop=prop: prop.GetValue(project, None))
            entry["binding"] = _text(prop.ToString())
            entry["declaringAssembly"] = _text(prop.DeclaringType.Assembly.FullName)
            result["attempts"].append(entry)
            if prop_name == "CoreProject" and candidate is not None:
                result["coreProject"] = value_summary(candidate)

    # The ScriptEngine public contract exposes the real wrapper through
    # IBaseObject<T>. Invoke that interface's getter directly, then inspect
    # the returned object without assuming it is the Core project yet.
    base_interfaces = []
    for interface in project_type.GetInterfaces():
        if _text(interface.FullName).startswith("_3S.CoDeSys.ScriptEngine.IBaseObject`1"):
            base_interfaces.append(interface)
    for index, interface in enumerate(base_interfaces):
        entry, candidate = record(
            "ibase_get_Extender_%d" % index,
            lambda interface=interface: interface.GetMethod("get_Extender").Invoke(
                project, System.Array[System.Object]([])))
        entry["binding"] = _text(interface.AssemblyQualifiedName) + ".get_Extender()"
        result["attempts"].append(entry)
        if candidate is not None:
            result["ibaseExtender"] = value_summary(candidate)
            for prop_name in ("CoreProject", "project"):
                prop = candidate.GetType().GetProperty(prop_name, flags)
                if prop is not None:
                    nested, core_candidate = record(
                        "ibase_extender_%s_%d" % (prop_name, index),
                        lambda prop=prop, candidate=candidate: prop.GetValue(candidate, None))
                    nested["binding"] = "IBaseObject.Extender." + _text(prop.ToString())
                    result["attempts"].append(nested)
                    if prop_name == "CoreProject" and core_candidate is not None:
                        result["coreProject"] = value_summary(core_candidate)

    # IScriptTreeObject.get_project() returns the project extended object for
    # a tree object. It is another independent route to compare with primary.
    for index, interface in enumerate(project_type.GetInterfaces()):
        if _text(interface.FullName) != "_3S.CoDeSys.ScriptEngine.BasicFunctionality.IScriptTreeObject":
            continue
        entry, candidate = record(
            "tree_get_project_%d" % index,
            lambda interface=interface: interface.GetMethod("get_project").Invoke(
                project, System.Array[System.Object]([])))
        entry["binding"] = _text(interface.AssemblyQualifiedName) + ".get_project()"
        result["attempts"].append(entry)
        if candidate is not None:
            result["treeProject"] = value_summary(candidate)

    core = result.get("coreProject")
    result["coreProjectBindingAvailable"] = bool(
        result.get("coreProjectBindingAvailable") or (core and core.get("present"))
    )
    result["nextRequired"] = (
        "use only a successful CoreProject binding to call "
        "UpdateConfigurationDataObject on a disposable project"
        if result["coreProjectBindingAvailable"] else
        "inspect the failed binding routes; no archive commit was attempted"
    )
    return result


def _vendor_assembly_filters(value=None):
    """Normalize vendor assembly filters without touching the live process."""
    if normalize_vendor_assembly_filters is not None:
        return normalize_vendor_assembly_filters(value)
    if value:
        return [_text(item).strip().lower() for item in _text(value).split(",")
                if _text(item).strip()][:20]
    return ["inovance", "inodeviceeditor", "inoaxis", "inoonline",
            "inoproject", "inocompile", "inoobject", "inosoftmotion",
            # Standard object plug-in families (not vendor-prefixed): the
            # alarm/trace/symbol object assemblies live here and were
            # invisible to the default filter (round-19 evidence: Alarm and
            # Trace searches returned identical vendor lists without a single
            # target type).
            "alarmconfiguration", "inotrace", "symbolconfig"]


def vendor_api_search(req):
    """Read-only inventory of loaded vendor types and likely commit methods."""
    import System
    terms = req.get("terms") or [
        "configuration", "storage", "archive", "sync", "save", "add",
        "mapping", "hardware", "io", "module",
    ]
    terms = [
        _text(item).strip().lower() for item in terms
        if _text(item).strip()
    ][:30]
    # InoProShop's vendor assemblies are not consistently named.  Some use
    # the company prefix (``Inovance``), while the actual editor plug-ins use
    # ``InoDeviceEditor...`` or ``InoAxis...``.  The old single default
    # silently returned zero results because none of the loaded assembly
    # names contained ``Inovance``.  Treat a comma-separated value as an OR
    # filter and cover the known vendor naming families by default.
    assembly_filters = _vendor_assembly_filters(req.get("assembly"))
    max_types = max(1, min(int(req.get("maxTypes", 300)), 2000))
    max_methods = max(1, min(int(req.get("maxMethods", 80)), 300))
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.DeclaredOnly)
    assemblies = []
    candidates = []
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        try:
            full_name = _text(assembly.FullName)
            if assembly_filters and not any(
                item in full_name.lower() for item in assembly_filters
            ):
                continue
            assemblies.append(full_name)
            for typ in assembly.GetTypes():
                type_name = _text(typ.FullName)
                lowered_type = type_name.lower()
                if not any(term in lowered_type for term in terms):
                    continue
                method_entries = []
                property_entries = []
                field_entries = []
                try:
                    for method in typ.GetMethods(flags):
                        text_value = _text(method.ToString())
                        lowered = text_value.lower()
                        if any(term in lowered for term in terms):
                            method_entries.append(text_value)
                    for prop in typ.GetProperties(flags):
                        text_value = _text(prop.ToString())
                        lowered = text_value.lower()
                        if any(term in lowered for term in terms):
                            property_entries.append(text_value)
                    for field in typ.GetFields(flags):
                        text_value = _text(field.ToString())
                        lowered = text_value.lower()
                        if any(term in lowered for term in terms):
                            field_entries.append(text_value)
                except Exception as exc:
                    method_entries.append("<reflection-error> " + repr(exc))
                if method_entries or property_entries or field_entries:
                    candidates.append({
                        "assembly": full_name,
                        "type": type_name,
                        "baseType": _text(typ.BaseType.FullName)
                                   if typ.BaseType is not None else None,
                        "methods": sorted(set(method_entries))[:max_methods],
                        "properties": sorted(set(property_entries))[:max_methods],
                        "fields": sorted(set(field_entries))[:max_methods],
                    })
                    if len(candidates) >= max_types:
                        break
            if len(candidates) >= max_types:
                break
        except Exception:
            continue
    candidates.sort(key=lambda item: (item["type"].lower(), item["assembly"].lower()))
    return {
        "readOnly": True,
        "mutatedProject": False,
        "assemblyFilter": assembly_filters,
        "terms": terms,
        "assemblies": sorted(set(assemblies)),
        "count": len(candidates),
        "types": candidates,
        "status": "observed" if candidates else "unavailable",
        "nextRequired": "select a concrete vendor editor commit method and validate it on a disposable project",
    }


def vendor_api_binding_probe(req):
    """Resolve a decompiled vendor contract against loaded CLR metadata.

    This is deliberately stronger than ``vendor.api.search`` but remains
    read-only: it never invokes a method and never creates a project object.
    A resolved ``System.Type`` is evidence that the current host loaded the
    contract, not evidence that the method is safe to call or that it mutates
    a project correctly.
    """
    import System

    type_selector = _text(req.get("type") or req.get("typeName")).strip()
    method_selector = _text(req.get("method") or req.get("methodName")).strip()
    if not type_selector:
        raise OperationError(
            "vendor.api.binding.probe requires type or typeName",
            "invalid_argument",
        )
    assembly_filters = _vendor_assembly_filters(
        req.get("assembly") or req.get("assemblyFilter")
    )
    max_methods = max(1, min(int(req.get("maxMethods", 100)), 500))
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic |
             System.Reflection.BindingFlags.DeclaredOnly)

    def type_name(value):
        return _text(value.FullName or value.Name)

    def type_ref(value):
        if value is None:
            return None
        try:
            name = type_name(value)
            if value.IsByRef:
                element = value.GetElementType()
                name = (_text(element.FullName or element.Name)
                        if element is not None else name) + "&"
            elif value.IsArray:
                element = value.GetElementType()
                name = (_text(element.FullName or element.Name)
                        if element is not None else name) + "[]"
            return name
        except Exception:
            return _text(value)

    def method_shape(method):
        parameters = []
        for parameter in method.GetParameters():
            parameter_type = parameter.ParameterType
            parameters.append({
                "name": _text(parameter.Name),
                "type": type_ref(parameter_type),
                "position": int(parameter.Position),
                "isOut": bool(parameter.IsOut),
                "isOptional": bool(parameter.IsOptional),
                "hasDefault": bool(parameter.HasDefaultValue),
            })
        try:
            declaring = type_name(method.DeclaringType)
        except Exception:
            declaring = None
        return {
            "name": _text(method.Name),
            "declaringType": declaring,
            "returnType": type_ref(method.ReturnType),
            "parameters": parameters,
            "parameterCount": len(parameters),
            "isStatic": bool(method.IsStatic),
            "isPublic": bool(method.IsPublic),
            "isPrivate": bool(method.IsPrivate),
            "isFamily": bool(method.IsFamily),
            "isAssembly": bool(method.IsAssembly),
            "isVirtual": bool(method.IsVirtual),
            "signature": _text(method.ToString()),
        }

    assemblies = []
    type_matches = []
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        try:
            full_name = _text(assembly.FullName)
            if assembly_filters and not any(
                    item in full_name.lower() for item in assembly_filters):
                continue
            assemblies.append(full_name)
            for typ in assembly.GetTypes():
                full_type = type_name(typ)
                lowered = full_type.lower()
                selector = type_selector.lower()
                if lowered != selector and not lowered.endswith("." + selector):
                    continue
                type_matches.append({
                    "assembly": full_name,
                    "assemblySimpleName": _text(assembly.GetName().Name),
                    "type": full_type,
                    "isInterface": bool(typ.IsInterface),
                    "isAbstract": bool(typ.IsAbstract),
                    "baseType": type_ref(typ.BaseType),
                    "interfaces": sorted(set(
                        type_name(item) for item in typ.GetInterfaces()
                    )),
                    "typeObject": typ,
                })
        except Exception:
            continue

    if not type_matches:
        return {
            "status": "unavailable",
            "readOnly": True,
            "mutatedProject": False,
            "assemblyFilter": assembly_filters,
            "assembliesScanned": len(assemblies),
            "typeSelector": type_selector,
            "methodSelector": method_selector or None,
            "typeMatches": [],
            "methods": [],
            "claims": {
                "runtimeTypeResolved": False,
                "runtimeMethodResolved": False,
                "methodInvoked": False,
                "projectMutationVerified": False,
            },
        }

    # Keep the CLR object private to this response; _json_safe would only
    # stringify it, and exposing it makes the result misleading as a binding.
    methods = []
    for match in type_matches:
        typ = match.pop("typeObject")
        try:
            for method in typ.GetMethods(flags):
                if method_selector and _text(method.Name).lower() != method_selector.lower():
                    continue
                methods.append(dict(match, **method_shape(method)))
        except Exception as exc:
            methods.append(dict(match, reflectionError=repr(exc)))
    methods = methods[:max_methods]
    if method_selector and not methods:
        status = "method_unavailable"
    elif len(type_matches) > 1:
        status = "ambiguous_type"
    else:
        status = "method_found" if method_selector else "type_found"
    return {
        "status": status,
        "readOnly": True,
        "mutatedProject": False,
        "assemblyFilter": assembly_filters,
        "assembliesScanned": len(assemblies),
        "typeSelector": type_selector,
        "methodSelector": method_selector or None,
        "typeMatches": [dict((key, value) for key, value in item.items())
                        for item in type_matches],
        "methods": methods,
        "claims": {
            "runtimeTypeResolved": True,
            "runtimeMethodResolved": bool(methods) if method_selector else None,
            "methodInvoked": False,
            "projectMutationVerified": False,
        },
        "nextRequired": (
            "bind a concrete object and perform a read-only instance probe"
            if methods else
            "verify the exact assembly/type name for this InoProShop version"
        ),
    }


def vendor_api_binding_batch_probe(req):
    """Run multiple read-only contract probes in one bridge request."""
    contracts = req.get("contracts")
    if not isinstance(contracts, (list, tuple)) or not contracts:
        raise OperationError(
            "vendor.api.binding.batch_probe requires a non-empty contracts array",
            "invalid_argument",
        )
    limit = max(1, min(int(req.get("limit", 200)), 500))
    results = []
    for index, item in enumerate(contracts[:limit]):
        if not isinstance(item, dict):
            results.append({
                "index": index,
                "status": "invalid_contract",
                "errorCode": "invalid_argument",
            })
            continue
        try:
            result = vendor_api_binding_probe(item)
            result["index"] = index
            results.append(result)
        except OperationError as exc:
            results.append({
                "index": index,
                "status": "error",
                "errorCode": exc.code,
                "error": _text(exc),
                "data": exc.data,
            })
        except Exception as exc:
            results.append({
                "index": index,
                "status": "error",
                "errorCode": "handler_error",
                "error": repr(exc),
            })
    counts = {}
    for item in results:
        status = _text(item.get("status") or "unknown")
        counts[status] = counts.get(status, 0) + 1
    return {
        "readOnly": True,
        "mutatedProject": False,
        "count": len(results),
        "requestedCount": len(contracts),
        "truncated": len(contracts) > limit,
        "statusCounts": counts,
        "results": results,
        "claims": {
            "methodInvoked": False,
            "projectMutationVerified": False,
        },
    }


def vendor_object_factory_list(req):
    """Enumerate the live standard object factories without invoking them.

    GVL/DUT creation is provided by the loaded ObjectManager plug-ins, not by
    the Inovance project wizard APEnvironment.  This probe records the exact
    factories and type GUIDs exposed by the current profile so a subsequent
    writer can bind the right factory instead of guessing a plug-in folder
    GUID.  It is intentionally read-only.
    """
    import System

    _require_project()
    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("SystemInstances type is unavailable",
                             "system_instances_unavailable")
    object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
    if object_mgr is None:
        raise OperationError("ObjectMgr is unavailable", "object_manager_unavailable")
    manager = _get_member(object_mgr, "ObjectFactoryManager",
                          "get_ObjectFactoryManager")
    if manager is None:
        raise OperationError("ObjectFactoryManager is unavailable",
                             "object_factory_manager_unavailable",
                             {"runtimeType": _text(object_mgr.GetType().FullName)})
    selector = _text(req.get("filter") or req.get("contains") or
                     req.get("factoryContains") or "").strip().lower()
    factories = _get_member(manager, "Factories", "get_Factories", [])
    try:
        factories = list(factories)
    except Exception:
        factories = []

    def type_name(value):
        try:
            return _text(value.FullName or value.Name)
        except Exception:
            return _text(value)

    def type_guid(value):
        try:
            attrs = value.GetType().GetCustomAttributes(True)
            for attr in attrs:
                guid = _get_member(attr, "Guid", "guid")
                if guid is not None:
                    text = _text(guid)
                    if re.match(r"^[0-9a-fA-F-]{36}$", text):
                        return text
        except Exception:
            pass
        return None

    entries = []
    for factory in factories:
        runtime_type = type_name(factory.GetType())
        lowered_runtime_type = runtime_type.lower()
        if selector:
            if selector not in lowered_runtime_type:
                continue
        elif not any(token in lowered_runtime_type for token in
                     ("gvlfactory", "gvlobjectfactory", "dutobjectfactory")):
            continue
        try:
            object_type = _get_member(factory, "ObjectType", "get_ObjectType")
            # Do not reflect every method here. Some InoProShop plug-ins
            # expose lazy proxy methods whose CLR metadata call blocks the
            # primary UI thread. The separate binding probe handles exact
            # method signatures once a factory is selected.
            methods = ["Create"]
            entries.append({
                "runtimeType": runtime_type,
                "factoryTypeGuid": type_guid(factory),
                "objectType": type_name(object_type) if object_type is not None else None,
                "name": _text(_get_member(factory, "Name", "get_Name", "")),
                "description": _text(_get_member(factory, "Description", "get_Description", "")),
                "objectBaseName": _text(_get_member(factory, "ObjectBaseName", "get_ObjectBaseName", "")),
                "methods": methods,
            })
        except Exception as exc:
            entries.append({"runtimeType": _text(factory), "reflectionError": repr(exc)})

    object_interface = "_3S.CoDeSys.Core.Objects.IObject"
    return {
        "readOnly": True,
        "mutatedProject": False,
        "managerRuntimeType": type_name(manager.GetType()),
        "factoryCount": len(entries),
        "filter": selector or "gvl/dut factory defaults",
        "factories": entries,
        "languageObjectCandidates": entries,
        "objectInterface": object_interface,
        "claims": {
            "liveFactoryInventory": True,
            "factoryMethodsInvoked": False,
            "projectMutationVerified": False,
        },
        "nextRequired": "select exact GVL/DUT factory, instantiate one disposable object, AddObject, UI-tree/readback/compile gate",
    }


