def alarm_class_create(req):
    """Create an Alarm Class under the Alarm Configuration.

    Blocked live: the AlarmClassObjectFactory.Create() throws a target
    invocation exception unless the alarm storage (DatabaseFileAlarmStorage)
    exists, and the storage factory's AddObject route itself fails on this
    profile (2026-09-01 live A/B). Surface the constraint honestly instead
    of a raw factory failure.
    """
    try:
        return _factory_object_create(
            "alarm.class.create", req, ALARM_CLASS_FACTORY_GUID,
            "AlarmClass", "Application/Alarm Configuration",
            "AlarmClassObject", "create_alarm_class", "alarm_class")
    except OperationError as exc:
        if exc.code == "object_factory_create_failed":
            raise OperationError(
                "alarm class creation is blocked on this profile: the class "
                "factory Create() requires the alarm storage object, whose "
                "own AddObject route is not yet supported",
                "alarm_class_creation_blocked",
                {"constraint": "DatabaseFileAlarmStorage required",
                 "verifiedWorking": ["alarm.config.create",
                                     "alarm.group.create",
                                     "trace.create"],
                 "cause": exc.data.get("cause"),
                 "mutatedProject": False})
        raise


def trace_create(req):
    """Create the native Trace object under Application."""
    # The trace factory's ObjectCreated hook rejects the empty batch on this
    # profile; registration happens through ObjectMgr.AddObject already, so
    # default to skipping the optional hook (round-20 live evidence).
    req = dict(req)
    req.setdefault("postCreate", False)
    return _factory_object_create(
        "trace.create", req, TRACE_FACTORY_GUID,
        "Trace", "Application",
        "Inovance.InoPro.InoTraceObject.TraceObject", "create_trace_object",
        "trace_object")


def vendor_language_object_create(req):
    """Create a GVL or DUT through the loaded ObjectManager factory.

    ScriptEngine ``create_gvl``/``create_dut`` writes the core model but does
    not necessarily register a vendor structured-view node.  The standard
    ObjectManager factories are the same route used by the native Add Object
    command: factory Create -> ObjectMgr.AddObject.  Source text is written
    only after registration, then read back through the textual object API.
    """
    import System

    _require_project()
    if req.get("disposable") is not True:
        raise OperationError("vendor language object creation requires disposable=true",
                             "disposable_required")
    if _text(req.get("confirm")).strip() != "vendor_language_object_create":
        raise OperationError("confirm must equal vendor_language_object_create",
                             "confirmation_required")
    kind = _text(req.get("kind") or req.get("objectKind") or "gvl").strip().lower()
    if kind in ("global_variable_list", "global_variables", "globalvarlist"):
        kind = "gvl"
    if kind in ("data_unit", "data_type", "datatype"):
        kind = "dut"
    if kind not in ("gvl", "dut"):
        raise OperationError("kind must be gvl or dut", "invalid_argument",
                             {"path": "kind", "expected": ["gvl", "dut"],
                              "actual": kind})
    name = _text(req.get("name")).strip()
    declaration = req.get("declaration")
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
        raise OperationError("vendor language object requires an IEC name",
                             "invalid_argument", {"path": "name", "actual": name})
    if declaration is None:
        raise OperationError("vendor language object requires declaration",
                             "invalid_argument", {"path": "declaration"})
    declaration = _validate_source_text(declaration, "declaration")

    app = getattr(project, "active_application", None)
    if app is None:
        raise OperationError("no active application", "no_active_application")
    app_guid = _text(_get_member(app, "guid", "get_guid"))
    if not app_guid:
        raise OperationError("application guid is unavailable", "binding_failed")

    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("SystemInstances type is unavailable",
                             "system_instances_unavailable")
    object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
    manager = _get_member(object_mgr, "ObjectFactoryManager",
                          "get_ObjectFactoryManager")
    if manager is None:
        raise OperationError("ObjectFactoryManager is unavailable",
                             "object_factory_manager_unavailable")
    factory_guid = GVL_OBJECT_FACTORY_GUID if kind == "gvl" else DUT_OBJECT_FACTORY_GUID
    try:
        factory = manager.GetFactory(System.Guid(factory_guid))
    except Exception as exc:
        raise OperationError("language object factory lookup failed",
                             "object_factory_lookup_failed", {"guid": factory_guid,
                                                               "cause": repr(exc)})
    if factory is None:
        raise OperationError("language object factory is not loaded",
                             "object_factory_unavailable", {"kind": kind,
                                                              "guid": factory_guid})

    trace = [{"step": "factory", "kind": kind, "guid": factory_guid,
              "runtimeType": _text(factory.GetType().FullName)}]
    try:
        value = factory.Create()
    except Exception as exc:
        raise OperationError("language object factory Create failed",
                             "object_factory_create_failed", {"kind": kind,
                                                                "cause": repr(exc)})
    if value is None:
        raise OperationError("language object factory returned no object",
                             "object_factory_create_empty", {"kind": kind})
    trace.append({"step": "Create", "runtimeType": _text(value.GetType().FullName)})

    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            handle = None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable", "project_handle_unavailable")
    add_method = None
    for method in object_mgr.GetType().GetMethods():
        if _text(method.Name) != "AddObject" or len(method.GetParameters()) != 6:
            continue
        add_method = method
        break
    if add_method is None:
        raise OperationError("vendor AddObject binding is unavailable",
                             "vendor_addobject_unavailable")
    new_guid = System.Guid.NewGuid()
    added = add_method.Invoke(object_mgr, System.Array[System.Object]([
        int(handle), System.Guid(app_guid), new_guid, value, name, -1,
    ]))
    trace.append({"step": "AddObject", "requestedGuid": _text(new_guid),
                  "returnedGuid": _text(added)})
    pou_cache.clear()
    textual = find_textual_object(name)
    if textual is None:
        raise OperationError("vendor language object not found after AddObject",
                             "vendor_language_object_not_found", {"kind": kind,
                                                                    "trace": trace})
    text_result = _write_document(
        _get_member(textual, "textual_declaration", "get_textual_declaration"),
        declaration, "declaration")
    created_path = None
    try:
        _created_obj, created_path = find_project_object(name)
    except Exception:
        pass
    return {
        "name": name,
        "kind": kind,
        "createdGuid": _text(added),
        "parent": "Application",
        "treePath": created_path,
        "creationRoute": "vendor_object_factory_add_object",
        "factoryGuid": factory_guid,
        "trace": trace,
        "text": text_result,
        "readback": read_st(textual),
        "object": _object_summary(textual),
        "uiVisibilityGate": "required: screenshot the tree in this session",
    }


def _select_object_factory_post_create_method(methods, batch_arguments_supplied):
    """Select only the documented ObjectCreated callbacks this writer can bind.

    An explicitly supplied string-array batch is meaningful only to the exact
    three-argument overload. Do not infer or fabricate a third argument for
    any other overload.
    """
    two_argument = None
    three_argument_string_array = None
    for method in methods:
        if _text(method.Name) != "ObjectCreated":
            continue
        parameters = method.GetParameters()
        if (len(parameters) == 2 and
                _text(parameters[0].ParameterType.FullName) == "System.Int32" and
                _text(parameters[1].ParameterType.FullName) == "System.Guid"):
            two_argument = method
        if (len(parameters) == 3 and
                _text(parameters[0].ParameterType.FullName) == "System.Int32" and
                _text(parameters[1].ParameterType.FullName) == "System.Guid" and
                bool(parameters[2].ParameterType.IsArray) and
                _text(parameters[2].ParameterType.GetElementType().FullName) ==
                "System.String"):
            three_argument_string_array = method
    if batch_arguments_supplied and three_argument_string_array is not None:
        return three_argument_string_array, "three_argument_string_array"
    if two_argument is not None:
        return two_argument, "two_argument"
    return None, None


def vendor_object_factory_create(req):
    """Create one project object through an explicitly selected native factory.

    This is the common creation route for non-textual CODESYS objects such as
    Trace, Visualization, Recipe, and Alarm Configuration. It deliberately
    does not infer a factory from a display name and does not configure any
    object-specific fields. A caller must first use ``vendor.object.factory.list``
    to obtain the exact live factory GUID, then validate the created object
    through tree visibility, save/reopen, and compilation before a specialized
    writer can be promoted.
    """
    import System

    _require_project()
    if req.get("disposable") is not True:
        raise OperationError("vendor object factory creation requires disposable=true",
                             "disposable_required")
    if _text(req.get("confirm")).strip() != "vendor_object_factory_create":
        raise OperationError("confirm must equal vendor_object_factory_create",
                             "confirmation_required")
    factory_guid = _text(req.get("factoryGuid") or req.get("factory")).strip()
    name = _text(req.get("name")).strip()
    parent_selector = _text(req.get("parent") or "Application").strip()
    batch_arguments_supplied = "batchArguments" in req
    batch_arguments = req.get("batchArguments")
    post_create_requested = req.get("postCreate") is True
    if not factory_guid:
        raise OperationError("factoryGuid is required", "invalid_argument",
                             {"path": "factoryGuid"})
    if not name or "/" in name or "\\" in name:
        raise OperationError("name must be one object name without a path",
                             "invalid_argument", {"path": "name", "actual": name})
    if batch_arguments_supplied:
        if not isinstance(batch_arguments, (list, tuple)):
            raise OperationError("batchArguments must be an array of strings",
                                 "invalid_argument", {"path": "batchArguments"})
        if any(not isinstance(item, basestring) for item in batch_arguments):
            raise OperationError("batchArguments must contain only strings",
                                 "invalid_argument", {"path": "batchArguments"})
    try:
        System.Guid(factory_guid)
    except Exception:
        raise OperationError("factoryGuid must be a GUID", "invalid_argument",
                             {"path": "factoryGuid", "actual": factory_guid})
    try:
        _existing, existing_path = find_project_object(name)
        raise OperationError("object name already exists: " + name,
                             "object_already_exists",
                             {"name": name, "existingPath": existing_path})
    except OperationError as exc:
        if exc.code != "object_not_found":
            raise

    parent, parent_path = find_project_object(parent_selector)
    parent_guid = _text(_get_member(parent, "guid", "get_guid"))
    if not parent_guid:
        raise OperationError("parent object GUID is unavailable",
                             "parent_guid_unavailable",
                             {"parent": parent_selector, "parentPath": parent_path})
    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("SystemInstances type is unavailable",
                             "system_instances_unavailable")
    object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
    manager = _get_member(object_mgr, "ObjectFactoryManager",
                          "get_ObjectFactoryManager")
    if manager is None:
        raise OperationError("ObjectFactoryManager is unavailable",
                             "object_factory_manager_unavailable")
    try:
        factory = manager.GetFactory(System.Guid(factory_guid))
    except Exception as exc:
        raise OperationError("object factory lookup failed",
                             "object_factory_lookup_failed",
                             {"factoryGuid": factory_guid, "cause": repr(exc)})
    if factory is None:
        raise OperationError("object factory is not loaded", "object_factory_unavailable",
                             {"factoryGuid": factory_guid})
    post_create_method = None
    post_create_mode = None
    if post_create_requested:
        post_create_method, post_create_mode = _select_object_factory_post_create_method(
            factory.GetType().GetMethods(), batch_arguments_supplied)
        if post_create_method is None:
            raise OperationError("factory has no ObjectCreated(Int32, Guid) binding",
                                 "object_factory_post_create_binding_unavailable",
                                 {"factoryGuid": factory_guid,
                                  "factoryRuntimeType": _text(factory.GetType().FullName),
                                  "mutatedProject": False})
    create_method = None
    for method in factory.GetType().GetMethods():
        if _text(method.Name) != "Create":
            continue
        parameters = method.GetParameters()
        if not batch_arguments_supplied and len(parameters) == 0:
            create_method = method
            break
        if batch_arguments_supplied and len(parameters) == 1:
            parameter_type = parameters[0].ParameterType
            if bool(parameter_type.IsArray) and _text(
                    parameter_type.GetElementType().FullName) == "System.String":
                create_method = method
                break
    if create_method is None:
        raise OperationError("factory has no matching Create binding",
                             "object_factory_create_binding_unavailable",
                             {"factoryGuid": factory_guid,
                              "batchArgumentsSupplied": batch_arguments_supplied,
                              "factoryRuntimeType": _text(factory.GetType().FullName)})
    try:
        batch_argument_array = (System.Array[System.String](list(batch_arguments))
                                if batch_arguments_supplied else None)
        invoke_args = [] if batch_argument_array is None else [batch_argument_array]
        value = create_method.Invoke(factory, System.Array[System.Object](invoke_args))
    except Exception as exc:
        exception_chain = []
        current = exc
        for _index in range(8):
            if current is None:
                break
            entry = {"type": _text(current.GetType().FullName)
                     if hasattr(current, "GetType") else _text(type(current)),
                     "message": _text(current)}
            inner = getattr(current, "InnerException", None)
            if inner is not None:
                entry["innerType"] = _text(inner.GetType().FullName)
                entry["innerMessage"] = _text(inner)
            exception_chain.append(entry)
            current = inner
        raise OperationError("native factory Create failed", "object_factory_create_failed",
                              {"factoryGuid": factory_guid,
                              "factoryRuntimeType": _text(factory.GetType().FullName),
                              "batchArgumentsSupplied": batch_arguments_supplied,
                              "cause": repr(exc), "exceptionChain": exception_chain})
    if value is None:
        raise OperationError("native factory returned no object", "object_factory_create_empty",
                             {"factoryGuid": factory_guid})
    handle = None
    if native_core_project is not None:
        try:
            handle = int(native_core_project.Handle)
        except Exception:
            handle = None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
        if handle is None:
            handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable", "project_handle_unavailable")
    # ProjectStructure.AddNode calls StructuredView.AddObject directly. That
    # route emits NodeAddedAndFolderSet but skips the ObjectMgr-added event.
    # The visible InoProShop tree immediately rendered vendor POU objects only
    # on the same ObjectMgr.AddObject route used by the native project wizard.
    # Use that event-producing route for factory objects as well.
    add_method = None
    for method in object_mgr.GetType().GetMethods():
        if _text(method.Name) == "AddObject" and len(method.GetParameters()) == 6:
            add_method = method
            break
    if add_method is None:
        raise OperationError("vendor AddObject binding is unavailable",
                             "vendor_addobject_unavailable",
                             {"factoryGuid": factory_guid,
                              "parentPath": parent_path,
                              "projectHandle": int(handle)})
    new_guid = System.Guid.NewGuid()
    try:
        added = add_method.Invoke(object_mgr, System.Array[System.Object]([
            int(handle), System.Guid(parent_guid), new_guid, value, name, -1,
        ]))
    except Exception as exc:
        raise OperationError("vendor ObjectMgr.AddObject failed",
                             "vendor_addobject_failed",
                             {"factoryGuid": factory_guid, "name": name,
                              "parentPath": parent_path, "cause": repr(exc)})
    post_create = {"requested": post_create_requested, "invoked": False}
    if post_create_requested:
        try:
            post_create_args = [int(handle), System.Guid(_text(added or new_guid))]
            if post_create_mode == "three_argument_string_array":
                post_create_args.append(batch_argument_array)
            post_create_method.Invoke(factory, System.Array[System.Object](post_create_args))
            post_create.update({
                "invoked": True,
                "method": _text(post_create_method.ToString()),
                "bindingMode": post_create_mode,
                "batchArgumentsForwarded": post_create_mode == "three_argument_string_array",
            })
        except Exception as exc:
            raise OperationError("native factory ObjectCreated failed",
                                 "object_factory_post_create_failed",
                                 {"factoryGuid": factory_guid, "name": name,
                                  "createdGuid": _text(added),
                                  "parentPath": parent_path, "cause": repr(exc),
                                  "recovery": ["project.tree", "screenshot",
                                               "object.delete with exact confirmation"]})
    # Names are not unique in the vendor tree: a factory object can expose a
    # native wrapper and a structured-view entry with the same display name.
    # The AddObject return value is the authoritative identity, so resolve the
    # result by GUID before falling back to the old name/path lookup.  Name
    # lookup here used to turn a successful Group creation into a false
    # vendor_object_not_visible error when two same-name entries existed.
    created_guid = _text(added or new_guid)
    guid_matches = []
    flat_after_add = []
    _walk_objects(project, [], 1, 64, flat_after_add)
    for candidate_path, candidate in flat_after_add:
        if _object_guid(candidate).lower() == created_guid.lower():
            guid_matches.append((candidate_path, candidate))
    if len(guid_matches) == 1:
        created_path, created = guid_matches[0]
    else:
        try:
            created, created_path = find_project_object(parent_path + "/" + name)
        except OperationError as exc:
            raise OperationError("created object is absent from the project tree",
                                 "vendor_object_not_visible",
                                 {"factoryGuid": factory_guid, "name": name,
                                  "parentPath": parent_path, "createdGuid": created_guid,
                                  "guidMatches": [item[0] for item in guid_matches],
                                  "cause": _text(exc)})
    return {
        "name": name,
        "parent": parent_path,
        "treePath": created_path,
        "factoryGuid": factory_guid,
        "factoryRuntimeType": _text(factory.GetType().FullName),
        "objectRuntimeType": _text(value.GetType().FullName),
        "batchArguments": list(batch_arguments) if batch_arguments_supplied else None,
        "postCreate": post_create,
        "createdGuid": created_guid,
        "creationRoute": "vendor_object_mgr_add_object",
        "modelVisibility": {"present": True, "path": created_path},
        "uiVisibility": {
            "status": "not_verified",
            "requiredEvidence": "same-session screenshot with the parent expanded",
        },
        "object": _object_summary(created, created_path),
        "nextRequired": [
            "read object-specific parameters through a verified native binding",
            "save, close, fresh-process reopen, and verify the tree path",
            "compile and inspect precompile/compiler/library diagnostics",
        ],
    }


def vendor_visual_probe(req):
    """Read the native VisualObject model without guessing its setters."""
    _require_project()
    import System
    target = _text(req.get("target") or req.get("path")).strip()
    if not target:
        raise OperationError("vendor.visual.probe requires target", "invalid_argument",
                             {"path": "target"})
    script_object, object_path = find_project_object(target)
    requested_guid = _object_guid(script_object)
    if not requested_guid:
        raise OperationError("visual object has no GUID", "visual_guid_unavailable",
                             {"target": target, "path": object_path})
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    try:
        meta = object_mgr.GetObjectToRead(handle, System.Guid(requested_guid))
    except Exception as exc:
        raise OperationError("native VisualObject lookup failed", "visual_object_lookup_failed",
                             {"target": object_path, "guid": requested_guid,
                              "projectHandle": handle, "cause": repr(exc)})
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    if native is None:
        raise OperationError("native VisualObject is unavailable", "visual_object_unavailable",
                             {"target": object_path, "guid": requested_guid,
                              "projectHandle": handle})
    clr_type = native.GetType()
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    property_names = sorted(set(_text(prop.Name) for prop in clr_type.GetProperties(flags)))
    method_names = sorted(set(_text(method.Name) for method in clr_type.GetMethods(flags)))
    selected = {}
    for name in ("VisualElemList", "Interface", "Properties", "Source", "LanguageModel"):
        value = _get_member(native, name, "get_" + name)
        if value is None:
            selected[name] = {"present": False}
            continue
        entry = {"present": True, "runtimeType": _text(value.GetType().FullName)}
        try:
            count = _get_member(value, "Count", "get_Count")
            if count is not None:
                entry["count"] = int(count)
        except Exception as exc:
            entry["countError"] = repr(exc)
        try:
            entry["text"] = _text(value)[:300]
        except Exception:
            pass
        selected[name] = entry
    return {
        "target": target,
        "path": object_path,
        "guid": requested_guid,
        "projectHandle": handle,
        "objectRuntimeType": _text(clr_type.FullName),
        "properties": property_names,
        "methods": method_names,
        "selected": selected,
        "managerProbe": manager_probe,
        "readOnly": True,
        "mutatedProject": False,
        "status": "observed",
    }


def visual_element_probe(req):
    """Read the native visualization element model without mutation.

    This deliberately stops at ObjectMgr.GetObjectToRead.  It does not call
    VisualObjectManager creators, member setters, editor commands, or save.
    The returned member values are bounded snapshots so callers can decide
    which concrete binding deserves a later disposable-project write test.
    """
    _require_project()
    import System

    target = _text(req.get("target") or req.get("path")).strip()
    if not target:
        raise OperationError("visual.element.probe requires target", "invalid_argument",
                             {"path": "target"})
    try:
        max_elements = max(1, min(int(req.get("maxElements", 128)), 512))
    except Exception:
        raise OperationError("maxElements must be an integer", "invalid_argument",
                             {"path": "maxElements"})
    try:
        max_depth = max(0, min(int(req.get("maxDepth", 5)), 12))
    except Exception:
        raise OperationError("maxDepth must be an integer", "invalid_argument",
                             {"path": "maxDepth"})
    try:
        max_members = max(1, min(int(req.get("maxMembers", 256)), 1000))
    except Exception:
        raise OperationError("maxMembers must be an integer", "invalid_argument",
                             {"path": "maxMembers"})

    script_object, object_path = find_project_object(target)
    requested_guid = _object_guid(script_object)
    if not requested_guid:
        raise OperationError("visual object has no GUID", "visual_guid_unavailable",
                             {"target": target, "path": object_path})
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    try:
        meta = object_mgr.GetObjectToRead(handle, System.Guid(requested_guid))
    except Exception as exc:
        raise OperationError("native VisualObject lookup failed",
                             "visual_object_lookup_failed",
                             {"target": object_path, "guid": requested_guid,
                              "projectHandle": handle, "cause": repr(exc)})
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    if native is None:
        raise OperationError("native VisualObject is unavailable",
                             "visual_object_unavailable",
                             {"target": object_path, "guid": requested_guid,
                              "projectHandle": handle})

    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public)
    scalar_types = set(("System.String", "System.Boolean", "System.Byte",
                        "System.SByte", "System.Int16", "System.UInt16",
                        "System.Int32", "System.UInt32", "System.Int64",
                        "System.UInt64", "System.Single", "System.Double",
                        "System.Decimal", "System.Guid"))
    value_tokens = ("variable", "expression", "address", "reference",
                    "input", "value", "text", "name", "path", "type",
                    "id", "identifier", "member")
    variable_tokens = ("variable", "expression", "address", "reference",
                       "binding", "input")

    def scalar(value):
        if value is None:
            return None
        if isinstance(value, bool) or isinstance(value, _INTEGER_TYPES):
            return value
        if isinstance(value, float):
            return value
        text = _text(value)
        if text == "":
            return ""
        return text[:512]

    def public_values(value, tokens=value_tokens, limit=80):
        if value is None:
            return {}
        result = {}
        try:
            typ = value.GetType()
            for prop in typ.GetProperties(flags):
                name = _text(prop.Name)
                try:
                    if prop.GetIndexParameters().Length:
                        continue
                except Exception:
                    pass
                lowered = name.lower()
                property_type = _text(prop.PropertyType.FullName)
                if not any(token in lowered for token in tokens) and property_type not in scalar_types:
                    continue
                try:
                    prop_value = prop.GetValue(value, None)
                    if prop_value is None:
                        continue
                    if property_type in scalar_types or isinstance(prop_value, _STRING_TYPES):
                        result[name] = scalar(prop_value)
                except Exception as exc:
                    result[name] = {"readError": repr(exc)}
                if len(result) >= limit:
                    break
        except Exception as exc:
            result["__reflectionError"] = repr(exc)
        return result

    def sequence(value, method_names, limit):
        if value is None:
            return [], {"present": False}
        info = {"present": True, "runtimeType": _text(value.GetType().FullName)}
        count = None
        for name in ("Count", "Length"):
            candidate = _get_member(value, name, "get_" + name)
            if candidate is not None:
                try:
                    count = int(candidate)
                    break
                except Exception:
                    pass
        if count is not None:
            info["count"] = count
        items = []
        upper = min(count, limit) if count is not None else limit
        for index in range(upper):
            item = None
            for method_name in method_names:
                try:
                    method = getattr(value, method_name)
                    item = method(index)
                    break
                except Exception:
                    pass
            if item is None:
                try:
                    item = value[index]
                except Exception:
                    item = None
            if item is not None:
                items.append((index, item))
        if not items and count is None:
            try:
                for index, item in enumerate(value):
                    if index >= limit:
                        break
                    items.append((index, item))
            except Exception as exc:
                info["enumerationError"] = repr(exc)
        info["returned"] = len(items)
        info["truncated"] = count is not None and count > limit
        return items, info

    def member_snapshot(member, path, depth, seen):
        snapshot = {
            "path": path,
            "runtimeType": _text(member.GetType().FullName),
            "values": public_values(member),
        }
        values = snapshot["values"]
        refs = []
        for name, value in values.items():
            if name == "__reflectionError" or isinstance(value, dict):
                continue
            text_value = _text(value).strip()
            if not text_value:
                continue
            lowered = name.lower()
            if any(token in lowered for token in variable_tokens):
                refs.append({"property": name, "value": text_value})
        snapshot["variableReferences"] = refs
        if depth >= max_depth:
            return snapshot
        key = id(member)
        if key in seen:
            snapshot["cycle"] = True
            return snapshot
        seen.add(key)
        child_collection = None
        child_name = None
        for candidate in ("Children", "NestedMembers", "Members"):
            child_collection = _get_member(member, candidate, "get_" + candidate)
            if child_collection is not None:
                child_name = candidate
                break
        if child_collection is not None:
            children, child_info = sequence(child_collection,
                                             ("GetVisualElemMember", "GetMember"),
                                             max_members)
            snapshot["childrenInfo"] = dict(child_info, property=child_name)
            snapshot["children"] = [member_snapshot(item, path + "/" + str(index),
                                                      depth + 1, seen)
                                     for index, item in children]
        return snapshot

    def type_tree_summary(element):
        tree = _get_member(element, "DescriptionTree", "get_DescriptionTree")
        if tree is None:
            return {"present": False}
        nodes = _get_member(tree, "TypeNodes", "get_TypeNodes")
        node_items, node_info = sequence(nodes, ("GetTypeNode",), max_members)
        return {
            "present": True,
            "runtimeType": _text(tree.GetType().FullName),
            "nodes": [{"index": index,
                       "runtimeType": _text(item.GetType().FullName),
                       "values": public_values(item, ("name", "id", "type", "input", "variable", "address", "attribute"), 40)}
                      for index, item in node_items],
            "nodeInfo": node_info,
        }

    def element_snapshot(element, path, depth, seen):
        result = {
            "path": path,
            "runtimeType": _text(element.GetType().FullName),
            "values": public_values(element, ("name", "type", "id", "position", "frame", "element"), 60),
            "variableReferences": [],
        }
        for name, value in result["values"].items():
            if isinstance(value, dict) or not _text(value).strip():
                continue
            if any(token in name.lower() for token in variable_tokens):
                result["variableReferences"].append({"property": name, "value": _text(value)})
        result["descriptionTree"] = type_tree_summary(element)
        if depth >= max_depth:
            result["truncatedAtDepth"] = True
            return result
        key = id(element)
        if key in seen:
            result["cycle"] = True
            return result
        seen.add(key)
        member_list = _get_member(element, "MemberList", "get_MemberList")
        members, member_info = sequence(member_list, ("GetVisualElemMember", "GetMember"), max_members)
        result["memberInfo"] = member_info
        result["bindableMembers"] = [member_snapshot(item, path + "/member[" + str(index) + "]",
                                                        depth + 1, seen)
                                      for index, item in members]
        nested = _get_member(element, "NestedElements", "get_NestedElements")
        nested_items, nested_info = sequence(nested, ("GetVisualElem",), max_elements)
        result["nestedInfo"] = nested_info
        result["nestedElements"] = [element_snapshot(item, path + "/nested[" + str(index) + "]",
                                                        depth + 1, seen)
                                     for index, item in nested_items]
        return result

    visual_list = None
    list_property = None
    for candidate in ("VisualElemList", "VisualElements", "Elements"):
        visual_list = _get_member(native, candidate, "get_" + candidate)
        if visual_list is not None:
            list_property = candidate
            break
    if visual_list is None:
        raise OperationError("native VisualObject has no readable element list",
                             "visual_element_list_unavailable",
                             {"target": object_path, "guid": requested_guid,
                              "runtimeType": _text(native.GetType().FullName),
                              "properties": [_text(item.Name) for item in native.GetType().GetProperties(flags)]})
    elements, list_info = sequence(visual_list, ("GetVisualElem", "GetElement"), max_elements)
    manager_info = {"available": False}
    for type_name in ("_3S.CoDeSys.VisualEditor.VisualObjectManager, VisualEditor.plugin",
                      "_3S.CoDeSys.VisualEditor.VisualObjectManager, VisualObject.plugin"):
        manager_type = _reflection_type(type_name)
        if manager_type is None:
            continue
        manager_info = {"available": True, "type": _text(manager_type.FullName),
                        "methods": sorted(set(_text(item.Name) for item in manager_type.GetMethods(flags)))[:200]}
        try:
            singleton = manager_type.GetProperty("Singleton")
            manager = singleton.GetValue(None, None) if singleton is not None else None
            if manager is not None:
                available = _get_member(manager, "AllAvailableElements", "get_AllAvailableElements")
                available_items, available_info = sequence(available, ("GetElement",), 256)
                manager_info["availableElements"] = [public_values(item, ("name", "type", "id", "identification"), 40)
                                                       for _index, item in available_items]
                manager_info["availableElementsInfo"] = available_info
        except Exception as exc:
            manager_info["readError"] = repr(exc)
        break
    ap_info = {"available": False}
    ap_type = _reflection_type(INOVANCE_AP_ENVIRONMENT_TYPE)
    if ap_type is not None:
        ap_info = {"available": True, "type": _text(ap_type.FullName),
                   "visualFactoryMethods": sorted(set(
                       _text(item.Name) for item in ap_type.GetMethods(
                           System.Reflection.BindingFlags.Static |
                           System.Reflection.BindingFlags.Public |
                           System.Reflection.BindingFlags.NonPublic)
                       if any(token in _text(item.Name).lower()
                              for token in ("visual", "visu"))))[:100]}
    return {
        "target": target,
        "path": object_path,
        "guid": requested_guid,
        "projectHandle": handle,
        "objectRuntimeType": _text(native.GetType().FullName),
        "elementListProperty": list_property,
        "elementList": list_info,
        "elements": [element_snapshot(item, "element[" + str(index) + "]", 0, set())
                     for index, item in elements],
        "visualObjectManager": manager_info,
        "apEnvironment": ap_info,
        "objectManager": manager_probe,
        "limits": {"maxElements": max_elements, "maxDepth": max_depth,
                    "maxMembers": max_members},
        "readOnly": True,
        "mutatedProject": False,
        "status": "observed",
    }


def visual_element_create(req):
    """Create one native visualization element and commit its owner object."""
    _require_project()
    _require_current_disposable_project(req, "visual.element.create")
    if _text(req.get("confirm")).strip() != "create_visual_element":
        raise OperationError(
            "confirm must equal create_visual_element",
            "confirmation_required",
            {"correctFormat": {"confirm": "create_visual_element",
                               "disposable": True}},
        )
    target = _text(req.get("target") or req.get("path")).strip()
    element_type = _text(req.get("elementType") or req.get("type")).strip()
    instance_name = _text(req.get("instanceName") or req.get("name")).strip()
    allowed_types = {
        "VisuFbCheckbox": {
            "variable": "m_pVariable..pVariable",
            "text": "m_StaticTexts.pstText",
            "tooltip": "m_StaticTexts.pstToolTip",
        },
        "VisuFbElemSimple": {
            "text": "m_StaticTexts.pstText",
            "tooltip": "m_StaticTexts.pstToolTip",
            "textVariable": "m_pTextChanges..pVarText",
        },
    }
    if element_type not in allowed_types:
        raise OperationError(
            "elementType is not in the verified native creator allowlist",
            "visual_element_type_unsupported",
            {"actual": element_type, "supported": sorted(allowed_types.keys()),
             "mutatedProject": False},
        )
    if not target:
        raise OperationError("target visualization is required", "invalid_argument",
                             {"path": "target"})
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", instance_name):
        raise OperationError("instanceName must be an IEC identifier", "invalid_argument",
                             {"path": "instanceName", "actual": instance_name})
    bindings = req.get("bindings") or {}
    if not isinstance(bindings, dict):
        raise OperationError("bindings must be an object", "invalid_argument",
                             {"path": "bindings"})
    unknown_bindings = sorted(set(bindings.keys()) - set(allowed_types[element_type].keys()))
    if unknown_bindings:
        raise OperationError("unsupported binding keys", "visual_binding_unsupported",
                             {"actual": unknown_bindings,
                              "supported": sorted(allowed_types[element_type].keys()),
                              "mutatedProject": False})
    if element_type == "VisuFbCheckbox" and not _text(bindings.get("variable")).strip():
        raise OperationError("Checkbox requires bindings.variable", "invalid_argument",
                             {"path": "bindings.variable",
                              "correctFormat": "<GVL-or-POU>.<variable>",
                              "example": "VisualToolGVL.gEnabled"})
    for key in ("variable", "textVariable"):
        expression = _text(bindings.get(key)).strip()
        if expression and not re.match(
                r"^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)+$",
                expression):
            raise OperationError(
                key + " must be a qualified IEC variable expression",
                "visual_variable_format_invalid",
                {"path": "bindings." + key, "actual": expression,
                 "correctFormat": "<GVL-or-POU>.<variable>",
                 "examples": ["VisualToolGVL.gEnabled", "PLC_PRG.xStart"],
                 "mutatedProject": False},
            )
    geometry = req.get("geometry") or {}
    if not isinstance(geometry, dict):
        raise OperationError("geometry must be an object", "invalid_argument",
                             {"path": "geometry"})
    try:
        x = int(geometry.get("x", 20))
        y = int(geometry.get("y", 20))
        width = int(geometry.get("width", 160))
        height = int(geometry.get("height", 48))
    except Exception:
        raise OperationError("geometry values must be integers", "invalid_argument",
                             {"path": "geometry"})
    if width <= 0 or height <= 0 or width > 10000 or height > 10000:
        raise OperationError("geometry width/height are out of range", "invalid_argument",
                             {"geometry": geometry, "widthRange": [1, 10000],
                              "heightRange": [1, 10000]})

    import System
    script_object, object_path = find_project_object(target)
    object_guid = _object_guid(script_object)
    if not object_guid:
        raise OperationError("visual object has no GUID", "visual_guid_unavailable",
                             {"target": target, "path": object_path})
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    meta = object_mgr.GetObjectToModify(handle, System.Guid(object_guid))
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    if native is None or not _text(native.GetType().FullName).endswith(".VisualObject"):
        raise OperationError("target is not a native VisualObject",
                             "visual_object_type_mismatch",
                             {"target": object_path,
                              "runtimeType": (_text(native.GetType().FullName)
                                              if native is not None else None),
                              "mutatedProject": False})
    visual_list = _get_member(native, "VisualElemList", "get_VisualElemList")
    if visual_list is None:
        raise OperationError("native VisualElemList is unavailable",
                             "visual_element_list_unavailable",
                             {"target": object_path, "mutatedProject": False})
    count_before = int(_get_member(visual_list, "Count", "get_Count", 0))
    for index in range(count_before):
        existing = visual_list.GetVisualElem(index)
        if _text(_get_member(existing, "InstanceName", "get_InstanceName")) == instance_name:
            raise OperationError("visual element instanceName already exists",
                                 "visual_element_name_exists",
                                 {"instanceName": instance_name, "index": index,
                                  "mutatedProject": False})

    manager_type = _reflection_type(
        "_3S.CoDeSys.VisualEditor.VisualObjectManager, VisualEditor.plugin")
    if manager_type is None:
        raise OperationError("VisualObjectManager is unavailable",
                             "visual_object_manager_unavailable",
                             {"mutatedProject": False})
    singleton_property = manager_type.GetProperty("Singleton")
    manager = singleton_property.GetValue(None, None) if singleton_property is not None else None
    if manager is None:
        raise OperationError("VisualObjectManager.Singleton is unavailable",
                             "visual_object_manager_unavailable",
                             {"mutatedProject": False})
    unique_id = int(_get_member(native, "UniqueId", "get_UniqueId", count_before + 1))
    try:
        element = manager.CreateElementByTypeName(
            element_type, None, instance_name, unique_id, int(handle),
            System.Guid(object_guid), True, None, None)
    except Exception as exc:
        raise OperationError("native visual element creation failed",
                             "visual_element_create_failed",
                             {"elementType": element_type, "instanceName": instance_name,
                              "cause": repr(exc), "mutatedProject": False})
    if element is None:
        raise OperationError("native visual element creator returned no element",
                             "visual_element_create_empty",
                             {"elementType": element_type, "mutatedProject": False})
    element.SetRect(x, y, width, height)
    member_readback = {}
    for key in sorted(bindings.keys()):
        value = _text(bindings.get(key))
        member_path = allowed_types[element_type][key]
        member = element.GetVisualElemMember(member_path, True, value)
        if member is None:
            raise OperationError("visual element member is unavailable",
                                 "visual_element_member_unavailable",
                                 {"binding": key, "memberPath": member_path,
                                  "mutatedProject": False})
        member.Value = value
        member_readback[key] = {"memberPath": member_path,
                                "requested": value,
                                "actual": _text(_get_member(member, "Value", "get_Value"))}
    added_index = int(visual_list.Add(element))
    object_mgr.SetObject(meta, True, None)

    read_meta = object_mgr.GetObjectToRead(handle, System.Guid(object_guid))
    read_native = _get_member(read_meta, "Object", "get_Object")
    read_list = _get_member(read_native, "VisualElemList", "get_VisualElemList")
    count_after = int(_get_member(read_list, "Count", "get_Count", 0))
    persisted = None
    for index in range(count_after):
        candidate = read_list.GetVisualElem(index)
        if _text(_get_member(candidate, "InstanceName", "get_InstanceName")) == instance_name:
            persisted = candidate
            added_index = index
            break
    if persisted is None or count_after != count_before + 1:
        raise OperationError("visual element commit readback failed",
                             "visual_element_readback_mismatch",
                             {"countBefore": count_before, "countAfter": count_after,
                              "instanceName": instance_name, "mutatedProject": True})
    persisted_members = {}
    binding_mismatches = []
    for key, member_path in allowed_types[element_type].items():
        if key not in bindings:
            continue
        member = persisted.GetVisualElemMember(member_path)
        actual_value = (_text(_get_member(member, "Value", "get_Value"))
                        if member is not None else None)
        persisted_members[key] = {
            "memberPath": member_path,
            "value": actual_value,
        }
        expected_value = _text(bindings.get(key))
        if actual_value != expected_value:
            binding_mismatches.append({
                "path": "bindings." + key,
                "expected": expected_value,
                "actual": actual_value,
            })
    if binding_mismatches:
        raise OperationError(
            "visual element commit did not retain every requested binding",
            "visual_element_binding_readback_mismatch",
            {"target": object_path, "instanceName": instance_name,
             "mismatches": binding_mismatches, "mutatedProject": True},
        )
    return {
        "input": {
            "target": object_path,
            "elementType": element_type,
            "instanceName": instance_name,
            "geometry": {"x": x, "y": y, "width": width, "height": height},
            "bindings": dict(bindings),
        },
        "target": object_path,
        "guid": object_guid,
        "elementType": element_type,
        "instanceName": instance_name,
        "geometry": {"x": x, "y": y, "width": width, "height": height},
        "bindings": dict(bindings),
        "before": {"elementCount": count_before},
        "after": {"elementCount": count_after, "index": added_index,
                  "instanceName": _text(_get_member(
                      persisted, "InstanceName", "get_InstanceName")),
                  "runtimeType": _text(persisted.GetType().FullName),
                  "members": persisted_members},
        "immediateReadback": True,
        "exactBindingReadback": True,
        "exactInstanceReadback": True,
        "elementCountReadback": True,
        "committed": True,
        "mutatedProject": True,
        "status": "created_persistence_pending",
        "correctVariableFormat": "<GVL-or-POU>.<variable>",
        "nextRequired": ["project.save", "fresh-process reopen",
                         "visual.element.probe", "UI screenshot", "build.compile"],
    }


VISUAL_OBJECT_FACTORY_GUID = "c351e8a2-c063-47de-a429-ee0bed555955"


def visual_page_create(req):
    """Create the one verified VisualObject page route with side-effect cleanup.

    InoProShop's VisualObjectFactory creates a native page and exactly one
    generated root GlobalTextList. That root is unsupported by the vendor
    POUs compiler, so this operation treats its ownership and deletion as an
    explicit part of the transaction rather than hiding it in a generic
    factory writer.
    """
    _require_current_disposable_project(req, "visual.page.create")
    if _text(req.get("confirm")).strip() != "create_visual_page":
        raise OperationError("confirm must equal create_visual_page",
                             "confirmation_required", {
                                 "correctFormat": {"confirm": "create_visual_page",
                                                    "disposable": True}})
    name = _text(req.get("name")).strip()
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
        raise OperationError("name must be an IEC identifier", "invalid_argument",
                             {"path": "name", "actual": name})
    parent = _text(req.get("parent") or "Application").strip()
    if parent != "Application":
        raise OperationError("visual.page.create requires the Application parent",
                             "visual_page_parent_unsupported", {
                                 "actual": parent, "required": "Application",
                                 "mutatedProject": False})
    before = []
    _walk_objects(project, [], 1, 64, before)
    result = vendor_object_factory_create({
        "factoryGuid": VISUAL_OBJECT_FACTORY_GUID,
        "name": name,
        "parent": "Application",
        "disposable": True,
        "confirm": "vendor_object_factory_create",
    })
    after = []
    _walk_objects(project, [], 1, 64, after)
    before_guids = set(_object_guid(item).lower() for _path, item in before
                       if _object_guid(item))
    generated = []
    for path, item in after:
        guid = _object_guid(item).lower()
        if guid not in before_guids and _object_name(item) == "GlobalTextList":
            generated.append((path, item, guid))
    if len(generated) != 1:
        raise OperationError(
            "VisualObjectFactory did not produce exactly one owned GlobalTextList",
            "visual_page_global_text_list_ownership_mismatch", {
                "factoryGuid": VISUAL_OBJECT_FACTORY_GUID,
                "generatedGlobalTextLists": [item[0] for item in generated],
                "createdGuid": result.get("createdGuid"),
                "mutatedProject": True,
                "recovery": "close disposable project without saving",
            })
    generated_path, generated_object, generated_guid = generated[0]
    generated_object.remove()
    remaining = []
    _walk_objects(project, [], 1, 64, remaining)
    still_present = [path for path, item in remaining
                     if _object_guid(item).lower() == generated_guid]
    if still_present:
        raise OperationError(
            "owned GlobalTextList deletion readback failed",
            "visual_page_global_text_list_delete_mismatch", {
                "path": generated_path, "guid": generated_guid,
                "mutatedProject": True,
                "recovery": "close disposable project without saving",
            })
    result["pageTransaction"] = {
        "factoryGuid": VISUAL_OBJECT_FACTORY_GUID,
        "parent": "Application",
        "generatedGlobalTextList": {"path": generated_path, "guid": generated_guid},
                "generatedGlobalTextListDeleted": True,
        "remainingTreeReadback": True,
        "compileRequired": True,
    }
    result["input"] = {"name": name, "parent": "Application"}
    result["exactPageReadback"] = bool(
        result.get("createdGuid") and
        result.get("createdGuid") == (result.get("object") or {}).get("guid") and
        result.get("treePath") == (result.get("object") or {}).get("path") and
        (result.get("object") or {}).get("name") == name)
    result["status"] = "created_page_global_text_list_compensation_pending"
    result["limits"] = [
        "exact VisualObjectFactory GUID and Application parent only",
        "generated GlobalTextList must be unique and is deleted only when owned by this transaction",
        "save/reopen and second compile remain explicit gates",
        "does not claim online visualization runtime",
    ]
    return result


def _vendor_domain_probe(req, domain):
    """Read one persisted Alarm/Recipe object through ObjectMgr only."""
    _require_project()
    import System
    target = _text(req.get("target") or req.get("path")).strip()
    requested_guid = _text(req.get("guid")).strip().lower()
    if not target and not requested_guid:
        raise OperationError(domain + ".probe requires target or guid", "invalid_argument",
                             {"paths": ["target", "guid"]})
    if requested_guid and not re.match(
            r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
            requested_guid):
        raise OperationError(domain + ".probe guid must be a GUID", "invalid_argument",
                             {"path": "guid", "actual": requested_guid})
    try:
        max_items = max(1, min(int(req.get("maxItems", 256)), 1000))
    except Exception:
        raise OperationError("maxItems must be an integer", "invalid_argument",
                             {"path": "maxItems"})
    if requested_guid:
        flat = []
        _walk_objects(project, [], 1, 64, flat)
        guid_matches = [(path, obj) for path, obj in flat
                        if _object_guid(obj).lower() == requested_guid]
        if len(guid_matches) != 1:
            raise OperationError(
                "domain object GUID did not resolve to exactly one project object",
                domain + "_guid_not_unique",
                {"guid": requested_guid, "matchCount": len(guid_matches),
                 "paths": [item[0] for item in guid_matches]},
            )
        script_object, object_path = guid_matches[0][1], guid_matches[0][0]
        if target:
            target_object, target_path = find_project_object(target)
            target_guid = _object_guid(target_object).lower()
            if target_guid != requested_guid:
                raise OperationError(
                    "domain probe target and guid resolve to different objects",
                    domain + "_selector_mismatch",
                    {"target": target, "targetPath": target_path,
                     "targetGuid": target_guid, "guid": requested_guid},
                )
    else:
        script_object, object_path = find_project_object(target)
        requested_guid = _object_guid(script_object).lower()
        if not requested_guid:
            raise OperationError("domain object has no GUID", domain + "_guid_unavailable",
                                 {"target": target, "path": object_path})
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    try:
        meta = object_mgr.GetObjectToRead(handle, System.Guid(requested_guid))
    except Exception as exc:
        raise OperationError("native domain object lookup failed",
                             domain + "_object_lookup_failed",
                             {"target": object_path, "guid": requested_guid,
                              "projectHandle": handle, "cause": repr(exc)})
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    if native is None:
        raise OperationError("native domain object is unavailable",
                             domain + "_object_unavailable",
                             {"target": object_path, "guid": requested_guid,
                              "projectHandle": handle})
    runtime_type = _text(native.GetType().FullName)
    domain_tokens = ("alarm", "alarmconfiguration") if domain == "alarm" else ("recipe",)
    if not any(token in runtime_type.lower() for token in domain_tokens):
        raise OperationError("target native type is not a " + domain + " object",
                             domain + "_object_mismatch",
                             {"target": object_path, "guid": requested_guid,
                              "runtimeType": runtime_type,
                              "expectedTypeTokens": list(domain_tokens)})
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    value_tokens = ("alarm", "recipe", "group", "class", "condition", "text",
                    "message", "expression", "variable", "ack", "confirm",
                    "notification", "action", "priority", "storage", "definition",
                    "value", "name", "target", "column", "type", "id", "path")
    variable_tokens = ("variable", "expression", "address", "reference", "target")
    scalar_types = set(("System.String", "System.Boolean", "System.Byte",
                        "System.SByte", "System.Int16", "System.UInt16",
                        "System.Int32", "System.UInt32", "System.Int64",
                        "System.UInt64", "System.Single", "System.Double",
                        "System.Decimal", "System.Guid"))

    def scalar(value):
        if value is None:
            return None
        if isinstance(value, bool) or isinstance(value, _INTEGER_TYPES):
            return value
        if isinstance(value, float):
            return value
        return _text(value)[:512]

    def interfaces(value):
        try:
            return sorted(set(_text(item.FullName) for item in value.GetType().GetInterfaces()))[:200]
        except Exception:
            return []

    def collection_snapshot(value):
        if value is None:
            return None
        count = _get_member(value, "Count", "get_Count")
        try:
            count = int(count) if count is not None else None
        except Exception:
            count = None
        info = {"runtimeType": _text(value.GetType().FullName),
                "count": count, "items": []}
        if count is None and not hasattr(value, "__iter__"):
            return info
        try:
            values = list(value)
        except Exception:
            values = []
            upper = min(count, max_items) if count is not None else 0
            for index in range(upper):
                try:
                    values.append(value[index])
                except Exception:
                    break
        for item in values[:max_items]:
            if item is None:
                continue
            item_entry = {"runtimeType": _text(item.GetType().FullName),
                          "interfaces": interfaces(item), "values": {}}
            try:
                for prop in item.GetType().GetProperties(flags):
                    name = _text(prop.Name)
                    if prop.GetIndexParameters().Length:
                        continue
                    lowered = name.lower()
                    prop_type = _text(prop.PropertyType.FullName)
                    if not any(token in lowered for token in value_tokens) and prop_type not in scalar_types:
                        continue
                    try:
                        prop_value = prop.GetValue(item, None)
                        if prop_value is not None and (prop_type in scalar_types or isinstance(prop_value, _STRING_TYPES)):
                            item_entry["values"][name] = scalar(prop_value)
                    except Exception as exc:
                        item_entry["values"][name] = {"readError": repr(exc)}
            except Exception as exc:
                item_entry["reflectionError"] = repr(exc)
            refs = []
            for name, value_text in item_entry["values"].items():
                if isinstance(value_text, dict) or not _text(value_text).strip():
                    continue
                if any(token in name.lower() for token in variable_tokens):
                    refs.append({"property": name, "value": _text(value_text)})
            item_entry["variableReferences"] = refs
            info["items"].append(item_entry)
        info["returned"] = len(info["items"])
        info["truncated"] = count is not None and count > max_items
        return info

    properties = []
    selected = {}
    for prop in native.GetType().GetProperties(flags):
        name = _text(prop.Name)
        properties.append({"name": name, "type": _text(prop.PropertyType.FullName)})
        lowered = name.lower()
        if not any(token in lowered for token in value_tokens):
            continue
        try:
            value = prop.GetValue(native, None)
            prop_type = _text(prop.PropertyType.FullName)
            if prop_type in scalar_types or isinstance(value, _STRING_TYPES):
                selected[name] = scalar(value)
            elif value is not None:
                selected[name] = collection_snapshot(value)
        except Exception as exc:
            selected[name] = {"readError": repr(exc)}
    methods = sorted(set(_text(method.ToString()) for method in native.GetType().GetMethods(flags)))[:500]
    return {
        "domain": domain,
        "target": target or requested_guid,
        "path": object_path,
        "guid": requested_guid,
        "selection": "guid" if req.get("guid") else "target",
        "projectHandle": handle,
        "objectRuntimeType": runtime_type,
        "interfaces": interfaces(native),
        "properties": properties,
        "methods": methods,
        "selected": selected,
        "objectManager": manager_probe,
        "maxItems": max_items,
        "readOnly": True,
        "mutatedProject": False,
        "status": "observed",
    }


def vendor_alarm_probe(req):
    return _vendor_domain_probe(req, "alarm")


ALARM_OBJECTS_ASSEMBLY = "AlarmConfigurationObjects.plugin"
ALARM_GROUP_RUNTIME_TYPE = "_3S.CoDeSys.AlarmConfigurationObjects.AlarmGroupObject"
ALARM_CLASS_RUNTIME_TYPE = "_3S.CoDeSys.AlarmConfigurationObjects.AlarmClassObject"
ALARM_RUNTIME_TYPE = "_3S.CoDeSys.AlarmConfigurationObjects.Alarm"
DIGITAL_OBSERVATION_RUNTIME_TYPE = (
    "_3S.CoDeSys.AlarmConfigurationObjects.DigitalObservation"
)
ALARM_COMPARISON_CODES = {"=": 179, "<>": 180}


def _alarm_object_manager(access="read"):
    """Return the live ObjectMgr and project handle for alarm transactions."""
    import System
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    return object_mgr, handle, manager_probe


def _alarm_native_target(selector, expected_token, access="read", requested_guid=None):
    """Resolve one exact tree object through ObjectMgr.

    Alarm wrappers can have duplicate display paths, so the writer accepts a
    path or GUID but always commits the native object returned by ObjectMgr.
    It deliberately does not fall back to a type-only enumeration.
    """
    import System
    selector = _text(selector).strip()
    requested_guid = _text(requested_guid).strip().lower()
    if not selector and not requested_guid:
        raise OperationError("alarm selector is required", "invalid_argument")
    if requested_guid:
        if not re.match(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
                        requested_guid):
            raise OperationError("alarm guid must be a GUID", "invalid_argument",
                                 {"path": "guid", "actual": requested_guid})
        matches = []
        flat = []
        _walk_objects(project, [], 1, 64, flat)
        for candidate_path, candidate in flat:
            if _object_guid(candidate).lower() == requested_guid:
                matches.append((candidate_path, candidate))
        if len(matches) != 1:
            raise OperationError(
                "alarm GUID did not resolve to exactly one project object",
                "alarm_guid_not_unique",
                {"guid": requested_guid, "matchCount": len(matches),
                 "paths": [item[0] for item in matches]})
        path, script_object = matches[0]
        if selector:
            try:
                target_object, target_path = find_project_object(selector)
                if _object_guid(target_object).lower() != requested_guid:
                    raise OperationError(
                        "alarm selector and GUID resolve to different objects",
                        "alarm_selector_mismatch",
                        {"selector": selector, "targetPath": target_path,
                         "guid": requested_guid})
            except OperationError as exc:
                if exc.code == "ambiguous_object_target":
                    # A duplicate wrapper path is expected here; the exact
                    # GUID remains authoritative and is already unique.
                    pass
                else:
                    raise
    else:
        script_object, path = find_project_object(selector)
    guid = requested_guid or _object_guid(script_object)
    if not guid:
        raise OperationError("alarm selector has no GUID", "alarm_guid_unavailable",
                             {"selector": selector, "path": path})
    object_mgr, handle, manager_probe = _alarm_object_manager(access)
    getter = (object_mgr.GetObjectToModify if access == "modify"
              else object_mgr.GetObjectToRead)
    try:
        meta = getter(handle, System.Guid(guid))
    except Exception as exc:
        raise OperationError("native alarm object lookup failed",
                             "alarm_object_lookup_failed",
                             {"selector": selector, "path": path, "guid": guid,
                              "access": access, "cause": repr(exc)})
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    runtime_type = _text(native.GetType().FullName) if native is not None else ""
    if expected_token.lower() not in runtime_type.lower():
        raise OperationError("alarm selector resolved to an unexpected native type",
                             "alarm_object_type_mismatch",
                             {"selector": selector, "path": path, "guid": guid,
                              "runtimeType": runtime_type, "expected": expected_token})
    return object_mgr, meta, native, {
        "selector": selector or requested_guid,
        "path": path,
        "guid": _text(guid),
        "nativeGuid": _text(_get_member(meta, "ObjectGuid", "get_ObjectGuid", guid)),
        "projectHandle": handle,
        "objectRuntimeType": runtime_type,
        "objectManager": manager_probe,
        "access": access,
    }


def _alarm_sequence(value):
    if value is None:
        return []
    try:
        return list(value)
    except Exception:
        count = _get_member(value, "Count", "get_Count")
        try:
            count = int(count or 0)
        except Exception:
            count = 0
        result = []
        for index in range(count):
            try:
                result.append(value[index])
            except Exception:
                try:
                    result.append(value.get_Item(index))
                except Exception:
                    break
        return result


def _alarm_property(value, name, default=None):
    if value is None:
        return default
    return _get_member(value, name, "get_" + name, default)


def _alarm_native_guid(value):
    """Read a native object's MetaObject GUID (tree wrappers use ``guid``)."""
    meta = _alarm_property(value, "MetaObject")
    return _text(_get_member(meta, "ObjectGuid", "get_ObjectGuid", ""))


def _alarm_reflection_instance(type_name):
    """Instantiate an internal vendor Alarm type without a guessed constructor."""
    import System
    runtime_type = _reflection_type(type_name + ", " + ALARM_OBJECTS_ASSEMBLY)
    if runtime_type is None:
        raise OperationError("alarm runtime type is unavailable",
                             "alarm_type_unavailable", {"type": type_name})
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    constructors = [item for item in runtime_type.GetConstructors(flags)
                    if item.GetParameters().Length == 0]
    if not constructors:
        raise OperationError("alarm runtime type has no parameterless constructor",
                             "alarm_constructor_unavailable",
                             {"type": type_name,
                              "runtimeType": _text(runtime_type.FullName)})
    try:
        value = constructors[0].Invoke(System.Array[System.Object]([]))
    except Exception as exc:
        raise OperationError("alarm runtime type construction failed",
                             "alarm_constructor_failed",
                             {"type": type_name, "cause": repr(exc)})
    return value, runtime_type


def _alarm_set_property(value, name, requested):
    """Set a public property using CLR reflection so internal classes work."""
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    prop = value.GetType().GetProperty(name, flags)
    if prop is None or not prop.CanWrite:
        raise OperationError("alarm property is not writable",
                             "alarm_property_unavailable",
                             {"property": name,
                              "runtimeType": _text(value.GetType().FullName)})
    converted = requested
    prop_type = prop.PropertyType
    if _text(prop_type.FullName) == "System.Byte":
        converted = System.Byte(int(requested))
    elif _text(prop_type.FullName) == "System.UInt32":
        converted = System.UInt32(int(requested))
    elif bool(prop_type.IsEnum):
        converted = System.Enum.ToObject(prop_type, int(requested))
    try:
        prop.SetValue(value, converted, None)
        return prop.GetValue(value, None)
    except Exception as exc:
        raise OperationError("alarm property setter rejected the value",
                             "alarm_property_write_failed",
                             {"property": name, "requested": _json_safe(requested),
                              "cause": repr(exc)})


def _alarm_invoke(value, name, arguments):
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    candidates = []
    for method in value.GetType().GetMethods(flags):
        if _text(method.Name) == name and len(method.GetParameters()) == len(arguments):
            candidates.append(method)
    if not candidates:
        raise OperationError("alarm method binding is unavailable",
                             "alarm_method_unavailable",
                             {"method": name, "runtimeType": _text(value.GetType().FullName)})
    try:
        return candidates[0].Invoke(value, System.Array[System.Object](arguments))
    except Exception as exc:
        raise OperationError("alarm native method failed",
                             "alarm_method_failed",
                             {"method": name, "cause": repr(exc)})


def _alarm_class_snapshot(alarm_class):
    if alarm_class is None:
        return None
    return {
        "runtimeType": _text(alarm_class.GetType().FullName),
        "guid": _alarm_native_guid(alarm_class),
        "name": _text(_get_member(alarm_class, "Name", "get_Name", "")),
        "priority": _json_safe(_alarm_property(alarm_class, "Priority")),
        "archiving": bool(_alarm_property(alarm_class, "Archiving", False)),
        "acknowledgeMethod": _json_safe(
            _alarm_property(alarm_class, "AcknowledgeMethod")),
        "acknowledgeSeparately": bool(
            _alarm_property(alarm_class, "AcknowledgeSeparately", False)),
    }


def _alarm_item_snapshot(alarm, project_handle=None):
    observation = _alarm_property(alarm, "ObservationType")
    observation_snapshot = None
    if observation is not None:
        observation_snapshot = {
            "runtimeType": _text(observation.GetType().FullName),
            "expression": _json_safe(_alarm_property(observation, "Expression")),
            "comparison": _json_safe(_alarm_property(observation, "Comparison")),
            "expressionToCompare": _json_safe(
                _alarm_property(observation, "ExpressionToCompare")),
        }
    alarm_class = None
    if project_handle is not None:
        try:
            alarm_class = _alarm_invoke(alarm, "GetAlarmClass", [int(project_handle)])
        except OperationError:
            alarm_class = None
    messages = []
    count = _alarm_property(alarm, "CountMessages")
    try:
        for index in range(int(count or 0)):
            messages.append(_json_safe(_alarm_invoke(alarm, "GetMessageID", [index])))
    except Exception:
        messages = []
    return {
        "runtimeType": _text(alarm.GetType().FullName),
        "internalID": _json_safe(_alarm_property(alarm, "InternalID")),
        "id": _json_safe(_alarm_property(alarm, "ID")),
        "deactivation": _json_safe(_alarm_property(alarm, "Deactivation")),
        "minPendingTime": _json_safe(_alarm_property(alarm, "MinPendingTime")),
        "latchVariable1": _json_safe(_alarm_property(alarm, "LatchVariable1")),
        "latchVariable2": _json_safe(_alarm_property(alarm, "LatchVariable2")),
        "higherPrioAlarm": _json_safe(_alarm_property(alarm, "HigherPrioAlarm")),
        "observation": observation_snapshot,
        "alarmClass": _alarm_class_snapshot(alarm_class),
        "messages": messages,
        "messageCount": _json_safe(count),
    }


def _alarm_group_snapshot(group, project_handle):
    alarms = _alarm_sequence(_alarm_property(group, "Alarms"))
    return {
        "runtimeType": _text(group.GetType().FullName),
        "guid": _alarm_native_guid(group),
        "internalID": _json_safe(_alarm_property(group, "InternalID")),
        "alarmCount": len(alarms),
        "alarms": [_alarm_item_snapshot(item, project_handle) for item in alarms],
    }


def alarm_item_create(req):
    """Create one fully parameterized Alarm item under an existing Group.

    This is intentionally an experimental writer.  It is protected by the
    normal disposable gate and is not promoted until UI, save/reopen, and all
    diagnostic categories have a runtime evidence record.
    """
    req = req or {}
    if req.get("confirm") != "create_alarm_item":
        raise OperationError("confirm must exactly equal create_alarm_item",
                             "confirmation_required")
    _require_current_disposable_project(req, "alarm.item.create")
    group_selector = _text(req.get("group") or req.get("target") or "").strip()
    class_selector = _text(req.get("alarmClass") or req.get("class") or "").strip()
    group_guid = _text(req.get("groupGuid") or "").strip()
    class_guid = _text(req.get("alarmClassGuid") or "").strip()
    alarm_id = _text(req.get("id") or "").strip()
    expression = _text(req.get("expression") or "").strip()
    expression_to_compare = _text(req.get("expressionToCompare") or "").strip()
    comparison = _text(req.get("comparison") or "=").strip()
    if (not group_selector and not group_guid) or (not class_selector and not class_guid) or not alarm_id or not expression:
        raise OperationError(
            "group, alarmClass, id, and expression are required",
            "invalid_argument",
            {"required": ["group or groupGuid", "alarmClass or alarmClassGuid", "id", "expression",
                           "expressionToCompare", "comparison"]})
    if not expression_to_compare:
        raise OperationError("expressionToCompare is required for a digital alarm",
                             "invalid_argument",
                             {"path": "expressionToCompare",
                              "correctFormat": "TRUE | FALSE | <IEC scalar>"})
    if comparison not in ALARM_COMPARISON_CODES:
        raise OperationError("comparison must be '=' or '<>'",
                             "invalid_argument",
                             {"path": "comparison", "actual": comparison,
                              "supported": ["=", "<>"]})
    if ("/" in alarm_id or "\\" in alarm_id or
            not re.match(r"^[A-Za-z_][A-Za-z0-9_.-]*$", alarm_id)):
        raise OperationError("id must be one IEC-safe alarm identifier",
                             "invalid_argument", {"path": "id", "actual": alarm_id,
                              "correctFormat": "Alarm_001"})
    if any(field in req for field in ("message", "text", "messageId")):
        raise OperationError(
            "alarm text/message requires an existing native TextList binding; a free text or message ID cannot be stored without it",
            "alarm_text_requires_text_list",
            {"mutatedProject": False,
             "next": "bind an existing TextList and create/read its exact message ID",
             "acceptedFields": []})
    # Round-23 evidence: an alarm expression referencing a Program POU member
    # (Application.MotorCtrl.X0 — a local input) compiles with 18 errors.
    # Alarm conditions must reference GLOBAL variables; catch it at plan time
    # with the exact fix instead of poisoning the project.
    expression_parts = expression.split(".")
    if len(expression_parts) >= 3 and expression_parts[0].strip().lower() == "application":
        first_object = expression_parts[1].strip()
        if first_object:
            try:
                _pou_obj, _pou_path = find_project_object("Application/" + first_object)
                pou_type = _text(_pou_obj.GetType().FullName).lower()
                if "program" in pou_type and "gvl" not in pou_type:
                    raise OperationError(
                        "alarm expression references a Program POU member; "
                        "alarm conditions must reference GLOBAL variables "
                        "(GVL members or application globals), not POU local "
                        "inputs/outputs",
                        "alarm_expression_not_addressable",
                        {"expression": expression, "pou": first_object,
                         "pouRuntimeType": _text(_pou_obj.GetType().FullName),
                         "fix": "declare a GVL (gvl.create) with a BOOL and use "
                                "Application.<GVL>.<var> in the expression",
                         "mutatedProject": False})
            except OperationError as exc:
                if exc.code != "object_not_found":
                    raise
    _read_mgr, _read_meta, read_group, read_group_binding = _alarm_native_target(
        group_selector, "AlarmGroupObject", "read", group_guid)
    class_mgr, class_meta, alarm_class, class_binding = _alarm_native_target(
        class_selector, "AlarmClassObject", "read", class_guid)
    if "Template" in _text(alarm_class.GetType().FullName):
        raise OperationError("alarmClass must be an existing AlarmClassObject, not a template",
                             "alarm_class_template_not_usable", {"selector": class_selector})
    handle = read_group_binding["projectHandle"]
    before = _alarm_group_snapshot(read_group, handle)
    duplicates = [item for item in before["alarms"] if item.get("id") == alarm_id]
    if duplicates:
        raise OperationError("alarm id already exists in the selected group",
                             "alarm_already_exists", {"id": alarm_id, "before": before,
                                                       "mutatedProject": False})
    object_mgr, group_meta, group, group_binding = _alarm_native_target(
        group_selector, "AlarmGroupObject", "modify", group_guid)
    locked_before = _alarm_group_snapshot(group, handle)
    if locked_before != before:
        raise OperationError("Alarm Group changed before the write lock was acquired",
                             "alarm_group_changed_before_write",
                             {"before": before, "lockedBefore": locked_before,
                              "mutatedProject": False,
                              "processDiscardRequired": True})
    alarm, alarm_type = _alarm_reflection_instance(ALARM_RUNTIME_TYPE)
    observation, observation_type = _alarm_reflection_instance(
        DIGITAL_OBSERVATION_RUNTIME_TYPE)
    _alarm_set_property(observation, "Expression", expression)
    _alarm_set_property(observation, "Comparison", ALARM_COMPARISON_CODES[comparison])
    _alarm_set_property(observation, "ExpressionToCompare", expression_to_compare)
    _alarm_set_property(alarm, "ID", alarm_id)
    _alarm_set_property(alarm, "ObservationType", observation)
    for field in ("deactivation", "minPendingTime", "latchVariable1",
                  "latchVariable2", "higherPrioAlarm"):
        if field in req:
            value = req.get(field)
            if not isinstance(value, _STRING_TYPES):
                raise OperationError("alarm field must be a string",
                                     "invalid_argument", {"path": field})
            _alarm_set_property(alarm, {
                "deactivation": "Deactivation",
                "minPendingTime": "MinPendingTime",
                "latchVariable1": "LatchVariable1",
                "latchVariable2": "LatchVariable2",
                "higherPrioAlarm": "HigherPrioAlarm",
            }[field], value)
    _alarm_invoke(alarm, "SetAlarmClass", [alarm_class])
    group_add = _alarm_invoke(group, "AddAlarm", [alarm])
    after_add = _alarm_group_snapshot(group, handle)
    matches = [item for item in after_add["alarms"] if item.get("id") == alarm_id]
    if len(matches) != 1:
        raise OperationError("native Alarm was not retained by AlarmGroup.AddAlarm",
                             "alarm_add_not_retained",
                             {"before": before, "afterAdd": after_add,
                              "id": alarm_id, "mutatedProject": False})
    try:
        commit_return = object_mgr.SetObject(group_meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed for Alarm Group",
                             "alarm_group_commit_failed",
                             {"before": before, "afterAdd": after_add,
                              "cause": repr(exc), "mutatedProject": True})
    _read_mgr, _read_meta, rebound_group, rebound_binding = _alarm_native_target(
        group_selector, "AlarmGroupObject", "read", group_guid)
    after = _alarm_group_snapshot(rebound_group, handle)
    matches = [item for item in after["alarms"] if item.get("id") == alarm_id]
    if len(matches) != 1:
        raise OperationError("Alarm commit did not retain exactly one item",
                             "alarm_commit_not_retained",
                             {"before": before, "after": after, "id": alarm_id,
                              "commitReturn": _json_safe(commit_return)})
    readback = matches[0]
    observation_readback = readback.get("observation") or {}
    expected = {"id": alarm_id, "expression": expression,
                "comparison": ALARM_COMPARISON_CODES[comparison],
                "expressionToCompare": expression_to_compare}
    actual = {"id": readback.get("id"),
              "expression": observation_readback.get("expression"),
              "comparison": observation_readback.get("comparison"),
              "expressionToCompare": observation_readback.get("expressionToCompare")}
    # The vendor snapshot reports the comparison as its enum name ("Equal",
    # "NotEqual") while the write accepts the numeric codes 179/180; accept
    # either form before the exact comparison.
    _alarm_comparison_names = {179: "equal", 180: "notequal"}
    normalized_actual = dict(actual)
    reported_comparison = normalized_actual.get("comparison")
    if isinstance(reported_comparison, str):
        reported_name = reported_comparison.strip().lower()
        for code_value, name_value in _alarm_comparison_names.items():
            if reported_name == name_value:
                normalized_actual["comparison"] = code_value
                break
    if normalized_actual != expected:
        raise OperationError("Alarm native readback differs from requested fields",
                             "alarm_commit_readback_mismatch",
                             {"before": before, "after": after,
                              "expected": expected, "actual": actual,
                              "commitReturn": _json_safe(commit_return)})
    selected_class_guid = _text(class_binding.get("nativeGuid") or class_binding.get("guid"))
    readback_class_guid = _text((readback.get("alarmClass") or {}).get("guid"))
    if selected_class_guid and readback_class_guid and selected_class_guid.lower() != readback_class_guid.lower():
        raise OperationError("Alarm class reference did not retain the selected class",
                             "alarm_class_reference_mismatch",
                             {"selectedClassGuid": selected_class_guid,
                              "readbackClassGuid": readback_class_guid,
                              "before": before, "after": after})
    return {
        "before": before,
        "input": {"group": group_selector, "alarmClass": class_selector,
                   "groupGuid": group_guid, "alarmClassGuid": class_guid,
                   "id": alarm_id, "expression": expression,
                   "comparison": comparison,
                   "comparisonCode": ALARM_COMPARISON_CODES[comparison],
                   "expressionToCompare": expression_to_compare,
                   "optionalFields": dict((field, req.get(field)) for field in (
                       "deactivation", "minPendingTime", "latchVariable1",
                       "latchVariable2", "higherPrioAlarm") if field in req)},
        "after": after,
        "alarm": readback,
        "alarmClassBinding": class_binding,
        "groupBinding": rebound_binding,
        "nativeTypes": {"alarm": _text(alarm_type.FullName),
                        "observation": _text(observation_type.FullName)},
        "groupAddReturn": _json_safe(group_add),
        "commitReturn": _json_safe(commit_return),
        "mutatedProject": True,
        "exactReadback": True,
        "status": "committed_same_process_requires_ui_save_reopen_compile_gate",
        "limits": [
            "text/message writing is not included until a native TextList binding is verified",
            "class priority and acknowledgement are read from the selected existing AlarmClass; generic AlarmClass creation remains blocked",
            "UI visibility, save/reopen, compiler, precompile, and Library Manager gates are still required before promotion",
        ],
    }


def alarm_item_delete(req):
    """Delete one Alarm item from an existing Alarm Group by id or GUID.

    Round-23 evidence: an alarm item whose expression references a Program
    POU local input compiles with 18 errors (Application.MotorCtrl.X0 is not
    addressable); the delete tool lets a session correct such an item
    instead of being stuck with a poisoned group.
    """
    req = req or {}
    if req.get("confirm") != "delete_alarm_item":
        raise OperationError("confirm must exactly equal delete_alarm_item",
                             "confirmation_required")
    _require_current_disposable_project(req, "alarm.item.delete")
    group_selector = _text(req.get("group") or req.get("target") or "").strip()
    group_guid = _text(req.get("groupGuid") or "").strip()
    alarm_id = _text(req.get("id") or "").strip()
    alarm_guid = _text(req.get("guid") or "").strip()
    if (not group_selector and not group_guid) or (not alarm_id and not alarm_guid):
        raise OperationError(
            "group (or groupGuid) and id (or guid) are required",
            "invalid_argument",
            {"required": ["group or groupGuid", "id or guid"]})
    object_mgr, group_meta, group, group_binding = _alarm_native_target(
        group_selector, "AlarmGroupObject", "modify", group_guid)
    handle = group_binding["projectHandle"]
    before = _alarm_group_snapshot(group, handle)
    alarms = _alarm_sequence(_alarm_property(group, "Alarms"))
    target = None
    target_index = None
    for index, item in enumerate(list(alarms)):
        item_guid = _text(_alarm_native_guid(item)).lower()
        item_id = _text(_alarm_property(item, "ID") or "")
        if (alarm_guid and item_guid == alarm_guid.lower()) or \
           (alarm_id and item_id == alarm_id):
            target = item
            target_index = index
            break
    if target is None:
        raise OperationError("alarm item not found in the selected group",
                             "alarm_item_not_found",
                             {"id": alarm_id, "guid": alarm_guid,
                              "before": before, "mutatedProject": False})
    removal = {"binding": "AlarmGroup.RemoveAlarm(item)", "return": None}
    try:
        _alarm_invoke(group, "RemoveAlarm", [target])
    except Exception as exc:
        raise OperationError(
            "alarm item removal failed: " + repr(exc),
            "alarm_item_remove_failed",
            {"id": alarm_id, "guid": alarm_guid, "before": before,
             "mutatedProject": False})
    after_remove = _alarm_group_snapshot(group, handle)
    if len(after_remove["alarms"]) != len(before["alarms"]) - 1:
        raise OperationError("alarm item removal was not retained in the collection",
                             "alarm_item_remove_not_retained",
                             {"before": before, "afterRemove": after_remove,
                              "id": alarm_id, "mutatedProject": False})
    try:
        commit_return = object_mgr.SetObject(group_meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed after alarm removal",
                             "alarm_group_commit_failed",
                             {"before": before, "afterRemove": after_remove,
                              "cause": repr(exc), "mutatedProject": True})
    _read_mgr, _read_meta, rebound_group, rebound_binding = _alarm_native_target(
        group_selector, "AlarmGroupObject", "read", group_guid)
    after = _alarm_group_snapshot(rebound_group, handle)
    remaining = [item for item in after["alarms"]
                 if item.get("id") == alarm_id or
                 (item.get("guid") or "").lower() == alarm_guid.lower()]
    if remaining:
        raise OperationError("alarm commit did not remove the item",
                             "alarm_commit_not_removed",
                             {"before": before, "after": after, "id": alarm_id,
                              "commitReturn": _json_safe(commit_return)})
    return {
        "before": before,
        "input": {"group": group_selector, "groupGuid": group_guid,
                  "id": alarm_id, "guid": alarm_guid},
        "after": after,
        "removal": removal,
        "groupBinding": rebound_binding,
        "commitReturn": _json_safe(commit_return),
        "mutatedProject": True,
        "exactReadback": True,
        "status": "committed_same_process_requires_ui_save_reopen_compile_gate",
        "limits": [
            "deletes the item from the Alarm Group collection only; alarm configuration persistence still requires save/reopen/compile",
        ],
    }


def vendor_recipe_probe(req):
    return _vendor_domain_probe(req, "recipe")


TRACE_OBJECT_RUNTIME_TYPE = "Inovance.InoPro.InoTraceObject.TraceObject"


def _recipe_definition_native(target, access="read"):
    import System
    script_object, object_path = find_project_object(target)
    guid = _object_guid(script_object)
    if not guid:
        raise OperationError("recipe definition has no GUID",
                             "recipe_definition_guid_unavailable",
                             {"target": target, "path": object_path})
    handle = _trace_project_handle()
    object_mgr, manager_probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": manager_probe})
    getter = (object_mgr.GetObjectToModify if access == "modify"
              else object_mgr.GetObjectToRead)
    try:
        meta = getter(handle, System.Guid(guid))
    except Exception as exc:
        raise OperationError("native Recipe Definition lookup failed",
                             "recipe_definition_lookup_failed",
                             {"target": object_path, "guid": guid,
                              "projectHandle": handle, "access": access,
                              "cause": repr(exc)})
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    runtime_type = (_text(native.GetType().FullName) if native is not None else "")
    if not runtime_type.endswith(".RecipeDefinitionObject"):
        raise OperationError("target is not a native Recipe Definition",
                             "recipe_definition_type_mismatch",
                             {"target": object_path, "guid": guid,
                              "runtimeType": runtime_type,
                              "expected": "_3S.CoDeSys.RecipeManObject.RecipeDefinitionObject"})
    return object_mgr, meta, native, {
        "target": target, "path": object_path, "guid": guid,
        "projectHandle": handle, "access": access,
        "objectRuntimeType": runtime_type,
    }


def _recipe_sequence(value):
    if value is None:
        return []
    try:
        return list(value)
    except Exception:
        count = _get_member(value, "Count", "get_Count")
        result = []
        try:
            count = int(count or 0)
        except Exception:
            count = 0
        for index in range(count):
            try:
                result.append(value[index])
            except Exception:
                try:
                    result.append(value.get_Item(index))
                except Exception:
                    break
        return result


def _recipe_variable_snapshot(variable):
    result = {"runtimeType": _text(variable.GetType().FullName)}
    for name in ("Id", "VariableName", "VariableNameInternal", "Name", "Comment",
                 "InvalidType", "TypeAsString", "UserDefTypeAsString"):
        value = _get_member(variable, name, "get_" + name)
        if value is not None:
            result[name] = _json_safe(value)
    value_type = _get_member(variable, "Type", "get_Type")
    if value_type is not None:
        result["Type"] = _text(_get_member(value_type, "FullName", "get_FullName") or value_type)
    return result


def _recipe_value_snapshot(value, index):
    import System
    result = {"index": index, "runtimeType": _text(value.GetType().FullName)}
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    for prop in value.GetType().GetProperties(flags):
        if prop.GetIndexParameters().Length:
            continue
        name = _text(prop.Name)
        if not any(token in name.lower() for token in
                   ("value", "invalid", "variable", "type", "id", "name")):
            continue
        try:
            prop_value = prop.GetValue(value, None)
            if prop_value is None or isinstance(prop_value, (_STRING_TYPES + _INTEGER_TYPES)) or isinstance(prop_value, bool):
                result[name] = _json_safe(prop_value)
            else:
                result[name] = _text(prop_value)[:512]
        except Exception as exc:
            result[name] = {"readError": repr(exc)}
    return result


def _recipe_snapshot(native, binding):
    variables = _recipe_sequence(_get_member(native, "Variables", "get_Variables"))
    recipes = _recipe_sequence(_get_member(native, "Recipes", "get_Recipes"))
    recipe_rows = []
    for recipe in recipes:
        values = _recipe_sequence(_get_member(recipe, "RecipeValues", "get_RecipeValues"))
        recipe_rows.append({
            "runtimeType": _text(recipe.GetType().FullName),
            "Name": _json_safe(_get_member(recipe, "Name", "get_Name")),
            "Id": _json_safe(_get_member(recipe, "Id", "get_Id")),
            "values": [_recipe_value_snapshot(item, index)
                       for index, item in enumerate(values)],
            "valueCount": len(values),
        })
    return {
        "binding": binding,
        "variables": [_recipe_variable_snapshot(item) for item in variables],
        "variableCount": len(variables),
        "recipes": recipe_rows,
        "recipeCount": len(recipes),
    }


def recipe_variable_add(req):
    target = _text(req.get("definition") or req.get("target") or req.get("path")).strip()
    variable_name = _text(req.get("variableName")).strip()
    name = _text(req.get("name")).strip()
    comment = _text(req.get("comment")) if req.get("comment") is not None else None
    if not target or not variable_name or not name:
        raise OperationError("definition, variableName, and name are required",
                             "invalid_argument",
                             {"required": ["definition", "variableName", "name"],
                              "correctFormat": {
                                  "definition": "Device/Plc Logic/Application/RecipeManager/RecipeDefinition",
                                  "variableName": "Application.RecipeGVL.Setpoint",
                                  "name": "Setpoint"}})
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$",
                    variable_name):
        raise OperationError("recipe variable must use the Recipe Definition IEC format",
                             "recipe_variable_format_invalid",
                             {"path": "variableName", "actual": variable_name,
                              "correctFormat": "<GVL>.<variable>"})
    if req.get("confirm") != "add_recipe_variable":
        raise OperationError("confirm must exactly equal add_recipe_variable",
                             "confirmation_required")
    _require_current_disposable_project(req, "recipe.variable.add")
    _read_mgr, _read_meta, read_native, read_binding = _recipe_definition_native(target, "read")
    before = _recipe_snapshot(read_native, read_binding)
    if any(item.get("Name") == name or item.get("VariableName") == variable_name
           for item in before["variables"]):
        raise OperationError("recipe variable already exists", "recipe_variable_already_exists",
                             {"name": name, "variableName": variable_name, "before": before,
                              "mutatedProject": False})
    object_mgr, meta, native, binding = _recipe_definition_native(target, "modify")
    locked_before = _recipe_snapshot(native, binding)
    if locked_before["variableCount"] != before["variableCount"]:
        raise OperationError("Recipe Definition changed before the write lock was acquired",
                             "recipe_definition_changed_before_write",
                             {"before": before, "lockedBefore": locked_before,
                              "mutatedProject": False,
                              "processDiscardRequired": True})
    try:
        variable = native.CreateVariable()
        setattr(variable, "VariableName", variable_name)
        setattr(variable, "Name", name)
        if comment is not None:
            setattr(variable, "Comment", comment)
    except Exception as exc:
        raise OperationError("native recipe variable creation or type resolution failed",
                             "recipe_variable_type_resolution_failed",
                             {"definition": target, "variableName": variable_name,
                              "correctFormat": "<GVL>.<existingScalar>",
                              "cause": repr(exc), "mutatedProject": False})
    prepared = _recipe_variable_snapshot(variable)
    type_text = _text(prepared.get("TypeAsString")).strip()
    resolved_type = _text(prepared.get("Type")).strip()
    invalid_type = (prepared.get("InvalidType") is True or not type_text or
                    not resolved_type or resolved_type.lower() == "none" or
                    "invalid" in type_text.lower() or u"\u65e0\u6548" in type_text)
    if invalid_type:
        raise OperationError("recipe variable did not resolve to a valid IEC type",
                             "recipe_variable_type_invalid",
                             {"definition": target, "requested": {
                                  "variableName": variable_name, "name": name},
                              "prepared": prepared,
                              "correctFormat": "<GVL>.<existingScalar>",
                              "mutatedProject": False})
    variables = _get_member(native, "Variables", "get_Variables")
    try:
        variables.Add(variable)
        count_after_add = len(_recipe_sequence(variables))
    except Exception as exc:
        raise OperationError("native recipe variable append failed",
                             "recipe_variable_append_failed",
                             {"definition": target, "prepared": prepared,
                              "cause": repr(exc)})
    if count_after_add != before["variableCount"] + 1:
        raise OperationError("recipe variable count did not increase exactly once",
                             "recipe_variable_append_not_retained",
                             {"beforeCount": before["variableCount"],
                              "afterAddCount": count_after_add, "prepared": prepared})
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed", "recipe_variable_commit_failed",
                             {"definition": target, "prepared": prepared,
                              "cause": repr(exc)})
    _mgr, _meta, rebound, rebound_binding = _recipe_definition_native(target, "read")
    after = _recipe_snapshot(rebound, rebound_binding)
    matches = [item for item in after["variables"]
               if item.get("Name") == name and item.get("VariableName") == variable_name]
    if after["variableCount"] != before["variableCount"] + 1 or len(matches) != 1:
        raise OperationError("recipe variable commit was not retained",
                             "recipe_variable_not_retained",
                             {"before": before, "after": after,
                              "requested": {"variableName": variable_name, "name": name},
                              "commitReturn": _json_safe(commit_return)})
    return {"before": before, "input": {"definition": target,
            "variableName": variable_name, "name": name, "comment": comment},
            "after": after, "variable": matches[0],
            "commitReturn": _json_safe(commit_return), "mutatedProject": True,
            "exactReadback": True, "countReadback": True,
            "typeResolved": True,
            "status": "committed_same_process_requires_save_reopen_compile_gate"}


def recipe_create(req):
    target = _text(req.get("definition") or req.get("target") or req.get("path")).strip()
    name = _text(req.get("name")).strip()
    if not target or not name:
        raise OperationError("definition and name are required", "invalid_argument",
                             {"required": ["definition", "name"]})
    if req.get("confirm") != "create_recipe":
        raise OperationError("confirm must exactly equal create_recipe",
                             "confirmation_required")
    _require_current_disposable_project(req, "recipe.create")
    _read_mgr, _read_meta, read_native, read_binding = _recipe_definition_native(target, "read")
    before = _recipe_snapshot(read_native, read_binding)
    if before["variableCount"] == 0:
        raise OperationError("recipe requires at least one valid recipe variable",
                             "recipe_variable_required", {"before": before})
    if any(item.get("Name") == name for item in before["recipes"]):
        raise OperationError("recipe already exists", "recipe_already_exists",
                             {"name": name, "before": before,
                              "mutatedProject": False})
    object_mgr, meta, native, binding = _recipe_definition_native(target, "modify")
    locked_before = _recipe_snapshot(native, binding)
    if (locked_before["variableCount"] != before["variableCount"] or
            locked_before["recipeCount"] != before["recipeCount"]):
        raise OperationError("Recipe Definition changed before the write lock was acquired",
                             "recipe_definition_changed_before_write",
                             {"before": before, "lockedBefore": locked_before,
                              "mutatedProject": False,
                              "processDiscardRequired": True})
    recipes = _get_member(native, "Recipes", "get_Recipes")
    try:
        recipe = native.CreateRecipe(name)
        count_after_create = len(_recipe_sequence(recipes))
        if count_after_create == before["recipeCount"]:
            recipes.Add(recipe)
            count_after_create = len(_recipe_sequence(recipes))
    except Exception as exc:
        raise OperationError("native Recipe creation failed", "recipe_create_failed",
                             {"definition": target, "name": name, "cause": repr(exc)})
    if count_after_create != before["recipeCount"] + 1:
        raise OperationError("recipe count did not increase exactly once",
                             "recipe_create_not_retained",
                             {"beforeCount": before["recipeCount"],
                              "afterCreateCount": count_after_create})
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed", "recipe_commit_failed",
                             {"definition": target, "name": name, "cause": repr(exc)})
    _mgr, _meta, rebound, rebound_binding = _recipe_definition_native(target, "read")
    after = _recipe_snapshot(rebound, rebound_binding)
    matches = [item for item in after["recipes"] if item.get("Name") == name]
    if after["recipeCount"] != before["recipeCount"] + 1 or len(matches) != 1:
        raise OperationError("recipe commit was not retained", "recipe_not_retained",
                             {"before": before, "after": after, "name": name,
                              "commitReturn": _json_safe(commit_return)})
    if matches[0].get("valueCount") != after["variableCount"]:
        raise OperationError("recipe values do not match the definition variables",
                             "recipe_values_not_initialized",
                             {"recipe": matches[0], "variableCount": after["variableCount"],
                              "after": after})
    return {"before": before, "input": {"definition": target, "name": name},
            "after": after, "recipe": matches[0],
            "commitReturn": _json_safe(commit_return), "mutatedProject": True,
            "exactReadback": True, "countReadback": True,
            "valueAlignmentReadback": True,
            "status": "committed_same_process_requires_value_save_reopen_compile_gate"}


def recipe_value_set(req):
    target = _text(req.get("definition") or req.get("target") or req.get("path")).strip()
    recipe_name = _text(req.get("recipe")).strip()
    variable_name = _text(req.get("variable")).strip()
    value = req.get("value")
    if not target or not recipe_name or not variable_name or not isinstance(value, _STRING_TYPES):
        raise OperationError("definition, recipe, variable, and string value are required",
                             "invalid_argument", {"required": {
                                 "definition": "Recipe Definition path",
                                 "recipe": "exact Recipe name",
                                 "variable": "exact recipe-variable Name or VariableName",
                                 "value": "IEC value as string"}})
    if req.get("confirm") != "set_recipe_value":
        raise OperationError("confirm must exactly equal set_recipe_value",
                             "confirmation_required")
    _require_current_disposable_project(req, "recipe.value.set")
    _read_mgr, _read_meta, read_native, read_binding = _recipe_definition_native(target, "read")
    before = _recipe_snapshot(read_native, read_binding)
    recipe_indexes = [index for index, item in enumerate(before["recipes"])
                      if item.get("Name") == recipe_name]
    variable_indexes = [index for index, item in enumerate(before["variables"])
                        if item.get("Name") == variable_name or
                        item.get("VariableName") == variable_name]
    if len(recipe_indexes) != 1 or len(variable_indexes) != 1:
        raise OperationError("recipe and variable selectors must each match exactly once",
                             "recipe_value_selector_mismatch",
                             {"recipe": recipe_name, "variable": variable_name,
                              "recipeMatches": recipe_indexes,
                              "variableMatches": variable_indexes, "before": before})
    recipe_index, variable_index = recipe_indexes[0], variable_indexes[0]
    before_value = _text(before["recipes"][recipe_index]["values"][variable_index].get("Value"))
    if before_value == value:
        return {"before": before, "input": {"definition": target,
                "recipe": recipe_name, "variable": variable_name, "value": value},
                "after": before, "beforeValue": before_value, "afterValue": before_value,
                "commitReturn": None, "mutatedProject": False,
                "selectorReadback": True, "exactReadback": True,
                "status": "unchanged"}
    object_mgr, meta, native, binding = _recipe_definition_native(target, "modify")
    locked_before = _recipe_snapshot(native, binding)
    if (locked_before["variableCount"] != before["variableCount"] or
            locked_before["recipeCount"] != before["recipeCount"]):
        raise OperationError("Recipe Definition changed before the write lock was acquired",
                             "recipe_definition_changed_before_write",
                             {"before": before, "lockedBefore": locked_before,
                              "mutatedProject": False,
                              "processDiscardRequired": True})
    recipes = _recipe_sequence(_get_member(native, "Recipes", "get_Recipes"))
    values = _recipe_sequence(_get_member(recipes[recipe_index],
                                          "RecipeValues", "get_RecipeValues"))
    if len(values) != before["variableCount"] or variable_index >= len(values):
        raise OperationError("RecipeValue collection does not align with variables",
                             "recipe_values_alignment_invalid", {"before": before})
    recipe_value = values[variable_index]
    before_value = _text(_get_member(recipe_value, "Value", "get_Value"))
    try:
        setattr(recipe_value, "Value", value)
        after_set = _text(_get_member(recipe_value, "Value", "get_Value"))
    except Exception as exc:
        raise OperationError("native RecipeValue setter rejected the IEC value",
                             "recipe_value_invalid", {"recipe": recipe_name,
                              "variable": variable_name, "value": value,
                              "cause": repr(exc), "correctFormat": {
                                  "INT": "42", "BOOL": "TRUE", "REAL": "1.5"}})
    if after_set != value:
        raise OperationError("native RecipeValue did not retain the requested text",
                             "recipe_value_not_retained_before_commit",
                             {"before": before_value, "requested": value,
                              "afterSet": after_set})
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed", "recipe_value_commit_failed",
                             {"recipe": recipe_name, "variable": variable_name,
                              "value": value, "cause": repr(exc)})
    _mgr, _meta, rebound, rebound_binding = _recipe_definition_native(target, "read")
    after = _recipe_snapshot(rebound, rebound_binding)
    readback = after["recipes"][recipe_index]["values"][variable_index].get("Value")
    if _text(readback) != value:
        raise OperationError("RecipeValue commit did not retain the requested text",
                             "recipe_value_not_retained", {"before": before,
                              "after": after, "requested": value,
                              "commitReturn": _json_safe(commit_return)})
    return {"before": before, "input": {"definition": target,
            "recipe": recipe_name, "variable": variable_name, "value": value},
            "after": after, "beforeValue": before_value, "afterValue": readback,
            "commitReturn": _json_safe(commit_return), "mutatedProject": True,
            "selectorReadback": True, "exactReadback": True,
            "status": "committed_same_process_requires_save_reopen_compile_gate"}


def recipe_read(req):
    target = _text(req.get("definition") or req.get("target") or req.get("path")).strip()
    if not target:
        raise OperationError("recipe.read requires definition", "invalid_argument",
                             {"required": ["definition"]})
    _mgr, _meta, native, binding = _recipe_definition_native(target, "read")
    result = _recipe_snapshot(native, binding)
    result.update({"readOnly": True, "mutatedProject": False, "status": "observed"})
    return result


TRACE_SETTINGS_FIELDS = {
    "autoSave": ("bAutoSave", "bool"),
    "autoSaveFileName": ("stAutoSaveFileName", "string"),
    "refreshDuration": ("nRefreshDuration", "positive_int"),
    "bufferPerVariable": ("uiBufferPerVariable", "uint"),
    "horizontalOrder": ("bHorizontalOrder", "bool"),
}
TRACE_RECORD_FIELDS = {
    "name": ("stRecordName", "required_string"),
    "taskName": ("stTaskName", "string"),
    "bufferEntries": ("uiBufferEntries", "uint"),
    "everyNCycles": ("uiEveryNCycles", "uint"),
    "triggerVariable": ("stTriggerVariable", "string"),
    "triggerLevel": ("stTriggerLevel", "string"),
    "triggerPosition": ("byTriggerPosition", "percentage"),
}
# Publicly promoted record fields (see trace.configure): the sampling/trigger
# geometry the trace page exposes and a readback can prove. Keep name and the
# trigger pair out until their semantics are verified end to end.
TRACE_PROMOTED_RECORD_FIELDS = (
    "taskName", "bufferEntries", "everyNCycles", "triggerPosition",
    "triggerVariable", "triggerLevel",
)


def _trace_trigger_level_verdict(type_display, level):
    """None when a trigger level literal matches the trigger type, else a verdict.

    The level is only promoted together with its trigger variable, and the type
    comes from the vendor's own precompiler (ITraceTypeHelper.GetIECExprInfo ->
    type.display, measured 2026-09-19: PLC_PRG.rOut resolves to REAL).
    """
    upper_type = _text(type_display).strip().upper()
    text = _text(level).strip()
    if not upper_type:
        return ("the trigger variable type could not be resolved",
                "trace_trigger_type_unresolved")
    if upper_type == "BOOL":
        if text.upper() in ("TRUE", "FALSE"):
            return None
        return ("a BOOL trigger level must be TRUE or FALSE",
                "trace_trigger_level_type_mismatch")
    if upper_type in ("SINT", "USINT", "INT", "UINT", "DINT", "UDINT", "LINT",
                      "ULINT", "BYTE", "WORD", "DWORD", "LWORD"):
        if re.match(r"^[+-]?[0-9]+$", text) or re.match(
                r"^(16#[0-9A-Fa-f]+|2#[01]+)$", text):
            return None
        return ("an integer trigger level must be a decimal, 16# or 2# literal",
                "trace_trigger_level_type_mismatch")
    if upper_type in ("REAL", "LREAL"):
        try:
            float(text)
            return None
        except Exception:
            return ("a REAL trigger level must be numeric",
                    "trace_trigger_level_type_mismatch")
    return ("this trigger type is not supported for a promoted trigger level",
            "trace_trigger_level_type_mismatch")
TRACE_VARIABLE_FIELDS = {
    "variableName": ("stVariableName", "required_string"),
    "graphName": ("stGraphName", "string"),
    "graphColor": ("nGraphColor", "int32"),
    "graphType": ("nGraphType", "nonnegative_int"),
    "visible": ("bVisible", "bool"),
}


def _trace_project_handle():
    core_project = _native_primary_project_for_current_path()
    handle = _get_member(core_project, "Handle", "get_Handle") if core_project is not None else None
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable", "project_handle_unavailable")
    try:
        return int(handle)
    except Exception:
        raise OperationError("project handle is not an integer", "project_handle_unavailable",
                             {"handle": _text(handle)})


def _trace_native_from_meta(meta):
    native = _get_member(meta, "Object", "get_Object") if meta is not None else None
    runtime_type = _text(_get_member(_get_member(native, "GetType"), "FullName"))
    if not runtime_type and native is not None:
        try:
            runtime_type = _text(native.GetType().FullName)
        except Exception:
            runtime_type = ""
    return native, runtime_type


def _native_trace_object(target, access="read"):
    """Resolve an exact TraceObject through the vendor ObjectMgr.

    ScriptEngine object wrappers are used only to resolve the requested tree
    path and GUID.  The configuration itself is always read from, or written
    through, the concrete Inovance TraceObject stored in ObjectMgr.
    """
    import System
    script_object, path = find_project_object(target)
    requested_guid = _object_guid(script_object)
    if not requested_guid:
        raise OperationError("trace tree object has no GUID", "trace_guid_unavailable",
                             {"target": target, "path": path})
    handle = _trace_project_handle()
    object_mgr, probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError("SystemInstances.ObjectMgr is unavailable",
                             "object_manager_unavailable", {"probe": probe})
    getter = object_mgr.GetObjectToModify if access == "modify" else object_mgr.GetObjectToRead
    candidates = []

    def inspect(guid):
        try:
            meta = getter(handle, System.Guid(_text(guid)))
            native, runtime_type = _trace_native_from_meta(meta)
            if runtime_type == TRACE_OBJECT_RUNTIME_TYPE:
                candidates.append((guid, meta, native, runtime_type))
        except Exception:
            pass

    inspect(requested_guid)
    access_fallback = None
    if not candidates and access == "modify":
        # MEASURED 2026-09-19 (Trace_PID): GetObjectToModify returned nothing for
        # the same GUID that GetObjectToRead resolved, so trace.configure answered
        # trace_object_unavailable (candidateCount=0, access=modify) while
        # trace.read on the identical target worked. Fall back to the read handle
        # - the write path still commits through ObjectMgr.SetObject and proves
        # the value by readback, so a shared read handle is safe here.
        getter = object_mgr.GetObjectToRead
        inspect(requested_guid)
        if candidates:
            access_fallback = "read_handle_with_setobject_commit"
    if not candidates:
        # Some ScriptEngine wrappers report a surrogate GUID.  Recover only a
        # unique same-name TraceObject, never a broad type-only match.
        wanted_name = _object_name(script_object).lower()
        try:
            for guid in list(object_mgr.GetAllObjects(handle)):
                stub = object_mgr.GetMetaObjectStub(handle, guid)
                if stub is None or _text(_get_member(stub, "Name", "get_Name")).lower() != wanted_name:
                    continue
                inspect(guid)
        except Exception as exc:
            raise OperationError("could not enumerate native TraceObjects", "trace_object_enumeration_failed",
                                 {"target": target, "path": path, "cause": repr(exc)})
    unique = {}
    for item in candidates:
        unique[_text(item[0])] = item
    candidates = list(unique.values())
    if len(candidates) != 1:
        raise OperationError(
            "target is not one unique Inovance TraceObject",
            "trace_object_unavailable",
            {"target": target, "path": path, "requestedGuid": requested_guid,
             "candidateCount": len(candidates), "access": access},
        )
    guid, meta, native, runtime_type = candidates[0]
    return object_mgr, meta, native, {
        "target": target,
        "path": path,
        "guid": requested_guid,
        "nativeGuid": _text(guid),
        "projectHandle": handle,
        "access": access,
        "accessFallback": access_fallback,
        "objectRuntimeType": runtime_type,
    }


def _trace_member(value, name):
    return _get_member(value, name, "get_" + name)


def _trace_list_item(values, index):
    try:
        return values[index]
    except Exception:
        getter = getattr(values, "get_Item", None)
        if not _is_callable(getter):
            raise
        return getter(index)


def _trace_snapshot(native, binding):
    settings = _trace_member(native, "TraceSettings")
    record = _trace_member(native, "Record")
    if settings is None or record is None:
        raise OperationError("TraceObject has no settings or record", "trace_model_unavailable",
                             {"binding": binding})
    setting_values = {}
    for public_name, (native_name, _kind) in TRACE_SETTINGS_FIELDS.items():
        value = _trace_member(settings, native_name)
        setting_values[public_name] = bool(value) if _kind == "bool" else (
            int(value) if _kind in ("positive_int", "uint") else _text(value)
        )
    record_values = {}
    for public_name, (native_name, kind) in TRACE_RECORD_FIELDS.items():
        value = _trace_member(record, native_name)
        record_values[public_name] = int(value) if kind in ("uint", "percentage") else _text(value)
    variables = []
    variable_list = _trace_member(record, "VariableList")
    count = int(_trace_member(variable_list, "Count") or 0) if variable_list is not None else 0
    for index in range(count):
        variable = _trace_list_item(variable_list, index)
        row = {
            "index": index,
            # TraceVariable owns this GUID; it is distinct from the Trace
            # object's MetaObject GUID and is required for add/readback proof.
            "guid": _text(_trace_member(variable, "guid")),
        }
        for public_name, (native_name, kind) in TRACE_VARIABLE_FIELDS.items():
            value = _trace_member(variable, native_name)
            if kind == "bool":
                row[public_name] = bool(value)
            elif kind in ("int32", "nonnegative_int"):
                row[public_name] = int(value)
            else:
                row[public_name] = _text(value)
        variables.append(row)
    return {
        "target": binding["target"],
        "path": binding["path"],
        "guid": binding["guid"],
        "nativeGuid": binding["nativeGuid"],
        "projectHandle": binding["projectHandle"],
        "objectRuntimeType": binding["objectRuntimeType"],
        "settings": setting_values,
        "record": record_values,
        "variables": variables,
        "variableCount": count,
        "mutatedProject": False,
        "status": "observed",
    }


def trace_read(req):
    target = _text(req.get("target") or req.get("trace") or req.get("path")).strip()
    if not target:
        raise OperationError("trace.read requires target", "invalid_argument", {"path": "target"})
    _object_mgr, _meta, native, binding = _native_trace_object(target, "read")
    return _trace_snapshot(native, binding)


def _trace_runtime_type_name(value):
    if value is None:
        return None
    try:
        return _text(value.GetType().FullName)
    except Exception:
        return _text(type(value))


def _trace_type_interface_match(value, interface_name):
    """Check one known CLR language-model interface without invoking it."""
    if value is None:
        return False, {"interface": interface_name, "available": False}
    interface_type = _reflection_type(interface_name)
    probe = {
        "interface": interface_name,
        "available": interface_type is not None,
        "valueRuntimeType": _trace_runtime_type_name(value),
    }
    if interface_type is None:
        return False, probe
    try:
        result = bool(interface_type.IsAssignableFrom(value.GetType()))
        probe["matched"] = result
        return result, probe
    except Exception as exc:
        probe["error"] = repr(exc)
        return False, probe


def _trace_expression_summary(native, expression):
    """Read the Trace vendor precompile verdict without changing its model."""
    attempts = []
    meta_object = _trace_member(native, "MetaObject")
    parent_guid = _trace_member(meta_object, "ParentObjectGuid") if meta_object is not None else None
    result = {
        "expression": expression,
        "binding": "TraceObject.GetTypeHelper().GetIECExprInfo(expression, MetaObject.ParentObjectGuid)",
        "metaObjectRuntimeType": _trace_runtime_type_name(meta_object),
        "parentApplicationGuid": _text(parent_guid) if parent_guid is not None else None,
        "attempts": attempts,
        "eligible": False,
        "status": "unavailable",
    }
    if meta_object is None or parent_guid is None:
        result.update({
            "errorCode": "trace_metaobject_unavailable",
            "error": "TraceObject MetaObject or ParentObjectGuid is unavailable",
        })
        return result
    type_helper = _trace_member(native, "GetTypeHelper")
    attempts.append({
        "binding": "TraceObject.GetTypeHelper",
        "available": type_helper is not None,
        "runtimeType": _trace_runtime_type_name(type_helper),
    })
    if type_helper is None:
        result.update({
            "errorCode": "trace_type_helper_unavailable",
            "error": "TraceObject.GetTypeHelper returned no vendor type helper",
        })
        return result
    getter = getattr(type_helper, "GetIECExprInfo", None)
    if not _is_callable(getter):
        result.update({
            "errorCode": "trace_expression_binding_unavailable",
            "error": "ITraceTypeHelper.GetIECExprInfo is unavailable",
        })
        return result
    try:
        expression_info = getter(expression, parent_guid)
        attempts.append({"binding": "ITraceTypeHelper.GetIECExprInfo", "called": True})
    except Exception as exc:
        attempts.append({"binding": "ITraceTypeHelper.GetIECExprInfo", "called": True,
                         "error": repr(exc)})
        result.update({
            "errorCode": "trace_expression_precompile_failed",
            "error": repr(exc),
        })
        return result
    if expression_info is None:
        result.update({
            "errorCode": "trace_expression_not_resolved",
            "error": "vendor precompile returned no expression information",
            "status": "ineligible",
        })
        return result
    expression_type = _trace_member(expression_info, "Type")
    variable = _trace_member(expression_info, "Var")
    is_bit_access = bool(_trace_member(expression_info, "IsBitAccess"))
    is_property = bool(_trace_member(expression_info, "IsProperty"))
    property_monitor = _text(_trace_member(expression_info, "PropertyMonitor"))
    pointer, pointer_probe = _trace_type_interface_match(
        expression_type, "_3S.CoDeSys.Core.LanguageModel.IPointerType, Core"
    )
    reference, reference_probe = _trace_type_interface_match(
        expression_type, "_3S.CoDeSys.Core.LanguageModel.IReferenceType, Core"
    )
    rejection_reasons = []
    if expression_type is None:
        rejection_reasons.append("type_unavailable")
    if variable is None:
        rejection_reasons.append("not_a_resolved_variable")
    if pointer:
        rejection_reasons.append("pointer_type")
    if reference:
        rejection_reasons.append("reference_type")
    if is_property and is_bit_access:
        rejection_reasons.append("property_bit_access")
    result.update({
        "status": "eligible" if not rejection_reasons else "ineligible",
        "eligible": not rejection_reasons,
        "expressionInfoRuntimeType": _trace_runtime_type_name(expression_info),
        "type": {
            "runtimeType": _trace_runtime_type_name(expression_type),
            "display": _text(expression_type) if expression_type is not None else None,
            "pointer": pointer,
            "reference": reference,
            "interfaceProbes": [pointer_probe, reference_probe],
        },
        "resolvedVariable": {
            "present": variable is not None,
            "runtimeType": _trace_runtime_type_name(variable),
            "name": _text(_trace_member(variable, "Name")) if variable is not None else None,
        },
        "isBitAccess": is_bit_access,
        "isProperty": is_property,
        "propertyMonitor": property_monitor,
        "rejectionReasons": rejection_reasons,
        "rule": "TraceObject v3.5.11 code generation requires a resolved variable and type, rejects pointer/reference types and property bit access",
    })
    return result


def trace_variable_probe(req):
    """Check one candidate Trace variable through the vendor precompiler.

    This operation intentionally gets only an ObjectMgr read metaobject. It
    does not create a TraceVariable, attach a diagram node, save the project,
    compile, or access the trace editor/online manager.
    """
    target = _text(req.get("target") or req.get("trace") or req.get("path")).strip()
    expression = req.get("expression")
    if not target:
        raise OperationError("trace.variable.probe requires target", "invalid_argument",
                             {"path": "target"})
    if not isinstance(expression, _STRING_TYPES):
        raise OperationError("trace.variable.probe requires string expression", "invalid_argument",
                             {"path": "expression", "expected": "string"})
    expression = _text(expression)
    if not expression.strip() or "\x00" in expression or len(expression) > 512:
        raise OperationError("trace expression is invalid", "invalid_argument",
                             {"path": "expression", "minimumLength": 1, "maximumLength": 512})
    _object_mgr, _meta, native, binding = _native_trace_object(target, "read")
    record = _trace_member(native, "Record")
    variable_list = _trace_member(record, "VariableList") if record is not None else None
    variable_count = int(_trace_member(variable_list, "Count") or 0) if variable_list is not None else None
    diagrams = _trace_member(record, "Diagrams") if record is not None else None
    diagram_count = int(_trace_member(diagrams, "Count") or 0) if diagrams is not None else None
    precompile = _trace_expression_summary(native, expression)
    return {
        "target": binding["target"],
        "path": binding["path"],
        "guid": binding["guid"],
        "nativeGuid": binding["nativeGuid"],
        "projectHandle": binding["projectHandle"],
        "objectRuntimeType": binding["objectRuntimeType"],
        "expression": precompile,
        "traceModel": {
            "recordRuntimeType": _trace_runtime_type_name(record),
            "variableCount": variable_count,
            "diagramRuntimeType": _trace_runtime_type_name(diagrams),
            "diagramCount": diagram_count,
        },
        "mutatedProject": False,
        "status": "observed",
        "limits": [
            "precompile eligibility is not a project write",
            "does not create a TraceVariable or diagram association",
            "does not save, compile, open an editor, or access an online trace manager",
        ],
    }


def trace_variable_add(req):
    """Add one eligible variable to a TraceObject through ObjectMgr.

    The variable route is intentionally narrower than the Trace editor: it
    stores one native TraceVariable in Record.VariableList and proves its
    vendor GUID, expression, and count through a fresh ObjectMgr readback.
    It does not construct a diagram, connect a curve, save, compile, or start
    online tracing.
    """
    target = _text(req.get("target") or req.get("trace") or req.get("path")).strip()
    expression = req.get("expression")
    if not target:
        raise OperationError("trace.variable.add requires target", "invalid_argument",
                             {"path": "target"})
    if not isinstance(expression, _STRING_TYPES):
        raise OperationError("trace.variable.add requires string expression", "invalid_argument",
                             {"path": "expression", "expected": "string"})
    expression = _text(expression)
    if not expression.strip() or "\x00" in expression or len(expression) > 512:
        raise OperationError("trace expression is invalid", "invalid_argument",
                             {"path": "expression", "minimumLength": 1, "maximumLength": 512})
    if req.get("confirm") != "add_trace_variable":
        raise OperationError("confirm must exactly equal add_trace_variable",
                             "confirmation_required")
    _require_current_disposable_project(req, "trace.variable.add")

    # Diagram construction is a separate native model with its own relation
    # collection. This tool must never silently create one as a side effect.
    if req.get("associateDiagram") is not None or req.get("diagramIndex") is not None:
        raise OperationError(
            "trace.variable.add does not support diagram creation or association",
            "trace_diagram_association_unavailable",
            {"target": target, "requestedFields": [key for key in
             ("associateDiagram", "diagramIndex") if req.get(key) is not None]},
        )

    probe = trace_variable_probe({"target": target, "expression": expression})
    eligibility = probe["expression"]
    if not eligibility.get("eligible"):
        raise OperationError(
            "Trace expression is not eligible for a trace variable",
            "trace_expression_ineligible",
            {"target": target, "expression": expression, "probe": probe},
        )
    model = probe["traceModel"]
    before_count = model.get("variableCount")
    if before_count is None:
        raise OperationError("TraceObject variable list is unavailable", "trace_model_unavailable",
                             {"target": target, "probe": probe})
    if any(row.get("variableName") == expression for row in
           trace_read({"target": target}).get("variables", [])):
        raise OperationError(
            "TraceObject already contains this variable expression",
            "trace_variable_already_exists",
            {"target": target, "expression": expression, "variableCount": before_count},
        )

    object_mgr, meta, native, binding = _native_trace_object(target, "modify")
    record = _trace_member(native, "Record")
    variable_list = _trace_member(record, "VariableList") if record is not None else None
    if variable_list is None:
        raise OperationError("TraceObject has no native VariableList", "trace_model_unavailable",
                             {"target": target, "binding": binding})
    try:
        variable = native.CreateTraceVariable()
    except Exception as exc:
        raise OperationError("TraceObject.CreateTraceVariable failed: " + repr(exc),
                             "trace_variable_create_failed", {"target": target})
    if variable is None:
        raise OperationError("TraceObject.CreateTraceVariable returned no variable",
                             "trace_variable_create_failed", {"target": target})
    variable_guid = _text(_trace_member(variable, "guid"))
    if not variable_guid:
        raise OperationError("new TraceVariable has no GUID", "trace_variable_guid_unavailable",
                             {"target": target})
    try:
        setattr(variable, "stVariableName", expression)
        set_expression = _text(_trace_member(variable, "stVariableName"))
        if set_expression != expression:
            raise OperationError(
                "TraceVariable rejected the requested expression",
                "trace_variable_expression_not_retained",
                {"target": target, "requested": expression, "afterSet": set_expression},
            )
        variable_list.Add(variable)
        count_after_add = int(_trace_member(variable_list, "Count") or 0)
    except OperationError:
        raise
    except Exception as exc:
        raise OperationError("could not append TraceVariable: " + repr(exc),
                             "trace_variable_append_failed",
                             {"target": target, "expression": expression,
                              "variableGuid": variable_guid})
    if count_after_add != before_count + 1:
        raise OperationError(
            "TraceObject VariableList count did not increase before commit",
            "trace_variable_append_not_retained",
            {"target": target, "beforeCount": before_count,
             "afterAddCount": count_after_add, "variableGuid": variable_guid},
        )
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed: " + repr(exc), "trace_variable_commit_failed",
                             {"target": target, "expression": expression,
                              "variableGuid": variable_guid, "beforeCount": before_count})

    _read_mgr, _read_meta, rebound_native, rebound_binding = _native_trace_object(target, "read")
    after = _trace_snapshot(rebound_native, rebound_binding)
    matching = [row for row in after["variables"] if row.get("guid") == variable_guid]
    expected_count = before_count + 1
    mismatch = (after["variableCount"] != expected_count or len(matching) != 1 or
                (matching and matching[0].get("variableName") != expression))
    if mismatch:
        raise OperationError(
            "TraceVariable commit did not retain GUID, expression, and count",
            "trace_variable_not_retained",
            {"target": target, "beforeCount": before_count, "expectedCount": expected_count,
             "after": after, "variableGuid": variable_guid, "expression": expression,
             "matchingVariableCount": len(matching),
             "commitReturn": _json_safe(commit_return)},
        )
    diagram_count = model.get("diagramCount")
    return {
        "input": {"target": target, "expression": expression},
        "target": target,
        "binding": rebound_binding,
        "probe": probe,
        "beforeVariableCount": before_count,
        "afterVariableCount": after["variableCount"],
        "variable": matching[0],
        "commitReturn": _json_safe(commit_return),
        "diagramAssociation": {
            "requested": False,
            "diagramCount": diagram_count,
            "status": "unavailable_no_diagram" if diagram_count == 0 else "not_requested",
            "reason": "diagram creation and association are intentionally outside trace.variable.add",
        },
        "mutatedProject": True,
        "committed": True,
        "exactVariableReadback": True,
        "countReadback": True,
        "status": "committed_same_process_requires_save_reopen_compile_gate",
        "limits": [
            "does not create a Trace diagram or associate a curve variable",
            "does not save, compile, open the Trace editor, or start online tracing",
            "fresh-process persistence and offline compile are separate promotion gates",
        ],
    }


def _trace_validate_value(kind, value, path):
    if kind == "bool":
        if not isinstance(value, bool):
            raise OperationError("trace value must be boolean", "invalid_argument",
                                 {"path": path, "expected": "boolean"})
        return bool(value)
    if kind in ("string", "required_string"):
        if not isinstance(value, _STRING_TYPES):
            raise OperationError("trace value must be a string", "invalid_argument",
                                 {"path": path, "expected": "string"})
        text = _text(value)
        if "\x00" in text or len(text) > 512 or (kind == "required_string" and not text.strip()):
            raise OperationError("trace string value is invalid", "invalid_argument",
                                 {"path": path, "maximumLength": 512,
                                  "emptyAllowed": kind != "required_string"})
        return text
    if isinstance(value, bool) or not isinstance(value, _INTEGER_TYPES):
        raise OperationError("trace value must be an integer", "invalid_argument",
                             {"path": path, "expected": "integer"})
    value = int(value)
    if kind == "uint" and not (1 <= value <= 4294967295):
        raise OperationError("trace unsigned value is out of range", "invalid_argument",
                             {"path": path, "minimum": 1, "maximum": 4294967295})
    if kind == "positive_int" and not (1 <= value <= 3600000):
        raise OperationError("trace refresh duration is out of range", "invalid_argument",
                             {"path": path, "minimum": 1, "maximum": 3600000})
    if kind == "percentage" and not (0 <= value <= 100):
        raise OperationError("trace trigger position is out of range", "invalid_argument",
                             {"path": path, "minimum": 0, "maximum": 100})
    if kind == "int32" and not (-2147483648 <= value <= 2147483647):
        raise OperationError("trace graph color is out of range", "invalid_argument",
                             {"path": path, "minimum": -2147483648, "maximum": 2147483647})
    if kind == "nonnegative_int" and not (0 <= value <= 2147483647):
        raise OperationError("trace graph type is out of range", "invalid_argument",
                             {"path": path, "minimum": 0, "maximum": 2147483647})
    return value


def _trace_apply_fields(instance, supplied, allowed, path_prefix):
    if supplied is None:
        return []
    if not isinstance(supplied, dict):
        raise OperationError("trace field group must be an object", "invalid_argument",
                             {"path": path_prefix, "expected": "object"})
    unknown = sorted(set(supplied.keys()) - set(allowed.keys()))
    if unknown:
        raise OperationError("trace configuration contains unsupported fields", "invalid_argument",
                             {"path": path_prefix, "unsupported": unknown,
                              "supported": sorted(allowed.keys())})
    changes = []
    for public_name in sorted(supplied.keys()):
        native_name, kind = allowed[public_name]
        requested = _trace_validate_value(kind, supplied[public_name], path_prefix + "." + public_name)
        before = _trace_member(instance, native_name)
        setattr(instance, native_name, requested)
        after = _trace_member(instance, native_name)
        changes.append({"path": path_prefix + "." + public_name,
                        "before": _json_safe(before), "requested": requested,
                        "afterSet": _json_safe(after)})
    return changes


def trace_configure(req):
    target = _text(req.get("target") or req.get("trace") or req.get("path")).strip()
    if not target:
        raise OperationError("trace.configure requires target", "invalid_argument", {"path": "target"})
    if req.get("confirm") != "configure_trace":
        raise OperationError("confirm must exactly equal configure_trace", "confirmation_required")
    _require_current_disposable_project(req, "trace.configure")
    # Field scope. settings stays limited to the promoted refreshDuration; the
    # record group is promoted for the fields the trace page exposes and a
    # readback can prove (measured 2026-09-19 on Trace_PID: name, taskName,
    # bufferEntries, everyNCycles, triggerVariable, triggerLevel,
    # triggerPosition are all readable). name/triggerVariable/triggerLevel stay
    # out of the public whitelist: a rename is not a recording setting and a
    # trigger level must match the trigger variable's IEC type, which this call
    # cannot validate.
    if req.get("variables") is not None:
        raise OperationError(
            "public trace.configure does not write curve variables",
            "trace_scope_not_promoted",
            {"supported": {"settings": ["refreshDuration"],
                           "record": list(TRACE_PROMOTED_RECORD_FIELDS)},
             "nextRequired": {"tool": "codesys_trace_variable_add",
                              "then": "add or validate one curve variable per call"},
             "mutatedProject": False},
        )
    supplied_record = req.get("record")
    if supplied_record is not None:
        if not isinstance(supplied_record, dict) or not supplied_record:
            raise OperationError("record must be a non-empty object", "invalid_argument",
                                 {"path": "record",
                                  "supported": list(TRACE_PROMOTED_RECORD_FIELDS)})
        blocked = sorted(set(supplied_record) - set(TRACE_PROMOTED_RECORD_FIELDS))
        if blocked:
            raise OperationError(
                "record contains fields outside the promoted whitelist",
                "trace_scope_not_promoted",
                {"unsupported": blocked,
                 "supported": list(TRACE_PROMOTED_RECORD_FIELDS),
                 "notPromoted": sorted(set(TRACE_RECORD_FIELDS) -
                                       set(TRACE_PROMOTED_RECORD_FIELDS)),
                 "mutatedProject": False})
    supplied_settings = req.get("settings")
    if supplied_settings is not None:
        if (not isinstance(supplied_settings, dict)
                or set(supplied_settings) != {"refreshDuration"}):
            raise OperationError(
                "settings is limited to refreshDuration",
                "trace_scope_not_promoted",
                {"supported": {"settings": ["refreshDuration"]},
                 "actualSettings": sorted(supplied_settings)
                                   if isinstance(supplied_settings, dict) else None,
                 "mutatedProject": False},
            )
    if supplied_settings is None and supplied_record is None:
        raise OperationError(
            "trace.configure needs settings and/or record",
            "invalid_argument",
            {"supported": {"settings": ["refreshDuration"],
                           "record": list(TRACE_PROMOTED_RECORD_FIELDS)}})
    object_mgr, meta, native, binding = _native_trace_object(target, "modify")
    before = _trace_snapshot(native, binding)
    settings = _trace_member(native, "TraceSettings")
    record = _trace_member(native, "Record")
    if supplied_record is not None and (
            "triggerVariable" in supplied_record or "triggerLevel" in supplied_record):
        trigger_variable = _text(supplied_record.get("triggerVariable") or "").strip()
        trigger_level = _text(supplied_record.get("triggerLevel") or "").strip()
        if not trigger_variable or not trigger_level:
            raise OperationError(
                "triggerVariable and triggerLevel must be supplied together and be non-empty",
                "invalid_argument",
                {"path": "record.triggerVariable/triggerLevel",
                 "triggerVariable": trigger_variable or None,
                 "triggerLevel": trigger_level or None,
                 "mutatedProject": False})
        expression_summary = _trace_expression_summary(native, trigger_variable)
        if not expression_summary.get("eligible"):
            raise OperationError(
                "the trigger variable is not eligible for trace recording",
                "trace_trigger_variable_ineligible",
                {"triggerVariable": trigger_variable,
                 "rejectionReasons": expression_summary.get("rejectionReasons"),
                 "status": expression_summary.get("status"),
                 "mutatedProject": False})
        type_display = _text((expression_summary.get("type") or {}).get("display"))
        verdict = _trace_trigger_level_verdict(type_display, trigger_level)
        if verdict is not None:
            raise OperationError(
                verdict[0], verdict[1],
                {"triggerVariable": trigger_variable,
                 "observedType": type_display or None,
                 "triggerLevel": trigger_level,
                 "allowed": {"BOOL": "TRUE|FALSE",
                             "integer": "decimal | 16#hex | 2#binary",
                             "REAL/LREAL": "numeric"},
                 "mutatedProject": False})
    changes = _trace_apply_fields(settings, supplied_settings, TRACE_SETTINGS_FIELDS, "settings")
    changes.extend(_trace_apply_fields(record, supplied_record, TRACE_RECORD_FIELDS, "record"))
    variable_updates = req.get("variables")
    if variable_updates is not None:
        if not isinstance(variable_updates, list) or not variable_updates:
            raise OperationError("variables must be a non-empty array", "invalid_argument",
                                 {"path": "variables"})
        variable_list = _trace_member(record, "VariableList")
        variable_count = int(_trace_member(variable_list, "Count") or 0)
        for update_index, update in enumerate(variable_updates):
            path_prefix = "variables[%d]" % update_index
            if not isinstance(update, dict) or "index" not in update:
                raise OperationError("each variable update requires index", "invalid_argument",
                                     {"path": path_prefix})
            index = _trace_validate_value("nonnegative_int", update["index"], path_prefix + ".index")
            if index >= variable_count:
                raise OperationError("trace variable index is out of range", "invalid_argument",
                                     {"path": path_prefix + ".index", "index": index,
                                      "variableCount": variable_count})
            variable_fields = dict(update)
            del variable_fields["index"]
            if not variable_fields:
                raise OperationError("trace variable update has no fields", "invalid_argument",
                                     {"path": path_prefix})
            changes.extend(_trace_apply_fields(
                _trace_list_item(variable_list, index), variable_fields,
                TRACE_VARIABLE_FIELDS, path_prefix,
            ))
    if not changes:
        raise OperationError("trace.configure has no fields to change", "invalid_argument")
    try:
        commit_return = object_mgr.SetObject(meta, True, None)
    except Exception as exc:
        raise OperationError("ObjectMgr.SetObject failed: " + repr(exc), "trace_commit_failed",
                             {"target": target, "before": before, "changes": changes})
    _read_mgr, _read_meta, rebound_native, rebound_binding = _native_trace_object(target, "read")
    after = _trace_snapshot(rebound_native, rebound_binding)
    mismatches = []
    for change in changes:
        parts = change["path"].replace("]", "").replace("[", ".").split(".")
        current = after
        try:
            for part in parts:
                current = current[int(part)] if part.isdigit() else current[part]
        except Exception:
            current = None
        if current != change["requested"]:
            mismatches.append({"path": change["path"], "requested": change["requested"],
                               "readback": current})
    if mismatches:
        raise OperationError("TraceObject commit did not retain every requested value",
                             "trace_configuration_not_retained",
                             {"target": target, "before": before, "after": after,
                              "changes": changes, "mismatches": mismatches,
                              "commitReturn": _json_safe(commit_return)})
    readback_settings = dict(
        (name, after["settings"].get(name))
        for name in sorted((supplied_settings or {}).keys()))
    return {
        "input": {"target": target,
                  "settings": dict(supplied_settings) if supplied_settings else None,
                  "record": dict(supplied_record) if supplied_record else None},
        "target": target,
        "before": before,
        "after": after,
        "readbackSettings": readback_settings,
        "changes": changes,
        "commitReturn": _json_safe(commit_return),
        "binding": rebound_binding,
        "mutatedProject": True,
        "committed": True,
        "exactReadback": True,
        "status": "committed_same_process_requires_save_reopen_gate",
        "limits": [
            "does not create or delete trace variables",
            "does not start online trace recording",
            "project.save, fresh-process reopen, compilation, and UI evidence are separate gates",
        ],
    }


def ui_navigator_refresh(req):
    """Refill already-open native navigator views for the current project.

    Some vendor object factories add valid project objects without publishing
    the StructuredView NodeAdded notification used for incremental tree
    rendering. NavigatorControl exposes Refill() as its native model rebuild
    route. This invokes that public method only on existing navigator views;
    it does not click controls, save, or mutate the project.
    """
    _require_project()
    if not bool(getattr(system, "ui_present", False)):
        raise OperationError(
            "navigator refresh requires an interactive InoProShop UI host",
            "ui_not_available",
            {"projectPath": _project_path(), "mutatedProject": False},
        )

    core_project = _native_primary_project_for_current_path()
    if core_project is None:
        raise OperationError(
            "the ScriptEngine project has no matching Core primary project",
            "core_project_unavailable",
            {"projectPath": _project_path(), "mutatedProject": False},
        )
    try:
        project_handle = int(_get_member(core_project, "Handle", "get_Handle"))
    except Exception:
        raise OperationError(
            "the Core project has no usable handle",
            "project_handle_unavailable",
            {"projectPath": _project_path(), "mutatedProject": False},
        )

    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    engine_property = (system_instances.GetProperty("Engine")
                       if system_instances is not None else None)
    engine = (engine_property.GetValue(None, None)
              if engine_property is not None else None)
    frame = _get_member(engine, "Frame", "get_Frame")
    if frame is None:
        raise OperationError(
            "the InoProShop frame is unavailable",
            "navigator_frame_unavailable",
            {"projectPath": _project_path(), "mutatedProject": False},
        )
    try:
        views = list(frame.GetViews())
    except Exception as exc:
        raise OperationError(
            "could not enumerate native IDE views",
            "navigator_view_enumeration_failed",
            {"projectPath": _project_path(), "cause": repr(exc),
             "mutatedProject": False},
        )

    import System
    flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
    examined = []
    refreshed = []
    for view in views:
        try:
            runtime_type = view.GetType()
            type_name = _text(runtime_type.FullName)
            refill = runtime_type.GetMethod("Refill", flags)
            view_handle = _get_member(view, "ProjectHandle", "get_ProjectHandle")
            structured_view = _get_member(view, "StructuredViewGuid", "get_StructuredViewGuid")
            candidate = "navigatorcontrol" in type_name.lower() and refill is not None
            entry = {
                "runtimeType": type_name,
                "projectHandle": int(view_handle) if view_handle is not None else None,
                "structuredViewGuid": _text(structured_view) if structured_view is not None else None,
                "navigatorCandidate": candidate,
            }
            examined.append(entry)
            if not candidate or view_handle is None or int(view_handle) != project_handle:
                continue
            refill.Invoke(view, System.Array[System.Object]([]))
            refreshed.append({
                "runtimeType": type_name,
                "projectHandle": int(view_handle),
                "structuredViewGuid": _text(structured_view),
                "binding": "_3S.CoDeSys.NavigatorControl.NavigatorControl.Refill()",
                "refreshed": True,
            })
        except Exception as exc:
            examined.append({
                "runtimeType": _text(view.GetType().FullName),
                "refreshError": repr(exc),
            })

    if not refreshed:
        raise OperationError(
            "no open navigator view matched the current project",
            "navigator_view_unavailable",
            {"projectPath": _project_path(), "projectHandle": project_handle,
             "examinedViews": examined, "mutatedProject": False,
             "next": "open the InoProShop project navigator and retry"},
        )
    return {
        "projectPath": _project_path(),
        "projectHandle": project_handle,
        "refreshedCount": len(refreshed),
        "refreshedViews": refreshed,
        "examinedViews": examined,
        "binding": "NavigatorControl.Refill",
        "uiAction": "native_navigator_model_refill",
        "mutatedProject": False,
        "limits": [
            "A successful refill only proves that the native refresh request completed.",
            "Object-family promotion still requires UI visibility, save/reopen, and compile evidence.",
        ],
    }


def ui_navigator_reveal(req):
    """Reveal and select one existing object in an open native navigator.

    This is deliberately a UI-session operation.  The StructuredView and
    NavigatorControl APIs are used only to resolve the already-published
    node, expand its in-memory parents, and set the native selection.  No
    ObjectMgr mutation, project save, or tree repair is performed here.
    """
    _require_project()
    if not bool(getattr(system, "ui_present", False)):
        raise OperationError(
            "navigator reveal requires an interactive InoProShop UI host",
            "ui_not_available",
            {"projectPath": _project_path(), "mutatedProject": False},
        )
    target_text = _text((req or {}).get("guid") or (req or {}).get("target") or "").strip()
    if not target_text:
        raise OperationError(
            "navigator reveal requires target guid",
            "invalid_argument",
            {"mutatedProject": False},
        )
    import System
    try:
        target_guid = System.Guid(target_text)
    except Exception:
        raise OperationError(
            "navigator reveal target must be a valid object GUID",
            "invalid_argument",
            {"target": target_text, "mutatedProject": False},
        )

    core_project = _native_primary_project_for_current_path()
    if core_project is None:
        raise OperationError(
            "the ScriptEngine project has no matching Core primary project",
            "core_project_unavailable",
            {"projectPath": _project_path(), "mutatedProject": False},
        )
    try:
        project_handle = int(_get_member(core_project, "Handle", "get_Handle"))
    except Exception:
        raise OperationError(
            "the Core project has no usable handle",
            "project_handle_unavailable",
            {"projectPath": _project_path(), "mutatedProject": False},
        )

    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    engine_property = (system_instances.GetProperty("Engine")
                       if system_instances is not None else None)
    engine = (engine_property.GetValue(None, None)
              if engine_property is not None else None)
    frame = _get_member(engine, "Frame", "get_Frame")
    if frame is None:
        raise OperationError(
            "the InoProShop frame is unavailable",
            "navigator_frame_unavailable",
            {"projectPath": _project_path(), "mutatedProject": False},
        )
    object_mgr, manager_binding = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError(
            "SystemInstances.ObjectMgr is unavailable",
            "object_manager_unavailable",
            {"binding": manager_binding, "mutatedProject": False},
        )

    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public)
    model_flags = (flags | System.Reflection.BindingFlags.NonPublic)

    def method_named(runtime_type, name, parameter_count=None):
        """Resolve one native overload without GetMethod ambiguity."""
        if runtime_type is None:
            return None
        matches = []
        for method in runtime_type.GetMethods(model_flags):
            if _text(method.Name) != name:
                continue
            if (parameter_count is not None and
                    len(method.GetParameters()) != parameter_count):
                continue
            matches.append(method)
        return matches[0] if matches else None

    try:
        views = list(frame.GetViews())
    except Exception as exc:
        raise OperationError(
            "could not enumerate native IDE views",
            "navigator_view_enumeration_failed",
            {"cause": repr(exc), "mutatedProject": False},
        )

    examined = []
    for view in views:
        try:
            runtime_type = view.GetType()
            type_name = _text(runtime_type.FullName)
            refill = method_named(runtime_type, "Refill", 0)
            view_handle = _get_member(view, "ProjectHandle", "get_ProjectHandle")
            structured_guid = _get_member(view, "StructuredViewGuid",
                                           "get_StructuredViewGuid")
            entry = {
                "runtimeType": type_name,
                "projectHandle": int(view_handle) if view_handle is not None else None,
                "structuredViewGuid": _text(structured_guid)
                if structured_guid is not None else None,
                "navigatorCandidate": "navigatorcontrol" in type_name.lower()
                and refill is not None,
            }
            examined.append(entry)
            if (not entry["navigatorCandidate"] or view_handle is None or
                    int(view_handle) != project_handle or structured_guid is None):
                continue

            # Rebuild only this existing navigator's model before resolving
            # the target.  Refill is a native UI model operation, not a write.
            refill.Invoke(view, System.Array[System.Object]([]))
            structured = object_mgr.GetStructuredView(
                project_handle, System.Guid(_text(structured_guid)))
            if structured is None:
                entry["revealStatus"] = "structured_view_unavailable"
                continue
            target_node = structured.GetNode(target_guid)
            if target_node is None:
                entry["revealStatus"] = "target_not_in_structured_view"
                continue

            # StructuredView.GetNode returns a valid native node, but the
            # navigator selection setter resolves through its own private
            # TreeTableModel.  Use that model's IProjectModelNode.SVNode so
            # SelectedSVNodes addresses the exact in-memory view node.
            selection_node = target_node
            model_field = runtime_type.GetField("_model", model_flags)
            navigator_model = (model_field.GetValue(view)
                               if model_field is not None else None)
            get_pm_node = (method_named(navigator_model.GetType(), "GetPMNode", 1)
                           if navigator_model is not None else None)
            project_model_node = (get_pm_node.Invoke(
                navigator_model, System.Array[System.Object]([target_guid]))
                if get_pm_node is not None else None)
            if project_model_node is None:
                entry["revealStatus"] = "target_not_in_navigator_model"
                continue
            model_svn = _get_member(project_model_node, "SVNode", "get_SVNode")
            if model_svn is None:
                entry["revealStatus"] = "navigator_model_svnnode_unavailable"
                continue
            selection_node = model_svn

            parent_guids = []
            parent = _get_member(selection_node, "Parent", "get_Parent")
            while parent is not None:
                parent_guid = _get_member(parent, "ObjectGuid", "get_ObjectGuid")
                if parent_guid is None:
                    break
                parent_guid = System.Guid(_text(parent_guid))
                parent_guids.append(parent_guid)
                parent = _get_member(parent, "Parent", "get_Parent")
            parent_guids.reverse()
            expanded = []
            for parent_guid in parent_guids:
                expand = method_named(runtime_type, "Expand", 1)
                if expand is not None:
                    expand.Invoke(view, System.Array[System.Object]([parent_guid]))
                expanded.append({"guid": _text(parent_guid), "expanded": True})

            selected_property = runtime_type.GetProperty("SelectedSVNodes", flags)
            if selected_property is None:
                entry["revealStatus"] = "selection_property_unavailable"
                continue
            element_type = selected_property.PropertyType.GetElementType()
            selected_array = System.Array.CreateInstance(element_type, 1)
            selected_array[0] = selection_node
            selected_property.SetValue(view, selected_array, None)

            # SelectedSVNodes marks the row but does not reliably scroll a
            # long vendor tree into the viewport.  Invoke the same native
            # TreeTableViewNode methods used by NavigatorControl's own
            # selection restore path so the screenshot can prove actual row
            # visibility, not merely selection state.
            tree_field = runtime_type.GetField("_treeTableView", model_flags)
            tree = tree_field.GetValue(view) if tree_field is not None else None
            object_node_method = (method_named(navigator_model.GetType(),
                                               "GetObjectNode", 1)
                if navigator_model is not None else None)
            object_node = (object_node_method.Invoke(
                navigator_model, System.Array[System.Object]([target_guid]))
                if object_node_method is not None else None)
            view_node_method = (method_named(tree.GetType(), "GetViewNode", 1)
                                if tree is not None else None)
            view_node = (view_node_method.Invoke(
                tree, System.Array[System.Object]([object_node]))
                if view_node_method is not None and object_node is not None else None)
            if view_node is None:
                entry["revealStatus"] = "navigator_view_node_unavailable"
                continue
            ensure_visible = method_named(view_node.GetType(), "EnsureVisible", 1)
            focus_node = method_named(view_node.GetType(), "Focus", 1)
            if ensure_visible is None or focus_node is None:
                entry["revealStatus"] = "navigator_visibility_binding_unavailable"
                continue
            ensure_visible.Invoke(view_node, System.Array[System.Object]([0]))
            focus_node.Invoke(view_node, System.Array[System.Object]([0]))
            control = _get_member(view, "Control", "get_Control")
            control_focus = (method_named(control.GetType(), "Focus", 0)
                             if control is not None else None)
            if control_focus is not None:
                control_focus.Invoke(control, System.Array[System.Object]([]))
            entry["treeVisibility"] = {
                "ensureVisibleInvoked": True,
                "focusInvoked": True,
                "viewNodeRuntimeType": _text(view_node.GetType().FullName),
                "binding": "NavigatorControl._treeTableView.GetViewNode(ObjectNode).EnsureVisible(0)",
            }

            selected_nodes = _get_member(view, "SelectedSVNodes", "get_SelectedSVNodes")
            selected_guids = []
            if selected_nodes is not None:
                for selected_node in list(selected_nodes):
                    selected_guid = _get_member(selected_node, "ObjectGuid",
                                                "get_ObjectGuid")
                    if selected_guid is not None:
                        selected_guids.append(_text(selected_guid))
            target_guid_text = _text(target_guid)
            if target_guid_text.lower() not in [item.lower() for item in selected_guids]:
                entry.update({"revealStatus": "selection_not_retained",
                              "selectedGuids": selected_guids})
                continue
            entry.update({
                "revealStatus": "selected",
                "targetGuid": target_guid_text,
                "parentGuids": [_text(item) for item in parent_guids],
                "expandedParents": expanded,
                "selectedGuids": selected_guids,
                "binding": "NavigatorControl.Refill + Expand(Guid) + SelectedSVNodes",
            })
            return {
                "projectPath": _project_path(),
                "projectHandle": project_handle,
                "targetGuid": target_guid_text,
                "view": entry,
                "examinedViews": examined,
                "uiAction": "native_navigator_reveal_select",
                "mutatedProject": False,
                "sessionOnly": True,
                "limits": [
                    "selection and expansion are UI-session state only",
                    "does not create, delete, move, or rename project objects",
                    "does not save the project or click native dialogs",
                ],
            }
        except OperationError:
            raise
        except Exception as exc:
            examined.append({
                "runtimeType": _text(view.GetType().FullName),
                "revealError": repr(exc),
            })

    raise OperationError(
        "no open navigator view contained the target object",
        "navigator_target_unavailable",
        {"projectPath": _project_path(), "projectHandle": project_handle,
         "targetGuid": _text(target_guid), "examinedViews": examined,
         "mutatedProject": False,
         "next": "run ui.navigator.refresh and retry after confirming the object is in the current project"},
    )


def device_config_io_channels_probe(req):
    """Read the vendor hardware module and its channel/parameter bindings.

    This deliberately stays below the ScriptEngine display tree.  It observes
    the native HdConfigProject module and its associated DevObject, but never
    assigns a parameter or mapping.
    """
    _require_project()
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", {"binding": binding})
    sync_project = factory.CreateConfigSyncProj()

    sync_project.StartSyncToConfigrationDataObject()
    hardware = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
    if hardware is None:
        try:
            import System
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject" and len(m.GetParameters()) == 2]
            if methods:
                args = System.Array[System.Object]([None, None])
                methods[0].Invoke(sync_project, args)
                hardware = args[0]
        except Exception:
            hardware = None
    if hardware is None:
        raise OperationError("vendor hardware configuration object is unavailable",
                             "hardware_configuration_unavailable", {"binding": binding})

    def shape(value, tokens=()):
        if value is None:
            return None
        result = {"runtimeType": _text(value.GetType().FullName)}
        try:
            typ = value.GetType()
            names = []
            for prop in typ.GetProperties():
                name = _text(prop.Name)
                if not tokens or any(token in name.lower() for token in tokens):
                    names.append(name)
            result["properties"] = sorted(set(names))
            methods = []
            for method in typ.GetMethods():
                name = _text(method.Name)
                if not tokens or any(token in name.lower() for token in tokens):
                    methods.append(_text(method.ToString()))
            result["methods"] = sorted(set(methods))[:300]
        except Exception as exc:
            result["reflectionError"] = repr(exc)
        return result

    bus_value = int(req.get("bus", 10))
    port = int(req.get("port", 0))
    rack = int(req.get("rack", 1))
    # ``slot`` was accepted by the public schema but silently ignored by the
    # original probe, so a request for one module returned every module on the
    # bus.  Keep None distinct from slot 0: callers that omit it still get the
    # bounded DATAMODULE inventory, while an explicit slot is exact.
    slot_value = req.get("slot")
    try:
        slot = int(slot_value) if slot_value is not None else None
    except (TypeError, ValueError):
        raise OperationError("slot must be an integer", "invalid_argument",
                             {"path": "slot", "actual": slot_value})
    module_name = _text(req.get("module") or "").strip()
    try:
        import System
        bus_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
        bus = System.Enum.ToObject(bus_type, bus_value)
    except Exception as exc:
        raise OperationError("invalid vendor bus enum: " + repr(exc), "invalid_argument")

    try:
        devices = list(hardware.GetDeviceList(0, bus, port))
    except Exception as exc:
        raise OperationError("vendor device list read failed: " + repr(exc),
                             "hardware_graph_read_failed")

    # The raw GetDeviceList rows do not expose model names through the member
    # accessors this probe can see (round-14 evidence: 4 rows, all model/
    # devType empty), while device.config.graph.probe's row shaping provably
    # returns model=14400005 + exact identification. Delegate row IDENTITY to
    # the graph probe and correlate DevObjects back by rack/slot/port.
    graph = device_config_graph_probe({})
    graph_devices = graph.get("devices", [])
    def _filter_key(value):
        # Device tree captions often contain localized suffixes and spacing;
        # IDs use a space between vendor/product words.  Comparing this
        # compact key in addition to the raw spelling lets one probe accept a
        # catalog model, an exact ID, or the visible tree caption without
        # guessing a different device.
        return re.sub(r"[^a-z0-9]+", "", _text(value).lower())

    wanted_ids = []
    tree_devices = device_tree().get("devices", [])
    module_key = _filter_key(module_name)
    if module_name:
        for item in tree_devices:
            device_id = item.get("deviceId") or {}
            candidates = (
                item.get("name"), item.get("path"),
                device_id.get("id"), device_id.get("type"),
                device_id.get("version"),
            )
            candidate_keys = [_filter_key(value) for value in candidates]
            if module_key and any(
                    module_key == key or module_key in key or key in module_key
                    for key in candidate_keys if key):
                ident_id = _text(device_id.get("id")).strip().lower()
                if ident_id:
                    wanted_ids.append(ident_id)
    selected_rows = []
    for row in graph_devices:
        ident = row.get("identification") or {}
        ident_id = _text(ident.get("id", "")).lower()
        model = _text(row.get("model", "")).lower()
        row_slot = row.get("slot")
        row_rack = row.get("rack")
        row_port = row.get("port")
        location_match = (
            (row_rack in (None, rack) or _text(row_rack) == _text(rack)) and
            (row_port in (None, port) or _text(row_port) == _text(port)) and
            (slot is None or row_slot in (slot, None) or
             _text(row_slot) == _text(slot))
        )
        if not location_match:
            continue
        if module_name:
            row_keys = {_filter_key(model), _filter_key(ident_id),
                        _filter_key(row.get("devType"))}
            match = (module_key in row_keys or
                     any(module_key and (module_key in key or key in module_key)
                         for key in row_keys if key) or
                     ident_id in wanted_ids)
        else:
            match = "datamodule" in _text(row.get("devType", "")).lower()
        if match:
            selected_rows.append(row)
    by_location = {}
    for item in devices:
        loc = (_json_safe(_get_member(item, "rackno", "get_RACKNO")),
               _json_safe(_get_member(item, "slotno", "get_SLOTNO")),
               _json_safe(_get_member(item, "portno", "get_PortNo")))
        by_location.setdefault(str(loc), item)

    modules = []
    for row in selected_rows:
        loc = str((row.get("rack"), row.get("slot"), row.get("port")))
        item = by_location.get(loc)
        entry = {
            "runtimeType": row.get("runtimeType"),
            "devType": row.get("devType"),
            "model": row.get("model"),
            "slot": row.get("slot"),
            "rack": row.get("rack"),
            "port": row.get("port"),
            "identification": row.get("identification"),
            "source": row.get("source"),
        }
        if item is not None:
            entry["reflection"] = shape(item, ("io", "channel", "address", "mapping", "parameter", "device", "slot", "ident"))
            dev_object = _get_member(item, "dev_object", "get_DevObject")
            if dev_object is None:
                dev_object = _get_member(item, "device_object", "get_DeviceObject")
            entry["devObject"] = shape(dev_object, ("io", "channel", "address", "mapping", "parameter", "connector", "device"))
            if dev_object is not None:
                parameter_set = None
                for name, getter in (("device_parameters", "get_device_parameters"),
                                     ("device_parameter_set", "get_device_parameter_set"),
                                     ("parameter_set", "get_parameter_set"),
                                     ("parameters", "get_parameters")):
                    try:
                        candidate = _get_member(dev_object, name, getter)
                        if candidate is not None:
                            parameter_set = candidate
                            entry.setdefault("parameterBindings", []).append({"name": name, "available": True})
                            break
                        entry.setdefault("parameterBindings", []).append({"name": name, "available": False})
                    except Exception as exc:
                        entry.setdefault("parameterBindings", []).append({"name": name, "available": False, "error": repr(exc)})
                if parameter_set is not None:
                    try:
                        values = list(parameter_set)
                        entry["parameterCount"] = len(values)
                        entry["parameters"] = [_parameter_summary(value) for value in values[:500]]
                    except Exception as exc:
                        entry["parameterEnumerationError"] = repr(exc)
        else:
            entry["devObjectUnavailable"] = True
            entry["hint"] = ("config graph row matched but no raw "
                             "GetDeviceList item shared its rack/slot/port; "
                             "use vendor_device_parameter_probe for channel "
                             "parameter ids")
        modules.append(entry)

    observed_rows = []
    for row in graph_devices:
        observed_rows.append({
            "model": row.get("model"),
            "devType": row.get("devType"),
            "identification": row.get("identification"),
            "slot": row.get("slot"),
            "rack": row.get("rack"),
            "port": row.get("port"),
        })
    result = {
        "target": "Device",
        "factoryBinding": binding,
        "hardwareRuntimeType": _text(hardware.GetType().FullName),
        "selection": {"bus": _text(bus), "rack": rack, "slot": slot,
                       "port": port, "module": module_name},
        "moduleCount": len(modules),
        "modules": modules,
        "mutatedProject": False,
        "mappingWriteSupport": "not_attempted",
        "status": "observed" if modules else "module_not_found",
        "nextRequired": "identify a concrete writable channel/mapping binding from DevObject reflection",
    }
    if not modules:
        result["observedModules"] = observed_rows[:50]
        result["hint"] = ("no config-graph row matched the module/slot filter; "
                          "re-probe with module=<model>, module=<device-tree "
                          "caption>, or module=<identification.id> from "
                          "observedModules; use vendor_device_parameter_probe "
                          "for native parameter ids when DevObject is absent")
    # MEASURED 2026-09-19: a communication slave (measured: ModbusTCP Slave,
    # HDV_MODBUS_TCP / ModbusTcpModule) exists as a config-graph row but exposes
    # NO DevObject and NO channels, so the channel-based io.mapping.add route
    # simply does not apply to it. Report that as a typed boundary instead of
    # letting a caller treat the module as an unmapped I/O module and retry.
    comm_datamodules = [
        module for module in modules
        if module.get("devObjectUnavailable")
        and _text(module.get("devType")).upper().startswith("HDV_")
        and _text(module.get("devType")).upper() not in ("HDV_CPU", "HDV_RACK")
        and bus_value != 10]
    if modules and comm_datamodules and len(comm_datamodules) == len(modules):
        result["status"] = "comm_module_has_no_channels"
        result["errorCode"] = "comm_slave_mapping_not_channel_based"
        result["mappingWriteSupport"] = "not_channel_based"
        result["boundary"] = (
            "This config-graph row is a communication slave module "
            "(devType=%s). It exposes no DevObject and no channels on this "
            "build, so codesys_io_mapping_add's channel route does not apply: "
            "the variable data of a communication slave is configured through "
            "its own vendor editor page / slave-variable table, not through "
            "rack channels."
            % _text((comm_datamodules[0] or {}).get("devType")))
        result["verifiedMappingSurface"] = (
            "local rack I/O modules on bus=10 (measured: device.config.io.add "
            "+ io.mapping.add on a GL10 module)")
        result["nextRequired"] = (
            "do NOT report the slave data mapping as done and do NOT retry "
            "io.mapping.add against this target; the communication-slave "
            "variable table route is not implemented yet")
    return result


def _configuration_archive_probe():
    """Read the vendor ConfigStorage archive through its real object manager.

    The ScriptEngine tree exposes the display node but not the serialized
    ConfigurationDataArchiveObject.  The vendor implementation locates it by
    scanning ObjectMgr.GetAllObjects(project.Handle), so the probe follows the
    same path and never creates or modifies an archive.
    """
    project_handle = _get_member(project, "handle", "get_Handle")
    extender = _get_member(project, "Extender", "get_Extender")
    extender_handle = _get_member(extender, "handle", "get_handle") if extender is not None else None
    if extender_handle not in (None, 0, "0"):
        project_handle = extender_handle
    result = {
        "binding": {
            "archiveType": INOVANCE_CONFIG_ARCHIVE_TYPE,
            "environmentType": INOVANCE_AP_ENVIRONMENT_TYPE,
        },
        "projectHandle": _json_safe(project_handle),
        "attempts": [],
        "found": False,
        "mutatedProject": False,
        "typeCandidates": [],
    }
    try:
        import System
        env_type = _reflection_type(INOVANCE_AP_ENVIRONMENT_TYPE)
        archive_type = _reflection_type(INOVANCE_CONFIG_ARCHIVE_TYPE)
        if env_type is None:
            raise RuntimeError("APEnvironment type is unavailable")
        if archive_type is None:
            raise RuntimeError("ConfigurationDataArchiveObject type is unavailable")
        mgr_prop = env_type.GetProperty("ObjectMgr")
        if mgr_prop is None:
            raise RuntimeError("APEnvironment.ObjectMgr property is unavailable")
        manager = mgr_prop.GetValue(None, None)
        if manager is None:
            raise RuntimeError("APEnvironment.ObjectMgr is null")
        handle = project_handle
        if handle is None:
            raise RuntimeError("project handle is unavailable")
        guids = manager.GetAllObjects(handle)
        result["attempts"].append({
            "name": "ObjectMgr.GetAllObjects",
            "ok": True,
            "count": len(list(guids)),
            "managerType": _text(manager.GetType().FullName),
        })
        for guid in guids:
            stub = manager.GetMetaObjectStub(handle, guid)
            object_type = _get_member(stub, "object_type", "get_ObjectType")
            type_name = _text(object_type.FullName if object_type is not None else "")
            if any(token in type_name.lower() for token in ("config", "archive", "storage")):
                result["typeCandidates"].append({"guid": _text(guid), "type": type_name,
                                                  "name": _text(_get_member(stub, "name", "get_Name", ""))})
            if not archive_type.IsAssignableFrom(object_type):
                continue
            meta = manager.GetObjectToRead(handle, guid)
            archive = _get_member(meta, "object", "get_Object")
            result["found"] = archive is not None
            result["guid"] = _text(guid)
            result["objectType"] = type_name
            result["metaType"] = _text(meta.GetType().FullName)
            if archive is not None:
                result["archive"] = {
                    "runtimeType": _text(archive.GetType().FullName),
                    "properties": sorted(set(_text(item.Name) for item in archive.GetType().GetProperties())),
                    "hardwarePresent": _get_member(archive, "hardware_configuration_proj", "get_HardwareConfigurationProj") is not None,
                    "networkPresent": _get_member(archive, "network_configuration_proj", "get_NetworkConfigurationProj") is not None,
                }
            break
        result["status"] = "found" if result["found"] else "not_found"
    except Exception as exc:
        result["status"] = "error"
        result["error"] = repr(exc)
    return result


def device_config_probe(req):
    """Bind the vendor configuration-sync object and inspect its live model."""
    _require_project()
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID
    )
    if factory is None:
        raise OperationError(
            "InoProShop configuration sync factory is unavailable",
            "configuration_factory_unavailable",
            {"binding": binding},
        )
    try:
        sync_project = factory.CreateConfigSyncProj()
    except Exception as exc:
        raise OperationError(
            "CreateConfigSyncProj failed: " + repr(exc),
            "configuration_sync_create_failed",
            {"binding": binding},
        )
    if sync_project is None:
        raise OperationError(
            "CreateConfigSyncProj returned no object",
            "configuration_sync_unavailable",
            {"binding": binding},
        )
    archive_probe = _configuration_archive_probe()
    sync_attempt = None
    save_attempt = None
    attach_attempt = None
    sync_readback = None
    sync_hardware = None
    sync_network = None
    archive = None
    if archive_probe.get("found"):
        try:
            import System
            env_type = _reflection_type(INOVANCE_AP_ENVIRONMENT_TYPE)
            manager = env_type.GetProperty("ObjectMgr").GetValue(None, None)
            handle = archive_probe.get("projectHandle")
            archive_type = _reflection_type(INOVANCE_CONFIG_ARCHIVE_TYPE)
            archive_guid = System.Guid(archive_probe.get("guid"))
            meta = manager.GetObjectToRead(handle, archive_guid)
            archive = _get_member(meta, "object", "get_Object")
            sync_project.AttachToConfigrationObjectData(archive)
            attach_attempt = {"called": True, "ok": True}
        except Exception as exc:
            attach_attempt = {"called": True, "ok": False, "error": repr(exc)}
    if bool(req.get("sync", False)):
        _require_current_disposable_project(req, "device.config.probe.sync")
        try:
            sync_project.StartSyncToConfigrationDataObject()
            sync_attempt = {"called": True, "ok": True}
        except Exception as exc:
            sync_attempt = {"called": True, "ok": False, "error": repr(exc)}

    if bool(req.get("save", False)):
        _require_current_disposable_project(req, "device.config.probe.save")
        try:
            save_result = sync_project.SaveConfigurationData()
            save_attempt = {"called": True, "ok": bool(save_result), "result": _json_safe(save_result)}
        except Exception as exc:
            save_attempt = {"called": True, "ok": False, "error": repr(exc)}

    try:
        import System
        methods = [method for method in sync_project.GetType().GetMethods()
                   if method.Name == "GetSyncToConfigrationDataObject" and len(method.GetParameters()) == 2]
        if methods:
            args = System.Array[System.Object]([None, None])
            methods[0].Invoke(sync_project, args)
            sync_hardware = args[0]
            sync_network = args[1]
            sync_readback = {
                "called": True,
                "ok": True,
                "hardwareRuntimeType": _text(args[0].GetType().FullName) if args[0] is not None else None,
                "networkRuntimeType": _text(args[1].GetType().FullName) if args[1] is not None else None,
            }
        else:
            sync_readback = {"called": False, "ok": False, "error": "GetSyncToConfigrationDataObject overload unavailable"}
    except Exception as exc:
        sync_readback = {"called": True, "ok": False, "error": repr(exc)}

    def describe(value, token_filter=()):
        if value is None:
            return None
        result = {"runtimeType": _text(value.GetType().FullName)}
        try:
            properties = []
            for item in value.GetType().GetProperties():
                name = _text(item.Name)
                if token_filter and not any(token in name.lower() for token in token_filter):
                    continue
                properties.append(name)
            result["properties"] = sorted(set(properties))
            methods = []
            for item in value.GetType().GetMethods():
                name = _text(item.Name)
                if token_filter and not any(token in name.lower() for token in token_filter):
                    continue
                methods.append(_text(item.ToString()))
            result["methods"] = sorted(set(methods))[:300]
        except Exception as exc:
            result["reflectionError"] = repr(exc)
        return result

    hardware = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
    network = _get_member(sync_project, "network_config_project", "get_NetworkConfigProject")
    result = {
        "factoryBinding": binding,
        "syncProject": describe(sync_project, ("config", "hardware", "network", "sync")),
        "hardwareConfig": describe(hardware, ("device", "rack", "module", "config", "compile", "slot", "bus", "cpu")),
        "networkConfig": describe(network, ("device", "module", "config", "bus", "network")),
        "mutatedProject": False,
        "writeSupport": "not_attempted",
        "sync": sync_attempt,
        "save": save_attempt,
        "configStorage": archive_probe,
        "attach": attach_attempt,
        "syncReadback": sync_readback,
        "mutationRisk": "GetSyncToConfigrationDataObject may create or update vendor ConfigStorage on AM600",
    }
    if hardware is None and sync_hardware is not None:
        hardware = sync_hardware
    if network is None and sync_network is not None:
        network = sync_network
    if hardware is not None:
        result["hardwareConfig"] = describe(hardware, ("device", "rack", "module", "config", "compile", "slot", "bus", "cpu"))
    if network is not None:
        result["networkConfig"] = describe(network, ("device", "module", "config", "bus", "network"))
    if sync_readback and sync_readback.get("ok"):
        result["configStorageAfterSync"] = _configuration_archive_probe()
    if save_attempt and save_attempt.get("ok"):
        result["configStorageAfterSave"] = _configuration_archive_probe()
        result["mutatedProject"] = True
    if hardware is not None:
        try:
            storage = hardware.GetConfigStorageObj()
            result["hardwareConfigStorage"] = {
                "present": storage is not None,
                "runtimeType": _text(storage.GetType().FullName) if storage is not None else None,
                "archiveGuid": _text(hardware.GetConfigurationDataArchiveObjectGuid()),
            }
            cpu = hardware.GetCpuModule()
            result["cpuModule"] = {
                "runtimeType": _text(cpu.GetType().FullName) if cpu is not None else None,
                "model": _text(_get_member(cpu, "dev_model", "get_DevModel", "")) if cpu is not None else "",
                "deviceDescription": _text(_get_member(cpu, "device_descriptioin", "get_DeviceDescriptioin", "")) if cpu is not None else "",
                "devType": _text(_get_member(cpu, "devtype", "get_DEVTYPE", "")) if cpu is not None else "",
                "slot": _json_safe(_get_member(cpu, "slotno", "get_SLOTNO")) if cpu is not None else None,
                "port": _json_safe(_get_member(cpu, "portno", "get_PortNo")) if cpu is not None else None,
            }
            result["cpuReflection"] = describe(cpu, ())
        except Exception as exc:
            result["cpuModuleError"] = repr(exc)
    result["status"] = "bound" if hardware is not None else "configuration_object_incomplete"
    return result


