def _cpu_protocol_port_verdict(inventory, resolved, supported_buses, spec,
                               lookup_error=None, support_error=None):
    """Return a strict, side-effect-free protocol-interface verdict."""
    inventory_port_type = inventory.get("PortType") or {}
    resolved_port_type = (resolved or {}).get("PortType") or {}
    checks = {
        "inventoryPortTypeExact": inventory_port_type.get("value") == spec["portType"],
        "inventoryPortNoPresent": isinstance(inventory.get("PortNo"), _INTEGER_TYPES),
        "inventoryIndexPresent": isinstance(inventory.get("Index"), _INTEGER_TYPES),
        "lookupSucceeded": resolved is not None and lookup_error is None,
        "resolvedPortTypeExact": (
            resolved is not None and
            resolved_port_type.get("value") == spec["portType"]),
        "resolvedPortNoMatchesInventory": (
            resolved is not None and
            resolved.get("PortNo") == inventory.get("PortNo")),
        "resolvedIndexMatchesInventory": (
            resolved is not None and
            resolved.get("Index") == inventory.get("Index")),
        "supportQuerySucceeded": support_error is None,
        "expectedBusPairPresent": any(
            bus.get("value") == spec["busType"] and
            _text(bus.get("name")).upper() == spec["busName"]
            for bus in (supported_buses or [])),
    }
    reasons = [name for name in sorted(checks) if not checks[name]]
    if lookup_error is not None:
        reasons.append("lookupError:" + _text(lookup_error))
    if support_error is not None:
        reasons.append("supportQueryError:" + _text(support_error))
    return {
        "supported": not reasons,
        "checks": checks,
        "failureReasons": reasons,
    }


def _cpu_port_inventory_enum_row(value):
    row = {"name": _text(value), "value": None}
    try:
        row["value"] = int(value)
    except Exception:
        pass
    return row


def _cpu_port_inventory_row(value):
    current_bus = _get_member(
        value, "CurrentBusDes", "get_CurrentBusDes", None)
    port_type = _get_member(value, "PortType", "get_PortType", None)
    bus_type = _get_member(current_bus, "BusType", "get_BusType", None)
    try:
        index = int(_get_member(value, "Index", "get_Index", None))
    except Exception:
        index = None
    try:
        port_no = int(_get_member(value, "PortNo", "get_PortNo", None))
    except Exception:
        port_no = None
    return {
        "Index": index,
        "PortNo": port_no,
        "PortType": _cpu_port_inventory_enum_row(port_type),
        "CurrentBusDes": {
            "BusType": _cpu_port_inventory_enum_row(bus_type),
        },
    }


def _protocol_created_object_readback(guid_values):
    """Read exact ObjectMgr identities for protocol objects without mutation."""
    result = {
        "source": "SystemInstances.ObjectMgr",
        "requestedGuids": list(guid_values or []),
        "objects": [],
        "complete": False,
    }
    handle = None
    for owner in (native_core_project, project):
        if owner is None:
            continue
        handle = _get_member(owner, "Handle", "get_Handle", None)
        if handle is None:
            handle = _get_member(owner, "handle", "get_handle", None)
        if handle is not None:
            break
    try:
        handle = int(handle)
    except Exception:
        result["error"] = "project handle is unavailable"
        return result
    manager, manager_probe = _system_instances_property("ObjectMgr")
    result["projectHandle"] = handle
    result["managerProbe"] = manager_probe
    if manager is None:
        result["error"] = "ObjectMgr is unavailable"
        return result
    try:
        import System
    except Exception as exc:
        result["error"] = repr(exc)
        return result
    for guid_text in result["requestedGuids"]:
        row = {"guid": _text(guid_text), "exists": False}
        try:
            guid = System.Guid(_text(guid_text))
            row["exists"] = bool(manager.ExistsObject(handle, guid))
            if not row["exists"]:
                row["readError"] = "ObjectMgr object does not exist"
                result["objects"].append(row)
                continue
            stub = manager.GetMetaObjectStub(handle, guid)
            row.update({
                "name": _text(_get_member(stub, "Name", "get_Name")),
                "parentGuid": _text(_get_member(
                    stub, "ParentObjectGuid", "get_ParentObjectGuid")),
                "objectType": _text(_get_member(
                    stub, "ObjectType", "get_ObjectType")),
            })
            meta = manager.GetObjectToRead(handle, guid)
            obj = _get_member(meta, "Object", "get_Object")
            row["runtimeType"] = (
                _text(obj.GetType().FullName) if obj is not None else "")
            identity = _get_member(
                obj, "DeviceIdentification", "get_DeviceIdentification")
            if identity is None:
                identity = _get_member(
                    obj, "device_identification", "get_DeviceIdentification")
            if identity is not None:
                row["deviceIdentification"] = {
                    "type": _json_safe(_get_member(identity, "Type", "get_Type")),
                    "id": _text(_get_member(identity, "Id", "get_Id")),
                    "version": _text(_get_member(
                        identity, "Version", "get_Version")),
                }
        except Exception as exc:
            row["readError"] = repr(exc)
        result["objects"].append(row)
    result["complete"] = (
        len(result["objects"]) == len(result["requestedGuids"]) and
        bool(result["objects"]) and
        all(row.get("exists") and not row.get("readError")
            for row in result["objects"]))
    comparison_rows = [{
        "guid": row.get("guid"),
        "name": row.get("name"),
        "parentGuid": row.get("parentGuid"),
        "objectType": row.get("objectType"),
        "runtimeType": row.get("runtimeType"),
        "deviceIdentification": row.get("deviceIdentification"),
    } for row in result["objects"]]
    result["identityComparisonRows"] = comparison_rows
    result["identityComparisonSha256"] = _sha256(json.dumps(
        _json_safe(comparison_rows), sort_keys=True, separators=(",", ":")))
    return result


def _mark_ethernet_ip_process_discard(result):
    """Describe an uncommitted EIP mutation that requires host replacement."""
    result["mutationAttempted"] = True
    result["mutatedProject"] = True
    result["committed"] = False
    result["processDiscardRequired"] = True
    result["recoveryAction"] = (
        "discard the current IDE process without trusting or reusing its "
        "in-memory project state")
    return result


def vendor_protocol_created_objects_read(req):
    """Read exact native identities for protocol-created object GUIDs."""
    _require_project()
    operation = "vendor.protocol.created_objects.read"
    raw_guids = req.get("createdGuids")
    if not isinstance(raw_guids, (list, tuple)) or not raw_guids:
        raise OperationError(
            "createdGuids must be a non-empty array of GUID strings",
            "invalid_argument",
            {"operation": operation, "path": "createdGuids",
             "mutatedProject": False})
    import System
    created_guids = []
    seen = set()
    for index, raw_guid in enumerate(raw_guids):
        if not isinstance(raw_guid, _STRING_TYPES) or not _text(raw_guid).strip():
            raise OperationError(
                "createdGuids entries must be non-empty GUID strings",
                "invalid_argument",
                {"operation": operation, "path": "createdGuids[%s]" % index,
                 "mutatedProject": False})
        guid_text = _text(raw_guid).strip()
        try:
            guid = System.Guid(guid_text)
        except Exception:
            raise OperationError(
                "createdGuids contains an invalid GUID",
                "invalid_argument",
                {"operation": operation, "path": "createdGuids[%s]" % index,
                 "actual": guid_text, "mutatedProject": False})
        canonical = _text(guid)
        if canonical == "00000000-0000-0000-0000-000000000000":
            raise OperationError(
                "createdGuids cannot contain Guid.Empty",
                "invalid_argument",
                {"operation": operation, "path": "createdGuids[%s]" % index,
                 "mutatedProject": False})
        canonical_key = canonical.lower()
        if canonical_key in seen:
            raise OperationError(
                "createdGuids cannot contain duplicates",
                "invalid_argument",
                {"operation": operation, "path": "createdGuids[%s]" % index,
                 "actual": canonical, "mutatedProject": False})
        seen.add(canonical_key)
        created_guids.append(canonical)
    readback = _protocol_created_object_readback(created_guids)
    return {
        "operation": operation,
        "projectPath": _project_path(),
        "createdGuids": created_guids,
        "readback": readback,
        "identityComparisonRows": readback.get("identityComparisonRows") or [],
        "identityComparisonSha256": readback.get("identityComparisonSha256"),
        "complete": bool(readback.get("complete")),
        "status": ("identity_readback_complete" if readback.get("complete")
                   else "identity_readback_incomplete"),
        "mutatedProject": False,
    }


def device_config_graph_probe(req):
    """Read the vendor hardware graph through HdConfigProject.

    The ScriptEngine tree only exposes display nodes.  The Inovance hardware
    configuration object contains the actual rack/module graph and its device
    objects, so this operation enumerates those objects without calling any
    mutating method.  Bus enum values and invalid port/rack combinations are
    recorded as attempts instead of being guessed as supported topology.
    """
    _require_project()
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID
    )
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", {"binding": binding})
    sync_project = factory.CreateConfigSyncProj()
    if sync_project is None:
        raise OperationError("configuration sync project is unavailable",
                             "configuration_sync_unavailable", {"binding": binding})
    sync_attempt = None
    try:
        sync_project.StartSyncToConfigrationDataObject()
        sync_attempt = {"called": True, "ok": True}
    except Exception as exc:
        sync_attempt = {"called": True, "ok": False, "error": repr(exc)}
    hardware = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
    if hardware is None:
        try:
            import System
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject" and len(m.GetParameters()) == 2]
            if methods:
                args = System.Array[System.Object]([None, None])
                methods[0].Invoke(sync_project, args)
                hardware = args[0]
        except Exception:
            hardware = None
    if hardware is None:
        raise OperationError("vendor hardware configuration object is unavailable",
                             "hardware_configuration_unavailable", {"binding": binding})

    def scalar(value, names):
        for name in names:
            try:
                item = _get_member(value, name, "get_" + name)
                if item is not None:
                    return _json_safe(item)
            except Exception:
                pass
        return None

    def identify(value):
        if value is None:
            return None
        result = {"runtimeType": _text(value.GetType().FullName)}
        for key, names in (
                ("model", ("dev_model", "get_DevModel", "DevModel")),
                ("description", ("device_descriptioin", "get_DeviceDescriptioin", "DeviceDescriptioin")),
                ("devType", ("devtype", "get_DEVTYPE", "DEVTYPE")),
                ("rack", ("rackno", "get_RACKNO", "RACKNO")),
                ("slot", ("slotno", "get_SLOTNO", "SLOTNO")),
                ("port", ("portno", "get_PortNo", "PortNo")),
                ("category", ("device_category", "get_DeviceCategory", "DeviceCategory")),
        ):
            value_read = scalar(value, names)
            if value_read is not None:
                result[key] = value_read
        try:
            try:
                identification = value.Identification
            except Exception:
                identification = _get_member(value, "identification", "get_Identification")
            if identification is not None:
                try:
                    ident_type = _json_safe(identification.Type)
                    ident_id = _text(identification.Id)
                    ident_version = _text(identification.Version)
                    ident_guid = _text(identification.DevGuid)
                except Exception:
                    ident_type = _json_safe(_get_member(identification, "type", "get_Type"))
                    ident_id = _text(_get_member(identification, "id", "get_Id"))
                    ident_version = _text(_get_member(identification, "version", "get_Version"))
                    ident_guid = _text(_get_member(identification, "dev_guid", "get_DevGuid"))
                result["identification"] = {
                    "type": ident_type,
                    "id": ident_id,
                    "version": ident_version,
                    "devGuid": ident_guid,
                }
                # A hardware module may inherit GetCpuDeviceGuid(), which is
                # the host CPU GUID rather than the module's own ObjectMgr
                # identity.  The vendor model's Identification.DevGuid is
                # the authoritative per-module value.
                own_guid = result["identification"]["devGuid"]
                if own_guid and own_guid != "00000000-0000-0000-0000-000000000000":
                    result["guid"] = own_guid
            identification_array = _get_member(value, "device_identificatioin_array", "get_DeviceIdentificatioinArray")
            if identification_array is None:
                try:
                    prop = value.GetType().GetProperty("DeviceIdentificatioinArray")
                    if prop is not None:
                        identification_array = prop.GetValue(value, None)
                except Exception:
                    pass
            if identification_array is not None:
                result["identificationArray"] = []
                for item in list(identification_array):
                    result["identificationArray"].append({
                        "type": _json_safe(_get_member(item, "type", "get_Type")),
                        "id": _text(_get_member(item, "id", "get_Id")),
                        "version": _text(_get_member(item, "version", "get_Version")),
                        "devGuid": _text(_get_member(item, "dev_guid", "get_DevGuid")),
                    })
            bus_array = _get_member(value, "bus_description_array", "get_BusDescriptionArray")
            if bus_array is not None:
                result["busDescriptions"] = []
                for item in list(bus_array):
                    dev_id = _get_member(item, "dev_identification", "get_DevIdentification")
                    result["busDescriptions"].append({
                        "runtimeType": _text(item.GetType().FullName),
                        "name": _text(_get_member(item, "name", "get_Name")),
                        "type": _json_safe(_get_member(dev_id, "type", "get_Type")) if dev_id is not None else None,
                        "id": _text(_get_member(dev_id, "id", "get_Id")) if dev_id is not None else "",
                        "version": _text(_get_member(dev_id, "version", "get_Version")) if dev_id is not None else "",
                    })
        except Exception as exc:
            result["identificationReadError"] = repr(exc)
        if "guid" not in result and "CPUModule" in result.get("runtimeType", ""):
            cpu_guid = scalar(value, ("get_cpu_device_guid", "GetCpuDeviceGuid"))
            if cpu_guid is not None:
                result["guid"] = _text(cpu_guid)
        try:
            dev_object = _get_member(value, "dev_object", "get_DevObject")
            if dev_object is not None:
                parameter_set = _get_member(dev_object, "device_parameter_set", "get_DeviceParameterSet")
                parameter_summary = None
                if parameter_set is not None:
                    try:
                        parameter_summary = {
                            "count": len(list(parameter_set)),
                            "runtimeType": _text(parameter_set.GetType().FullName),
                        }
                    except Exception as exc:
                        parameter_summary = {"readError": repr(exc)}
                result["deviceObject"] = {
                    "runtimeType": _text(dev_object.GetType().FullName),
                    "parameterSet": parameter_summary,
                }
        except Exception as exc:
            result["deviceObjectReadError"] = repr(exc)
        return result

    enum_values = []
    attempts = []
    try:
        import System
        enum_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
        if enum_type is not None:
            for enum_value in System.Enum.GetValues(enum_type):
                enum_values.append({"name": _text(enum_value), "value": int(enum_value), "_raw": enum_value})
    except Exception as exc:
        attempts.append({"binding": "DevBusType.enum", "ok": False, "error": repr(exc)})
    if not enum_values:
        enum_values = [{"name": "<enum-unavailable>", "value": 0, "_raw": 0}]

    devices = []
    seen = set()
    def add_devices(items, context):
        try:
            values = list(items) if items is not None else []
        except Exception as exc:
            attempts.append({"binding": context, "ok": False, "error": repr(exc)})
            return
        for item in values:
            if item is None:
                continue
            identity = identify(item)
            key = repr(identity)
            if key in seen:
                continue
            seen.add(key)
            identity["source"] = context
            devices.append(identity)

    try:
        add_devices([hardware.GetCpuModule()], "GetCpuModule")
    except Exception as exc:
        attempts.append({"binding": "GetCpuModule", "ok": False, "error": repr(exc)})
    try:
        cpu = hardware.GetCpuModule()
        ids = _get_member(cpu, "device_identificatioin_array", "get_DeviceIdentificatioinArray")
        if ids is None:
            try:
                prop = cpu.GetType().GetProperty("DeviceIdentificatioinArray")
                if prop is not None:
                    ids = prop.GetValue(cpu, None)
            except Exception:
                pass
        if ids is not None:
            result_ids = []
            for item in list(ids):
                result_ids.append({
                    "type": _json_safe(_get_member(item, "type", "get_Type")),
                    "id": _text(_get_member(item, "id", "get_Id")),
                    "version": _text(_get_member(item, "version", "get_Version")),
                    "devGuid": _text(_get_member(item, "dev_guid", "get_DevGuid")),
                    "deviceName": _text(_get_member(item, "device_name", "get_DeviceName")),
                    "insertIndex": _json_safe(_get_member(item, "insert_index", "get_InsertIndex")),
                })
            attempts.append({"binding": "CPUModule.DeviceIdentificatioinArray",
                             "ok": True, "count": len(result_ids), "values": result_ids})
    except Exception as exc:
        attempts.append({"binding": "CPUModule.DeviceIdentificatioinArray", "ok": False,
                         "error": repr(exc)})

    # Physical protocol support must be derived from the vendor CPU port
    # inventory.  Never scan guessed port numbers and never treat GetRackNum
    # accepting a bus enum as proof that the CPU has that communication port.
    cpu_port_inventory = {
        "source": "CPUModule.PortUseInfoArray",
        "strictFailClosed": True,
        "portNumbersGuessed": False,
        "getRackNumUsedForProtocolSupport": False,
        "readable": False,
        "ports": [],
        "protocols": {},
    }
    cpu = None
    try:
        cpu = hardware.GetCpuModule()
        raw_port_array = _get_member(
            cpu, "PortUseInfoArray", "get_PortUseInfoArray", None)
        if raw_port_array is None:
            cpu_port_inventory["readError"] = "PortUseInfoArray returned None"
            raw_ports = []
        else:
            raw_ports = list(raw_port_array)
            cpu_port_inventory["readable"] = True
    except Exception as exc:
        raw_ports = []
        cpu_port_inventory["readError"] = repr(exc)

    for raw_port in raw_ports:
        try:
            cpu_port_inventory["ports"].append(
                _cpu_port_inventory_row(raw_port))
        except Exception as exc:
            cpu_port_inventory.setdefault("portReadErrors", []).append(repr(exc))

    port_type_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.CommunicationPortType, InoDeviceConfiguration")
    for protocol in sorted(CPU_PROTOCOL_PORT_INVENTORY_SPECS):
        spec = CPU_PROTOCOL_PORT_INVENTORY_SPECS[protocol]
        protocol_result = {
            "expectedPortType": spec["portType"],
            "expectedBus": {"name": spec["busName"], "value": spec["busType"]},
            "supported": False,
            "status": "not_verified_supported",
            "candidates": [],
        }
        candidates = [row for row in cpu_port_inventory["ports"]
                      if (row.get("PortType") or {}).get("value") == spec["portType"]]
        if not cpu_port_inventory["readable"]:
            protocol_result["failureReason"] = "cpu_port_inventory_unreadable"
        elif not candidates:
            protocol_result["failureReason"] = "physical_interface_not_in_inventory"
        elif port_type_enum is None:
            protocol_result["failureReason"] = "communication_port_type_enum_unavailable"
        else:
            try:
                import System
                typed_port = System.Enum.ToObject(port_type_enum, spec["portType"])
            except Exception as exc:
                typed_port = None
                protocol_result["failureReason"] = "communication_port_type_conversion_failed"
                protocol_result["conversionError"] = repr(exc)
            if typed_port is not None:
                for inventory in candidates:
                    resolved = None
                    lookup_error = None
                    supported_buses = []
                    support_error = None
                    # PortNo comes exclusively from PortUseInfoArray.
                    port_no = inventory.get("PortNo")
                    if not isinstance(port_no, _INTEGER_TYPES):
                        lookup_error = "inventory PortNo is not an integer"
                    else:
                        try:
                            resolved_raw = cpu.GetPortInfoByTypeAndNo(typed_port, port_no)
                            if resolved_raw is not None:
                                resolved = _cpu_port_inventory_row(resolved_raw)
                        except Exception as exc:
                            lookup_error = repr(exc)
                    try:
                        for bus in list(cpu.GetSupportBusBuyInterface(typed_port) or []):
                            supported_buses.append(
                                _cpu_port_inventory_enum_row(bus))
                    except Exception as exc:
                        support_error = repr(exc)
                    verdict = _cpu_protocol_port_verdict(
                        inventory, resolved, supported_buses, spec,
                        lookup_error, support_error)
                    protocol_result["candidates"].append({
                        "inventory": inventory,
                        "resolvedByTypeAndNo": resolved,
                        "supportedBusesByInterface": supported_buses,
                        "lookupError": lookup_error,
                        "supportQueryError": support_error,
                        "verdict": verdict,
                    })
                protocol_result["supported"] = any(
                    item["verdict"]["supported"]
                    for item in protocol_result["candidates"])
                if protocol_result["supported"]:
                    protocol_result["status"] = "verified_supported"
                else:
                    protocol_result["failureReason"] = "cross_validation_failed"
        cpu_port_inventory["protocols"][protocol] = protocol_result
    # GetDeviceList(rack, bus, port) is the vendor's non-UI graph accessor.
    # Probe only the bounded range needed by the current project and retain
    # every successful call so a later writer can use observed topology.
    for bus in enum_values:
        for port in range(0, 9):
            try:
                    rack_count = int(hardware.GetRackNum(bus["_raw"], port))
            except Exception as exc:
                attempts.append({"binding": "GetRackNum", "bus": bus, "port": port,
                                 "ok": False, "error": repr(exc)})
                continue
            if rack_count < 0 or rack_count > 64:
                attempts.append({"binding": "GetRackNum", "bus": bus, "port": port,
                                 "ok": False, "error": "out_of_range:" + _text(rack_count)})
                continue
            attempts.append({"binding": "GetRackNum", "bus": bus, "port": port,
                             "ok": True, "rackCount": rack_count})
            for rack in range(0, rack_count):
                try:
                    add_devices(hardware.GetDeviceList(rack, bus["_raw"], port),
                                "GetDeviceList:%s:%s:%s" % (bus["name"], rack, port))
                except Exception as exc:
                    attempts.append({"binding": "GetDeviceList", "bus": bus,
                                     "rack": rack, "port": port, "ok": False,
                                     "error": repr(exc)})
    public_bus_types = [{"name": item["name"], "value": item["value"]} for item in enum_values]
    # Correlate config-model identities with the actual ObjectMgr objects.
    # This prevents inherited CPU GUIDs from being reported for every module.
    try:
        object_mgr, _object_probe = _system_instances_property("ObjectMgr")
        handle = _get_member(native_core_project or project, "handle", "get_Handle")
        if object_mgr is not None and handle is not None:
            import System
            native_by_identity = {}
            for object_guid in list(object_mgr.GetAllObjects(int(handle))):
                try:
                    meta = object_mgr.GetObjectToRead(int(handle), object_guid)
                    obj = _get_member(meta, "object", "get_Object")
                    ident = _get_member(obj, "device_identification", "get_DeviceIdentification") if obj is not None else None
                    if ident is None:
                        continue
                    key = (
                        _json_safe(_get_member(ident, "type", "get_Type")),
                        _text(_get_member(ident, "id", "get_Id")).upper(),
                        _text(_get_member(ident, "version", "get_Version")).upper(),
                    )
                    native_by_identity[key] = {
                        "guid": _text(object_guid),
                        "name": _text(_get_member(object_mgr.GetMetaObjectStub(int(handle), object_guid), "name", "get_Name")),
                        "parentGuid": _text(_get_member(object_mgr.GetMetaObjectStub(int(handle), object_guid), "parent_object_guid", "get_ParentObjectGuid")),
                    }
                except Exception:
                    continue
            for device in devices:
                ident = device.get("identification") or {}
                key = (ident.get("type"), _text(ident.get("id")).upper(), _text(ident.get("version")).upper())
                native = native_by_identity.get(key)
                if native is not None:
                    device["guid"] = native["guid"]
                    device["objectMgrName"] = native["name"]
                    device["objectMgrParentGuid"] = native["parentGuid"]
    except Exception as exc:
        attempts.append({"binding": "ObjectMgr.identityCorrelation", "ok": False, "error": repr(exc)})
    return {
        "target": "Device",
        "factoryBinding": binding,
        "hardwareRuntimeType": _text(hardware.GetType().FullName),
        "busTypes": public_bus_types,
        "devices": devices,
        "deviceCount": len(devices),
        "cpuPortInventory": cpu_port_inventory,
        "attempts": attempts,
        "mutatedProject": False,
        "writeSupport": "not_attempted",
        "sync": sync_attempt,
        "status": "observed",
        "nextRequired": "select one catalogued module and verify native add/readback before implementing a writer",
    }


def device_config_io_parent_probe(req):
    """Read-only correlation of the vendor config CPU and ObjectMgr CPU.

    The I/O add action consumes ``IConfigDeviceIdentification.DevGuid`` while
    the configuration-sync model may expose only ``GetCpuDeviceGuid``.  The
    vendor UI resolves the real object through ConfigurationSyncProject's
    private GetCpuDeviceObject() path, so this probe records every candidate
    and its ObjectMgr presence without mutating the project.
    """
    _require_project()
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", {"binding": binding})
    sync_project = factory.CreateConfigSyncProj()
    if sync_project is None:
        raise OperationError("configuration sync project is unavailable",
                             "configuration_sync_unavailable", {"binding": binding})
    attempts = []
    try:
        sync_project.StartSyncToConfigrationDataObject()
        attempts.append({"binding": "StartSyncToConfigrationDataObject", "ok": True})
    except Exception as exc:
        attempts.append({"binding": "StartSyncToConfigrationDataObject", "ok": False,
                         "error": repr(exc)})

    hardware = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
    if hardware is None:
        try:
            import System
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject" and len(m.GetParameters()) == 2]
            if methods:
                args = System.Array[System.Object]([None, None])
                methods[0].Invoke(sync_project, args)
                hardware = args[0]
                attempts.append({"binding": "GetSyncToConfigrationDataObject", "ok": True})
        except Exception as exc:
            attempts.append({"binding": "GetSyncToConfigrationDataObject", "ok": False,
                             "error": repr(exc)})
    if hardware is None:
        raise OperationError("vendor hardware configuration object is unavailable",
                             "hardware_configuration_unavailable", {"binding": binding,
                                                                        "attempts": attempts})

    def guid_text(value):
        text_value = _text(value or "")
        return text_value if text_value else ""

    def read_identification(value):
        ident = _get_member(value, "identification", "get_Identification") if value is not None else None
        if ident is None:
            return None
        return {
            "type": _json_safe(_get_member(ident, "type", "get_Type")),
            "id": _text(_get_member(ident, "id", "get_Id")),
            "version": _text(_get_member(ident, "version", "get_Version")),
            "devGuid": guid_text(_get_member(ident, "dev_guid", "get_DevGuid")),
        }

    cpu = None
    try:
        cpu = hardware.GetCpuModule()
    except Exception as exc:
        attempts.append({"binding": "GetCpuModule", "ok": False, "error": repr(exc)})

    candidates = []
    def add_candidate(label, value):
        value_text = guid_text(value)
        entry = {"source": label, "guid": value_text,
                 "valid": value_text not in ("", "00000000-0000-0000-0000-000000000000")}
        if not any(item["source"] == label for item in candidates):
            candidates.append(entry)
        return entry

    cpu_ident = read_identification(cpu)
    if cpu_ident is not None:
        add_candidate("hardware.GetCpuModule().Identification.DevGuid", cpu_ident.get("devGuid"))
    try:
        add_candidate("hardware.GetCpuModule().GetCpuDeviceGuid", cpu.GetCpuDeviceGuid())
    except Exception as exc:
        attempts.append({"binding": "CPUModule.GetCpuDeviceGuid", "ok": False, "error": repr(exc)})
    try:
        add_candidate("hardware.GetCpuDeviceGuid", hardware.GetCpuDeviceGuid())
    except Exception as exc:
        attempts.append({"binding": "IHardwareConfigProj.GetCpuDeviceGuid", "ok": False, "error": repr(exc)})

    # Invoke the vendor's private resolver exactly as IsAM600CPU does.
    try:
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Public |
                 System.Reflection.BindingFlags.NonPublic)
        method = [m for m in sync_project.GetType().GetMethods(flags)
                  if m.Name == "GetCpuDeviceObject" and len(m.GetParameters()) == 0]
        if method:
            add_candidate("ConfigurationSyncProject.GetCpuDeviceObject", method[0].Invoke(sync_project, None))
        else:
            attempts.append({"binding": "ConfigurationSyncProject.GetCpuDeviceObject", "ok": False,
                             "error": "method unavailable"})
    except Exception as exc:
        attempts.append({"binding": "ConfigurationSyncProject.GetCpuDeviceObject", "ok": False,
                         "error": repr(exc)})

    handle = None
    for value in (native_core_project, project):
        if value is None:
            continue
        handle = _get_member(value, "handle", "get_Handle")
        if handle is None:
            handle = _get_member(value, "Handle", "get_Handle")
        if handle is not None:
            break
    try:
        handle = int(handle)
    except Exception:
        handle = None

    object_mgr, object_mgr_probe = _system_instances_property("ObjectMgr")
    objects = []
    if object_mgr is not None and handle is not None:
        try:
            all_guids = list(object_mgr.GetAllObjects(handle))
            for object_guid in all_guids:
                try:
                    stub = object_mgr.GetMetaObjectStub(handle, object_guid)
                    parent_guid = _get_member(stub, "parent_object_guid", "get_ParentObjectGuid")
                    entry = {
                        "guid": guid_text(object_guid),
                        "parentGuid": guid_text(parent_guid),
                        "name": _text(_get_member(stub, "name", "get_Name")),
                        "objectType": _text(_get_member(stub, "object_type", "get_ObjectType")),
                    }
                    try:
                        meta = object_mgr.GetObjectToRead(handle, object_guid)
                        obj = _get_member(meta, "object", "get_Object")
                        if obj is not None:
                            entry["runtimeType"] = _text(obj.GetType().FullName)
                            ident = _get_member(obj, "device_identification", "get_DeviceIdentification")
                            if ident is not None:
                                entry["deviceIdentification"] = {
                                    "type": _json_safe(_get_member(ident, "type", "get_Type")),
                                    "id": _text(_get_member(ident, "id", "get_Id")),
                                    "version": _text(_get_member(ident, "version", "get_Version")),
                                }
                    except Exception as exc:
                        entry["readError"] = repr(exc)
                    objects.append(entry)
                except Exception as exc:
                    objects.append({"guid": guid_text(object_guid), "error": repr(exc)})
            attempts.append({"binding": "ObjectMgr.GetAllObjects", "ok": True,
                             "handle": handle, "count": len(objects)})
        except Exception as exc:
            attempts.append({"binding": "ObjectMgr.GetAllObjects", "ok": False,
                             "handle": handle, "error": repr(exc)})
    else:
        attempts.append({"binding": "ObjectMgr.GetAllObjects", "ok": False,
                         "handle": handle, "error": "object manager or project handle unavailable"})

    for candidate in candidates:
        candidate["existsInObjectManager"] = False
        if candidate["valid"] and object_mgr is not None and handle is not None:
            try:
                import System
                candidate["existsInObjectManager"] = bool(
                    object_mgr.ExistsObject(handle, System.Guid(candidate["guid"])))
            except Exception as exc:
                candidate["existsError"] = repr(exc)

    return {
        "factoryBinding": binding,
        "syncProjectRuntimeType": _text(sync_project.GetType().FullName),
        "hardwareRuntimeType": _text(hardware.GetType().FullName),
        "cpuRuntimeType": _text(cpu.GetType().FullName) if cpu is not None else None,
        "cpuIdentification": cpu_ident,
        "projectHandle": handle,
        "objectManager": object_mgr_probe,
        "candidates": candidates,
        "objects": objects,
        "objectCount": len(objects),
        "attempts": attempts,
        "mutatedProject": False,
        "status": "observed",
    }


def device_config_io_action_probe(req):
    """Discover the exact vendor I/O action and device-tree parser bindings."""
    _require_project()
    result = {"mutatedProject": False, "writeSupport": "not_attempted", "attempts": []}

    def shape(value):
        if value is None:
            return None
        try:
            typ = value.GetType()
            return {
                "runtimeType": _text(typ.FullName),
                "properties": sorted(set(_text(item.Name) for item in typ.GetProperties())),
                "methods": sorted(set(_text(item.ToString()) for item in typ.GetMethods()))[:500],
            }
        except Exception as exc:
            return {"error": repr(exc)}

    candidates = (
        ("Inovance.InoPro.InoDeviceConfiguration.IDevTreeFileParserFactory, InoDeviceConfiguration",
         "{669014F5-D843-4E51-962E-1386A8828EBE}", "deviceTreeParserFactory"),
        ("Inovance.InoPro.InoDeviceBase.IOModule.IIoModuleAddActionFactory, InoDeviceBase",
         "{0AD367FC-6F6B-44E4-B1D9-F1DFFCDC92FA}", "ioModuleAddActionFactory"),
        ("Inovance.InoPro.InoDeviceBase.IOModule.IIoModuleAddActionFactory, InoDeviceBase.plugin",
         "{0AD367FC-6F6B-44E4-B1D9-F1DFFCDC92FA}", "ioModuleAddActionFactoryPlugin"),
        ("Inovance.InoPro.InoDeviceConfiguration.IIoModuleAddActionFactory, InoDeviceConfiguration",
         "{0AD367FC-6F6B-44E4-B1D9-F1DFFCDC92FA}", "ioModuleAddActionFactoryConfiguration"),
    )
    bound = {}
    for interface_name, guid, label in candidates:
        try:
            value, binding = _reflection_generic_create(interface_name, guid)
            bound[label] = {"binding": binding, "shape": shape(value)}
        except Exception as exc:
            result["attempts"].append({"label": label, "interface": interface_name,
                                       "ok": False, "error": repr(exc)})
    result["bindings"] = bound
    try:
        import System
        type_hits = []
        for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
            try:
                for typ in assembly.GetTypes():
                    full_name = _text(typ.FullName)
                    if any(token in full_name for token in ("IoModuleAddActionFactory", "IIoModuleConfigAction", "IIoModuleAddAction")):
                        type_hits.append({"assembly": _text(assembly.FullName), "type": full_name})
            except Exception:
                pass
        result["loadedTypeHits"] = type_hits[:100]
    except Exception as exc:
        result["loadedTypeHitsError"] = repr(exc)

    parser = None
    parser_factory = bound.get("deviceTreeParserFactory")
    if parser_factory:
        try:
            factory, _ = _reflection_generic_create(
                "Inovance.InoPro.InoDeviceConfiguration.IDevTreeFileParserFactory, InoDeviceConfiguration",
                "{669014F5-D843-4E51-962E-1386A8828EBE}")
            parser = factory.CreateDeviceTreeParser()
            result["parser"] = shape(parser)
            identifier = _text(req.get("identifier") or "10F41010")
            parser_result = {"identifier": identifier}
            for method_name in ("GetDeviceIdentification", "GetDeviceDescription",
                                "GetDevicePictureName2", "GetDevicePictureName3"):
                try:
                    method = getattr(parser, method_name)
                    value = method(identifier)
                    if method_name == "GetDeviceIdentification" and value is not None:
                        parser_result[method_name] = {
                            "type": _json_safe(_get_member(value, "type", "get_Type")),
                            "id": _text(_get_member(value, "id", "get_Id")),
                            "version": _text(_get_member(value, "version", "get_Version")),
                        }
                    else:
                        parser_result[method_name] = _json_safe(value)
                except Exception as exc:
                    parser_result[method_name] = {"error": repr(exc)}
            try:
                import System
                bus_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
                local_bus = System.Enum.ToObject(bus_type, 10) if bus_type is not None else 10
                value = parser.GetDeviceIdentificationFromIOModule(identifier, local_bus)
                parser_result["GetDeviceIdentificationFromIOModule"] = {
                    "type": _json_safe(_get_member(value, "type", "get_Type")),
                    "id": _text(_get_member(value, "id", "get_Id")),
                    "version": _text(_get_member(value, "version", "get_Version")),
                } if value is not None else None
            except Exception as exc:
                parser_result["GetDeviceIdentificationFromIOModule"] = {"error": repr(exc)}
            for method_name in ("GetDeviceDescriptionFromIOModule", "GetDevicePicFromIOModule",
                                "GetDevicePicFromIOModule_ByID", "GetDeviceDescriptionFromModuleDevice"):
                try:
                    parser_result[method_name] = _json_safe(getattr(parser, method_name)(identifier))
                except Exception as exc:
                    parser_result[method_name] = {"error": repr(exc)}
            try:
                import System
                hw_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.HwDevType, InoDeviceConfiguration")
                digital_hw = System.Enum.ToObject(hw_type, 2) if hw_type is not None else 2
                for method_name, args in (
                        ("GetDeviceIdentificationByType", (identifier,)),
                        ("GetSpecialIoModuleIentificaion", (digital_hw, identifier)),):
                    try:
                        value = getattr(parser, method_name)(*args)
                        parser_result[method_name] = {
                            "type": _json_safe(_get_member(value, "type", "get_Type")),
                            "id": _text(_get_member(value, "id", "get_Id")),
                            "version": _text(_get_member(value, "version", "get_Version")),
                        } if value is not None else None
                    except Exception as exc:
                        parser_result[method_name] = {"error": repr(exc)}
            except Exception as exc:
                parser_result["identificationFactoryCalls"] = {"error": repr(exc)}
            try:
                import System
                io_enum_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.IOModuleType, InoDeviceConfiguration")
                io_catalog = []
                if io_enum_type is not None:
                    for io_value in System.Enum.GetValues(io_enum_type):
                        try:
                            names = list(parser.GetIoModuleList(io_value))
                        except Exception as exc:
                            names = {"error": repr(exc)}
                        io_catalog.append({"name": _text(io_value), "value": int(io_value), "modules": _json_safe(names)})
                parser_result["ioModuleCatalog"] = io_catalog
            except Exception as exc:
                parser_result["ioModuleCatalog"] = {"error": repr(exc)}
            # Optional bounded identity/topology probes.  These are kept on
            # the read-only action probe rather than hidden inside the write
            # path so a caller can establish the exact parser module name
            # (which is case-sensitive and may retain hyphens) before an
            # add action is ever constructed.  ``GetIoModuleList`` exposes
            # repository/module names, while the installed catalog's
            # orderNumber is a separate action model; conflating the two was
            # the source of the R47 false-negative preflight.
            requested_names = req.get("moduleNames") or []
            if isinstance(requested_names, (list, tuple)):
                requested_names = [_text(item).strip() for item in requested_names
                                   if _text(item).strip()]
            else:
                requested_names = []
            if requested_names:
                module_probes = []
                try:
                    import System
                    bus_type = _reflection_type(
                        "Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
                    local_bus = (System.Enum.ToObject(bus_type, int(req.get("bus", 10)))
                                 if bus_type is not None else int(req.get("bus", 10)))
                    hw_type = _reflection_type(
                        "Inovance.InoPro.InoDeviceConfiguration.HwDevType, InoDeviceConfiguration")
                    for probe_name in requested_names[:24]:
                        probe = {"name": probe_name}
                        try:
                            value = parser.GetDeviceIdentificationFromIOModule(
                                probe_name, local_bus)
                            if value is not None:
                                probe["localIdentity"] = {
                                    "type": _json_safe(_get_member(value, "type", "get_Type")),
                                    "id": _text(_get_member(value, "id", "get_Id")),
                                    "version": _text(_get_member(value, "version", "get_Version")),
                                    "deviceName": _text(_get_member(value, "device_name", "get_DeviceName")),
                                }
                        except Exception as exc:
                            probe["localIdentityError"] = repr(exc)
                        # Probe the exact native predicate with the parser
                        # name.  This is diagnostic only; it never mutates a
                        # project and does not decide a write by itself.
                        try:
                            methods = [method for method in parser.GetType().GetMethods()
                                       if _text(method.Name) == "IoModuleMatchParentDevice"
                                       and len(method.GetParameters()) == 4]
                            if methods and probe.get("localIdentity"):
                                ident = System.Activator.CreateInstance(_reflection_type(
                                    "Inovance.InoPro.InoProfileParser.ConfigDeviceIdentification, InoProfileParser"))
                                ident.Type = int(probe["localIdentity"]["type"])
                                ident.Id = probe["localIdentity"]["id"]
                                ident.Version = probe["localIdentity"]["version"]
                                ident.DeviceName = probe["localIdentity"].get("deviceName") or probe_name
                                predicates = []
                                for parent_value in (7, 10):
                                    for tag in ("IO_MODULE", "IO_MODULE_STD", "IO_MODULE_EXT",
                                                "IO_MODULE_GL20", "IO_MODULE_GL20_old"):
                                        try:
                                            params = methods[0].GetParameters()
                                            parent_arg = (System.Enum.ToObject(params[2].ParameterType,
                                                                                parent_value)
                                                          if params[2].ParameterType.IsEnum
                                                          else parent_value)
                                            matched = methods[0].Invoke(
                                                parser, System.Array[System.Object]([
                                                    ident, probe_name, parent_arg, tag]))
                                            predicates.append({"parentType": parent_value,
                                                               "tag": tag, "matched": bool(matched)})
                                        except Exception as exc:
                                            predicates.append({"parentType": parent_value,
                                                               "tag": tag, "error": repr(exc)})
                                probe["predicates"] = predicates
                        except Exception as exc:
                            probe["predicateError"] = repr(exc)
                        module_probes.append(probe)
                except Exception as exc:
                    module_probes = [{"error": repr(exc)}]
                parser_result["moduleProbes"] = module_probes
            cpu_type = _text(req.get("cpuType") or "").strip()
            if cpu_type:
                try:
                    values = parser.GetCpuConfigDeviceIdentifiList(cpu_type)
                    cpu_configs = []
                    for value in list(values or [])[:200]:
                        cpu_configs.append({
                            "deviceName": _text(_get_member(value, "device_name", "get_DeviceName")),
                            "type": _json_safe(_get_member(value, "type", "get_Type")),
                            "id": _text(_get_member(value, "id", "get_Id")),
                            "version": _text(_get_member(value, "version", "get_Version")),
                        })
                    parser_result["cpuConfigDeviceIdentifications"] = cpu_configs
                except Exception as exc:
                    parser_result["cpuConfigDeviceIdentifications"] = {"error": repr(exc)}
            result["parserReadback"] = parser_result
        except Exception as exc:
            result["attempts"].append({"label": "CreateDeviceTreeParser", "ok": False,
                                       "error": repr(exc)})

    result["status"] = "observed" if bound or parser is not None else "unavailable"
    result["nextRequired"] = "bind parser identification and action CreateIoModuleAddAction, then execute only on disposable project"
    return result


# Evidence-backed module-name aliases for device.config.io.add (keys are
# lowercase). The vendor parser resolves these names only after the device
# profile has been loaded in the current IDE session; a cold IDE returns
# None, and these carry the verified catalog identity instead.
# Source: device.config.io.add verifiedIdentity (GL10_1600END closure,
# 2026-08-31) + device.list_installed.
VERIFIED_MODULE_ALIASES = {
    "gl10_1600end": {
        "type": 40010, "id": "10F4 0010", "version": "00.00.00.10",
        "name": "GL10 16点DI模块",
    },
}
# Keep the fallback identity's parser/tree name ASCII and exact.  The legacy
# localized display label above is retained for compatibility with old
# receipts, but must never be passed to the case-sensitive parser lookup.
VERIFIED_MODULE_ALIASES["gl10_1600end"]["parserName"] = "GL10_1600END"
VERIFIED_MODULE_ALIASES["gl20(gl20s)-4lc-pid"] = {
    "type": 41053, "id": "10F4 1053", "version": "00.00.00.10",
    "name": "GL20(GL20S)-4LC-PID",
    "parserName": "GL20(GL20S)-4LC-PID",
}


def _config_identity_parts(identity):
    """Read a vendor ``IConfigDeviceIdentification`` without guessing names.

    IronPython exposes the same CLR object through different members depending
    on whether it was returned by the parser interface or constructed through
    ``Activator``.  Parser results commonly have ``Type/Id/Version`` while an
    interface proxy may only expose ``get_Type`` and friends.  Keeping this
    normalization in one read-only helper prevents an empty proxy from being
    mistaken for a real catalog identity.
    """
    if identity is None:
        return {"type": None, "id": "", "version": "", "deviceName": ""}
    raw_type = _get_member(identity, "Type", "get_Type")
    if raw_type is None:
        raw_type = _get_member(identity, "type", "get_type")
    try:
        type_value = int(raw_type)
    except Exception:
        try:
            type_value = int(_get_member(raw_type, "value", "Value", "get_Value"))
        except Exception:
            type_value = None
    raw_id = _get_member(identity, "Id", "get_Id")
    if raw_id is None:
        raw_id = _get_member(identity, "id", "get_id")
    raw_version = _get_member(identity, "Version", "get_Version")
    if raw_version is None:
        raw_version = _get_member(identity, "version", "get_version")
    raw_name = _get_member(identity, "DeviceName", "get_DeviceName")
    if raw_name is None:
        raw_name = _get_member(identity, "device_name", "get_DeviceName")
    return {
        "type": type_value,
        "id": _text(raw_id or ""),
        "version": _text(raw_version or ""),
        "deviceName": _text(raw_name or ""),
    }


def _io_module_parent_tag(parent_device_type, parent_identity):
    """Return the exact I/O tag key selected by the native module picker.

    EtherCAT module names are not globally unique in the V1.10 parser.  The
    picker first derives one tag from the *actual parent device* and then asks
    ``GetSpecialIoModuleIentificaion(parentType, name, tag)`` for the identity
    stored under that branch.  Keeping this classifier pure makes the
    coupler/tag contract host-testable and prevents a CPU row from being used
    accidentally as an EtherCAT parent.
    """
    parts = (parent_identity if isinstance(parent_identity, dict)
             else _config_identity_parts(parent_identity))
    try:
        parent_number = int(parent_device_type)
    except Exception:
        try:
            parent_number = int(_get_member(
                parent_device_type, "value", "Value", "get_Value"))
        except Exception:
            parent_number = None
    parent_id = _text(parts.get("id") or "").strip().upper()
    parent_type = parts.get("type")
    try:
        parent_type = int(parent_type)
    except Exception:
        parent_type = None
    result = {
        "parentDeviceType": parent_number,
        "parentIdentity": parts,
        "parentId": parent_id,
        "tag": "IO_MODULE",
        "reason": "default_io_module_tag",
        "exactParentIdentity": bool(parent_id and parent_type is not None),
    }
    if parent_number != 10:
        result["reason"] = "non_ethercat_parent_uses_default_tag"
        return result
    if (parent_type == 65 and parent_id in (
            "100000_10F4020201006000",
            "100000_10F4091001006000")):
        result["tag"] = "IO_MODULE_EXT"
        result["reason"] = "vendor_extended_coupler_tag"
    elif ((parent_type == 65 and parent_id in (
            "100000_10F4100001006000",
            "100000_10F4100101006000")) or
            (parent_type == 4102 and parent_id == "10F4 0001")):
        result["tag"] = "IO_MODULE_GL20"
        result["reason"] = "vendor_gl20_coupler_tag"
    else:
        result["reason"] = "vendor_default_ethercat_tag"
    return result


def _io_module_parent_context(hardware, parent, before, bus_value):
    """Snapshot the selected hardware parent and the independent root CPU.

    ``FindSpecialDevice`` returns the CPU on a local bus but an EtherCAT
    slave/coupler on bus 3.  The old coordinator always read
    ``hardware.GetCpuModule()`` first, so an EtherCAT add was preflighted as
    if its parent DEVTYPE were HDV_CPU=7.  This helper makes both identities
    explicit without mutating either object.
    """
    try:
        bus_number = int(bus_value)
    except Exception:
        bus_number = None
    cpu_rows = [item for item in (before.get("devices") or [])
                if _text(item.get("devType")).strip().upper() == "HDV_CPU"]
    cpu_row = cpu_rows[0] if len(cpu_rows) == 1 else {}
    root_cpu = None
    try:
        root_cpu = hardware.GetCpuModule()
    except Exception:
        root_cpu = None
    root_identity_object = _get_member(
        root_cpu, "Identification", "get_Identification")
    if root_identity_object is None:
        root_identity_object = _get_member(
            root_cpu, "identification", "get_identification")
    root_identity = _config_identity_parts(root_identity_object)
    if not root_identity.get("id"):
        root_identity = cpu_row.get("identification") or root_identity
    root_model = (_text(cpu_row.get("model") or "").strip() or
                  _text(root_identity.get("deviceName") or "").strip())

    parent_identity_object = _get_member(
        parent, "Identification", "get_Identification")
    if parent_identity_object is None:
        parent_identity_object = _get_member(
            parent, "identification", "get_identification")
    parent_identity = _config_identity_parts(parent_identity_object)
    if (not parent_identity.get("id") and bus_number == 10 and
            root_identity.get("id")):
        parent_identity = dict(root_identity)
    parent_device_type = _get_member(
        parent, "DEVTYPE", "get_DEVTYPE")
    if parent_device_type is None:
        parent_device_type = _get_member(
            parent, "devtype", "get_devtype")
    try:
        parent_device_type_value = int(parent_device_type)
    except Exception:
        try:
            parent_device_type_value = int(_get_member(
                parent_device_type, "value", "Value", "get_Value"))
        except Exception:
            parent_device_type_value = None
    if parent_device_type_value is None and parent_device_type is not None:
        # IronPython enum objects sometimes refuse int() but expose the numeric
        # value through the .NET Enum API (measured 2026-09-19: a real EtherCAT
        # coupler came back with parentDeviceType=null and the admission gate
        # therefore answered "not admissible").
        try:
            import System
            parent_device_type_value = int(System.Convert.ToInt32(
                parent_device_type))
        except Exception:
            parent_device_type_value = None
    if (parent_device_type_value is None and bus_number == 10 and
            root_identity.get("id")):
        parent_device_type_value = 7
    parent_model = (_text(parent_identity.get("deviceName") or "").strip() or
                    (root_model if bus_number == 10 else ""))
    tag = _io_module_parent_tag(
        parent_device_type_value, parent_identity)
    return {
        "bus": bus_number,
        "parentRuntimeType": (_text(parent.GetType().FullName)
                              if parent is not None else None),
        "parentDeviceType": parent_device_type_value,
        "parentIdentity": parent_identity,
        "parentModel": parent_model,
        "rootCpuIdentity": root_identity,
        "rootCpuModel": root_model,
        "parserTag": tag.get("tag"),
        "parserTagDetails": tag,
    }


def _io_module_parent_guid_candidates(parent):
    """Collect only GUIDs owned by the selected parent hardware object."""
    candidates = []
    seen = set()

    def add(value, source):
        text_value = _text(value or "").strip()
        if not text_value or text_value.lower() == (
                "00000000-0000-0000-0000-000000000000"):
            return
        key = text_value.lower()
        if key in seen:
            return
        seen.add(key)
        candidates.append({"guid": text_value, "source": source})

    identity = _get_member(parent, "Identification", "get_Identification")
    if identity is None:
        identity = _get_member(parent, "identification", "get_identification")
    add(_get_member(identity, "DevGuid", "get_DevGuid"),
        "parent_identification_dev_guid")
    dev_object = _get_member(parent, "DevObject", "get_DevObject")
    if dev_object is None:
        dev_object = _get_member(parent, "dev_object", "get_dev_object")
    add(_get_member(dev_object, "ObjectGuid", "get_ObjectGuid"),
        "parent_dev_object_guid")
    meta = _get_member(dev_object, "MetaObject", "get_MetaObject")
    add(_get_member(meta, "ObjectGuid", "get_ObjectGuid"),
        "parent_dev_object_meta_guid")
    add(_get_member(meta, "Guid", "get_Guid"),
        "parent_dev_object_meta_guid_alias")
    add(_get_member(parent, "ObjectGuid", "get_ObjectGuid"),
        "parent_object_guid")
    return candidates


def _io_module_coupler_support(parent_id, module_id):
    """Invoke the native static coupler compatibility predicate exactly once."""
    import System
    result = {
        "checked": False,
        "available": False,
        "couplerId": _text(parent_id or "").strip(),
        "moduleId": _text(module_id or "").strip(),
        "supported": None,
    }
    runtime_type = _reflection_type(
        "Inovance.InoPro.DeviceConfigurationEditor.CommFunClass, "
        "InoDeviceConfigurationEditor.plugin")
    if runtime_type is None:
        result["error"] = "CommFunClass runtime type is unavailable"
        return result
    flags = (System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public)
    methods = [method for method in runtime_type.GetMethods(flags)
               if _text(method.Name) == "IsModuleSupportByCoupler" and
               len(method.GetParameters()) == 2]
    result["bindingCount"] = len(methods)
    if len(methods) != 1:
        result["error"] = "exact IsModuleSupportByCoupler binding is unavailable"
        return result
    result["available"] = True
    result["binding"] = _text(methods[0].ToString())
    try:
        value = methods[0].Invoke(
            None, System.Array[System.Object]([
                result["couplerId"], result["moduleId"]]))
        result["checked"] = True
        result["supported"] = bool(value)
    except Exception as exc:
        result["error"] = repr(exc)
    return result


def _io_module_ethercat_gate(parser, parent_identity, root_cpu_identity,
                             module_identity, parser_tag):
    """Mirror the native EtherCAT tag/coupler/limited-module admission gate."""
    parent_parts = (parent_identity if isinstance(parent_identity, dict)
                    else _config_identity_parts(parent_identity))
    root_parts = (root_cpu_identity if isinstance(root_cpu_identity, dict)
                  else _config_identity_parts(root_cpu_identity))
    module_parts = (module_identity if isinstance(module_identity, dict)
                    else _config_identity_parts(module_identity))
    data = {
        "allowed": None,
        "reason": None,
        "parserTag": _text(parser_tag or "").strip(),
        "parentIdentity": parent_parts,
        "rootCpuIdentity": root_parts,
        "moduleIdentity": module_parts,
        "couplerSupport": None,
        "limitedModule": None,
        "limitedModuleChecked": False,
    }
    if (not data["parserTag"] or not parent_parts.get("id") or
            parent_parts.get("type") is None):
        data["reason"] = "ethercat_parent_or_parser_tag_unavailable"
        return None, data
    if not root_parts.get("id") or not module_parts.get("id"):
        data["reason"] = "ethercat_root_or_module_identity_unavailable"
        return None, data
    coupler = _io_module_coupler_support(
        parent_parts.get("id"), module_parts.get("id"))
    data["couplerSupport"] = coupler
    if not coupler.get("checked"):
        data["reason"] = "ethercat_coupler_gate_unavailable"
        return None, data
    if coupler.get("supported") is not True:
        data["allowed"] = False
        data["reason"] = "vendor_coupler_rejects_module"
        return False, data
    try:
        limited = parser.IsLimitedModule(
            _text(root_parts.get("id")).strip(),
            _text(module_parts.get("id")).strip(), True)
        data["limitedModule"] = bool(limited)
        data["limitedModuleChecked"] = True
    except Exception as exc:
        data["limitedModuleError"] = repr(exc)
        data["reason"] = "ethercat_limited_module_gate_unavailable"
        return None, data
    if data["limitedModule"]:
        data["allowed"] = False
        data["reason"] = "vendor_is_limited_ethercat_module"
        return False, data
    data["allowed"] = True
    data["reason"] = "vendor_ethercat_tag_coupler_and_limit_gates_allow_module"
    return True, data


def _parser_io_module_resolution(parser, identity, bus_value,
                                  requested_name=None,
                                  parent_device_type=None,
                                  parser_tag=None):
    """Resolve the exact, case-sensitive parser module name for an identity.

    ``IConfigDeviceIdentification.DeviceName`` and the installed repository's
    ``OrderNumber`` are not interchangeable.  The native predicates index
    ``ModuleInfos`` by its exact ``moduleName`` (hyphens included), whereas
    ``IoModuleAddAction`` receives the action model.  Enumerate the bounded
    parser lists and match all three identity fields before using a name in a
    predicate or topology decision.
    """
    import System
    wanted = _config_identity_parts(identity)
    result = {
        "requestedName": _text(requested_name or "").strip(),
        "bus": None,
        "parentDeviceType": None,
        "parserTag": _text(parser_tag or "").strip(),
        "tagAwareRequired": False,
        "tagAware": False,
        "wantedIdentity": wanted,
        "candidateNames": [],
        "attempts": [],
        "exactMatch": False,
        "resolvedName": None,
        "resolvedIdentity": None,
    }
    try:
        bus_number = int(bus_value)
    except Exception:
        bus_number = None
    result["bus"] = bus_number
    try:
        parent_number = int(parent_device_type)
    except Exception:
        try:
            parent_number = int(_get_member(
                parent_device_type, "value", "Value", "get_Value"))
        except Exception:
            parent_number = None
    result["parentDeviceType"] = parent_number
    if parser is None or wanted.get("type") is None or not wanted.get("id"):
        result["reason"] = "requested identity is incomplete"
        return result
    try:
        io_enum_type = _reflection_type(
            "Inovance.InoPro.InoDeviceConfiguration.IOModuleType, InoDeviceConfiguration")
        names = []
        if result["requestedName"]:
            names.append(result["requestedName"])

        # EtherCAT is a tagged namespace.  The same visible/order name can
        # resolve to different identities under IO_MODULE, IO_MODULE_EXT, or
        # IO_MODULE_GL20.  Never use the generic
        # GetDeviceIdentificationFromIOModule(name, DBT_ETHERCAT) fallback:
        # on V1.10 it returns a broad/empty record and can make an unsupported
        # module look admissible.  Resolve only through the exact three
        # argument parser contract used by HwDevTreeView.
        if bus_number == 3:
            result["tagAwareRequired"] = True
            if parent_number != 10 or not result["parserTag"]:
                result["reason"] = "ethercat_parent_type_or_tag_unavailable"
                return result
            # The shipped parser has more than one EtherCAT catalogue.  The
            # newer GL20 entries are exposed by ``GetEctIoModuleList`` (and,
            # on some builds, ``GetEct16IoModuleList``), while legacy AM600
            # DI/DO entries live under the plain EtherCAT ``IO_MODULE``
            # section and are exposed by ``GetIoModuleList``.  Enumerate all
            # read-only list surfaces before probing the tag-aware identity
            # method; using only the GL20 list made a valid legacy module look
            # like an unenumerated identity.
            seen_names = set(_text(item).strip().lower() for item in names
                             if _text(item).strip())

            def append_candidate(value):
                text_value = _text(value).strip()
                if not text_value:
                    return False
                key = text_value.lower()
                if key in seen_names or len(names) >= 256:
                    return False
                seen_names.add(key)
                names.append(text_value)
                return True

            if io_enum_type is not None:
                # Keep this order stable: requested name first, then the
                # legacy EtherCAT list, GL20 list, and GL20-16 list.  A few
                # vendor builds omit one of the methods; that is a normal
                # compatibility boundary and must not make the resolver
                # optimistic or throw before the remaining lists are tried.
                list_specs = (
                    ("ethercat_io_catalog_list", "GetIoModuleList"),
                    ("ect_catalog_list", "GetEctIoModuleList"),
                    ("ect16_catalog_list", "GetEct16IoModuleList"),
                )
                for category in range(4):
                    try:
                        category_value = System.Enum.ToObject(io_enum_type, category)
                    except Exception as exc:
                        result["attempts"].append({
                            "kind": "io_category_value", "category": category,
                            "ok": False, "error": repr(exc),
                        })
                        continue
                    for source_kind, method_name in list_specs:
                        method = getattr(parser, method_name, None)
                        if method is None:
                            result["attempts"].append({
                                "kind": source_kind, "method": method_name,
                                "category": category, "ok": False,
                                "error": "method unavailable",
                            })
                            continue
                        try:
                            values = method(category_value)
                            # A CLR string is iterable too; treat it as one
                            # candidate rather than accidentally adding its
                            # individual characters.
                            if isinstance(values, (str, bytes)):
                                values = [values]
                            else:
                                values = list(values or [])
                            added = 0
                            for value in values:
                                if append_candidate(value):
                                    added += 1
                                if len(names) >= 256:
                                    break
                            result["attempts"].append({
                                "kind": source_kind, "method": method_name,
                                "category": category, "ok": True,
                                "count": len(values), "added": added,
                            })
                        except Exception as exc:
                            result["attempts"].append({
                                "kind": source_kind, "method": method_name,
                                "category": category, "ok": False,
                                "error": repr(exc),
                            })
            result["candidateNames"] = names[:256]
            methods = []
            try:
                import System
                flags = (System.Reflection.BindingFlags.Instance |
                         System.Reflection.BindingFlags.Public |
                         System.Reflection.BindingFlags.NonPublic)
                methods = [method for method in parser.GetType().GetMethods(flags)
                           if _text(method.Name) ==
                           "GetSpecialIoModuleIentificaion" and
                           len(method.GetParameters()) == 3]
            except Exception as exc:
                result["tagIdentityBindingError"] = repr(exc)
            if len(methods) != 1:
                result["reason"] = "ethercat_tag_identity_binding_unavailable"
                result["tagIdentityBindingCount"] = len(methods)
                return result
            try:
                parent_arg = parent_number
                params = methods[0].GetParameters()
                if params[0].ParameterType.IsEnum:
                    parent_arg = System.Enum.ToObject(
                        params[0].ParameterType, parent_number)
            except Exception:
                parent_arg = parent_number
            # EtherCAT is a TAGGED namespace: the same name resolves to
            # different identities under IO_MODULE / IO_MODULE_EXT /
            # IO_MODULE_GL20.  Measured 2026-09-19: with the tag fixed to the
            # parent tag ("IO_MODULE") a real GL20 module never produced an
            # exact identity and the gate answered
            # no_exact_ethercat_tag_identity_match.  Probe every documented tag
            # and keep the one that yields the exact identity.
            tags = [result["parserTag"]]
            if bus_number == 3:
                for extra_tag in ("IO_MODULE", "IO_MODULE_EXT", "IO_MODULE_GL20"):
                    if extra_tag not in tags:
                        tags.append(extra_tag)
            exact_matches = []
            parser_name_matches = []
            matched_tag = None
            lookup_attempts = 0
            for candidate in names[:256]:
                for tag in tags:
                    try:
                        value = methods[0].Invoke(
                            parser, System.Array[System.Object]([
                                parent_arg, candidate, tag]))
                        observed = _config_identity_parts(value)
                    except Exception as exc:
                        if lookup_attempts < 40:
                            result["attempts"].append({
                                "kind": "tag_identity_lookup", "name": candidate,
                                "tag": tag, "parentType": parent_number,
                                "ok": False, "error": repr(exc),
                            })
                            lookup_attempts += 1
                        continue
                    if value is not None and lookup_attempts < 40:
                        result["attempts"].append({
                            "kind": "tag_identity_lookup", "name": candidate,
                            "tag": tag, "parentType": parent_number,
                            "ok": True, "identity": observed,
                        })
                        lookup_attempts += 1
                    if (value is not None and
                            observed.get("type") == wanted.get("type") and
                            _text(observed.get("id")).strip().lower() ==
                            _text(wanted.get("id")).strip().lower() and
                            _text(observed.get("version")).strip().lower() ==
                            _text(wanted.get("version")).strip().lower()):
                        exact_matches.append((candidate, observed))
                        if matched_tag is None:
                            matched_tag = tag
                        break
                    if (value is not None
                            and candidate == result["requestedName"]
                            and _text(observed.get("deviceName")).strip()
                            == _text(result["requestedName"]).strip()):
                        # The parser's own identity for this exact name/tag.
                        parser_name_matches.append((candidate, observed))
                        if matched_tag is None:
                            matched_tag = tag
            if matched_tag is not None:
                result["matchedTag"] = matched_tag
                result["parserTag"] = matched_tag
            # Several legacy digital-output variants intentionally share one
            # repository identity (ETP/ETN/ER).  The native picker keeps those
            # variants distinct by passing the selected tree-node text as
            # ``sModuleName``.  Honour an exact caller-supplied parser name
            # when it itself matches the identity; only report ambiguity when
            # no such explicit spelling disambiguates the shared identity.
            requested_matches = [item for item in exact_matches
                                 if item[0] == result["requestedName"]]
            # MEASURED 2026-09-19: the tag lookup returns the PARSER's own
            # identity, not the repository identity - for
            # GL20(GL20S)-4LC-PID under IO_MODULE_GL20 it answers
            # {type: 68, id: "100000_10F41053_Temperature Measure_10F41000",
            #  version: "0", deviceName: "GL20(GL20S)-4LC-PID"}, while the
            # installed catalog says {type: 41053, id: "10F4 1053",
            # version: "00.00.00.10"}.  Comparing the two id systems can never
            # succeed, which is why a real module kept failing with
            # no_exact_ethercat_tag_identity_match.  The native picker hands the
            # parser identity to CreateIoModuleAddAction, so for an EtherCAT
            # bus an identity whose deviceName equals the requested parser name
            # (under a documented tag) IS the exact parser identity.
            parser_identity_matches = [
                item for item in parser_name_matches
                if item[0] == result["requestedName"]]
            if (not requested_matches and parser_identity_matches
                    and result.get("matchedTag")):
                requested_matches = parser_identity_matches
                result["identityVerdictSource"] = (
                    "parser_tag_identity_matches_requested_name")
            selected_match = (requested_matches[0]
                              if len(requested_matches) == 1 else
                              (exact_matches[0] if len(exact_matches) == 1
                               else None))
            if selected_match is not None:
                result["exactMatch"] = True
                result["tagAware"] = True
                result["resolvedName"] = selected_match[0]
                result["resolvedIdentity"] = selected_match[1]
                result["selectionBasis"] = (
                    "explicit_requested_parser_name"
                    if requested_matches else "unique_identity_match")
            elif len(exact_matches) > 1:
                result["ambiguousMatches"] = [item[0] for item in exact_matches]
                result["reason"] = "multiple_exact_ethercat_tag_identity_matches"
            else:
                result["reason"] = "no_exact_ethercat_tag_identity_match"
            return result

        if io_enum_type is not None:
            for category in range(4):
                try:
                    category_value = System.Enum.ToObject(io_enum_type, category)
                    if bus_number == 4:
                        # No dedicated public list exists on this build; the
                        # generic list is still useful for exact identity
                        # matching and remains read-only.
                        values = parser.GetIoModuleList(category_value)
                    else:
                        values = parser.GetIoModuleList(category_value)
                    for value in list(values or []):
                        text_value = _text(value).strip()
                        if text_value and text_value not in names:
                            names.append(text_value)
                except Exception as exc:
                    result["attempts"].append({
                        "kind": "catalog_list", "category": category,
                        "ok": False, "error": repr(exc),
                    })
        result["candidateNames"] = names[:256]
        for candidate in names[:256]:
            try:
                bus_type = _reflection_type(
                    "Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
                bus_arg = (System.Enum.ToObject(bus_type, bus_number)
                           if bus_type is not None and bus_number is not None
                           else bus_number)
                value = parser.GetDeviceIdentificationFromIOModule(
                    candidate, bus_arg)
                observed = _config_identity_parts(value)
                attempt = {"kind": "identity_lookup", "name": candidate,
                           "ok": value is not None, "identity": observed}
                result["attempts"].append(attempt)
                if (value is not None and observed.get("type") == wanted.get("type")
                        and _text(observed.get("id")).strip().lower() ==
                            _text(wanted.get("id")).strip().lower()
                        and _text(observed.get("version")).strip().lower() ==
                            _text(wanted.get("version")).strip().lower()):
                    result["exactMatch"] = True
                    result["resolvedName"] = candidate
                    result["resolvedIdentity"] = observed
                    break
            except Exception as exc:
                result["attempts"].append({
                    "kind": "identity_lookup", "name": candidate,
                    "ok": False, "error": repr(exc),
                })
    except Exception as exc:
        result["error"] = repr(exc)
    if not result.get("exactMatch"):
        result["reason"] = "no exact parser module identity match"
    return result


def _io_module_cpu_family_gate(identity, module_name, module_model,
                                parent_model, parent_device_type, bus_value,
                                module_identity=None):
    """Apply the vendor ``HwDevTreeView.CheckDevIdentification`` family gate.

    This part is intentionally pure Python and has no CLR/parser dependency,
    so it can be exercised in host-side contract tests.  ``allowed=None``
    means the caller has not proved a local CPU parent; it is never promoted
    to a write permission.  The exact CPU-ID sets and GL10/GL20 rules mirror
    the decompiled V1.10 picker (``HwDevType == HDV_CPU``).
    """
    # ``identity`` is the *parent CPU* identity.  The candidate I/O identity
    # is optional and is used only to recover a GL-family label when the
    # parser/order name itself is terse.
    parts = (identity if isinstance(identity, dict)
             else _config_identity_parts(identity))
    module_parts = (module_identity if isinstance(module_identity, dict)
                    else _config_identity_parts(module_identity))
    module_text = " ".join([
        _text(module_parts.get("deviceName", "")),
        _text(module_name or ""), _text(module_model or "")]).upper()
    if "GL10" in module_text:
        module_family = "GL10"
    elif "GL20" in module_text:
        module_family = "GL20"
    else:
        module_family = "unknown"
    try:
        bus_number = int(bus_value)
    except Exception:
        bus_number = None
    try:
        parent_number = int(parent_device_type)
    except Exception:
        parent_number = None
    data = {
        "bus": bus_number,
        "parentDeviceType": parent_number,
        "moduleFamily": module_family,
        "module": _text(module_name or ""),
        "moduleModel": _text(module_model or ""),
        "parentModel": _text(parent_model or ""),
        "allowed": None,
        "reason": None,
    }
    if bus_number != 10:
        data["allowed"] = True
        data["reason"] = "exact_parser_identity_for_non_local_bus"
        return data
    if parent_number != 7:
        data["reason"] = "local_bus_parent_is_not_cpu"
        return data

    cpu_id = _text(parts.get("id", "")).strip().upper()
    cpu_type = parts.get("type")
    try:
        cpu_type = int(cpu_type)
    except Exception:
        cpu_type = None
    am7_ids = set(("10F4 0819", "10F4 081A", "10F4 082D", "10F4 082E",
                   "10F4 082F", "10F4 0831", "10F4 081B", "10F4 081C",
                   "10F4 081E", "10F4 081F", "10F4 081D"))
    am3_ids = set(("10F4 0030", "10F4 0054", "10F4 0051", "10F4 0058",
                   "10F4 005B", "10F4 005A", "10F4 0052", "10F4 0059",
                   "10F4 0031", "10F4 000A", "10F4 0056", "10F4 0053"))
    recognized = cpu_type == 4102 and (cpu_id in am7_ids or cpu_id in am3_ids)
    data["cpuFamily"] = ("AM7" if cpu_id in am7_ids else
                          "AM3_AM5" if cpu_id in am3_ids else "other")
    data["recognizedFamilyGate"] = recognized
    if recognized and module_family == "GL10":
        data["allowed"] = False
        data["reason"] = "vendor_iomodule_tool_rejects_gl10_on_am3_am7_cpu"
        return data
    if not recognized and module_family == "GL20":
        data["allowed"] = False
        data["reason"] = "vendor_iomodule_tool_requires_known_am_cpu_for_gl20"
        return data
    data["allowed"] = True
    data["reason"] = "vendor_cpu_family_gate_allows_module"
    return data


def _io_module_hw_dev_type_gate(module_family, hw_dev_type,
                                parent_device_type, bus_value):
    """Check the native ``HwDevType`` used for local GL modules.

    The AM600 picker constructs both GL10 and GL20 local-bus nodes as
    ``HDV_DATAMODULE`` (numeric value 2).  Passing the temperature enum (5)
    can still create a short-lived in-memory row, but the row is not written
    to the project archive.  Keep this check pure and before action creation
    so that callers receive a deterministic, non-mutating rejection.  Other
    buses have their own native type selection and are intentionally outside
    this local-only gate.
    """
    def as_int(value):
        try:
            return int(value)
        except Exception:
            text_value = _text(value).strip().upper()
            names = {
                "HDV_DATAMODULE": 2,
                "HDV_TEMPERATUREMODULE": 5,
                "HDV_CPU": 7,
                "HDV_ETHERCAT_MODULE": 10,
            }
            return names.get(text_value)

    bus_number = as_int(bus_value)
    parent_number = as_int(parent_device_type)
    actual_number = as_int(hw_dev_type)
    family = _text(module_family or "").strip().upper()
    result = {
        "bus": bus_number,
        "parentDeviceType": parent_number,
        "moduleFamily": family or "unknown",
        "expectedHwDevType": None,
        "actualHwDevType": actual_number,
        "allowed": True,
        "reason": "non_local_or_unknown_module_family",
    }
    if bus_number == 10 and parent_number == 7 and family in ("GL10", "GL20"):
        result["expectedHwDevType"] = 2
        if actual_number is None:
            result["allowed"] = False
            result["reason"] = "hw_dev_type_unavailable_expected_hdv_datamodule_2"
        elif actual_number != 2:
            result["allowed"] = False
            result["reason"] = "hw_dev_type_mismatch_expected_hdv_datamodule_2"
        else:
            result["reason"] = "local_gl_module_uses_hdv_datamodule_2"
    return result


def _io_module_topology_preflight(parser, identity, module_name, module_model,
                                  bus_value, parent_model, parent_identity,
                                  parent_device_type, root_cpu_identity=None,
                                  parser_tag=None, parser_resolution=None):
    """Mirror the vendor IOModuleTool gate without constructing an action.

    The four-argument ``IoModuleMatchParentDevice`` predicate is a *branch
    selector* used by ``DigitalModule``/``TemperatureModule`` to choose local
    versus EtherCAT parameter initialization.  A false predicate therefore is
    not an incompatibility signal.  The actual UI admission gate is the CPU
    family/module-family check in ``IOModuleTool`` plus exact parser identity
    resolution; this helper models that gate and reports its evidence.
    """
    data = {
        "bus": None,
        "parentDeviceType": None,
        "parentModel": _text(parent_model or ""),
        "parentIdentity": parent_identity or {},
        "rootCpuIdentity": root_cpu_identity or {},
        "parserTag": _text(parser_tag or "").strip(),
        "module": _text(module_name or ""),
        "moduleModel": _text(module_model or ""),
        "moduleFamily": "unknown",
        "allowed": None,
        "reason": None,
        "limitedModule": None,
        "limitedModuleChecked": False,
    }
    try:
        data["bus"] = int(bus_value)
    except Exception:
        data["bus"] = None
    try:
        data["parentDeviceType"] = int(parent_device_type)
    except Exception:
        data["parentDeviceType"] = None
    # EtherCAT I/O modules are children of the selected DEVTYPE=10
    # coupler/slave.  ``FindSpecialDevice`` has a compatibility fallback to
    # the local CPU for some rack/slot combinations; accepting that CPU here
    # would silently attach an ECT module to the wrong bus.  Require the
    # actual coupler parent before any parser or action work is considered.
    if data.get("bus") == 3 and data.get("parentDeviceType") != 10:
        data["reason"] = "ethercat_parent_is_not_coupler"
        return None, data
    resolution = parser_resolution or _parser_io_module_resolution(
        parser, identity, data["bus"], module_name,
        data["parentDeviceType"], data.get("parserTag"))
    data["parserResolution"] = resolution
    parser_name = _text(resolution.get("resolvedName") or "")
    identity_parts = _config_identity_parts(identity)
    family_gate = _io_module_cpu_family_gate(
        parent_identity, module_name, module_model, parent_model,
        parent_device_type, bus_value,
        module_identity=dict(identity_parts, deviceName=" ".join([
            parser_name, identity_parts.get("deviceName", "")]).strip()))
    data.update(family_gate)

    # An exact parser identity is mandatory.  It is the same object selected
    # by the native tree picker; a generic repository row (or a type-68
    # EtherCAT identity supplied for a local slot) is never promoted.
    if not resolution.get("exactMatch"):
        data["reason"] = "parser_identity_not_resolved"
        return None, data

    # The local-bus picker gate is specific to a CPU parent.  For other buses
    # the exact parser identity is the strongest available admission proof;
    # the native bus-specific action will still perform its own slot checks.
    if data["allowed"] is None:
        return None, data
    if data["allowed"] is False:
        return False, data

    # EtherCAT admission has two additional native checks that are independent
    # of the local CPU-family classifier: the selected coupler must support
    # the exact module identity and the root CPU/module pair must not be in
    # the vendor's limited table.  Both are read-only and must complete before
    # an action is constructed.  Unknown tag/coupler state fails closed.
    if data.get("bus") == 3:
        ethercat_match, ethercat_details = _io_module_ethercat_gate(
            parser, parent_identity, root_cpu_identity,
            identity, data.get("parserTag"))
        data["ethercatGate"] = ethercat_details
        data["couplerSupport"] = ethercat_details.get("couplerSupport")
        data["limitedModule"] = ethercat_details.get("limitedModule")
        data["limitedModuleChecked"] = ethercat_details.get(
            "limitedModuleChecked", False)
        if ethercat_match is None:
            data["reason"] = ethercat_details.get(
                "reason") or "ethercat_gate_unavailable"
            return None, data
        if ethercat_match is False:
            data["reason"] = ethercat_details.get(
                "reason") or "ethercat_gate_rejected"
            return False, data
        return True, data

    parent_parts = (parent_identity if isinstance(parent_identity, dict)
                    else _config_identity_parts(parent_identity))
    if not parent_parts.get("id"):
        parent_parts = _config_identity_parts(parent_identity)
    cpu_id = _text(parent_parts.get("id") or "").strip().upper()
    am7_ids = set(("10F4 0819", "10F4 081A", "10F4 082D", "10F4 082E",
                   "10F4 082F", "10F4 0831", "10F4 081B", "10F4 081C",
                   "10F4 081E", "10F4 081F", "10F4 081D"))

    # AM600IoModuleListForm calls IsLimitedModule for every recognized
    # hdt7/type4102 CPU family (high and low IDs), not only AM7.  A positive
    # result is a hard native rejection; AM320's current catalog returns
    # false, but keeping the call here prevents future LimitedDevice entries
    # from being bypassed.
    if data.get("recognizedFamilyGate"):
        try:
            module_id = identity_parts.get("id")
            limited = parser.IsLimitedModule(cpu_id, module_id, False)
            data["limitedModule"] = bool(limited)
            data["limitedModuleChecked"] = True
            if bool(limited):
                data["allowed"] = False
                data["reason"] = "vendor_is_limited_module"
                return False, data
        except Exception as exc:
            data["limitedModuleError"] = repr(exc)
    return True, data


def _io_module_add_preflight(parser, identity, module_name, module_model,
                             digital_hw, hardware, parent, before, req):
    """Collect the complete read-only admission proof for one I/O add.

    This is deliberately a top-level helper.  ``device_config_io_add`` is
    executed by IronPython 2.7, whose nested-function closure tuple is capped
    at 128 cells; keeping the topology probe outside that large transaction
    handler avoids turning a diagnostic variable into a runtime compile
    failure.  The returned dictionary contains only evidence and values that
    the caller may pass to the native action after the gate succeeds.
    """
    bus_value = int(req.get("bus", 10))
    # Snapshot the *selected* parent before resolving the parser name.  For
    # bus=3 this is the EtherCAT coupler/slave (DEVTYPE=10), while the CPU is
    # retained separately for the limited-module gate.
    parent_context = _io_module_parent_context(
        hardware, parent, before, bus_value)
    parent_model = parent_context.get("parentModel") or ""
    parent_identity_data = parent_context.get("parentIdentity") or {}
    parent_device_type_value = parent_context.get("parentDeviceType")
    parser_tag = parent_context.get("parserTag")
    parser_resolution = _parser_io_module_resolution(
        parser, identity, bus_value, module_name,
        parent_device_type_value, parser_tag)
    parser_module_name = _text(parser_resolution.get("resolvedName") or "") or None
    if not parser_module_name and _text(module_name).strip().lower() in VERIFIED_MODULE_ALIASES:
        parser_module_name = _text(
            VERIFIED_MODULE_ALIASES[_text(module_name).strip().lower()].get(
                "parserName") or module_name).strip() or None

    topology_match, topology_details = _io_module_topology_preflight(
        parser, identity, module_name, module_model, bus_value,
        parent_model, parent_identity_data, parent_device_type_value,
        parent_context.get("rootCpuIdentity"), parser_tag,
        parser_resolution)
    # ``HwDevType`` is an independent native admission condition.  In
    # particular, a GL20 local module may satisfy the CPU-family gate while a
    # caller accidentally supplies HDV_TEMPERATUREMODULE=5; that combination
    # produces a transient row which cannot be archived.  Evaluate it before
    # any action is constructed and fold only a negative verdict into the
    # write admission result.
    hw_type_details = _io_module_hw_dev_type_gate(
        topology_details.get("moduleFamily") if isinstance(topology_details, dict)
        else None,
        digital_hw, parent_device_type_value, bus_value)
    hw_type_match = hw_type_details.get("allowed")
    if isinstance(topology_details, dict):
        topology_details["hwDevTypeGate"] = hw_type_details
    if hw_type_match is False:
        topology_match = False
    if topology_match is None or topology_match is False:
        # A failed/unavailable identity, parent, or HwDevType gate already
        # determines the outcome.  Do not spend another batch of native
        # predicate calls merely to decorate a rejection; this is a common
        # source of noisy retries in the E2E driver.
        predicate_match = None
        compatibility_attempts = [{
            "kind": "predicate_skipped",
            "reason": "topology_or_hw_type_gate_not_admissible",
        }]
    else:
        predicate_match, compatibility_attempts = _io_module_parent_compatibility(
            parser, identity, module_name, digital_hw, parent_model,
            module_model=module_model, bus_value=bus_value,
            parent_device_type=parent_device_type_value,
            parser_module_name=parser_module_name)
    return {
        "parserResolution": parser_resolution,
        "parserModuleName": parser_module_name,
        "parentModel": parent_model,
        "parentDeviceType": parent_device_type_value,
        "parentDeviceTypeValue": parent_device_type_value,
        "bus": bus_value,
        "parentIdentity": parent_identity_data,
        "rootCpuIdentity": parent_context.get("rootCpuIdentity") or {},
        "parentContext": parent_context,
        "parserTag": parser_tag,
        "topologyMatch": topology_match,
        "topologyDetails": topology_details,
        "hwDevTypeMatch": hw_type_match,
        "hwDevTypeDetails": hw_type_details,
        "predicateMatch": predicate_match,
        "compatibilityAttempts": compatibility_attempts,
        "identitySnapshot": _config_identity_parts(identity),
    }


def _io_module_parent_compatibility(parser, identity, module_name,
                                    hw_type, parent_model=None,
                                    module_model=None, bus_value=None,
                                    parent_device_type=None,
                                    parser_module_name=None):
    """Run InoProShop's read-only module/parent predicate before mutation.

    The four-argument overload is a branch selector used by the native module
    classes (local versus EtherCAT initialization), not the complete picker
    admission gate.  The direct I/O picker passes the exact parser/tree
    ``moduleName`` (case-sensitive, hyphens preserved); another synchronization
    path may pass an order number with hyphens replaced by underscores.  Probe
    both forms for diagnostics, but let ``_io_module_topology_preflight``
    decide whether a write is allowed.  In particular, a false predicate is
    valid for a local AM320 GL20 module and must not be treated as rejection.

    ``attempts`` deliberately records every bounded, read-only predicate call
    (at most five tag checks for each relevant parent type/model).  These are
    diagnostics, not mutation retries.  A false result is trusted only when
    the vendor four-argument overload is available and all required calls
    completed; otherwise the caller receives ``None`` and fails closed with an
    ``io_topology_preflight_unavailable`` error.
    """
    import System
    flags = (System.Reflection.BindingFlags.Instance |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    methods_by_arity = {3: [], 4: []}
    try:
        for method in parser.GetType().GetMethods(flags):
            if _text(method.Name) != "IoModuleMatchParentDevice":
                continue
            arity = len(method.GetParameters())
            if arity in methods_by_arity:
                methods_by_arity[arity].append(method)
        for arity in methods_by_arity:
            methods_by_arity[arity].sort(key=lambda item: _text(item.ToString()))
    except Exception:
        methods_by_arity = {3: [], 4: []}

    attempts = []

    # Preserve exact parser names.  Do not canonicalize hyphens here: the
    # vendor ModuleInfos indexer uses ordinal string comparison.  The action
    # selector/order number is kept separately by the caller and must never
    # become a predicate argument.
    models = []
    value = _text(parser_module_name).strip()
    if value:
        models.append(value)
    if not models:
        return None, [{
            "kind": "model_resolution",
            "ok": False,
            "error": "catalog order number/model is unavailable",
        }]

    def as_int(value):
        try:
            return int(value)
        except Exception:
            try:
                return int(_get_member(value, "value", "Value", "get_Value"))
            except Exception:
                return None

    bus_number = as_int(bus_value)
    parent_number = as_int(parent_device_type)
    module_number = as_int(hw_type)
    # The enum values are vendor-defined; 7 is HDV_CPU and 10 is the
    # EtherCAT/special-module parent family in the decompiled picker.  We only
    # use 7 when the caller supplied an explicit CPU parent identity; no
    # module type is silently substituted for the parent type.
    parent_candidates = []
    if parent_number is not None:
        parent_candidates.append(parent_number)
    # DigitalModule's native InitModuleConfigurationBaseInfo and
    # AddDeviceConfigurationData do not select the overload by bus number.
    # They always test the five type-10 tags first, then (when those do not
    # match) the type-7/parent ``IO_MODULE`` tag.  A previous implementation
    # only tested type 10 for bus=3, which falsely rejected GL20 modules on an
    # AM320 local bus (bus=10).  Keep the bus observations for diagnostics,
    # but mirror the vendor decision tree for every bus.
    if 10 not in parent_candidates:
        parent_candidates.append(10)
    tags = ("IO_MODULE", "IO_MODULE_STD", "IO_MODULE_EXT",
            "IO_MODULE_GL20", "IO_MODULE_GL20_old")

    def enum_for(method, value):
        params = method.GetParameters()
        if len(params) < 3:
            return value
        param_type = params[2].ParameterType
        try:
            if param_type.IsEnum:
                return System.Enum.ToObject(param_type, int(value))
        except Exception:
            pass
        return value

    def invoke(method, model, parent_type, tag, arity):
        entry = {
            "kind": "predicate",
            "arity": arity,
            "binding": _text(method.ToString()),
            "model": model,
            "parentType": parent_type,
        }
        if tag is not None:
            entry["tag"] = tag
        try:
            typed_parent = enum_for(method, parent_type)
            if arity == 4:
                args = [identity, model, typed_parent, tag]
            else:
                args = [identity, model, typed_parent]
            value = method.Invoke(parser, System.Array[System.Object](args))
            entry["ok"] = True
            entry["matched"] = bool(value)
        except Exception as exc:
            entry["ok"] = False
            entry["error"] = repr(exc)
        attempts.append(entry)
        return entry

    four_arg_methods = methods_by_arity.get(4) or []
    three_arg_methods = methods_by_arity.get(3) or []
    if four_arg_methods and parent_candidates:
        # Match the exact order used by DigitalModule.InitModule... and
        # AddDeviceConfigurationData: type 10 is tested with all tags, then
        # the parent DEVTYPE (normally 7 for a CPU) with IO_MODULE.  The
        # native code applies this sequence for both bus=10 and bus=3.
        for model in models:
            for tag in tags:
                invoke(four_arg_methods[0], model, 10, tag, 4)
            if parent_number is not None and parent_number != 10:
                invoke(four_arg_methods[0], model, parent_number, "IO_MODULE", 4)
        successful = [item for item in attempts
                      if item.get("kind") == "predicate" and item.get("ok")]
        if not successful:
            return None, attempts
        type10_io_match = any(item.get("matched") and
                              item.get("parentType") == 10 and
                              item.get("tag") == "IO_MODULE"
                              for item in successful)
        type10_special_match = any(item.get("matched") and
                                   item.get("parentType") == 10 and
                                   item.get("tag") in tags[1:]
                                   for item in successful)
        # Preserve the historical field name for downstream evidence while
        # making its meaning explicit: any type-10 tag is the native
        # EtherCAT/special-module branch.
        ethercat_match = type10_io_match or type10_special_match
        local_match = any(item.get("matched") and
                          item.get("parentType") == parent_number and
                          item.get("tag") == "IO_MODULE" for item in successful)
        # This is the exact DigitalModule predicate, not a bus heuristic:
        # type-10 IO_MODULE wins; otherwise a type-7/local match is valid only
        # when none of the type-10 specialised tags matched.
        native_module_match = type10_io_match or (
            not type10_special_match and local_match)
        if bus_number == 10:
            # Keep an explicit bus=10 branch for the audit contract; the
            # vendor implementation still permits its type-10 GL20 path.
            matched = native_module_match
        elif bus_number == 3:
            matched = native_module_match
        else:
            matched = native_module_match
        attempts.append({
            "kind": "predicate_summary",
            "ok": True,
            "bus": bus_number,
            "moduleType": module_number,
            "parentType": parent_number,
            "ethercatMatch": ethercat_match,
            "localMatch": local_match,
            "type10IoModuleMatch": type10_io_match,
            "type10SpecialMatch": type10_special_match,
            "nativeModuleMatch": native_module_match,
            "matched": matched,
            "models": models,
            "tags": list(tags),
        })
        return matched, attempts

    # A vendor build without IConfigDevTreeFileParser1 cannot be safely
    # classified.  Keep one legacy call for observability only; its false
    # result must never reject a module when the four-argument contract is
    # absent because its semantics are not equivalent.
    if three_arg_methods and parent_number is not None:
        for model in models:
            invoke(three_arg_methods[0], model, parent_number, None, 3)
    attempts.append({
        "kind": "predicate_summary",
        "ok": False,
        "reason": "four_argument_overload_or_parent_type_unavailable",
        "fourArgumentOverload": bool(four_arg_methods),
        "parentType": parent_number,
        "models": models,
    })
    return None, attempts


_IO_MODULE_PARENT_DEVTYPE = {
    1: 11,   # DBT_MODBUS      -> HDV_MODBUS_MODULE
    2: 9,    # DBT_CANOPEN     -> HDV_CANOPEN_MODULE
    3: 10,   # DBT_ETHERCAT    -> HDV_ETHERCAT_MODULE
    4: 8,    # DBT_DP          -> HDV_DP_MODULE
    6: 13,   # DBT_MODBUS_TCP  -> HDV_MODBUS_TCP
    11: 16,  # DBT_ETHERNETIP  -> HDV_ETHERNETIP
    16: 22,  # DBT_PROFINET    -> HDV_PROFINET
}


def _io_module_parent_for_bus(hardware, local_bus, bus_value, rack, slot, port,
                              result):
    """Resolve the module's parent for the local bus and for network buses.

    TOP-LEVEL ON PURPOSE.  `device_config_io_add` sits at IronPython's 128
    closure-cell limit; inlining this logic there made the IDE raise a native
    dialog ("运行 persistent_bridge.py 引起的异常 System.ArgumentException:
    MutableTuple`128[ClosureCell...]") which then blocked the whole bridge
    (measured 2026-09-19).

    The admission gate in `_io_module_topology_preflight` requires the parent's
    HwDevType to match the bus (bus 3 -> HDV_ETHERCAT_MODULE = 10), so a lookup
    that falls back to the CPU must be rejected HERE with a typed error instead
    of being handed to the gate, which would only answer
    io_topology_preflight_unavailable.
    """
    if int(bus_value) == 10:
        # Local bus keeps its verified path unchanged.
        return hardware.FindSpecialDevice(rack, 0, local_bus, port)
    required = _IO_MODULE_PARENT_DEVTYPE.get(int(bus_value))
    candidates = []
    for accessor in ("GetTheFirstDev", "GetLastDev", "GetCurSelectedDevice"):
        finder = getattr(hardware, accessor, None)
        if not hasattr(finder, "__call__"):
            continue
        try:
            candidate = finder(local_bus, port)
        except Exception as exc:
            result["attempts"].append({"binding": accessor, "ok": False,
                                       "error": repr(exc)})
            continue
        if candidate is not None:
            candidates.append(candidate)
    try:
        for candidate in list(hardware.GetDeviceList(0, local_bus, port)):
            candidates.append(candidate)
    except Exception as exc:
        result["attempts"].append({"binding": "GetDeviceList", "ok": False,
                                   "error": repr(exc)})
    found = []
    chosen = None
    without_identity = None
    for candidate in candidates:
        raw_type = _get_member(candidate, "DEVTYPE", "get_DEVTYPE", None)
        type_value = None
        try:
            # IronPython stringifies the enum as its NAME ("HDV_ETHERCAT_MODULE"),
            # so the numeric comparison must happen on the enum object itself -
            # comparing the text against the integer 10 never matched
            # (measured 2026-09-19: three real couplers were listed and still
            # reported as "no parent of the required type").
            type_value = int(raw_type)
        except (TypeError, ValueError):
            type_value = None
        entry = {
            "deviceType": _text(raw_type),
            "deviceTypeValue": type_value,
            "model": _text(_get_member(candidate, "DevModel", "get_DevModel", "")),
            "rack": _text(_get_member(candidate, "RACKNO", "get_RACKNO", "")),
            "slot": _text(_get_member(candidate, "SLOTNO", "get_SLOTNO", "")),
        }
        # A coupler node whose Identification is empty cannot key the vendor's
        # tag-aware parser lookup (measured 2026-09-19: the chosen node came
        # back with parentModel="" and the gate then answered
        # no_exact_ethercat_tag_identity_match).  Prefer a node that carries an
        # identity and keep the identity-less one only as a fallback.
        identification = _get_member(candidate, "Identification", "get_Identification")
        identity_parts = _config_identity_parts(identification)
        entry["identificationId"] = _text(identity_parts.get("id") or "")
        entry["identificationName"] = _text(identity_parts.get("deviceName") or "")
        found.append(entry)
        if (chosen is None and required is not None and type_value is not None
                and type_value == int(required)):
            if entry["identificationId"]:
                chosen = candidate
                entry["chosen"] = True
                entry["chosenReason"] = "identity_present"
                break
            if without_identity is None:
                without_identity = (candidate, entry)
    if chosen is None and without_identity is not None:
        chosen = without_identity[0]
        without_identity[1]["chosen"] = True
        without_identity[1]["chosenReason"] = "fallback_identity_empty"
    fill_markers = {}
    if chosen is not None:
        # The coupler's native Identification can carry an id with an EMPTY
        # DeviceName, and the vendor's tag-aware parser lookup then answers
        # no_exact_ethercat_tag_identity_match even though everything else
        # matches (measured 2026-09-19: parentModel="" while the id was the
        # catalog id of the slave this route created).  Fill the name from the
        # uniquely resolved installed catalog row - the same pattern
        # vendor_ethercat_slave_add already uses for the module identity.
        chosen_identity = _get_member(chosen, "Identification", "get_Identification")
        parts = _config_identity_parts(chosen_identity)
        if chosen_identity is not None and not _text(parts.get("deviceName") or ""):
            wanted_id = _text(parts.get("id") or "").strip().lower()
            filled = None
            if wanted_id:
                for _raw, item in _installed_device_entries():
                    device_id = item.get("deviceId") or {}
                    if _text(device_id.get("id") or "").strip().lower() == wanted_id:
                        filled = _text(item.get("name") or "")
                        break
            if filled:
                try:
                    chosen_identity.DeviceName = filled
                    fill_markers["identityNameFilledFromCatalog"] = filled
                except Exception as exc:
                    fill_markers["identityNameFillError"] = repr(exc)
    if chosen is not None:
        result["parentResolution"] = {
            "bus": int(bus_value), "port": port,
            "requiredHwDevType": required,
            "found": found[:8],
        }
        result["parentResolution"].update(fill_markers)
        return chosen
    raise OperationError(
        "no module parent of the type this bus requires was found "
        "(bus %d needs HwDevType %s)" % (int(bus_value), required),
        "io_module_parent_not_coupler",
        {"bus": int(bus_value), "port": port, "rack": rack, "slot": slot,
         "requiredHwDevType": required, "found": found[:8],
         "mutatedProject": False,
         "next": {
             "tool": "inoproshop_ethercat_slave_add" if int(bus_value) == 3
                     else "inoproshop_device_config_io_add",
             "then": "create the network slave on this bus first (for EtherCAT "
                     "use inoproshop_ethercat_slave_add), then attach the module "
                     "to it; the admission gate refuses a parent whose DevType "
                     "does not match the bus",
         }})


def _place_io_module_in_project_tree(hardware, parent, rack, bus, port,
                                     wanted_type, wanted_id):
    """Vendor UI parity for a network-bus I/O module (decompiled recipe).

    InoDeviceConfigurationManagement/IoModuleAddAction: Execute() and
    Execute(bool) create the config-graph device and its device-object data, but
    the PROJECT-TREE placement is the editor framework's step - only ReDo()
    performs

        _hwConfigProj.AddDev(_addedDevice);
        SystemInstances.ObjectMgr.MoveObject(project.Handle,
                                             addedDevice.Identification.DevGuid,
                                             _parentDeviceGuid,
                                             addedDevice.Identification.InsertIndex);

    Measured 2026-09-19 (EtherCAT module add): calling the action directly left
    the module visible only in the in-session graph (sameInstanceReadback
    rackIoModuleNum=1) while commitReadback reported objectTreeMatchCount=0 and
    the reloaded config matched nothing - so the compile still said the slave has
    no module. This helper performs that missing placement step.
    """
    import System
    result = {"attempted": True}
    try:
        rows = list(hardware.GetDeviceList(rack, bus, port))
    except Exception as exc:
        rows = []
        result["deviceListError"] = repr(exc)
    result["candidateCount"] = len(rows)
    added = None
    for candidate in rows:
        identity = _get_member(candidate, "Identification", "get_Identification")
        candidate_id = _text(_get_member(identity, "Id", "get_Id"))
        if wanted_id and candidate_id == wanted_id:
            added = candidate
            break
    if added is None and rows:
        added = rows[-1]
        result["selectionFallback"] = "last_device_in_list"
    if added is None:
        result["status"] = "module_not_found_in_graph"
        result["nextRequired"] = (
            "the native action did not leave a device row in the config graph")
        return result
    identity = _get_member(added, "Identification", "get_Identification")
    device_guid = _get_member(identity, "DevGuid", "get_DevGuid")
    insert_index = _get_member(identity, "InsertIndex", "get_InsertIndex")
    result["deviceIdentification"] = {
        "type": _text(_get_member(identity, "Type", "get_Type")),
        "id": _text(_get_member(identity, "Id", "get_Id")),
        "devGuid": _text(device_guid),
    }
    try:
        add_result = hardware.AddDev(added)
        result["addDev"] = {"ok": True, "result": _json_safe(add_result)}
    except Exception as exc:
        result["addDev"] = {"ok": False, "error": repr(exc)}
    try:
        parent_identity = _get_member(parent, "Identification", "get_Identification")
        parent_guid = _get_member(parent_identity, "DevGuid", "get_DevGuid")
        system_instances = _reflection_type(
            "_3S.CoDeSys.Core.SystemInstances, Core")
        if system_instances is None:
            raise RuntimeError("SystemInstances type is unavailable")
        object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
        engine = system_instances.GetProperty("Engine").GetValue(None, None)
        core_projects = _get_member(engine, "Projects", "get_Projects")
        primary = _get_member(core_projects, "PrimaryProject", "get_PrimaryProject")
        handle = int(primary.Handle)
        move_result = object_mgr.MoveObject(handle, device_guid, parent_guid,
                                            insert_index)
        result["moveObject"] = {
            "ok": True, "result": _json_safe(move_result), "handle": handle,
            "parentGuid": _text(parent_guid),
            "insertIndex": _json_safe(insert_index)}
    except Exception as exc:
        result["moveObject"] = {"ok": False, "error": repr(exc)}
    if _text(device_guid) in ("", "00000000-0000-0000-0000-000000000000"):
        result["status"] = "placement_blocked_by_empty_devguid"
        result["boundary"] = (
            "The created module carries NO project-object GUID, so the vendor "
            "action's CopyDeviceObjectToStream() silently skips (decompiled "
            "ConfigAction.cs: it returns early when deviceObjectGuid == "
            "Guid.Empty) and the module never reaches the object tree. The "
            "vendor's own programmatic recipe (decompiled CommonFunc.AddHdDev) "
            "creates the module's PROJECT OBJECT first and then stamps "
            "devIdentification.DevGuid = mo.ObjectGuid plus "
            "devIdentification.InsertIndex = "
            "IHardwareConfigProj2.CalInsertIndexOfIOModule(rack, slot, bus) "
            "before calling CreateIoModuleAddAction(...).Execute(false).")
        result["nextRequired"] = (
            "create the module's project object through the vendor device-object "
            "path (the AddHdDev recipe above), then repeat the add; until then "
            "treat a network-bus module attach as NOT DONE")
    else:
        result["status"] = "placement_attempted"
    return result


def device_config_io_add(req):
    """Execute one native Inovance I/O add action on a disposable project."""
    _require_project()
    _require_current_disposable_project(req, "device.config.io.add")
    if _text(req.get("confirm")) != "add_io_module":
        raise OperationError("device.config.io.add requires confirm=add_io_module",
                             "confirmation_required")
    result = {"mutatedProject": False, "operation": "device.config.io.add",
              "attempts": [],
              # Copied into every failure payload: before this, a native
              # failure reported module/identity/rack/slot/bus/port as null
              # because it read result["inputs"], which was never populated.
              "inputs": {
                  "module": _text(req.get("module") or req.get("moduleName") or ""),
                  "bus": int(req.get("bus", 10)),
                  "rack": int(req.get("rack", 1)),
                  "slot": int(req.get("slot", 1)),
                  "port": int(req.get("port", 0)),
              }}
    diagnose = bool(req.get("diagnose", False))
    # `before` stays a local regardless: the post-execute verification gates
    # (before/after config row matching) need it. It only lands in the
    # RESPONSE payload under diagnose=true.
    before = device_config_graph_probe({})
    if diagnose:
        result["before"] = before
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    sync_project = factory.CreateConfigSyncProj()

    def archive_state(storage):
        if storage is None:
            return {"present": False}
        state = {"present": True, "runtimeType": _text(storage.GetType().FullName)}
        for key, name in (("hardwareBytes", "HardwareConfigurationData"),
                          ("networkBytes", "NetworkConfigurationData")):
            try:
                prop = storage.GetType().GetProperty(name)
                value = prop.GetValue(storage, None) if prop is not None else None
                state[key] = len(value) if value is not None else None
            except Exception as exc:
                state[key + "Error"] = repr(exc)
        return state

    def invoke_internal(value, name, arguments):
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Public |
                 System.Reflection.BindingFlags.NonPublic)
        methods = [method for method in value.GetType().GetMethods(flags)
                   if method.Name == name and len(method.GetParameters()) == len(arguments)]
        if not methods:
            raise RuntimeError("method unavailable: " + name)
        args = System.Array[System.Object](arguments)
        return methods[0].Invoke(value, args)

    def set_internal_property(value, name, member_value):
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Public |
                 System.Reflection.BindingFlags.NonPublic)
        prop = value.GetType().GetProperty(name, flags)
        if prop is None:
            raise RuntimeError("property unavailable: " + name)
        prop.SetValue(value, member_value, None)

    def internal_shape(value):
        if value is None:
            return None
        result = {"runtimeType": _text(value.GetType().FullName)}
        try:
            import System
            flags = (System.Reflection.BindingFlags.Instance |
                     System.Reflection.BindingFlags.Public |
                     System.Reflection.BindingFlags.NonPublic)
            members = []
            for method in value.GetType().GetMethods(flags):
                name = _text(method.Name)
                if any(token in name.lower() for token in
                       ("sync", "config", "archive", "save", "update", "stream", "object")):
                    members.append(_text(method.ToString()))
            result["methods"] = sorted(set(members))[:500]
            properties = []
            property_types = {}
            for prop in value.GetType().GetProperties(flags):
                name = _text(prop.Name)
                if any(token in name.lower() for token in
                       ("project", "core", "inner", "target", "object", "service", "meta")):
                    properties.append(name)
                    property_types[name] = _text(prop.PropertyType.FullName)
            result["properties"] = sorted(set(properties))[:300]
            result["propertyTypes"] = property_types
            result["interfaces"] = sorted(set(_text(item.FullName)
                                               for item in value.GetType().GetInterfaces()))[:300]
        except Exception as exc:
            result["reflectionError"] = repr(exc)
        return result

    if diagnose:
        result["syncProjectInternal"] = internal_shape(sync_project)
        result["scriptProjectInternal"] = internal_shape(project)
        project_candidates = {}
        for name in ("Project", "CoreProject", "InnerProject", "TargetObject", "Object", "MetaObject", "Extender", "project", "core_project"):
            try:
                import System
                flags = (System.Reflection.BindingFlags.Instance |
                         System.Reflection.BindingFlags.Public |
                         System.Reflection.BindingFlags.NonPublic)
                prop = project.GetType().GetProperty(name, flags)
                candidate = prop.GetValue(project, None) if prop is not None else _get_member(project, name, "get_" + name)
                project_candidates[name] = {
                    "present": candidate is not None,
                    "runtimeType": _text(candidate.GetType().FullName) if candidate is not None else None,
                }
            except Exception as exc:
                project_candidates[name] = {"present": False, "error": repr(exc)}
        result["scriptProjectCandidates"] = project_candidates
    try:
        sync_project.StartSyncToConfigrationDataObject()
        result["syncStart"] = {"called": True, "ok": True}
    except Exception as exc:
        result["syncStart"] = {"called": True, "ok": False, "error": repr(exc)}
    hardware = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
    if hardware is None:
        try:
            import System
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject" and len(m.GetParameters()) == 2]
            if methods:
                args = System.Array[System.Object]([None, None])
                methods[0].Invoke(sync_project, args)
                hardware = args[0]
        except Exception:
            hardware = None
    if hardware is None:
        raise OperationError("hardware configuration object is unavailable",
                             "hardware_configuration_unavailable")
    try:
        storage = hardware.GetConfigStorageObj()
        if diagnose:
            result["configStorageBefore"] = archive_state(storage)
            result["hardwareInternal"] = internal_shape(hardware)
            result["configStorageInternal"] = internal_shape(storage)
        if storage is not None:
            sync_project.AttachToConfigrationObjectData(storage)
            result["configAttach"] = {
                "called": True,
                "ok": True,
                "runtimeType": _text(storage.GetType().FullName),
            }
            refreshed = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
            if refreshed is not None:
                hardware = refreshed
            try:
                sync_project.StartSyncToConfigrationDataObject()
                result["syncAfterAttach"] = {"called": True, "ok": True}
                refreshed = _get_member(sync_project, "hardware_config_project", "get_HardwareConfigProject")
                if refreshed is not None:
                    hardware = refreshed
            except Exception as exc:
                result["syncAfterAttach"] = {"called": True, "ok": False, "error": repr(exc)}
        else:
            result["configAttach"] = {"called": True, "ok": False, "error": "GetConfigStorageObj returned None"}
    except Exception as exc:
        result["configAttach"] = {"called": True, "ok": False, "error": repr(exc)}
    parser_factory, parser_binding = _reflection_generic_create(
        "Inovance.InoPro.InoDeviceConfiguration.IDevTreeFileParserFactory, InoDeviceConfiguration",
        "{669014F5-D843-4E51-962E-1386A8828EBE}")
    parser = parser_factory.CreateDeviceTreeParser()
    action_factory, action_binding = _reflection_generic_create(
        "Inovance.InoPro.InoDeviceConfiguration.IIoModuleAddActionFactory, InoDeviceConfiguration",
        "{0AD367FC-6F6B-44E4-B1D9-F1DFFCDC92FA}")
    identifier = _text(req.get("id") or "100000_10F40210_Digital In_AM600-1600END")
    module_name = _text(req.get("module") or "GL10_1600END")
    # STRICT IDENTITY PRE-CHECK (measured 2026-09-19): passing the catalog
    # DISPLAY name (e.g. "GL10 16点DI模块", which exists twice in the catalog)
    # used to reach the native action and come back as
    # `native_io_add_failed: SystemError('序列不包含任何元素')` - an untyped
    # vendor LINQ error. Resolve the name here the way device.add does: zero
    # matches and ambiguity both become typed, actionable errors, and the
    # explicit type/id form bypasses the name lookup entirely.
    if not (req.get("type") is not None or req.get("id") is not None):
        token = _text(module_name).strip().lower()
        name_matches = []
        for _raw, item in _installed_device_entries():
            device_id = item.get("deviceId") or {}
            if int(device_id.get("type") or 0) < 40000:
                continue
            names = [_text(item.get("name")).strip().lower(),
                     _text(item.get("orderNumber")).strip().replace("-", "_").lower(),
                     _text(item.get("orderNumber")).strip().lower()]
            if token and token in [name for name in names if name]:
                name_matches.append(item)
        # NOTE (regression caught by this same harness): a token that matches
        # no catalog DISPLAY name is NOT necessarily invalid - GL10_1600END is
        # the parser/model name and resolves through the parser path below.
        # Only ambiguity is rejected here; an unknown token keeps flowing into
        # the existing typed identity errors.
        if len(name_matches) > 1:
            raise OperationError(
                "module '%s' matches %d installed catalog records"
                % (module_name, len(name_matches)),
                "ambiguous_module_selector",
                {"module": module_name,
                 "candidates": [{"name": _text(item.get("name")),
                                 "orderNumber": _text(item.get("orderNumber")),
                                 "deviceId": item.get("deviceId")}
                                for item in name_matches[:12]],
                 "mutatedProject": False,
                 "next": {"then": "re-send with the order-number form (e.g. "
                                  "GL10_1600END) or with the exact type/id "
                                  "fields; the native action must not be called "
                                  "with an ambiguous module token"}})
    # Keep the installed catalog order number separate from the exact parser
    # tree name.  The direct I/O picker uses the latter as ``sDevModel``;
    # synchronization helpers may use the former (with hyphens replaced), so
    # both are retained and reported independently.
    # Keep the catalog model distinct from the display name.  The
    # remaining catalog-loop temporaries below intentionally reuse existing
    # locals: IronPython 2.7 represents nested locals as closure cells and
    # has a hard 128-cell limit for this function.
    module_model = None
    # ``CreateIoModuleAddAction`` receives the visible tree-node text used by
    # the native picker.  Keep that selector independent from the parser's
    # canonical ModuleInfos key and from the repository order number.
    action_selector = None
    description = _text(req.get("description") or parser.GetDeviceDescription(module_name) or "")
    picture = _text(req.get("picture") or parser.GetDevicePicFromIOModule_ByID(identifier) or "")
    if not picture:
        picture = _text(parser.GetDevicePictureName3(identifier) or "")
    try:
        import System
        bus_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
        hw_type = _reflection_type("Inovance.InoPro.InoDeviceConfiguration.HwDevType, InoDeviceConfiguration")
        local_bus = System.Enum.ToObject(bus_type, int(req.get("bus", 10)))
        digital_hw = System.Enum.ToObject(hw_type, int(req.get("hwDevType", 2)))
        # The UI receives the complete identity from the installed device
        # tree.  Hand-constructing type=68/version=0 creates a model object
        # that can be displayed but can hang the native AddObject path.
        # Prefer the parser identity and only fall back to explicit fields
        # when this installation has no catalog entry.
        identity = None
        catalog_identity = None
        catalog_type = catalog_id = catalog_version = None
        explicit_identity = req.get("type") is not None or req.get("id") is not None
        if explicit_identity:
            # An explicit type/id from device.list_installed is AUTHORITATIVE:
            # resolve against the installed catalog, never the parser — the
            # parser can bind the same id to a data-module record (type 68)
            # instead of the I/O module row, which then dies inside the
            # native action.
            try:
                _raw_selected, selected = _resolve_installed_device(req)
            except OperationError as exc:
                raise OperationError(
                    "I/O module identity not in the installed catalog: "
                    + str(exc),
                    exc.code,
                    {"module": module_name, "id": identifier,
                     "selector": {"type": req.get("type"),
                                  "id": req.get("id"),
                                  "version": req.get("version")},
                     "candidates": _device_candidate_names(module_name)})
            selected_id = selected.get("deviceId") or {}
            identity = System.Activator.CreateInstance(_reflection_type(
                "Inovance.InoPro.InoProfileParser.ConfigDeviceIdentification, InoProfileParser"))
            identity.Type = int(selected_id.get("type"))
            identity.Id = _text(selected_id.get("id"))
            identity.Version = _text(selected_id.get("version") or "0")
            identity.DeviceName = _text(selected.get("name") or module_name)
            module_model = _text(selected.get("orderNumber") or "").replace("-", "_") or None
            action_selector = _text(selected.get("name") or "").strip() or None
            catalog_type, catalog_id, catalog_version = (
                identity.Type, identity.Id, identity.Version)
            result["catalogIdentity"] = {
                "available": True,
                "source": "installed_catalog_explicit_identity",
                "type": catalog_type,
                "id": catalog_id,
                "version": catalog_version,
            }
        else:
            for identity_key in (module_name, identifier):
                try:
                    catalog_identity = parser.GetDeviceIdentification(identity_key)
                except Exception:
                    catalog_identity = None
                if catalog_identity is not None:
                    break
            if catalog_identity is not None:
                identity = catalog_identity
                identity_parts = _config_identity_parts(identity)
                catalog_type = identity_parts.get("type")
                catalog_id = identity_parts.get("id")
                catalog_version = identity_parts.get("version")
                result["catalogIdentity"] = {
                    "runtimeType": _text(identity.GetType().FullName),
                    "type": catalog_type,
                    "id": catalog_id,
                    "version": catalog_version,
                    "deviceName": _text(_get_member(identity, "device_name", "get_DeviceName")),
                    "devGuid": _text(_get_member(identity, "dev_guid", "get_DevGuid")),
                    "phase": "before_action_factory",
                }
                # Some V1.10 EtherCAT module records resolve to an object whose
                # fields are empty, just like AM600RTU_ECT.  Resolve the exact
                # installed catalog row by caller-supplied id/order/name and fill
                # that native identity object; never invent a type or version.
                if not catalog_id or catalog_type in (None, 0):
                    matches = []
                    for _raw, item in _installed_device_entries():
                        item_id = item.get("deviceId") or {}
                        if int(item_id.get("type") or -1) != 68:
                            continue
                        same_id = identifier and _text(item_id.get("id")).lower() == identifier.lower()
                        same_name = (_text(item.get("orderNumber")).lower() == module_name.lower() or
                                     _text(item.get("name")).lower() == module_name.lower())
                        if same_id or same_name:
                            matches.append(item)
                    # An explicit id is authoritative; a name/order must resolve
                    # to one row to avoid selecting the wrong duplicate module.
                    if identifier and any((_text((item.get("deviceId") or {}).get("id")).lower() == identifier.lower()) for item in matches):
                        matches = [item for item in matches if _text((item.get("deviceId") or {}).get("id")).lower() == identifier.lower()]
                    if len(matches) == 1:
                        resolved = matches[0].get("deviceId") or {}
                        identity.Type = int(resolved.get("type"))
                        identity.Id = _text(resolved.get("id"))
                        identity.Version = _text(resolved.get("version"))
                        identity.DeviceName = _text(matches[0].get("name") or module_name)
                        action_selector = _text(matches[0].get("name") or "").strip() or None
                        catalog_type, catalog_id, catalog_version = identity.Type, identity.Id, identity.Version
                        result["catalogIdentity"]["resolution"] = "installed_catalog_unique_match"
                        result["catalogIdentity"]["type"] = catalog_type
                        result["catalogIdentity"]["id"] = catalog_id
                        result["catalogIdentity"]["version"] = catalog_version
                    elif not catalog_id or catalog_type in (None, 0):
                        raise OperationError(
                            "EtherCAT I/O module identity is empty or catalog-ambiguous",
                            "ethercat_io_identity_incomplete",
                            {"module": module_name, "id": identifier,
                             "candidateCount": len(matches)})
            elif module_name.lower() in VERIFIED_MODULE_ALIASES:
                # Cold-IDE fallback: the vendor parser resolves module names
                # only after the device profile has been loaded in this IDE
                # session. The verified alias carries the evidence-backed
                # catalog identity so a fresh project still adds the module.
                alias = VERIFIED_MODULE_ALIASES[module_name.lower()]
                identity = System.Activator.CreateInstance(_reflection_type(
                    "Inovance.InoPro.InoProfileParser.ConfigDeviceIdentification, InoProfileParser"))
                identity.Type = int(alias.get("type"))
                identity.Id = _text(alias.get("id"))
                identity.Version = _text(alias.get("version"))
                identity.DeviceName = _text(alias.get("name") or module_name)
                catalog_type, catalog_id, catalog_version = (
                    identity.Type, identity.Id, identity.Version)
                result["catalogIdentity"] = {
                    "available": True,
                    "source": "verified_module_alias",
                    "type": catalog_type,
                    "id": catalog_id,
                    "version": catalog_version,
                }
            else:
                # Parser could not resolve module_name/identifier and no
                # verified alias exists.  Never build a placeholder identity
                # (type=68/default id) — that object renders but fails deep
                # inside the native AddObject path.
                raise OperationError(
                    "module identity unresolvable: pass module=<exact vendor "
                    "name> (e.g. GL10_1600END) or type/id/version from "
                    "device.list_installed",
                    "module_identity_unresolvable",
                    {"module": module_name, "id": identifier,
                     "candidates": _device_candidate_names(module_name)})
        # Parser identities do not carry IDeviceInfo.OrderNumber.  Resolve the
        # canonical model from the same installed catalog used for identity
        # validation whenever the explicit-selector path did not already do
        # so.  A unique match is required; otherwise retain a normalized
        # caller model only as a diagnostic/action fallback.
        if not module_model:
            identity_parts = _config_identity_parts(identity)
            actual_type = identity_parts.get("type")
            candidate_name = _text(identity_parts.get("id"))
            matches = []
            for _raw, item in _installed_device_entries():
                item_id = item.get("deviceId") or {}
                if actual_type is not None and item_id.get("type") != actual_type:
                    continue
                if candidate_name and _text(item_id.get("id")) != candidate_name:
                    continue
                if (_text(item_id.get("version")) and
                        _text(identity_parts.get("version")) and
                        _text(item_id.get("version")) !=
                        _text(identity_parts.get("version"))):
                    continue
                key = _text(item.get("orderNumber") or "").replace("-", "_")
                if key and key not in matches:
                    matches.append(key)
                if not action_selector:
                    action_selector = _text(item.get("name") or "").strip() or None
            if len(matches) == 1:
                module_model = matches[0]
        if not module_model:
            module_model = _text(module_name).strip().replace("-", "_") or None
        if not action_selector:
            action_selector = _text(module_name).strip() or None
        rack = int(req.get("rack", 1))
        slot = int(req.get("slot", 1))
        port = int(req.get("port", 0))
        insert_index = int(req.get("insertIndex", -1))
        if insert_index < 0:
            try:
                insert_index = int(hardware.CalInsertIndexOfIOModule(rack, slot, local_bus))
            except Exception as exc:
                result["attempts"].append({"binding": "CalInsertIndexOfIOModule", "ok": False, "error": repr(exc)})
                insert_index = 0
        identity.InsertIndex = insert_index
        # The native local-bus picker attaches an I/O module to the CPU's
        # ``FindSpecialDevice`` node even though its surrounding tree is
        # rendered under a rack.  Older callers sometimes supplied
        # ``parentMode=rack`` based on that visual tree.  Passing the Rack
        # wrapper to the action creates a transient row which disappears on
        # reopen (R51 evidence); normalize that *local-bus-only* spelling to
        # the same CPU parent the picker uses.  Non-local buses retain the
        # explicit rack contract because their topology has separate native
        # coupler/rack semantics.
        if (_text(req.get("parentMode")).strip().lower() == "rack" and
                int(req.get("bus", 10)) == 10):
            result["parentModeNormalization"] = {
                "requested": "rack", "used": "cpu",
                "bus": 10,
                "reason": "local_bus_picker_attaches_to_cpu",
            }
            parent = hardware.FindSpecialDevice(rack, 0, local_bus, port)
        elif _text(req.get("parentMode")).strip().lower() == "rack":
            parent = hardware.FindRack(rack, local_bus, port)
        else:
            # Local + network parent resolution lives in a TOP-LEVEL helper:
            # this function is at IronPython's closure-cell limit (see the
            # helper's docstring for the measured failure).
            parent = _io_module_parent_for_bus(
                hardware, local_bus, int(req.get("bus", 10)), rack, slot, port,
                result)
        # Keep the parser identity, native branch predicate, and vendor CPU
        # family admission proof in one top-level helper.  Besides making the
        # three layers explicit, this avoids IronPython's 128-cell nested
        # closure limit in this transaction handler.
        preflight = _io_module_add_preflight(
            parser, identity, module_name, module_model, digital_hw,
            hardware, parent, before, req)
        result["parserModuleResolution"] = preflight["parserResolution"]
        result["parentCompatibility"] = {
            "checked": True,
            # Backward-compatible field: ``matched`` now means the complete
            # native topology admission decision, not the branch predicate.
            "matched": preflight["topologyMatch"],
            "predicateMatched": preflight["predicateMatch"],
            "module": module_name,
            "moduleModel": module_model,
            "parserModuleName": preflight["parserModuleName"],
            "parentModel": preflight["parentModel"],
            "parentDeviceType": preflight["parentDeviceTypeValue"],
            "bus": preflight["bus"],
            "parentIdentity": preflight["parentIdentity"],
            "rootCpuIdentity": preflight.get("rootCpuIdentity"),
            "parserTag": preflight.get("parserTag"),
            "topology": preflight["topologyDetails"],
            "hwDevTypeMatch": preflight.get("hwDevTypeMatch"),
            "hwDevTypeGate": preflight.get("hwDevTypeDetails"),
            "attempts": preflight["compatibilityAttempts"],
        }
        if preflight["topologyMatch"] is None:
            raise OperationError(
                "vendor topology admission check is unavailable",
                "io_topology_preflight_unavailable", {
                    "module": module_name,
                    "moduleModel": module_model,
                    "parserModuleName": preflight["parserModuleName"],
                    "identity": preflight["identitySnapshot"],
                    "parentModel": preflight["parentModel"],
                    "parentDeviceType": preflight["parentDeviceTypeValue"],
                    "bus": preflight["bus"],
                    "topology": preflight["topologyDetails"],
                    "attempts": preflight["compatibilityAttempts"],
                    "parentResolution": result.get("parentResolution"),
                    "mutatedProject": False,
                    "next": "use the exact parser module name and a vendor-supported parent; do not retry an unresolved identity",
                })
        if preflight.get("hwDevTypeMatch") is False:
            raise OperationError(
                "requested HwDevType is not valid for the selected local module",
                "io_module_hw_dev_type_incompatible", {
                    "module": module_name,
                    "moduleModel": module_model,
                    "parserModuleName": preflight["parserModuleName"],
                    "identity": preflight["identitySnapshot"],
                    "parentModel": preflight["parentModel"],
                    "parentDeviceType": preflight["parentDeviceTypeValue"],
                    "parentIdentity": preflight["parentIdentity"],
                    "bus": preflight["bus"],
                    "hwDevType": _text(digital_hw),
                    "hwDevTypeGate": preflight.get("hwDevTypeDetails"),
                    "topology": preflight["topologyDetails"],
                    "mutatedProject": False,
                    "next": "use hwDevType=2 (HDV_DATAMODULE) for a local GL10/GL20 module; do not retry with type 5",
                })
        if not preflight["topologyMatch"]:
            raise OperationError(
                "vendor module is not compatible with the selected parent; native action was not executed",
                "io_module_parent_incompatible", {
                    "module": module_name,
                    "moduleModel": module_model,
                    "parserModuleName": preflight["parserModuleName"],
                    "identity": preflight["identitySnapshot"],
                    "parentModel": preflight["parentModel"],
                    "parentDeviceType": preflight["parentDeviceTypeValue"],
                    "parentIdentity": preflight["parentIdentity"],
                    "bus": preflight["bus"],
                    "rack": rack, "slot": slot, "port": port,
                    "topology": preflight["topologyDetails"],
                    "attempts": preflight["compatibilityAttempts"],
                    "mutatedProject": False,
                    "next": "use a compatible CPU/local-bus family; do not retry this module under the same parent",
                })
        # The vendor sync model can expose a valid CPU object GUID through
        # GetCpuDeviceGuid while leaving Identification.DevGuid empty.  The
        # native add action uses Identification.DevGuid for permission and
        # modular-data updates; passing Guid.Empty produces the modal
        # "UpdateModularData ... GUID 0000" error.  Repair the in-memory
        # vendor model only after proving the GUID exists in ObjectMgr.
        parent_guid_candidates = _io_module_parent_guid_candidates(parent)
        parent_guid = (parent_guid_candidates[0]["guid"]
                       if parent_guid_candidates else None)
        # Only a local CPU parent may borrow the vendor CPU GUID exposed by
        # ConfigurationSyncProject.  An EtherCAT coupler/slave has its own
        # ObjectMgr identity; substituting the CPU GUID would make the native
        # action update the wrong object and can leave a phantom row behind.
        local_cpu_parent = (preflight.get("bus") == 10 and
                            preflight.get("parentDeviceTypeValue") == 7)
        if not parent_guid and local_cpu_parent:
            try:
                cpu_module = hardware.GetCpuModule()
                parent_guid = cpu_module.GetCpuDeviceGuid()
            except Exception:
                try:
                    import System
                    flags = (System.Reflection.BindingFlags.Instance |
                             System.Reflection.BindingFlags.Public |
                             System.Reflection.BindingFlags.NonPublic)
                    methods = [m for m in sync_project.GetType().GetMethods(flags)
                               if m.Name == "GetCpuDeviceObject" and len(m.GetParameters()) == 0]
                    parent_guid = methods[0].Invoke(sync_project, None) if methods else None
                except Exception:
                    parent_guid = None
            if parent_guid is not None:
                try:
                    parent_identity = _get_member(parent, "identification", "get_Identification")
                    if parent_identity is not None:
                        parent_identity.DevGuid = parent_guid
                except Exception as exc:
                    result["parentGuidRepairError"] = repr(exc)
        parent_guid_text = _text(parent_guid or "")
        parent_guid_valid = parent_guid_text not in (
            "", "00000000-0000-0000-0000-000000000000")
        parent_guid_exists = False
        handle = None
        if parent_guid_valid:
            try:
                if native_core_project is not None:
                    handle = _get_member(
                        native_core_project, "Handle", "get_Handle")
                if handle is None:
                    handle = _get_member(project, "handle", "get_handle")
                if handle is None:
                    handle = _get_member(project, "Handle", "get_Handle")
                import System
                # Use the same singleton manager as the vendor action and all
                # readback probes. APEnvironment.ObjectMgr can be a stale
                # wrapper after a clean-process project reopen.
                mgr, mgr_probe = _system_instances_property("ObjectMgr")
                result["parentGuidManager"] = {
                    "binding": "SystemInstances.ObjectMgr",
                    "runtimeType": _text(mgr.GetType().FullName)
                    if mgr is not None else None,
                    "probe": mgr_probe,
                }
                guid_value = System.Guid(parent_guid_text)
                parent_guid_exists = bool(
                    mgr.ExistsObject(int(handle), guid_value))
                if diagnose:
                    result["parentGuidObjectScan"] = {
                        "allObjectsContainsGuid": False,
                        "objectCount": None,
                    }
                    try:
                        all_objects = list(mgr.GetAllObjects(int(handle)))
                        guid_texts = set(_text(item).lower() for item in all_objects)
                        result["parentGuidObjectScan"] = {
                            "allObjectsContainsGuid": parent_guid_text.lower() in guid_texts,
                            "objectCount": len(all_objects),
                        }
                    except Exception as scan_exc:
                        result["parentGuidObjectScan"]["error"] = repr(scan_exc)
            except Exception as exc:
                result["parentGuidExistsError"] = repr(exc)
        result["parentGuidPreflight"] = {
            "guid": parent_guid_text,
            "valid": parent_guid_valid,
            "existsInObjectManager": parent_guid_exists,
            "projectHandle": int(handle) if handle is not None else None,
            "parentRuntimeType": _text(parent.GetType().FullName) if parent is not None else None,
            "candidates": parent_guid_candidates,
            "cpuFallbackAllowed": local_cpu_parent,
        }
        if not parent_guid_valid or not parent_guid_exists:
            raise RuntimeError(
                "vendor parent device GUID is empty or not present in ObjectMgr: "
                + parent_guid_text)
        if bool(req.get("preflightOnly", False)):
            result["executed"] = False
            result["mutatedProject"] = False
            result["status"] = "preflight_ready"
            result["nextRequired"] = "run the native vendor transaction only after explicit confirmation"
            return result
        rect = hardware.GetSlotRect(rack, slot, local_bus, port)
        result["inputs"] = {
            "factoryBinding": action_binding,
            "configFactoryBinding": binding,
            "parserBinding": parser_binding,
            "module": module_name,
            # Keep all forms: ``module`` is the caller-facing selector,
            # ``parserModuleName`` is the exact tree/picker model, and
            # ``moduleModel`` is the installed repository order number.  The
            # direct native picker passes the parser model to the action;
            # synchronization code may use the order-number form, so they
            # must never be silently conflated.
            "moduleModel": module_model,
            "parserModuleName": preflight["parserModuleName"],
            "actionSelector": action_selector,
            "identity": preflight["identitySnapshot"],
            "hwDevType": _text(digital_hw), "bus": _text(local_bus),
            "parentDeviceType": preflight["parentDeviceTypeValue"],
            "rack": rack, "slot": slot, "port": port,
            "insertIndex": insert_index,
            "description": description, "picture": picture,
            "parentRuntimeType": _text(parent.GetType().FullName) if parent is not None else None,
            "rect": _json_safe(rect),
        }
        # Match the direct vendor picker while preserving the bus-specific
        # naming contracts.  Local GL10/GL20 rows are selected from the
        # visible installed catalog label (R45/R52 proved that a localized
        # label is what this action persists).  EtherCAT rows, however, are
        # indexed by the exact parser/tree name under the selected tag; using
        # an installed display label/order number there can create a transient
        # row or select a duplicate module.  Other buses stay conservative and
        # use the exact parser name as well.
        action_model = preflight["parserModuleName"] or _text(module_name).strip()
        action_model_source = "parser_tree_name"
        if preflight.get("bus") == 10 and action_selector:
            action_model = action_selector
            action_model_source = "installed_catalog_display_name_local_bus"
        if not action_model:
            raise OperationError(
                "exact parser module name is unavailable",
                "module_identity_unresolvable",
                {"mutatedProject": False, "moduleModel": module_model})
        result["actionModel"] = action_model
        result["actionModelSource"] = action_model_source
        result["actionSelector"] = action_selector
        if identity is None:
            # Measured 2026-09-19: a module DISPLAY name resolved to no identity
            # yet the native action was still invoked, which surfaced as
            # `native_io_add_failed: SystemError('序列不包含任何元素')` - a raw
            # .NET LINQ failure with a null identity in the payload. Fail here
            # instead, with the candidates the caller can actually use.
            raise OperationError(
                "module identity did not resolve in the installed catalog: "
                + _text(module_name),
                "module_identity_unresolved",
                {"module": _text(module_name),
                 "bus": int(req.get("bus", 10)),
                 "rack": rack, "slot": slot,
                 "candidates": _device_candidate_names(module_name),
                 "mutatedProject": False,
                 "next": {
                     "then": "pass the catalog order-number form reported by "
                             "inoproshop_device_list_installed (e.g. "
                             "GL10_1600END) or the exact type/id/version; a "
                             "display name alone can be ambiguous, and the "
                             "native action must not be called without an "
                             "identity",
                 }})
        action = action_factory.CreateIoModuleAddAction(
            digital_hw, action_model,
            rack, slot, rect, description, picture,
            identity, parent, hardware)
        result["actionRuntimeType"] = _text(action.GetType().FullName)
        try:
            action_stream = action.DeviceObjectStream
            result["deviceObjectStreamBeforeExecute"] = {
                "present": action_stream is not None,
                "length": int(action_stream.Length) if action_stream is not None else None,
            }
        except Exception as exc:
            result["deviceObjectStreamBeforeExecute"] = {"readError": repr(exc)}
        if diagnose:
            try:
                action_methods = []
                for method in action.GetType().GetMethods():
                    if any(token in _text(method.Name).lower() for token in ("execute", "undo", "device", "module", "config")):
                        action_methods.append(_text(method.ToString()))
                result["actionReflection"] = sorted(set(action_methods))[:100]
            except Exception as exc:
                result["actionReflectionError"] = repr(exc)
        execute_mode = _text(req.get("executeMode") or "default").strip().lower()
        execute_via_undo = req.get("executeViaUndoManager", True) is not False
        if execute_via_undo:
            # The vendor UI never calls the action directly.  It submits the
            # action to UndoRedoManager, which performs Execute(), registers
            # the object stream, and updates the hardware transaction state.
            undo_factory, undo_binding = _reflection_generic_create(
                "Inovance.InoPro.InoDeviceConfiguration.IConfigUnDoManagerFactory, InoDeviceConfiguration",
                "{2B1107E5-6245-4D8A-95B2-2FE422729DF5}")
            undo_manager = undo_factory.CreateConfigUndoManager()
            config_type = _reflection_type(
                "Inovance.InoPro.InoDeviceConfiguration.ConfigType, InoDeviceConfiguration")
            hardware_config = System.Enum.ToObject(config_type, 0) if config_type is not None else 0
            parent_bus = _get_member(parent, "BusNetworkTopology", "get_BusNetworkTopology")
            undo_manager.AddToUnDoManager(hardware_config, action, parent_bus)
            result["executeMode"] = "vendor_undo_manager"
            result["executeArgument"] = None
            result["undoManagerBinding"] = undo_binding
            result["undoManagerRuntimeType"] = _text(undo_manager.GetType().FullName)
        elif execute_mode == "default":
            action.Execute()
            result["executeMode"] = "direct_default_experimental"
            result["executeArgument"] = None
        elif execute_mode == "bool":
            execute_argument = bool(req.get("executeArgument", False))
            action.Execute(execute_argument)
            result["executeMode"] = "direct_bool_experimental"
            result["executeArgument"] = execute_argument
        else:
            raise RuntimeError("executeMode must be default or bool")
        try:
            action_stream = action.DeviceObjectStream
            result["deviceObjectStreamAfterExecute"] = {
                "present": action_stream is not None,
                "length": int(action_stream.Length) if action_stream is not None else None,
            }
        except Exception as exc:
            result["deviceObjectStreamAfterExecute"] = {"readError": repr(exc)}
        result["executed"] = True
        result["mutatedProject"] = True
        # Network-bus modules also need the framework's project-tree placement
        # (see _place_io_module_in_project_tree). Local-rack adds already place
        # the module through their slot geometry, so keep them untouched.
        try:
            # result["inputs"] is later replaced by the identity payload, so read
            # the bus from the request (and fall back to the resolved enum).
            placement_bus = int(req.get("bus", 10))
        except Exception:
            try:
                placement_bus = int(local_bus)
            except Exception:
                placement_bus = 10
        if (placement_bus != 10
                and req.get("placeInProjectTree", True) is not False):
            try:
                catalog_identity = result.get("catalogIdentity") or {}
                result["projectTreePlacement"] = _place_io_module_in_project_tree(
                    hardware, parent, rack, local_bus, port,
                    catalog_identity.get("type"),
                    _text(catalog_identity.get("id")))
            except Exception as exc:
                result["projectTreePlacement"] = {"attempted": True,
                                                 "error": repr(exc)}
        try:
            result["sameInstanceReadback"] = {
                "rackIoModuleNum": int(hardware.GetRackIoModuleNum(rack, local_bus, port)),
                "deviceListCount": len(list(hardware.GetDeviceList(0, local_bus, port)))
            }
        except Exception as exc:
            result["sameInstanceReadback"] = {"ok": False, "error": repr(exc)}
    except Exception as exc:
        if isinstance(exc, OperationError):
            # Preserve structured preflight/identity errors instead of
            # relabeling them as a native action failure.
            raise
        result["executed"] = False
        result["error"] = repr(exc)
        result["errorCode"] = "native_io_add_failed"
        # A native vendor transaction failure is a failed operation, not a
        # successful response containing data.executed=false.  The payload is
        # deliberately COMPACT: the full rack/guid forensics stay in the
        # evidence files, not in the model's context.
        raise OperationError("native I/O add failed: " + repr(exc),
                             "native_io_add_failed", {
                                 "module": result.get("inputs", {}).get("module"),
                                 "identity": result.get("inputs", {}).get("identity"),
                                 "rack": result.get("inputs", {}).get("rack"),
                                 "slot": result.get("inputs", {}).get("slot"),
                                 "bus": result.get("inputs", {}).get("bus"),
                                 "port": result.get("inputs", {}).get("port"),
                                 "stage": "native_io_add_action",
                                 "error": repr(exc),
                                 "hint": "verify the module identity against "
                                         "device.list_installed and use the "
                                         "rack/slot of a free position",
                             })
    try:
        commit_mode = _text(req.get("commitMode") or "").strip().lower()
        if not commit_mode:
            # An IO module add without an archive commit can never survive the
            # ObjectMgr readback gate below, so the proven update_archive
            # sequence (UpdateData + UpdateConfigurationDataObject) is the only
            # default that can succeed. Explicit "none" still skips the block.
            commit_mode = "update_archive"
        result["commitMode"] = commit_mode
        if commit_mode in ("update_archive", "update_archive_add", "sync_recreate"):
            try:
                network = _get_member(sync_project, "network_config_project", "get_NetworkConfigProject")
                set_internal_property(storage, "HardwareConfigurationProj", hardware)
                if network is not None:
                    set_internal_property(storage, "NetworkConfigurationProj", network)
                invoke_internal(storage, "UpdateData", [])
                result["archiveUpdateData"] = {"called": True, "ok": True}
            except Exception as exc:
                result["archiveUpdateData"] = {"called": True, "ok": False, "error": repr(exc)}
            try:
                core_project = native_core_project
                core_binding = "wizard.Execute return value" if core_project is not None else None
                if core_project is None:
                    project_values = [project]
                    for wrapper_name in ("Extender", "project", "CoreProject"):
                        wrapper = _get_member(project, wrapper_name, "get_" + wrapper_name)
                        if wrapper is not None:
                            project_values.append(wrapper)
                    for wrapper in project_values:
                        for candidate_name in ("CoreProject", "core_project", "project"):
                            try:
                                import System
                                flags = (System.Reflection.BindingFlags.Instance |
                                         System.Reflection.BindingFlags.Public |
                                         System.Reflection.BindingFlags.NonPublic)
                                prop = wrapper.GetType().GetProperty(candidate_name, flags)
                                candidate = prop.GetValue(wrapper, None) if prop is not None else None
                            except Exception:
                                candidate = _get_member(wrapper, candidate_name, "get_" + candidate_name)
                            if candidate is not None:
                                core_project = candidate
                                break
                        if core_project is not None:
                            break
                if core_project is None:
                    raise RuntimeError("ScriptProject CoreProject binding unavailable")
                result["coreProjectRuntimeType"] = _text(core_project.GetType().FullName)
                result["coreProjectBinding"] = core_binding or "ScriptEngine wrapper probe"
                if commit_mode == "update_archive_add":
                    add_result = invoke_internal(
                        sync_project, "AddConfigurationDataObject", [core_project])
                    result["archiveProjectAdd"] = {
                        "called": True, "ok": bool(add_result),
                        "result": _json_safe(add_result),
                    }
                if commit_mode == "sync_recreate":
                    try:
                        sync_result = invoke_internal(
                            sync_project, "SyncToConfigrationDataObject", [])
                        result["syncToConfigurationData"] = {
                            "called": True, "ok": True,
                            "result": _json_safe(sync_result),
                        }
                    except Exception as exc:
                        result["syncToConfigurationData"] = {
                            "called": True, "ok": False, "error": repr(exc),
                        }
                    try:
                        import System
                        flags = (System.Reflection.BindingFlags.Instance |
                                 System.Reflection.BindingFlags.Public |
                                 System.Reflection.BindingFlags.NonPublic)
                        recreate_methods = [m for m in sync_project.GetType().GetMethods(flags)
                                            if _text(m.Name) == "RecreateConfigStorageObj"
                                            and len(m.GetParameters()) == 1]
                        if not recreate_methods:
                            raise RuntimeError("RecreateConfigStorageObj(ref) unavailable")
                        recreate_args = System.Array[System.Object]([storage])
                        recreate_result = recreate_methods[0].Invoke(sync_project, recreate_args)
                        storage = recreate_args[0]
                        result["recreateConfigStorage"] = {
                            "called": True, "ok": True,
                            "result": _json_safe(recreate_result),
                            "storage": archive_state(storage),
                        }
                        sync_project.AttachToConfigrationObjectData(storage)
                    except Exception as exc:
                        result["recreateConfigStorage"] = {
                            "called": True, "ok": False, "error": repr(exc),
                        }
                update_result = invoke_internal(
                    sync_project, "UpdateConfigurationDataObject", [core_project, storage])
                result["archiveProjectUpdate"] = {
                    "called": True, "ok": bool(update_result), "result": _json_safe(update_result)
                }
            except Exception as exc:
                result["archiveProjectUpdate"] = {"called": True, "ok": False, "error": repr(exc)}
            result["configStorageAfterArchiveUpdate"] = archive_state(storage)
        try:
            result["hardwareSaved"] = bool(hardware.SaveHardWareConfiguration())
        except Exception as exc:
            result["hardwareSaved"] = False
            result["hardwareSaveError"] = repr(exc)
        try:
            result["configSaveResult"] = bool(sync_project.SaveConfigurationData())
            result["configSaved"] = True
        except Exception as exc:
            result["configSaved"] = False
            result["configSaveError"] = repr(exc)
        result["hardwareReloaded"] = False
        result["hardwareReloadStatus"] = "skipped_requires_separate_reopen_experiment"
    except Exception as exc:
        result["persistenceSequenceError"] = repr(exc)
    after_probe = device_config_graph_probe({})
    if diagnose:
        result["after"] = after_probe

    expected_identity = {
        "type": int(identity.Type),
        "id": _text(identity.Id).strip(),
        "version": _text(identity.Version).strip(),
    }

    def exact_config_rows(snapshot):
        rows = []
        for row in (snapshot or {}).get("devices", []):
            actual = row.get("identification") or {}
            try:
                actual_type = int(actual.get("type"))
            except Exception:
                actual_type = None
            if (actual_type == expected_identity["type"] and
                    _text(actual.get("id")).strip().lower() ==
                    expected_identity["id"].lower() and
                    _text(actual.get("version")).strip().lower() ==
                    expected_identity["version"].lower() and
                    int(row.get("rack", -999)) == rack and
                    int(row.get("slot", -999)) == slot and
                    int(row.get("port", -999)) == port):
                rows.append(row)
        return rows

    before_rows = exact_config_rows(before)
    after_rows = exact_config_rows(after_probe)
    ui_tree = device_tree()
    ui_rows = []
    for row in ui_tree.get("devices", []):
        actual = row.get("deviceId") or {}
        try:
            actual_type = int(actual.get("type"))
        except Exception:
            actual_type = None
        if (actual_type == expected_identity["type"] and
                _text(actual.get("id")).strip().lower() ==
                expected_identity["id"].lower() and
                _text(actual.get("version")).strip().lower() ==
                expected_identity["version"].lower()):
            ui_rows.append(row)
    result["commitReadback"] = {
        "expectedIdentity": expected_identity,
        "expectedLocation": {"rack": rack, "slot": slot, "port": port},
        "beforeConfigMatchCount": len(before_rows),
        "reboundConfigMatchCount": len(after_rows),
        "objectTreeMatchCount": len(ui_rows),
        "reboundConfigMatches": after_rows,
        "objectTreeMatches": ui_rows,
    }
    if len(after_rows) != len(before_rows) + 1 or len(ui_rows) < 1:
        # The rebound ConfigurationSyncProject probe never shows the freshly
        # added module, even for the proven 20260824 flow (evidence:
        # work/bridge/res/00e1e9758f224b598d0bac2dba85eb15.json), so this
        # in-process signal cannot distinguish success. When the same-session
        # hardware model does contain the module, accept the add here and make
        # the authoritative persistence proof the project.save plus
        # fresh-process reopen device-tree readback that follows the call.
        same_instance = result.get("sameInstanceReadback") or {}
        try:
            same_instance_modules = int(same_instance.get("rackIoModuleNum") or 0)
        except Exception:
            same_instance_modules = 0
        if same_instance_modules >= 1:
            result["status"] = "committed_pending_reopen_readback"
            result["persistenceVerified"] = False
            result["processDiscardRequired"] = False
            result["nextRequired"] = (
                "project.save, close, fresh-process reopen and device.tree exact "
                "identity readback; that reopen gate is the authoritative proof"
            )
            return result
        result["status"] = "not_committed"
        result["persistenceVerified"] = False
        result["processDiscardRequired"] = True
        result["nextRequired"] = (
            "discard this IDE process; the vendor action changed only its transient "
            "hardware model and did not publish the exact module to ObjectMgr"
        )
        raise OperationError(
            "native I/O add did not survive a new configuration session and ObjectMgr readback",
            "io_module_not_committed", result)
    result["status"] = "committed_same_process"
    result["persistenceVerified"] = False
    result["processDiscardRequired"] = False
    result["nextRequired"] = (
        "project.save, close, fresh-process reopen, exact identity readback and second compile"
    )
    return result


def vendor_ethercat_slave_transaction_probe(req):
    """Read the exact Inovance EtherCAT slave insertion transaction inputs.

    A generic ScriptEngine ``device.add`` produces an object-model device but
    bypasses the hardware/network configuration transaction.  This probe binds
    the factories that the Inovance device-tree editor uses and resolves the
    actual CPU EtherCAT port and catalogue identity.  It deliberately does
    not create an action or mutate the project.
    """
    _require_project()
    result = {
        "operation": "vendor.ethercat.slave.transaction.probe",
        "mutatedProject": False,
        "transaction": "InsertEtherCATSlaveAction",
        "attempts": [],
        "staticContract": {
            "factory": "IInsertEtherCATSlaveActionFactory1",
            "factoryGuid": INOVANCE_ETHERCAT_SLAVE_ACTION_FACTORY_GUID,
            "action": "InsertEtherCATSlaveAction",
            "execution": [
                "CreateHardwareConifgDevice",
                "CreateNetworkConfigDevice",
                "InsertECTSlaveInCoDeSysDevList",
                "UpdateSlaveEditor",
            ],
            "requiredArguments": [
                "productName", "deviceIdentification", "picture", "description",
                "portIndex", "portNo", "hardwareConfig", "networkConfig",
                "deviceCategory", "behindDevice", "axisIsAdding",
            ],
        },
    }

    def bind(label, interface_name, type_guid):
        try:
            value, binding = _reflection_generic_create(interface_name, type_guid)
            result["attempts"].append({
                "label": label,
                "ok": value is not None,
                "binding": binding,
            })
            return value, binding
        except Exception as exc:
            result["attempts"].append({"label": label, "ok": False, "error": repr(exc)})
            return None, None

    action_factory, action_binding = bind(
        "insertEthercatSlaveActionFactory",
        INOVANCE_ETHERCAT_SLAVE_ACTION_FACTORY_INTERFACE,
        INOVANCE_ETHERCAT_SLAVE_ACTION_FACTORY_GUID,
    )
    network_factory, network_binding = bind(
        "networkEthercatFactory",
        INOVANCE_ETHERCAT_NETWORK_FACTORY_INTERFACE,
        INOVANCE_ETHERCAT_NETWORK_FACTORY_GUID,
    )
    undo_factory, undo_binding = bind(
        "configUndoManagerFactory",
        INOVANCE_CONFIG_UNDO_FACTORY_INTERFACE,
        INOVANCE_CONFIG_UNDO_FACTORY_GUID,
    )
    result["factoryBindings"] = {
        "insertAction": action_binding,
        "network": network_binding,
        "undo": undo_binding,
    }
    if action_factory is None or network_factory is None or undo_factory is None:
        raise OperationError(
            "required Inovance EtherCAT transaction factory is unavailable",
            "ethercat_vendor_transaction_unavailable",
            result,
        )

    config_factory, config_binding = bind(
        "configurationSyncProjectFactory",
        INOVANCE_CONFIG_FACTORY_INTERFACE,
        INOVANCE_CONFIG_FACTORY_GUID,
    )
    if config_factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", result)
    sync_project = config_factory.CreateConfigSyncProj()
    try:
        sync_project.StartSyncToConfigrationDataObject()
        result["attempts"].append({"label": "StartSyncToConfigrationDataObject", "ok": True})
    except Exception as exc:
        result["attempts"].append({"label": "StartSyncToConfigrationDataObject", "ok": False,
                                   "error": repr(exc)})
    # IConfigurationSyncProject exposes PascalCase CLR properties.  Earlier
    # bridge code only tried Python-style names, which made a live AM600
    # configuration graph appear absent.  Keep the out-parameter fallback for
    # vendor versions that expose the concrete implementation differently.
    def first_member(obj, names, default=None):
        for name in names:
            value = _get_member(obj, name, "get_" + name, None)
            if value is not None:
                return value
        return default
    hardware = first_member(sync_project, (
        "HardwareConfigProject", "hardware_config_project"))
    network = first_member(sync_project, (
        "NetworkConfigProject", "network_config_project"))
    if hardware is None or network is None:
        try:
            import System
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject"
                       and len(m.GetParameters()) == 2]
            if methods:
                args = System.Array[System.Object]([None, None])
                methods[0].Invoke(sync_project, args)
                if hardware is None:
                    hardware = args[0]
                if network is None:
                    network = args[1]
                result["attempts"].append({
                    "label": "GetSyncToConfigrationDataObject",
                    "ok": hardware is not None and network is not None,
                })
        except Exception as exc:
            result["attempts"].append({
                "label": "GetSyncToConfigrationDataObject",
                "ok": False, "error": repr(exc),
            })
    if hardware is None or network is None:
        raise OperationError("vendor hardware/network configuration is unavailable",
                             "ethercat_configuration_graph_unavailable", result)
    result["configuration"] = {
        "factoryBinding": config_binding,
        "syncProjectRuntimeType": _text(sync_project.GetType().FullName),
        "hardwareRuntimeType": _text(hardware.GetType().FullName),
        "networkRuntimeType": _text(network.GetType().FullName),
    }

    parser_factory, parser_binding = bind(
        "deviceTreeParserFactory",
        "Inovance.InoPro.InoDeviceConfiguration.IDevTreeFileParserFactory, InoDeviceConfiguration",
        "{669014F5-D843-4E51-962E-1386A8828EBE}",
    )
    if parser_factory is None:
        raise OperationError("device tree parser is unavailable",
                             "ethercat_device_parser_unavailable", result)
    parser = parser_factory.CreateDeviceTreeParser()
    product_name = _text(req.get("productName") or req.get("module") or "").strip()
    identifier = _text(req.get("identifier") or req.get("id") or product_name).strip()
    if not product_name or not identifier:
        raise OperationError(
            "productName and identifier are required for an EtherCAT transaction probe",
            "invalid_argument", result)
    identity = None
    identity_attempts = []
    for candidate in (identifier, product_name):
        try:
            identity = parser.GetDeviceIdentification(candidate)
            identity_attempts.append({"candidate": candidate, "resolved": identity is not None})
            if identity is not None:
                break
        except Exception as exc:
            identity_attempts.append({"candidate": candidate, "resolved": False, "error": repr(exc)})
    if identity is None:
        result["identityAttempts"] = identity_attempts
        raise OperationError("installed EtherCAT device identity was not resolved",
                             "ethercat_device_identity_unresolved", result)
    identity_type = _get_member(identity, "type", "get_Type")
    identity_id = _text(_get_member(identity, "id", "get_Id"))
    identity_version = _text(_get_member(identity, "version", "get_Version"))
    # V1.10's parser returns an empty IConfigDeviceIdentification for several
    # built-in EtherCAT order numbers even though the same records are present
    # in the installed repository.  Resolve the authoritative triple from the
    # repository and populate a vendor identity object, preserving the exact
    # catalog values rather than accepting caller-supplied guesses.
    if identity_type is None or not identity_id or not identity_version:
        repo_matches = []
        try:
            for raw, item in _filter_installed_devices({
                    "name": product_name, "deviceName": product_name}):
                candidate = item.get("deviceId") or {}
                if int(candidate.get("type") or -1) == 65:
                    repo_matches.append((raw, item))
            if not repo_matches:
                for raw, item in _installed_device_entries():
                    if _text(item.get("orderNumber")).lower() == product_name.lower():
                        candidate = item.get("deviceId") or {}
                        if int(candidate.get("type") or -1) == 65:
                            repo_matches.append((raw, item))
        except Exception as exc:
            result["repositoryIdentityError"] = repr(exc)
        if len(repo_matches) == 1:
            candidate = repo_matches[0][1].get("deviceId") or {}
            identity_type = candidate.get("type")
            identity_id = _text(candidate.get("id"))
            identity_version = _text(candidate.get("version"))
            try:
                ap_type = _reflection_type(INOVANCE_AP_ENVIRONMENT_TYPE)
                create_method = ap_type.GetMethod("CreateConfigDeviceIdentification") if ap_type is not None else None
                if create_method is not None:
                    rebuilt = create_method.Invoke(None, None)
                    rebuilt.Type = int(identity_type)
                    rebuilt.Id = identity_id
                    rebuilt.Version = identity_version
                    rebuilt.DeviceName = product_name
                    identity = rebuilt
                    result["identitySource"] = "installed_repository_order_number"
            except Exception as exc:
                result["identityRebuildError"] = repr(exc)
    if identity_type is None or not identity_id or not identity_version:
        result["identityAttempts"] = identity_attempts
        result["resolvedIdentity"] = {
            "type": _json_safe(identity_type), "id": identity_id,
            "version": identity_version,
        }
        try:
            identity_type_info = identity.GetType()
            result["identityReflection"] = {
                "runtimeType": _text(identity_type_info.FullName),
                "properties": sorted(set(_text(prop.Name)
                                         for prop in identity_type_info.GetProperties())),
                "fields": sorted(set(_text(field.Name)
                                     for field in identity_type_info.GetFields())),
                "methods": sorted(set(_text(method.ToString())
                                      for method in identity_type_info.GetMethods()
                                      if any(token in _text(method.Name).lower()
                                             for token in ("id", "clone", "device"))))[:100],
            }
        except Exception as exc:
            result["identityReflection"] = {"error": repr(exc)}
        raise OperationError(
            "device-tree parser returned an empty EtherCAT identity; refuse insertion",
            "ethercat_device_identity_incomplete", result)
    try:
        port_no = int(req.get("portNo", req.get("port", 0)))
        port_index = int(req.get("portIndex", req.get("index", 0)))
    except Exception:
        raise OperationError("portNo and portIndex must be integers", "invalid_argument", result)
    cpu = hardware.GetCpuModule()
    port_rows = []
    selected_port = None
    ports = first_member(cpu, ("PortUseInfoArray", "port_use_info_array"), [])
    for item in list(ports or []):
        bus = first_member(item, ("CurrentBusDes", "current_bus_des"))
        bus_type = first_member(bus, ("BusType", "bus_type")) if bus is not None else None
        port_type = first_member(item, ("PortType", "port_type"))
        row = {
            "portNo": _json_safe(first_member(item, ("PortNo", "port_no"))),
            "index": _json_safe(first_member(item, ("Index", "index"))),
            "portType": _text(port_type),
            "busType": _text(bus_type),
            "deviceGuid": _text(first_member(
                first_member(bus, ("DevIdentification", "dev_identification")),
                ("DevGuid", "dev_guid"))) if bus is not None else "",
        }
        try:
            supported = cpu.GetSupportBusBuyInterface(port_type)
            row["supportedBusTypes"] = [_text(value) for value in list(supported or [])]
        except Exception as exc:
            row["supportedBusTypesError"] = repr(exc)
        port_rows.append(row)
        if row["portNo"] == port_no and "ETHERCAT" in row["busType"].upper():
            selected_port = row
    result["cpuEthercatPorts"] = port_rows
    if not port_rows:
        try:
            result["cpuPortReflection"] = {
                "runtimeType": _text(cpu.GetType().FullName),
                "properties": sorted(set(_text(prop.Name) for prop in cpu.GetType().GetProperties()
                                         if "port" in _text(prop.Name).lower())),
                "methods": sorted(set(_text(method.ToString()) for method in cpu.GetType().GetMethods()
                                      if "port" in _text(method.Name).lower()))[:80],
            }
        except Exception as exc:
            result["cpuPortReflection"] = {"error": repr(exc)}
        raise OperationError(
            "CPU EtherCAT port metadata could not be read from the vendor configuration model",
            "ethercat_port_metadata_unreadable", result)
    if selected_port is None:
        raise OperationError(
            "selected CPU port is not an active EtherCAT configuration port",
            "ethercat_port_not_configured",
            result,
        )
    result["inputs"] = {
        "parserBinding": parser_binding,
        "productName": product_name,
        "identity": {
            "type": _json_safe(identity_type),
            "id": identity_id,
            "version": identity_version,
            "deviceName": _text(_get_member(identity, "device_name", "get_DeviceName")),
        },
        "description": _text(parser.GetDeviceDescription(product_name) or ""),
        "picture": _text(parser.GetDevicePictureName2(product_name) or "EtherCat.bmp"),
        "portNo": port_no,
        "portIndex": port_index,
        "deviceCategory": _text(req.get("deviceCategory") or "CSDC_GENERIC"),
        "axisIsAdding": bool(req.get("axisIsAdding", False)),
        "selectedCpuPort": selected_port,
    }
    result["status"] = "transaction_inputs_ready"
    result["nextRequired"] = (
        "run vendor.ethercat.slave.insert only on a disposable project with explicit "
        "confirmation, then verify UI tree, ObjectMgr identity, save/reopen and compile"
    )
    return result


# The writer and read-only inventory intentionally share one exact table.
# Generic Ethernet (3) is not evidence for EtherNet/IP (8) or PROFINET (12).
PROTOCOL_PORT_ENABLE_SPECS = CPU_PROTOCOL_PORT_INVENTORY_SPECS


def _normalize_offline_protocol(value):
    value = _text(value).strip().lower().replace("-", "_").replace("/", "_")
    aliases = {
        "modbus_tcp_slave": "modbus_tcp",
        "modbustcp": "modbus_tcp",
        "tcp": "modbus_tcp",
        "modbus_rtu": "modbus",
        "rtu": "modbus",
        "serial": "modbus",
        "can": "canopen",
        "profibus": "profibus_dp",
        "dp": "profibus_dp",
        "ethernetip": "ethernet_ip",
        "eip": "ethernet_ip",
        "cip": "ethernet_ip",
        "pn": "profinet",
    }
    return aliases.get(value, value)


def vendor_protocol_port_enable(req):
    """Enable one installed Inovance protocol bus on a physical CPU port.

    This is the shared transaction behind the non-EtherCAT offline protocol
    matrix.  It deliberately stops at the bus/master object; slave insertion
    and editor-page writes remain separate operations with their own gates.
    """
    operation = "vendor.protocol.port.enable"
    project_path = _require_current_disposable_project(req, operation)
    if req.get("confirm") != "enable_protocol_port":
        raise OperationError(
            "confirm must exactly equal enable_protocol_port",
            "confirmation_required", {"projectPath": project_path})
    protocol = _normalize_offline_protocol(req.get("protocol"))
    if protocol not in (
            "canopen", "profibus_dp", "ethernet_ip", "modbus", "modbus_tcp"):
        raise OperationError(
            "public protocol-port enable covers CANopen, PROFIBUS-DP, "
            "EtherNet/IP and Modbus; PROFINET has no installed master identity "
            "on this build",
            "protocol_scope_not_promoted",
            {"protocol": protocol,
             "supported": ["canopen", "profibus_dp", "ethernet_ip",
                           "modbus", "modbus_tcp"],
             "notPromoted": [],
             "unsupportedOnThisBuild": ["profinet"],
             "mutatedProject": False},
        )
    spec = PROTOCOL_PORT_ENABLE_SPECS.get(protocol)
    if spec is None:
        raise OperationError(
            "protocol must be canopen, profibus_dp, ethernet_ip, or profinet",
            "invalid_argument",
            {"path": "protocol", "actual": protocol,
             "allowed": sorted(PROTOCOL_PORT_ENABLE_SPECS.keys())})

    import System
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", {"binding": binding})
    sync_project = factory.CreateConfigSyncProj()
    if sync_project is None:
        raise OperationError("configuration sync project is unavailable",
                             "configuration_sync_unavailable", {"binding": binding})
    sync_project.StartSyncToConfigrationDataObject()
    hardware = _get_member(sync_project, "HardwareConfigProject", "get_HardwareConfigProject")
    network = _get_member(sync_project, "NetworkConfigProject", "get_NetworkConfigProject")
    if hardware is None or network is None:
        try:
            methods = [method for method in sync_project.GetType().GetMethods()
                       if method.Name == "GetSyncToConfigrationDataObject" and
                       len(method.GetParameters()) == 2]
            args = System.Array[System.Object]([None, None])
            methods[0].Invoke(sync_project, args)
            hardware, network = args[0], args[1]
        except Exception:
            pass
    if hardware is None or network is None:
        raise OperationError("vendor configuration graph is unavailable",
                             "protocol_configuration_graph_unavailable")

    port_type_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.CommunicationPortType, InoDeviceConfiguration")
    bus_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
    if port_type_enum is None or bus_enum is None:
        raise OperationError("vendor protocol enums are unavailable",
                             "protocol_bus_enum_unavailable")
    cpu = hardware.GetCpuModule()
    inventory_data = {
        "protocol": protocol,
        "expectedPortType": spec["portType"],
        "expectedBus": {"name": spec["busName"], "value": spec["busType"]},
        "ports": [],
        "mutatedProject": False,
    }
    try:
        raw_ports = _get_member(
            cpu, "PortUseInfoArray", "get_PortUseInfoArray", None)
        if raw_ports is None:
            raise RuntimeError("PortUseInfoArray returned None")
        inventory_data["ports"] = [
            _cpu_port_inventory_row(item) for item in list(raw_ports)]
    except Exception as exc:
        inventory_data["readError"] = repr(exc)
        raise OperationError(
            "CPU physical port inventory is unavailable",
            "cpu_port_inventory_unreadable", inventory_data)

    exact_candidates = [
        row for row in inventory_data["ports"]
        if (row.get("PortType") or {}).get("value") == spec["portType"]]
    inventory_data["exactCandidates"] = exact_candidates
    requested_port_no = req.get("portNo")
    if requested_port_no is not None:
        try:
            if isinstance(requested_port_no, bool):
                raise ValueError("boolean is not a port number")
            requested_port_no = int(requested_port_no)
        except Exception:
            raise OperationError(
                "portNo must be an integer when supplied",
                "invalid_argument", inventory_data)
        selected_candidates = [
            row for row in exact_candidates
            if row.get("PortNo") == requested_port_no]
        if not selected_candidates:
            inventory_data["requestedPortNo"] = requested_port_no
            raise OperationError(
                "portNo does not identify a physical port of the exact protocol type",
                "protocol_port_not_in_inventory", inventory_data)
    else:
        selected_candidates = exact_candidates
    if not selected_candidates:
        raise OperationError(
            "CPU has no physical port of the exact protocol type",
            "protocol_port_not_supported", inventory_data)
    if len(selected_candidates) != 1:
        inventory_data["requestedPortNo"] = requested_port_no
        inventory_data["matchingCandidateCount"] = len(selected_candidates)
        raise OperationError(
            "protocol port is ambiguous; supply a portNo from exactCandidates",
            "protocol_port_ambiguous", inventory_data)

    inventory = selected_candidates[0]
    port_no = inventory["PortNo"]
    port_type = System.Enum.ToObject(port_type_enum, spec["portType"])
    lookup_error = None
    support_error = None
    port = None
    resolved_row = None
    supported_details = []
    try:
        port = cpu.GetPortInfoByTypeAndNo(port_type, port_no)
        if port is not None:
            resolved_row = _cpu_port_inventory_row(port)
    except Exception as exc:
        lookup_error = repr(exc)
    try:
        supported_details = [
            _cpu_port_inventory_enum_row(item) for item in
            list(cpu.GetSupportBusBuyInterface(port_type) or [])]
    except Exception as exc:
        support_error = repr(exc)
    verdict = _cpu_protocol_port_verdict(
        inventory, resolved_row, supported_details, spec,
        lookup_error, support_error)
    inventory_data["selectedInventoryPort"] = inventory
    inventory_data["resolvedByTypeAndNo"] = resolved_row
    inventory_data["supportedBusesByInterface"] = supported_details
    inventory_data["verdict"] = verdict
    if not verdict["supported"] or port is None:
        raise OperationError(
            "physical protocol port failed strict cross-validation",
            "protocol_port_cross_validation_failed", inventory_data)

    # This installation has one exact PROFINET *local slave* identity, but no
    # installed PROFINET master identity.  A physical PN-capable port does not
    # authorize substituting that slave object as a master.  Keep this gate
    # after the read-only port verdict and before every configuration mutation.
    if protocol == "profinet":
        inventory_data["physicalPortInventoryVerdict"] = verdict
        inventory_data["knownLocalSlaveIdentity"] = {
            "type": 41151,
            "id": "10F4 1151",
            "version": "00.00.00.10",
            "role": "local_slave",
            "usableAsMaster": False,
        }
        inventory_data["exactMasterIdentity"] = None
        inventory_data["mutatedProject"] = False
        raise OperationError(
            "installed exact PROFINET master identity is unavailable",
            "exact_profinet_master_identity_unavailable", inventory_data)

    supported = [item["name"] for item in supported_details]
    target_bus = cpu.GetBusDescription(System.Enum.ToObject(bus_enum, spec["busType"]))
    current_bus = _get_member(port, "CurrentBusDes", "get_CurrentBusDes")
    before_bus = _text(_get_member(current_bus, "BusType", "get_BusType"))
    result = {
        "operation": operation,
        "projectPath": project_path,
        "protocol": protocol,
        "portNo": port_no,
        "portIndex": inventory["Index"],
        "portType": _text(port_type),
        "supportedBusTypes": supported,
        "supportedBusTypeDetails": supported_details,
        "portInventoryVerdict": verdict,
        "before": {"busType": before_bus, "deviceTree": device_tree()},
        "after": None,
        "mutatedProject": False,
        "configurationFactory": binding,
        "attempts": [],
    }
    if before_bus == spec["busName"]:
        result["after"] = {"busType": before_bus, "deviceTree": result["before"]["deviceTree"]}
        result["status"] = "already_enabled"
        return result
    if target_bus is None:
        raise OperationError("CPU returned no bus description for the protocol",
                             "protocol_bus_description_unavailable", result)

    prior_mode = _get_member(current_bus, "CurrentCommMode", "get_CurrentCommMode")
    new_bus = target_bus.ObjectClone()
    try:
        setattr(port, "CurrentBusDes", new_bus)
        result["attempts"].append({"binding": "IPortUseInfo.CurrentBusDes=ObjectClone",
                                    "ok": True})
        needs_mode_rebind = (
            current_bus is not None and prior_mode is not None and
            _json_safe(prior_mode) != _json_safe(
                _get_member(target_bus, "CurrentCommMode", "get_CurrentCommMode")) and
            _json_safe(prior_mode) != 4 and
            bool(_get_member(target_bus, "SupportMasterSlave", "get_SupportMasterSlave", False)))
        if needs_mode_rebind:
            setattr(new_bus, "CurrentCommMode", prior_mode)
        actual_port_no = int(_get_member(port, "PortNo", "get_PortNo", port_no))
        if protocol == "ethernet_ip":
            try:
                created = cpu.AddBusDeviceOjbects(new_bus, actual_port_no)
                created_values = list(created) if created is not None else []
                created_guids = [_text(value) for value in created_values]
                invalid_guids = [value for value in created_guids if value in (
                    "", "00000000-0000-0000-0000-000000000000")]
                if not created_guids or invalid_guids:
                    raise RuntimeError(
                        "AddBusDeviceOjbects returned no non-empty GUID list")
                result["createdGuids"] = created_guids
                result["immediateCreatedObjectReadback"] = (
                    _protocol_created_object_readback(created_guids))
                result["immediateTreeReadback"] = device_tree()
                result["attempts"].append({
                    "binding": "ICpuModule.AddBusDeviceOjbects",
                    "ok": True,
                    "portNo": actual_port_no,
                    "createdGuids": created_guids,
                })
            except Exception as exc:
                result["attempts"].append({
                    "binding": "ICpuModule.AddBusDeviceOjbects",
                    "ok": False,
                    "portNo": actual_port_no,
                    "error": repr(exc),
                })
                _mark_ethernet_ip_process_discard(result)
                raise OperationError(
                    "native EtherNet/IP bus registration failed: " + repr(exc),
                    "native_ethernet_ip_bus_registration_failed", result)
        else:
            cpu.AddBusDeviceOjbect(
                _get_member(new_bus, "DevIdentification", "get_DevIdentification"),
                actual_port_no, port_type)
            result["attempts"].append({
                "binding": "ICpuModule.AddBusDeviceOjbect",
                "ok": True,
                "portNo": actual_port_no,
            })
    except Exception as exc:
        if isinstance(exc, OperationError):
            raise
        if protocol == "ethernet_ip":
            _mark_ethernet_ip_process_discard(result)
            raise OperationError(
                "native EtherNet/IP bus registration failed: " + repr(exc),
                "native_ethernet_ip_bus_registration_failed", result)
        raise OperationError("native protocol bus registration failed: " + repr(exc),
                             "native_protocol_bus_registration_failed", result)

    mediator_factory, mediator_binding = _reflection_generic_create(
        INOVANCE_PROJECT_MEDIATOR_INTERFACE, INOVANCE_PROJECT_MEDIATOR_FACTORY_GUID)
    if mediator_factory is None:
        if protocol == "ethernet_ip":
            _mark_ethernet_ip_process_discard(result)
        raise OperationError("vendor project mediator is unavailable",
                             "protocol_mediator_unavailable", result)
    mediator = mediator_factory.CreateProjMediator(hardware, network)
    result["mediatorBinding"] = mediator_binding
    try:
        show_network = bool(_get_member(new_bus, "ShowNetwork", "get_ShowNetwork", False))
        if show_network:
            mediator.AddSpeccialDevBus(port_no, port_type)
        result["attempts"].append({"binding": "IProjectMediator.AddSpeccialDevBus",
                                    "ok": True, "called": show_network})
        result["configurationSave"] = bool(sync_project.SaveConfigurationData())
        if protocol == "ethernet_ip" and not result["configurationSave"]:
            raise RuntimeError("SaveConfigurationData returned false")
        project.save()
        result["projectSaveCompleted"] = True
    except Exception as exc:
        if protocol == "ethernet_ip":
            _mark_ethernet_ip_process_discard(result)
            raise OperationError(
                "native EtherNet/IP configuration save failed: " + repr(exc),
                "native_ethernet_ip_configuration_save_failed", result)
        raise OperationError("native protocol configuration save failed: " + repr(exc),
                             "native_protocol_configuration_save_failed", result)

    rebound_port = cpu.GetPortInfoByTypeAndNo(port_type, port_no)
    after_bus = _text(_get_member(
        _get_member(rebound_port, "CurrentBusDes", "get_CurrentBusDes"),
        "BusType", "get_BusType"))
    result["after"] = {"busType": after_bus, "deviceTree": device_tree()}
    result["mutatedProject"] = True
    if after_bus != spec["busName"]:
        if protocol == "ethernet_ip":
            _mark_ethernet_ip_process_discard(result)
        raise OperationError("protocol bus write did not survive native save",
                             "protocol_port_enable_unconfirmed", result)
    if protocol == "ethernet_ip":
        result["postSaveCreatedObjectReadback"] = (
            _protocol_created_object_readback(result.get("createdGuids") or []))
        result["persistenceIdentityBaseline"] = {
            "createdGuids": result.get("createdGuids") or [],
            "baselineComplete": result[
                "postSaveCreatedObjectReadback"].get("complete", False),
            "identityComparisonRows": result[
                "postSaveCreatedObjectReadback"].get(
                    "identityComparisonRows") or [],
            "identityComparisonSha256": result[
                "postSaveCreatedObjectReadback"].get(
                    "identityComparisonSha256"),
            "compareAfterFreshProcessReopen": True,
            "requiredComparisonFields": [
                "guid", "name", "parentGuid", "objectType", "runtimeType",
                "deviceIdentification.type", "deviceIdentification.id",
                "deviceIdentification.version",
            ],
        }
        result["committed"] = True
        result["processDiscardRequired"] = False
    result["status"] = "enabled_same_process_persistence_unverified"
    result["nextRequired"] = (
        "verify UI tree, save, fresh-process reopen, exact bus readback and second compile")
    return result


# ---------------------------------------------------------------------------
# 通讯 device add: the vendor's OWN configuration action.
#
# Source of truth (decompiled InoDeviceConfigurationManagement plugin,
# InoProShop V1.10.0.3, read 2026-09-19).  ModbusTcpDevSynConfig.AddModbusTcpDev
# is exactly what the device picker runs:
#     portIndex = cpu.GetPortIndex(portNo, CommunicationPortType.CPT_ETHERNET_PORT)
#     action = factory.CreateModubsTcpAddAction(
#         null, identity, "modbusTcp.bmp", description,
#         portIndex, portNo, hardware, network, DeviceCategory.CSDC_GENERIC)
#     action.Execute(bNeedAddDeviceObjData: false)
# The other lines share that shape; CANopen and PROFIBUS-DP carry one extra file
# argument (EDS / GSD) between the description and the port index.  The identity
# object MUST come from the installed repository row - the picker never invents
# one - and the port must already carry the protocol bus (see
# vendor.protocol.port.enable), otherwise the action's CheckDevicePermission
# fails on an empty parent GUID.
# ---------------------------------------------------------------------------
PROTOCOL_DEVICE_ADD_SPECS = {
    "modbus_tcp": {
        "interface": "Inovance.InoPro.InoDeviceConfiguration.INwModubsTcpAddActionFactory, InoDeviceConfiguration",
        "guid": "{FE16ABFC-E6A1-46C1-A8D0-96CC54B422DA}",
        "method": "CreateModubsTcpAddAction",
        "portType": 3, "busType": 6, "busName": "DBT_MODBUS_TCP",
        "picture": "modbusTcp.bmp", "fileArgument": None,
        "defaultCategory": 1,
    },
    "modbus": {
        "interface": "Inovance.InoPro.InoDeviceConfiguration.INwModubsAddActionFactory, InoDeviceConfiguration",
        "guid": "{B306B479-5D54-4DFA-99F7-6241179099FE}",
        "method": "CreateModubsAddAction",
        "portType": 1, "busType": 1, "busName": "DBT_MODBUS",
        "picture": "modbus.bmp", "fileArgument": None,
        "defaultCategory": 1,
    },
    "canopen": {
        "interface": "Inovance.InoPro.InoDeviceConfiguration.INwCanopenAddActionFactory, InoDeviceConfiguration",
        "guid": "{12B6A545-D7AE-4D0D-9111-3F8BBAC69AAF}",
        "method": "CreateCanopenAddAction",
        "portType": 2, "busType": 2, "busName": "DBT_CANOPEN",
        "picture": "networkCanOPen.bmp", "fileArgument": "edsFile",
        # The CANopen action takes the EDS product name, not the catalog row:
        # the picker reads it from ICanOpenSlaveConfig3.GetCanOpenDeviceInfo and
        # calls ProductName.Replace("'", "") before building the action, so a
        # null product name dies inside the action constructor.
        "requiresProductName": True,
        "defaultCategory": 1,
    },
    "profibus_dp": {
        "interface": "Inovance.InoPro.InoDeviceConfiguration.INwDpAddActionFactory, InoDeviceConfiguration",
        "guid": "{F60150AB-91C5-40D4-9859-27E61A183DDF}",
        "method": "CreateDpAddAction",
        "portType": 4, "busType": 4, "busName": "DBT_DP",
        "picture": "networkDP.bmp", "fileArgument": "gsdFile",
        "requiresProductName": True,
        "defaultCategory": 1,
    },
    "ethernet_ip": {
        "interface": "Inovance.InoPro.InoDeviceConfiguration.INwEtherNetIPAddActionFactory, InoDeviceConfiguration",
        "guid": "{499F9C9A-51DB-4B2A-B051-1EC6254519BF}",
        "method": "CreateEtherNetIPAddAction",
        "portType": 8, "busType": 11, "busName": "DBT_ETHERNETIP",
        "picture": "networkEthIP.bmp", "fileArgument": None,
        "defaultCategory": 1,
    },
}


CANOPEN_EDS_SERVICE_INTERFACE = (
    "Inovance.InoPro.InoDeviceBase.CanOpen.ICanOpenSlaveConfig3, "
    "InoDeviceBase"
)
CANOPEN_EDS_SERVICE_GUID = "{3196C774-A299-4C74-B8D3-49406B322A16}"
CANOPEN_VENDOR_SLAVE_IDENTITY = {
    "type": 40102,
    "id": "10F4 0102",
    "version": "00.00.00.10",
}
PROFIBUS_GSD_SERVICE_INTERFACE = (
    "Inovance.InoPro.InoDeviceBase.DP.IDPConfig, InoDeviceBase"
)
PROFIBUS_GSD_SERVICE_GUID = "{32EE2EB5-3F40-4509-AF67-99926F28ACC9}"
PROFIBUS_VENDOR_SLAVE_IDENTITY = {
    "type": 40702,
    "id": "10F4 0702",
    "version": "00.00.00.10",
}


def _canopen_eds_info(eds_file):
    """Parse an EDS through the same vendor service used by the IDE picker."""
    service, binding = _reflection_generic_create(
        CANOPEN_EDS_SERVICE_INTERFACE, CANOPEN_EDS_SERVICE_GUID)
    if service is None:
        raise OperationError(
            "the vendor CANopen EDS parser is unavailable",
            "canopen_eds_parser_unavailable",
            {"binding": binding, "edsFile": eds_file,
             "mutatedProject": False})
    try:
        info = service.GetCanOpenDeviceInfo(eds_file)
    except Exception as exc:
        raise OperationError(
            "the vendor CANopen EDS parser rejected the file: " + repr(exc),
            "canopen_eds_parse_failed",
            {"binding": binding, "edsFile": eds_file,
             "mutatedProject": False})
    if info is None:
        raise OperationError(
            "the vendor CANopen EDS parser returned no device information",
            "canopen_eds_invalid",
            {"binding": binding, "edsFile": eds_file,
             "mutatedProject": False})
    result = {
        "productName": _text(_get_member(info, "ProductName", "get_ProductName")),
        "description": _text(_get_member(info, "Description", "get_Description")),
        "vendorName": _text(_get_member(info, "VendorName", "get_VendorName")),
        "vendorNumber": _text(_get_member(info, "VendorNumber", "get_VendorNumber")),
        "productNumber": _text(_get_member(info, "ProductNumber", "get_ProductNumber")),
        "revisionNumber": _text(_get_member(info, "RevisionNumber", "get_RevisionNumber")),
        "fileVersion": _text(_get_member(info, "FileVersion", "get_FileVersion")),
        "version": _text(_get_member(info, "Version", "get_Version")),
        "support402Axis": bool(_get_member(
            info, "Support402Axis", "get_Support402Axis", False)),
        "binding": binding,
    }
    if not result["productName"]:
        raise OperationError(
            "the EDS has no ProductName accepted by the vendor CANopen parser",
            "canopen_eds_product_name_missing",
            {"edsFile": eds_file, "edsInfo": result,
             "mutatedProject": False})
    return result


def _canopen_project_object_template():
    """Resolve the AM600 CANopen slave shell filled from an external EDS.

    InoProShop's DeviceTreeDescription explicitly states that 40102 / 10F4
    0102 is the fixed project device used while importing a CANopen EDS.  A
    repository EDS row is type 18 with child interface ``Common.CANopen``;
    inserting that row directly below AM600's ``Inovance:CANopenMaster`` is
    rejected by ObjectMgr and the transient row is rolled back.
    """
    _raw, selected = _resolve_installed_device(dict(
        CANOPEN_VENDOR_SLAVE_IDENTITY))
    return selected


def _profibus_gsd_info(gsd_file):
    """Parse a GSD through the same vendor service used by the DP picker."""
    service, binding = _reflection_generic_create(
        PROFIBUS_GSD_SERVICE_INTERFACE, PROFIBUS_GSD_SERVICE_GUID)
    if service is None:
        raise OperationError(
            "the vendor PROFIBUS GSD parser is unavailable",
            "profibus_gsd_parser_unavailable",
            {"binding": binding, "gsdFile": gsd_file,
             "mutatedProject": False})
    try:
        info = service.GetDPSlaveDeviceInfo(gsd_file)
    except Exception as exc:
        raise OperationError(
            "the vendor PROFIBUS GSD parser rejected the file: " + repr(exc),
            "profibus_gsd_parse_failed",
            {"binding": binding, "gsdFile": gsd_file,
             "mutatedProject": False})
    if info is None:
        raise OperationError(
            "the vendor PROFIBUS GSD parser returned no device information",
            "profibus_gsd_invalid",
            {"binding": binding, "gsdFile": gsd_file,
             "mutatedProject": False})
    result = {
        "modelName": _text(_get_member(info, "ModelName", "get_ModelName")),
        "description": _text(_get_member(
            info, "Description", "get_Description")),
        "identNumber": _json_safe(_get_member(
            info, "IdentNumber", "get_IdentNumber")),
        "maxModule": _json_safe(_get_member(
            info, "MaxModule", "get_MaxModule")),
        "runtimeType": (_text(info.GetType().FullName)
                        if info is not None and hasattr(info, "GetType")
                        else _text(type(info))),
        "binding": binding,
    }
    if not result["modelName"]:
        raise OperationError(
            "the GSD has no ModelName accepted by the vendor PROFIBUS parser",
            "profibus_gsd_model_name_missing",
            {"gsdFile": gsd_file, "gsdInfo": result,
             "mutatedProject": False})
    return result


def _profibus_project_object_template():
    """Resolve the fixed AM600/AM610 DP slave shell filled from a GSD.

    The vendor DeviceTreeDescription explicitly states that 40702 / 10F4 0702
    is the project object used while importing a PROFIBUS-DP GSD.  The GSD
    parser supplies the model, limits and module definitions; the shell is the
    object identity accepted by the Inovance:DPMaster connector.
    """
    _raw, selected = _resolve_installed_device(dict(
        PROFIBUS_VENDOR_SLAVE_IDENTITY))
    return selected


def _protocol_device_add_identity(selected):
    """Build the ConfigDeviceIdentification the vendor picker passes."""
    import System
    identity = System.Activator.CreateInstance(_reflection_type(
        "Inovance.InoPro.InoProfileParser.ConfigDeviceIdentification, "
        "InoProfileParser"))
    device_id = selected.get("deviceId") or {}
    identity.Type = int(device_id.get("type"))
    identity.Id = _text(device_id.get("id"))
    identity.Version = _text(device_id.get("version") or "0")
    identity.DeviceName = _text(selected.get("name") or "")
    return identity


def _protocol_port_row(cpu, port_type, port_no):
    """Exact physical port of this protocol type, or a typed boundary error."""
    rows = []
    try:
        raw_ports = _get_member(cpu, "PortUseInfoArray", "get_PortUseInfoArray", None)
        rows = [_cpu_port_inventory_row(item) for item in list(raw_ports)]
    except Exception as exc:
        raise OperationError(
            "CPU physical port inventory is unavailable: " + repr(exc),
            "cpu_port_inventory_unreadable", {"mutatedProject": False})
    exact = [row for row in rows
             if (row.get("PortType") or {}).get("value") == port_type]
    if port_no is not None:
        exact = [row for row in exact if row.get("PortNo") == port_no]
    if not exact:
        raise OperationError(
            "the CPU has no physical port of this protocol type",
            "protocol_port_not_supported",
            {"portType": port_type, "portNo": port_no, "ports": rows,
             "mutatedProject": False})
    if len(exact) != 1:
        raise OperationError(
            "protocol port is ambiguous; pass portNo from the port inventory",
            "protocol_port_ambiguous",
            {"portType": port_type, "portNo": port_no,
             "candidates": exact, "mutatedProject": False})
    return exact[0]


def vendor_protocol_device_add(req):
    """Add one installed 通讯 device through the vendor configuration action."""
    operation = "vendor.protocol.device.add"
    project_path = _require_current_disposable_project(req, operation)
    _require_confirmation(req, ("add_protocol_device", "protocol_device_add"))
    protocol = _normalize_offline_protocol(req.get("protocol"))
    spec = PROTOCOL_DEVICE_ADD_SPECS.get(protocol)
    if spec is None:
        raise OperationError(
            "protocol must be one of modbus_tcp, modbus, canopen, profibus_dp, "
            "ethernet_ip",
            "invalid_argument",
            {"path": "protocol", "actual": protocol,
             "allowed": sorted(PROTOCOL_DEVICE_ADD_SPECS.keys()),
             "mutatedProject": False})
    selector_req = _device_selector_request(req, False)
    selector_present = any(selector_req.get(key) is not None for key in (
        "name", "selectorName", "catalogName", "deviceName", "device_name",
        "type", "id", "version",
    ))
    requested_selection = None
    if selector_present:
        _raw, requested_selection = _resolve_installed_device(req)
    if protocol == "profibus_dp":
        # GSD rows are not project objects.  InoProShop always creates the
        # fixed 40702 slave shell and fills it from IDPConfig, even when its
        # picker started from a catalog row.  Keep an optional caller selector
        # only as audit evidence; it must never replace the project shell.
        selected = _profibus_project_object_template()
    elif protocol == "canopen" and not selector_present:
        # The EDS contains the real product identity.  Requiring the model to
        # discover the internal 40102 shell first only leaks an implementation
        # detail and caused avoidable selector failures.
        selected = _canopen_project_object_template()
    else:
        if requested_selection is None:
            _raw, requested_selection = _resolve_installed_device(req)
        selected = requested_selection
    device_id = selected.get("deviceId") or {}
    result = {
        "operation": operation,
        "projectPath": project_path,
        "protocol": protocol,
        "selection": _json_safe(selected),
        "requestedSelection": _json_safe(requested_selection),
        "factory": {"interface": spec["interface"], "guid": spec["guid"],
                    "method": spec["method"]},
        "bus": {"portType": spec["portType"], "busType": spec["busType"],
                "busName": spec["busName"]},
        "attempts": [],
        "mutatedProject": False,
    }
    import System
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable",
                             {"binding": binding, "mutatedProject": False})
    result["configurationFactory"] = binding
    sync_project = factory.CreateConfigSyncProj()
    if sync_project is None:
        raise OperationError("configuration sync project is unavailable",
                             "configuration_sync_unavailable",
                             {"mutatedProject": False})
    sync_project.StartSyncToConfigrationDataObject()
    hardware = _get_member(sync_project, "HardwareConfigProject",
                           "get_HardwareConfigProject")
    network = _get_member(sync_project, "NetworkConfigProject",
                          "get_NetworkConfigProject")
    if hardware is None or network is None:
        raise OperationError("vendor configuration graph is unavailable",
                             "protocol_configuration_graph_unavailable",
                             {"mutatedProject": False})
    cpu = hardware.GetCpuModule()
    if cpu is None:
        raise OperationError("the open project has no CPU module",
                             "cpu_module_unavailable", {"mutatedProject": False})
    port_type_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.CommunicationPortType, "
        "InoDeviceConfiguration")
    bus_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.DevBusType, "
        "InoDeviceConfiguration")
    category_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.DeviceCategory, "
        "InoDeviceConfiguration")
    if port_type_enum is None or bus_enum is None or category_enum is None:
        raise OperationError("vendor protocol enums are unavailable",
                             "protocol_bus_enum_unavailable",
                             {"mutatedProject": False})
    requested_port_no = req.get("portNo")
    if requested_port_no is not None:
        try:
            requested_port_no = int(requested_port_no)
        except Exception:
            raise OperationError("portNo must be an integer", "invalid_argument",
                                 {"path": "portNo", "actual": req.get("portNo"),
                                  "mutatedProject": False})
    port_row = _protocol_port_row(cpu, spec["portType"], requested_port_no)
    port_no = int(port_row.get("PortNo") or 0)
    result["port"] = port_row
    port_type = System.Enum.ToObject(port_type_enum, spec["portType"])
    try:
        port = cpu.GetPortInfoByTypeAndNo(port_type, port_no)
    except Exception as exc:
        raise OperationError("the physical port could not be resolved: " + repr(exc),
                             "protocol_port_lookup_failed",
                             {"portNo": port_no, "mutatedProject": False})
    current_bus = _get_member(port, "CurrentBusDes", "get_CurrentBusDes", None)
    current_bus_type = _text(_get_member(current_bus, "BusType", "get_BusType", ""))
    result["portBusBefore"] = current_bus_type
    if current_bus_type != spec["busName"]:
        raise OperationError(
            "the physical port does not carry the %s bus yet (found %s); a "
            "device can only be added under an enabled bus"
            % (spec["busName"], current_bus_type or "none"),
            "protocol_port_not_enabled",
            {"protocol": protocol, "portNo": port_no,
             "expectedBus": spec["busName"], "observedBus": current_bus_type,
             "mutatedProject": False,
             "next": {"tool": "inoproshop_protocol_port_enable",
                      "arguments": {"protocol": protocol, "portNo": port_no,
                                    "confirm": "enable_protocol_port",
                                    "disposable": True},
                      "then": "enable the protocol bus on this port, then "
                              "repeat the device add"}})
    # InoProShop exposes two different indices for the same physical port:
    # IPortUseInfo.Index is the position in the CPU's complete port inventory,
    # while ICpuModule.GetPortIndex is the index within one port type.  The
    # decompiled vendor picker passes GetPortIndex to Create*AddAction.  Keep
    # both values in the receipt so a profile-specific disagreement is visible
    # instead of silently collapsing them into one number.  portIndex is an
    # internal disposable-project probe override; public cards intentionally do
    # not expose it until a non-vendor profile proves that it is required.
    inventory_port_index = port_row.get("Index")
    vendor_port_index = None
    vendor_port_index_error = None
    try:
        vendor_port_index = int(cpu.GetPortIndex(port_no, port_type))
    except Exception as exc:
        vendor_port_index_error = repr(exc)
    requested_port_index = req.get("portIndex")
    if requested_port_index is not None:
        try:
            port_index = int(requested_port_index)
        except Exception:
            raise OperationError("portIndex must be an integer", "invalid_argument",
                                 {"path": "portIndex",
                                  "actual": requested_port_index,
                                  "mutatedProject": False})
        port_index_source = "disposable_probe_override"
    elif vendor_port_index is not None:
        port_index = vendor_port_index
        port_index_source = "ICpuModule.GetPortIndex"
    else:
        port_index = int(inventory_port_index)
        port_index_source = "IPortUseInfo.Index_fallback"
    result["portIndex"] = port_index
    result["portIndexResolution"] = {
        "selected": port_index,
        "source": port_index_source,
        "vendorTypeRelativeIndex": vendor_port_index,
        "inventoryIndex": inventory_port_index,
        "vendorLookupError": vendor_port_index_error,
        "indicesDiffer": (vendor_port_index is not None and
                          inventory_port_index is not None and
                          int(vendor_port_index) != int(inventory_port_index)),
    }
    add_factory, add_binding = _reflection_generic_create(
        spec["interface"], spec["guid"])
    if add_factory is None:
        raise OperationError("the vendor 通讯 add factory is not registered",
                             "protocol_device_add_factory_unavailable",
                             {"factory": spec["interface"], "guid": spec["guid"],
                              "binding": add_binding, "mutatedProject": False})
    result["actionFactory"] = add_binding
    identity_selection = selected
    if protocol == "canopen" and int(device_id.get("type") or 0) == 18:
        identity_selection = _canopen_project_object_template()
        result["identityAdaptation"] = {
            "reason": "external EDS rows use Common.CANopen while the AM600 "
                      "master accepts its fixed Inovance CANopen slave shell",
            "sourceIdentity": _json_safe(device_id),
            "projectObjectTemplate": _json_safe(
                identity_selection.get("deviceId") or {}),
            "vendorRecipe": "DeviceTreeDescription canopen_protocol + "
                            "CanOpenSlaveConfig.FillEdsFileToDeviceObject",
        }
    elif protocol == "canopen" and not selector_present:
        result["identityAdaptation"] = {
            "reason": "the EDS supplies the real device identity; the project "
                      "uses InoProShop's fixed CANopen slave shell",
            "sourceIdentity": None,
            "projectObjectTemplate": _json_safe(device_id),
            "vendorRecipe": "DeviceTreeDescription canopen_protocol + "
                            "CanOpenSlaveConfig.FillEdsFileToDeviceObject",
        }
    elif protocol == "profibus_dp":
        result["identityAdaptation"] = {
            "reason": "the GSD supplies the real device model and module data; "
                      "the project uses InoProShop's fixed PROFIBUS-DP slave shell",
            "sourceIdentity": _json_safe(
                (requested_selection or {}).get("deviceId") or None),
            "projectObjectTemplate": _json_safe(device_id),
            "vendorRecipe": "DeviceTreeDescription dp_protocol + "
                            "DPDevSynConfig.GetDPSlaveDeviceInfo",
        }
    identity = _protocol_device_add_identity(identity_selection)
    picture = _text(req.get("picture") or spec["picture"])
    category_value = req.get("deviceCategory")
    if category_value is None:
        category_value = spec["defaultCategory"]
    try:
        category_value = int(category_value)
    except Exception:
        raise OperationError("deviceCategory must be 0 (CSDC_AM600) or 1 "
                             "(CSDC_GENERIC)", "invalid_argument",
                             {"path": "deviceCategory",
                              "actual": req.get("deviceCategory"),
                              "mutatedProject": False})
    category = System.Enum.ToObject(category_enum, category_value)
    file_value = None
    eds_info = None
    gsd_info = None
    if spec.get("fileArgument"):
        file_argument = spec["fileArgument"]
        file_value = _text(req.get(file_argument) or "").strip()
        if not file_value:
            raise OperationError(
                "the %s add action needs %s: the vendor action resolves the "
                "device from that file and pops a modal '文件不存在()' (which "
                "blocks the IDE) when it is missing" % (protocol, file_argument),
                "protocol_device_file_required",
                {"protocol": protocol, "field": file_argument,
                 "selection": _json_safe(selected), "mutatedProject": False,
                 "next": {"arguments": {file_argument: "<absolute EDS/GSD path>"},
                          "then": "pass the device's real EDS/GSD file; the "
                                  "picker reads it from the device object, it is "
                                  "not a catalog name"}})
        if not os.path.isfile(file_value):
            raise OperationError(
                "the %s file does not exist on this machine: %s"
                % (file_argument, file_value),
                "protocol_device_file_not_found",
                {"protocol": protocol, "field": file_argument,
                 "path": file_value, "mutatedProject": False,
                 "next": {"then": "pass an existing EDS/GSD file path; calling "
                                  "the vendor action with a missing file opens a "
                                  "blocking modal and hangs the IDE (measured "
                                  "2026-09-19)"}})
        if protocol == "canopen":
            eds_info = _canopen_eds_info(file_value)
            result["edsInfo"] = eds_info
        elif protocol == "profibus_dp":
            gsd_info = _profibus_gsd_info(file_value)
            result["gsdInfo"] = gsd_info
    product_name = _text(req.get("productName") or "").strip()
    if protocol == "ethernet_ip":
        # The EtherNet/IP action dereferences its first string argument while
        # creating device-object data.  Passing None makes Execute(true) die
        # with a vendor NullReferenceException; Execute(false) then reports
        # success without adding a tree row.  The installed EDS catalog row is
        # already the authoritative product name, so resolve it automatically
        # and reject a contradictory override before any mutation.
        catalog_product_name = _text(selected.get("name") or "").strip()
        if product_name and catalog_product_name and product_name != catalog_product_name:
            raise OperationError(
                "productName does not match the installed EtherNet/IP EDS device name",
                "ethernet_ip_product_name_mismatch",
                {"provided": product_name, "catalog": catalog_product_name,
                 "selection": _json_safe(selected), "mutatedProject": False})
        product_name = catalog_product_name or product_name
        result["productNameResolution"] = {
            "source": "installed_eds_catalog_name" if catalog_product_name else "request",
            "value": product_name,
        }
    if protocol == "canopen" and eds_info is not None:
        parsed_product_name = _text(eds_info.get("productName")).strip()
        if product_name and product_name != parsed_product_name:
            raise OperationError(
                "productName does not match the vendor-parsed EDS ProductName",
                "canopen_eds_product_name_mismatch",
                {"provided": product_name, "parsed": parsed_product_name,
                 "edsFile": file_value, "mutatedProject": False})
        product_name = parsed_product_name
    elif protocol == "profibus_dp" and gsd_info is not None:
        parsed_model_name = _text(gsd_info.get("modelName")).strip()
        if product_name and product_name != parsed_model_name:
            raise OperationError(
                "productName does not match the vendor-parsed GSD ModelName",
                "profibus_gsd_model_name_mismatch",
                {"provided": product_name, "parsed": parsed_model_name,
                 "gsdFile": file_value, "mutatedProject": False})
        product_name = parsed_model_name
    if spec.get("requiresProductName") and not product_name:
        raise OperationError(
            "the %s add action needs the device's own product name (the EDS/GSD "
            "product name the vendor device shows), not just its catalog row"
            % protocol,
            "protocol_device_product_name_required",
            {"protocol": protocol, "selection": _json_safe(selected),
             "mutatedProject": False,
             "next": {"arguments": {"productName": "<product name from the "
                                                   "device's EDS/GSD>"},
                      "then": "re-send with productName set; the picker reads it "
                              "from the device object, and the action dies on a "
                              "null product name"}})
    parsed_description = ""
    if eds_info is not None:
        parsed_description = _text(eds_info.get("description")).strip()
    elif gsd_info is not None:
        parsed_description = _text(gsd_info.get("description")).strip()
    description = _text(req.get("description") or parsed_description or
                        product_name or selected.get("description") or
                        selected.get("name") or protocol)
    call_args = [product_name or None, identity, picture, description]
    if spec.get("fileArgument"):
        call_args.append(file_value)
    call_args.extend([port_index, port_no, hardware, network, category])
    result["callShape"] = {
        "method": spec["method"],
        "identity": {"type": identity.Type, "id": identity.Id,
                     "version": identity.Version,
                     "deviceName": identity.DeviceName},
        "picture": picture,
        "category": {"name": ("CSDC_AM600" if category_value == 0
                              else "CSDC_GENERIC"),
                     "value": category_value},
        "portIndex": port_index,
        "portNo": port_no,
        "fileArgument": spec.get("fileArgument") or None,
    }
    before_tree = device_tree()
    method = getattr(add_factory, spec["method"], None)
    if not hasattr(method, "__call__"):
        raise OperationError("the vendor factory has no " + spec["method"],
                             "protocol_device_add_factory_unavailable",
                             {"factory": spec["interface"],
                              "methods": _member_names(add_factory, ["create"]),
                              "mutatedProject": False})
    try:
        action = method(*call_args)
    except Exception as exc:
        raise OperationError(
            "the vendor action could not be constructed: " + repr(exc),
            "protocol_device_add_action_rejected", result)
    result["attempts"].append({"binding": spec["method"], "ok": True})
    # Two overloads exist: Execute(bool bNeedAddDeviceObjData) and Execute().
    # The device picker calls Execute(false) because the IDE's object framework
    # creates the device object afterwards; a standalone scripting add has to
    # create that data itself, so try the requested variant first (default
    # true) and record what the other one did instead of guessing.
    requested_flag = req.get("createDeviceObjectData")
    if requested_flag is None:
        requested_flag = True
    order = [bool(requested_flag), not bool(requested_flag)]
    executed = None
    execute_error = None
    for flag in order:
        try:
            executed = bool(action.Execute(flag))
            result["attempts"].append({
                "binding": "IConfigAction.Execute",
                "createDeviceObjectData": flag, "ok": True,
                "returned": executed})
            result["createDeviceObjectData"] = flag
            break
        except Exception as exc:
            execute_error = exc
            result["attempts"].append({
                "binding": "IConfigAction.Execute",
                "createDeviceObjectData": flag, "ok": False,
                "error": repr(exc)})
            tree_now = device_tree()
            result.setdefault("treesAfterFailedExecute", []).append({
                "createDeviceObjectData": flag,
                "deviceCount": tree_now.get("count"),
                "paths": [_text(item.get("path")) for item in
                          (tree_now.get("devices") or [])]})
    result["executed"] = executed
    if executed is None:
        before_count = before_tree.get("count")
        result["mutatedProject"] = any(
            row.get("deviceCount") not in (None, before_count)
            for row in (result.get("treesAfterFailedExecute") or []))
        result["before"] = {"deviceCount": before_count}
        result["status"] = "execute_failed_both_variants"
        raise OperationError(
            "the vendor action raised for both Execute variants: "
            + repr(execute_error),
            "protocol_device_add_execute_failed", result)
    result["mutatedProject"] = True
    if not executed:
        result["status"] = "action_returned_false"
        result["nextRequired"] = (
            "the vendor action refused the add; check the port bus, the identity "
            "row and the device category before retrying")
        return result
    try:
        result["configurationSave"] = bool(sync_project.SaveConfigurationData())
    except Exception as exc:
        result["configurationSaveError"] = repr(exc)
    try:
        project.save()
        result["projectSaveCompleted"] = True
    except Exception as exc:
        result["projectSaveError"] = repr(exc)
    after_tree = device_tree()
    before_paths = set(_text(item.get("path")) for item in
                       (before_tree.get("devices") or []))
    new_paths = [_text(item.get("path")) for item in
                 (after_tree.get("devices") or [])
                 if _text(item.get("path")) not in before_paths]
    result["before"] = {"deviceCount": before_tree.get("count")}
    result["after"] = {"deviceCount": after_tree.get("count"),
                       "newDevicePaths": new_paths,
                       "deviceTree": after_tree}
    result["created"] = bool(new_paths)
    result["persistenceVerified"] = False
    result["status"] = ("added_same_process_readback"
                        if new_paths else "action_reported_success_no_tree_row")
    result["nextRequired"] = (
        "prove persistence: save, reopen the project in a fresh process, read "
        "the device tree again and compile; an action that reports success "
        "without a new tree row is the transient-row failure mode")
    result["boundary"] = (
        "This is the vendor add action (Create*AddAction + the recorded "
        "Execute(bool) variant). Same-process tree readback is only the first "
        "gate; save/reopen and compilation remain mandatory.")
    if not new_paths:
        raise OperationError(
            "the vendor action returned success but no project device row "
            "survived ObjectMgr relationship checks",
            "protocol_device_add_unconfirmed", result)
    return result


def _ethernet_ip_parameter_rows(target, depth=3):
    probe = vendor_device_parameter_probe({
        "target": target,
        "depth": depth,
        "scenario": "ethernet_ip_engineering",
    })
    device_id = probe.get("deviceId") or {}
    try:
        device_type = int(device_id.get("type") or 0)
    except Exception:
        device_type = 0
    if device_type != 101:
        raise OperationError(
            "target is not an installed EtherNet/IP adapter device",
            "ethernet_ip_adapter_target_required",
            {"target": target, "deviceId": device_id,
             "expectedDeviceType": 101, "mutatedProject": False})
    connector = None
    for row in probe.get("connectors") or []:
        try:
            connector_id = int(row.get("connectorId"))
        except Exception:
            connector_id = None
        if connector_id == 0:
            connector = row
            break
    if connector is None:
        raise OperationError(
            "EtherNet/IP adapter connector 0 is unavailable",
            "ethernet_ip_connector_unavailable",
            {"target": target, "connectors": probe.get("connectors") or [],
             "mutatedProject": False})
    parameters = {}
    for row in connector.get("parameters") or []:
        try:
            parameters[int(row.get("id"))] = row
        except Exception:
            continue
    return probe, connector, parameters


def _ethernet_ip_value_int(value):
    text = _text(value).strip()
    try:
        return int(text, 0)
    except Exception:
        try:
            return int(text)
        except Exception:
            return None


def _ethernet_ip_value_bool(value):
    text = _text(value).strip().lower()
    if text in ("true", "1"):
        return True
    if text in ("false", "0"):
        return False
    return None


def _ethernet_ip_byte_array(value):
    text = _text(value).strip().strip("[]")
    if not text:
        return []
    result = []
    for raw in text.split(","):
        item = raw.strip()
        try:
            if item.lower().startswith("16#"):
                result.append(int(item[3:], 16))
            elif item.lower().startswith("0x"):
                result.append(int(item[2:], 16))
            elif re.match(r"^[0-9]+$", item):
                result.append(int(item, 10))
            else:
                return []
        except Exception:
            return []
    return result


def _ethernet_ip_child_values(element):
    result = {}
    for child in (element or {}).get("children") or []:
        name = _text(child.get("identifier") or child.get("visibleName")).strip()
        if not name:
            continue
        value = child.get("value")
        parsed = _ethernet_ip_value_int(value)
        if parsed is None:
            parsed_bool = _ethernet_ip_value_bool(value)
            parsed = parsed_bool if parsed_bool is not None else value
        result[name] = parsed
    return result


def _ethernet_ip_repository_root():
    try:
        import System
        executable = _text(
            System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName)
        install_root = os.path.dirname(os.path.dirname(executable))
        candidate = os.path.join(install_root, "Repository", "Devices")
        if os.path.isdir(candidate):
            return candidate
    except Exception:
        pass
    return None


def _ethernet_ip_eds_contract(device_id):
    repository = _ethernet_ip_repository_root()
    if not repository:
        return {"available": False, "reason": "device_repository_unavailable"}
    try:
        device_type = str(int(device_id.get("type")))
    except Exception:
        return {"available": False, "reason": "device_identity_incomplete"}
    device_name = _text(device_id.get("id")).strip()
    root = os.path.join(repository, device_type, device_name)
    if not os.path.isdir(root):
        return {"available": False, "reason": "eds_identity_directory_missing",
                "identityRoot": root}
    matches = []
    for directory, _folders, files in os.walk(root):
        for name in files:
            if name.lower().endswith(".eds"):
                matches.append(os.path.join(directory, name))
    matches.sort()
    if not matches:
        return {"available": False, "reason": "eds_file_missing",
                "identityRoot": root}
    path = matches[0]
    try:
        with open(path, "rb") as stream:
            raw = stream.read()
        text = _decode_bytes(raw)
    except Exception as exc:
        return {"available": False, "reason": "eds_read_failed",
                "path": path, "error": repr(exc)}
    parameters = []
    for match in re.finditer(r"(?ms)^\s*Param(\d+)\s*=\s*(.*?);", text):
        number = int(match.group(1))
        body = match.group(2)
        name_match = re.search(
            r'(?m)^\s*"([^"]*)"\s*,\s*\$\s*name\s*$', body)
        limits_match = re.search(
            r"(?m)^\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*,"
            r"\s*\$\s*min,\s*max,\s*default data values", body)
        row = {"number": number,
               "name": name_match.group(1) if name_match else ""}
        if limits_match:
            row["minimum"] = int(limits_match.group(1))
            row["maximum"] = int(limits_match.group(2))
            row["default"] = int(limits_match.group(3))
        parameters.append(row)
    rpi = None
    for row in parameters:
        if "rpi" in _text(row.get("name")).lower():
            rpi = row
            break
    try:
        digest = hashlib.sha256(raw).hexdigest()
    except Exception:
        digest = None
    return {"available": True, "path": path, "sha256": digest,
            "parameters": parameters, "rpi": rpi}


def _ethernet_ip_io_task_contract(target):
    parts = [item for item in _text(target).split("/") if item]
    if len(parts) < 2:
        return {"available": False, "reason": "master_path_unavailable"}
    master_name = parts[-2]
    expected_program = master_name + ".IOCycle"
    candidates = []
    try:
        tasks = _find_tasks()
    except Exception as exc:
        return {"available": False, "reason": "task_inventory_failed",
                "error": repr(exc), "expectedProgram": expected_program}
    for path, task in tasks:
        summary = _task_summary(path, task)
        calls = []
        for key in ("pouCalls", "childCalls"):
            for row in summary.get(key) or []:
                name = _text(row.get("name"))
                if name and name not in calls:
                    calls.append(name)
        if expected_program not in calls:
            continue
        interval = _text(summary.get("interval")).strip()
        match = re.match(r"^t#([0-9]+)(us|\xb5s|\u00b5s|ms|s)$",
                         interval.lower())
        row = {"task": path, "taskName": summary.get("name"),
               "interval": interval, "expectedProgram": expected_program,
               "calls": calls}
        if match is not None:
            unit = "us" if match.group(2) in ("us", "\xb5s", "\u00b5s") else match.group(2)
            scale = {"us": 1, "ms": 1000, "s": 1000000}[unit]
            row["cycleUs"] = int(match.group(1)) * scale
        candidates.append(row)
    if len(candidates) != 1 or not candidates[0].get("cycleUs"):
        return {"available": False,
                "reason": ("io_task_ambiguous" if len(candidates) > 1
                           else "io_task_not_found"),
                "masterName": master_name,
                "expectedProgram": expected_program,
                "candidates": candidates}
    result = candidates[0]
    result["available"] = True
    result["masterName"] = master_name
    return result


def vendor_protocol_ethernet_ip_read(req):
    """Normalized engineering view of one installed EtherNet/IP adapter."""
    _require_project()
    target = _text(req.get("target") or "").strip()
    if not target:
        raise OperationError("target is required", "invalid_argument",
                             {"path": "target", "mutatedProject": False})
    probe, connector, parameters = _ethernet_ip_parameter_rows(target, 4)

    def parameter(parameter_id):
        return parameters.get(int(parameter_id)) or {}

    def element(parameter_id):
        return parameter(parameter_id).get("element") or {}

    ip_bytes = _ethernet_ip_byte_array(element(256).get("value"))
    target_ip = None
    if len(ip_bytes) == 4 and all(0 <= item <= 255 for item in ip_bytes):
        target_ip = ".".join(str(item) for item in ip_bytes)
    connections = []
    for parameter_id in sorted(parameters):
        row_element = element(parameter_id)
        if _text(row_element.get("visibleName")) != "Connection Settings":
            continue
        index = len(connections)
        low = parameter_id & 0xFFF
        if low > 0:
            index = low - 1
        values = _ethernet_ip_child_values(row_element)
        path_row = parameter(0x10002001 + index)
        path_bytes = _ethernet_ip_byte_array(
            (path_row.get("element") or {}).get("value"))
        connections.append({
            "index": index,
            "parameterId": parameter_id,
            "rpiUs": values.get("RPI"),
            "timeoutMultiplier": values.get("TimeoutMultiplier"),
            "otConnectionParameters": values.get("OTConnectionParams"),
            "toConnectionParameters": values.get("TOConnectionParams"),
            "transportType": values.get("TransportType"),
            "connectionFlags": values.get("ConnectionFlags"),
            "connectionPath": path_bytes,
            "raw": values,
        })
    assemblies = []
    for parameter_id in sorted(parameters):
        row = parameter(parameter_id)
        row_element = row.get("element") or {}
        channel_type = _text(row_element.get("channelType")).lower()
        if channel_type not in ("input", "output"):
            continue
        mapping = row.get("ioMapping") or {}
        variables = [_text(item.get("variable")) for item in
                     (mapping.get("variableMappings") or [])
                     if _text(item.get("variable"))]
        assemblies.append({
            "connectionIndex": parameter_id & 0xFFFF,
            "direction": channel_type,
            "flow": ("target_to_scanner" if channel_type == "input"
                     else "scanner_to_target"),
            "parameterId": parameter_id,
            "name": row_element.get("visibleName"),
            "bitSize": row_element.get("bitSize"),
            "byteSize": (int(row_element.get("bitSize")) // 8
                         if row_element.get("bitSize") is not None else None),
            "iecAddress": mapping.get("iecAddress"),
            "variables": variables,
            "mappingCount": len(variables),
        })
    eds = _ethernet_ip_eds_contract(probe.get("deviceId") or {})
    io_task = _ethernet_ip_io_task_contract(target)
    return {
        "target": target,
        "deviceId": probe.get("deviceId"),
        "connectorId": connector.get("connectorId"),
        "targetIp": target_ip,
        "targetIpBytes": ip_bytes,
        "bootp": _ethernet_ip_value_bool(element(544).get("value")),
        "storeIp": _ethernet_ip_value_bool(element(545).get("value")),
        "numberOfConnections": _ethernet_ip_value_int(
            element(0x10000000).get("value")),
        "connections": connections,
        "assemblies": assemblies,
        "edsContract": eds,
        "ioTask": io_task,
        "parameterInventory": probe.get("parameterInventory"),
        "mutatedProject": False,
        "status": "observed",
        "verificationBoundary": {
            "offlineConfigurationReadback": True,
            "physicalClass1TrafficVerified": False,
            "reason": "a reachable physical EtherNet/IP target is required for online traffic proof",
        },
    }


def _ethernet_ip_ipv4(value):
    text = _text(value).strip()
    parts = text.split(".")
    if len(parts) != 4:
        raise OperationError(
            "targetIp must be an IPv4 address with four decimal octets",
            "ethernet_ip_invalid_ipv4",
            {"path": "targetIp", "actual": text, "mutatedProject": False})
    octets = []
    for part in parts:
        if not re.match(r"^[0-9]{1,3}$", part):
            raise OperationError(
                "targetIp contains a non-decimal octet",
                "ethernet_ip_invalid_ipv4",
                {"path": "targetIp", "actual": text,
                 "mutatedProject": False})
        octet = int(part)
        if octet < 0 or octet > 255:
            raise OperationError(
                "targetIp octets must be in 0..255",
                "ethernet_ip_invalid_ipv4",
                {"path": "targetIp", "actual": text,
                 "mutatedProject": False})
        octets.append(octet)
    return text, octets


def vendor_protocol_ethernet_ip_configure(req):
    operation = "vendor.protocol.ethernet_ip.configure"
    settings = req.get("settings")
    if settings is not None:
        if not isinstance(settings, dict):
            raise OperationError(
                "settings must be a JSON object", "invalid_argument",
                {"path": "settings", "mutatedProject": False})
        allowed_settings = set(("targetIp", "rpiUs", "bootp", "storeIp"))
        unknown_settings = sorted(set(settings).difference(allowed_settings))
        if unknown_settings:
            raise OperationError(
                "settings contains unsupported EtherNet/IP fields",
                "invalid_argument",
                {"path": "settings", "unknown": unknown_settings,
                 "allowed": sorted(allowed_settings),
                 "mutatedProject": False})
        duplicate_settings = sorted(
            name for name in allowed_settings if name in req)
        if duplicate_settings:
            raise OperationError(
                "pass EtherNet/IP values inside settings or at the top level, not both",
                "invalid_argument",
                {"path": "settings", "duplicates": duplicate_settings,
                 "mutatedProject": False})
        normalized = dict(req)
        normalized.pop("settings", None)
        normalized.update(settings)
        req = normalized
    _require_current_disposable_project(req, operation)
    _require_confirmation(req, ("configure_ethernet_ip",))
    target = _text(req.get("target") or "").strip()
    if not target:
        raise OperationError("target is required", "invalid_argument",
                             {"path": "target", "mutatedProject": False})
    supplied = [name for name in ("targetIp", "rpiUs", "bootp", "storeIp")
                if name in req]
    if not supplied:
        raise OperationError(
            "at least one EtherNet/IP setting is required",
            "ethernet_ip_no_settings",
            {"allowed": ["targetIp", "rpiUs", "bootp", "storeIp"],
             "mutatedProject": False})
    before = vendor_protocol_ethernet_ip_read({"target": target})
    changes = []
    pending_writes = []

    def write(parameter_id, element_path, value, field):
        receipt = vendor_device_parameter_write({
            "target": target,
            "connectorId": 0,
            "parameterId": parameter_id,
            "elementPath": element_path,
            "value": value,
            "confirm": "write_vendor_parameter",
            "disposable": True,
        })
        changes.append({"field": field, "parameterId": parameter_id,
                        "elementPath": element_path,
                        "before": receipt.get("before"),
                        "after": receipt.get("after"),
                        "committed": receipt.get("committed")})

    # Validate the complete request before the first vendor write.  A request
    # such as {targetIp: valid, rpiUs: invalid} must not retain the IP address
    # and then fail on the later field.
    expected = {}
    if "targetIp" in req:
        ip_text, octets = _ethernet_ip_ipv4(req.get("targetIp"))
        vendor_value = "[" + ",".join("16#%02X" % item for item in octets) + "]"
        pending_writes.append((256, [], vendor_value, "targetIp"))
        expected["targetIp"] = ip_text
    if "rpiUs" in req:
        value = req.get("rpiUs")
        if isinstance(value, bool) or not isinstance(value, _INTEGER_TYPES):
            raise OperationError(
                "rpiUs must be an integer",
                "invalid_argument",
                {"path": "rpiUs", "actual": req.get("rpiUs"),
                 "mutatedProject": False})
        value = int(value)
        contract = (before.get("edsContract") or {}).get("rpi") or {}
        minimum = contract.get("minimum")
        maximum = contract.get("maximum")
        if minimum is None or maximum is None:
            raise OperationError(
                "the installed EDS does not expose an RPI range; refusing to guess",
                "ethernet_ip_rpi_contract_unavailable",
                {"edsContract": before.get("edsContract"),
                 "mutatedProject": False})
        if value < int(minimum) or value > int(maximum):
            raise OperationError(
                "rpiUs is outside the installed EDS range",
                "ethernet_ip_rpi_out_of_range",
                {"path": "rpiUs", "actual": value,
                 "minimum": minimum, "maximum": maximum,
                 "mutatedProject": False})
        task_contract = before.get("ioTask") or {}
        cycle_us = task_contract.get("cycleUs")
        if not task_contract.get("available") or not cycle_us:
            raise OperationError(
                "the EtherNet/IP IO task cycle could not be resolved; refusing to guess a compilable RPI",
                "ethernet_ip_io_task_contract_unavailable",
                {"ioTask": task_contract, "mutatedProject": False})
        if value % int(cycle_us) != 0:
            lower = (value // int(cycle_us)) * int(cycle_us)
            upper = lower + int(cycle_us)
            raise OperationError(
                "rpiUs must be an integer multiple of the live EtherNet/IP IO task cycle",
                "ethernet_ip_rpi_not_task_multiple",
                {"path": "rpiUs", "actual": value,
                 "taskCycleUs": cycle_us, "ioTask": task_contract,
                 "nearestValid": [item for item in (lower, upper)
                                  if item >= int(minimum) and
                                  item <= int(maximum)],
                 "mutatedProject": False})
        connection_index = req.get("connectionIndex", 0)
        if (isinstance(connection_index, bool) or
                not isinstance(connection_index, _INTEGER_TYPES)):
            raise OperationError("connectionIndex must be an integer",
                                 "invalid_argument",
                                 {"path": "connectionIndex",
                                  "mutatedProject": False})
        connection_index = int(connection_index)
        matches = [row for row in before.get("connections") or []
                   if row.get("index") == connection_index]
        if len(matches) != 1:
            raise OperationError(
                "connectionIndex does not identify one EtherNet/IP connection",
                "ethernet_ip_connection_not_found",
                {"connectionIndex": connection_index,
                 "available": [row.get("index") for row in
                               before.get("connections") or []],
                 "mutatedProject": False})
        pending_writes.append(
            (matches[0]["parameterId"], ["RPI"], value, "rpiUs"))
        expected["rpiUs"] = {"connectionIndex": connection_index,
                             "value": value}
    for field, parameter_id in (("bootp", 544), ("storeIp", 545)):
        if field not in req:
            continue
        value = req.get(field)
        if not isinstance(value, bool):
            raise OperationError(
                field + " must be a JSON boolean",
                "invalid_argument",
                {"path": field, "actual": value,
                 "mutatedProject": False})
        pending_writes.append(
            (parameter_id, [], "TRUE" if value else "FALSE", field))
        expected[field] = value
    for parameter_id, element_path, value, field in pending_writes:
        write(parameter_id, element_path, value, field)
    after = vendor_protocol_ethernet_ip_read({"target": target})
    mismatches = []
    for field in ("targetIp", "bootp", "storeIp"):
        if field in expected and after.get(field) != expected[field]:
            mismatches.append({"field": field, "expected": expected[field],
                               "actual": after.get(field)})
    if "rpiUs" in expected:
        target_index = expected["rpiUs"]["connectionIndex"]
        rows = [row for row in after.get("connections") or []
                if row.get("index") == target_index]
        actual = rows[0].get("rpiUs") if len(rows) == 1 else None
        if actual != expected["rpiUs"]["value"]:
            mismatches.append({"field": "rpiUs",
                               "connectionIndex": target_index,
                               "expected": expected["rpiUs"]["value"],
                               "actual": actual})
    if mismatches:
        raise OperationError(
            "EtherNet/IP configuration did not retain every requested value",
            "ethernet_ip_configuration_not_retained",
            {"changes": changes, "mismatches": mismatches,
             "after": after, "mutatedProject": True})
    return {
        "target": target,
        "changes": changes,
        "readback": after,
        "mutatedProject": True,
        "persistenceVerified": False,
        "status": "committed_same_process_requires_restart_gate",
        "nextRequired": "save, reopen in a fresh process, call the read tool again, and compile before delivery",
    }


def vendor_protocol_ethernet_ip_mapping(req):
    operation = "vendor.protocol.ethernet_ip.mapping"
    _require_current_disposable_project(req, operation)
    _require_confirmation(req, ("map_ethernet_ip_io",))
    target = _text(req.get("target") or "").strip()
    variable = _text(req.get("variable") or "").strip()
    direction = _text(req.get("direction") or "").strip().lower()
    action = _text(req.get("action") or "add").strip().lower()
    if not target:
        raise OperationError("target is required", "invalid_argument",
                             {"path": "target", "mutatedProject": False})
    if direction not in ("input", "output"):
        raise OperationError("direction must be input or output",
                             "invalid_argument",
                             {"path": "direction", "actual": direction,
                              "mutatedProject": False})
    if action not in ("add", "remove"):
        raise OperationError("action must be add or remove", "invalid_argument",
                             {"path": "action", "actual": action,
                              "mutatedProject": False})
    if not re.match(r"^Application\.[A-Za-z_][A-Za-z0-9_]*\."
                    r"[A-Za-z_][A-Za-z0-9_]*$", variable):
        raise OperationError(
            "variable must be Application.<GVL_or_POU>.<IEC_variable>",
            "ethernet_ip_invalid_variable",
            {"path": "variable", "actual": variable,
             "mutatedProject": False})
    connection_index = req.get("connectionIndex", 0)
    if (isinstance(connection_index, bool) or
            not isinstance(connection_index, _INTEGER_TYPES)):
        raise OperationError("connectionIndex must be an integer",
                             "invalid_argument",
                             {"path": "connectionIndex",
                              "mutatedProject": False})
    connection_index = int(connection_index)
    create_variable = req.get("createVariable", False)
    if not isinstance(create_variable, bool):
        raise OperationError("createVariable must be a JSON boolean",
                             "invalid_argument",
                             {"path": "createVariable",
                              "actual": create_variable,
                              "mutatedProject": False})
    before = vendor_protocol_ethernet_ip_read({"target": target})
    matches = [row for row in before.get("assemblies") or []
               if row.get("direction") == direction and
               row.get("connectionIndex") == connection_index]
    if len(matches) != 1:
        raise OperationError(
            "no exact EtherNet/IP assembly matches direction and connectionIndex",
            "ethernet_ip_assembly_not_found",
            {"direction": direction, "connectionIndex": connection_index,
             "assemblies": before.get("assemblies") or [],
             "mutatedProject": False})
    assembly = matches[0]
    existing_variables = [
        _text(item) for item in (assembly.get("variables") or [])
        if _text(item)
    ]
    already_present = variable in existing_variables
    if ((action == "add" and already_present) or
            (action == "remove" and not already_present)):
        status = "already_present" if action == "add" else "already_absent"
        receipt = {
            "operation": operation,
            "action": action,
            "target": target,
            "parameterId": assembly["parameterId"],
            "connectorId": 0,
            "elementPath": [],
            "variable": variable,
            "createVariable": create_variable,
            "direction": direction,
            "connectionIndex": connection_index,
            "assembly": assembly,
            "status": status,
            "landed": True,
            "exactReadback": True,
            "mutationAttempted": False,
            "mutatedProject": False,
            "persistenceVerified": False,
            "candidateAttempts": [{
                "parameterSet": "ethernet_ip_normalized_readback",
                "status": status,
                "beforeVariables": existing_variables,
                "readbackVariables": existing_variables,
            }],
        }
        if action == "add":
            receipt["alreadyPresent"] = True
        else:
            receipt["alreadyAbsent"] = True
        receipt["nextRequired"] = (
            "no project write was attempted; save/reopen/compile is only "
            "required when another operation changed the project")
        return receipt
    receipt = vendor_io_variable_mapping({
        "target": target,
        "connectorId": 0,
        "parameterId": assembly["parameterId"],
        "elementPath": [],
        "variable": variable,
        "action": action,
        "createVariable": create_variable,
        "confirm": "map_variable",
        "disposable": True,
    })
    receipt["operation"] = operation
    receipt["assembly"] = assembly
    receipt["direction"] = direction
    receipt["connectionIndex"] = connection_index
    receipt["persistenceVerified"] = False
    receipt["nextRequired"] = (
        "save, reopen in a fresh process, read the EtherNet/IP adapter again, "
        "and compile before delivery")
    return receipt


def _ethercat_missing_port_details(cpu, port_no, port_type):
    """Keep a failed exact lookup separate from physical capability evidence."""
    inventory = {"source": "CPUModule.PortUseInfoArray", "readable": False,
                 "complete": False, "ports": [], "readErrors": []}
    try:
        raw = _get_member(cpu, "PortUseInfoArray", "get_PortUseInfoArray", None)
        if raw is None:
            raise ValueError("PortUseInfoArray is unavailable")
        raw_ports = list(raw)
        inventory["readable"] = True
        for value in raw_ports:
            try:
                row = _cpu_port_inventory_row(value)
                inventory["ports"].append(row)
                if row["PortNo"] is None or row["PortType"]["value"] is None:
                    inventory["readErrors"].append("port identity is incomplete")
            except Exception as exc:
                inventory["readErrors"].append(repr(exc))
        inventory["complete"] = not inventory["readErrors"]
    except Exception as exc:
        inventory["readErrors"].append(repr(exc))
    candidates = [row for row in inventory["ports"]
                  if row["PortType"]["value"] == 5 and row["PortNo"] is not None]
    if any(row["PortNo"] == port_no for row in candidates):
        verdict = "port_lookup_inventory_mismatch"
        next_required = ("The inventory lists this port but the exact lookup failed. "
                         "Read device.config.graph.probe and diagnose the current "
                         "configuration binding before retrying; do not guess another port.")
    elif candidates:
        verdict = "requested_port_number_not_found"
        next_required = ("Select the intended PortNo from availableEthercatPorts "
                         "and explicitly retry. PortNo is not Index; this failure "
                         "does not mean EtherCAT is unsupported.")
    else:
        verdict = ("no_ethercat_port_in_current_inventory" if inventory["complete"]
                   else "port_inventory_inconclusive")
        next_required = ("Read device.config.graph.probe and verify the current CPU "
                         "identity and inventory readability. Do not infer a platform-wide "
                         "capability boundary from this failed port lookup.")
    return {"portNo": port_no, "portType": _text(port_type),
            "mutatedProject": False, "cpuPortInventory": inventory,
            "availableEthercatPorts": candidates, "capabilityVerdict": verdict,
            "nextRequired": next_required}


def vendor_ethercat_port_enable(req):
    """Enable one physical EtherCAT interface through the vendor mediator.

    InoProShop's Hardware Configuration page first changes the CPU port from
    DBT_NULL to DBT_ETHERCAT, registers the bus object, and only then permits
    EtherCAT slave insertion.  This operation exposes that prerequisite as a
    separate, auditable transaction.
    """
    operation = "vendor.ethercat.port.enable"
    project_path = _require_current_disposable_project(req, operation)
    if req.get("confirm") != "enable_ethercat_port":
        raise OperationError(
            "confirm must exactly equal enable_ethercat_port",
            "confirmation_required", {"projectPath": project_path})
    import System
    factory, binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", {"binding": binding})
    sync_project = factory.CreateConfigSyncProj()
    if sync_project is None:
        raise OperationError("configuration sync project is unavailable",
                             "configuration_sync_unavailable", {"binding": binding})
    sync_project.StartSyncToConfigrationDataObject()
    hardware = _get_member(sync_project, "HardwareConfigProject", "get_HardwareConfigProject")
    network = _get_member(sync_project, "NetworkConfigProject", "get_NetworkConfigProject")
    if hardware is None or network is None:
        try:
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject" and len(m.GetParameters()) == 2]
            if methods:
                args = System.Array[System.Object]([None, None])
                methods[0].Invoke(sync_project, args)
                hardware, network = args[0], args[1]
        except Exception:
            pass
    if hardware is None or network is None:
        raise OperationError("vendor configuration graph is unavailable",
                             "ethercat_configuration_graph_unavailable")
    cpu = hardware.GetCpuModule()
    port_no = int(req.get("portNo", 0))
    port_type_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.CommunicationPortType, InoDeviceConfiguration")
    bus_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
    if port_type_enum is None or bus_enum is None:
        raise OperationError("vendor bus enums are unavailable", "ethercat_bus_enum_unavailable")
    port_type = System.Enum.ToObject(port_type_enum, 5)  # CPT_ETHERCAT_NET_PORT
    ethercat_bus = System.Enum.ToObject(bus_enum, 3)  # DBT_ETHERCAT
    # ``IPortUseInfo.Index`` is the bus-local attach index, not a stable
    # global array index.  The UI resolves a physical port by its interface
    # type and number; use the same contract and only expose the resolved
    # index to the later slave-insert action.
    port = cpu.GetPortInfoByTypeAndNo(port_type, port_no)
    if port is None:
        raise OperationError("requested EtherCAT physical port was not found",
                             "ethercat_port_not_found",
                             _ethercat_missing_port_details(cpu, port_no, port_type))
    port_index = int(_get_member(port, "Index", "get_Index", -1))
    requested_index = req.get("portIndex")
    if requested_index is not None and int(requested_index) != port_index:
        raise OperationError(
            "portIndex does not match the vendor-resolved physical EtherCAT port",
            "ethercat_port_index_mismatch",
            {"requestedPortIndex": int(requested_index), "resolvedPortIndex": port_index,
             "portNo": port_no, "portType": _text(port_type)})
    before_bus = _get_member(_get_member(port, "CurrentBusDes", "get_CurrentBusDes"),
                             "BusType", "get_BusType")
    result = {
        "operation": operation, "projectPath": project_path,
        "mutatedProject": False, "portIndex": port_index, "portNo": port_no,
        "portType": _text(port_type), "beforeBusType": _text(before_bus),
        "mediatorBinding": None, "attempts": []}
    if _text(before_bus) == "DBT_ETHERCAT":
        result.update({"status": "already_enabled", "mutatedProject": False})
        return result
    supported = [_text(value) for value in list(cpu.GetSupportBusBuyInterface(port_type) or [])]
    result["supportedBusTypes"] = supported
    if "DBT_ETHERCAT" not in [value.upper() for value in supported]:
        raise OperationError("physical port does not support EtherCAT",
                             "ethercat_port_unsupported", result)
    parser_factory, parser_binding = _reflection_generic_create(
        "Inovance.InoPro.InoDeviceConfiguration.IDevTreeFileParserFactory, InoDeviceConfiguration",
        "{669014F5-D843-4E51-962E-1386A8828EBE}")
    if parser_factory is None:
        raise OperationError("vendor device-tree parser is unavailable",
                             "ethercat_device_parser_unavailable", result)
    parser = parser_factory.CreateDeviceTreeParser()
    current_bus = _get_member(port, "CurrentBusDes", "get_CurrentBusDes")
    target_bus = cpu.GetBusDescription(ethercat_bus)
    if current_bus is None or target_bus is None:
        raise OperationError("vendor port or EtherCAT bus description is unavailable",
                             "ethercat_bus_description_unavailable", result)
    prior_mode = _get_member(current_bus, "CurrentCommMode", "get_CurrentCommMode")
    new_bus = target_bus.ObjectClone()
    if new_bus is None:
        raise OperationError("vendor EtherCAT bus description could not be cloned",
                             "ethercat_bus_clone_failed", result)
    result["parserBinding"] = parser_binding
    result["priorCommunicationMode"] = _text(prior_mode)
    result["targetDefaultCommunicationMode"] = _text(
        _get_member(target_bus, "CurrentCommMode", "get_CurrentCommMode"))
    # This is the exact core of HardWareConfigForm.BusSelect.  The mediator
    # alone only affects the network view; creating the CPU bus DeviceObject
    # is what makes the port a real DBT_ETHERCAT configuration endpoint.
    try:
        setattr(port, "CurrentBusDes", new_bus)
        result["attempts"].append({"binding": "IPortUseInfo.CurrentBusDes=ObjectClone",
                                    "ok": True})
        cpu_ident = _get_member(cpu, "Identification", "get_Identification")
        bus_ident = _get_member(new_bus, "DevIdentification", "get_DevIdentification")
        bus_name = _text(_get_member(bus_ident, "DeviceName", "get_DeviceName"))
        needs_mode_rebind = (
            _json_safe(prior_mode) != _json_safe(_get_member(
                target_bus, "CurrentCommMode", "get_CurrentCommMode")) and
            _json_safe(prior_mode) != 4 and
            bool(_get_member(target_bus, "SupportMasterSlave", "get_SupportMasterSlave", False)))
        if needs_mode_rebind:
            setattr(new_bus, "CurrentCommMode", prior_mode)
            resolved_ident = parser.GetBusDeviceIdentification(prior_mode, cpu_ident, bus_name)
            if resolved_ident is not None:
                setattr(new_bus, "DevIdentification", resolved_ident)
            result["attempts"].append({"binding": "GetBusDeviceIdentification",
                                        "ok": resolved_ident is not None})
        port_actual_no = int(_get_member(port, "PortNo", "get_PortNo", port_no))
        cpu.AddBusDeviceOjbect(
            _get_member(new_bus, "DevIdentification", "get_DevIdentification"),
            port_actual_no, port_type)
        result["attempts"].append({"binding": "ICpuModule.AddBusDeviceOjbect",
                                    "ok": True, "portNo": port_actual_no})
    except Exception as exc:
        raise OperationError("native EtherCAT CPU bus registration failed: " + repr(exc),
                             "native_ethercat_bus_registration_failed", result)
    mediator_factory, mediator_binding = _reflection_generic_create(
        INOVANCE_PROJECT_MEDIATOR_INTERFACE, INOVANCE_PROJECT_MEDIATOR_FACTORY_GUID)
    if mediator_factory is None:
        raise OperationError("vendor project mediator is unavailable",
                             "ethercat_mediator_unavailable", result)
    mediator = mediator_factory.CreateProjMediator(hardware, network)
    result["mediatorBinding"] = mediator_binding
    result["mediatorRuntimeType"] = _text(mediator.GetType().FullName)
    try:
        show_network = bool(_get_member(new_bus, "ShowNetwork", "get_ShowNetwork", False))
        if show_network:
            mediator.AddSpeccialDevBus(port_no, port_type)
        result["attempts"].append({"binding": "IProjectMediator.AddSpeccialDevBus",
                                    "ok": True, "portNo": port_no,
                                    "called": show_network})
    except Exception as exc:
        raise OperationError("native EtherCAT port enable failed: " + repr(exc),
                             "native_ethercat_port_enable_failed", result)
    after_port = cpu.GetPortInfoByTypeAndNo(port_type, port_no)
    after_bus = _get_member(_get_member(after_port, "CurrentBusDes", "get_CurrentBusDes"),
                            "BusType", "get_BusType") if after_port is not None else None
    result["afterBusType"] = _text(after_bus)
    if _text(after_bus) != "DBT_ETHERCAT":
        raise OperationError("mediator returned but EtherCAT port did not change",
                             "ethercat_port_enable_unconfirmed", result)
    try:
        save_config = getattr(sync_project, "SaveConfigurationData")
        result["configurationSave"] = bool(save_config())
    except Exception as exc:
        result["configurationSave"] = False
        result["configurationSaveError"] = repr(exc)
    project.save()
    result["mutatedProject"] = True
    result["status"] = "enabled_same_process_persistence_unverified"
    result["nextRequired"] = "read vendor port and UI tree, then save/reopen and compile"
    return result


def vendor_ethercat_slave_add(req):
    """Append the first EtherCAT slave through InoProShop's native action.

    ``InsertEtherCATSlaveAction`` is specifically for inserting before an
    existing network slave.  The vendor's own synchronization code uses
    ``NwEthercatAddAction`` when rebuilding the first/append topology.  This
    operation deliberately implements that distinct, observed path.
    """
    operation = "vendor.ethercat.slave.add"
    project_path = _require_current_disposable_project(req, operation)
    if req.get("confirm") != "add_ethercat_slave":
        raise OperationError("confirm must exactly equal add_ethercat_slave",
                             "confirmation_required", {"projectPath": project_path})
    product_name = _text(req.get("productName") or req.get("module") or "").strip()
    if not product_name:
        raise OperationError("productName is required", "invalid_argument")
    # Resolve by either the installed display name or the vendor order number;
    # no caller-supplied type/id/version is accepted for this action.
    candidates = []
    for raw, item in _installed_device_entries():
        device_id = item.get("deviceId") or {}
        if int(device_id.get("type") or -1) != 65:
            continue
        if (_text(item.get("name")).lower() == product_name.lower() or
                _text(item.get("orderNumber")).lower() == product_name.lower()):
            candidates.append((raw, item))
    if len(candidates) != 1:
        raise OperationError(
            "EtherCAT slave must resolve to exactly one installed type=65 catalog record",
            "ethercat_slave_catalog_ambiguous" if candidates else "ethercat_slave_not_installed",
            {"productName": product_name,
             "candidates": [item for _raw, item in candidates[:20]]})
    selected = candidates[0][1]
    selected_id = selected.get("deviceId") or {}
    import System
    config_factory, config_binding = _reflection_generic_create(
        INOVANCE_CONFIG_FACTORY_INTERFACE, INOVANCE_CONFIG_FACTORY_GUID)
    if config_factory is None:
        raise OperationError("configuration sync factory is unavailable",
                             "configuration_factory_unavailable", {"binding": config_binding})
    sync_project = config_factory.CreateConfigSyncProj()
    sync_project.StartSyncToConfigrationDataObject()
    hardware = _get_member(sync_project, "HardwareConfigProject", "get_HardwareConfigProject")
    network = _get_member(sync_project, "NetworkConfigProject", "get_NetworkConfigProject")
    if hardware is None or network is None:
        try:
            methods = [m for m in sync_project.GetType().GetMethods()
                       if m.Name == "GetSyncToConfigrationDataObject" and len(m.GetParameters()) == 2]
            args = System.Array[System.Object]([None, None])
            methods[0].Invoke(sync_project, args)
            hardware, network = args[0], args[1]
        except Exception:
            pass
    if hardware is None or network is None:
        raise OperationError("vendor configuration graph is unavailable",
                             "ethercat_configuration_graph_unavailable")
    port_no = int(req.get("portNo", 0))
    port_type_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.CommunicationPortType, InoDeviceConfiguration")
    bus_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.DevBusType, InoDeviceConfiguration")
    category_enum = _reflection_type(
        "Inovance.InoPro.InoDeviceConfiguration.DeviceCategory, InoDeviceConfiguration")
    if port_type_enum is None or bus_enum is None or category_enum is None:
        raise OperationError("required EtherCAT enums are unavailable", "ethercat_bus_enum_unavailable")
    port_type = System.Enum.ToObject(port_type_enum, 5)
    ethercat_bus = System.Enum.ToObject(bus_enum, 3)
    category_name = _text(req.get("deviceCategory") or "CSDC_AM600").upper()
    category_value = 0 if category_name == "CSDC_AM600" else 1 if category_name == "CSDC_GENERIC" else None
    if category_value is None:
        raise OperationError("deviceCategory must be CSDC_AM600 or CSDC_GENERIC",
                             "invalid_argument")
    category = System.Enum.ToObject(category_enum, category_value)
    cpu = hardware.GetCpuModule()
    port = cpu.GetPortInfoByTypeAndNo(port_type, port_no)
    current_bus = _get_member(port, "CurrentBusDes", "get_CurrentBusDes") if port is not None else None
    current_bus_type = _get_member(current_bus, "BusType", "get_BusType") if current_bus is not None else None
    if _text(current_bus_type) != "DBT_ETHERCAT":
        raise OperationError("EtherCAT physical port is not enabled",
                             "ethercat_port_not_configured",
                             {"portNo": port_no, "actualBusType": _text(current_bus_type),
                              "requiredOperation": "vendor.ethercat.port.enable"})
    port_index = int(_get_member(port, "Index", "get_Index", -1))
    parser_factory, parser_binding = _reflection_generic_create(
        "Inovance.InoPro.InoDeviceConfiguration.IDevTreeFileParserFactory, InoDeviceConfiguration",
        "{669014F5-D843-4E51-962E-1386A8828EBE}")
    parser = parser_factory.CreateDeviceTreeParser() if parser_factory is not None else None
    # V1.10 exposes no public APEnvironment identity constructor.  The
    # device-tree parser does return the exact native config-identity object,
    # although AM600RTU_ECT is returned with empty fields.  Reuse that object
    # and fill it only from the uniquely resolved installed catalog record.
    identity = None
    identity_source = None
    if parser is not None:
        try:
            identity = parser.GetDeviceIdentification(product_name)
        except Exception:
            identity = None
    if identity is not None:
        try:
            identity.Type = int(selected_id.get("type"))
            identity.Id = _text(selected_id.get("id"))
            identity.Version = _text(selected_id.get("version"))
            identity.DeviceName = product_name
            identity_source = "parser_identity_filled_from_installed_catalog"
        except Exception as exc:
            raise OperationError("native EtherCAT identity object is not writable",
                                 "ethercat_identity_not_writable", {"error": repr(exc)})
    if identity is None:
        raise OperationError("device-tree parser did not return a native identity object",
                             "ethercat_identity_factory_unavailable")
    picture = _text(parser.GetDevicePictureName2(product_name)) if parser is not None else ""
    if not picture:
        picture = "EtherCat.bmp"
    action_factory, action_binding = _reflection_generic_create(
        INOVANCE_ETHERCAT_ADD_ACTION_FACTORY_INTERFACE,
        INOVANCE_ETHERCAT_ADD_ACTION_FACTORY_GUID)
    if action_factory is None:
        raise OperationError("native EtherCAT append action factory unavailable",
                             "ethercat_append_action_unavailable")
    result = {
        "operation": operation, "projectPath": project_path, "mutatedProject": False,
        "catalog": selected, "portNo": port_no, "portIndex": port_index,
        "factoryBinding": action_binding, "parserBinding": parser_binding,
        "category": _text(category), "identitySource": identity_source,
        "identity": {"type": int(selected_id.get("type")),
                      "id": _text(selected_id.get("id")),
                      "version": _text(selected_id.get("version")),
                      "deviceName": product_name},
        "attempts": []}
    try:
        action = action_factory.CreateEthercatAction(
            product_name, identity, picture, _text(selected.get("description")),
            port_index, port_no, hardware, network, category,
            bool(req.get("axisIsAdding", False)))
        result["actionRuntimeType"] = _text(action.GetType().FullName)
        execution_result = action.Execute()
        result["executeReturn"] = bool(execution_result)
        if not execution_result:
            raise RuntimeError("NwEthercatAddAction.Execute returned false")
    except Exception as exc:
        result["error"] = repr(exc)
        raise OperationError("native EtherCAT append action failed: " + repr(exc),
                             "native_ethercat_append_failed", result)
    try:
        result["configurationSave"] = bool(sync_project.SaveConfigurationData())
    except Exception as exc:
        result["configurationSave"] = False
        result["configurationSaveError"] = repr(exc)
    project.save()
    result["mutatedProject"] = True
    result["status"] = "added_same_process_persistence_unverified"
    result["nextRequired"] = (
        "verify UI tree and ObjectMgr identity immediately, then save/reopen and compile")
    return result


def _device_parent(req, root_only=False):
    target = req.get("parent") or req.get("target")
    if target is not None and _text(target).strip().lower() in (
            "", "/", "root", "project"):
        return project, ""
    if root_only:
        if target:
            raise OperationError(
                "device.add_cpu always inserts at the project root; use "
                "device.add for a child device",
                "invalid_argument",
            )
        return project, ""
    if target:
        value, path = find_project_object(target)
        return value, path
    return project, ""


def _device_add_binding_retryable(error):
    """Classify errors where trying another *binding* is still safe.

    A native vendor rejection (for example, the Chinese "cannot add/insert at
    this location" dialog text) is a topology verdict, not an overload issue;
    repeating ``parent.add`` with another identity shape only risks duplicate
    native mutations.  Alternate bindings are therefore attempted only for
    clear argument/overload resolution failures.
    """
    text = _text(error).lower()
    # TypeError is the normal IronPython signal for selecting the wrong CLR
    # overload.  ValueError is only retryable when its text clearly describes
    # argument conversion/arity; native topology code also raises ValueError
    # on some builds, and retrying that mutation can insert a duplicate node.
    if isinstance(error, TypeError):
        return True
    retry_markers = (
        "typeerror", "argumentexception", "argumentnullexception",
        "missingmethod", "missingmember", "method not found",
        "no applicable overload", "overload", "cannot convert",
        "wrong number of arguments", "takes ", "expected ",
    )
    return any(marker in text for marker in retry_markers)


def _add_device(req, root_only=False):
    _require_project()
    name = _text(req.get("name")).strip()
    if not name:
        raise OperationError("device instance name is required", "invalid_argument")
    parent, parent_path = _device_parent(req, root_only)
    existing = _find_created_child(parent, name)
    if existing is not None:
        raise OperationError(
            "a child with this device instance name already exists",
            "device_name_exists",
            {"name": name, "parent": parent_path, "existing": _object_summary(existing)},
        )
    # ``name`` is the destination instance for generic insertion.  Resolve the
    # repository row from deviceName/selectorName or the exact identity; this
    # avoids the historical ``explicit_identity_not_enumerated`` false
    # negative when both fields are supplied.
    raw, selected = _resolve_installed_device(req, instance_name=True)
    identity = selected.get("deviceId") or {}
    if identity.get("type") in (None, "") or not identity.get("id"):
        raise OperationError(
            "installed device has no usable ScriptEngine device identity",
            "invalid_device_identity",
            {"device": selected},
        )
    module = _text(req.get("module") or "")
    attempts = []
    selector = _device_selector_summary(req, instance_name=True)
    device_id = _get_member(raw, "device_id", "get_device_id") if raw is not None else None
    # The exact type/id/version overload is the canonical insertion call.  A
    # repository-ID overload is retained for older ScriptEngine builds, but
    # the manufactured-ID fallback is created lazily only after an explicit
    # overload failure; constructing it eagerly used to perform an unnecessary
    # native repository call on every successful insertion.
    calls = [
        ("type_id_version", lambda: parent.add(
            name, int(identity["type"]), identity["id"], identity["version"], module
        )),
    ]
    if device_id is not None:
        calls.append(("repository_device_id", lambda: parent.add(
            name, device_id, module
        )))
    factory_pending = True
    call_index = 0
    while call_index < len(calls):
        binding, call = calls[call_index]
        try:
            call()
            try:
                system.delay(50)
            except Exception:
                pass
            created = _find_created_child(parent, name)
            if created is None:
                raise OperationError(
                    "InoProShop accepted device.add but the new node was not "
                    "visible in the project tree",
                    "device_add_unconfirmed",
                    {"binding": binding, "name": name, "parent": parent_path,
                      "selector": selector, "device": selected,
                      "attempts": attempts},
                )
            return {
                "added": True,
                "binding": binding,
                "parent": parent_path,
                "selector": selector,
                "device": selected,
                "node": {
                    "name": _object_name(created),
                    "path": (parent_path + "/" if parent_path else "") + _object_name(created),
                    "deviceId": _project_device_identity(created),
                },
                "failedBindings": attempts,
            }
        except OperationError:
            raise
        except Exception as exc:
            attempts.append({"binding": binding, "error": repr(exc)})
            created = _find_created_child(parent, name)
            if created is not None:
                return {
                    "added": True,
                    "binding": binding + "_raised_after_insert",
                    "parent": parent_path,
                    "selector": selector,
                    "device": selected,
                    "node": {
                        "name": _object_name(created),
                        "path": (parent_path + "/" if parent_path else "") + _object_name(created),
                        "deviceId": _project_device_identity(created),
                    },
                    "failedBindings": attempts,
                }
            if not _device_add_binding_retryable(exc):
                attempts[-1]["retrySuppressed"] = True
                attempts[-1]["retryReason"] = "native_rejection_not_binding_error"
                break
            call_index += 1
            if call_index >= len(calls) and factory_pending:
                factory_pending = False
                try:
                    manufactured_id = _device_repository().create_device_identification(
                        int(identity["type"]), identity["id"], identity["version"]
                    )
                    calls.append(("factory_device_id", lambda manufactured_id=manufactured_id:
                                  parent.add(name, manufactured_id, module)))
                except Exception as factory_exc:
                    attempts.append({"binding": "factory_device_id",
                                     "error": repr(factory_exc),
                                     "retrySuppressed": True,
                                     "retryReason": "factory_identity_unavailable"})
            continue
        call_index += 1
    raise OperationError(
        "InoProShop rejected this device at the requested parent. Use "
        "device.tree to inspect compatible insertion points.",
        "device_add_rejected",
        {"name": name, "parent": parent_path, "selector": selector,
         "device": selected,
          "attempts": attempts},
    )


def _plug_device(req):
    """Plug one installed module into an existing device's next free slot.

    MEASURED 2026-09-19 (InoProShop V1.10.0.3): the vendor plugin refuses a
    generic ``device.add`` for a module identity on the device tree, while the
    ScriptEngine device object exposes the dedicated slot API.
    ``plug(name, type, id, version, module)`` fills the next free slot and
    ``insert(name, index, ...)`` places the same identity at an exact slot
    index.  Both are surfaced through this single operation because a second
    tool card would only dilute the device/configuration context.
    """
    operation = "device.plug"
    _require_project()
    name = _text(req.get("name")).strip()
    if not name:
        raise OperationError("module instance name is required",
                             "invalid_argument")
    parent, parent_path = _device_parent(req)
    existing = _find_created_child(parent, name)
    if existing is not None:
        raise OperationError(
            "a child with this module instance name already exists",
            "device_name_exists",
            {"name": name, "parent": parent_path,
             "existing": _object_summary(existing)},
        )
    raw, selected = _resolve_installed_device(req, instance_name=True)
    identity = selected.get("deviceId") or {}
    if identity.get("type") in (None, "") or not identity.get("id"):
        raise OperationError(
            "installed module has no usable ScriptEngine device identity",
            "invalid_device_identity",
            {"device": selected},
        )
    module = _text(req.get("module") or "")
    slot = req.get("slot")
    selector = _device_selector_summary(req, instance_name=True)
    device_id = _get_member(raw, "device_id", "get_device_id") if raw is not None else None
    calls = []
    if slot is not None:
        try:
            slot_index = int(slot)
        except Exception:
            raise OperationError("slot must be an integer slot index",
                                 "invalid_argument")
        calls.append((
            "insert_slot_type_id_version",
            lambda slot_index=slot_index: parent.insert(
                name, slot_index, int(identity["type"]), identity["id"],
                identity["version"], module),
        ))
    calls.append((
        "plug_type_id_version",
        lambda: parent.plug(
            name, int(identity["type"]), identity["id"],
            identity["version"], module),
    ))
    if device_id is not None:
        calls.append(("plug_repository_device_id",
                      lambda: parent.plug(name, device_id, module)))
    attempts = []
    call_index = 0
    while call_index < len(calls):
        binding, call = calls[call_index]
        try:
            call()
            try:
                system.delay(50)
            except Exception:
                pass
            created = _find_created_child(parent, name)
            if created is None:
                attempts.append({"binding": binding,
                                 "error": "the native call returned without "
                                          "publishing a project tree row",
                                 "retrySuppressed": True,
                                 "retryReason": "native_call_returned_without_row"})
                raise OperationError(
                    "InoProShop accepted device.plug but no module row "
                    "appeared in the project tree",
                    "device_plug_unconfirmed",
                    {"binding": binding, "name": name, "parent": parent_path,
                     "slot": slot, "selector": selector, "device": selected,
                     "attempts": attempts},
                )
            return {
                "plugged": True,
                "binding": binding,
                "parent": parent_path,
                "slot": slot,
                "selector": selector,
                "device": selected,
                "mutatedProject": True,
                "node": {
                    "name": _object_name(created),
                    "path": (parent_path + "/" if parent_path else "") + _object_name(created),
                    "deviceId": _project_device_identity(created),
                },
                "failedBindings": attempts,
                "status": "plugged_same_process_requires_save_reopen_compile_gate",
                "persistenceVerified": False,
                "nextRequired": (
                    "project.save, close, fresh-process reopen, device.tree exact "
                    "identity readback and build.compile 0/0 - a same-process "
                    "row is not persistence"
                ),
            }
        except OperationError:
            raise
        except Exception as exc:
            attempts.append({"binding": binding, "error": repr(exc)})
            created = _find_created_child(parent, name)
            if created is not None:
                return {
                    "plugged": True,
                    "binding": binding + "_raised_after_insert",
                    "parent": parent_path,
                    "slot": slot,
                    "selector": selector,
                    "device": selected,
                    "mutatedProject": True,
                    "node": {
                        "name": _object_name(created),
                        "path": (parent_path + "/" if parent_path else "") + _object_name(created),
                        "deviceId": _project_device_identity(created),
                    },
                    "failedBindings": attempts,
                    "status": "plugged_same_process_requires_save_reopen_compile_gate",
                    "persistenceVerified": False,
                    "nextRequired": (
                        "project.save, close, fresh-process reopen, device.tree exact "
                        "identity readback and build.compile 0/0 - a same-process "
                        "row is not persistence"
                    ),
                }
            if not _device_add_binding_retryable(exc):
                attempts[-1]["retrySuppressed"] = True
                attempts[-1]["retryReason"] = "native_rejection_not_binding_error"
                break
            call_index += 1
            continue
        call_index += 1
    raise OperationError(
        "InoProShop rejected this module at the requested slot. Read the "
        "parent's exact slot state first, or try the same identity with "
        "device.add when the parent is a bus master rather than a rack.",
        "device_plug_rejected",
        {"name": name, "parent": parent_path, "slot": slot,
         "selector": selector, "device": selected, "attempts": attempts},
    )


def _set_text_if_present(obj, declaration=None, implementation=None):
    result = {}
    if declaration is not None:
        result["declaration"] = _write_document(
            _get_member(obj, "textual_declaration", "get_textual_declaration"),
            declaration,
            "declaration",
        )
    if implementation is not None:
        result["implementation"] = _write_document(
            _get_member(obj, "textual_implementation", "get_textual_implementation"),
            implementation,
            "implementation",
        )
    return result


def _property_implementation_target(obj):
    children = []
    try:
        children = list(obj.get_children(False))
    except Exception:
        children = []
    getter = None
    candidates = []
    for child in children:
        child_name = (_object_name(child) or "").lower()
        has_impl = _get_member(
            child, "has_textual_implementation",
            "get_has_textual_implementation"
        )
        candidates.append({
            "name": _object_name(child),
            "hasTextualImplementation": bool(has_impl)
            if has_impl is not None else None,
        })
        if child_name == "get" or child_name.endswith(".get"):
            getter = child
        elif getter is None and has_impl:
            getter = child
    if getter is None and len(children) == 1:
        getter = children[0]
    if getter is None:
        raise RuntimeError(
            "property getter child object not found: %s" % candidates)
    return getter, candidates


def _set_property_text(obj, declaration=None, implementation=None):
    """Write property text: declaration on the property, body on its getter.

    A CODESYS property keeps the declaration on itself while the executable
    text lives on the getter/setter child objects, so the plain textual
    members are unavailable on the property node itself.
    """
    result = {}
    if declaration is not None:
        result["declaration"] = _write_document(
            _get_member(obj, "textual_declaration", "get_textual_declaration"),
            declaration,
            "declaration",
        )
    if implementation is not None:
        getter, candidates = _property_implementation_target(obj)
        result["implementation"] = _write_document(
            _get_member(getter, "textual_implementation", "get_textual_implementation"),
            implementation,
            "property getter implementation",
        )
        result["getterObject"] = _object_name(getter)
        result["children"] = candidates
    return result


def _child_requested_text_readback(obj, declaration=None,
                                   implementation=None, property_text=False):
    fields = {}
    if declaration is not None:
        fields["declaration"] = _document_readback(
            _get_member(obj, "textual_declaration", "get_textual_declaration"),
            declaration,
            "declaration",
        )
    if implementation is not None:
        implementation_obj = obj
        if property_text:
            implementation_obj, candidates = _property_implementation_target(obj)
            fields["getterObject"] = _object_name(implementation_obj)
            fields["propertyChildren"] = candidates
        fields["implementation"] = _document_readback(
            _get_member(
                implementation_obj, "textual_implementation",
                "get_textual_implementation"
            ),
            implementation,
            "property getter implementation" if property_text
            else "implementation",
        )
    return fields


def _rollback_new_child(parent, name, created):
    """Remove only the object inserted by a failed child-create transaction."""
    created_guid = _object_guid(created) if created is not None else ""
    matches = [child for child in _children(parent)
               if _object_name(child).lower() == name.lower()]
    targets = []
    if created_guid:
        targets = [child for child in matches
                   if _object_guid(child).lower() == created_guid.lower()]
    if not targets and len(matches) == 1:
        targets = matches
    if not targets and created is not None and not matches:
        targets = [created]
    attempts = []
    seen = set()
    for target in targets:
        key = _object_guid(target) or _text(id(target))
        if key in seen:
            continue
        seen.add(key)
        try:
            target.remove()
            attempts.append({"guid": _object_guid(target), "removed": True})
        except Exception as exc:
            attempts.append({
                "guid": _object_guid(target), "removed": False,
                "error": repr(exc),
            })
    remaining = [_object_summary(child) for child in _children(parent)
                 if _object_name(child).lower() == name.lower()]
    return {
        "attempted": bool(targets),
        "complete": not remaining,
        "createdGuid": created_guid or None,
        "attempts": attempts,
        "remaining": remaining,
    }


def _validate_child_return_type(value, required):
    if value is None:
        if required:
            raise OperationError(
                "returnType is required", "invalid_argument",
                {"path": "returnType", "mutatedProject": False},
            )
        return None
    result = _text(value)
    if (not result or result != result.strip() or len(result) > 256 or
            "\r" in result or "\n" in result or ";" in result):
        raise OperationError(
            "returnType must be one non-empty IEC type expression",
            "invalid_argument",
            {
                "path": "returnType",
                "expected": "one IEC type expression without line breaks or ';'",
                "actual": result,
                "mutatedProject": False,
            },
        )
    return result


def _validate_child_declaration_header(operation, name, return_type,
                                       declaration):
    if declaration is None:
        return
    keyword = "METHOD" if operation == "pou.create_method" else "PROPERTY"
    expected = keyword + " " + name
    if return_type:
        expected += " : " + return_type
    actual = _canonical_source_text(declaration).strip().split("\n", 1)[0].strip()
    if actual.upper() != expected.upper():
        raise OperationError(
            keyword.lower() +
            " declaration header must match name and returnType",
            "invalid_argument",
            {
                "path": "declaration",
                "expected": expected,
                "actual": actual,
                "example": expected,
                "mutatedProject": False,
            },
        )


def _pou_child_create(req, operation):
    """Create one POU child with preflight, identity and text readback gates."""
    _require_project()
    parent_target = _text(req.get("parent"))
    raw_name = _text(req.get("name"))
    if not parent_target or not raw_name:
        raise OperationError(
            "parent and name are required", "invalid_argument",
            {"mutatedProject": False},
        )
    if (raw_name != raw_name.strip() or
            not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", raw_name)):
        raise OperationError(
            "name must be an IEC identifier", "invalid_argument",
            {
                "path": "name",
                "expected": "IEC identifier [A-Za-z_][A-Za-z0-9_]*",
                "actual": raw_name,
                "mutatedProject": False,
            },
        )
    name = raw_name
    if operation in ("pou.create_action", "pou.create_transition") and \
            "declaration" in req:
        raise OperationError(
            operation +
            " does not have a declaration document; omit declaration",
            "invalid_argument",
            {
                "path": "declaration",
                "expected": "field omitted",
                "actual": req.get("declaration"),
                "mutatedProject": False,
            },
        )

    return_type = _validate_child_return_type(
        req.get("returnType") if req.get("returnType") is not None
        else req.get("return_type"),
        operation == "pou.create_property",
    )
    declaration = req.get("declaration") if "declaration" in req else None
    implementation = (req.get("implementation")
                      if "implementation" in req else None)
    if declaration is not None:
        declaration = _validate_source_text(declaration, "declaration")
    if implementation is not None:
        implementation = _validate_source_text(
            implementation, "implementation")
    if operation in ("pou.create_method", "pou.create_property"):
        _validate_child_declaration_header(
            operation, name, return_type, declaration)

    parent_obj, parent_path = find_project_object(parent_target)
    _require_child_destination_absent(
        parent_obj, parent_path, name, operation)
    factory_names = {
        "pou.create_method": "create_method",
        "pou.create_property": "create_property",
        "pou.create_action": "create_action",
        "pou.create_transition": "create_transition",
    }
    factory_name = factory_names.get(operation)
    factory = getattr(parent_obj, factory_name, None) if factory_name else None
    if not _is_callable(factory):
        raise OperationError(
            "parent does not support " + operation,
            "unsupported_child_parent",
            {
                "operation": operation,
                "parent": parent_path,
                "parentType": _object_type(parent_obj),
                "requiredBinding": factory_name,
                "mutatedProject": False,
            },
        )
    if operation == "pou.create_method":
        variants = [(name, return_type, None), (name, return_type), (name,)]
    elif operation == "pou.create_property":
        variants = [(name, return_type, None), (name, return_type)]
    else:
        variants = [(name, None), (name,)]

    member = None
    creation_binding = None
    attempts = []
    for arguments in variants:
        binding = factory_name + "(" + ",".join(
            ["None" if item is None else "value" for item in arguments]
        ) + ")"
        try:
            member = factory(*arguments)
            if member is None:
                member = _find_created_child(parent_obj, name)
            if member is not None:
                creation_binding = binding
                attempts.append({"binding": binding, "ok": True})
                break
            attempts.append({
                "binding": binding, "ok": False,
                "error": "native factory returned no object or tree child",
            })
        except Exception as exc:
            inserted = _find_created_child(parent_obj, name)
            if inserted is not None:
                member = inserted
                creation_binding = binding + "_raised_after_insert"
                attempts.append({
                    "binding": binding, "ok": True,
                    "raisedAfterInsert": True, "error": repr(exc),
                })
                break
            attempts.append({
                "binding": binding, "ok": False, "error": repr(exc),
            })
    if member is None:
        raise OperationError(
            "all native child creation bindings failed",
            "child_creation_failed",
            {
                "operation": operation,
                "parent": parent_path,
                "name": name,
                "attempts": attempts,
                "mutatedProject": False,
            },
        )

    try:
        rebound, _initial = _created_child_model_readback(
            parent_obj, parent_path, name, member, operation)
        if operation == "pou.create_property":
            text_receipt = _set_property_text(
                rebound, declaration, implementation)
        else:
            text_receipt = _set_text_if_present(
                rebound, declaration, implementation)
        rebound, result = _created_child_model_readback(
            parent_obj, parent_path, name, member, operation)
        requested_text = _child_requested_text_readback(
            rebound, declaration, implementation,
            operation == "pou.create_property",
        )
    except OperationError as exc:
        rollback = _rollback_new_child(parent_obj, name, member)
        exc.data["rollback"] = rollback
        exc.data["mutatedProject"] = not rollback.get("complete")
        raise
    except Exception as exc:
        rollback = _rollback_new_child(parent_obj, name, member)
        raise OperationError(
            "created child failed post-create validation",
            "child_post_create_validation_failed",
            {
                "operation": operation,
                "parent": parent_path,
                "name": name,
                "error": repr(exc),
                "rollback": rollback,
                "mutatedProject": not rollback.get("complete"),
            },
        )

    result.update({
        "creationBinding": creation_binding,
        "factoryAttempts": attempts,
        "text": text_receipt,
        "requestedTextReadback": True,
        "requestedTextFields": sorted([
            field for field in ("declaration", "implementation")
            if field in requested_text
        ]),
        "readback": {
            "object": _object_summary(rebound, result.get("path")),
            "requestedText": requested_text,
        },
        "mutatedProject": True,
    })
    return result


def _dut_type(kind):
    normalized = (kind or "structure").strip().lower()
    mapping = {
        "structure": "Structure",
        "struct": "Structure",
        "enumeration": "Enumeration",
        "enum": "Enumeration",
        "union": "Union",
        "alias": "Alias",
    }
    member = mapping.get(normalized)
    if member is None or not hasattr(DutType, member):
        raise RuntimeError("unsupported DUT kind: " + normalized)
    return getattr(DutType, member)


def _build_action(action):
    _require_project()
    app, application_binding = _resolve_active_application()
    if app is None:
        raise OperationError("no buildable application is available",
                             "application_unavailable", application_binding)
    if action == "clean":
        app.clean()
        return {"action": action, "cleaned": True,
                "applicationBinding": application_binding}
    if action == "clean_all":
        project.clean_all()
        return {"action": action, "cleaned": True,
                "applicationBinding": application_binding}
    method = getattr(app, action, None)
    if method is None:
        raise RuntimeError("active application does not support: " + action)
    cleared = clear_messages(exclude_categories=(PRECOMPILE_CATEGORY,))
    method()
    summary = _wait_for_stable_diagnostics()
    summary["action"] = action
    summary["clearMessages"] = cleared
    summary["applicationBinding"] = application_binding
    return summary


def _find_marked_objects(marker, required_members=None):
    required_members = required_members or []
    found = []

    def visit(parent, prefix):
        for child in _children(parent):
            name = _object_name(child) or "<unnamed>"
            path = "/".join(prefix + [name])
            marked = bool(_get_member(child, marker, "get_" + marker, False))
            members_match = (bool(required_members) and
                             all(hasattr(child, member) for member in required_members))
            if marked or members_match:
                found.append((path, child))
            visit(child, prefix + [name])

    visit(project, [])
    return found


def _watchdog_summary(task):
    watchdog = _get_member(task, "watchdog", "get_watchdog")
    if watchdog is None:
        return None
    result = {}
    for name in ("enabled", "time", "time_unit", "sensitivity"):
        value = _get_member(watchdog, name, "get_" + name)
        if value is not None:
            result[name] = _json_safe(value)
    return result


def _task_interval_unit(value):
    """Return a stable ASCII task-unit token across IronPython code pages."""
    text = _text(value)
    lowered = text.lower()
    if lowered in ("\\xb5s", "\\u00b5s", "µs", "us"):
        return "us"
    return _json_safe(value)


def _task_validate_core_binding(req, task):
    """Reject a malformed new field before any other task setting is written."""
    if "core_binding" not in req:
        return
    value = req.get("core_binding")
    if (isinstance(value, bool) or not isinstance(value, _INTEGER_TYPES)
            or value < -2147483648 or value > 2147483647):
        raise OperationError(
            "core_binding must be a native signed 32-bit integer, not a string or boolean",
            "invalid_argument",
            {"field": "core_binding", "requested": value,
             "expectedType": "integer", "mutatedProject": False},
        )
    if _get_member(task, "core_binding", "get_core_binding") is None:
        raise OperationError(
            "this task does not expose native core_binding; keep the reported task settings and inspect the target's task-group configuration",
            "task_field_not_exposed",
            {"field": "core_binding", "requested": value,
             "mutatedProject": False},
        )


def _task_summary(path, task):
    result = _object_summary(task, path)
    for name in (
        "kind_of_task", "priority", "interval", "interval_unit", "event",
        "external_event", "core_binding", "parent_synchron_task",
    ):
        value = _get_member(task, name, "get_" + name)
        if value is not None:
            result[name] = (_task_interval_unit(value)
                            if name == "interval_unit" else _json_safe(value))
    watchdog = _watchdog_summary(task)
    if watchdog is not None:
        result["watchdog"] = watchdog
    calls = []
    pous = _get_member(task, "pous", "get_pous")
    if pous is not None:
        try:
            # Iterating ScriptPouObjectCollection yields only the POU name;
            # indexed access yields the native (name, comment) record.  The
            # old iterator path therefore reported every persisted comment as
            # empty after a reopen even though task.pou.set and the project
            # file retained it.  Reuse the indexed snapshot contract used by
            # the mutation gate so task.list exposes honest persistence.
            for entry in _task_pou_snapshot(pous):
                calls.append({
                    "name": entry.get("name"),
                    "value": entry.get("name"),
                    "comment": entry.get("comment"),
                    "runtimeType": "",
                    "readBinding": "ScriptPouObjectCollection[index]",
                })
        except Exception:
            calls = []
    child_calls = []
    for child in _children(task):
        references = {}
        for member in (
            "pou_name", "program_name", "called_pou", "pou", "value",
            "key", "item1",
        ):
            value = _get_member(child, member, "get_" + member)
            if value is not None and _text(value):
                references[member] = _object_name(value) or _text(value)
        child_calls.append({
            "name": _object_name(child),
            "guid": _object_guid(child),
            "type": _object_type(child),
            "references": references,
        })
    result["pouCalls"] = calls
    result["childCalls"] = child_calls
    return result


def _find_tasks():
    return _find_marked_objects("is_task", ["interval", "priority", "watchdog"])


def _find_task(name):
    tasks = _find_tasks()
    matches = [(path, task) for path, task in tasks
               if _object_name(task) == name or path.lower() == _text(name).lower()]
    if len(matches) != 1:
        if not matches:
            raise RuntimeError("task not found: " + _text(name))
        raise RuntimeError("ambiguous task: " + _text(name))
    return matches[0]


def _task_pou_entry(value):
    """Normalize one ScriptPouObjectCollection entry to name/comment text."""
    if isinstance(value, (list, tuple)):
        name = value[0] if value else ""
        comment = value[1] if len(value) > 1 else ""
        return {"name": _text(name), "comment": _text(comment)}
    if isinstance(value, _STRING_TYPES):
        return {"name": _text(value), "comment": ""}

    name = None
    for member in (
        "pou_name", "program_name", "called_pou", "pou", "value",
        "key", "item1", "Item1", "name", "Name",
    ):
        candidate = _get_member(value, member, "get_" + member)
        if candidate is not None and _text(candidate):
            name = _object_name(candidate) or _text(candidate)
            break
    comment = None
    for member in ("comment", "Comment", "item2", "Item2"):
        candidate = _get_member(value, member, "get_" + member)
        if candidate is not None:
            comment = candidate
            break
    if name is None:
        name = _object_name(value) or _text(value)
    return {"name": _text(name), "comment": _text(comment)}


def _task_pou_snapshot(collection):
    """Read task entries through the indexed API so comments are retained."""
    try:
        count = len(collection)
    except Exception:
        values = list(collection)
    else:
        values = []
        try:
            for index in range(count):
                values.append(collection[index])
        except Exception:
            values = list(collection)
    entries = [_task_pou_entry(value) for value in values]
    for index, entry in enumerate(entries):
        if not entry["name"]:
            raise RuntimeError(
                "task POU entry %d has no readable name: %r" % (index, values[index])
            )
    return entries


def _task_pou_apply_entries(collection, requested_entries, task=None):
    """Resize and replace one native task POU collection with exact readback."""
    requested_entries = [
        {"name": _text(entry.get("name")),
         "comment": _text(entry.get("comment"))}
        for entry in requested_entries
    ]
    def native_collection():
        # Some vendor builds return a new collection view after tree edits.
        return getattr(task, "pous", collection) if task is not None else collection

    def snapshot():
        return _task_pou_snapshot(native_collection())

    current = snapshot()
    overlap = min(len(current), len(requested_entries))
    needs_replace = any(
        current[index] != requested_entries[index]
        for index in range(overlap)
    )
    required = []
    if needs_replace:
        required.append("replace")
    if len(requested_entries) > len(current):
        required.append("add")
    if len(requested_entries) < len(current):
        required.append("remove")
    methods = {}
    for name in required:
        method = getattr(collection, name, None)
        if not _is_callable(method) and not (name == "remove" and task is not None):
            raise RuntimeError(
                "ScriptPouObjectCollection.%s is unavailable" % name
            )
        methods[name] = method

    trace = []
    # Shrink before replacement: replacing first can create duplicate names,
    # making the vendor's name-based remove delete a retained call instead.
    for index in range(len(current) - 1, len(requested_entries) - 1, -1):
        before_remove = snapshot()
        expected = before_remove[:index] + before_remove[index + 1:]
        removed = False
        binding = None
        attempts = [index]
        name = before_remove[index]["name"]
        # Never use an ambiguous name to remove a particular occurrence.
        if sum(entry["name"] == name for entry in before_remove) == 1:
            attempts.append(name)
        attempts.append(native_collection()[index])
        for candidate in attempts:
            method = getattr(native_collection(), "remove", None)
            if not _is_callable(method):
                break
            try:
                method(candidate)
            except Exception:
                pass
            observed = snapshot()
            if observed == expected:
                removed = True
                binding = "collection.remove"
                break
            if observed != before_remove:
                raise RuntimeError("task POU removal changed an unexpected entry: %r" % observed)
            # A non-throwing no-op is not success; try the next native binding.
        if not removed and task is not None:
            # Real InoProShop V1.10 remove(name) can silently do nothing. The
            # exact typed child is the task CALL, never the PROGRAM definition.
            candidates = [child for child in _children(task)
                          if _text(_object_type(child)).lower() ==
                          "413e2a7d-adb1-4d2c-be29-6ae6e4fab820"
                          and _object_name(child) == name]
            if len(candidates) == 1 and sum(entry["name"] == name for entry in before_remove) == 1:
                method = getattr(candidates[0], "remove", None)
                if _is_callable(method):
                    method()
                    observed = snapshot()
                    if observed != expected:
                        raise RuntimeError("task call child removal readback mismatch: %r" % observed)
                    removed = True
                    binding = "task_call_child.remove"
        if not removed:
            raise RuntimeError(
                "native task POU removal had no verified effect for index %d" % index
            )
        trace.append({"method": "remove", "index": index,
                      "name": name, "binding": binding})
    for index in range(overlap):
        entry = requested_entries[index]
        if current[index] == entry:
            continue
        native_collection().replace(index, entry["name"], entry["comment"])
        trace.append({"method": "replace", "index": index,
                      "name": entry["name"]})
    for index in range(len(current), len(requested_entries)):
        entry = requested_entries[index]
        native_collection().add(entry["name"], entry["comment"])
        trace.append({"method": "add", "index": index,
                      "name": entry["name"]})

    after = snapshot()
    if after != requested_entries:
        raise RuntimeError(
            "task POU readback mismatch: expected %r, got %r" %
            (requested_entries, after)
        )
    return trace, after


def _task_pou_name_key(value):
    """Return a stable case-insensitive key for one task-call spelling.

    InoProShop has returned both bare names (``PLC_PRG``) and suffix paths
    (``Application/PLC_PRG``) for the same task call over its API versions.
    Keep normalisation deliberately small and ASCII/Unicode safe so this
    helper can run in the resident IronPython 2.7 interpreter.
    """
    value = _text(value).strip().replace("\\", "/")
    while "//" in value:
        value = value.replace("//", "/")
    return value.strip("/").lower()


def _task_pou_names_match(left, right):
    """Match task-call names without conflating two qualified POUs.

    A bare name is allowed to match a qualified suffix because the native
    ScriptPouObjectCollection commonly stores only the POU name.  Two
    different qualified paths (``FolderA/P`` vs ``FolderB/P``) are kept
    distinct; this avoids reporting a false C0457 conflict when projects have
    duplicate POU names in separate namespaces.
    """
    left_key = _task_pou_name_key(left)
    right_key = _task_pou_name_key(right)
    if not left_key or not right_key:
        return False
    if left_key == right_key:
        return True
    left_has_path = "/" in left_key
    right_has_path = "/" in right_key
    if left_has_path and right_has_path:
        return False
    return left_key.rsplit("/", 1)[-1] == right_key.rsplit("/", 1)[-1]


def _task_call_reference_names(value):
    """Read all useful POU spellings from one native task-call object."""
    names = []
    direct = _object_name(value)
    if not direct and isinstance(value, _STRING_TYPES):
        direct = _text(value)
    if direct:
        names.append(_text(direct))
    for member in (
        "pou_name", "program_name", "called_pou", "pou", "value",
        "key", "item1", "Item1",
    ):
        candidate = _get_member(value, member, "get_" + member)
        if candidate is None or not _text(candidate):
            continue
        name = _object_name(candidate) or _text(candidate)
        if name and name not in names:
            names.append(_text(name))
    return names


def _task_call_is_program(name):
    """Classify a task-call spelling as a textual PROGRAM when resolvable.

    Task configurations also contain vendor-generated calls such as
    ``EtherCAT.EtherCAT_Task``.  Those are not IEC PROGRAM POUs and can be
    legitimately present on multiple tasks, so they must not be labelled as a
    C0457 duplicate.  If the host cannot resolve a name, stay conservative
    (``True``) for mutation preflight; a false negative is safer than writing
    a potentially conflicting call.
    """
    resolver = globals().get("find_textual_object")
    is_callable = globals().get("_is_callable", callable)
    if resolver is None or not is_callable(resolver):
        return True
    candidates = [_text(name)]
    normalized = _task_pou_name_key(name)
    if "/" in normalized:
        candidates.append(_text(name).replace("\\", "/").rstrip("/").rsplit("/", 1)[-1])
    saw_object = False
    for candidate in candidates:
        if not candidate:
            continue
        try:
            value = resolver(candidate)
        except Exception:
            # Ambiguous/temporarily unavailable textual lookup is not proof
            # that the call is external; retain the conservative classification.
            return True
        if value is None:
            continue
        saw_object = True
        reader = globals().get("read_st")
        if reader is None or not is_callable(reader):
            return True
        try:
            declaration = reader(value).get("declaration", "")
        except Exception:
            return True
        return _text(declaration).lstrip().upper().startswith("PROGRAM ")
    return False if not saw_object else True


def _task_call_records(path, task):
    """Return read-only evidence for every POU call attached to one task.

    The vendor API exposes calls through both ``task.pous`` and child call
    objects.  Older builds expose only one of those views, while newer builds
    expose both.  We intentionally retain the source/index metadata and let
    the audit layer merge duplicate observations instead of trusting either
    view in isolation.
    """
    records = []
    collection = _get_member(task, "pous", "get_pous")
    if collection is not None:
        try:
            entries = _task_pou_snapshot(collection)
        except Exception:
            # A partially materialised collection should not make a safety
            # preflight mutate the project.  Fall back to the best-effort
            # enumerable view and retain only names that are readable.
            try:
                entries = [_task_pou_entry(item) for item in list(collection)]
            except Exception:
                entries = []
        for index, entry in enumerate(entries):
            name = _text(entry.get("name")) if isinstance(entry, dict) else ""
            if not name:
                continue
            records.append({
                "name": name,
                "key": _task_pou_name_key(name),
                "isProgram": _task_call_is_program(name),
                "source": "pous",
                "index": index,
                "comment": (_text(entry.get("comment"))
                            if isinstance(entry, dict) else ""),
            })

    for index, child in enumerate(_children(task)):
        references = []
        for member in (
            "pou_name", "program_name", "called_pou", "pou", "value",
            "key", "item1",
        ):
            candidate = _get_member(child, member, "get_" + member)
            if candidate is None or not _text(candidate):
                continue
            name = _object_name(candidate) or _text(candidate)
            if name and name not in references:
                references.append(_text(name))
        # A child with explicit references should not contribute its wrapper
        # name (which can be an opaque generated identifier).  If no
        # reference is exposed, its own name is the only useful evidence.
        names = references or _task_call_reference_names(child)
        for name in names:
            if not name:
                continue
            record = {
                "name": _text(name),
                "key": _task_pou_name_key(name),
                "isProgram": _task_call_is_program(name),
                "source": "child",
                "index": index,
            }
            try:
                record["guid"] = _object_guid(child)
            except Exception:
                pass
            try:
                record["type"] = _object_type(child)
            except Exception:
                pass
            records.append(record)
    return records


def _task_call_audit(target=None, target_task_path=None, target_task=None):
    """Build cross-task assignment evidence from the native task tree.

    This is read-only and intentionally independent from ``program.audit`` so
    the mutation preflight can use exactly the same identity rules.  The
    returned ``assignments`` list contains at most one row per POU/task pair;
    ``duplicateTaskCalls`` groups rows observed on more than one task.
    """
    target_key = _task_pou_name_key(target)
    target_path_key = _task_pou_name_key(target_task_path)
    target_guid = ""
    target_name_key = ""
    if target_task is not None:
        try:
            target_guid = _object_guid(target_task)
        except Exception:
            target_guid = ""
        try:
            target_name_key = _task_pou_name_key(_object_name(target_task))
        except Exception:
            target_name_key = ""

    task_rows = []
    assignments = []
    for path, task in _find_tasks():
        calls = _task_call_records(path, task)
        grouped = {}
        for call in calls:
            key = call.get("key") or _task_pou_name_key(call.get("name"))
            if not key:
                continue
            row = grouped.get(key)
            if row is None:
                row = {
                    "name": call.get("name"),
                    "key": key,
                    "isProgram": call.get("isProgram", True),
                    "sources": [],
                }
                grouped[key] = row
            elif call.get("isProgram") is True:
                # An unresolved view is conservative; preserve a positive
                # classification if either native view resolves the call.
                row["isProgram"] = True
            source = {
                "kind": call.get("source"),
                "index": call.get("index"),
            }
            for field in ("guid", "type", "comment"):
                if call.get(field):
                    source[field] = call.get(field)
            if source not in row["sources"]:
                row["sources"].append(source)
        task_name = _object_name(task)
        task_guid = _object_guid(task)
        task_row = {
            "name": task_name,
            "path": path,
            "guid": task_guid,
            "calls": sorted(grouped.values(), key=lambda item: item.get("key", "")),
        }
        task_rows.append(task_row)
        for call in task_row["calls"]:
            assignments.append({
                "pou": call.get("name"),
                "pouKey": call.get("key"),
                "isProgram": call.get("isProgram", True),
                "task": task_name,
                "taskPath": path,
                "taskGuid": task_guid,
                "sources": call.get("sources", []),
            })

    by_pou = {}
    for assignment in assignments:
        key = assignment.get("pouKey")
        if not key:
            continue
        by_pou.setdefault(key, []).append(assignment)
    duplicate_rows = []
    for key, rows in by_pou.items():
        task_keys = set()
        for row in rows:
            task_key = (_task_pou_name_key(row.get("taskPath")) or
                        _task_pou_name_key(row.get("task")) or
                        _task_pou_name_key(row.get("taskGuid")))
            if task_key:
                task_keys.add(task_key)
        # Only textual PROGRAM calls are subject to the native cross-task
        # restriction.  Vendor-generated task calls can be shared safely.
        if (len(task_keys) > 1 and
                any(row.get("isProgram", True) for row in rows)):
            duplicate_rows.append({
                "pou": rows[0].get("pou"),
                "pouKey": key,
                "taskCount": len(task_keys),
                "tasks": rows,
                "nativeErrorCode": "C0457",
            })
    duplicate_rows.sort(key=lambda item: item.get("pouKey", ""))

    target_assignments = []
    if target_key:
        for assignment in assignments:
            if _task_pou_names_match(target, assignment.get("pou")):
                target_assignments.append(assignment)

    def is_target_assignment(row):
        path_key = _task_pou_name_key(row.get("taskPath"))
        if target_path_key:
            return path_key == target_path_key
        if target_guid and _text(row.get("taskGuid")) == target_guid:
            return True
        if target_task is not None and target_name_key:
            return _task_pou_name_key(row.get("task")) == target_name_key
        return False

    target_other = [
        row for row in target_assignments
        if not is_target_assignment(row)
    ]

    # Keep a project-wide owner view for the selected POU.  ``targetOther``
    # answers a different question (which rows are outside the selected
    # task), and therefore cannot be used as proof of a duplicate when the
    # caller did not select a task.  In particular, a single assignment to a
    # non-MainTask would otherwise look like a cross-task conflict merely
    # because ``program.audit`` historically defaulted to MainTask.
    owner_rows = {}
    owner_unknown = []
    for row in target_assignments:
        if row.get("isProgram", True) is False:
            continue
        owner_key = (_task_pou_name_key(row.get("taskPath")) or
                     _task_pou_name_key(row.get("taskGuid")) or
                     _task_pou_name_key(row.get("task")))
        if not owner_key:
            owner_unknown.append(row)
            continue
        if owner_key not in owner_rows:
            owner_rows[owner_key] = row
    target_owner_rows = sorted(
        owner_rows.values(),
        key=lambda item: (_task_pou_name_key(item.get("taskPath")) or
                          _task_pou_name_key(item.get("task")) or
                          _task_pou_name_key(item.get("taskGuid"))),
    )

    return {
        "tasks": task_rows,
        "assignments": assignments,
        "duplicateTaskCalls": duplicate_rows,
        "targetAssignments": target_assignments,
        "targetOtherTaskAssignments": target_other,
        "targetOwnerTasks": target_owner_rows,
        "targetOwnerTaskCount": len(target_owner_rows),
        "targetOwnerAssignmentsUnknown": owner_unknown,
        "targetDuplicateAcrossTasks": len(target_owner_rows) > 1,
    }


def _task_pou_cross_task_conflicts(task_path, task, requested_names):
    """Return requested PROGRAM calls already owned by another task."""
    evidence = _task_call_audit(target_task_path=task_path, target_task=task)
    conflicts = []
    for requested in requested_names:
        matches = []
        for assignment in evidence.get("assignments", []):
            if assignment.get("isProgram") is False:
                continue
            if not _task_pou_names_match(requested, assignment.get("pou")):
                continue
            same_task = (
                _task_pou_name_key(assignment.get("taskPath")) ==
                _task_pou_name_key(task_path)
            )
            if not same_task:
                matches.append(assignment)
        # A task can expose the same call through both ``pous`` and child
        # views.  Collapse those observations to one conflicting task row.
        unique = {}
        for assignment in matches:
            key = (_task_pou_name_key(assignment.get("taskPath")) or
                   _task_pou_name_key(assignment.get("task")) or
                   _task_pou_name_key(assignment.get("taskGuid")))
            unique[key] = assignment
        matches = sorted(unique.values(),
                         key=lambda item: _task_pou_name_key(item.get("taskPath")))
        if matches:
            conflicts.append({
                "pou": _text(requested),
                "normalizedPou": _task_pou_name_key(requested),
                "conflictingTasks": matches,
                "nativeErrorCode": "C0457",
            })
    return conflicts


def task_pou_set(req):
    """Replace one task's executed PROGRAM list with exact readback."""
    _require_project()
    task_name = _text(req.get("task") or req.get("name") or "MainTask").strip()
    requested = req.get("pous")
    if not isinstance(requested, list) or not requested:
        raise OperationError(
            "task.pou.set requires a non-empty pous array",
            "invalid_argument",
            {"path": "pous", "expected": ["PLC_PRG"], "actual": requested},
        )
    supplied_entries = req.get("entries")
    if supplied_entries is not None:
        if (not isinstance(supplied_entries, list) or
                len(supplied_entries) != len(requested)):
            raise OperationError(
                "task.pou.set entries must have one record per pous item",
                "invalid_argument",
                {"path": "entries", "expected":
                 "same length as pous", "actual": supplied_entries},
            )
    names = []
    textual_program_names = []
    seen = set()
    for index, value in enumerate(requested):
        name = _text(value).strip()
        if not name:
            raise OperationError(
                "task POU name must not be empty",
                "invalid_argument",
                {"path": "pous[%d]" % index, "expected": "existing PROGRAM name", "actual": value},
            )
        lowered = name.lower()
        if lowered in seen:
            raise OperationError(
                "duplicate task POU: " + name,
                "duplicate_task_pou",
                {"path": "pous[%d]" % index, "actual": name},
            )
        pou = find_textual_object(name)
        if pou is not None:
            declaration = read_st(pou).get("declaration", "").lstrip().upper()
            if not declaration.startswith("PROGRAM "):
                raise OperationError(
                    "task entries must reference PROGRAM POUs: " + name,
                    "invalid_task_pou_kind",
                    {"path": "pous[%d]" % index, "expected": "PROGRAM", "actual": declaration.split(" ", 1)[0]},
                )
            textual_program_names.append(name)
        else:
            # Vendor task configurations may contain generated/external calls
            # (for example ETHERCAT.EtherCAT_Task) that are not textual POUs.
            # Preserve them only when they are already present in this task;
            # never allow an unknown name to be introduced by this route.
            existing_task = None
            try:
                _, existing_task = _find_task(task_name)
                existing_names = [
                    record.get("name") for record in
                    _task_call_records("", existing_task)
                    if record.get("name")
                ]
                if not existing_names:
                    existing_names = [
                        (_object_name(item) or _text(item)) for item in
                        list(_get_member(existing_task, "pous", "get_pous") or [])
                    ]
                    existing_names.extend(
                        _object_name(child) for child in _children(existing_task)
                        if _object_name(child)
                    )
            except Exception:
                existing_names = []
            if (not any(_task_pou_names_match(name, existing)
                        for existing in existing_names) and
                    "." not in name):
                raise OperationError(
                    "task POU does not exist: " + name,
                    "pou_not_found",
                    {"path": "pous[%d]" % index, "actual": name},
                )
        seen.add(lowered)
        names.append(name)

    task_path, task = _find_task(task_name)
    collection = _get_member(task, "pous", "get_pous")
    if collection is None:
        raise OperationError(
            "task POU collection is unavailable: " + task_name,
            "task_pou_collection_unavailable",
        )
    before_entries = _task_pou_snapshot(collection)
    before = [entry["name"] for entry in before_entries]

    # InoProShop rejects a PROGRAM assigned to more than one task with C0457.
    # Perform this complete read-only preflight before calling replace/remove/
    # add so a rejected request cannot leave a partially changed task list.
    try:
        conflicts = _task_pou_cross_task_conflicts(
            task_path, task, textual_program_names)
    except Exception as exc:
        # Never fall through to a native mutation when the project-wide call
        # inventory cannot be read.  A false negative here would merely defer
        # the same C0457 failure to compile, after the task list may already
        # have changed.
        raise OperationError(
            "task POU cross-task conflict preflight could not be completed",
            "task_pou_conflict_preflight_failed",
            {
                "task": task_name,
                "taskPath": task_path,
                "before": before,
                "requested": names,
                "error": repr(exc),
                "mutatedProject": False,
                "preflight": "read_only_task_call_inventory",
            },
        )
    if conflicts:
        raise OperationError(
            "one or more PROGRAM POUs are already assigned to another task "
            "(InoProShop C0457)",
            "task_pou_cross_task_conflict",
            {
                "task": task_name,
                "taskPath": task_path,
                "before": before,
                "requested": names,
                "conflicts": conflicts,
                "conflictCount": len(conflicts),
                "nativeErrorCode": "C0457",
                "mutatedProject": False,
                "preflight": "read_only_task_call_inventory",
            },
        )

    if supplied_entries is not None:
        requested_entries = []
        for index, entry in enumerate(supplied_entries):
            if not isinstance(entry, dict):
                raise OperationError(
                    "task.pou.set entries must contain objects",
                    "invalid_argument",
                    {"path": "entries[%d]" % index,
                     "expected": {"name": names[index],
                                   "comment": ""},
                     "actual": entry},
                )
            entry_name = _text(entry.get("name")).strip()
            if not _task_pou_names_match(entry_name, names[index]):
                raise OperationError(
                    "task.pou.set entries names must match pous in order",
                    "invalid_argument",
                    {"path": "entries[%d].name" % index,
                     "expected": names[index], "actual": entry_name},
                )
            # E2E V2 R023: a non-empty comment is NOT persisted by this CODESYS
            # build's task-call API (readback always ''), and the write-then-
            # readback-mismatch path left a BROKEN rollback with duplicate
            # entries (restored=false, after=["PLC_PRG","PLC_PRG"]). Reject
            # non-empty comments BEFORE any mutation instead of failing after.
            comment = _text(entry.get("comment"))
            if comment:
                raise OperationError(
                    "task POU comments are not persisted by this CODESYS build "
                    "(readback always returns ''); pass pous without entries, "
                    "or entries with empty comment fields",
                    "task_pou_comment_not_persisted",
                    {"path": "entries[%d].comment" % index,
                     "actual": comment,
                     "mutatedProject": False},
                )
            requested_entries.append({
                "name": names[index],
                "comment": "",
            })
    else:
        # The compact names-only API must not erase comments on calls that are
        # retained.  Preserve by normalized name (not only by position), so a
        # reorder/resize operation remains lossless; newly introduced names
        # receive the historical empty comment default.
        requested_entries = []
        for name in names:
            comment = ""
            for existing in before_entries:
                if _task_pou_names_match(name, existing.get("name")):
                    comment = _text(existing.get("comment"))
                    break
            requested_entries.append({"name": name, "comment": comment})

    try:
        mutation_trace, after_entries = _task_pou_apply_entries(
            collection, requested_entries, task=task)
        after = [entry["name"] for entry in after_entries]
    except Exception as exc:
        recovery = {
            "attempted": True, "restored": False, "error": None,
            "trace": [], "after": None,
        }
        try:
            recovery["trace"], restored_entries = _task_pou_apply_entries(
                collection, before_entries, task=task)
            recovery["after"] = [entry["name"] for entry in restored_entries]
            recovery["restored"] = restored_entries == before_entries
        except Exception as restore_exc:
            recovery["error"] = repr(restore_exc)
            try:
                recovery["after"] = [
                    entry["name"] for entry in _task_pou_snapshot(collection)
                ]
            except Exception:
                pass
        raise OperationError(
            "task POU update failed: " + repr(exc),
            "task_pou_set_failed",
            {"task": task_name, "before": before, "requested": names, "recovery": recovery},
        )
    return {
        "task": task_name,
        "taskPath": task_path,
        "before": before,
        "after": after,
        "beforeEntries": before_entries,
        "afterEntries": after_entries,
        "exactReadback": after == names,
        "resized": len(before) != len(after),
        "mutationTrace": mutation_trace,
    }


def program_audit(req):
    """Read-only audit of whether a POU participates in an executable program."""
    _require_project()
    target = _text(req.get("pou") or req.get("target") or
                   req.get("program") or "PLC_PRG").strip()
    requested_task = req.get("task")
    requested_task_text = _text(requested_task).strip()
    explicit_task = bool(requested_task_text)
    task_name = requested_task_text or "MainTask"
    result = {
        "targetPou": target,
        "targetTask": task_name,
        "taskInference": {
            "requestedTask": (requested_task_text
                               if requested_task_text else None),
            "explicit": explicit_task,
            "inferred": False,
            "reason": ("explicit_task" if explicit_task
                        else "default_main_task"),
            "ownerTask": None,
            "ownerTaskPath": None,
            "ownerTaskGuid": None,
        },
        "checks": {},
        "missing": [],
        "warnings": [],
    }
    devices = device_tree().get("devices", [])
    cpu_devices = [item for item in devices
                   if (item.get("deviceId") or {}).get("type") == 4102]
    result["cpuDevices"] = cpu_devices
    result["checks"]["singleCpu"] = len(cpu_devices) == 1

    pou_error = None
    try:
        normalized_path = target.replace("\\", "/").strip("/")
        if "/" in normalized_path:
            pou, pou_path = find_project_object(normalized_path)
            if not _is_textual(pou):
                raise RuntimeError("target is not a textual POU: " + target)
        else:
            # A task call object has the same name as its referenced POU. A
            # bare-name project-tree lookup is therefore ambiguous after the
            # POU is assigned to a task; restrict this lookup to POU objects.
            pou = find_textual_object(target)
            if pou is None:
                pou_path = None
            else:
                paths = [
                    item.get("path") for item in list_textual_objects()
                    if item.get("name") == target and item.get("path")
                ]
                if len(paths) != 1:
                    raise RuntimeError(
                        "textual POU path is ambiguous for '%s': %r" %
                        (target, paths)
                    )
                pou_path = paths[0]
    except Exception as exc:
        pou, pou_path = None, None
        pou_error = repr(exc)
    if pou is None:
        result["checks"]["pouExists"] = False
        result["missing"].append("target POU does not exist: " + target)
        if pou_error:
            result["warnings"].append(pou_error)
    else:
        result["checks"]["pouExists"] = True
        result["pou"] = _object_summary(pou, pou_path)
        result["pou"].update(read_st(pou))

    # Collect project-wide call evidence before resolving the selected task.
    # This lets an omitted ``task`` be safely inferred from a unique PROGRAM
    # owner instead of treating every non-MainTask assignment as a C0457
    # duplicate.  The small local normalizers keep this public function
    # usable by the AST/fixture contract tests without importing the native
    # bridge helper graph.
    def audit_name_key(value):
        value = _text(value).strip().replace("\\", "/")
        while "//" in value:
            value = value.replace("//", "/")
        return value.strip("/").lower()

    def assignment_owner_key(row):
        return (audit_name_key(row.get("taskPath")) or
                audit_name_key(row.get("taskGuid")) or
                audit_name_key(row.get("task")))

    def assignment_identity(row):
        return (audit_name_key(row.get("pouKey") or row.get("pou")),
                assignment_owner_key(row))

    def merge_assignment_rows(*sources):
        merged = []
        seen = set()
        for source in sources:
            if not isinstance(source, list):
                continue
            for row in source:
                if not isinstance(row, dict):
                    continue
                identity = assignment_identity(row)
                if identity[0] and identity[1]:
                    if identity in seen:
                        continue
                    seen.add(identity)
                merged.append(row)
        return merged

    def program_owner_rows(rows):
        owners = {}
        unknown = []
        for row in rows:
            if row.get("isProgram", True) is False:
                continue
            key = assignment_owner_key(row)
            if not key:
                unknown.append(row)
                continue
            if key not in owners:
                owners[key] = row
        ordered = sorted(
            owners.values(),
            key=lambda item: (audit_name_key(item.get("taskPath")) or
                              audit_name_key(item.get("task")) or
                              audit_name_key(item.get("taskGuid"))),
        )
        return ordered, unknown

    def owner_display_name(row):
        name = _text(row.get("task")).strip()
        if name:
            return name
        path = _text(row.get("taskPath")).replace("\\", "/").strip("/")
        return path.rsplit("/", 1)[-1] if path else ""

    task_call_audit = None
    task_call_audit_error = None
    try:
        # No selected task is passed intentionally: targetOtherTaskAssignments
        # then remains a project-wide source view, while owner rows below are
        # deduplicated by task identity.
        task_call_audit = _task_call_audit(
            target=target, target_task_path=None, target_task=None
        )
    except Exception as exc:
        task_call_audit_error = repr(exc)
        task_call_audit = {
            "tasks": [],
            "assignments": [],
            "duplicateTaskCalls": [],
            "targetAssignments": [],
            "targetOtherTaskAssignments": [],
            "targetOwnerTasks": [],
            "targetOwnerTaskCount": 0,
            "targetOwnerAssignmentsUnknown": [],
            "targetDuplicateAcrossTasks": False,
            "error": repr(exc),
        }

    target_assignment_rows = merge_assignment_rows(
        task_call_audit.get("targetAssignments", []),
        task_call_audit.get("targetOtherTaskAssignments", []),
        task_call_audit.get("targetOwnerTasks", []),
    )
    owner_rows, owner_unknown = program_owner_rows(target_assignment_rows)

    if not explicit_task and pou is not None and len(owner_rows) == 1 and not owner_unknown:
        owner = owner_rows[0]
        inferred_task_name = owner_display_name(owner)
        if inferred_task_name:
            task_name = inferred_task_name
            result["taskInference"] = {
                "requestedTask": None,
                "explicit": False,
                "inferred": True,
                "reason": "unique_program_owner",
                "ownerTask": _text(owner.get("task")) or inferred_task_name,
                "ownerTaskPath": _text(owner.get("taskPath")) or None,
                "ownerTaskGuid": _text(owner.get("taskGuid")) or None,
            }
    result["targetTask"] = task_name

    if task_call_audit_error:
        result["warnings"].append(
            "project-wide task-call audit could not be completed: " +
            task_call_audit_error
        )

    try:
        task_path, task = _find_task(task_name)
        task_data = _task_summary(task_path, task)
        result["task"] = task_data
        result["checks"]["taskExists"] = True
    except Exception as exc:
        task = None
        task_data = None
        result["checks"]["taskExists"] = False
        result["missing"].append("task does not exist: " + task_name)
        result["warnings"].append(repr(exc))

    call_names = []
    unresolved_calls = []
    if task_data is not None:
        for item in task_data.get("childCalls", []):
            references = item.get("references") or {}
            if references:
                call_names.extend(references.values())
            elif item.get("name"):
                unresolved_calls.append(item.get("name"))
        for item in task_data.get("pouCalls", []):
            if isinstance(item, dict) and item.get("name"):
                call_names.append(item.get("name"))
            elif not isinstance(item, dict) and _text(item):
                call_names.append(_text(item))
    normalized_target = target.replace("\\", "/").split("/")[-1].lower()
    call_names = [_text(name) for name in call_names if _text(name)]
    # IScriptTaskObject.pous is the documented authoritative collection of
    # executed POU names. Child task-reference objects can remain opaque.
    if call_names:
        unresolved_calls = []
    called = normalized_target in [name.lower() for name in call_names]
    if not called and unresolved_calls:
        called = None
    result["checks"]["calledByTask"] = called
    result["checks"]["taskCallsResolved"] = not bool(unresolved_calls)
    result["resolvedTaskCalls"] = sorted(set(call_names))
    result["unresolvedTaskCallObjects"] = sorted(set(unresolved_calls))

    # The inventory was collected before task resolution so that omitted
    # ``task`` requests could be inferred from a unique owner.  Reuse that
    # read-only snapshot here; a second native traversal would add latency and
    # could observe a transiently different task tree.
    result["taskCallAssignments"] = task_call_audit.get("assignments", [])
    result["duplicateTaskCalls"] = task_call_audit.get(
        "duplicateTaskCalls", [])
    target_assignments = target_assignment_rows
    target_program_assignments = [
        row for row in target_assignments
        if row.get("isProgram", True) is not False
    ]
    owner_rows, owner_unknown = program_owner_rows(target_program_assignments)

    selected_path_key = audit_name_key((task_data or {}).get("path"))
    selected_guid = _text((task_data or {}).get("guid")).strip()
    selected_name_key = audit_name_key((task_data or {}).get("name"))
    if not selected_name_key and task is not None:
        try:
            selected_name_key = audit_name_key(getattr(task, "name", ""))
        except Exception:
            selected_name_key = ""

    def is_selected_task(row):
        row_path_key = audit_name_key(row.get("taskPath"))
        if selected_path_key and row_path_key:
            return row_path_key == selected_path_key
        row_guid = _text(row.get("taskGuid")).strip()
        if selected_guid and row_guid:
            return row_guid == selected_guid
        row_name_key = audit_name_key(row.get("task"))
        if selected_name_key and row_name_key:
            return row_name_key == selected_name_key
        return False

    non_selected_program_assignments = [
        row for row in target_program_assignments
        if not is_selected_task(row)
    ]
    # C0457 is a property of a POU having more than one distinct PROGRAM
    # owner, not a property of whether the selected task happens to be the
    # default MainTask.  A unique owner on TaskBeta is therefore healthy when
    # ``task`` was omitted (and is also not a conflict for an explicit
    # MainTask audit).
    duplicate_across_tasks = len(owner_rows) > 1
    # Preserve the historical meaning of ``otherTaskAssignments`` as an
    # observational list relative to the selected task.  It may contain one
    # unique owner on another task; that fact alone is not a C0457 conflict.
    # Consumers must use ``duplicateAcrossTasks``/``ownerTaskCount`` for the
    # native-conflict decision.
    target_other_assignments = non_selected_program_assignments
    result["crossTaskCallEvidence"] = {
        "targetPou": target,
        "assignments": target_assignments,
        "otherTaskAssignments": target_other_assignments,
        "nonSelectedTaskAssignments": non_selected_program_assignments,
        "ownerTasks": owner_rows,
        "ownerTaskCount": len(owner_rows),
        "unknownOwnerAssignments": owner_unknown,
        "duplicateAcrossTasks": duplicate_across_tasks,
        "nativeErrorCode": ("C0457" if duplicate_across_tasks else None),
    }
    result["checks"]["calledByOtherTask"] = (
        None if task is None else bool(target_other_assignments)
    )
    result["checks"]["crossTaskConflictFree"] = (
        False if task is None else not duplicate_across_tasks
    )
    if duplicate_across_tasks:
        result["warnings"].append(
            "target PROGRAM is assigned to another task; InoProShop may "
            "report C0457 (cross-task task POU conflict)"
        )
        result["missing"].append(
            "target POU is assigned to more than one task"
        )
    if called is False:
        result["missing"].append(
            "target POU is not called by task %s" % task_name
        )
    elif called is None:
        result["missing"].append(
            "task call references could not be resolved through the SP11 API"
        )

    declaration = (result.get("pou") or {}).get("declaration", "")
    implementation_language = (result.get("pou") or {}).get(
        "implementationLanguage", ""
    )
    result["checks"]["hasDeclaration"] = bool(declaration.strip())
    language_text = _text(implementation_language).lower()
    if language_text:
        result["checks"]["isLadder"] = (
            language_text == "ld" or
            any(marker in language_text for marker in ("ladder", "lad"))
        )
        result["checks"]["ladderLanguageResolved"] = True
    else:
        result["checks"]["isLadder"] = None
        result["checks"]["ladderLanguageResolved"] = False
        result["warnings"].append(
            "implementation language is not exposed by this graphical POU API; "
            "native LAD export/readback is required"
        )
    result["parameterEvidence"] = {
        "declaration": declaration,
        "hasDirectAddress": " AT %" in declaration.upper(),
        "hasFunctionBlockInstance": any(
            (":" + name) in declaration.replace(" ", "").upper()
            for name in ("TON", "TOF", "TP", "CTU", "CTD", "CTUD")
        ),
        "note": "Compilation proves type correctness, not live I/O behavior.",
    }
    if not result["parameterEvidence"]["hasDirectAddress"]:
        result["warnings"].append(
            "no direct AT % I/O address is visible in the POU declaration; "
            "GVL or device I/O mapping may still supply external signals"
        )

    structure_checks = ("singleCpu", "pouExists", "taskExists", "calledByTask",
                        "crossTaskConflictFree", "hasDeclaration", "isLadder")
    result["executableStructureComplete"] = all(
        result["checks"].get(name) for name in structure_checks
    )
    result["claims"] = {
        "taskInvocationVerified": bool(result["checks"].get("calledByTask")),
        "offlineCompileVerified": False,
        "ioMappingVerified": False,
        "onlineRuntimeVerified": False,
    }
    result["complete"] = all(result["claims"].values())
    result["status"] = "complete" if result["complete"] else "incomplete"
    if not result["claims"]["offlineCompileVerified"]:
        result["missing"].append(
            "offline compile is not part of this read-only audit; run build.compile"
        )
    if not result["claims"]["ioMappingVerified"]:
        result["missing"].append(
            "I/O mapping is not verified by declarations or compilation"
        )
    if not result["claims"]["onlineRuntimeVerified"]:
        result["missing"].append(
            "online download and runtime behavior require target hardware evidence"
        )
    return result


def _library_summary(value):
    result = {}
    fields = (
        ("display_name", ("display_name", "DisplayName")),
        ("name", ("name", "Name")),
        ("namespace", ("namespace", "Namespace")),
        ("version", ("version", "Version")),
        ("company", ("company", "Company")),
        ("category", ("category", "Category")),
        ("default_resolution", ("default_resolution", "DefaultResolution")),
        ("is_placeholder", ("is_placeholder", "IsPlaceholder")),
    )
    for output_name, candidates in fields:
        item = None
        for candidate in candidates:
            try:
                item = _get_member(value, candidate, "get_" + candidate)
            except Exception:
                item = None
            if item is not None and _text(item) != "":
                break
        if item is not None and _text(item) != "":
            result[output_name] = _json_safe(item)
    try:
        result["runtimeType"] = _text(value.GetType().FullName)
    except Exception:
        pass
    if not result:
        result["display"] = _text(value)
    else:
        # Some SP11 repository wrappers expose no Name property but have a
        # useful ToString() value. Keep it as a diagnostic fallback without
        # pretending it is a canonical library identity.
        try:
            display = _text(value)
            if display and display not in (result.get("runtimeType"), "System.Object"):
                result["display"] = display
        except Exception:
            pass
    return result


def _normalized_library_identity(value):
    """Normalize one display identity without weakening exact-version checks."""
    return re.sub(r"\s+", " ", _text(value).strip()).lower()


def _library_identity_candidates(value):
    """Return only native identity spellings, excluding diagnostic CLR text."""
    summary = value if isinstance(value, dict) else _library_summary(value)
    result = []
    for field in ("name", "display_name", "default_resolution", "display"):
        candidate = _text(summary.get(field)).strip()
        if (not candidate or candidate.startswith("<") or
                candidate in result):
            continue
        result.append(candidate)
    name = _text(summary.get("name")).strip()
    version = _text(summary.get("version")).strip()
    company = _text(summary.get("company")).strip()
    if name and version and "," not in name:
        combined = name + ", " + version
        if company:
            combined += " (" + company + ")"
        if combined not in result:
            result.append(combined)
    return result


def _library_exact_resolution_matches(value, requested_resolution):
    return bool(_library_exact_resolution_value(value, requested_resolution))


def _library_exact_resolution_value(value, requested_resolution):
    """Return the native spelling equal to the requested full identity."""
    requested = _normalized_library_identity(requested_resolution)
    if not requested:
        return ""
    for candidate in _library_identity_candidates(value):
        if _normalized_library_identity(candidate) == requested:
            return candidate
    return ""


def _installed_library_exact_matches(name, resolution):
    """Resolve an exact installed identity before any project mutation."""
    try:
        values = list(librarymanager.get_all_libraries(False))
    except Exception:
        values = list(librarymanager.get_all_libraries())
    return [
        value for value in values
        if _library_reference_matches(value, name) and
        _library_exact_resolution_matches(value, resolution)
    ]


def _native_managed_library_manager():
    """Resolve the same ManagedLibraryMgr used by the vendor Library UI.

    ``librarymanager`` is a ScriptEngine wrapper and is sufficient for older
    read operations, but the documented vendor install path lives on the
    InoLibManEditor dependency bag.  Prefer that concrete manager for every
    repository operation so a successful inspection cannot be confused with
    an unverified installation binding.
    """
    import System
    flags = (System.Reflection.BindingFlags.Static |
             System.Reflection.BindingFlags.Public |
             System.Reflection.BindingFlags.NonPublic)
    attempts = []
    for type_name in (
            "Inovance.InoPro.InoLibManEditor.APEnvironment, InoLibManEditor",
            "Inovance.InoPro.InoDeviceObject.APEnvironment, InoDeviceObject"):
        ap_type = _reflection_type(type_name)
        if ap_type is None:
            attempts.append({"binding": type_name + ".ManagedLibraryMgr",
                             "error": "type unavailable"})
            continue
        try:
            prop = ap_type.GetProperty("ManagedLibraryMgr", flags)
            manager = prop.GetValue(None, None) if prop is not None else None
            if manager is not None:
                return manager, type_name + ".ManagedLibraryMgr", attempts
            attempts.append({"binding": type_name + ".ManagedLibraryMgr",
                             "error": "property returned null"})
        except Exception as exc:
            attempts.append({"binding": type_name + ".ManagedLibraryMgr",
                             "error": repr(exc)})
    if librarymanager is not None:
        return librarymanager, "ScriptEngine.librarymanager_fallback", attempts
    raise OperationError(
        "managed library manager is unavailable",
        "library_manager_unavailable",
        {"attempts": attempts, "mutatedSystem": False},
    )


def _managed_library_repositories():
    """Return native managed-library repositories with binding evidence.

    ScriptEngine exposes this as a property in some SP11 builds while the
    vendor UI calls ``GetAllRepositories``.  Read both shapes rather than
    assuming that the wrapper has one particular spelling.
    """
    manager, manager_binding, attempts = _native_managed_library_manager()
    for name in ("get_all_repositories", "GetAllRepositories"):
        try:
            values = list(getattr(manager, name)())
            return values, manager_binding + "." + name + "()", attempts
        except Exception as exc:
            attempts.append({"binding": name + "()", "error": repr(exc)})
    for name in ("repositories", "get_repositories"):
        try:
            value = getattr(manager, name)
            if hasattr(value, "__call__"):
                value = value()
            return list(value), manager_binding + "." + name, attempts
        except Exception as exc:
            attempts.append({"binding": name, "error": repr(exc)})
    raise OperationError(
        "managed library repository binding is unavailable",
        "library_repository_binding_unavailable",
        {"attempts": attempts, "mutatedSystem": False},
    )


def _managed_repository_index(req):
    value = req.get("repositoryIndex", req.get("repository_index", 0))
    try:
        index = int(value)
    except Exception:
        raise OperationError(
            "repositoryIndex must be a non-negative integer",
            "invalid_argument", {"path": "repositoryIndex", "value": value},
        )
    if index < 0:
        raise OperationError(
            "repositoryIndex must be a non-negative integer",
            "invalid_argument", {"path": "repositoryIndex", "value": value},
        )
    return index


def _managed_repository_summary(repository, index):
    result = {"index": index}
    for output, names in (
            ("name", ("name", "Name")),
            ("rootFolder", ("root_folder", "RootFolder")),
            ("editable", ("editable", "Editable")),
            ("readOnly", ("read_only", "ReadOnly"))):
        for name in names:
            value = _get_member(repository, name, "get_" + name)
            if value is not None:
                result[output] = _json_safe(value)
                break
    try:
        result["runtimeType"] = _text(repository.GetType().FullName)
    except Exception:
        pass
    return result


def _managed_repository_at(index):
    repositories, binding, attempts = _managed_library_repositories()
    if index >= len(repositories):
        raise OperationError(
            "repositoryIndex is not installed",
            "library_repository_not_found",
            {"repositoryIndex": index, "repositoryCount": len(repositories),
             "repositories": [_managed_repository_summary(value, number)
                              for number, value in enumerate(repositories)],
             "binding": binding, "attempts": attempts, "mutatedSystem": False},
        )
    # The vendor code uses GetRepository(0) for the default target.  Prefer
    # that native API, but require it to identify the same indexed repository
    # we just enumerated before allowing a mutation through it.
    manager, manager_binding, manager_attempts = _native_managed_library_manager()
    attempts.extend(manager_attempts)
    for name in ("get_repository", "GetRepository"):
        try:
            selected = getattr(manager, name)(index)
            if selected is not None:
                return selected, _managed_repository_summary(selected, index), {
                    "enumeration": binding, "selection": manager_binding + "." + name + "()",
                    "failedBindings": attempts,
                }
        except Exception as exc:
            attempts.append({"binding": name + "()", "error": repr(exc)})
    return repositories[index], _managed_repository_summary(repositories[index], index), {
        "enumeration": binding, "selection": "enumerated_index",
        "failedBindings": attempts,
    }


def _managed_repository_libraries(repository):
    manager, manager_binding, attempts = _native_managed_library_manager()
    for name in ("get_all_libraries", "GetAllLibraries"):
        try:
            return (list(getattr(manager, name)(repository)),
                    manager_binding + "." + name + "(repository)", attempts)
        except Exception as exc:
            attempts.append({"binding": name + "(repository)", "error": repr(exc)})
    raise OperationError(
        "managed library enumeration for repository is unavailable",
        "library_repository_binding_unavailable",
        {"attempts": attempts, "mutatedSystem": False},
    )


def _managed_library_file_path(value):
    manager, manager_binding, attempts = _native_managed_library_manager()
    for name, args in (
            ("get_file_path", (value, True)),
            ("get_file_path", (value,)),
            ("GetFilePath", (value, True)),
            ("GetFilePath", (value,))):
        try:
            path = getattr(manager, name)(*args)
            if path:
                return _text(path), manager_binding + "." + name, attempts
        except Exception as exc:
            attempts.append({"binding": name, "error": repr(exc)})
    return None, None, attempts


def _library_file_metadata(path, include_hash):
    result = {"path": path, "exists": bool(path and os.path.isfile(path))}
    if result["exists"]:
        try:
            result["bytes"] = os.path.getsize(path)
            if include_hash:
                digest = hashlib.sha256()
                with open(path, "rb") as stream:
                    while True:
                        chunk = stream.read(1024 * 1024)
                        if not chunk:
                            break
                        digest.update(chunk)
                result["sha256"] = digest.hexdigest()
        except Exception as exc:
            result["metadataError"] = repr(exc)
    return result


def library_repository_inspect(req):
    """Read exact repository identities and their installed libraries only."""
    req = req or {}
    pattern = _text(req.get("pattern", "")).strip().lower()
    limit = max(1, min(int(req.get("limit", 200)), 2000))
    include_libraries = bool(req.get("includeLibraries", True))
    include_file_metadata = bool(req.get("includeFileMetadata", False))
    include_file_hash = bool(req.get("includeFileHash", False))
    if include_file_hash:
        include_file_metadata = True
    repositories, binding, attempts = _managed_library_repositories()
    requested = req.get("repositoryIndex", req.get("repository_index"))
    if requested is None:
        indexes = range(len(repositories))
    else:
        indexes = [_managed_repository_index(req)]
    result = []
    for index in indexes:
        if index >= len(repositories):
            raise OperationError(
                "repositoryIndex is not installed", "library_repository_not_found",
                {"repositoryIndex": index, "repositoryCount": len(repositories),
                 "mutatedSystem": False},
            )
        repository = repositories[index]
        entry = _managed_repository_summary(repository, index)
        if include_libraries:
            values, library_binding, library_attempts = _managed_repository_libraries(repository)
            libraries = []
            for value in values:
                summary = _library_summary(value)
                if pattern and pattern not in _text(summary).lower():
                    continue
                path, path_binding, path_attempts = _managed_library_file_path(value)
                if path:
                    summary["file"] = _library_file_metadata(path, include_file_hash) \
                        if include_file_metadata else {"path": path}
                    summary["fileBinding"] = path_binding
                if path_attempts:
                    summary["fileBindingFailures"] = path_attempts
                libraries.append(summary)
                if len(libraries) >= limit:
                    break
            entry["libraryCount"] = len(values)
            entry["libraries"] = libraries
            entry["truncated"] = len(libraries) < len(values) and len(libraries) >= limit
            entry["libraryBinding"] = library_binding
            if library_attempts:
                entry["libraryBindingFailures"] = library_attempts
        result.append(entry)
    return {
        "readOnly": True,
        "mutatedSystem": False,
        "repositoryCount": len(repositories),
        "repositories": result,
        "repositoryBinding": binding,
        "repositoryBindingFailures": attempts,
    }


def _require_system_library_mutation(req, operation, expected_confirm):
    if req.get("systemMutation") is not True:
        raise OperationError(
            operation + " changes the machine-wide managed library repository; "
            "repeat with systemMutation=true after inspecting the exact target",
            "system_mutation_confirmation_required",
            {"operation": operation, "mutatedSystem": False,
             "required": ["systemMutation=true", "confirm=" + expected_confirm],
             "next": "call library.repository.inspect first"},
        )
    if _text(req.get("confirm")).strip() != expected_confirm:
        raise OperationError(
            operation + " requires an exact confirmation token",
            "confirmation_required",
            {"operation": operation, "mutatedSystem": False,
             "expectedConfirm": expected_confirm},
        )


def _install_managed_library(req):
    operation = "library.install"
    path = _text(req.get("path")).strip()
    if not path:
        raise OperationError(operation + " requires path", "invalid_argument",
                             {"path": "path", "mutatedSystem": False})
    path = os.path.abspath(path)
    if not os.path.isfile(path):
        raise OperationError("library package file was not found", "library_package_not_found",
                             {"path": path, "mutatedSystem": False})
    extension = os.path.splitext(path)[1].lower()
    if extension not in (".library", ".compiled-library"):
        raise OperationError(
            "library.install accepts only .library or .compiled-library files",
            "unsupported_library_package", {"path": path, "extension": extension,
                                             "mutatedSystem": False},
        )
    digest = _library_file_metadata(path, True).get("sha256")
    expected_digest = _text(req.get("expectedSha256")).strip().lower()
    if expected_digest != digest:
        raise OperationError(
            "expectedSha256 must match the exact library file before installation",
            "library_package_hash_mismatch",
            {"path": path, "expectedSha256": expected_digest or None,
             "actualSha256": digest, "mutatedSystem": False},
        )
    index = _managed_repository_index(req)
    overwrite = bool(req.get("overwrite", False))
    expected_confirm = (("install_library_overwrite:" if overwrite else "install_library:") + digest)
    _require_system_library_mutation(req, operation, expected_confirm)
    repository, repository_summary, binding = _managed_repository_at(index)
    before, before_binding, before_attempts = _managed_repository_libraries(repository)
    install_attempts = []
    installed = None
    manager, manager_binding, manager_attempts = _native_managed_library_manager()
    install_attempts.extend(manager_attempts)
    for name in ("install_library", "InstallLibrary"):
        try:
            installed = getattr(manager, name)(repository, path, overwrite)
            install_attempts.append({"binding": manager_binding + "." + name + "(repository,path,overwrite)", "ok": True})
            break
        except Exception as exc:
            install_attempts.append({"binding": manager_binding + "." + name + "(repository,path,overwrite)", "error": repr(exc)})
    if installed is None:
        raise OperationError(
            "native managed-library installation returned no library",
            "library_install_failed",
            {"path": path, "sha256": digest, "repository": repository_summary,
             "attempts": install_attempts, "systemMutationAttempted": True,
             "mutatedSystem": False},
        )
    after, after_binding, after_attempts = _managed_repository_libraries(repository)
    installed_summary = _library_summary(installed)
    installed_identity = _text(installed_summary.get("display_name") or
                               installed_summary.get("name"))
    if installed_identity:
        retained = False
        for value in after:
            summary = _library_summary(value)
            if installed_identity in (_text(summary.get("display_name")),
                                     _text(summary.get("name"))):
                retained = True
                break
        if not retained:
            raise OperationError(
                "native installation returned but the installed library is absent from repository readback",
                "library_install_readback_mismatch",
                {"path": path, "sha256": digest, "installedLibrary": installed_summary,
                 "repository": repository_summary, "systemMutationAttempted": True,
                 "mutatedSystem": True},
            )
    return {
        "installed": True, "mutatedSystem": True, "path": path,
        "file": _library_file_metadata(path, True), "repository": repository_summary,
        "installedLibrary": installed_summary,
        "beforeCount": len(before), "afterCount": len(after),
        "bindings": {"repository": binding, "before": before_binding,
                     "install": install_attempts, "after": after_binding},
        "bindingFailures": before_attempts + after_attempts,
    }


def _uninstall_managed_library(req):
    operation = "library.uninstall"
    requested = _text(req.get("library") or req.get("name")).strip()
    if not requested:
        raise OperationError(operation + " requires an exact library identity", "invalid_argument",
                             {"path": "library", "mutatedSystem": False})
    index = _managed_repository_index(req)
    repository, repository_summary, binding = _managed_repository_at(index)
    values, list_binding, list_attempts = _managed_repository_libraries(repository)
    matches = []
    for value in values:
        summary = _library_summary(value)
        identities = [
            _text(summary.get("display_name")), _text(summary.get("name")),
            _text(summary.get("default_resolution")), _text(summary.get("display")),
        ]
        if requested in identities:
            matches.append((value, summary))
    if not matches:
        raise OperationError(
            "exact library identity was not found in the selected repository",
            "library_not_found",
            {"library": requested, "repository": repository_summary,
             "mutatedSystem": False},
        )
    if len(matches) != 1:
        raise OperationError(
            "library identity is ambiguous; use display_name from library.repository.inspect",
            "ambiguous_library_identity",
            {"library": requested, "matches": [summary for _value, summary in matches],
             "mutatedSystem": False},
        )
    selected, selected_summary = matches[0]
    canonical = _text(selected_summary.get("display_name") or
                      selected_summary.get("name") or requested)
    _require_system_library_mutation(req, operation, "uninstall_library:" + canonical)
    uninstall_attempts = []
    removed = False
    manager, manager_binding, manager_attempts = _native_managed_library_manager()
    uninstall_attempts.extend(manager_attempts)
    for name in ("uninstall_library", "UninstallLibrary"):
        try:
            getattr(manager, name)(repository, selected)
            uninstall_attempts.append({"binding": manager_binding + "." + name + "(repository,library)", "ok": True})
            removed = True
            break
        except Exception as exc:
            uninstall_attempts.append({"binding": manager_binding + "." + name + "(repository,library)", "error": repr(exc)})
    if not removed:
        raise OperationError(
            "native managed-library uninstall failed",
            "library_uninstall_failed",
            {"library": selected_summary, "repository": repository_summary,
             "attempts": uninstall_attempts, "systemMutationAttempted": True,
             "mutatedSystem": False},
        )
    after, after_binding, after_attempts = _managed_repository_libraries(repository)
    remaining = []
    for value in after:
        summary = _library_summary(value)
        if canonical in (_text(summary.get("display_name")), _text(summary.get("name"))):
            remaining.append(summary)
    if remaining:
        raise OperationError(
            "native uninstall returned but the exact library remains in repository readback",
            "library_uninstall_readback_mismatch",
            {"library": selected_summary, "remaining": remaining,
             "repository": repository_summary, "mutatedSystem": True},
        )
    return {
        "uninstalled": True, "mutatedSystem": True,
        "library": selected_summary, "repository": repository_summary,
        "beforeCount": len(values), "afterCount": len(after),
        "bindings": {"repository": binding, "list": list_binding,
                     "uninstall": uninstall_attempts, "after": after_binding},
        "bindingFailures": list_attempts + after_attempts,
    }


def _find_project_library_manager():
    matches = []

    def is_manager(candidate):
        try:
            return (hasattr(candidate, "references") or
                    bool(_get_member(candidate, "is_libman", "get_is_libman", False)))
        except Exception:
            return False

    def visit(parent):
        for child in _children(parent):
            if is_manager(child):
                matches.append(child)
            visit(child)

    # A vendor project can expose a root Library Manager plus the real
    # application-scoped manager.  Library references belong to the active
    # Application, so resolve that subtree first instead of treating both
    # objects as interchangeable.
    active = _get_member(project, "active_application", "get_active_application")
    application_matches = []
    if active is not None:
        def visit_application(parent):
            for child in _children(parent):
                if is_manager(child):
                    application_matches.append(child)
                visit_application(child)
        visit_application(active)
        if len(application_matches) == 1:
            return application_matches[0]

    visit(project)
    if not matches:
        raise RuntimeError("project Library Manager object not found")
    if len(matches) > 1:
        exact = [item for item in matches
                 if _object_name(item).lower() in ("library manager", u"库管理器")]
        if len(exact) == 1:
            return exact[0]
        raise RuntimeError("multiple Library Manager objects found")
    return matches[0]


def _library_reference_matches(reference, requested_name):
    """Match a requested display/bare name without relying on one API spelling."""
    requested = _text(requested_name).strip().lower()
    if not requested:
        return False
    summary = _library_summary(reference)
    for value in summary.values():
        text = _text(value).strip().lower()
        if text == requested or text.startswith(requested + ","):
            return True
        if text.lstrip("#") == requested or text.lstrip("#").startswith(requested + ","):
            return True
    return False


def _library_reference_key(reference):
    """Return the exact native key accepted by SP11 remove_library."""
    summary = _library_summary(reference)
    for field in ("name", "display_name", "default_resolution"):
        value = _text(summary.get(field)).strip()
        if value and not value.startswith("#"):
            return value
    return _text(summary.get("display") or summary.get("name")).strip()


def _add_project_library(req):
    """Add one installed library reference through the project's Library Manager.

    This is deliberately project-scoped.  It does not install, remove, or
    modify global library repositories.
    """
    operation = "library.add"
    _require_current_disposable_project(req, operation)
    name = _text(req.get("name") or req.get("library")).strip()
    resolution = _text(req.get("resolution") or req.get("defaultResolution")).strip()
    if not name or not resolution:
        raise OperationError(
            "library.add requires name and exact installed resolution",
            "invalid_argument", {"name": name, "resolution": resolution},
        )
    installed = _installed_library_exact_matches(name, resolution)
    if not installed:
        raise OperationError(
            "exact installed library resolution was not found",
            "library_resolution_not_installed",
            {"name": name, "resolution": resolution},
        )
    manager = _find_project_library_manager()
    before = list(_get_member(manager, "references", "get_references", []))
    exact_before = [
        reference for reference in before
        if (_library_reference_matches(reference, name) and
            _library_exact_resolution_matches(reference, resolution))
    ]
    if len(exact_before) == 1:
        return {
            "added": False,
            "alreadyPresent": True,
            "name": name,
            "requestedResolution": resolution,
            "matchedReference": _library_summary(exact_before[0]),
            "exactReadback": True,
            "before": [_library_summary(reference) for reference in before],
            "after": [_library_summary(reference) for reference in before],
            "attempts": [],
            "claims": {"targetInstalled": True, "readback": True},
        }
    if len(exact_before) > 1:
        raise OperationError(
            "library.add found duplicate exact project references",
            "library_reference_ambiguous",
            {"name": name, "resolution": resolution,
             "matches": [_library_summary(item) for item in exact_before]},
        )
    conflicting = [
        _library_summary(reference) for reference in before
        if _library_reference_matches(reference, name)
    ]
    if conflicting:
        raise OperationError(
            "a different resolution of this project library is already present; "
            "use library.update",
            "library_resolution_conflict",
            {"name": name, "resolution": resolution,
             "existing": conflicting, "suggestedOperation": "library.update"},
        )
    add_value = _library_exact_resolution_value(installed[0], resolution)
    try:
        manager.add_library(add_value)
    except Exception as exc:
        raise OperationError(
            "native add_library failed for the exact installed resolution",
            "library_add_failed",
            {"name": name, "resolution": resolution,
             "addValue": add_value, "error": repr(exc)},
        )
    after = list(_get_member(manager, "references", "get_references", []))
    exact_after = [
        reference for reference in after
        if (_library_reference_matches(reference, name) and
            _library_exact_resolution_matches(reference, resolution))
    ]
    if len(exact_after) != 1:
        rollback = {"attempted": False, "ok": False}
        added_name_matches = [
            reference for reference in after
            if _library_reference_matches(reference, name)
        ]
        if added_name_matches:
            rollback["attempted"] = True
            try:
                manager.remove_library(
                    _library_reference_key(added_name_matches[0]))
                rollback["ok"] = True
            except Exception as exc:
                rollback["error"] = repr(exc)
        raise OperationError(
            "library.add did not retain exactly one requested resolution",
            "library_add_readback_mismatch",
            {"name": name, "resolution": resolution,
             "after": [_library_summary(reference) for reference in after],
             "rollback": rollback},
        )
    return {
        "added": True,
        "alreadyPresent": False,
        "name": name,
        "requestedResolution": resolution,
        "addValue": add_value,
        "matchedReference": _library_summary(exact_after[0]),
        "exactReadback": True,
        "before": [_library_summary(reference) for reference in before],
        "after": [_library_summary(reference) for reference in after],
        "saveRequired": True,
        "claims": {"targetInstalled": True, "readback": True},
    }


def _remove_project_library(req):
    """Remove one project library reference through the native manager."""
    operation = "library.remove"
    _require_current_disposable_project(req, operation)
    name = _text(req.get("name") or req.get("library")).strip()
    if not name:
        raise OperationError("library.remove requires name", "invalid_argument")
    if _text(req.get("confirm")).strip() != name:
        raise OperationError(
            "library.remove requires confirm equal to the exact library name",
            "confirmation_required", {"name": name},
        )
    manager = _find_project_library_manager()
    before = list(_get_member(manager, "references", "get_references", []))
    matching = [item for item in before if _library_reference_matches(item, name)]
    if not matching:
        return {"removed": False, "alreadyAbsent": True, "name": name,
                "before": [_library_summary(item) for item in before],
                "after": [_library_summary(item) for item in before],
                "absenceReadback": True, "targetState": "absent"}
    if len(matching) != 1:
        raise OperationError(
            "library.remove matched more than one project reference",
            "library_reference_ambiguous",
            {"name": name,
             "matches": [_library_summary(item) for item in matching]},
        )
    matching_summary = _library_summary(matching[0])
    if matching_summary.get("is_placeholder") or _text(matching_summary.get("name")).startswith("#"):
        raise OperationError(
            "placeholder libraries cannot be removed as ordinary project references; "
            "use library.placeholder.set_redirection or vendor.libversion.update",
            "placeholder_library_requires_redirection",
            {"name": name, "reference": matching_summary,
             "suggestedOperations": ["library.placeholder.set_redirection",
                                     "vendor.libversion.update"]},
        )
    attempts = []
    remove_key = _library_reference_key(matching[0])
    try:
        manager.remove_library(remove_key)
        attempts.append({"binding": "remove_library(exact_reference_key)",
                         "key": remove_key, "ok": True})
    except Exception as exc:
        attempts.append({"binding": "remove_library(name)", "ok": False,
                         "error": repr(exc)})
        raise OperationError("native remove_library failed", "library_remove_failed",
                         {"name": name, "removeKey": remove_key,
                          "attempts": attempts})
    after = list(_get_member(manager, "references", "get_references", []))
    if any(_library_reference_matches(item, name) for item in after):
        raise OperationError("library removal did not persist in native readback",
                             "library_remove_readback_mismatch",
                             {"name": name,
                              "after": [_library_summary(item) for item in after]})
    return {"removed": True, "alreadyAbsent": False, "name": name,
            "removedReference": matching_summary,
            "before": [_library_summary(item) for item in before],
            "after": [_library_summary(item) for item in after],
            "attempts": attempts, "absenceReadback": True,
            "targetState": "absent",
            "saveRequired": True}


def _update_project_library(req):
    """Replace one project library reference with an exact resolution."""
    operation = "library.update"
    _require_current_disposable_project(req, operation)
    name = _text(req.get("name") or req.get("library")).strip()
    resolution = _text(req.get("resolution") or req.get("version")).strip()
    if not name or not resolution:
        raise OperationError(
            "library.update requires name and exact resolution",
            "invalid_argument", {"name": name, "resolution": resolution},
        )
    if _text(req.get("confirm")).strip() != "update_project_library":
        raise OperationError(
            "library.update requires confirm=update_project_library",
            "confirmation_required", {"requiredConfirm": "update_project_library"},
        )
    manager = _find_project_library_manager()
    before_values = list(_get_member(manager, "references", "get_references", []))
    matches = [item for item in before_values if _library_reference_matches(item, name)]
    if not matches:
        raise OperationError("project library was not found: " + name,
                             "library_not_found", {"name": name})
    if len(matches) != 1:
        raise OperationError(
            "library.update matched more than one project reference",
            "library_reference_ambiguous",
            {"name": name,
             "matches": [_library_summary(item) for item in matches]},
        )
    before = [_library_summary(item) for item in before_values]
    matching_summary = _library_summary(matches[0])
    if matching_summary.get("is_placeholder") or _text(matching_summary.get("name")).startswith("#"):
        raise OperationError(
            "placeholder libraries cannot be updated with remove/add; use the "
            "vendor placeholder redirection flow",
            "placeholder_library_requires_redirection",
            {"name": name, "reference": matching_summary,
             "suggestedOperations": ["library.placeholder.set_redirection",
                                     "vendor.libversion.update"]},
        )
    # Resolve one exact installed identity before removing the current
    # reference. A failed exact add must never fall back to a bare library
    # name because that can silently select a different installed version.
    installed_values = _installed_library_exact_matches(name, resolution)
    installed = [_library_summary(item) for item in installed_values]
    if not installed:
        raise OperationError(
            "exact installed library resolution was not found",
            "library_resolution_not_installed",
            {"name": name, "resolution": resolution},
        )
    if _library_exact_resolution_matches(matches[0], resolution):
        return {
            "updated": False,
            "alreadyCurrent": True,
            "name": name,
            "resolution": resolution,
            "before": before,
            "after": before,
            "matchedReference": matching_summary,
            "installedMatches": installed,
            "exactReadback": True,
            "saveRequired": False,
            "claims": {"exactResolution": True,
                       "targetInstalled": True,
                       "nativeRemoveAdd": False,
                       "readback": True, "saved": False,
                       "freshProcessPersistence": False},
        }
    remove_key = _library_reference_key(matches[0])
    try:
        manager.remove_library(remove_key)
    except Exception as exc:
        raise OperationError("native remove_library failed during update",
                             "library_update_remove_failed",
                             {"error": repr(exc), "removeKey": remove_key})
    add_value = _library_exact_resolution_value(
        installed_values[0], resolution
    )
    add_attempts = []
    try:
        manager.add_library(add_value)
    except Exception as exc:
        add_attempts.append({"value": add_value, "error": repr(exc)})
        restored = False
        restore_error = None
        try:
            manager.add_library(remove_key)
            restored = True
        except Exception as exc:
            restore_error = repr(exc)
        raise OperationError("native add_library failed during update",
                             "library_update_add_failed",
                             {"error": add_attempts, "attempts": add_attempts,
                              "restoredOriginal": restored,
                              "restoreError": restore_error,
                              "removeKey": remove_key})
    after_values = list(_get_member(manager, "references", "get_references", []))
    after = [_library_summary(item) for item in after_values]
    retained = [
        item for item in after_values
        if (_library_reference_matches(item, name) and
            _library_exact_resolution_matches(item, resolution))
    ]
    if len(retained) != 1:
        rollback = {"attempted": True, "removedRequested": False,
                    "restoredOriginal": False}
        try:
            for item in after_values:
                if _library_reference_matches(item, name):
                    manager.remove_library(_library_reference_key(item))
            rollback["removedRequested"] = True
            manager.add_library(remove_key)
            rollback["restoredOriginal"] = True
        except Exception as exc:
            rollback["error"] = repr(exc)
        raise OperationError("updated library was not retained in native readback",
                             "library_update_readback_mismatch",
                             {"name": name, "resolution": resolution,
                              "after": after, "rollback": rollback})
    return {"updated": True, "name": name, "resolution": resolution,
            "before": before, "after": after, "installedMatches": installed,
            "removeKey": remove_key, "addValue": add_value,
            "matchedReference": _library_summary(retained[0]),
            "exactReadback": True,
            "saveRequired": True, "claims": {"exactResolution": True,
            "targetInstalled": True,
            "nativeRemoveAdd": True, "addAttempts": add_attempts,
            "readback": True, "saved": False,
            "freshProcessPersistence": False}}


def _placeholder_state_entries(manager):
    """Read placeholder lib man items and their stored identity fields."""
    entries = []
    values = _get_member(manager, "references", "get_references", [])
    for value in list(values):
        name = _text(_get_member(value, "name", "get_name", ""))
        placeholder_name = _get_member(
            value, "placeholder_name", "get_placeholder_name"
        )
        if placeholder_name is None and not name.startswith("#"):
            continue
        entry = {}
        for field in (
            "name", "placeholder_name", "default_resolution",
            "resolver_guid", "resolution_info", "resolution_not_required",
            "redirected_resolution", "is_system_library", "is_optional",
        ):
            item = _get_member(value, field, "get_" + field)
            if item is not None:
                entry[field] = _json_safe(item)
        effective = _get_member(
            value, "effective_resolution", "get_effective_resolution"
        )
        if effective is not None:
            entry["effective_resolution"] = _library_summary(effective)
        entries.append(entry)
    return entries


def library_diagnose(req=None):
    """Diagnose project library references without changing the project.

    This combines the live Library Manager reference list, placeholder
    redirections, and currently published native diagnostics.  It does not
    trigger a build or attempt installation/resolution; callers must use the
    separate guarded tools for those mutations.
    """
    del req
    if project is None:
        raise OperationError(
            "library.diagnose requires an open project",
            "project_required",
            {"next": "project.open or project.create_with_cpu"},
        )
    manager = _find_project_library_manager()
    references = list(_get_member(manager, "references", "get_references", []))
    entries = [_library_summary(value) for value in references]
    placeholders = _placeholder_state_entries(manager)
    unresolved = []
    for item in placeholders:
        name = _text(item.get("placeholder_name") or item.get("name"))
        effective = item.get("effective_resolution")
        redirected = item.get("redirected_resolution")
        if not effective and not redirected:
            unresolved.append({"name": name, "reason": "no_effective_resolution"})
    api, api_kind, probes = _placeholder_redirection_api(manager, False)
    redirections = {}
    if api is not None:
        for item in placeholders:
            name = _text(item.get("placeholder_name") or item.get("name"))
            if not name:
                continue
            try:
                redirections[name] = _text(api.get_redirected_placeholder_resolution(name))
            except Exception as exc:
                redirections[name] = {"error": repr(exc)}
    diagnostics = collect_messages()
    library_messages = []
    for message in diagnostics.get("messages", []):
        text_value = _text(message.get("text", ""))
        lowered = text_value.lower()
        if ("library" in lowered or "库" in text_value or
                "placeholder" in lowered or "占位" in text_value):
            library_messages.append(message)
    status = "blocked" if unresolved or library_messages else "clean"
    return {
        "status": status,
        "manager": _object_name(manager),
        "referenceCount": len(entries),
        "references": entries,
        "placeholderCount": len(placeholders),
        "placeholders": placeholders,
        "unresolvedPlaceholders": unresolved,
        "redirections": redirections,
        "redirectionApi": api_kind,
        "redirectionBindingProbes": probes,
        "diagnostics": library_messages,
        "diagnosticCollectionComplete": diagnostics.get("collectionComplete", False),
        "claims": {
            "readOnly": True,
            "buildTriggered": False,
            "installationAttempted": False,
            "resolutionAttempted": False,
            "cleanMeansNoObservedLibraryIssue": True,
        },
    }


class _ClrRedirectionAdapter(object):
    """Uniform accessor for a CLR IPlaceholderRedirection instance."""

    def __init__(self, target, get_method, set_method):
        self._target = target
        self._get = get_method
        self._set = set_method

    @staticmethod
    def _args(values):
        import System
        return System.Array[System.Object](list(values))

    def get_redirected_placeholder_resolution(self, name):
        return self._get.Invoke(self._target, self._args([name]))

    def set_redirected_placeholder_resolution(self, name, resolution):
        return self._set.Invoke(self._target, self._args([name, resolution]))


def _placeholder_redirection_api(manager, for_write=False):
    """Locate the vendor placeholder redirection accessor on the LibManObject.

    Tries, in order: snake_case Python dispatch, PascalCase Python dispatch,
    the PlaceholderRedirection property object, and finally .NET reflection
    against the underlying CLR LibManObject through SystemInstances.ObjectMgr.
    When for_write is True the CLR route acquires the object for modification
    and attaches a commit() call that pairs SetObject with the modify lock.
    """
    probes = []
    for get_name, set_name in (
        ("get_redirected_placeholder_resolution",
         "set_redirected_placeholder_resolution"),
        ("GetRedirectedPlaceholderResolution",
         "SetRedirectedPlaceholderResolution"),
    ):
        direct_get = getattr(manager, get_name, None)
        direct_set = getattr(manager, set_name, None)
        probes.append({
            "kind": "direct", "get": get_name, "set": set_name,
            "available": direct_get is not None and direct_set is not None,
        })
        if direct_get is not None and direct_set is not None:
            return manager, "direct", probes
    redir = _get_member(
        manager, "placeholder_redirection", "get_placeholder_redirection"
    )
    if redir is None:
        redir = _get_member(manager, "PlaceholderRedirection")
    if redir is not None:
        for get_name, set_name in (
            ("get_redirected_placeholder_resolution",
             "set_redirected_placeholder_resolution"),
            ("GetRedirectedPlaceholderResolution",
             "SetRedirectedPlaceholderResolution"),
        ):
            redir_get = getattr(redir, get_name, None)
            redir_set = getattr(redir, set_name, None)
            probes.append({
                "kind": "placeholder_redirection", "get": get_name,
                "set": set_name,
                "available": redir_get is not None and redir_set is not None,
            })
            if redir_get is not None and redir_set is not None:
                return redir, "placeholder_redirection", probes
    try:
        import System
        flags = (System.Reflection.BindingFlags.Instance |
                 System.Reflection.BindingFlags.Public)
        manager_type = manager.GetType()
        property_info = manager_type.GetProperty("PlaceholderRedirection", flags)
        probes.append({
            "kind": "clr_reflection", "managerType": _text(manager_type.FullName),
            "propertyFound": property_info is not None,
        })
        if property_info is not None:
            clr_redir = property_info.GetValue(manager, None)
            if clr_redir is not None:
                get_method = clr_redir.GetType().GetMethod(
                    "GetRedirectedPlaceholderResolution"
                )
                set_method = clr_redir.GetType().GetMethod(
                    "SetRedirectedPlaceholderResolution"
                )
                probes.append({
                    "kind": "clr_reflection",
                    "redirType": _text(clr_redir.GetType().FullName),
                    "getMethodFound": get_method is not None,
                    "setMethodFound": set_method is not None,
                })
                if get_method is not None and set_method is not None:
                    adapter = _ClrRedirectionAdapter(
                        clr_redir, get_method, set_method
                    )
                    return adapter, "clr_reflection", probes
    except Exception as exc:
        probes.append({"kind": "clr_reflection", "error": repr(exc)})
    # Strategy 4: reach the real CLR LibManObject through
    # SystemInstances.ObjectMgr using the project handle and the manager GUID.
    try:
        import System
        manager_guid = _get_member(manager, "guid", "get_guid")
        if not manager_guid:
            raise RuntimeError("library manager guid is unavailable")
        handle = None
        if native_core_project is not None:
            try:
                handle = int(native_core_project.Handle)
            except Exception:
                handle = None
        if handle is None:
            handle = _get_member(project, "handle", "get_handle")
        if handle is None:
            handle = _get_member(project, "Handle", "get_Handle")
        if handle is None:
            raise RuntimeError("project handle is unavailable")
        system_instances = _reflection_type(
            "_3S.CoDeSys.Core.SystemInstances, Core"
        )
        if system_instances is None:
            raise RuntimeError("SystemInstances type is unavailable")
        object_mgr = system_instances.GetProperty("ObjectMgr").GetValue(None, None)
        if object_mgr is None:
            raise RuntimeError("SystemInstances.ObjectMgr is null")
        guid = System.Guid(_text(manager_guid))
        if for_write:
            meta = object_mgr.GetObjectToModify(int(handle), guid)
        else:
            meta = object_mgr.GetObjectToRead(int(handle), guid)
        if meta is None:
            raise RuntimeError("CLR LibManObject meta is unavailable")
        clr_libman = meta.Object
        redir_prop = clr_libman.GetType().GetProperty("PlaceholderRedirection")
        if redir_prop is None:
            raise RuntimeError("CLR PlaceholderRedirection property missing")
        redir = redir_prop.GetValue(clr_libman, None)
        get_method = redir.GetType().GetMethod(
            "GetRedirectedPlaceholderResolution"
        )
        set_method = redir.GetType().GetMethod(
            "SetRedirectedPlaceholderResolution"
        )
        if get_method is None or set_method is None:
            raise RuntimeError("CLR redirection methods missing")
        adapter = _ClrRedirectionAdapter(redir, get_method, set_method)

        if for_write:

            def commit():
                return object_mgr.SetObject(meta, True, None)

            adapter.commit = commit
        probes.append({
            "kind": "clr_object_mgr",
            "managerType": _text(clr_libman.GetType().FullName),
            "projectHandle": int(handle),
            "managerGuid": _text(manager_guid),
            "access": "modify" if for_write else "read",
            "getMethodFound": True,
            "setMethodFound": True,
        })
        return adapter, "clr_object_mgr", probes
    except Exception as exc:
        probes.append({"kind": "clr_object_mgr", "error": repr(exc)})
    return None, "none", probes


def _restore_placeholder_redirection(api, name, before):
    """Best-effort same-object rollback after crossing the setter boundary."""
    result = {"attempted": True, "before": before, "restored": False}
    try:
        api.set_redirected_placeholder_resolution(name, before)
        commit_fn = getattr(api, "commit", None)
        if commit_fn is not None:
            commit_fn()
            result["commitCalled"] = True
        else:
            result["commitCalled"] = False
        after = _text(api.get_redirected_placeholder_resolution(name))
        result["after"] = after
        result["restored"] = (
            _normalized_library_identity(after) ==
            _normalized_library_identity(before)
        )
    except Exception as exc:
        result["error"] = repr(exc)
    result["processDiscardRequired"] = not result["restored"]
    return result


LEGACY_OPS = {
    "ping": "bridge.ping",
    "status": "bridge.status",
    "create-project": "project.create",
    "open-project": "project.open",
    "create-pou": "pou.create",
    "write-st": "pou.set_text",
    "read-st": "pou.get",
    "list-textual": "pou.list",
    "build": "build.compile",
    "read-diagnostics": "build.diagnostics",
    "save": "project.save",
    "close": "project.close",
    "exit": "bridge.stop",
}


def _normalize_request(req):
    """Accept the old flat validation shape and the stable v1 op/args shape."""
    legacy = req.get("cmd")
    operation = req.get("op") or LEGACY_OPS.get(legacy) or legacy
    args = req.get("args")
    if not isinstance(args, dict):
        args = {}
    merged = dict(req)
    merged.update(args)
    # The transport request ID is not an operation argument. Keeping it here
    # makes operations with a legitimate `id` field (notably device selectors)
    # silently consume the request UUID when the caller omitted that argument.
    if "id" not in args:
        merged.pop("id", None)
    merged["_legacyCmd"] = legacy
    merged["op"] = operation
    return operation, merged


def _project_path():
    if project is None:
        return None
    return _text(_get_member(project, "path", "get_path", "")) or None


def _vendor_project_load_state():
    """Read Inovance ObjectMgr lazy-load completion without pumping UI events."""
    if project is None:
        return {
            "available": True,
            "finished": True,
            "objectsRemaining": 0,
            "projectHandle": None,
            "reason": "no_project_open",
        }
    handle = None
    if native_core_project is not None:
        handle = _get_member(native_core_project, "Handle", "get_Handle")
    if handle is None:
        handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(project, "Handle", "get_Handle")
    if handle is None:
        return {
            "available": False,
            "finished": False,
            "objectsRemaining": None,
            "projectHandle": None,
            "error": "project handle is unavailable",
        }
    object_mgr, probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        return {
            "available": False,
            "finished": False,
            "objectsRemaining": None,
            "projectHandle": int(handle),
            "error": "SystemInstances.ObjectMgr is unavailable",
            "bindingProbe": probe,
        }
    try:
        import System
        methods = [
            method for method in object_mgr.GetType().GetMethods()
            if method.Name == "IsLoadProjectFinished" and
            len(method.GetParameters()) == 2
        ]
        if len(methods) != 1:
            raise RuntimeError(
                "IsLoadProjectFinished overload count is %d" % len(methods)
            )
        args = System.Array[System.Object]([
            System.Int32(int(handle)), System.Int32(0)
        ])
        finished = bool(methods[0].Invoke(object_mgr, args))
        return {
            "available": True,
            "finished": finished,
            "objectsRemaining": int(args[1]),
            "projectHandle": int(handle),
            "binding": "ObjectMgr.IsLoadProjectFinished(Int32, out Int32)",
        }
    except Exception as exc:
        return {
            "available": False,
            "finished": False,
            "objectsRemaining": None,
            "projectHandle": int(handle),
            "error": repr(exc),
        }


_PROJECT_CLOSE_STALL = {"signature": None, "firstSeenAt": None, "samples": 0}


def _project_close_stall_evidence(load_state):
    """Decide whether the vendor lazy-load gate is stalled rather than slow.

    Measured on this machine (2026-09-19): InoProShop's ObjectMgr never clears
    IsLoadProjectFinished — a wizard-created project sits at objectsRemaining=62
    and a project left behind by a forced IDE kill at 63, both unchanged across
    a minute of polling, while the vanilla line reports finished=True / 0 on the
    same call. The deferral below therefore never converts into a close on the
    InoProShop line, and the old recovery text ("retry project.close after
    project.status reports finished=true") sent the caller into a loop it could
    never leave. A non-advancing signature is escalated to a terminal boundary
    instead; a genuinely loading project keeps returning the retryable error.
    """
    now = time.time()
    signature = (load_state.get("projectHandle"),
                 load_state.get("objectsRemaining"))
    state = globals().get("_PROJECT_CLOSE_STALL")
    if not isinstance(state, dict) or state.get("signature") != signature:
        state = {"signature": signature, "firstSeenAt": now, "samples": 1}
    else:
        state["samples"] = int(state.get("samples") or 0) + 1
    globals()["_PROJECT_CLOSE_STALL"] = state
    observed = max(0.0, now - (state.get("firstSeenAt") or now))
    return {
        "signature": list(signature) if isinstance(signature, tuple) else signature,
        "samples": state["samples"],
        "observedSeconds": round(observed, 3),
        "stalled": bool(state["samples"] >= 3 and observed >= 3.0)
        or observed >= 20.0,
    }


def _close_project_after_vendor_load():
    """Close only after vendor lazy-load callbacks have completed.

    InoProShop continues Project.LazyLoadNextObject on the UI idle loop after
    ScriptEngine's projects.open returns. Closing the project while objects
    remain lets SoftMotion's ProjectLoadFinished callback access a stale
    project handle and terminates the IDE. Fail fast so the caller can poll
    project.status and retry without blocking the primary thread.
    """
    global project, native_core_project
    if project is None:
        return {"closed": True, "alreadyClosed": True,
                "vendorLoadState": _vendor_project_load_state()}
    load_state = _vendor_project_load_state()
    if not load_state.get("available"):
        raise OperationError(
            "cannot prove vendor background project loading has completed",
            "project_close_load_state_unavailable",
            {
                "projectPath": _project_path(),
                "vendorLoadState": load_state,
                "mutatedProject": False,
                "recovery": "poll project.status; do not close or switch projects",
            },
        )
    if not load_state.get("finished"):
        stall = _project_close_stall_evidence(load_state)
        if stall.get("stalled"):
            raise OperationError(
                "vendor background project loading has not advanced, so this "
                "IDE session cannot close the project; close the IDE and let "
                "the route start a fresh one",
                "project_close_blocked_by_stalled_vendor_load",
                {
                    "projectPath": _project_path(),
                    "vendorLoadState": load_state,
                    "stall": stall,
                    "mutatedProject": False,
                    "next": {
                        "tool": "codesys_ide_close",
                        "arguments": {"confirm": "close_ide"},
                        "then": "re-run the project operation you actually need "
                                "(project.open / project.prepare_vendor_project); "
                                "the route starts a fresh IDE on demand",
                        "doNot": "do not keep retrying project.close",
                    },
                },
            )
        raise OperationError(
            "vendor background project loading is still active; retry project.close after project.status reports finished=true",
            "project_close_deferred",
            {
                "projectPath": _project_path(),
                "vendorLoadState": load_state,
                "retryAfterMs": 250,
                "mutatedProject": False,
                "next": {
                    "tool": "codesys_project_status",
                    "then": "retry project.close at most twice; if the vendor "
                            "load state still has not advanced the bridge answers "
                            "project_close_blocked_by_stalled_vendor_load, and "
                            "codesys_ide_close (confirm=close_ide) is the way out",
                },
            },
        )
    closed_path = _project_path()
    project.close()
    project = None
    native_core_project = None
    pou_cache.clear()
    return {
        "closed": True,
        "projectPath": closed_path,
        "vendorLoadState": load_state,
    }


def project_status():
    return {
        "ready": True,
        "protocolVersion": PROTOCOL_VERSION,
        "bridgePid": os.getpid() if hasattr(os, "getpid") else None,
        "bridgeSource": _bridge_source_info(),
        "bridgeMode": BRIDGE_MODE,
        "bridgePaused": bridge_paused,
        "abortHandling": abort_handling_status,
        "python": sys.version.split("\n")[0],
        "uiPresent": bool(getattr(system, "ui_present", False)),
        "projectOpen": project is not None,
        "projectPath": _project_path(),
        "dirty": bool(_get_member(project, "dirty", "get_dirty", False)) if project else False,
        "primary": bool(_get_member(project, "primary", "get_primary", False)) if project else False,
        "library": bool(_get_member(project, "library", "get_library", False)) if project else False,
        "promptHandling": prompt_handling_status,
        "vendorLoadState": _vendor_project_load_state(),
    }


def _write_pou_request(req):
    _require_project()
    name = req.get("name") or req.get("pou") or req.get("target")
    if not name:
        raise RuntimeError("missing POU name")
    if req.get("code") is not None or req.get("st") is not None:
        raise RuntimeError(
            "legacy code/st field is unsafe; provide declaration and implementation separately"
        )
    declaration = req.get("declaration")
    implementation = req.get("implementation")
    if declaration is None and implementation is None:
        raise RuntimeError("provide declaration and/or implementation")
    vendor_created = _vendor_st_create_if_needed(req)
    if vendor_created is not None:
        return vendor_created
    pou = find_textual_object(name)
    created = False
    if pou is None:
        if not bool(req.get("createIfMissing", True)):
            raise RuntimeError("textual object not found: " + name)
        pou, created = get_or_create_pou(
            name, req.get("kind", "program"), True, req.get("language", "st"),
            return_type=req.get("returnType") or req.get("return_type"),
            base_type=req.get("baseType") or req.get("base_type"),
            interfaces=req.get("interfaces"),
            parent=req.get("parent"),
        )
    write_result = {"name": _object_name(pou), "created": created}
    if declaration is not None:
        write_result["declaration"] = _write_document(
            _get_member(pou, "textual_declaration", "get_textual_declaration"),
            declaration,
            "declaration",
        )
    if implementation is not None:
        write_result["implementation"] = _write_document(
            _get_member(pou, "textual_implementation", "get_textual_implementation"),
            implementation,
            "implementation",
        )
    write_result["readback"] = read_st(pou)
    # E2E V2 R042: gvl.create resolves its tree path (R030) but pou.upsert did
    # not — the model had to reverse-engineer the deletion target from
    # project.tree every round. Mirror the gvl.create resolution (best effort).
    try:
        _found, found_path = find_project_object(_object_name(pou))
        if found_path:
            write_result["path"] = found_path
    except Exception:
        pass
    return write_result


def _prepare_vendor_language_model_for_build():
    """Finish InoProShop's lazy project load before invoking ScriptEngine.

    The vendor Build command calls ``ObjectMgr.FinishLoadProject(handle)``
    before ``LanguageModelMgr.Compile``.  ``projects.open`` can return while
    dozens of objects are still loading, so mirror that initialization inside
    the single public build request instead of asking the caller to poll and
    retry.
    """
    before = _vendor_project_load_state()
    if not before.get("available") or before.get("projectHandle") is None:
        raise OperationError(
            "cannot initialize InoProShop's language model before build",
            "build_initialization_unavailable",
            {"vendorLoadState": before, "mutatedProject": False},
        )
    object_mgr, probe = _system_instances_property("ObjectMgr")
    if object_mgr is None:
        raise OperationError(
            "SystemInstances.ObjectMgr is unavailable for build initialization",
            "build_initialization_unavailable",
            {"vendorLoadState": before, "bindingProbe": probe,
             "mutatedProject": False},
        )
    try:
        import System
        methods = []
        for method in object_mgr.GetType().GetMethods():
            if method.Name != "FinishLoadProject":
                continue
            parameters = method.GetParameters()
            if (len(parameters) == 1 and
                    _text(parameters[0].ParameterType.FullName) == "System.Int32"):
                methods.append(method)
        if len(methods) != 1:
            raise RuntimeError(
                "FinishLoadProject(Int32) overload count is %d" % len(methods)
            )
        methods[0].Invoke(
            object_mgr,
            System.Array[System.Object]([
                System.Int32(int(before["projectHandle"]))
            ]),
        )
    except Exception as exc:
        raise OperationError(
            "InoProShop failed to finish project loading before build",
            "build_initialization_failed",
            {"vendorLoadState": before, "bindingProbe": probe,
             "error": repr(exc), "mutatedProject": False},
        )
    after = _vendor_project_load_state()
    if not after.get("available") or not after.get("finished"):
        raise OperationError(
            "InoProShop project loading is incomplete after FinishLoadProject",
            "build_initialization_incomplete",
            {"before": before, "after": after, "mutatedProject": False},
        )
    return {
        "binding": "ObjectMgr.FinishLoadProject(Int32)",
        "before": before,
        "after": after,
    }


def _build_project(precompile_timeline=None, secondary_verification=False):
    _require_project()
    initialization = _prepare_vendor_language_model_for_build()
    app, application_binding = _resolve_active_application()
    if app is None:
        raise OperationError("no buildable application is available",
                             "application_unavailable", application_binding)
    # Capture the last pre-clear state for native LAD transactions.  Some
    # parser diagnostics are published under the build category and would be
    # destroyed by the required build-message clear below.
    if precompile_timeline is not None:
        precompile_timeline.append(
            _diagnostic_stage_snapshot("before_build_clear"))
    # Preserve the parser category.  The application build emits progress and
    # compile diagnostics, but does not reliably re-publish editor/precompile
    # errors after they were cleared.  They must remain visible to this build
    # result so a red editor diagnostic cannot be downgraded to 0/0.
    cleared = clear_messages(exclude_categories=(PRECOMPILE_CATEGORY,))
    app.build()
    summary = _wait_for_stable_diagnostics()
    if secondary_verification:
        # Keep a second independent observation window after Application.build
        # returns.  Vendor precompile/library diagnostics can be published
        # after the first quiet period and otherwise produce false-green LAD.
        verification = _wait_for_stable_diagnostics(
            minimum_observation_ms=max(3000, DIAGNOSTIC_MIN_OBSERVATION_MS),
            quiet_period_ms=DIAGNOSTIC_QUIET_PERIOD_MS,
            timeout_ms=max(8000, DIAGNOSTIC_TIMEOUT_MS))
        _merge_post_build_diagnostic_verification(summary, verification)
    if precompile_timeline is not None:
        _apply_precompile_timeline(summary, precompile_timeline)
    # ``compile_summary`` is also used by read-only diagnostic replay tests,
    # where an empty post-build direct query is useful evidence.  A real build
    # must be stricter: if the installed precompile category was inactive and
    # no positioned/parser messages were observed, record an explicit gap so
    # callers cannot promote a false 0/0 result after a process restart.
    # E2E V2 R052b: SP11's structured API rejects the inactive precompile
    # category, so on InoProShop the ONLY channel that can observe it is the
    # guarded direct query after a real build — which the diagnostic snapshot
    # above already documents as positive evidence of a clean parser pass
    # (installed + query complete + count 0).  Without this exemption every
    # InoProShop build reported "offline build failed" while its own
    # diagnostics were 0/0, i.e. the conservative rule fired on exactly the
    # evidence the snapshot calls sufficient.  The exemption stays narrow: it
    # demands the guarded direct-query evidence source AND a clean, complete,
    # stable build window, so an unguarded/replayed empty result still fails
    # closed below and in _compile_gate_passed.
    direct_query_clean = (
        summary.get("precompileEvidenceSource") ==
        "post_build_direct_category_query" and
        summary.get("precompileCategoryQueried") is True and
        summary.get("precompileCategoryInstalled") is True and
        int(summary.get("precompileErrorCount", -1) or 0) == 0 and
        int(summary.get("precompileWarningCount", -1) or 0) == 0 and
        int(summary.get("precompileUnknownSeverityCount", -1) or 0) == 0 and
        summary.get("compileStatus") == "success" and
        int(summary.get("errorCount", -1) or 0) == 0 and
        int(summary.get("unknownSeverityCount", -1) or 0) == 0 and
        summary.get("diagnosticsComplete") is True and
        summary.get("diagnosticsStable") is True
    )
    # MEASURED 2026-09-19: a project that is genuinely clean apart from
    # positioned compiler WARNINGS ("No POU defined for task 'TaskProbe'" left
    # by an earlier probe round) publishes those warnings through the build
    # category WITH source positions.  The inference branch then labels the
    # whole window "structured_position_inference", which the narrow exemption
    # above did not accept, so ANY project carrying a single positioned warning
    # could never be certified - not even with 0 errors, an installed and fully
    # queried precompile category and a clean direct query.  Accept that case
    # only while the inference contributed NO error and NO unknown-severity
    # message: a positioned ERROR keeps failing closed through
    # errors_present / precompile_errors_present, and the warning counts stay in
    # the receipt so the caller still sees exactly what was reported.
    positioned_warnings_only_clean = (
        summary.get("precompileEvidenceSource") ==
        "structured_position_inference" and
        int(summary.get("precompileErrorCount", -1) or 0) == 0 and
        int(summary.get("precompileUnknownSeverityCount", -1) or 0) == 0 and
        int(summary.get("errorCount", -1) or 0) == 0 and
        int(summary.get("unknownSeverityCount", -1) or 0) == 0 and
        summary.get("precompileCategoryQueried") is True and
        summary.get("precompileCategoryInstalled") is True and
        summary.get("compileStatus") == "success" and
        summary.get("diagnosticsComplete") is True and
        summary.get("diagnosticsStable") is True
    )
    if positioned_warnings_only_clean and not direct_query_clean:
        summary["precompileEvidenceSource"] = (
            "structured_position_inference_warnings_only")
        direct_query_clean = True
    if (summary.get("precompileCategoryActive") is False and
            not (summary.get("precompileMessages") or
                 (summary.get("diagnosticHistory") or {}).get("messages")) and
            not summary.get("postBuildVerificationPassed") and
            not direct_query_clean):
        if "precompile_category_not_observed" not in summary.get("diagnosticGaps", []):
            summary.setdefault("diagnosticGaps", []).append(
                "precompile_category_not_observed")
        summary["compileOk"] = False
        summary["precompileOk"] = False
        if summary.get("precompileStatus") == "success":
            summary["precompileStatus"] = "unknown"
    elif direct_query_clean and not summary.get("postBuildVerificationPassed"):
        summary["diagnosticGaps"] = [gap for gap in summary.get("diagnosticGaps", [])
                                     if gap != "precompile_category_not_observed"]
        summary["precompileStatus"] = "success"
        summary["precompileOk"] = True
        summary["precompileCategoryObserved"] = True
        summary["precompileEvidenceSource"] = \
            "post_build_direct_category_query_clean"
        summary["compileOk"] = not summary.get("diagnosticGaps")
    # Re-assert the effective result after timeline/history normalization.
    # The independent post-build window is the vendor compiler's delayed
    # result and is allowed to prove a clean build when the category is
    # inactive on an otherwise clean project.
    if summary.get("postBuildVerificationPassed") is True:
        verification = summary.get("postBuildVerification") or {}
        if (verification.get("compileStatus") == "success" and
                int(verification.get("errorCount", 0) or 0) == 0 and
                int(verification.get("warningCount", 0) or 0) == 0 and
                int(verification.get("precompileErrorCount", 0) or 0) == 0 and
                int(verification.get("precompileWarningCount", 0) or 0) == 0 and
                verification.get("diagnosticsComplete") is True and
                verification.get("diagnosticsStable") is True):
            summary["diagnosticGaps"] = [gap for gap in summary.get("diagnosticGaps", [])
                                          if gap != "precompile_category_not_observed"]
            summary["compileStatus"] = "success"
            summary["compileOk"] = True
            summary["precompileStatus"] = "success"
            summary["precompileOk"] = True
            summary["precompileCategoryObserved"] = True
            summary["precompileCategoryActive"] = True
            summary["precompileEvidenceSource"] = "post_build_verification_window"
    summary["clearMessages"] = cleared
    summary["applicationBinding"] = application_binding
    summary["buildInitialization"] = initialization
    return summary


def _hashes_match(actual, expected):
    return (
        actual.get("declarationSha256") == expected.get("declarationSha256") and
        actual.get("implementationSha256") == expected.get("implementationSha256")
    )


def _source_items(req):
    items = req.get("pous")
    if items is None:
        items = req.get("sources")
    if items is None and req.get("name"):
        items = [req]
    if not isinstance(items, list) or not items:
        raise RuntimeError("source.import requires a non-empty pous array")
    return items


# ---------------------------------------------------------------------------
# E2E V2 R048: CODESYS runtime-verification (simulation) family.
#
# Design mirrors the TIA PLCSIM family that already ships for the Siemens line
# (tia_plcsim_plan phase gate / tia_plcsim_standard_* lifecycle /
# tia_plcsim_assert_behavior scenario): a read-only status gate, an explicit
# simulation switch with readback, an online lifecycle with proofs, batch
# read/write with force hygiene, and ONE ordered assertion scenario whose
# verdict is what the program really computed at runtime.
#
# Machine-verified basis (2026-09-10, vanilla CODESYS V3.5 SP22 Patch 3,
# ScriptEngine 4.2, independent headless instance; script and log in
# D:\codesys-mcp-external\_sim_test\sim_stimulus.py / stim_result.txt):
#   dev.get_simulation_mode()/set_simulation_mode(True) -> True, save()
#   se.online.create_online_application(app).login(se.OnlineChangeOption.Try, True)
#   oapp.start() -> application_state == "run"; oapp.is_logged_in == True
#   oapp.read_value("PLC_PRG.bMotor") -> "BOOL#TRUE"  (type prefix must be stripped)
#   oapp.set_prepared_value(expr, value) + oapp.write_prepared_values()
#   oapp.force_prepared_values() / get_forced_expressions() / unforce_all_values()
#   A stimulus->response suite scored 9 PASS / 0 FAIL on correct logic and
#   2 FAIL after injecting two bugs (no latch / no hysteresis) => it discriminates.
#   Writing an expression that is currently FORCED raises StandardError
#   ('应用程序中的错误。'), so every write pre-checks the forced list instead.
#   SP22 caveat: getattr(se.OnlineChangeOption, "Try") is None — access the
#   attribute directly.
# ---------------------------------------------------------------------------

_SIM_SESSION = {"online": None, "appGuid": None, "appPath": None}
_SIM_COMPARE_ALIASES = {
    "==": "eq", "!=": "ne", ">": "gt", ">=": "ge", "<": "lt", "<=": "le",
}


def _sim_scriptengine():
    active = globals().get("_ACTIVE_SCRIPTENGINE")
    if active is not None:
        return active
    try:
        import scriptengine as se
        return se
    except Exception as exc:
        raise OperationError(
            "CODESYS runtime verification is unavailable in this host: the "
            "scriptengine module could not be imported (%s)" % _text(exc),
            "sim_unavailable",
            {"mutatedProject": False},
        )


def _sim_application_object():
    se = _sim_scriptengine()
    _require_project()
    path = _application_tree_path()
    if not path:
        raise OperationError(
            "the open project has no Application node",
            "sim_unavailable",
            {"mutatedProject": False},
        )
    # E2E V2 R048: create_online_application() must receive an object from the
    # SCRIPTENGINE project tree — the same binding the machine-verified reference
    # script uses. Objects reached through the bridge's own wrapped `project`
    # (and through find_project_object) made it fail with "堆栈为空。"
    # (stack is empty), so prefer se.projects.primary and keep the wrapped
    # project only as a fallback.
    candidates = []
    try:
        primary = se.projects.primary
        if primary is not None:
            candidates.append(primary)
    except Exception:
        pass
    if project is not None:
        candidates.append(project)
    for candidate in candidates:
        try:
            for obj in candidate.get_children(True):
                if getattr(obj, "is_application", False):
                    return obj, _text(path)
        except Exception:
            continue
    found, found_path = find_project_object(path)
    if found is None:
        raise OperationError(
            "the Application object could not be resolved: " + _text(path),
            "sim_unavailable",
            {"applicationPath": path, "mutatedProject": False},
        )
    return found, _text(found_path or path)


def _sim_device_object():
    _require_project()
    path = _application_tree_path() or ""
    device_name = path.split("/")[0].strip()
    if device_name:
        found, found_path = find_project_object(device_name)
        if found is not None:
            return found, _text(found_path or device_name)
    for obj in _children(project):
        try:
            if getattr(obj, "is_device", False):
                return obj, _object_name(obj)
        except Exception:
            continue
    raise OperationError(
        "the open project has no device object to switch simulation on",
        "sim_unavailable",
        {"mutatedProject": False},
    )


def _sim_norm(value):
    text = _text(value)
    if "#" in text:
        text = text.split("#", 1)[1]
    return text.strip()


def _sim_scalar(text):
    """Return (value, kind) where kind is bool|number|text."""
    raw = _text(text).strip()
    low = raw.lower()
    if low in ("true", "false"):
        return (low == "true"), "bool"
    try:
        return float(raw), "number"
    except Exception:
        return raw, "text"


def _sim_value_text(value):
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, float):
        return repr(value)
    return _text(value)


def _sim_delay(se, ms):
    ms = max(0, int(ms))
    if ms <= 0:
        return
    try:
        se.system.delay(ms)
    except Exception:
        time.sleep(ms / 1000.0)


def _sim_forced_list(oapp):
    if oapp is None:
        return []
    try:
        return [_text(item) for item in list(oapp.get_forced_expressions())]
    except Exception:
        return []


# OperatingState is a flag enum; the static table is only a fallback for a
# profile whose enum is not reachable through the script engine object.
_OPERATION_STATE_FALLBACK = (
    ("program_loaded", 1), ("download", 2), ("online_change", 4),
    ("store_bootproject", 8), ("force_active", 16), ("exception", 32),
    ("run_after_download", 64), ("store_bootproject_only", 128),
    ("exit", 256), ("delete", 512), ("reset", 1024),
    ("retain_mismatch", 2048), ("bootproject_valid", 4096),
    ("load_bootproject", 8192), ("flow_active", 16384),
)


def _enum_int(value):
    """int() of a .NET enum across IronPython's stringified-enum behaviour."""
    if value is None:
        return None
    for candidate in (value, getattr(value, "value", None),
                      getattr(value, "value__", None)):
        if candidate is None:
            continue
        try:
            return int(candidate)
        except Exception:
            continue
    return None


def _operation_state_flags(se, raw):
    """Decode OperatingState onto its live member names (static fallback)."""
    value = _enum_int(raw)
    if value is None:
        return None
    bits = []
    seen = set()
    enum = getattr(se, "OperatingState", None)
    if enum is not None:
        try:
            for name in dir(enum):
                text = _text(name)
                if not text or text.startswith("_") or text in seen:
                    continue
                seen.add(text)
                bit = _enum_int(getattr(enum, text, None))
                if bit is None or bit <= 0:
                    continue
                bits.append((text, bit))
        except BaseException:
            bits = []
    source = "live OperatingState enum"
    if not bits:
        bits = list(_OPERATION_STATE_FALLBACK)
        source = "static OperatingState fallback"
    flags = {}
    for name, bit in bits:
        try:
            flags[name] = bool(value & bit)
        except Exception:
            continue
    return {"value": value, "flags": flags, "source": source}


def _state_flag(state, name):
    """One decoded OperatingState bit, False when the profile hides it."""
    flags = ((state or {}).get("operationStateFlags") or {}).get("flags") or {}
    return bool(flags.get(name))


def _download_evidence(before, after):
    """What the target's OWN OperatingState says about one login.

    Measured 2026-09-19 (InoProShop V1.10.0.3, simulated runtime): a first
    login on a target with nothing loaded reported operation_state
    "none" before and 4097 (program_loaded | bootproject_valid) after, while the
    transient ``download`` bit was already clear at sample time. So
    operation_state is a STATE bitmask, not an event log: the honest evidence is
    (a) the transient download/online-change bits when they are still set, and
    (b) the program_loaded transition (not loaded before -> loaded after), which
    is exactly what a fresh login transfer produces. Never report "the target
    said no download" from a missing transient bit.
    """
    loaded_before = _state_flag(before, "program_loaded")
    loaded_after = _state_flag(after, "program_loaded")
    download_bit = (_state_flag(after, "download")
                    or _state_flag(after, "run_after_download"))
    change_bit = _state_flag(after, "online_change")
    flags = ((after or {}).get("operationStateFlags") or {})
    return {
        "operationStateBefore": (before or {}).get("operationState"),
        "operationStateAfter": (after or {}).get("operationState"),
        "downloadBit": download_bit,
        "onlineChangeBit": change_bit,
        "programLoadedBefore": loaded_before,
        "programLoadedAfter": loaded_after,
        "bootprojectValid": _state_flag(after, "bootproject_valid"),
        "storeBootproject": _state_flag(after, "store_bootproject"),
        "flagsSource": flags.get("source"),
        "transferInferred": bool(download_bit or (loaded_after and not loaded_before)),
    }


def _download_verdict(evidence):
    """Verdict vocabulary for _download_evidence; never overstates the bits."""
    if not evidence or not evidence.get("flagsSource"):
        return "unproven_no_operation_state"
    if evidence.get("downloadBit"):
        return "download_bit_observed"
    if evidence.get("onlineChangeBit"):
        return "online_change_bit_observed"
    if evidence.get("transferInferred"):
        return "program_loaded_by_login"
    if evidence.get("programLoadedAfter"):
        return "already_loaded_no_transfer_evidence"
    return "no_program_on_target"


def _sim_online_session(create=True):
    """Return the live online application, optionally creating + logging in."""
    se = _sim_scriptengine()
    app_obj, app_path = _sim_application_object()
    app_guid = _text(getattr(app_obj, "guid", ""))
    session = _SIM_SESSION.get("online")
    if session is not None and _SIM_SESSION.get("appGuid") == app_guid:
        return se, session, app_path
    if session is not None:
        try:
            session.logout()
        except Exception:
            pass
        _SIM_SESSION["online"] = None
    if not create:
        return se, None, app_path
    try:
        session = se.online.create_online_application(app_obj)
    except Exception as exc:
        raise OperationError(
            "could not create an online application for the open project: %s"
            % _text(exc),
            "sim_online_unavailable",
            {"applicationPath": app_path, "mutatedProject": False},
        )
    _SIM_SESSION.update({"online": session, "appGuid": app_guid,
                         "appPath": app_path})
    return se, session, app_path


def _sim_state(se, oapp):
    state = {"loggedIn": None, "applicationState": None}
    if oapp is None:
        return state
    try:
        state["loggedIn"] = bool(oapp.is_logged_in)
    except Exception as exc:
        state["loggedInError"] = _text(exc)
    try:
        state["applicationState"] = _text(oapp.application_state)
    except Exception as exc:
        state["applicationStateError"] = _text(exc)
    # These are current/transient status bits, not a record of the last login.
    # Return them as observations; they do not identify the delivered source.
    try:
        raw = oapp.operation_state
        state["operationState"] = _text(raw)
        state["operationStateFlags"] = _operation_state_flags(se, raw)
    except Exception as exc:
        state["operationStateError"] = _text(exc)
    return state


def _sim_read_batch(oapp, expressions):
    """Ask the native monitoring API for one bounded batch.

    Both scalar and batch APIs can return cached monitoring values. The batch
    preserves expression/value alignment and avoids duplicate scalar reads;
    it does not prove freshness. No PLC timestamp or sample age is exposed.
    Never describe host API latency as PLC sampling or first-scan evidence.
    """
    if not expressions:
        return []
    reader = getattr(oapp, "read_values", None)
    if not callable(reader):
        raise OperationError(
            "this installed online API has no read_values monitoring entry point; "
            "current-value evidence is unavailable. Use native IDE monitoring; "
            "a cached read_value is not a substitute.",
            "sim_monitoring_read_unavailable",
            {"expressions": expressions, "mutatedProject": False})
    try:
        raw_values = list(reader(tuple(expressions)))
    except Exception as exc:
        raise OperationError(
            "read_values failed for %s: %s" % (expressions, _text(exc)),
            "sim_read_failed", {"expressions": expressions, "mutatedProject": False})
    if len(raw_values) != len(expressions) or any(value is None for value in raw_values):
        raise OperationError(
            "native monitoring returned an incomplete batch; no values were mapped",
            "sim_read_incomplete",
            {"expressions": expressions, "requestedCount": len(expressions),
             "returnedCount": len(raw_values), "mutatedProject": False})
    return raw_values


def _sim_read_items(oapp, items):
    forced = set(_sim_forced_list(oapp))
    expressions = []
    for item in items or []:
        expr = _text(item.get("expression") or item.get("tag") or item.get("name")).strip()
        if not expr:
            raise OperationError("every read item needs an expression",
                                 "invalid_argument", {"mutatedProject": False})
        expressions.append(expr)
    unique = []
    for expr in expressions:
        if expr not in unique:
            unique.append(expr)
    sampled = dict(zip(unique, _sim_read_batch(oapp, unique)))
    return [{"expression": expr, "raw": _text(sampled[expr]),
             "value": _sim_norm(sampled[expr]), "forced": expr in forced,
             "readMethod": "read_values", "atomicSnapshot": False,
             "monitoringFreshness": "unknown", "sampleAgeMs": None}
            for expr in expressions]


def _sim_prepared_expressions(oapp):
    """The prepared set is application-wide, including the user's editors."""
    try:
        return sorted(set(_text(expr) for expr in oapp.get_prepared_expressions()))
    except Exception as exc:
        raise OperationError(
            "cannot inspect the shared prepared-value set; no write was issued: " + _text(exc),
            "sim_prepared_state_unavailable",
            {"runtimeWriteAttempted": False, "mutatedProject": False})


def _sim_clear_owned_preparations(oapp, expressions):
    """Cancel this call's preparations only; never clear someone else's set."""
    errors = []
    try:
        pending = _sim_prepared_expressions(oapp)
        targets = [expr for expr in expressions if expr in pending]
        if not targets:
            return {"complete": True, "remainingOwnedExpressions": [], "errors": []}
    except OperationError as exc:
        # We still know what this call attempted; cancel just those expressions.
        targets = expressions
        errors.append({"error": _text(exc)})
    for expr in targets:
        try:
            # ScriptOnline documents None/empty string as UNPREPARE, not a write.
            oapp.set_prepared_value(expr, None)
        except Exception as exc:
            errors.append({"expression": expr, "error": _text(exc)})
    try:
        remaining = [expr for expr in _sim_prepared_expressions(oapp) if expr in expressions]
    except OperationError as exc:
        remaining = None
        errors.append({"error": _text(exc)})
    return {"complete": remaining == [], "remainingOwnedExpressions": remaining,
            "errors": errors}


def _sim_write_items(oapp, items, force=False, unforce_first=False):
    if not items:
        raise OperationError("every write needs at least one item",
                             "invalid_argument", {"mutatedProject": False})
    forced = set(_sim_forced_list(oapp))
    prepared = []
    seen = set()
    for item in items:
        expr = _text(item.get("expression") or item.get("tag") or item.get("name")).strip()
        if not expr:
            raise OperationError("every write item needs an expression",
                                 "invalid_argument", {"mutatedProject": False})
        if expr in seen:
            raise OperationError("duplicate write expression: " + expr,
                                 "invalid_argument", {"expression": expr, "mutatedProject": False})
        seen.add(expr)
        if expr in forced and not unforce_first:
            raise OperationError(
                "expression %s is currently FORCED; writing it raises "
                "StandardError('应用程序中的错误。') — call codesys_sim_force_clear "
                "first or pass unforceFirst=true (machine-verified 2026-09-10)"
                % expr,
                "sim_expression_forced",
                {"expression": expr, "forcedExpressions": sorted(forced),
                 "mutatedProject": False},
            )
        prepared.append((expr, _sim_value_text(item.get("value"))))
    existing = _sim_prepared_expressions(oapp)
    if existing:
        raise OperationError(
            "prepared values already exist in the IDE; this call will not commit or discard them. "
            "Review/finish or remove those preparations in the online editor, then retry this write.",
            "sim_prepared_values_present",
            {"preparedExpressions": existing, "runtimeWriteAttempted": False,
             "preparedByThisCall": [], "mutatedProject": False})
    if unforce_first:
        oapp.unforce_all_values()
    attempted = []
    for expr, value in prepared:
        attempted.append(expr)
        try:
            oapp.set_prepared_value(expr, value)
        except Exception as exc:
            cleanup = _sim_clear_owned_preparations(oapp, attempted)
            raise OperationError(
                "set_prepared_value failed for %s=%s: %s; runtime write not issued; "
                "this call's preparations cleared=%s" % (expr, value, _text(exc), cleanup["complete"]),
                "sim_write_failed",
                {"expression": expr, "value": value, "mutatedProject": False,
                 "runtimeWriteAttempted": False, "runtimeValuesMayHaveChanged": False,
                 "forcesClearedFirst": bool(unforce_first), "preparedCleanup": cleanup},
            )
    try:
        now = _sim_prepared_expressions(oapp)
        if set(now) != seen:
            raise OperationError(
                "shared preparations changed during this call; no runtime write was issued",
                "sim_prepared_values_changed",
                {"preparedExpressions": now, "expectedExpressions": sorted(seen),
                 "runtimeWriteAttempted": False, "mutatedProject": False})
    except OperationError as exc:
        cleanup = _sim_clear_owned_preparations(oapp, attempted)
        exc.data["preparedCleanup"] = cleanup
        raise
    try:
        if force:
            oapp.force_prepared_values()
        else:
            oapp.write_prepared_values()
    except Exception as exc:
        cleanup = _sim_clear_owned_preparations(oapp, attempted)
        raise OperationError(
            "applying prepared values failed: %s; some values may already have changed. "
            "Read the affected variables before retrying; this call's preparations cleared=%s"
            % (_text(exc), cleanup["complete"]),
            "sim_write_failed",
            {"prepared": [list(item) for item in prepared],
             "mutatedProject": True, "runtimeWriteAttempted": True,
             "runtimeValuesMayHaveChanged": True, "preparedCleanup": cleanup},
        )
    cleanup = _sim_clear_owned_preparations(oapp, attempted)
    if not cleanup["complete"]:
        raise OperationError(
            "runtime values were submitted but this call's preparations could not be cleared; "
            "read the affected variables and remove the named preparations in the online editor before retrying",
            "sim_prepared_cleanup_failed",
            {"runtimeWriteAttempted": True, "runtimeValuesMayHaveChanged": True,
             "preparedCleanup": cleanup, "mutatedProject": True})
    return {
        "applied": [{"expression": expr, "value": value} for expr, value in prepared],
        "mechanism": "force" if force else "write",
        "forcedExpressions": _sim_forced_list(oapp),
        "preparedCleanup": cleanup,
        "runtimeWriteAttempted": True,
    }


def _sim_compare(actual_text, operator, expected_text, tolerance=None):
    op = _text(operator or "eq").strip().lower()
    op = _SIM_COMPARE_ALIASES.get(op, op)
    if op not in ("eq", "ne", "gt", "ge", "lt", "le"):
        raise OperationError(
            "unsupported operator %r (eq/ne/gt/ge/lt/le)" % _text(operator),
            "invalid_argument", {"mutatedProject": False},
        )
    actual, a_kind = _sim_scalar(actual_text)
    expected, e_kind = _sim_scalar(expected_text)
    if op in ("gt", "ge", "lt", "le"):
        if a_kind != "number" or e_kind != "number":
            raise OperationError(
                "operator %s needs numeric values (actual=%r expected=%r)"
                % (op, _text(actual_text), _text(expected_text)),
                "sim_compare_type_mismatch", {"mutatedProject": False},
            )
        if op == "gt":
            return actual > expected
        if op == "ge":
            return actual >= expected
        if op == "lt":
            return actual < expected
        return actual <= expected
    if tolerance is not None and a_kind == "number" and e_kind == "number":
        same = abs(actual - expected) <= abs(float(tolerance))
    elif a_kind == "number" and e_kind == "number":
        same = abs(actual - expected) <= 1e-9
    else:
        same = _text(actual_text).strip().lower() == _text(expected_text).strip().lower()
    return same if op == "eq" else (not same)


def _sim_evaluate(oapp, expectations):
    """Read each expression once in a native batch, without atomicity claims."""
    rows = []
    all_ok = True
    expressions = []
    for exp in expectations or []:
        expr = _text(exp.get("expression") or exp.get("tag") or exp.get("name")).strip()
        if not expr:
            raise OperationError("every expectation needs an expression",
                                 "invalid_argument", {"mutatedProject": False})
        if expr not in expressions:
            expressions.append(expr)
    started = time.time()
    sampled = dict(zip(expressions, _sim_read_batch(oapp, expressions)))
    read_end_ms = int((time.time() - started) * 1000)
    for exp in expectations or []:
        expr = _text(exp.get("expression") or exp.get("tag") or exp.get("name")).strip()
        raw = sampled[expr]
        actual = _sim_norm(raw)
        ok = _sim_compare(actual, exp.get("operator"), exp.get("value"),
                          exp.get("tolerance"))
        all_ok = all_ok and ok
        rows.append({
            "expression": expr,
            "operator": _text(exp.get("operator") or "eq"),
            "expected": _text(exp.get("value")),
            "actual": actual,
            "raw": _text(raw),
            "ok": bool(ok),
            "readMethod": "read_values",
            "readStartOffsetMs": 0,
            "readEndOffsetMs": read_end_ms,
            "monitoringFreshness": "unknown",
            "sampleAgeMs": None,
        })
    return all_ok, rows


def _sim_observation_window(started, sample_started, sample_finished, observed):
    """Timing is host acquisition time, never a PLC atomic-snapshot claim."""
    return {"startedMsAfterStimulus": int((sample_started - started) * 1000),
            "completedMsAfterStimulus": int((sample_finished - started) * 1000),
            "acquisitionMs": int((sample_finished - sample_started) * 1000),
            "uniqueExpressions": len(set(row.get("expression") for row in observed)),
            "readMethod": "read_values", "offsetScope": "native_batch_call",
            "atomicSnapshot": False,
            "monitoringFreshness": "unknown", "sampleAgeMs": None,
            "timeSource": "host_api_call_not_plc_sample"}


def sim_status():
    se = _sim_scriptengine()
    device, device_path = _sim_device_object()
    app_obj, app_path = _sim_application_object()
    simulation_mode = None
    simulation_error = None
    try:
        simulation_mode = bool(device.get_simulation_mode())
    except Exception as exc:
        simulation_error = _text(exc)
    try:
        _, session, _ = _sim_online_session(create=False)
    except OperationError:
        session = None
    state = _sim_state(se, session)
    tasks = []
    try:
        tasks = [_task_summary(path, task) for path, task in _find_tasks()]
    except Exception as exc:
        tasks = [{"error": _text(exc)}]
    return {
        "line": CODESYS_LINE if "CODESYS_LINE" in globals() else None,
        "project": _project_path(),
        "device": {"path": device_path, "name": _object_name(device)},
        "deviceSimulationMode": simulation_mode,
        "deviceSimulationError": simulation_error,
        "applicationPath": app_path,
        "online": state,
        "forcedExpressions": _sim_forced_list(session),
        "tasks": tasks,
        "capabilities": {
            "simulationSwitch": simulation_mode is not None,
            "onlineLifecycle": True,
            "batchReadWrite": True,
            "force": True,
            "scenarioAssert": True,
            "ioEvaluation": False,
            "fieldbusEvaluation": False,
        },
        "boundary": ("Simulation covers program logic only — no I/O wiring, "
                     "fieldbus or hardware is evaluated; 'simulation pass' is "
                     "not 'wiring correct'."),
    }


# ---------------------------------------------------------------------------
# Native online diagnostics run inside the owned ScriptExecutor request.
# Execution events supply the online driver's context; no permanent frame is
# required. Thread snapshots are diagnostics, not a UI interaction test.
# ---------------------------------------------------------------------------
_SIM_PROBE_LAST = {"report": None}


def _sim_thread_id():
    try:
        import ctypes as _ctypes_tid
        kernel = _ctypes_tid.WinDLL("kernel32")
        kernel.GetCurrentThreadId.restype = _ctypes_tid.c_ulong
        return int(kernel.GetCurrentThreadId())
    except BaseException:
        return None


def _sim_ui_thread_id():
    """Thread id that owns this process' IDE main window (None when headless).

    E2E V2 R052 (measured the hard way): an EnumWindows + ctypes-callback walk
    is NOT safe to repeat from the script thread - three CODESYS processes died
    with System.AccessViolationException in IronPython's ctypes InteropInvoker
    with ``DynamicClass._sim_ui_thread_id`` at the top of the managed stack.
    Ask .NET for the main window handle instead and make ONE plain ctypes call.
    """
    handle = None
    try:
        import System
        handle = int(System.Diagnostics.Process.GetCurrentProcess().MainWindowHandle)
    except BaseException:
        handle = None
    if not handle:
        return None
    try:
        import ctypes as _ctypes_ui
        user32 = _ctypes_ui.WinDLL("user32")
        owner = _ctypes_ui.c_ulong()
        return int(user32.GetWindowThreadProcessId(_ctypes_ui.c_void_p(handle),
                                                   _ctypes_ui.byref(owner)))
    except BaseException:
        return None


def _sim_probe_snapshot():
    """Thread/frame facts for the caller of the online API."""
    try:
        se_module = _sim_scriptengine()
        module_attrs = sorted([_text(name) for name in dir(se_module)])[:160]
        module_name = _text(getattr(se_module, "__name__", "scriptengine"))
    except BaseException as exc:
        module_attrs = None
        module_name = "import failed: " + _text(exc)
    thread_id = _sim_thread_id()
    script_thread = globals().get("_SCRIPT_THREAD_ID")
    context = globals().get("_UI_SYNC_CONTEXT")
    return {
        "pid": os.getpid(),
        "threadId": thread_id,
        "threadName": _text(getattr(threading.currentThread(), "name", "")
                            or getattr(threading.currentThread(), "getName",
                                       lambda: "")()),
        "scriptThreadId": script_thread,
        "isScriptThread": bool(script_thread is not None
                               and thread_id == script_thread),
        "uiThreadId": _sim_ui_thread_id(),
        "primaryThreadHop": bool(globals().get("_PRIMARY_THREAD_HOP")),
        "syncContext": None if context is None else _text(type(context).__name__),
        "inFrameLoop": False,
        "frameLoopThreadId": None,
        "boundedRequestActive": bool(globals().get("_BOUNDED_REQUEST_ACTIVE")),
        "scriptengineModule": module_name,
        "scriptengineAttrs": module_attrs,
    }


def _sim_probe_describe(obj):
    if obj is None:
        return None
    info = {"type": _text(type(obj).__name__), "repr": _text(obj)[:160]}
    for key in ("is_application", "is_device", "is_active_application",
                "guid", "name"):
        try:
            value = getattr(obj, key)
            if not callable(value):
                info[key] = _text(value)
        except BaseException:
            pass
    return info


def _sim_probe_step(report, name, function):
    entry = {"step": name}
    try:
        entry["ok"] = True
        entry["value"] = function()
    except BaseException as exc:
        entry["ok"] = False
        entry["exceptionType"] = _text(type(exc).__name__)
        entry["exception"] = _text(exc)
        entry["traceback"] = traceback.format_exc()
    report["steps"].append(entry)
    return entry


def _sim_probe_core_interface():
    """Is the CORE (non-script) online manager reachable in-process?"""
    import System
    core_type = None
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        try:
            candidate = assembly.GetType("_3S.CoDeSys.Core.SystemInstances")
        except BaseException:
            candidate = None
        if candidate is not None:
            core_type = candidate
            break
    if core_type is None:
        raise RuntimeError("SystemInstances type is not loaded in this process")
    result = {"type": _text(core_type.FullName),
              "assembly": _text(core_type.Assembly.GetName().Name)}
    for name in ("IsOnlineMgrAvailable", "OnlineMgrOrNull", "OnlineMgr"):
        try:
            prop = core_type.GetProperty(name)
            value = None if prop is None else prop.GetValue(None, None)
            result[name] = (None if value is None
                            else _text(value.GetType().FullName))
        except BaseException as exc:
            result[name] = "error: " + _text(exc)
    return result


def _sim_probe_engine_handle():
    """Look for a reachable IScriptEngine (a nested script executor would give
    the bridge a real script frame without a second process)."""
    import System
    result = {"assemblies": [], "interface": None, "staticProviders": []}
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        try:
            name = _text(assembly.GetName().Name)
        except BaseException:
            continue
        if "ScriptEngine" not in name:
            continue
        result["assemblies"].append(name)
        try:
            types = assembly.GetTypes()
        except BaseException:
            continue
        for type_obj in types:
            try:
                full = _text(type_obj.FullName)
                members = type_obj.GetMembers()
            except BaseException:
                continue
            if full.endswith("IScriptEngine"):
                result["interface"] = full
            for member in members:
                try:
                    if not bool(getattr(member, "IsStatic", False)):
                        continue
                    declared = None
                    for attribute in ("PropertyType", "ReturnType"):
                        try:
                            declared = getattr(member, attribute)
                            break
                        except BaseException:
                            continue
                    if declared is None:
                        continue
                    if _text(declared.FullName).endswith("IScriptEngine"):
                        result["staticProviders"].append(
                            full + "." + _text(member.Name))
                except BaseException:
                    continue
    return result


def sim_native_probe(args=None):
    """One request, every candidate: report thread/frame + each driver call."""
    args = args if isinstance(args, dict) else {}
    skip = set([_text(item) for item in (args.get("skip") or [])])
    report = {
        "line": globals().get("CODESYS_LINE"),
        "startedAt": time.time(),
        "context": _sim_probe_snapshot(),
        "steps": [],
    }
    state = {"se": None, "primary": None, "appScript": None,
             "appWrapped": None, "deviceScript": None, "session": None}

    def _import_se():
        se_local = _sim_scriptengine()
        state["se"] = se_local
        return {"attrs": len(dir(se_local)),
                "hasOnline": hasattr(se_local, "online"),
                "hasProjects": hasattr(se_local, "projects"),
                "hasSystem": hasattr(se_local, "system")}
    _sim_probe_step(report, "import scriptengine in this context", _import_se)
    se = state["se"]

    def _primary_tree():
        if se is None:
            raise RuntimeError("scriptengine module unavailable")
        primary = se.projects.primary
        if primary is None:
            raise RuntimeError("se.projects.primary returned None")
        state["primary"] = primary
        children = list(primary.get_children(True))
        return {"primaryType": _text(type(primary).__name__),
                "childCount": len(children),
                "children": [_sim_probe_describe(child)
                             for child in children[:25]]}
    _sim_probe_step(report, "se.projects.primary.get_children(True)", _primary_tree)

    def _pick_from_tree():
        primary = state.get("primary")
        if primary is None:
            raise RuntimeError("primary project unavailable")
        for child in primary.get_children(True):
            try:
                if bool(getattr(child, "is_application", False)):
                    state["appScript"] = child
                elif bool(getattr(child, "is_device", False)):
                    if state["deviceScript"] is None:
                        state["deviceScript"] = child
            except BaseException:
                continue
        if state["appScript"] is None:
            raise RuntimeError("no application node in the SCRIPT tree")
        return {"application": _sim_probe_describe(state["appScript"]),
                "device": _sim_probe_describe(state["deviceScript"])}
    _sim_probe_step(report, "application object from the SCRIPT tree",
                    _pick_from_tree)

    def _pick_wrapped():
        _require_project()
        path = _application_tree_path()
        if not path:
            raise RuntimeError("open project has no Application node path")
        found, found_path = find_project_object(path)
        if found is None:
            raise RuntimeError("wrapped project lookup failed: " + _text(path))
        state["appWrapped"] = found
        return {"path": _text(found_path or path),
                "application": _sim_probe_describe(found)}
    _sim_probe_step(report, "application object from the WRAPPED bridge project",
                    _pick_wrapped)

    def _active_application():
        primary = state.get("primary")
        if primary is None:
            raise RuntimeError("primary project unavailable")
        value = primary.active_application
        return _sim_probe_describe(value)
    _sim_probe_step(report, "se.projects.primary.active_application", _active_application)

    def _try_create(candidate):
        if se is None:
            raise RuntimeError("scriptengine module unavailable")
        session = se.online.create_online_application(candidate)
        state["session"] = session
        info = {"sessionType": _text(type(session).__name__)}
        for key in ("is_logged_in", "application_state"):
            try:
                info[key] = _text(getattr(session, key))
            except BaseException as exc:
                info[key] = "error: " + _text(exc)
        try:
            info["forcedExpressions"] = [_text(item) for item
                                         in list(session.get_forced_expressions())]
        except BaseException as exc:
            info["forcedExpressionsError"] = _text(exc)
        return info

    if "create_script_app" not in skip:
        _sim_probe_step(report, "create_online_application(SCRIPT tree app)",
                        lambda: _try_create(state.get("appScript")))
    if "create_wrapped_app" not in skip:
        _sim_probe_step(report, "create_online_application(WRAPPED app)",
                        lambda: _try_create(state.get("appWrapped")))
    if "create_none" not in skip:
        _sim_probe_step(report, "create_online_application(None=active app)",
                        lambda: _try_create(None))

    def _set_active():
        primary = state.get("primary")
        app = state.get("appScript")
        if primary is None or app is None:
            raise RuntimeError("primary project/application unavailable")
        before = _sim_probe_describe(primary.active_application)
        primary.active_application = app
        after = _sim_probe_describe(primary.active_application)
        return {"before": before, "after": after}
    if "set_active" not in skip:
        _sim_probe_step(report, "set primary.active_application to SCRIPT app",
                        _set_active)
    if "create_after_active" not in skip:
        _sim_probe_step(report, "create_online_application after set active",
                        lambda: _try_create(state.get("appScript")))

    if "create_device" not in skip:
        _sim_probe_step(report, "create_online_device(SCRIPT tree device)",
                        lambda: se.online.create_online_device(
                            state.get("deviceScript")))

    if "core_interface" not in skip:
        _sim_probe_step(report, "core SystemInstances online manager",
                        _sim_probe_core_interface)
    if "engine_handle" not in skip:
        _sim_probe_step(report, "reachable IScriptEngine handle",
                        _sim_probe_engine_handle)

    session = state.get("session")
    if session is not None:
        _SIM_SESSION.update({"online": session,
                             "appGuid": _text(getattr(state.get("appScript"),
                                                      "guid", "")),
                             "appPath": _application_tree_path()})
    report["finishedAt"] = time.time()
    report["sessionCreated"] = session is not None
    _SIM_PROBE_LAST["report"] = report
    try:
        target = os.path.join(os.path.dirname(HEARTBEAT_FILE),
                              "sim-native-probe.json")
        with open(target, "wb") as probe_handle:
            probe_handle.write(json.dumps(report).encode("utf-8"))
    except BaseException:
        pass
    return report


# ---------------------------------------------------------------------------
# Native runtime verification uses a bounded execution for every request.
# The native login/run state survives between requests; event-bound wrappers
# are rebound for each execution. Program mutations still invalidate the code
# epoch so the next runtime operation refreshes the current program.
# ---------------------------------------------------------------------------
_SIM_CODE_EPOCH = {"value": 0}
_SIM_BOUNDARY = ("Simulation evidence covers program LOGIC only: CODESYS "
                 "simulation does not evaluate I/O wiring, fieldbus or "
                 "hardware, so a passing scenario is not proof of correct "
                 "wiring.")


def _sim_bump_code_epoch():
    """A project mutation makes the running program stale by definition."""
    _SIM_CODE_EPOCH["value"] = int(_SIM_CODE_EPOCH.get("value") or 0) + 1


def _sim_teardown(session):
    """Unforce, stop and logout without raising (invalidation + stop path)."""
    if session is None:
        return
    for name in ("unforce_all_values", "stop", "logout"):
        try:
            getattr(session, name)()
        except BaseException:
            pass


# Vendor rejections seen when an object is deleted while the device session is
# logged in (E2E V2 R053/R090): InoProShop reports
# ``无法移除对象'X [...MainTask]'，因为该对象已经用于当前登录的设备`` and the
# InoProShop SP11 build also words it ``无法移动或删除对象'X [Device: PLC 逻辑:
# Application: 任务配置: MainTask]'，该对象已用于登录的PLC中``.  Both arrive as an
# opaque handler_error with an EMPTY data payload, so the model had to infer
# "log out first" from the raw text.  Match both wordings instead of only one.
_OBJECT_DELETE_SESSION_MARKERS = (
    "已经用于当前登录的设备",
    "已用于登录的",
    "用于登录的PLC",
    "currently logged",
    "currently logged-in",
    "logged in device",
    "used by the logged",
)


def _object_delete_online_session():
    """Evidence about a live sim/login session at the delete boundary."""
    session = _SIM_SESSION.get("online")
    if session is None:
        return None
    evidence = {"sessionPresent": True, "loggedIn": None,
                "applicationState": None}
    try:
        se = _sim_scriptengine()
        state = _sim_state(se, session)
        evidence["loggedIn"] = (bool(state.get("loggedIn"))
                                if state.get("loggedIn") is not None else None)
        evidence["applicationState"] = state.get("applicationState")
    except BaseException as exc:
        evidence["stateUnavailable"] = _text(exc)
    return evidence


def _object_delete_release_online_session():
    """Unforce/stop/logout the resident session before a delete (autoLogout)."""
    session = _SIM_SESSION.get("online")
    _sim_teardown(session)
    _SIM_SESSION.update({"online": None, "key": None, "appGuid": None})
    return {"released": session is not None}


def _object_delete_session_error(target, path, raw, online_session):
    """Actionable error for a delete blocked by the logged-in device.

    Returns None when neither the vendor text nor the live-session evidence
    points at a session, so an unrelated delete failure keeps its own error.
    """
    marked = False
    for marker in _OBJECT_DELETE_SESSION_MARKERS:
        if marker in raw:
            marked = True
            break
    if not marked and not online_session:
        return None
    if not marked and online_session and not online_session.get("loggedIn"):
        return None
    return OperationError(
        "the object cannot be removed while a device session is logged in: %s"
        % raw,
        "object_delete_blocked_by_online_session",
        {"target": target, "path": path,
         "mutatedProject": False,
         "rawVendorMessage": raw,
         "onlineSession": online_session,
         "requiredAction": {"tool": "codesys_sim_online", "action": "stop"},
         "remediation": ("End the runtime session first: call codesys_sim_online with "
                         "action=stop (it also unforces values and switches the device "
                         "simulation mode off), then repeat this exact object.delete — or "
                         "pass autoLogout=true to let the bridge release the session in "
                         "this call. Cleanup order stays task entry -> POU -> GVL."),
         "hint": ("the device holds the Application while it is logged in, so the vendor "
                  "refuses to remove objects that belong to it")})


def _sim_session_key(app_obj):
    return (_text(getattr(app_obj, "guid", "")),
            int(_SIM_CODE_EPOCH.get("value") or 0))


def _online_observe_session(require_login=False):
    """Observe a matching session without save/login/download/start/teardown.

    Bounded dispatch can rebind and dispose a wrapper for an existing native
    session. That does not grant a read operation permission to control it.
    A stale program binding must remain untouched until an explicit mutation.
    """
    se = _sim_scriptengine()
    device, device_path = _sim_device_object()
    app_obj, app_path = _sim_application_object()
    key = _sim_session_key(app_obj)
    session = _SIM_SESSION.get("online")
    report = {"devicePath": device_path, "applicationPath": app_path,
              "applicationGuid": key[0] or None,
              "programVersion": None, "programVersionSource": "unavailable",
              "bridgeCodeEpoch": key[1],
              "readOnly": True, "onlineSessionTouched": False,
              "simulationModeUntouched": True, "startIssued": False,
              "loginIssued": False, "sessionCreated": False}
    try:
        mode = bool(device.get_simulation_mode())
    except BaseException as exc:
        mode = None
        report["simulationModeError"] = _text(exc)
    report["simulationModeBefore"] = mode
    report["simulationModeAfter"] = mode
    if session is None:
        status = "no_session"
    elif _SIM_SESSION.get("key") != key:
        status = "stale_session"
    else:
        status = "matching_session"
    observed = session if status == "matching_session" else None
    state = _sim_state(se, observed)
    if observed is not None:
        status = ("ready" if state.get("loggedIn") is True else
                  "login_required" if state.get("loggedIn") is False else
                  "state_unavailable")
    report["onlineSessionStatus"] = status
    # This epoch detects writes observed by the bridge. It is not a vendor
    # program checksum and cannot prove that UI/external edits were absent.
    report["identityBoundary"] = (
        "applicationGuid identifies the project Application; bridgeCodeEpoch "
        "is a local edit counter, not the runtime program version. "
        "A verified vendor program version is unavailable.")
    report["online"] = state
    report["forcedExpressions"] = (
        _sim_forced_list(observed) if status == "ready" else None)
    if status != "ready":
        report["next"] = {
            "tool": "codesys_online_login",
            "arguments": {"confirm": "online_login"},
            "effect": "Explicit login may transfer the program and start it; "
                      "inspect the intended project and target before requesting it."}
        if require_login:
            raise OperationError(
                "online operation requires a matching logged-in session (" + status +
                "); no login, download, start or session teardown was issued",
                "online_session_not_ready", report)
    return se, observed, report


def _sim_ensure_online(manage_simulation=True, change_option="Try", start_if_stopped=True):
    """Return (se, session, report) for a logged-in session.

    The session is created on first use, reused while the program version and
    the application are unchanged, and torn down when either moves.

    manage_simulation=False is the online.* contract: the SAME session
    machinery, but a call must never retarget the project. Switching the device
    into simulation mode here silently moved a real-device project onto the
    simulator (measured defect 2026-09-19), so the online family reports the
    device's mode instead of changing it.

    start_if_stopped=False lets reset preserve an already stopped application.
    Reset must never start executing the old program merely to connect first.
    """
    se = _sim_scriptengine()
    device, device_path = _sim_device_object()
    app_obj, app_path = _sim_application_object()
    report = {"devicePath": device_path, "applicationPath": app_path}
    key = _sim_session_key(app_obj)
    session = _SIM_SESSION.get("online")
    needs_login = (session is None or _SIM_SESSION.get("key") != key or
                   not _sim_state(se, session).get("loggedIn"))
    if needs_login:
        option = _online_change_option(se, _text(change_option))
        try:
            project.save()
            report["saved"] = True
        except BaseException as exc:
            report.update({"saved": False, "saveError": _text(exc),
                           "loginIssued": False, "mutatedTarget": False})
            raise OperationError(
                "the project could not be saved; no login or download was issued",
                "online_login_blocked_by_save", report)
    if session is not None and _SIM_SESSION.get("key") != key:
        report["invalidated"] = (
            "the program changed since the session started"
            if _SIM_SESSION.get("appGuid") == key[0]
            else "a different application became active")
        _sim_teardown(session)
        _SIM_SESSION.update({"online": None, "key": None})
        session = None
    try:
        report["simulationModeBefore"] = bool(device.get_simulation_mode())
    except BaseException as exc:
        report["simulationModeBefore"] = None
        report["simulationModeError"] = _text(exc)
    if not manage_simulation:
        report["simulationModeUntouched"] = True
        report["simulationModeAfter"] = report.get("simulationModeBefore")
    else:
        if report.get("simulationModeBefore") is False:
            device.set_simulation_mode(True)
        if report.get("simulationModeBefore") is not None:
            try:
                report["simulationModeAfter"] = bool(device.get_simulation_mode())
            except BaseException:
                report["simulationModeAfter"] = None
        else:
            report["simulationModeAfter"] = None
    if session is None:
        try:
            session = se.online.create_online_application(app_obj)
        except BaseException as exc:
            raise OperationError(
                "could not create an online application for the open project: %s"
                % _text(exc), "sim_online_unavailable",
                {"applicationPath": app_path, "mutatedProject": False})
        _SIM_SESSION.update({"online": session, "key": key, "appGuid": key[0],
                             "appPath": app_path})
        report["sessionCreated"] = True
    state = _sim_state(se, session)
    if not state.get("loggedIn"):
        # A matching session may disconnect after the first state sample.
        # Re-resolve the same enum, and save before any late login too.
        if not needs_login:
            option = _online_change_option(se, _text(change_option))
            try:
                project.save()
                report["saved"] = True
            except BaseException as exc:
                report.update({"saved": False, "saveError": _text(exc),
                               "loginIssued": False, "mutatedTarget": False})
                raise OperationError(
                    "the project could not be saved; no login or download was issued",
                    "online_login_blocked_by_save", report)
        report["changeOption"] = _text(change_option)
        report["deleteForeignApps"] = False
        report["operationStateBeforeLogin"] = state.get("operationState")
        session.login(option, False)
        report["loginIssued"] = True
        state = _sim_state(se, session)
        report["operationStateAfterLogin"] = state.get("operationState")
        report["downloadEvidence"] = _download_evidence(None, state)
    if start_if_stopped and _text(state.get("applicationState")).strip().lower() != "run":
        session.start()
        report["startIssued"] = True
        state = _sim_state(se, session)
    report["online"] = state
    report["forcedExpressions"] = _sim_forced_list(session)
    return se, session, report


def _sim_session_report(report):
    return {
        "project": _project_path(),
        "deviceSimulationMode": report.get("simulationModeAfter"),
        "simulationModeBefore": report.get("simulationModeBefore"),
        "online": report.get("online"),
        "loginState": (report.get("online") or {}).get("applicationState"),
        "forcedExpressions": report.get("forcedExpressions"),
        "session": report,
    }


def sim_online_native(args, manage_simulation=True):
    """state|login|start ensure the live session; stop|logout tear it down.

    manage_simulation=False keeps the online.* contract: report the device's
    simulation mode, never switch it. The sim.* cards keep the historical
    behaviour of turning simulation on while they verify program logic.
    """
    args = args if isinstance(args, dict) else {}
    action = _text(args.get("action") or "state").strip().lower()
    session = _SIM_SESSION.get("online")
    if action in ("stop", "logout", "shutdown"):
        forced_before = _sim_forced_list(session)
        already = session is None
        _sim_teardown(session)
        _SIM_SESSION.update({"online": None, "key": None, "appGuid": None})
        device_path = None
        sim_after = None
        sim_before = None
        try:
            device, device_path = _sim_device_object()
            sim_before = bool(device.get_simulation_mode())
            if manage_simulation and sim_before:
                device.set_simulation_mode(False)
            sim_after = bool(device.get_simulation_mode())
            if manage_simulation:
                try:
                    project.save()
                except BaseException:
                    pass
        except OperationError:
            device_path = None
            sim_before = None
        return {
            "stopped": True,
            "alreadyStopped": already,
            "forcedBefore": forced_before,
            "forcedAfter": [],
            "forcedCleared": {"forcedBefore": forced_before, "forcedAfter": []},
            "device": device_path,
            "deviceSimulationMode": sim_after,
            "simulationMode": {"before": sim_before, "after": sim_after},
            "simulationModeUntouched": (not manage_simulation),
            "online": {"loggedIn": False, "applicationState": None},
            "project": _project_path(),
            "boundary": _SIM_BOUNDARY,
        }
    if action not in ("state", "status", "login", "start"):
        raise OperationError("action must be state|login|start|stop|logout",
                             "invalid_argument", {"mutatedProject": False})
    option = _text(args.get("changeOption") or "Try")
    if option not in ("Never", "Try", "Force"):
        raise OperationError(
            "changeOption must be Never, Try or Force",
            "invalid_argument",
            {"field": "changeOption", "actual": option,
             "supported": ["Never", "Try", "Force"], "mutatedProject": False})
    _se, _session, report = _sim_ensure_online(
        manage_simulation=manage_simulation, change_option=option)
    payload = _sim_session_report(report)
    payload["action"] = action
    payload["note"] = ("the resident bridge logs in and starts once per program "
                       "version; action=state reports the live session")
    payload["boundary"] = _SIM_BOUNDARY
    return payload


def sim_read_native(args, manage_simulation=True):
    args = args if isinstance(args, dict) else {}
    _se, session, report = _sim_ensure_online(manage_simulation=manage_simulation)
    payload = {"values": _sim_read_items(session, args.get("items"))}
    payload.update(_sim_session_report(report))
    payload["boundary"] = _SIM_BOUNDARY
    return payload


def sim_write_native(args, manage_simulation=True):
    args = args if isinstance(args, dict) else {}
    _se, session, report = _sim_ensure_online(manage_simulation=manage_simulation)
    payload = _sim_write_items(session, args.get("items"),
                               force=bool(args.get("force")),
                               unforce_first=bool(args.get("unforceFirst")))
    payload["online"] = report.get("online")
    payload["downloadEvidence"] = report.get("downloadEvidence")
    payload["boundary"] = _SIM_BOUNDARY
    return payload


def sim_force_clear_native(args, manage_simulation=True):
    _se, session, _report = _sim_ensure_online(manage_simulation=manage_simulation)
    before = _sim_forced_list(session)
    session.unforce_all_values()
    return {"forcedBefore": before, "forcedAfter": _sim_forced_list(session),
            "boundary": _SIM_BOUNDARY}


def _sim_payload_chars(payload):
    """The runtime first removes JSON whitespace without losing any fields."""
    try:
        return len(json.dumps(payload, ensure_ascii=False, separators=(",", ":")))
    except Exception:
        return len(json.dumps(payload))


def _sim_cadence_ms(times):
    """Observed sampling interval of one step (mean gap), in milliseconds."""
    if not times or len(times) < 2:
        return None
    total = 0.0
    for index in range(1, len(times)):
        total += (times[index] - times[index - 1]) * 1000.0
    return int(round(total / float(len(times) - 1)))


# The engine replaces any tool result longer than this with a lossy summary
# (runtime/src/conversation/turn.rs: MAX_TOOL_RESULT_MODEL_CHARS = 12_000) that
# keeps only a SAMPLE of steps[] — measured in R053/L92: a 20-step scenario came
# back as "passed:16/failed:0" with the last steps' observations invisible.
_SIM_RESULT_CHAR_BUDGET = 10000


def _sim_short_expression(value):
    """Keep the exact qualified expression: different objects share leaf names."""
    return _text(value).strip()


def _sim_check_line(observation):
    """One compact, complete check line: expr op expected -> actual OK|FAIL."""
    if not isinstance(observation, dict):
        return _text(observation)
    line = "%s %s %s -> %s %s" % (
        _sim_short_expression(observation.get("expression")),
        _text(observation.get("operator") or "eq"),
        _text(observation.get("expected")),
        _text(observation.get("actual")),
        "OK" if observation.get("ok") else "FAIL")
    if observation.get("tolerance") is not None:
        line += " tolerance=" + _text(observation.get("tolerance"))
    if observation.get("error"):
        line += " error=" + _text(observation.get("error"))
    return line


def _sim_prune_row(row):
    """Drop per-sample/verbose noise from one step row, keep its identity."""
    row.pop("write", None)
    row.pop("observationsOmitted", None)
    row.pop("observationCount", None)
    if row.get("samples") == 1:
        row.pop("samples", None)
    if row.get("firstHoldMs") is None:
        row.pop("firstHoldMs", None)
    if row.get("sampleCadenceMs") is None:
        # Only an unobservable interval for a single-sample step; the payload's
        # top-level sampleCadenceMs still reports the scenario's cadence.
        row.pop("sampleCadenceMs", None)
    failures = row.get("failures")
    if not failures:
        row.pop("failures", None)
    elif row.get("observations"):
        # The failing observation rows already carry the measured values, so the
        # free-text detail is duplicated evidence: keep the machine-readable kind.
        row["failures"] = [{"kind": _text(failure.get("kind"))}
                           if isinstance(failure, dict) else failure
                           for failure in failures]
    if not row.get("observations"):
        row.pop("observations", None)
    return row


def _sim_archive_result(payload):
    """Persist the complete native result before any projection, as UTF-8 JSON.

    Content-addressed names avoid overwriting another scenario; pretty JSON
    makes read_file offset/limit useful without re-running the controller.
    """
    raw = json.dumps(_json_safe(payload), ensure_ascii=False, indent=2).encode("utf-8")
    digest = hashlib.sha256(raw).hexdigest()
    directory = os.path.abspath(os.path.join(os.path.dirname(RES_DIR), "evidence", "sim-assert"))
    if not os.path.isdir(directory):
        os.makedirs(directory)
    path = os.path.join(directory, digest + ".json")
    if not os.path.isfile(path):
        temp_path = path + ".tmp"
        with open(temp_path, "wb") as output:
            output.write(raw)
        os.rename(temp_path, path)
    with open(path, "rb") as source:
        if hashlib.sha256(source.read()).hexdigest() != digest:
            raise IOError("simulation evidence hash mismatch")
    return {"path": path, "sha256": digest, "bytes": len(raw), "format": "utf-8-json"}


def _sim_compact_result(payload, limit=_SIM_RESULT_CHAR_BUDGET):
    """Preserve every measured check or explicitly link its complete evidence.

    Budget the minified JSON, matching the engine's lossless first stage.
    Under pressure remove duplicated session/write metadata before check rows.
    Never shorten qualified identifiers or silently discard passing checks.
    A report too large even after projection is read from its saved evidence,
    not re-executed on the controller just to recover missing observations.
    """
    budget = max(2000, int(limit))
    if _sim_payload_chars(payload) <= budget:
        return payload
    try:
        evidence = _sim_archive_result(payload)
    except Exception as exc:
        raise OperationError(
            "scenario executed but its complete evidence could not be saved: " + _text(exc),
            "sim_result_evidence_write_failed",
            {"scenarioExecuted": True, "verdict": payload.get("verdict"),
             "next": "Repair the evidence directory's write access; do not automatically rerun the scenario."})
    payload["evidence"] = evidence
    payload["completeResultInline"] = True
    for row in payload.get("steps") or []:
        for observation in row.get("observations") or []:
            observation.pop("raw", None)
    if _sim_payload_chars(payload) <= budget:
        return payload
    omitted = []
    structured = []
    for row in payload.get("steps") or []:
        observations = row.get("observations") or []
        if not observations:
            _sim_prune_row(row)
            continue
        lines = [_sim_check_line(observation) for observation in observations]
        if row.get("status") == "pass":
            row["observationsSummary"] = lines
            row["observations"] = []
            omitted.append(row.get("index"))
        else:
            failing = [observation for observation in observations
                       if not observation.get("ok")]
            held = [observation for observation in observations
                    if observation.get("ok")]
            if not failing:
                failing = observations
                held = []
            row["observations"] = [_sim_prune_observation(observation)
                                   for observation in failing]
            if held:
                row["observationsSummary"] = [
                    _sim_check_line(observation) for observation in held]
                row["heldCount"] = len(held)
            structured.append(row.get("index"))
        _sim_prune_row(row)
    payload["observationsOmittedForPassingSteps"] = bool(omitted)
    payload["compactedSteps"] = omitted
    payload["compaction"] = {
        "applied": True,
        "budgetChars": budget,
        "policy": ("all steps keep name/status/elapsedMs (+sampleCadenceMs when observed); a "
                   "FAILED step keeps each failed check as a full row and its held checks as "
                   "summary lines; a PASSING step keeps one summary line per expectation"),
        "observationsOmittedForPassingSteps": omitted,
        "failedStepsWithFullObservations": structured,
    }
    if _sim_payload_chars(payload) <= budget:
        return payload
    session = payload.get("session")
    if isinstance(session, dict):
        payload["session"] = {
            key: session.get(key) for key in (
                "sessionCreated", "loginIssued", "startIssued",
                "simulationModeBefore", "simulationModeAfter", "invalidated",
                "forcedExpressions", "online")
            if key in session}
        payload["compaction"]["sessionTrimmed"] = True
    if _sim_payload_chars(payload) <= budget:
        return payload
    # The echoed preset and repeated online flags can dominate a small scenario.
    # Their exact values already live in the full evidence file. The preset's
    # stop/start verification, warnings and no-reset semantics remain inline.
    preset = payload.get("presetApplied")
    if isinstance(preset, dict) and isinstance(preset.get("applied"), list):
        preset["appliedCount"] = len(preset.pop("applied"))
        preset["appliedValuesInFullResult"] = True
    for owner in (payload, payload.get("session")):
        if not isinstance(owner, dict):
            continue
        online = owner.get("online")
        if isinstance(online, dict):
            owner["online"] = {key: online[key] for key in
                               ("applicationState", "loggedIn", "operationState") if key in online}
    payload["compaction"]["sessionAndPresetDetailsInFullResult"] = True
    if _sim_payload_chars(payload) <= budget:
        return payload
    # Complete summary lines can replace structured failure rows; no value or
    # failing check is thrown away. The archive retains all raw diagnostics.
    for row in payload.get("steps") or []:
        observations = row.get("observations") or []
        if not observations:
            continue
        row["observationsSummary"] = (
            [_sim_check_line(observation) for observation in observations] +
            list(row.get("observationsSummary") or []))
        row.pop("observations", None)
    payload["compaction"]["failedChecksAsCompleteSummaryLines"] = True
    if _sim_payload_chars(payload) <= budget:
        return payload
    # A large step table is not sampled: return an explicit file-backed result.
    # The model must read that artifact for per-check claims; do not turn a
    # compact pass label into evidence for details that are not shown inline.
    result = {key: payload[key] for key in ("verdict", "passed", "failed", "skipped") if key in payload}
    result.update({
        "completeResultInline": False,
        "stepCount": len(payload.get("steps") or []),
        "evidence": evidence,
        "compaction": {"applied": True, "budgetChars": budget, "policy": "complete evidence in file; no sampled checks"},
        "next": {"tool": "read_file", "path": evidence["path"], "offset": 0, "limit": 160},
        "modelInstruction": "Per-step evidence is in the saved file. Read it before claiming any measured value; do not rerun the scenario to recover output."})
    return result


def _sim_prune_observation(observation):
    """Minimal structured row retaining qualified identity and read failures."""
    if not isinstance(observation, dict):
        return observation
    row = {}
    for key in ("operator", "expected", "actual", "ok", "tolerance", "error"):
        if key in observation:
            row[key] = observation.get(key)
    if observation.get("expression") is not None:
        row["expression"] = _sim_short_expression(observation.get("expression"))
    return row


def _sim_apply_preset(se, session, preset, args, session_preexisting):
    """Apply the power-up input picture and REPORT what really happened.

    Documented contract: stop -> write -> start, so an NC-wired input gets its
    healthy value before the first scan (E2E V2 R049).

    E2E V2 R090 measured the gap: when the session already existed the old code
    only reported ``mechanism="write"`` (the per-write mechanism of
    ``_sim_write_items``) with no restart evidence at all, and the model read the
    initial state off it.  L92 (2026-09-10) measured the underlying semantics on
    BOTH lines: a preset does NOT bring the program back to its initial values —
    a free-running DWORD counter kept growing across the preset step (vanilla
    671 -> 797 -> 911; InoProShop 258 -> 522) and a latch stayed TRUE.

    So the result now states explicitly:
      * ``mechanism``: "stop_write_start" when the stop and the start were both
        issued AND the application state verifiably left "run" and came back to
        "run"; otherwise "write_no_restart";
      * ``stopIssued/stopVerified/startIssued/startVerified`` plus the observed
        application states, so an unverified restart is visible instead of
        silent;
      * ``valueSource`` and ``hint``: these values are a LIVE WRITE, never proof
        of power-up defaults, because scan-carried state (latches, counters,
        timers, state machines) is NOT reset;
      * ``warnings`` -> payload ``presetWarnings``: session_preexisting_no_restart
        when the restart could not be verified on a pre-existing session,
        preset_restart_unverified otherwise.
    """
    state_before = None
    state_after_stop = None
    state_after_start = None
    stop_error = None
    start_error = None
    stop_issued = False
    stop_verified = False
    start_issued = False
    start_verified = False
    try:
        state_before = _text(_sim_state(se, session).get("applicationState"))
    except BaseException:
        state_before = None
    try:
        session.stop()
        stop_issued = True
    except BaseException as exc:
        stop_error = _text(exc)
    if stop_issued:
        # The writes are only a power-up picture if the program is genuinely not
        # scanning while they land, so wait for that state instead of assuming
        # stop() took effect.
        deadline = time.time() + 3.0
        while time.time() < deadline:
            try:
                state_after_stop = _text(
                    _sim_state(se, session).get("applicationState"))
            except BaseException:
                state_after_stop = None
            if _text(state_after_stop).strip().lower() != "run":
                stop_verified = True
                break
            _sim_delay(se, 100)
    try:
        applied = _sim_write_items(session, preset, force=False,
                                   unforce_first=bool(args.get("clearForced")))
    except BaseException:
        # Never leave the program stopped because the write failed.
        try:
            session.start()
        except BaseException:
            pass
        raise
    try:
        session.start()
        start_issued = True
    except BaseException as exc:
        start_error = _text(exc)
    if start_issued:
        deadline = time.time() + 5.0
        while time.time() < deadline:
            try:
                state_after_start = _text(
                    _sim_state(se, session).get("applicationState"))
            except BaseException:
                state_after_start = None
            if _text(state_after_start).strip().lower() == "run":
                start_verified = True
                break
            _sim_delay(se, 100)
    _sim_delay(se, 300)
    restarted = bool(stop_verified and start_verified)
    result = dict(applied)
    warnings = []
    if not restarted:
        warnings.append("session_preexisting_no_restart" if session_preexisting
                        else "preset_restart_unverified")
    result.update({
        "mechanism": "stop_write_start" if restarted else "write_no_restart",
        "writeMechanism": applied.get("mechanism"),
        "sessionPreexisting": bool(session_preexisting),
        "stopIssued": stop_issued,
        "stopVerified": stop_verified,
        "startIssued": start_issued,
        "startVerified": start_verified,
        "applicationStateBefore": state_before,
        "applicationStateAfterStop": state_after_stop,
        "applicationStateAfterStart": state_after_start,
        "stopError": stop_error,
        "startError": start_error,
        # Measured on both CODESYS lines (L92 2026-09-10): stop/start and a fresh
        # login both leave scan-carried state untouched, so preset values are a
        # live write and must never be read as power-up defaults.
        "powerUpDefaults": False,
        "valueSource": "live_write_not_power_up_defaults",
        "hint": ("preset updates the current session, even when stop/start is verified: scan-carried state "
                 "(latches, counters, timers, state machines) is NOT reset, so they are not "
                 "power-up defaults. Read the real runtime state (codesys_sim_read) and "
                 "anchor the scenario on those measured values."),
        "warnings": warnings,
    })
    return result


def sim_assert_native(args):
    """Ordered scenario against the RUNNING simulated application."""
    args = args if isinstance(args, dict) else {}
    se, session, report = _sim_ensure_online()
    state = report.get("online") or {}
    if not state.get("loggedIn"):
        raise OperationError(
            "the simulated application is not logged in",
            "sim_online_unavailable",
            {"applicationPath": report.get("applicationPath"),
             "mutatedProject": False})
    if _text(state.get("applicationState")).strip().lower() != "run":
        raise OperationError(
            "the simulated application is not running (applicationState=%s); "
            "no runtime evidence can be claimed from it"
            % _text(state.get("applicationState")),
            "sim_not_running",
            {"simulationState": _text(state.get("applicationState")),
             "mutatedProject": False})
    forced_before = _sim_forced_list(session)
    if forced_before and not args.get("clearForced"):
        raise OperationError(
            "refused: forced expressions present: %s" % forced_before,
            "sim_forced_expressions_present",
            {"forcedExpressions": forced_before, "mutatedProject": False})
    if forced_before:
        session.unforce_all_values()

    steps = args.get("steps") or []
    if not steps:
        raise OperationError("scenario needs a non-empty steps array",
                             "invalid_argument", {"mutatedProject": False})
    # E2E V2 R049: an NC-wired input reads 0 during the first scans, so a
    # fail-safe latch sets before the scenario can write anything. `preset`
    # applies the power-up input picture BEFORE the program runs: stop ->
    # write -> start, exactly like an operator's "modify values" while stopped.
    # E2E V2 R090/L92: the mechanism is now reported truthfully instead of
    # degrading silently to a plain write.
    preset_applied = None
    preset_warnings = []
    preset = args.get("preset") or []
    if preset:
        preset_applied = _sim_apply_preset(
            se, session, preset, args, not report.get("sessionCreated"))
        preset_warnings = list(preset_applied.get("warnings") or [])
    poll_default = max(10, int(args.get("pollIntervalMs") or 100))
    max_samples = max(1, min(int(args.get("maxSamplesPerStep") or 60), 600))
    stop_first = args.get("stopOnFirstFailure")
    stop_first = True if stop_first is None else bool(stop_first)
    default_settle = max(0, int(args.get("defaultSettleMs") or 200))

    rows = []
    verdict = "pass"
    for index, step in enumerate(steps):
        row = {"index": index,
               "name": _text(step.get("name") or ("step %d" % (index + 1))),
               "status": "skipped", "samples": 0, "observations": [],
               "sampleCadenceMs": None,
               "failures": []}
        sample_times = []
        if verdict == "fail" and stop_first:
            row["skippedBecause"] = "stopOnFirstFailure"
            rows.append(row)
            continue
        writes = step.get("write") or []
        if writes:
            row["write"] = _sim_write_items(
                session, writes, force=bool(step.get("force")),
                unforce_first=bool(step.get("unforceFirst")))
        started = time.time()
        expectations = step.get("expect") or []
        window_ms = int(step.get("expectWithinMs") or 0)
        not_before_ms = int(step.get("expectNotBeforeMs") or 0)
        hold_ms = int(step.get("holdMs") or 0)
        poll_ms = int(step.get("pollIntervalMs") or poll_default)
        settle_ms = step.get("settleMs")
        if settle_ms is None:
            scans = step.get("settleScans")
            scan_time = step.get("scanTimeMs")
            settle_ms = ((int(scans) * int(scan_time))
                         if (scans and scan_time) else default_settle)
        settle_ms = max(0, int(settle_ms))
        if not expectations:
            _sim_delay(se, settle_ms)
            row["status"] = "observed"
            row["elapsedMs"] = int((time.time() - started) * 1000)
            rows.append(row)
            continue
        if window_ms > 0:
            if not_before_ms > 0 and window_ms <= not_before_ms:
                raise OperationError(
                    "expectWithinMs must exceed expectNotBeforeMs",
                    "invalid_argument", {"mutatedProject": False})
            first_hold = None
            last_rows = []
            deadline = started + (window_ms / 1000.0)
            while True:
                sample_started = time.time()
                ok_now, observed = _sim_evaluate(session, expectations)
                sample_finished = time.time()
                row["samples"] += 1
                sample_times.append(sample_finished)
                row["observationWindow"] = _sim_observation_window(
                    started, sample_started, sample_finished, observed)
                last_rows = observed
                if ok_now:
                    first_hold = int((sample_finished - started) * 1000)
                    break
                if time.time() >= deadline or row["samples"] >= max_samples:
                    break
                _sim_delay(se, poll_ms)
            row["observations"] = last_rows
            row["firstHoldMs"] = first_hold
            if first_hold is None:
                row["status"] = "fail"
                row["undersampled"] = row["samples"] >= max_samples
                row["failures"].append(
                    {"kind": "expectWithinMs",
                     "detail": "not observed to hold within %d ms" % window_ms})
            elif sample_finished > deadline:
                row["status"] = "fail"
                row["undersampled"] = True
                row["failures"].append(
                    {"kind": "observationDeadline",
                     "detail": ("matching values were only observed at %d ms, after the %d ms "
                                "deadline; timing is unverified, not proof of a late PLC response. "
                                "Use a PLC-latched timestamp/trace for deadlines below acquisition latency.")
                               % (first_hold, window_ms)})
            elif not_before_ms > 0 and first_hold < not_before_ms:
                row["status"] = "fail"
                row["failures"].append(
                    {"kind": "expectNotBeforeMs",
                     "detail": "held at %d ms, before %d ms"
                               % (first_hold, not_before_ms)})
            else:
                row["status"] = "pass"
        else:
            _sim_delay(se, settle_ms)
            sample_started = time.time()
            ok_now, observed = _sim_evaluate(session, expectations)
            sample_finished = time.time()
            row["samples"] = 1
            sample_times.append(sample_finished)
            row["observationWindow"] = _sim_observation_window(
                started, sample_started, sample_finished, observed)
            row["observations"] = observed
            row["firstHoldMs"] = int((time.time() - started) * 1000) if ok_now else None
            row["status"] = "pass" if ok_now else "fail"
            if not ok_now:
                row["failures"].append(
                    {"kind": "expect",
                     "detail": "at least one expectation did not hold"})
        # Apply the same sampled hold after either first-satisfaction path.
        # Without a window, an initially failed expectation must fail immediately.
        if row["status"] == "pass" and hold_ms > 0:
            hold_deadline = time.time() + (hold_ms / 1000.0)
            while time.time() < hold_deadline:
                _sim_delay(se, poll_ms)
                sample_started = time.time()
                ok_now, observed = _sim_evaluate(session, expectations)
                sample_finished = time.time()
                row["samples"] += 1
                sample_times.append(sample_finished)
                row["observations"] = observed
                row["observationWindow"] = _sim_observation_window(
                    started, sample_started, sample_finished, observed)
                if not ok_now:
                    row["status"] = "fail"
                    row["observations"] = observed
                    row["failures"].append(
                        {"kind": "holdMs",
                         "detail": "state broke during %d ms hold"
                                   % hold_ms})
                    break
        row["sampleCadenceMs"] = _sim_cadence_ms(sample_times)
        row["elapsedMs"] = int((time.time() - started) * 1000)
        if row["status"] != "pass" and verdict == "pass":
            verdict = "fail"
        rows.append(row)

    cadence_values = [r.get("sampleCadenceMs") for r in rows
                      if r.get("sampleCadenceMs") is not None]
    sampled_cadence = (int(round(sum(cadence_values) / float(len(cadence_values))))
                       if cadence_values else None)
    payload = {
        "verdict": verdict,
        "scenario": _text(args.get("scenario") or ""),
        "steps": rows,
        "passed": len([r for r in rows if r["status"] == "pass"]),
        "failed": len([r for r in rows if r["status"] in ("fail", "error")]),
        "skipped": len([r for r in rows if r["status"] == "skipped"]),
        "pollIntervalMs": poll_default,
        # Observed sampling interval (mean of the per-step cadences) and the per
        # step boundary time (each row's elapsedMs) are what an edge-based
        # scenario is calibrated against (E2E V2 R053/R090).
        "sampleCadenceMs": sampled_cadence,
        "observationSemantics": ("Unique expressions are requested together through native read_values; "
                                 "repeated checks share one value per pass. This is not an atomic PLC "
                                 "snapshot or PLC timestamp. Offsets bound the native batch call. For short "
                                 "freshness windows, check one expression per fresh stimulus; do not lengthen "
                                 "the program's timeout to accommodate the observer."),
        "maxSamplesPerStep": max_samples,
        "forcedExpressionsAtStart": forced_before,
        "presetApplied": preset_applied,
        "presetWarnings": preset_warnings,
        "online": report.get("online"),
        "simulationMode": {"before": report.get("simulationModeBefore"),
                           "after": report.get("simulationModeAfter")},
        "applicationPath": report.get("applicationPath"),
        "session": report,
        "boundary": _SIM_BOUNDARY,
    }
    return _sim_compact_result(payload)


def _roundtrip(req):
    """Write, independently read, build, save, reopen, read and rebuild."""
    global project, native_core_project
    path = req.get("projectPath") or req.get("path")
    # Defense in depth for callers that invoke the compatibility handler
    # directly (bypassing the dispatch guard).  A round-trip writes source,
    # saves the project, and reopens it; it is never valid against the real
    # PLC Engineering Suite project or an arbitrary filesystem path.
    if req.get("disposable") is not True:
        raise OperationError(
            "roundtrip.verify requires disposable=true",
            "disposable_confirmation_required",
            {"operation": "roundtrip.verify", "mutatedProject": False},
        )
    if _text(req.get("confirm")).strip() != "verify_roundtrip":
        raise OperationError(
            "roundtrip.verify requires confirm=verify_roundtrip",
            "confirmation_required",
            {"operation": "roundtrip.verify", "mutatedProject": False,
             "expectedConfirm": "verify_roundtrip"},
        )
    if path:
        path = _require_disposable_destination_path(path, "roundtrip.verify")
        if not path.lower().endswith(".project"):
            raise OperationError(
                "roundtrip.verify projectPath must end in .project",
                "invalid_argument",
                {"projectPath": path, "mutatedProject": False},
            )
    open_info = None
    if project is None:
        if not path:
            raise RuntimeError("roundtrip.verify requires projectPath when no project is open")
        if not os.path.isfile(path):
            raise RuntimeError("project not found: " + _text(path))
        project, open_info = open_project_silent(path, req.get("password", ""))
        native_core_project = None
        pou_cache.clear()
    elif (path and _project_path() and
          os.path.normcase(os.path.abspath(path)) !=
          os.path.normcase(os.path.abspath(_project_path()))):
        raise RuntimeError("a different project is already open; close it first")

    steps = {
        "projectPath": _project_path(),
        "open": {"projectPath": _project_path(), "details": open_info},
    }
    expected = []
    writes = []
    for item in _source_items(req):
        write = _write_pou_request(item)
        writes.append(write)
        expected.append({"name": write["name"], "hashes": write["readback"]})
    steps["write"] = writes

    read_after = []
    for entry in expected:
        pou = find_textual_object(entry["name"])
        if pou is None:
            raise RuntimeError("textual object disappeared after write: " + entry["name"])
        actual = read_st(pou)
        if not _hashes_match(actual, entry["hashes"]):
            raise RuntimeError("independent readback hash mismatch: " + entry["name"])
        read_after.append(actual)
    steps["readback"] = read_after

    build = _build_project()
    steps["build"] = build
    steps["diagnostics"] = build
    if not _compile_gate_passed(build):
        return False, steps, "build_failed", "build did not reach compileStatus=success"

    project.save()
    steps["save"] = {"saved": True}
    persisted_path = _project_path() or path
    if not persisted_path:
        raise RuntimeError("open project path is unavailable; pass projectPath explicitly")
    steps["close"] = _close_project_after_vendor_load()

    project, reopen_info = open_project_silent(persisted_path, req.get("password", ""))
    native_core_project = None
    pou_cache.clear()
    steps["reopen"] = {"projectPath": _project_path(), "open": reopen_info}
    persisted = []
    for entry in expected:
        pou = find_textual_object(entry["name"])
        if pou is None:
            raise RuntimeError("textual object missing after reopen: " + entry["name"])
        actual = read_st(pou)
        if not _hashes_match(actual, entry["hashes"]):
            raise RuntimeError("persisted readback hash mismatch: " + entry["name"])
        persisted.append(actual)
    steps["persistedReadback"] = persisted
    persisted_build = _build_project()
    steps["persistedBuild"] = persisted_build
    if not _compile_gate_passed(persisted_build):
        return False, steps, "persisted_build_failed", "reopened project did not compile successfully"
    return True, steps, None, None


