def _program_reader_module():
    import program_reader
    # Reload the read adapter on a bridge hot reload without restarting IDEs.
    try:
        import importlib
        return importlib.reload(program_reader)
    except (ImportError, AttributeError):
        return reload(program_reader)


def source_snapshot(req=None):
    _require_project()
    reader = _program_reader_module()
    targets = (req or {}).get("targets")
    if targets is not None:
        if not isinstance(targets, list) or not targets or len(targets) > 32:
            raise OperationError("source.snapshot targets must contain 1..32 paths", "invalid_argument")
    else:
        targets = [item.get("path") for item in list_textual_objects()]
    items = []
    for target in targets:
        obj, path = find_project_object(target)
        source = reader.text_view(obj, path, read_st, _get_member, _text)
        source["type"] = _object_type(obj)
        items.append(source)
    return {"count": len(items), "projectPath": _project_path(), "items": items,
            "complete": all(item["bodyComplete"] for item in items)}


def source_search(req):
    """Search textual project objects and return source-level evidence.

    This stays read-only and searches the ScriptEngine readback rather than
    the project file bytes, so matches are tied to the object/path and hash
    returned by the same bridge session.
    """
    _require_project()
    query = _text(req.get("query") or req.get("pattern"))
    if not query:
        raise OperationError("source.search requires query", "invalid_argument")
    regex_mode = bool(req.get("regex", False))
    case_sensitive = bool(req.get("caseSensitive", False))
    try:
        limit = int(req.get("maxResults", 200))
    except Exception:
        raise OperationError("maxResults must be an integer", "invalid_argument")
    limit = max(1, min(limit, 5000))
    flags = 0 if case_sensitive else re.IGNORECASE
    try:
        matcher = re.compile(query if regex_mode else re.escape(query), flags)
    except Exception as exc:
        raise OperationError(
            "invalid source.search pattern: " + _text(exc),
            "invalid_argument",
        )

    matches = []
    objects = list_textual_objects()
    for item in objects:
        obj, path = find_project_object(item.get("path"))
        source = read_st(obj)
        for section in ("declaration", "implementation"):
            text_value = source.get(section, "")
            for match in matcher.finditer(text_value):
                start = match.start()
                line = text_value.count("\n", 0, start) + 1
                line_start = text_value.rfind("\n", 0, start) + 1
                line_end = text_value.find("\n", match.end())
                if line_end < 0:
                    line_end = len(text_value)
                matches.append({
                    "path": path,
                    "name": source.get("name"),
                    "section": section,
                    "line": line,
                    "column": start - line_start + 1,
                    "match": match.group(0),
                    "lineText": text_value[line_start:line_end],
                    "sha256": source.get(section + "Sha256"),
                })
                if len(matches) >= limit:
                    return {
                        "query": query,
                        "regex": regex_mode,
                        "caseSensitive": case_sensitive,
                        "truncated": True,
                        "count": len(matches),
                        "projectPath": _project_path(),
                        "matches": matches,
                    }
    return {
        "query": query,
        "regex": regex_mode,
        "caseSensitive": case_sensitive,
        "truncated": False,
        "count": len(matches),
        "projectPath": _project_path(),
        "matches": matches,
    }


def project_info():
    """Read project metadata exposed by the current ScriptEngine binding.

    CODESYS profiles do not expose one stable metadata object.  This tool
    therefore reports only fields that are actually readable from the live
    project object and explicitly lists fields that were not exposed.  It is
    intentionally read-only and must not infer metadata from the file name.
    """
    if project is None:
        raise OperationError(
            "project.info requires an open project",
            "project_required",
            {"next": "project.open or project.create_with_cpu"},
        )
    fields = (
        "name", "title", "author", "company", "version", "description",
        "created", "modified", "path", "dirty", "primary", "library",
    )
    metadata = {}
    unavailable = []
    probes = []
    for field in fields:
        value = _get_member(project, field, "get_" + field, None)
        if value is None or _text(value) == "":
            unavailable.append(field)
            probes.append({"field": field, "available": False})
            continue
        metadata[field] = _json_safe(value)
        probes.append({"field": field, "available": True})
    # Project metadata is exposed by ScriptProject.get_project_info(), not by
    # the root ScriptProject object in this InoProShop profile. Read that
    # object explicitly so save/reopen verification can observe the same
    # fields that project.set_info mutates.
    info_object = _get_member(project, "project_info", "get_project_info", None)
    info_fields = ("company", "title", "version", "author", "description")
    info_metadata = {}
    info_unavailable = []
    if info_object is not None:
        for field in info_fields:
            value = _get_member(info_object, field, "get_" + field, None)
            if value is None:
                info_unavailable.append(field)
            else:
                info_metadata[field] = _json_safe(value)
    else:
        info_unavailable = list(info_fields)
    # ``path`` is the one field required by the route contract; use the
    # canonical helper when a profile exposes it only through a wrapper.
    if not metadata.get("path") and _project_path():
        metadata["path"] = _project_path()
        if "path" in unavailable:
            unavailable.remove("path")
    return {
        "metadata": metadata,
        "projectInfo": info_metadata,
        "projectInfoAvailableFields": sorted(info_metadata.keys()),
        "projectInfoUnavailableFields": sorted(info_unavailable),
        "availableFields": sorted(metadata.keys()),
        "unavailableFields": sorted(set(unavailable)),
        "binding": "live_scriptengine_project_object",
        "probes": probes,
        "claims": {
            "readOnly": True,
            "fileNameInference": False,
            "fullMetadata": not bool(unavailable),
        },
    }


def project_set_info(req):
    """Set native project-information fields with exact live readback."""
    operation = "project.set_info"
    _require_current_disposable_project(req, operation)
    if _text(req.get("confirm")).strip() != "set_project_info":
        raise OperationError(
            "project.set_info requires confirm=set_project_info",
            "confirmation_required",
            {"requiredConfirm": "set_project_info"},
        )
    allowed = ("company", "title", "version", "author", "description")
    supplied = {field: req.get(field) for field in allowed if req.get(field) is not None}
    if not supplied:
        raise OperationError(
            "project.set_info requires at least one metadata field",
            "invalid_argument", {"fields": list(allowed)},
        )
    info = _get_member(project, "project_info", "get_project_info")
    if info is None:
        raise OperationError(
            "native project information object is unavailable",
            "project_info_unavailable",
        )
    before = {}
    for field in allowed:
        value = _get_member(info, field, "get_" + field)
        if value is not None:
            before[field] = _json_safe(value)
    attempts = []
    for field, value in supplied.items():
        text_value = _text(value)
        if field == "version" and not text_value:
            raise OperationError("version must not be empty", "invalid_argument", {"field": field})
        try:
            setattr(info, field, value if field != "version" else text_value)
            attempts.append({"field": field, "ok": True})
        except Exception as exc:
            attempts.append({"field": field, "ok": False, "error": repr(exc)})
            raise OperationError(
                "native project information setter failed: " + field,
                "project_info_write_failed",
                {"field": field, "attempts": attempts, "before": before},
            )
    after = {}
    mismatches = []
    for field in allowed:
        value = _get_member(info, field, "get_" + field)
        if value is not None:
            after[field] = _json_safe(value)
    for field, requested in supplied.items():
        expected = _text(requested)
        actual = _text(after.get(field))
        if field == "version":
            expected = expected.strip()
            actual = actual.strip()
        if actual != expected:
            mismatches.append({"field": field, "requested": expected, "actual": actual})
    if mismatches:
        raise OperationError(
            "project information native readback mismatch",
            "project_info_readback_mismatch",
            {"before": before, "after": after, "mismatches": mismatches},
        )
    return {
        "updated": True,
        "before": before,
        "after": after,
        "changedFields": sorted(supplied.keys()),
        "attempts": attempts,
        "saveRequired": True,
        "claims": {"nativeSetter": True, "exactReadback": True,
                   "saved": False, "freshProcessPersistence": False},
    }


def _textual_declaration_target(req, operation, require_exact_path=False):
    """Resolve one textual declaration object for a scoped ST edit."""
    _require_project()
    if require_exact_path:
        target = _text(req.get("target")).strip()
    else:
        target = _text(req.get("target") or req.get("name")).strip()
    if not target:
        raise OperationError(
            operation + " requires an exact target path",
            "invalid_argument",
            {"path": "target", "expected": "full slash-separated project path",
             "mutatedProject": False},
        )
    obj, path = find_project_object(target)
    normalized_target = target.replace("\\", "/").strip("/")
    if (require_exact_path and
            normalized_target.lower() != path.lower()):
        raise OperationError(
            operation + " requires an exact project-object path; short names are rejected",
            "exact_object_path_required",
            {"path": "target", "actual": target, "resolvedPath": path,
             "correctFormat": path, "mutatedProject": False},
        )
    document = _get_member(
        obj, "textual_declaration", "get_textual_declaration"
    )
    if document is None:
        raise OperationError(
            "target has no textual declaration: " + path,
            "textual_declaration_unavailable",
            {"target": target, "path": path},
        )
    return obj, path, document


def _restore_textual_declaration(path, target_guid, before, operation):
    """Restore one declaration and prove the restored object identity/text."""
    result = {
        "attempted": True,
        "complete": False,
        "target": path,
        "targetGuid": target_guid,
        "processDiscardRequired": True,
    }
    try:
        rebound, rebound_path = find_project_object(path)
        rebound_guid = _object_guid(rebound)
        if (rebound_path.lower() != path.lower() or not target_guid or
                not rebound_guid or rebound_guid.lower() != target_guid.lower()):
            raise RuntimeError("rollback target identity changed")
        document = _get_member(
            rebound, "textual_declaration", "get_textual_declaration"
        )
        result["write"] = _write_document(
            document, before, operation + ".rollback.declaration"
        )
        verified, verified_path = find_project_object(path)
        verified_guid = _object_guid(verified)
        if (verified_path.lower() != path.lower() or not verified_guid or
                verified_guid.lower() != target_guid.lower()):
            raise RuntimeError("rollback readback target identity changed")
        verified_document = _get_member(
            verified, "textual_declaration", "get_textual_declaration"
        )
        result["readback"] = _document_readback(
            verified_document, before,
            operation + ".rollback.declaration.readback",
        )
        result["complete"] = True
        result["processDiscardRequired"] = False
    except Exception as exc:
        result["error"] = repr(exc)
    return result


def _commit_textual_declaration(obj, path, document, before, expected,
                                operation, write_required=True):
    """Write one declaration and rebind the exact path/GUID before success."""
    target_guid = _object_guid(obj)
    if not target_guid:
        raise OperationError(
            "textual declaration target has no stable GUID",
            "textual_target_identity_unavailable",
            {"target": path, "mutatedProject": False},
        )
    try:
        if write_required:
            write = _write_document(document, expected, "declaration")
        else:
            _document_readback(document, expected, "declaration")
            write = None
        rebound, rebound_path = find_project_object(path)
        rebound_guid = _object_guid(rebound)
        exact_path = rebound_path.lower() == path.lower()
        guid_match = bool(
            rebound_guid and rebound_guid.lower() == target_guid.lower()
        )
        if not exact_path or not guid_match:
            raise RuntimeError("textual declaration target identity changed after write")
        rebound_document = _get_member(
            rebound, "textual_declaration", "get_textual_declaration"
        )
        declaration_readback = _document_readback(
            rebound_document, expected, "declaration.rebound"
        )
        return {
            "object": rebound,
            "source": read_st(rebound),
            "write": write,
            "targetGuid": target_guid,
            "target": {
                "name": _object_name(rebound),
                "path": rebound_path,
                "guid": rebound_guid,
                "exactPath": True,
                "guidMatch": True,
            },
            "declaration": declaration_readback,
        }
    except Exception as exc:
        if write_required:
            rollback = _restore_textual_declaration(
                path, target_guid, before, operation
            )
        else:
            rollback = {
                "attempted": False,
                "complete": True,
                "processDiscardRequired": False,
            }
        raise OperationError(
            operation + " could not prove exact native declaration readback",
            "declaration_write_readback_failed",
            {"target": path, "targetGuid": target_guid,
             "cause": repr(exc), "rollback": rollback,
             "mutatedProject": not rollback.get("complete"),
             "processDiscardRequired": rollback.get(
                 "processDiscardRequired", True)},
        )


def _raise_declaration_verification_failure(message, code, data, path,
                                            target_guid, before, operation):
    """Rollback a declaration whose semantic readback did not match."""
    rollback = _restore_textual_declaration(
        path, target_guid, before, operation
    )
    details = dict(data or {})
    details.update({
        "rollback": rollback,
        "mutatedProject": not rollback.get("complete"),
        "processDiscardRequired": rollback.get(
            "processDiscardRequired", True),
    })
    raise OperationError(message, code, details)


def pou_list_variables(req):
    """Read a structured, source-backed declaration inventory."""
    if parse_st_declaration is None:
        raise OperationError(
            "ST declaration parser module is unavailable",
            "st_declaration_tools_unavailable",
        )
    obj, path, _document = _textual_declaration_target(
        req, "pou.list_variables"
    )
    source = read_st(obj)
    variables = parse_st_declaration(source.get("declaration", ""))
    return {
        "target": path,
        "name": source.get("name"),
        "count": len(variables),
        "variables": variables,
        "declarationSha256": source.get("declarationSha256"),
        "claims": {
            "sourceBacked": True,
            "semanticTypeCheck": False,
            "runtimeMappingCheck": False,
        },
    }


def pou_add_variable(req):
    """Insert one ST declaration and require native exact text readback."""
    if (rewrite_add_variable is None or parse_st_declaration is None or
            declaration_target_kind is None):
        raise OperationError(
            "ST declaration rewrite module is unavailable",
            "st_declaration_tools_unavailable",
        )
    obj, path, document = _textual_declaration_target(
        req, "pou.add_variable", require_exact_path=True
    )
    name = _text(req.get("variable")).strip()
    var_type = _text(req.get("type")).strip()
    if not name or not var_type:
        raise OperationError(
            "pou.add_variable requires variable/name and type",
            "invalid_argument",
            {"variable": name, "type": var_type},
        )
    before = _document_text(document)
    target_kind = declaration_target_kind(before)
    if target_kind not in ("pou", "gvl"):
        # E2E V2 R037: targetKind "unknown" is most often a GVL whose
        # declaration pane lacks the VAR_GLOBAL ... END_VAR wrapper — the
        # old message pointed at DUT and sent the model on a wrong path.
        hint = ""
        if _text(target_kind) == "unknown" and not re.search(
                r"\bVAR_GLOBAL\b", before):
            hint = ("; likely cause: this GVL's declaration pane lacks the "
                    "VAR_GLOBAL ... END_VAR wrapper (bare variable lines are "
                    "stored verbatim but stay INVISIBLE to the compiler)")
        raise OperationError(
            "pou.add_variable only supports POU and GVL declaration shapes; "
            "this target must be edited with a DUT-specific operation" + hint,
            "declaration_target_unsupported",
            {"target": path, "targetKind": target_kind,
             "supportedKinds": ["pou", "gvl"], "mutatedProject": False},
        )
    requested_section = req.get("section")
    if target_kind == "gvl":
        if requested_section is not None and _text(requested_section).upper() != "VAR_GLOBAL":
            raise OperationError(
                "GVL variables must be declared in VAR_GLOBAL",
                "gvl_section_invalid",
                {"target": path, "actual": requested_section,
                 "correctFormat": "section=VAR_GLOBAL", "mutatedProject": False},
            )
        requested_section = "VAR_GLOBAL"
    elif requested_section is None:
        requested_section = "VAR"
    try:
        expected, mutation = rewrite_add_variable(
            before, name, var_type, requested_section,
            req.get("init"), req.get("comment"), req.get("pragma"),
        )
    except ValueError as exc:
        message = _text(exc)
        code = "variable_already_exists" if message.startswith(
            "variable already exists:"
        ) else "invalid_variable_declaration"
        raise OperationError(message, code, {"target": path, "variable": name})
    transaction = _commit_textual_declaration(
        obj, path, document, before, expected, "pou.add_variable"
    )
    source = transaction["source"]
    variables = parse_st_declaration(source.get("declaration", ""))
    exact = [item for item in variables if item.get("name", "").lower() ==
             mutation.get("name", "").lower()]
    if len(exact) != 1:
        _raise_declaration_verification_failure(
            "native declaration readback did not contain exactly one new variable",
            "variable_readback_mismatch",
            {"target": path, "variable": mutation.get("name"),
             "matches": exact}, path, transaction["targetGuid"], before,
            "pou.add_variable",
        )
    return {
        "target": path,
        "targetGuid": transaction["targetGuid"],
        "input": {"target": path, "variable": mutation.get("name"),
                  "type": var_type},
        "mutation": mutation,
        "beforeDeclarationSha256": _sha256(before),
        "write": transaction["write"],
        "mutatedProject": True,
        "readback": {
            "target": transaction["target"],
            "declarationSha256": source.get("declarationSha256"),
            "declarationCanonicalMatch": transaction[
                "declaration"].get("canonicalMatch") is True,
            "variable": exact[0],
            "exactOneMatch": True,
        },
        "compileRequired": True,
        "claims": {
            "declarationTextReadback": True,
            "exactTargetReadback": True,
            "rollbackOnFailure": True,
            "precompileVerified": False,
            "compileVerified": False,
            "symbolConfigurationVerified": False,
        },
    }


def pou_add_symbol_pragma(req):
    """Add one CODESYS symbol pragma with native declaration readback."""
    if (rewrite_symbol_pragma is None or parse_st_declaration is None or
            declaration_target_kind is None):
        raise OperationError(
            "ST declaration rewrite module is unavailable",
            "st_declaration_tools_unavailable",
        )
    obj, path, document = _textual_declaration_target(
        req, "pou.add_symbol_pragma", require_exact_path=True
    )
    name = _text(req.get("variable")).strip()
    if not name:
        raise OperationError(
            "pou.add_symbol_pragma requires variable/name", "invalid_argument"
        )
    before = _document_text(document)
    target_kind = declaration_target_kind(before)
    if target_kind not in ("pou", "gvl"):
        raise OperationError(
            "pou.add_symbol_pragma only supports POU and GVL declaration "
            "shapes; this target must be edited with a DUT-specific operation",
            "declaration_target_unsupported",
            {"target": path, "targetKind": target_kind,
             "supportedKinds": ["pou", "gvl"], "mutatedProject": False},
        )
    try:
        expected, mutation = rewrite_symbol_pragma(
            before, name, req.get("access", "readwrite")
        )
    except ValueError as exc:
        message = _text(exc)
        code = "variable_not_found" if message.startswith(
            "variable not found"
        ) else "invalid_symbol_pragma"
        raise OperationError(message, code, {"target": path, "variable": name})
    write = None
    transaction = None
    if mutation.get("changed"):
        transaction = _commit_textual_declaration(
            obj, path, document, before, expected,
            "pou.add_symbol_pragma"
        )
        write = transaction["write"]
    else:
        transaction = _commit_textual_declaration(
            obj, path, document, before, expected,
            "pou.add_symbol_pragma", write_required=False
        )
    source = transaction["source"]
    variables = parse_st_declaration(source.get("declaration", ""))
    matches = [item for item in variables if item.get("name", "").lower() ==
               mutation.get("name", "").lower()]
    expected_pragma = mutation.get("pragma", "").lower()
    retained = len(matches) == 1 and _text(matches[0].get("pragma")).lower() == expected_pragma
    if not retained:
        _raise_declaration_verification_failure(
            "native declaration readback did not retain symbol pragma",
            "symbol_pragma_readback_mismatch",
            {"target": path, "variable": name, "matches": matches,
             "expectedPragma": mutation.get("pragma")}, path,
            transaction["targetGuid"], before, "pou.add_symbol_pragma",
        )
    return {
        "target": path,
        "targetGuid": transaction["targetGuid"],
        "input": {"target": path, "variable": mutation.get("name")},
        "mutation": mutation,
        "beforeDeclarationSha256": _sha256(before),
        "write": write,
        "mutatedProject": mutation.get("changed") is True,
        "readback": {
            "target": transaction["target"],
            "declarationSha256": source.get("declarationSha256"),
            "declarationCanonicalMatch": transaction[
                "declaration"].get("canonicalMatch") is True,
            "variable": matches[0],
            "pragmaRetained": True,
        },
        "compileRequired": True,
        "claims": {
            "declarationTextReadback": True,
            "exactTargetReadback": True,
            "rollbackOnFailure": True,
            "symbolExportConfigurationVerified": False,
            "onlineSymbolAvailabilityVerified": False,
        },
    }


def export_project_xml(req):
    _require_project()
    path = req.get("path")
    target = req.get("target")
    if not path:
        raise RuntimeError("project.export_xml requires path")
    if not target:
        raise RuntimeError("project.export_xml requires target")
    obj, object_path = find_project_object(target)
    parent = os.path.dirname(path)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent)
    if os.path.exists(path):
        if not bool(req.get("overwrite", False)):
            raise RuntimeError("destination exists; set overwrite=true")
        os.remove(path)
    recursive = bool(req.get("recursive", False))
    folders = bool(req.get("exportFolderStructure", False))
    plaintext = bool(req.get("declarationsAsPlaintext", True))
    attempts = []
    native_matches = project.find(_object_name(obj), True)
    calls = (
        ("object_explicit_none", lambda: obj.export_xml(
            None, path, recursive, folders, plaintext
        )),
        ("project_explicit_none", lambda: project.export_xml(
            None, native_matches, path, recursive, folders, plaintext
        )),
        ("project_reporter_free", lambda: project.export_xml(
            native_matches, path, recursive, folders, plaintext
        )),
    )
    method = None
    for label, call in calls:
        try:
            if os.path.exists(path):
                os.remove(path)
            call()
            if os.path.isfile(path):
                method = label
                break
            attempts.append({"method": label, "error": "destination not created"})
        except Exception as exc:
            attempts.append({"method": label, "error": repr(exc)})
    if method is None:
        raise OperationError(
            "InoProShop SP11 did not bind any PLCopenXML export overload; no file was created",
            "plcopen_xml_export_binding_unavailable",
            {
                "mutatedProject": False,
                "fileCreated": False,
                "path": path,
                "target": object_path,
                "attempts": attempts,
                "recovery": "use project.export_native for the verified InoProShop structured-view exchange route",
            },
        )
    if not os.path.isfile(path):
        raise RuntimeError("export_xml returned without creating destination")
    with open(path, "rb") as exported:
        raw = exported.read()
    # Return the small structural witness the model needs for a native LAD
    # readback.  Without this, callers export the XML and then fall back to a
    # generic shell/grep round-trip just to count networks and TON/coil shapes.
    # Keep it deliberately narrow and derived from the bytes that were hashed.
    text = raw.decode("utf-8", "replace")
    comments = [value for value in re.findall(
        r'<Single Name="Comment" Type="string">([^<]*)</Single>', text
    ) if value.strip()]
    graph_evidence = {
        "networkItemsCount": text.count('<List2 Name="NetworkItems">'),
        "networkCommentCount": len(comments),
        "networkComments": comments,
        "rvalueCount": text.count('Name="RValue"'),
        "functionBlockCount": text.count('CallType" Type="{bffb3c53-f105-4e85-aba2-e30df579d75f}">FunctionBlock'),
        "coilCount": text.count('IsCoil" Type="bool">True'),
    }
    return {
        "exported": True,
        "target": object_path,
        "path": path,
        "bytes": len(raw),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "recursive": recursive,
        "exportFolderStructure": folders,
        "declarationsAsPlaintext": plaintext,
        "binding": method,
        "failedBindings": attempts,
        "graphEvidence": graph_evidence,
    }


def _project_file_readback(path):
    """Return disk evidence for one project file after a synchronous save."""
    resolved = os.path.normcase(os.path.abspath(_text(path))) if path else ""
    if not resolved or not os.path.isfile(resolved):
        return {"path": resolved or None, "exists": False, "bytes": None,
                "sha256": None, "mtime": None}
    with open(resolved, "rb") as stream:
        raw = stream.read()
    return {
        "path": resolved,
        "exists": True,
        "bytes": len(raw),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "mtime": os.path.getmtime(resolved),
    }


def _project_dirty_readback():
    value = _get_member(project, "dirty", "get_dirty", None)
    return bool(value) if value is not None else None


def save_project():
    _require_project()
    requested_path = _project_path()
    if not requested_path:
        raise OperationError("open project path is unavailable",
                             "project_path_unavailable")
    dirty_before = _project_dirty_readback()
    project.save()
    project_path = _project_path()
    file_readback = _project_file_readback(project_path)
    dirty_after = _project_dirty_readback()
    same_path = bool(
        project_path and
        os.path.normcase(os.path.abspath(project_path)) ==
        os.path.normcase(os.path.abspath(requested_path))
    )
    if (not same_path or not file_readback.get("exists") or
            not file_readback.get("bytes") or dirty_after is not False):
        raise OperationError(
            "project.save returned without a clean project and file readback",
            "project_save_readback_failed",
            {"requestedPath": requested_path, "projectPath": project_path,
             "samePath": same_path, "dirtyBefore": dirty_before,
             "dirtyAfter": dirty_after, "fileReadback": file_readback},
        )
    return {
        "saved": True,
        "projectPath": project_path,
        "requestedPath": requested_path,
        "samePath": True,
        "dirtyBefore": dirty_before,
        "dirtyAfter": False,
        "fileReadback": file_readback,
    }


def save_project_as(req):
    _require_project()
    path = req.get("path")
    if not path:
        raise OperationError("project.save_as requires path", "invalid_argument")
    path = _require_disposable_destination_path(path, "project.save_as")
    if os.path.exists(path) and not bool(req.get("overwrite", False)):
        raise OperationError("destination exists; set overwrite=true",
                             "destination_exists", {"path": path})
    parent = os.path.dirname(path)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent)
    if os.path.exists(path):
        os.remove(path)
    password = req.get("password") if "password" in req else None
    dirty_before = _project_dirty_readback()
    project.save_as(path, password)
    project_path = _project_path()
    file_readback = _project_file_readback(path)
    dirty_after = _project_dirty_readback()
    same_path = bool(
        project_path and
        os.path.normcase(os.path.abspath(project_path)) ==
        os.path.normcase(os.path.abspath(path))
    )
    if (not same_path or not file_readback.get("exists") or
            not file_readback.get("bytes") or dirty_after is not False):
        raise OperationError(
            "project.save_as returned without exact path and file readback",
            "project_save_as_readback_failed",
            {"requestedPath": path, "projectPath": project_path,
             "samePath": same_path, "dirtyBefore": dirty_before,
             "dirtyAfter": dirty_after, "fileReadback": file_readback},
        )
    return {
        "savedAs": True,
        "projectPath": project_path,
        "requestedPath": path,
        "samePath": True,
        "dirtyBefore": dirty_before,
        "dirtyAfter": False,
        "fileReadback": file_readback,
    }


def _import_tree_snapshot():
    flat = []
    _walk_objects(project, [], 1, 64, flat)
    rows = []
    for path, obj in flat:
        declaration = _document_text(_get_member(
            obj, "textual_declaration", "get_textual_declaration"))
        implementation = _document_text(_get_member(
            obj, "textual_implementation", "get_textual_implementation"))
        rows.append({
            "path": path,
            "pathKey": path.lower(),
            "guid": _object_guid(obj),
            "type": _object_type(obj),
            "name": _object_name(obj),
            "sourceSha256": _sha256(declaration + "\x00" + implementation),
            "object": obj,
        })
    return rows


def _import_tree_key(row):
    guid = _text(row.get("guid")).strip().lower()
    return ("guid", guid) if guid else ("path", row.get("pathKey"))


def _import_tree_delta(before, after):
    before_map = dict((_import_tree_key(row), row) for row in before)
    after_map = dict((_import_tree_key(row), row) for row in after)
    added = [row for key, row in after_map.items() if key not in before_map]
    removed = [row for key, row in before_map.items() if key not in after_map]
    changed = []
    for key in set(before_map).intersection(after_map):
        left = before_map[key]
        right = after_map[key]
        if (left.get("pathKey") != right.get("pathKey") or
                left.get("sourceSha256") != right.get("sourceSha256")):
            changed.append(right)

    def public_rows(rows):
        return [{"path": row.get("path"), "guid": row.get("guid"),
                 "type": row.get("type"), "name": row.get("name")}
                for row in rows]

    return {
        "added": public_rows(added),
        "removed": public_rows(removed),
        "changed": public_rows(changed),
        "addedCount": len(added),
        "removedCount": len(removed),
        "changedCount": len(changed),
        "mutationObserved": bool(added or removed or changed),
    }


def _rollback_import_additions(before):
    """Remove only roots introduced after the pre-import tree snapshot."""
    before_keys = set(_import_tree_key(row) for row in before)
    after = _import_tree_snapshot()
    added = [row for row in after if _import_tree_key(row) not in before_keys]
    added_paths = set(row["pathKey"] for row in added)
    roots = []
    seen = set()
    for row in sorted(added, key=lambda item: item["pathKey"].count("/")):
        parts = row["pathKey"].split("/")
        if any("/".join(parts[:index]) in added_paths
               for index in range(1, len(parts))):
            continue
        key = _import_tree_key(row)
        if key not in seen:
            seen.add(key)
            roots.append(row)
    attempts = []
    for row in roots:
        try:
            row["object"].remove()
            attempts.append({"path": row["path"], "guid": row["guid"],
                             "removed": True})
        except Exception as exc:
            attempts.append({"path": row["path"], "guid": row["guid"],
                             "removed": False, "error": repr(exc)})
    pou_cache.clear()
    remaining = [
        {"path": row["path"], "guid": row["guid"]}
        for row in _import_tree_snapshot()
        if _import_tree_key(row) not in before_keys
    ]
    complete = not remaining and all(item.get("removed") for item in attempts)
    return {
        "attempted": bool(roots),
        "complete": complete,
        "attempts": attempts,
        "remaining": remaining,
        "processDiscardRequired": not complete,
    }


def _expected_import_path(parent_path, expected_name):
    expected = _text(expected_name).strip().replace("\\", "/").strip("/")
    if not expected:
        raise OperationError("expectedName is required for exact import readback",
                             "invalid_argument", {"path": "expectedName"})
    if "/" in expected or not parent_path:
        return expected
    return parent_path.rstrip("/") + "/" + expected


def _find_exact_import_target(expected_path):
    try:
        obj, path = find_project_object(expected_path)
    except Exception:
        return None, None
    if path.lower() != expected_path.lower():
        return None, path
    return obj, path


def _import_target_receipt(expected_path, obj, path):
    expected_name = expected_path.rsplit("/", 1)[-1]
    return {
        "present": obj is not None,
        "exactPath": bool(path and path.lower() == expected_path.lower()),
        "exactName": bool(obj is not None and _object_name(obj) == expected_name),
        "nonemptyGuid": bool(obj is not None and _object_guid(obj)),
        "expectedPath": expected_path,
        "object": _object_summary(obj, path) if obj is not None else None,
    }


def import_project_xml(req):
    _require_project()
    source = req.get("path") or req.get("xml")
    if not source:
        raise OperationError("project.import_xml requires path or xml",
                             "invalid_argument")
    if req.get("path") and not os.path.isfile(source):
        raise OperationError("PLCopenXML file not found: " + source,
                             "source_not_found", {"path": source})
    target = req.get("parent")
    if target:
        container, parent_path = find_project_object(target)
    else:
        container, parent_path = project, None
    expected_path = _expected_import_path(
        parent_path, req.get("expectedName"))
    before_target, before_target_path = _find_exact_import_target(expected_path)
    folders = bool(req.get("importFolderStructure", False))
    conflict_name = _text(req.get("conflictResolve", "copy")).strip().lower()
    if conflict_name not in ("copy", "replace", "skip"):
        raise OperationError(
            "project.import_xml conflictResolve must be copy, replace, or skip",
            "invalid_argument", {"path": "conflictResolve",
                                 "actual": conflict_name})
    if conflict_name == "copy" and before_target is not None:
        raise OperationError(
            "copy import requires an absent exact expected target",
            "import_target_exists",
            {"expectedPath": expected_path, "mutatedProject": False})
    if conflict_name == "skip" and before_target is None:
        raise OperationError(
            "skip import requires the exact target to exist before import",
            "import_skip_target_missing",
            {"expectedPath": expected_path, "mutatedProject": False})
    before = _import_tree_snapshot()
    dirty_before = _project_dirty_readback()
    binding = "reporter_free_copy"
    try:
        if conflict_name == "copy":
            result = container.import_xml(source, folders)
        else:
            conflict_value = (ConflictResolve.Replace
                              if conflict_name == "replace"
                              else ConflictResolve.Skip)
            binding = "conflict_first_" + conflict_name
            result = container.import_xml(conflict_value, source, folders)
    except Exception as exc:
        rollback = _rollback_import_additions(before)
        raise OperationError(
            "PLCopenXML import failed through the single verified binding",
            "project_import_xml_failed",
            {"binding": binding, "cause": repr(exc), "rollback": rollback,
             "mutatedProject": not rollback.get("complete"),
             "processDiscardRequired": rollback.get("processDiscardRequired")},
        )
    pou_cache.clear()
    imported, imported_path = _find_exact_import_target(expected_path)
    declaration_write = None
    auto_added_libraries = []
    if conflict_name == "copy" and imported is not None:
        repair = _nwl_plcopen_import_source_details(
            source, expected_path.rsplit("/", 1)[-1])
        if repair.get("ok"):
            for namespace in repair.get("namespaces", []):
                try:
                    auto = _nwl_auto_add_installed_library(
                        {"disposable": True}, namespace)
                except Exception as exc:
                    auto = {"ok": False, "error": repr(exc),
                            "namespace": namespace, "attempted": True}
                if auto.get("ok"):
                    auto_added_libraries.append({
                        "namespace": namespace,
                        "name": auto.get("name"),
                        "resolution": auto.get("resolution"),
                        "projectAdded": bool((auto.get("result") or {}).get("added")),
                    })
            if repair.get("declaration"):
                declaration_doc = _nwl_declaration_document(imported)
                if declaration_doc is not None:
                    try:
                        declaration_write = _write_document(
                            declaration_doc, repair.get("declaration"),
                            "declaration")
                    except Exception as exc:
                        rollback = _rollback_import_additions(before)
                        rollback_libraries = _nwl_rollback_auto_added_libraries(
                            {"disposable": True}, auto_added_libraries)
                        raise OperationError(
                            "PLCopenXML import declaration repair failed",
                            "project_import_xml_repair_failed",
                            {"binding": binding, "cause": repr(exc),
                             "rollback": rollback,
                             "autoAddedLibraries": auto_added_libraries,
                             "autoAddedLibraryRollback": rollback_libraries,
                             "mutatedProject": not rollback.get("complete"),
                             "processDiscardRequired": rollback.get("processDiscardRequired")},
                        )
    pou_cache.clear()
    after = _import_tree_snapshot()
    delta = _import_tree_delta(before, after)
    receipt = _import_target_receipt(expected_path, imported, imported_path)
    dirty_after = _project_dirty_readback()
    skip_verified = bool(
        conflict_name == "skip" and before_target is not None and
        imported is not None and
        _object_guid(before_target) == _object_guid(imported) and
        before_target_path.lower() == imported_path.lower())
    mutation_observed = bool(delta.get("mutationObserved") or
                             (dirty_before is False and dirty_after is True))
    exact_target = all(receipt.get(field) is True for field in (
        "present", "exactPath", "exactName", "nonemptyGuid"))
    if (not exact_target or
            (conflict_name != "skip" and not mutation_observed) or
            (conflict_name == "skip" and not skip_verified)):
        rollback = (_rollback_import_additions(before)
                    if conflict_name == "copy" else {
                        "attempted": False, "complete": False,
                        "processDiscardRequired": True,
                        "reason": "replace/skip cannot be reversed without the original serialized object",
                    })
        raise OperationError(
            "PLCopenXML import returned without proving the requested target state",
            "project_import_xml_readback_failed",
            {"binding": binding, "expectedPath": expected_path,
             "targetStateReadback": receipt, "treeDelta": delta,
             "dirtyBefore": dirty_before, "dirtyAfter": dirty_after,
             "rollback": rollback,
             "mutatedProject": not rollback.get("complete"),
             "processDiscardRequired": rollback.get("processDiscardRequired")},
        )
    skipped = conflict_name == "skip"
    return {
        "status": "skipped_existing" if skipped else "imported",
        "imported": not skipped,
        "alreadyPresent": skipped,
        "mutatedProject": not skipped,
        "mutationObserved": mutation_observed if not skipped else False,
        "singleBindingAttempted": True,
        "source": req.get("path") or "inline_xml",
        "parent": parent_path,
        "expectedName": req.get("expectedName"),
        "importedPath": imported_path,
        "targetStateReadback": receipt,
        "treeDelta": delta,
        "dirtyBefore": dirty_before,
        "dirtyAfter": dirty_after,
        "importFolderStructure": folders,
        "conflictResolve": conflict_name,
        "declarationRepaired": declaration_write is not None,
        "autoAddedLibraries": auto_added_libraries,
        "result": _json_safe(result),
        "binding": binding,
        "failedBindings": [],
    }


def export_project_native(req):
    _require_project()
    _require_current_disposable_project(req, "project.export_native")
    if _text(req.get("confirm")).strip() != "export_native_project_xml":
        raise OperationError(
            "project.export_native requires confirm=export_native_project_xml",
            "confirmation_required",
            {"mutatedProject": False, "fileWriteAttempted": False},
        )
    path = req.get("path")
    target = req.get("target")
    if not path:
        raise RuntimeError("project.export_native requires path")
    if not target:
        raise RuntimeError("project.export_native requires target")
    path = _require_disposable_destination_path(path, "project.export_native")
    obj, object_path = find_project_object(target)
    parent = os.path.dirname(path)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent)
    if os.path.exists(path):
        if not bool(req.get("overwrite", False)):
            raise RuntimeError("destination exists; set overwrite=true")
        os.remove(path)
    recursive = bool(req.get("recursive", False))
    attempts = []
    method = None
    for label, call in (
            ("object_explicit_none", lambda: obj.export_native(
                path, recursive, None, None
            )),
            ("object_defaults", lambda: obj.export_native(path, recursive))):
        try:
            if os.path.exists(path):
                os.remove(path)
            call()
            if os.path.isfile(path):
                method = label
                break
            attempts.append({"method": label, "error": "destination not created"})
        except Exception as exc:
            attempts.append({"method": label, "error": repr(exc)})
    if method is None:
        raise RuntimeError("all export_native bindings failed: " + _text(attempts))
    with open(path, "rb") as exported:
        raw = exported.read()
    return {
        "exported": True,
        "format": "inoproshop_native_xml",
        "target": object_path,
        "path": path,
        "bytes": len(raw),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "recursive": recursive,
        "binding": method,
        "failedBindings": attempts,
    }


def import_project_native(req):
    _require_project()
    paths = req.get("paths")
    if paths is not None:
        if not isinstance(paths, list) or not paths or not all(isinstance(item, str) for item in paths):
            raise RuntimeError("project.import_native paths must be a non-empty string array")
        import_paths = paths
    else:
        path = req.get("path")
        if not path:
            raise RuntimeError("project.import_native requires path or paths")
        import_paths = [path]
    for import_path in import_paths:
        if not os.path.isfile(import_path):
            raise RuntimeError("native XML file not found: " + import_path)
    target = req.get("parent")
    container, parent_path = find_project_object(target) if target else (project, None)
    attempts = []
    binding = None
    result = None
    replaced_existing = None
    expected_name = req.get("expectedName")
    if expected_name:
        # Same-name pre-delete: importing over an existing object raises a
        # vendor modal dialog ("导入的一个或多个对象已经存在") that blocks
        # unattended automation. Remove EVERY existing object with that name
        # first (this operation is disposable+confirm gated at the dispatch
        # boundary) and prove absence before importing. A broken earlier
        # import can leave DUPLICATES, so a single find_project_object match
        # is not enough — walk the parent and remove all matches.
        existing_removed = []
        try:
            flat = []
            _walk_objects(container, [], 1, 64, flat)
            name_matches = [(path, obj) for path, obj in flat
                            if _object_name(obj) == expected_name]
            for match_path, match_obj in name_matches:
                match_guid = _object_guid(match_obj)
                match_obj.remove()
                existing_removed.append({
                    "name": expected_name, "path": match_path,
                    "guid": match_guid,
                })
        except Exception:
            # Fall back to the single-match path when the walk fails.
            try:
                existing, existing_path = find_project_object(expected_name)
            except OperationError:
                existing = None
            if existing is not None:
                existing_removed.append({
                    "name": _object_name(existing), "path": existing_path,
                    "guid": _object_guid(existing),
                })
                existing.remove()
        if existing_removed:
            pou_cache.clear()
            # Prove absence for the last removed path.
            try:
                remaining, _remaining_path = find_project_object(
                    existing_removed[-1]["path"])
            except OperationError:
                remaining = None
            if remaining is not None:
                raise OperationError(
                    "existing object was not removed before re-import",
                    "object_delete_readback_failed",
                    {"path": existing_removed[-1]["path"],
                     "removed": existing_removed,
                     "mutatedProject": True},
                )
            replaced_existing = existing_removed[0]
            replaced_existing["count"] = len(existing_removed)
    if len(import_paths) > 1:
        bindings = (
            ("list_explicit_none", lambda: container.import_native(import_paths, None, None)),
            ("list_defaults", lambda: container.import_native(import_paths)),
        )
    else:
        path = import_paths[0]
        bindings = (
            ("single_explicit_none", lambda: container.import_native(path, None, None)),
            ("single_defaults", lambda: container.import_native(path)),
            ("list_explicit_none", lambda: container.import_native([path], None, None)),
        )
    for label, call in bindings:
        try:
            result = call()
            binding = label
            break
        except Exception as exc:
            attempts.append({"method": label, "error": repr(exc)})
    if binding is None:
        raise RuntimeError("all import_native bindings failed: " + _text(attempts))
    expected_name = req.get("expectedName")
    imported_path = None
    if expected_name:
        imported, imported_path = find_project_object(expected_name)
        if imported is None:
            raise RuntimeError("native import returned but expected object was not found: " + expected_name)
    return {
        "imported": True,
        "format": "inoproshop_native_xml",
        "path": import_paths[0] if len(import_paths) == 1 else None,
        "paths": import_paths,
        "count": len(import_paths),
        "parent": parent_path,
        "expectedName": expected_name,
        "importedPath": imported_path,
        "replacedExisting": replaced_existing,
        "result": _json_safe(result),
        "binding": binding,
        "failedBindings": attempts,
    }


def _lad_signature_identity(signature):
    """Return the context-independent identity of one serialized signature."""
    fields = (
        "name", "objectGuid", "parentObjectGuid", "pouType", "callType",
        "instanceRequirement", "inputs", "inouts", "outputs", "allInputs",
        "allOutputs", "runtimeType",
    )
    payload = dict((field, signature.get(field)) for field in fields)
    return json.dumps(payload, ensure_ascii=True, sort_keys=True,
                      separators=(",", ":"))


def _lad_signature_record_json(signature):
    """Canonicalize a complete bridge-issued signature for exact comparison."""
    return json.dumps(signature, ensure_ascii=True, sort_keys=True,
                      separators=(",", ":"))


def _select_trusted_lad_signature(instruction, provided, resolved):
    """Select only an unchanged signature from the current live query result."""
    instructions = resolved.get("instructions") or []
    candidates = []
    for item in instructions:
        for signature in item.get("signatures") or []:
            if (_text(signature.get("name")).strip().lower() ==
                    _text(instruction).strip().lower()):
                candidates.append(signature)
    if not candidates:
        raise OperationError(
            "instruction was not found in the installed LanguageModelMgr catalog",
            "instruction_not_found",
            {"instruction": instruction, "resolved": resolved,
             "mutatedProject": False},
        )
    if provided is None:
        selected = candidates[0]
        return selected, {
            "provided": False,
            "matchedLive": True,
            "contextVerified": True,
            "candidateCount": len(candidates),
            "contextSource": (selected.get("context") or {}).get("source"),
        }
    if not isinstance(provided, dict):
        raise OperationError(
            "signature must be the unchanged object returned by lad.instruction_signatures",
            "signature_record_invalid",
            {"actualType": _text(type(provided)), "mutatedProject": False},
        )
    provided_json = _lad_signature_record_json(provided)
    for candidate in candidates:
        if _lad_signature_record_json(candidate) == provided_json:
            # Use the newly queried record, not caller-owned data, even after
            # exact equality has proved that the request was not altered.
            return candidate, {
                "provided": True,
                "matchedLive": True,
                "contextVerified": True,
                "candidateCount": len(candidates),
                "contextSource": (candidate.get("context") or {}).get("source"),
            }
    same_identity_candidates = [
        candidate for candidate in candidates
        if _lad_signature_identity(candidate) == _lad_signature_identity(provided)
    ]
    context_mismatch = bool(
        same_identity_candidates and
        not any(candidate.get("context") == provided.get("context")
                for candidate in same_identity_candidates)
    )
    raise OperationError(
        "provided LAD signature does not exactly match the current live runtime record",
        "signature_context_mismatch" if context_mismatch else "signature_record_mismatch",
        {
            "instruction": instruction,
            "actualContext": provided.get("context"),
            "expectedContexts": [candidate.get("context") for candidate in candidates],
            "mutatedProject": False,
            "remediation": (
                "Pass one complete signature object returned by a fresh "
                "lad.instruction_signatures call without changing any field."
            ),
        },
    )


def lad_instruction_signatures(req):
    """Resolve installed LD/FBD instruction signatures through vendor API.

    This is the same LanguageModelMgr.FindSignaturesByName route used by the
    vendor's UpdateFBParams command.  It reports signatures and pins only; it
    never creates or changes a graphical object.
    """
    _require_project()
    names = req.get("names") or req.get("instructions") or []
    if isinstance(names, _STRING_TYPES):
        names = [names]
    if not isinstance(names, (list, tuple)) or not names:
        raise OperationError("lad.instruction_signatures requires names[]",
                             "invalid_argument", {"path": "names"})
    names = [_text(item).strip() for item in names if _text(item).strip()]
    if not names or len(names) > 200:
        raise OperationError("names must contain 1..200 instruction names",
                             "invalid_argument")
    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("Core SystemInstances type is unavailable",
                             "system_instances_unavailable")
    lm_prop = system_instances.GetProperty("LanguageModelMgr")
    if lm_prop is None:
        raise OperationError("SystemInstances.LanguageModelMgr is unavailable",
                             "language_model_manager_unavailable")
    manager = lm_prop.GetValue(None, None)
    if manager is None:
        raise OperationError("SystemInstances.LanguageModelMgr is null",
                             "language_model_manager_unavailable")
    handle = _get_member(project, "handle", "get_handle")
    if handle is None:
        handle = _get_member(native_core_project, "Handle", "get_Handle")
    if handle is None:
        raise OperationError("project handle is unavailable", "project_handle_unavailable")
    import System
    guid = System.Guid.Empty
    target = req.get("target") or req.get("pou")
    if target:
        obj, _path = find_project_object(target)
        guid = System.Guid(_object_guid(obj))
    methods = [m for m in manager.GetType().GetMethods()
               if m.Name == "FindSignaturesByName" and not m.IsGenericMethod]
    attempts = []
    # FindSignaturesByName returns ISignature objects without their owning
    # precompile context. Reconcile each result with the independently walked
    # live catalog so the public record carries the exact context provenance.
    catalog = lad_instruction_catalog({})
    catalog_by_identity = {}
    for catalog_signature in catalog.get("signatures") or []:
        key = _lad_signature_identity(catalog_signature)
        catalog_by_identity.setdefault(key, []).append(catalog_signature)
    unreconciled = []
    resolved = []
    for name in names:
        found = []
        for method in methods:
            params = method.GetParameters()
            raw_count = 0
            try:
                if len(params) == 3:
                    args = System.Array[System.Object]([System.Int32(int(handle)), guid, name])
                elif len(params) == 4:
                    # The vendor's TransformFA path calls the four-argument
                    # overload as (project, Guid.Empty, applicationGuid,
                    # name).  The second GUID is not the target POU GUID.
                    args = System.Array[System.Object]([
                        System.Int32(int(handle)), System.Guid.Empty, guid, name
                    ])
                else:
                    continue
                values = method.Invoke(manager, args)
                for signature in list(values or []):
                    raw_count += 1
                    query_record = _lad_catalog_signature(
                        signature,
                        {"source": "find_signatures_by_name:unreconciled"},
                        0,
                    )
                    matches = catalog_by_identity.get(
                        _lad_signature_identity(query_record), [])
                    if matches:
                        found.extend(matches)
                    else:
                        unreconciled.append({
                            "name": name,
                            "method": method.ToString(),
                            "identity": _lad_signature_identity(query_record),
                            "reason": "live signature context was not found in lad.instruction_catalog",
                        })
                attempts.append({"name": name, "method": method.ToString(),
                                 "rawCount": raw_count,
                                 "count": len(found), "ok": True})
                if found:
                    break
            except Exception as exc:
                attempts.append({"name": name, "method": method.ToString(),
                                 "ok": False, "error": repr(exc)})
        # A few vendor contexts return the same signature through more than
        # one overload. Keep distinct overloads, but remove exact duplicates
        # so generator callers receive a deterministic catalog.
        unique = []
        seen = set()
        for signature in found:
            # Comments/descriptions are not signature identity and a few
            # installed libraries expose them as legacy non-UTF8 byte text.
            # The canonical identity contains every callable/port field while
            # avoiding a read-only catalog failure on unrelated documentation.
            key = _lad_signature_identity(signature)
            if key in seen:
                continue
            seen.add(key)
            unique.append(signature)
        found = unique
        resolved.append({"requested": name, "count": len(found),
                         "status": "found" if found else "not_found",
                         "signatures": found})
    return {"status": "resolved", "binding": "SystemInstances.LanguageModelMgr.FindSignaturesByName",
            "projectHandle": _json_safe(handle), "target": target,
            "instructions": resolved, "attempts": attempts,
            "catalogBinding": catalog.get("binding"),
            "catalogSignatureCount": catalog.get("count"),
            "unreconciledSignatures": unreconciled,
            "mutatedProject": False,
            "next": "pass one unchanged signatures[] object as signature to lad.generate_instruction"}


def _lad_signature_variables(signature, field):
    """Return the exact IEC pins exposed by a runtime ISignature object."""
    result = []
    values = _get_member(signature, field, "get_" + field, [])
    try:
        for value in list(values or []):
            item = {
                "name": _text(_get_member(value, "OrgName", "get_OrgName", "")),
                "type": _text(_get_member(value, "Type", "get_Type", "")),
            }
            for prop in ("Name", "Flags", "IsInput", "IsOutput", "IsInOut", "DefaultValue"):
                actual = _get_member(value, prop, "get_" + prop)
                if actual is not None and _text(actual) != "":
                    item[prop[0].lower() + prop[1:]] = _text(actual)
            result.append(item)
    except Exception as exc:
        return [{"enumerationError": repr(exc)}]
    return result


def _lad_context_info(context, source_hint=""):
    """Serialize context identity without forcing CLR objects through JSON."""
    info = {"source": source_hint or "unknown",
            "runtimeType": _text(context.GetType().FullName) if context is not None else ""}
    for prop in ("ApplicationGuid", "LibraryGuid", "ObjectGuid", "Name", "LibraryName",
                 "ProjectName", "Version", "VersionString", "Placeholder", "Namespace"):
        value = _get_member(context, prop, "get_" + prop)
        if value is None:
            continue
        text = _text(value)
        if text:
            info[prop[0].lower() + prop[1:]] = text
    return info


def _lad_catalog_signature(signature, context_info, depth, gui_hidden=None):
    """Build a stable, generator-ready record from one live ISignature."""
    pou_type = _text(_get_member(signature, "POUType", "get_POUType", ""))
    context_record = dict(context_info) if isinstance(context_info, dict) else {}
    if not _text(context_record.get("source")).strip():
        context_record["source"] = "unresolved"
    record = {
        "name": _text(_get_member(signature, "Name", "get_Name", "")),
        "objectGuid": _text(_get_member(signature, "ObjectGuid", "get_ObjectGuid", "")),
        "parentObjectGuid": _text(_get_member(signature, "ParentObjectGuid", "get_ParentObjectGuid", "")),
        "pouType": pou_type,
        "callType": pou_type,
        "instanceRequirement": ("required" if pou_type == "FunctionBlock" else
                                 "context_dependent" if pou_type in ("Method", "Action") else
                                 "not_required" if pou_type in ("Function", "Property", "Program") else "unknown"),
        "inputs": _lad_signature_variables(signature, "Inputs"),
        "inouts": _lad_signature_variables(signature, "InOuts"),
        "outputs": _lad_signature_variables(signature, "Outputs"),
        "allInputs": _lad_signature_variables(signature, "AllInputs"),
        "allOutputs": _lad_signature_variables(signature, "AllOutputs"),
        "context": context_record,
        "depth": depth,
        "runtimeType": _text(signature.GetType().FullName),
    }
    if gui_hidden is not None:
        record["guiHidden"] = gui_hidden
    for prop in ("Comment", "Description", "Namespace", "LibraryName", "IsOperator", "IsHidden"):
        value = _get_member(signature, prop, "get_" + prop)
        if value is not None and _text(value) != "":
            record[prop[0].lower() + prop[1:]] = _text(value)
    return record


def lad_instruction_catalog(req):
    """Enumerate the installed runtime instruction catalog in one read call.

    The vendor LAD editor does not expose a static instruction list. Its own
    resolver walks LanguageModelMgr precompile contexts and their nested
    LibraryContexts, so this operation follows that same runtime route and
    returns generator-ready signatures instead of a guessed name list.
    """
    _require_project()
    system_instances = _reflection_type("_3S.CoDeSys.Core.SystemInstances, Core")
    if system_instances is None:
        raise OperationError("Core SystemInstances type is unavailable", "system_instances_unavailable")
    lm_prop = system_instances.GetProperty("LanguageModelMgr")
    manager = lm_prop.GetValue(None, None) if lm_prop is not None else None
    if manager is None:
        raise OperationError("LanguageModelMgr is unavailable", "language_model_manager_unavailable")
    import System
    contexts = []
    attempts = []
    seen_contexts = set()

    def add_context(value, source, depth=0):
        if value is None:
            return
        try:
            # Application/library contexts often share the same GUID fields
            # and CLR type. Use CLR object identity so separate loaded
            # libraries are not collapsed into one record.
            try:
                import System.Runtime.CompilerServices
                identity = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(value)
            except Exception:
                identity = id(value)
            key = "identity:" + _text(identity)
        except Exception:
            key = repr(value)
        if key in seen_contexts or depth > 8:
            return
        seen_contexts.add(key)
        info = _lad_context_info(value, source)
        contexts.append((value, info, depth))
        nested = _get_member(value, "LibraryContexts", "get_LibraryContexts", [])
        try:
            for child in list(nested or []):
                add_context(child, source + "/library", depth + 1)
        except Exception as exc:
            attempts.append({"source": source, "nestedError": repr(exc)})

    # The public manager overload is what the vendor navigator uses. Invoke
    # it reflectively so this remains compatible with the loaded profile's
    # exact interface version.
    for method in manager.GetType().GetMethods():
        if method.Name != "AllPreCompileContexts" or method.IsGenericMethod:
            continue
        params = method.GetParameters()
        if len(params) != 2:
            continue
        for include_projects, include_libraries in ((True, True), (True, False), (False, True), (False, False)):
            try:
                values = method.Invoke(manager, System.Array[System.Object]([include_projects, include_libraries]))
                count = 0
                for value in list(values or []):
                    add_context(value, "all_precompile_contexts:%s:%s" % (include_projects, include_libraries))
                    count += 1
                attempts.append({"method": method.ToString(), "includeProjects": include_projects,
                                 "includeLibraries": include_libraries, "ok": True, "count": count})
            except Exception as exc:
                attempts.append({"method": method.ToString(), "includeProjects": include_projects,
                                 "includeLibraries": include_libraries, "ok": False, "error": repr(exc)})

    # Ensure the active application and global/library contexts are present
    # even when the profile filters AllPreCompileContexts by visibility.
    app_guid = System.Guid.Empty
    try:
        app_obj, _ = find_project_object("Device/Plc Logic/Application")
        app_guid = System.Guid(_object_guid(app_obj))
    except Exception:
        pass
    get_pre = [m for m in manager.GetType().GetMethods()
               if m.Name == "GetPrecompileContext" and not m.IsGenericMethod]
    for guid, source in ((app_guid, "active_application"), (System.Guid.Empty, "global")):
        for method in get_pre:
            if len(method.GetParameters()) != 1:
                continue
            try:
                value = method.Invoke(manager, System.Array[System.Object]([guid]))
                add_context(value, source)
                break
            except Exception as exc:
                attempts.append({"method": method.ToString(), "source": source, "ok": False, "error": repr(exc)})
    library_root = _get_member(manager, "LibraryContexts", "get_LibraryContexts", [])
    try:
        for value in list(library_root or []):
            add_context(value, "manager_library", 0)
    except Exception as exc:
        attempts.append({"source": "manager_library", "error": repr(exc)})

    records = []
    seen = set()
    context_counts = []
    visibility_methods = [m for m in manager.GetType().GetMethods()
                          if m.Name == "IsHiddenSignature" and not m.IsGenericMethod
                          and len(m.GetParameters()) == 2]
    visibility_attempts = []

    def gui_hidden(signature):
        """Apply the same GUI hiding flag used by the vendor library browser."""
        if not visibility_methods:
            return None
        for method in visibility_methods:
            params = method.GetParameters()
            try:
                if not params[0].ParameterType.IsInstanceOfType(signature):
                    continue
                flag_type = params[1].ParameterType
                flag = System.Enum.ToObject(flag_type, System.Int64(-281474976251903))
                value = method.Invoke(manager, System.Array[System.Object]([signature, flag]))
                return bool(value)
            except Exception as exc:
                visibility_attempts.append({"method": method.ToString(), "error": repr(exc)})
        return None

    for context, context_info, depth in contexts:
        signatures = _get_member(context, "AllSignatures", "get_AllSignatures", [])
        count = 0
        try:
            for signature in list(signatures or []):
                record = _lad_catalog_signature(signature, context_info, depth, gui_hidden(signature))
                key = (record.get("objectGuid"), record.get("name"), record.get("pouType"),
                       json.dumps(record.get("inputs", []), sort_keys=True),
                       json.dumps(record.get("outputs", []), sort_keys=True))
                if key in seen:
                    continue
                seen.add(key)
                records.append(record)
                count += 1
        except Exception as exc:
            context_counts.append(dict(context_info, error=repr(exc), signatureCount=0))
            continue
        context_counts.append(dict(context_info, signatureCount=count))

    records.sort(key=lambda item: (item.get("name", "").upper(), item.get("pouType", ""), item.get("objectGuid", "")))
    by_type = {}
    by_source = {}
    common_namespaces = set((
        "STANDARD", "STANDARD64", "UTIL", "FPU", "CAA", "COMMFB",
        "TCP", "UDP", "SYSSOCKET", "SM3_BASIC", "SM3_RAMPS",
        "SM3_TRAJECTORYGENERATION", "IOSTANDARD", "CMPHSIO",
    ))
    common = []
    for item in records:
        by_type[item.get("pouType") or "unknown"] = by_type.get(item.get("pouType") or "unknown", 0) + 1
        source = (item.get("context") or {}).get("source") or "unknown"
        by_source[source] = by_source.get(source, 0) + 1
        namespace = (item.get("context") or {}).get("namespace") or ""
        # Empty namespace contains IEC numeric operators as well as runtime
        # helpers. Keep the public operator names and exclude compiler
        # internals beginning with an underscore.
        if (item.get("pouType") in ("Function", "FunctionBlock") and
                item.get("guiHidden") is not True and
                ((namespace in common_namespaces) or
                 (not namespace and not item.get("name", "").startswith("_")))):
            common.append(item)
    common.sort(key=lambda item: (item.get("name", "").upper(), item.get("pouType", ""), item.get("objectGuid", "")))
    common_by_namespace = {}
    for item in common:
        namespace = (item.get("context") or {}).get("namespace") or "<core>"
        common_by_namespace[namespace] = common_by_namespace.get(namespace, 0) + 1
    return {
        "status": "resolved",
        "binding": "LanguageModelMgr.AllPreCompileContexts/GetPrecompileContext",
        "applicationGuid": _text(app_guid),
        "contexts": context_counts,
        "signatures": records,
        "count": len(records),
        "common": common,
        "commonCount": len(common),
        "commonByNamespace": common_by_namespace,
        "commonSelection": {
            "callableOnly": True,
            "namespaces": sorted(common_namespaces),
            "coreRule": "empty namespace and name does not start with '_'",
        },
        "byPouType": by_type,
        "bySource": by_source,
        "attempts": attempts,
        "visibility": {"methodCount": len(visibility_methods),
                        "attempts": visibility_attempts,
                        "flag": -281474976251903,
                        "binding": "LanguageModelMgr.IsHiddenSignature"},
        "mutatedProject": False,
        "next": "pass a catalog signature to lad.native_generate_instruction",
    }


def lad_generate_add(req):
    """Generate, import, save, export and compile one parameterized ADD POU.

    PLCopen XML is the only graph-writing route currently backed by a real
    InoProShop import/readback/compile experiment.  The private native XML
    route remains export-only and is deliberately not used here.
    """
    _require_current_disposable_project(req, "lad.generate_add")
    if _text(req.get("confirm")).strip() != "generate_lad_add":
        raise OperationError("lad.generate_add requires confirm=generate_lad_add",
                             "confirmation_required")
    if generate_addition_xml is None:
        raise OperationError("PLCopen LAD generator module is unavailable",
                             "lad_generator_unavailable")
    name = _text(req.get("name") or "").strip()
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
        raise OperationError("lad.generate_add requires an IEC identifier name",
                             "invalid_argument", {"path": "name", "actual": name})
    parent = _text(req.get("parent") or "Device/Plc Logic/Application").strip()
    if parent == "Application":
        parent = "Device/Plc Logic/Application"
    if parent not in ("Device/Plc Logic/Application",):
        raise OperationError("lad.generate_add is verified only under Application",
                             "ui_visible_pou_parent_unverified", {"parent": parent})
    try:
        find_project_object(parent)
    except Exception:
        raise OperationError("LAD parent was not found", "parent_not_found", {"parent": parent})
    try:
        find_project_object(parent.rstrip("/") + "/" + name)
    except Exception:
        pass
    else:
        raise OperationError("LAD destination already exists", "destination_exists",
                             {"target": parent.rstrip("/") + "/" + name,
                              "mutatedProject": False})
    project_dir = os.path.dirname(_project_path())
    artifact_dir = os.path.join(project_dir, ".lad-generated")
    plcopen_path = _require_disposable_destination_path(
        os.path.join(artifact_dir, name + ".plcopen.xml"), "lad.generate_add")
    native_path = _require_disposable_destination_path(
        os.path.join(artifact_dir, name + ".native.xml"), "lad.generate_add")
    if os.path.exists(plcopen_path) or os.path.exists(native_path):
        if not bool(req.get("overwrite", False)):
            raise OperationError("generator artifact exists; set overwrite=true",
                                 "destination_exists", {"plcopenPath": plcopen_path,
                                                         "nativePath": native_path})
        for path in (plcopen_path, native_path):
            try:
                os.remove(path)
            except OSError:
                pass
    try:
        generated = generate_addition_xml(
            plcopen_path, name, req.get("left", "A"), req.get("right", "B"),
            req.get("output", "Result"), req.get("type", "INT"))
    except (ValueError, IOError, OSError) as exc:
        raise OperationError("LAD PLCopen generation rejected parameters",
                             "invalid_argument", {"error": _text(exc),
                                                     "mutatedProject": False})
    imported = import_project_xml({
        "path": plcopen_path, "parent": parent,
        "importFolderStructure": False, "conflictResolve": "copy",
        "expectedName": name})
    object_path = parent.rstrip("/") + "/" + name
    obj, object_path = find_project_object(object_path)
    exported = export_project_native({
        "target": object_path, "path": native_path, "recursive": True,
        "overwrite": True, "disposable": True,
        "confirm": "export_native_project_xml"})
    project.save()
    compiled = _build_project()
    diagnostics_complete = _compile_gate_passed(
        compiled, require_zero_warnings=True)
    ready = diagnostics_complete
    return {
        "status": "ready" if ready else "compile_blocked",
        "generated": generated,
        "imported": imported,
        "treePath": object_path,
        "treeVisible": True,
        "saved": True,
        "native": exported,
        "compile": compiled,
        "claims": {"plcopenGraphWritten": True, "nativeReadback": True,
                    "compileZeroErrorsWarnings": ready,
                    "precompileDiagnosticsComplete": diagnostics_complete},
    }


def lad_generate_instruction(req):
    """Resolve one live instruction signature, generate exact-port XML, and
    run the same import/native-readback/compile gates as the verified ADD
    route. This never accepts guessed port names or types.
    """
    _require_current_disposable_project(req, "lad.generate_instruction")
    if _text(req.get("confirm")).strip() != "generate_lad_instruction":
        raise OperationError("lad.generate_instruction requires confirm=generate_lad_instruction",
                             "confirmation_required")
    if generate_signature_xml is None:
        raise OperationError("signature LAD generator module is unavailable", "lad_generator_unavailable")
    instruction = _text(req.get("instruction") or req.get("name") or "").strip()
    name = _text(req.get("name") or ("LAD_" + re.sub(r"[^A-Za-z0-9_]", "_", instruction))).strip()
    if not instruction:
        raise OperationError("instruction is required", "invalid_argument", {"path": "instruction"})
    if not is_iec_identifier(name):
        raise OperationError(
            "name must be a non-reserved IEC identifier",
            "lad_plan_validation_failed",
            {"stage": "validate_plan", "mutatedProject": False,
             "errors": [{"code": "INVALID_POU_NAME", "path": "name",
                         "expected": "non-reserved IEC identifier", "actual": name,
                         "example": "LAD_NATIVE_TON",
                         "message": "invalid POU name",
                         "remediation": "Use letters, digits and underscores; start with a letter or underscore."}]})
    parent = _text(req.get("parent") or "Device/Plc Logic/Application").strip()
    if parent == "Application": parent = "Device/Plc Logic/Application"
    if parent != "Device/Plc Logic/Application":
        raise OperationError("signature generator is verified only under Application", "ui_visible_pou_parent_unverified", {"parent": parent})
    find_project_object(parent)
    object_path = parent.rstrip("/") + "/" + name
    try:
        find_project_object(object_path)
    except Exception:
        pass
    else:
        raise OperationError("LAD destination already exists", "destination_exists", {"target": object_path, "mutatedProject": False})
    resolved = lad_instruction_signatures({"names": [instruction], "target": req.get("scopeTarget") or req.get("target")})
    signature, signature_verification = _select_trusted_lad_signature(
        instruction, req.get("signature"), resolved)
    if validate_signature_request is None:
        raise OperationError("signature validator is unavailable",
                             "lad_validator_unavailable")
    validation = validate_signature_request(
        signature, req.get("inputs"), req.get("inouts"),
        req.get("outputs"), req.get("instance"),
        require_verified_derived_types=False,
    )
    if not validation.get("ok"):
        raise OperationError(
            "LAD plan validation failed; no XML or project write occurred",
            "lad_plan_validation_failed",
            {"stage": "validate_plan", "instruction": instruction,
             "errors": validation.get("errors", []),
             "normalized": validation.get("normalized"),
             "mutatedProject": False,
             "remediation": "Correct every reported path and retry."},
        )
    # Match the native route's dependency gate before synthesizing PLCopen
    # XML.  Without this check a library callable (for example COMMFB.ADDR)
    # can be accepted by the live signature lookup but silently disappear
    # during vendor import when its namespace is not referenced by the
    # disposable project.
    library_preflight = _nwl_signature_library_preflight(signature)
    if not library_preflight.get("ok"):
        raise OperationError(
            library_preflight.get("message") or
            "LAD project library dependency is missing",
            library_preflight.get("code") or
            "missing_project_library_reference",
            dict(library_preflight, stage="validate_dependencies",
                 instruction=instruction, mutatedProject=False,
                 remediation="Add the exact installed project library, then regenerate once."),
        )
    project_dir = os.path.dirname(_project_path())
    artifact = _require_disposable_destination_path(os.path.join(project_dir, ".lad-generated", name + ".plcopen.xml"), "lad.generate_instruction")
    if os.path.exists(artifact) and not bool(req.get("overwrite", False)):
        raise OperationError("generator artifact exists; set overwrite=true", "destination_exists", {"path": artifact})
    generated = generate_signature_xml(artifact, name, signature,
                                       req.get("inputs"), req.get("outputs"),
                                       req.get("instance"), req.get("inouts"))
    imported = import_project_xml({"path": artifact, "parent": parent, "importFolderStructure": False, "conflictResolve": "copy", "expectedName": name})
    obj, object_path = find_project_object(object_path)
    native_path = _require_disposable_destination_path(os.path.join(project_dir, ".lad-generated", name + ".native.xml"), "lad.generate_instruction")
    exported = export_project_native({"target": object_path, "path": native_path, "recursive": True, "overwrite": True, "disposable": True, "confirm": "export_native_project_xml"})
    project.save()
    compiled = _build_project()
    diagnostics_complete = _compile_gate_passed(
        compiled, require_zero_warnings=True)
    ready = diagnostics_complete
    return {"status": "ready" if ready else "compile_blocked", "instruction": instruction,
            "signature": signature, "signatureVerification": signature_verification,
            "generated": generated, "imported": imported, "treePath": object_path, "treeVisible": True,
            "native": exported, "compile": compiled, "claims": {"exactSignatureUsed": True, "nativeReadback": True,
            "compileZeroErrorsWarnings": ready,
            "precompileDiagnosticsComplete": diagnostics_complete}}


def lad_native_type_inventory(req=None):
    """Read the installed NWL graph CLR types by their serialized GUIDs.

    Native LAD exports preserve implementation, network, box and operand type
    GUIDs.  This inventory resolves those GUIDs in the loaded plugin so the
    native generator can use the vendor's own constructors instead of emitting
    guessed private XML.
    """
    _require_project()
    import System
    wanted = {
        "d9a99d73-b633-47db-b876-a752acb25871": "network",
        "9873c309-1f09-4ebf-9078-42d8057ef11b": "assignment",
        "acfc6f68-8e3a-4af5-bf81-3dd512095a46": "box",
        "c9b2f165-48a2-4a45-8326-3952d8a3d708": "operand",
        "f40d3e09-c02c-4522-a88c-dac23558cfc4": "outputs",
    }
    result = {"readOnly": True, "mutatedProject": False, "types": [],
              "assemblies": []}
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        full_name = _text(assembly.FullName)
        if "nwl" not in full_name.lower() and "implementation" not in full_name.lower():
            continue
        try:
            types = assembly.GetTypes()
        except Exception as exc:
            result["assemblies"].append({"assembly": full_name,
                                          "error": repr(exc)})
            continue
        for typ in types:
            guid = None
            try:
                for attr in typ.GetCustomAttributes(False):
                    value = _get_member(attr, "Guid", "get_Guid")
                    if value is not None:
                        candidate = _text(value).strip("{} ").lower()
                        if candidate in wanted:
                            guid = candidate
                            break
            except Exception:
                continue
            if guid is None:
                continue
            entry = {"role": wanted[guid], "guid": guid,
                     "runtimeType": _text(typ.FullName),
                     "assembly": full_name, "abstract": bool(typ.IsAbstract),
                     "interface": bool(typ.IsInterface), "constructors": [],
                     "properties": [], "methods": []}
            try:
                entry["constructors"] = [_text(item.ToString())
                                          for item in typ.GetConstructors()]
                entry["properties"] = [_text(item.ToString())
                                        for item in typ.GetProperties()]
                entry["methods"] = [_text(item.ToString())
                                     for item in typ.GetMethods()
                                     if any(token in _text(item.Name).lower()
                                            for token in ("append", "set", "add", "insert",
                                                          "remove", "create", "param", "input",
                                                          "output", "tree", "network"))]
            except Exception as exc:
                entry["reflectionError"] = repr(exc)
            result["types"].append(entry)
    result["types"].sort(key=lambda item: (item["role"], item["runtimeType"]))
    result["status"] = "found" if result["types"] else "not_found"
    return result


def lad_nwl_assembly_survey(req=None):
    """Read-only scan of loaded vendor assemblies for LAD topology families.

    The known-GUID inventory only resolves the five types the native writer
    already uses.  This survey scans every loaded NWL/InoPro assembly for
    types whose names or interfaces suggest contacts, coils, power rails,
    branches, wires, connectors, rungs, or jumps, so the contact/wire writer
    can bind the vendor's own topology primitives instead of guessing.
    """
    import System
    tokens = ("contact", "coil", "rail", "branch", "wire", "connector",
              "rung", "jump", "power", "label")
    wanted_asms = ("nwl", "implementation", "lad", "nwlobject")
    result = {"readOnly": True, "mutatedProject": False, "matches": [],
              "scannedAssemblies": [], "tokenCounts": {}}
    seen_types = set()
    for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
        full_name = _text(assembly.FullName)
        lower = full_name.lower()
        if not any(token in lower for token in wanted_asms):
            continue
        result["scannedAssemblies"].append(full_name)
        try:
            types = assembly.GetTypes()
        except Exception as exc:
            result["matches"].append({"assembly": full_name,
                                      "error": repr(exc)})
            continue
        for typ in types:
            key = _text(typ.AssemblyQualifiedName)
            if key in seen_types:
                continue
            try:
                iface_names = [_text(item.Name)
                               for item in typ.GetInterfaces()]
                probe = _text(typ.Name).lower() + " " + \
                    " ".join(name.lower() for name in iface_names)
                hit_tokens = [token for token in tokens
                              if token in probe]
                if not hit_tokens:
                    continue
                seen_types.add(key)
                type_guid = None
                try:
                    for attr in typ.GetCustomAttributes(False):
                        value = _get_member(attr, "Guid", "get_Guid")
                        if value is not None:
                            type_guid = _text(value).strip("{} ")
                            break
                except Exception:
                    pass
                for token in hit_tokens:
                    result["tokenCounts"][token] = (
                        result["tokenCounts"].get(token, 0) + 1)
                entry = {
                    "assembly": full_name.split(",")[0],
                    "fullName": _text(typ.FullName),
                    "abstract": bool(typ.IsAbstract),
                    "interface": bool(typ.IsInterface),
                    "typeGuid": type_guid,
                    "hitTokens": hit_tokens,
                    "interfaces": iface_names[:8],
                    "properties": [_text(item.Name)
                                   for item in typ.GetProperties()][:24],
                    "constructors": [_text(item)
                                     for item in typ.GetConstructors()][:4],
                }
                result["matches"].append(entry)
            except Exception:
                continue
            if len(result["matches"]) >= 250:
                result["truncated"] = True
                break
        if len(result["matches"]) >= 250:
            break
    result["status"] = ("found" if result["matches"] else "not_found")
    # Focused probe: dissect every unknown item-family type (full property and
    # method surface) to identify the branch/reference/terminator primitives.
    if req.get("dissectGuids"):
        wanted_guids = set(_text(item).strip().lower()
                           for item in req["dissectGuids"])
        result["dissected"] = []
        try:
            for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
                if "nwlobject.plugin" not in _text(
                        assembly.FullName).lower():
                    continue
                for typ in assembly.GetTypes():
                    type_guid = None
                    try:
                        for attr in typ.GetCustomAttributes(False):
                            value = _get_member(attr, "Guid", "get_Guid")
                            if value is not None:
                                type_guid = _text(value).strip("{} ").lower()
                                break
                    except Exception:
                        continue
                    if type_guid not in wanted_guids:
                        continue
                    entry = {
                        "fullName": _text(typ.FullName),
                        "typeGuid": type_guid,
                        "interfaces": [_text(item.Name)
                                       for item in typ.GetInterfaces()],
                        "properties": [_text(item.PropertyType) + " "
                                       + _text(item.Name)
                                       for item in typ.GetProperties()],
                        "methods": [_text(item)
                                    for item in typ.GetMethods()
                                    if not _text(item.Name).startswith("get_")
                                    and not _text(item.Name).startswith("set_")
                                    and not _text(item.Name).startswith("add_")
                                    and not _text(item.Name).startswith(
                                        "remove_")][:40],
                        "constructors": [_text(item)
                                         for item in typ.GetConstructors()],
                    }
                    result["dissected"].append(entry)
        except Exception as exc:
            result["dissectError"] = repr(exc)
    # Focused probes for the contact/wire writer: the LD operator enum and
    # every concrete item/tree type in the object plugin.
    result["operatorEnum"] = None
    result["itemFamily"] = []
    try:
        for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
            if "core" not in _text(assembly.FullName).lower():
                continue
            for typ in assembly.GetTypes():
                if _text(typ.Name) != "Operator" or not typ.IsEnum:
                    continue
                result["operatorEnum"] = {
                    "assembly": _text(assembly.FullName.split(",")[0]),
                    "values": [_text(name) for name in typ.GetEnumNames()],
                }
                break
            if result["operatorEnum"]:
                break
    except Exception as exc:
        result["operatorEnum"] = {"error": repr(exc)}
    try:
        item_family = {}
        for assembly in System.AppDomain.CurrentDomain.GetAssemblies():
            lower = _text(assembly.FullName).lower()
            if "nwlobject" not in lower and "implementationobject" not in lower \
                    and "nwlobject, " not in lower.replace("nwl", "nwl"):
                if not ("nwlobject" in lower or "implementation" in lower):
                    continue
            try:
                types = assembly.GetTypes()
            except Exception:
                continue
            for typ in types:
                try:
                    if typ.IsInterface:
                        continue
                    ifaces = [_text(item.Name)
                              for item in typ.GetInterfaces()]
                    if not any(name in ("INWLItem", "IBoxTree",
                                        "IBoxTreeOperand",
                                        "INWLImplementationObject")
                               for name in ifaces):
                        continue
                    type_guid = None
                    try:
                        for attr in typ.GetCustomAttributes(False):
                            value = _get_member(attr, "Guid", "get_Guid")
                            if value is not None:
                                type_guid = _text(value).strip("{} ")
                                break
                    except Exception:
                        pass
                    key = _text(typ.FullName) + "|" + _text(type_guid)
                    if key in item_family:
                        continue
                    item_family[key] = {
                        "fullName": _text(typ.FullName),
                        "assembly": _text(assembly.FullName.split(",")[0]),
                        "typeGuid": type_guid,
                        "interfaces": ifaces[:6],
                    }
                except Exception:
                    continue
        result["itemFamily"] = sorted(
            item_family.values(),
            key=lambda item: _text(item.get("fullName")))
    except Exception as exc:
        result["itemFamilyError"] = repr(exc)
    return result


def ui_screenshot(req):
    """Capture the InoProShop main window (or full primary screen) to a PNG."""
    import System
    path = _text(req.get("path")) or r"work\bridge\res\ui_screenshot.png"
    path = os.path.abspath(path)
    parent = os.path.dirname(path)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent)
    try:
        import clr
        clr.AddReference("System.Drawing")
        from System.Drawing import Bitmap, Graphics, Imaging
    except Exception as exc:
        raise OperationError("screenshot needs System.Drawing",
                             "screenshot_unavailable", {"cause": repr(exc)})
    import ctypes
    user32 = ctypes.windll.user32
    hwnd = 0
    try:
        for proc in System.Diagnostics.Process.GetProcessesByName("InoProShop"):
            handle = _get_member(proc, "MainWindowHandle",
                                 "get_MainWindowHandle")
            if handle is not None and int(handle) != 0:
                hwnd = int(handle)
                break
    except Exception:
        hwnd = 0
    class RECT(ctypes.Structure):
        _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                    ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
    left = top = 0
    width = height = 0
    used = "primary_screen"
    if hwnd:
        rect = RECT()
        if user32.GetWindowRect(hwnd, ctypes.byref(rect)):
            left, top = int(rect.left), int(rect.top)
            width = int(rect.right) - left
            height = int(rect.bottom) - top
            used = "ide_window"
    if width <= 0 or height <= 0:
        try:
            import clr as _clr
            _clr.AddReference("System.Windows.Forms")
            from System.Windows.Forms import Screen
            bounds = Screen.PrimaryScreen.Bounds
            left, top = int(bounds.Left), int(bounds.Top)
            width, height = int(bounds.Width), int(bounds.Height)
            used = "primary_screen"
        except Exception as exc:
            raise OperationError("cannot resolve capture bounds",
                                 "screenshot_bounds_unavailable",
                                 {"cause": repr(exc)})
    bitmap = Bitmap(width, height)
    graphics = Graphics.FromImage(bitmap)
    try:
        graphics.CopyFromScreen(left, top, 0, 0,
                                System.Drawing.Size(width, height))
    finally:
        graphics.Dispose()
    bitmap.Save(path, Imaging.ImageFormat.Png)
    bitmap.Dispose()
    return {"saved": path, "bounds": {"left": left, "top": top,
                                      "width": width, "height": height},
            "source": used, "readOnly": True, "mutatedProject": False}


def pou_open_editor(req):
    """Open one project object's editor and report which binding worked."""
    _require_project()
    target = _text(req.get("target"))
    if not target:
        raise OperationError("pou.open_editor requires target",
                             "invalid_argument")
    obj, path = find_project_object(target)
    if obj is None:
        raise OperationError("object not found: " + target,
                             "object_not_found", {"target": target})
    attempts = []
    editor = None
    binding = None
    for label, call in (
        ("open_editor_body", lambda: obj.open_editor("body")),
        ("open_editor_none", lambda: obj.open_editor()),
        ("open_editor_zero", lambda: obj.open_editor(0)),
    ):
        try:
            editor = call()
            binding = label
            break
        except Exception as exc:
            attempts.append({"binding": label, "error": repr(exc)})
    return {"target": target, "path": path, "binding": binding,
            "editorOpen": editor is not None, "failedBindings": attempts,
            "mutatedProject": False, "readOnly": True}


