            path = _require_disposable_destination_path(path, operation)
            if project is not None:
                return fail(rid, operation, "a project is already open; close it first", error_code="project_already_open")
            template = (normalized.get("template") or "CodeSysProject").strip()
            if not template.endswith(".project"):
                template += ".project"
            if (template.lower() == "standard.project" and
                    _text(PROFILE).lower().startswith("inoproshop")):
                return fail(
                    rid, operation,
                    "Standard.project is incompatible with the InoProShop vendor profile; "
                    "use project.prepare_vendor_project",
                    error_code="incompatible_template",
                    data={
                        "template": template,
                        "profile": PROFILE,
                        "suggestedOperation": "project.prepare_vendor_project",
                    },
                )
            source = os.path.join(normalized.get("templates_dir") or TEMPLATES_DIR, template)
            if not os.path.isfile(source):
                return fail(rid, operation, "template not found: " + source, error_code="template_not_found")
            parent = os.path.dirname(path)
            if parent and not os.path.isdir(parent):
                os.makedirs(parent)
            if os.path.exists(path):
                # 2026-09-07 review H2: the old code silently removed an
                # existing same-path project before copying the template — an
                # accidental re-run of the same task wiped the previous
                # project with no acknowledgement. Fail closed instead; the
                # caller picks a fresh path or deletes explicitly.
                return fail(
                    rid, operation,
                    "project already exists at " + path,
                    error_code="destination_exists",
                    data={
                        "path": path,
                        "disposableRoot": DISPOSABLE_ROOT,
                        "remediation": ("pick a fresh path under the disposable root, "
                                        "or delete the existing project explicitly first"),
                    },
                )
            shutil.copyfile(source, path)
            project, open_info = open_project_silent(path, "")
            native_core_project = _native_primary_project_for_current_path()
            pou_cache.clear()
            ok(rid, operation, {
                "path": path,
                "template": template,
                "source": source,
                "open": open_info,
                "nativeCoreProjectBound": native_core_project is not None,
            })
