def _request_operation(req):
    try:
        operation, _normalized = _normalize_request(req)
    except BaseException:
        return None
    return operation


def _bounded_project_identity():
    """Read the actual primary project, not a potentially stale bridge wrapper."""
    se = _sim_scriptengine()
    primary = _get_member(se.projects, "primary", "get_primary")
    if primary is None:
        return None
    path = _text(_get_member(primary, "path", "get_path", ""))
    handle_value = _get_member(primary, "handle", "get_handle", None)
    return {
        "path": os.path.normcase(os.path.abspath(path)) if path else None,
        "handle": _text(handle_value) if handle_value is not None else None,
    }


def _bounded_drop_session_identity():
    # A different/reopened project must never inherit the previous PLC wrapper.
    # Dropping an invalid binding does not stop or log out either application.
    _SIM_SESSION.update({"online": None, "appGuid": None,
                         "appPath": None, "key": None})
    globals()["_BOUNDED_SESSION_IDENTITY"] = None


def _bounded_bind_session():
    """Rebind a known native session for this Execute, without login/save/start."""
    identity = globals().get("_BOUNDED_SESSION_IDENTITY")
    if not identity or not _SIM_SESSION.get("appGuid"):
        return
    current_project = _bounded_project_identity()
    if current_project is None or current_project != identity.get("project"):
        _bounded_drop_session_identity()
        return
    app_obj, app_path = _sim_application_object()
    app_guid = _text(getattr(app_obj, "guid", ""))
    if app_guid != identity.get("appGuid"):
        _bounded_drop_session_identity()
        return
    se = _sim_scriptengine()
    session = se.online.create_online_application(app_obj)
    _SIM_SESSION["online"] = session
    _SIM_SESSION["appPath"] = app_path
    globals().setdefault("_BOUNDED_FRAME_WRAPPERS", []).append(session)
    # Keep the original code key. _sim_ensure_online must still invalidate a
    # session after a program mutation, even though its wrapper is now fresh.


def _bounded_release_session():
    session = _SIM_SESSION.get("online")
    wrappers = globals().get("_BOUNDED_FRAME_WRAPPERS", [])
    if session is not None and not any(item is session for item in wrappers):
        wrappers.append(session)
    errors = []
    try:
        try:
            if session is not None:
                project_identity = _bounded_project_identity()
                if project_identity is None:
                    _bounded_drop_session_identity()
                else:
                    globals()["_BOUNDED_SESSION_IDENTITY"] = {
                        "project": project_identity,
                        "appGuid": _SIM_SESSION.get("appGuid"),
                    } if _SIM_SESSION.get("appGuid") else None
            elif not _SIM_SESSION.get("appGuid"):
                globals()["_BOUNDED_SESSION_IDENTITY"] = None
        except BaseException as exc:
            errors.append(_text(exc))
        for wrapper in wrappers:
            try:
                wrapper.Dispose()
            except BaseException as exc:
                errors.append(_text(exc))
        if errors:
            raise RuntimeError("; ".join(errors))
    finally:
        # OnlineApplication stores its execution event; it cannot be reused in
        # another frame. Dispose releases refs, not the native login/run state.
        _SIM_SESSION["online"] = None
        globals()["_BOUNDED_FRAME_WRAPPERS"] = []


def _bounded_failure(req, exc, stage):
    prior = None
    raw = globals().get("_BOUNDED_RESULT_JSON")
    if raw:
        try:
            prior = json.loads(_text(raw))
        except Exception:
            prior = {"unparsedResult": _text(raw)}
    rid = _text(req.get("id", "unknown")) if isinstance(req, dict) else "unknown"
    operation = _request_operation(req) if isinstance(req, dict) else "?"
    data = {"executionVerified": False, "failureStage": stage}
    if prior is not None:
        data["priorResult"] = prior
    # A handler may already have committed changes. Do not claim rollback or
    # mutatedProject=false merely because frame cleanup subsequently failed.
    fail(rid, operation, _text(exc), stage=stage, data=data,
         error_code="bounded_frame_" + stage + "_failed")


def _bounded_dispatch_request():
    """One request in the executor's own scope; the host publishes on return."""
    global _BOUNDED_RESULT_JSON, _BOUNDED_RESULT_ACTION
    global _BOUNDED_HEARTBEAT_JSON, _BOUNDED_REQUEST_ACTIVE
    if not globals().get("_BOUNDED_EXECUTOR_SCOPE", False):
        raise RuntimeError("bounded dispatch requires an owned executor scope")
    if globals().get("_BOUNDED_REQUEST_ACTIVE", False):
        raise RuntimeError("bounded executor request re-entry is not allowed")
    _BOUNDED_REQUEST_ACTIVE = True
    _BOUNDED_RESULT_JSON = ""
    _BOUNDED_RESULT_ACTION = ""
    _BOUNDED_HEARTBEAT_JSON = ""
    globals()["_BOUNDED_FRAME_WRAPPERS"] = []
    req = None
    stage = "request"
    try:
        req = json.loads(_text(globals().get("_BOUNDED_REQUEST_JSON", "")))
        if not isinstance(req, dict) or not _safe_request_id(req.get("id")):
            raise ValueError("bounded request must be an object with a safe id")
        configure_abort_handling()
        stage = "binding"
        _bounded_bind_session()
        stage = "handler"
        action = handle(req)
        if action == "EXIT":
            _BOUNDED_RESULT_ACTION = "EXIT"
        if not _BOUNDED_RESULT_JSON:
            raise RuntimeError("handler returned without a response")
    except BaseException as exc:
        _bounded_failure(req, exc, stage)
    finally:
        try:
            _bounded_release_session()
        except BaseException as exc:
            _bounded_failure(req, exc, "cleanup")
        _BOUNDED_REQUEST_ACTIVE = False
        _write_heartbeat("paused" if bridge_paused else "idle", force=True)


def _bounded_initialize_scope():
    # LoadDrivers belongs to the host and runs once per owned executor.
    # Only this inner scope owns project/online state; no worker or frame loop.
    configure_prompt_handling()
    configure_abort_handling()
    _discover_primary_project()
    _write_thread_info()
    _write_heartbeat("idle", force=True)


_INFRAME_LOOP_ACTIVE = False
_INFRAME_LOOP_THREAD_ID = None
_INFRAME_OPERATIONS = (
    "sim.status", "sim.set", "sim.online", "sim.read", "sim.write",
    "sim.force_clear", "sim.assert", "sim.native_probe",
)


def _sim_frame_loop():
    """Serve the sim.* queue without ever leaving the --runscript frame."""
    global _INFRAME_LOOP_ACTIVE, _INFRAME_LOOP_THREAD_ID
    _INFRAME_LOOP_ACTIVE = True
    _INFRAME_LOOP_THREAD_ID = _sim_thread_id()
    try:
        with open(os.path.join(os.path.dirname(HEARTBEAT_FILE),
                               "bridge-frameloop.json"), "wb") as frame_handle:
            frame_handle.write(json.dumps({
                "inFrameLoop": True,
                "threadId": _INFRAME_LOOP_THREAD_ID,
                "scriptThreadId": _SCRIPT_THREAD_ID,
                "operations": list(_INFRAME_OPERATIONS),
                "startedAt": time.time(),
            }).encode("utf-8"))
    except BaseException:
        pass
    while True:
        try:
            names = [name for name in os.listdir(REQ_DIR)
                     if name.endswith(".json")]
            names.sort()
            for filename in names:
                path = os.path.join(REQ_DIR, filename)
                try:
                    with open(path, "rb") as request_file:
                        req = json.loads(request_file.read().decode("utf-8-sig"))
                except Exception:
                    continue
                if _request_operation(req) not in _INFRAME_OPERATIONS:
                    continue
                request_id = _safe_request_id(req.get("id"))
                if request_id is None or request_id != filename[:-5]:
                    continue
                try:
                    os.remove(path)
                except Exception:
                    continue
                try:
                    handle(req)
                except BaseException:
                    pass
            if _PRIMARY_THREAD_HOP:
                # InoProShop: this thread is not the UI thread, so the IDE keeps
                # running its own loop while we wait.
                try:
                    system.delay(POLL_DELAY_MS)
                except BaseException:
                    time.sleep(POLL_DELAY_MS / 1000.0)
            else:
                # SP22: yield exactly the way the inline poll loop always did.
                # NEVER probe the UI thread from here per iteration (R052 crash:
                # repeated ctypes window enumeration from this thread killed the
                # IDE with an AccessViolationException).
                _vanilla_ui_yield(POLL_DELAY_MS)
        except BaseException:
            try:
                time.sleep(0.2)
            except BaseException:
                pass


def _worker_loop():
    global bridge_paused
    _write_thread_info()
    _write_heartbeat("idle", force=True)
    with open(READY_FILE, "wb") as ready:
        ready.write((PROTOCOL_VERSION + "\n").encode("ascii"))

    # One-time insurance: if the IDE came up with its window parked
    # off-screen, restore it.  Deliberately NOT periodic — a periodic check
    # would fight the user's own minimize (a minimized window reports the
    # same parked coordinates), the exact regression that broke minimizing.
    if not _PRIMARY_THREAD_HOP:
        _ensure_ide_window_visible()
    while True:
        try:
            names = [name for name in os.listdir(REQ_DIR)
                     if name.endswith(".json")]
            names.sort()
            for filename in names:
                path = os.path.join(REQ_DIR, filename)
                try:
                    with open(path, "rb") as request_file:
                        req = json.loads(request_file.read().decode("utf-8-sig"))
                except Exception as exc:
                    fallback_id = _safe_request_id(filename[:-5])
                    if fallback_id:
                        fail(fallback_id, "?", repr(exc), stage="parse")
                    try:
                        os.remove(path)
                    except Exception:
                        pass
                    continue

                request_id = _safe_request_id(req.get("id"))
                if request_id is None or request_id != filename[:-5]:
                    safe_filename_id = _safe_request_id(filename[:-5])
                    if safe_filename_id:
                        fail(safe_filename_id, req.get("cmd"),
                             "unsafe or mismatched request id")
                    try:
                        os.remove(path)
                    except Exception:
                        pass
                    continue

                if (_INFRAME_LOOP_ACTIVE
                        and _request_operation(req) in _INFRAME_OPERATIONS):
                    # E2E V2 R052: the script-frame loop owns sim.* - leave the
                    # request file in place for it instead of racing it here.
                    continue

                try:
                    os.remove(path)
                except Exception:
                    continue
                if _run_on_primary(req) == "EXIT":
                    _write_heartbeat("stopped", force=True)
                    _remove_ready_file()
                    return
            _write_heartbeat("paused" if bridge_paused else "idle")
            if _PRIMARY_THREAD_HOP or _UI_SYNC_CONTEXT is not None:
                # Loop on a BACKGROUND thread (InoProShop model): plain
                # sleep — the UI thread is never held.
                time.sleep(POLL_DELAY_MS / 1000.0)
            else:
                # Only reachable when the loop runs inline on the UI thread
                # with no marshal available: pump messages to stay usable.
                _vanilla_ui_yield(POLL_DELAY_MS)
        except BaseException:
            _write_heartbeat("failed", force=True)
            _remove_ready_file()
            # Diagnosability: the worker dies silently otherwise (2026-09-08
            # CODESYS probe: state=failed with no traceback anywhere). Persist
            # the traceback next to the heartbeat so a host-side failure is
            # inspectable without an IDE console. IronPython 2.7's builtin
            # open() has no encoding kwarg — write bytes.
            try:
                failure_log = os.path.join(
                    os.path.dirname(HEARTBEAT_FILE), "bridge-failure.log"
                )
                payload = "[%s]\n%s\n" % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    traceback.format_exc(),
                )
                if isinstance(payload, unicode):
                    payload = payload.encode("utf-8")
                else:
                    try:
                        payload = payload.decode("utf-8").encode("utf-8")
                    except Exception:
                        payload = payload.decode("latin-1").encode("utf-8")
                with open(failure_log, "ab") as failure_handle:
                    failure_handle.write(payload)
            except Exception:
                pass
            return


def main():
    lifecycle = (os.environ.get("CODESYS_BRIDGE_SCRIPT_LIFECYCLE") or "command").strip().lower()
    if lifecycle == "command":
        import command_bridge_host
        command_bridge_host.start(__file__, system, _PRIMARY_THREAD_HOP,
                                  _UI_SYNC_CONTEXT, globals())
        return
    # Diagnostic-only alternatives. Never silently fall back to the permanent
    # frame: it locks native controls even while our heartbeat reports idle.
    # Direct ScriptEngine imports are blocked on InoProShop; the default uses
    # the available script/execute command instead and rebinds its drivers.
    if lifecycle == "bounded":
        import bounded_bridge_host
        context = _UI_SYNC_CONTEXT
        if not _PRIMARY_THREAD_HOP:
            ui_thread = _sim_ui_thread_id()
            if (_SCRIPT_THREAD_ID is None or ui_thread is None
                    or _SCRIPT_THREAD_ID != ui_thread):
                context = None
        bounded_bridge_host.start(
            __file__, system, _PRIMARY_THREAD_HOP, context)


        return
    if lifecycle != "legacy-frame":
        raise ValueError("unknown CODESYS_BRIDGE_SCRIPT_LIFECYCLE: " + lifecycle)
    global worker_thread
    for directory in (REQ_DIR, RES_DIR):
        if not os.path.isdir(directory):
            os.makedirs(directory)
    configure_prompt_handling()
    configure_abort_handling()
    _discover_primary_project()
    if _PRIMARY_THREAD_HOP or _UI_SYNC_CONTEXT is not None:
        # Legacy diagnostic path: a background queue is NOT evidence that the
        # vendor has released its script-level lock on the workspace.
        worker_thread = threading.Thread(
            target=_worker_loop,
            name="CodesysRouteBridge",
        )
        worker_thread.daemon = True
        worker_thread.start()
        # E2E V2 R052 (A/B measured on the vanilla line): returning from the
        # script destroys the --runscript frame and the online API then fails
        # with the R048 root cause verbatim —
        #   sim.online -> sim_online_unavailable
        #   "could not create an online application for the open project:
        #    堆栈为空。" (applicationPath PLCWinNT/Plc Logic/Application)
        # and every later sim.read/write/assert fails the same way. With this
        # loop the SAME scenario scores 8/8 pass on BOTH lines. The frame loop
        # therefore IS the mechanism that replaced the sidecar process; the env
        # switch exists only to reproduce the failing side of that A/B.
        if os.environ.get("CODESYS_BRIDGE_SIM_FRAME_LOOP", "1") != "0":
            _sim_frame_loop()
    else:
        # No hop and no sync context: the poll loop must run inline on the
        # script thread (last-resort fallback; pumps messages at idle).
        _worker_loop()


if not globals().get("_BRIDGE_SOURCE_RELOAD_ACTIVE", False):
    if globals().get("_BOUNDED_EXECUTOR_SCOPE", False):
        _bounded_initialize_scope()
    else:
        main()
